function out($data)
{
    echo json_encode($data, JSON_UNESCAPED_UNICODE);
    exit;
}
function fail($msg, $code = 400, array $extra = [])
{
    /* Το $extra ταξιδεύει μαζί με το μήνυμα: η οθόνη χρειάζεται δομή για να
       αντιδράσει (π.χ. «σε ποια άλλη καρτέλα ανήκει αυτό το τηλέφωνο»), όχι
       μόνο κείμενο να δείξει. */
    http_response_code($code);
    out(['error' => $msg] + $extra);
}

$action = $_GET['a'] ?? '';
$adminId = pm_admin_id();
$MEET_ROOM = null;   // guests του CloudOn Meet: έγκυρο room token αντί για login
$CRON_OK = false;    // presence_sweep από το pulse cron: HMAC της ώρας με το pm_secret, χωρίς login
if ($adminId <= 0) {
    if (strpos($action, 'rtc_') === 0 && ($MEET_ROOM = pm_verify_meet($_REQUEST['mt'] ?? ''))) {
        // ok — signaling ως guest, περιορισμένος στο δωμάτιο του token
    } elseif ($action === 'event_rsvp_public') {
        // ok — δημόσιο RSVP πελάτη με δικό του signed token
    } elseif (in_array($action, ['presence_sweep', 'cards_build'], true)
        && (hash_equals(hash_hmac('sha256', 'sweep.' . date('YmdHi'), pm_secret()), (string) ($_GET['k'] ?? ''))
        || hash_equals(hash_hmac('sha256', 'sweep.' . date('YmdHi', time() - 60), pm_secret()), (string) ($_GET['k'] ?? '')))) {
        $CRON_OK = true;
    } else {
        fail('auth', 401);
    }
}
$FULL = $adminId > 0 ? Db::isFullAccess($adminId) : false;
$in = [];
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $testIn = getenv("CNP_TEST_INPUT");
    $in = json_decode($testIn && PHP_SAPI === "cli" ? file_get_contents($testIn) : file_get_contents("php://input"), true) ?: [];
}

/* ---------- helpers ---------- */
function initials($name)
{
    $p = preg_split('/\s+/', trim((string) $name));
    return mb_strtoupper(mb_substr($p[0] ?? '', 0, 1) . mb_substr($p[1] ?? '', 0, 1));
}
/** Κανονικοποίηση ελληνικού κειμένου για ταίριασμα: πεζά, χωρίς τόνους, λέξεις ≥3. */
/**
 * Χονδρική ανίχνευση γλώσσας κειμένου, ως βοήθημα προς το AI.
 *
 * Δεν είναι αυθεντία: τα greeklish («kalimera, thelo voithia») μετρώνται ως
 * λατινικά ενώ είναι ελληνικά. Γι' αυτό το αποτέλεσμα δίνεται στο μοντέλο ως
 * ΥΠΟΔΕΙΞΗ με ρητή άδεια να την αγνοήσει — εκείνο κρίνει καλύτερα από κανόνα.
 *
 * @return string|null 'ελληνικά', 'αγγλικά' ή null όταν δεν υπάρχει επαρκές δείγμα
 */
/**
 * Αλυσίδα πιστώσεων ενός πελάτη: πού κατέληξε κάθε υπερπληρωμή.
 *
 * ΓΙΑΤΙ ΧΡΕΙΑΖΕΤΑΙ: όταν ο πελάτης πληρώσει παραπάνω, το WHMCS κρατά το
 * πλεόνασμα ως πίστωση και το εφαρμόζει σε ΕΠΟΜΕΝΑ παραστατικά. Έτσι μια
 * είσπραξη μπορεί τελικά να εξοφλεί άλλο τιμολόγιο από εκείνο στο οποίο
 * είναι καταχωρημένη — και χωρίς αυτή την αντιστοίχιση το λογιστήριο δεν
 * μπορεί να κάνει ματς.
 *
 * Η κατανάλωση θεωρείται FIFO: η παλαιότερη πίστωση ξοδεύεται πρώτη.
 *
 * @return array [invoiceId πηγής => [['invoice'=>id, 'num'=>'2026…', 'amount'=>float], …]]
 */
/**
 * Ζόμπι συνδρομές: ακυρωμένες υπηρεσίες που κρατούν αναγνωριστικό συνδρομής.
 * Χρησιμοποιείται και από την οθόνη και από το CSV — μία πηγή αλήθειας, αλλιώς
 * το λογιστήριο βλέπει άλλα νούμερα από την οθόνη.
 */
/**
 * Πού «σπάνε» τα βιβλία: ποια παραστατικά δείχνουν άλλα χρήματα από όσα
 * καταχωρήθηκαν. Χωρίς αυτή την ανάλυση η «ασυμφωνία» είναι ένας αριθμός χωρίς
 * αποδεικτικά — και μοιάζει με οφειλή, ενώ συνήθως είναι παλιό παραστατικό
 * σημασμένο «Paid» χωρίς καταχωρημένη συναλλαγή.
 * Κοινό για οθόνη και CSV, με συγκεντρωτικά ερωτήματα (όχι βρόχος ανά πελάτη).
 */
/**
 * Παραστατικά σημασμένα «Paid» με λιγότερες (ή καθόλου) καταχωρημένες
 * εισπράξεις. Επί χρόνια η πλατφόρμα δουλευόταν χειροκίνητα, οπότε η σήμανση
 * «Paid» είναι η αλήθεια — η γραμμή πληρωμής απλώς δεν καταχωρήθηκε. Τα ποσά
 * αυτά θεωρούνται εισπραγμένα, αλλιώς φουσκώνουν ψεύτικες οφειλές.
 * Επιστρέφει ['byClient' => [uid => ποσό], 'rows' => [αναλυτικά]].
 */
/**
 * Πραγματικά ανοιχτά υπόλοιπα, υπολογισμένα ΑΝΑ ΠΑΡΑΣΤΑΤΙΚΟ.
 *
 * Τα συγκεντρωτικά ανά πελάτη («τιμολογημένα μείον εισπράξεις») βγάζουν λάθος
 * όταν μια υπερπληρωμή γίνεται πίστωση και εξοφλεί άλλο παραστατικό: το ποσό
 * μετριέται δύο φορές, μία ως πλεόνασμα κι άλλη μία ως ανεξόφλητο. Ανά
 * παραστατικό το πλεόνασμα δεν διαρρέει (κόβεται στο μηδέν) και η πίστωση
 * μετράει εκεί όπου εφαρμόστηκε.
 *
 * Ένα παραστατικό θεωρείται εξοφλημένο όταν: πληρωμές + εφαρμοσμένη πίστωση
 * καλύπτουν την αξία, Ή όταν είναι σημασμένο «Paid» (η πλατφόρμα δουλευόταν
 * χειροκίνητα επί χρόνια — η σήμανση είναι η αλήθεια).
 */
/**
 * Ημερομηνία για ανθρώπους: πάντα ηη/μμ/εεεε. Το ISO μένει μόνο στη βάση και
 * στα ερωτήματα — ποτέ σε οθόνη ή σε CSV που ανοίγει το λογιστήριο.
 */
function cnp_d($v)
{
    $v = trim((string) $v);
    if ($v === '' || strpos($v, '0000') === 0) { return ''; }
    $ts = strtotime($v);
    return $ts ? date('d/m/Y', $ts) : $v;
}

function cnp_receivables()
{
    static $cache = null;
    if ($cache !== null) { return $cache; }

    /* Μόνο οι πραγματικές επιστροφές (refundid > 0) μειώνουν τα εισπραγμένα.
       Το tblaccounts κρατά και εγγραφές εξόδου που δεν είναι χρήματα πίσω
       («Applied Debit Note for Late Fees»)· αν αφαιρεθούν, το παραστατικό
       φαίνεται πιο ανοιχτό απ' όσο είναι. */
    $alloc = [];
    foreach (Capsule::table('tblaccounts')->where('invoiceid', '>', 0)
                 ->selectRaw('invoiceid, SUM(amountin) - SUM(CASE WHEN refundid > 0 THEN amountout ELSE 0 END) p')
                 ->groupBy('invoiceid')->get() as $r) {
        $alloc[(int) $r->invoiceid] = (float) $r->p;
    }
    $open = [];
    foreach (Capsule::table('tblinvoices')->whereNotIn('status', ['Cancelled', 'Draft'])
                 ->get(['id', 'userid', 'status', 'subtotal', 'tax', 'tax2', 'credit']) as $i) {
        if ($i->status === 'Paid' || $i->status === 'Refunded') { continue; }
        $gross = (float) $i->subtotal + (float) $i->tax + (float) $i->tax2;
        $rest = round($gross - ($alloc[(int) $i->id] ?? 0) - (float) $i->credit, 2);
        if ($rest <= 0.005) { continue; }   // πλεόνασμα δεν διαρρέει σε άλλο παραστατικό
        $uid = (int) $i->userid;
        $open[$uid] = ($open[$uid] ?? 0) + $rest;
    }
    $cache = $open;
    return $cache;
}

function cnp_assumed_paid()
{
    static $cache = null;
    if ($cache !== null) { return $cache; }

    $alloc = [];
    foreach (Capsule::table('tblaccounts')->where('invoiceid', '>', 0)
                 ->selectRaw('invoiceid, SUM(amountin) - SUM(CASE WHEN refundid > 0 THEN amountout ELSE 0 END) p')
                 ->groupBy('invoiceid')->get() as $r) {
        $alloc[(int) $r->invoiceid] = (float) $r->p;
    }
    $by = []; $rows = [];
    foreach (Capsule::table('tblinvoices')->where('status', 'Paid')->orderBy('date', 'desc')
                 ->get(['id', 'userid', 'invoicenum', 'date', 'datepaid', 'paymentmethod', 'subtotal', 'tax', 'tax2', 'credit']) as $i) {
        $gross = (float) $i->subtotal + (float) $i->tax + (float) $i->tax2;
        /* Η πίστωση που εφαρμόστηκε πάνω στο παραστατικό (tblinvoices.credit)
           το εξοφλεί εξίσου με μια πληρωμή — απλώς δεν έχει δική της εγγραφή
           στο tblaccounts. Χωρίς αυτήν, παραστατικά πληρωμένα με υπόλοιπο
           πελάτη έμοιαζαν ασυμπλήρωτα. */
        $paid  = ($alloc[(int) $i->id] ?? 0.0) + (float) $i->credit;
        $gap = round($gross - $paid, 2);
        if ($gap <= 0.005) { continue; }
        $uid = (int) $i->userid;
        $by[$uid] = ($by[$uid] ?? 0) + $gap;
        $rows[] = ['invoice' => (int) $i->id, 'client' => $uid,
            'num' => (string) ($i->invoicenum ?: $i->id), 'date' => substr((string) $i->date, 0, 10),
            'datepaid' => substr((string) $i->datepaid, 0, 10), 'method' => (string) $i->paymentmethod,
            'gross' => round($gross, 2), 'paid' => round($paid, 2), 'credit' => round((float) $i->credit, 2),
            'gap' => $gap];
    }
    $cache = ['byClient' => $by, 'rows' => $rows];
    return $cache;
}

function cnp_book_gaps(array $ids)
{
    if (!$ids) { return ['inv' => [], 'unalloc' => [], 'cancelled' => []]; }

    $allocated = [];
    foreach (Capsule::table('tblaccounts')->whereIn('userid', $ids)->where('invoiceid', '>', 0)
                 ->selectRaw('invoiceid, SUM(amountin) - SUM(CASE WHEN refundid > 0 THEN amountout ELSE 0 END) p')
                 ->groupBy('invoiceid')->get() as $r) {
        $allocated[(int) $r->invoiceid] = (float) $r->p;
    }

    $byClient = [];
    foreach (Capsule::table('tblinvoices')->whereIn('userid', $ids)->whereNotIn('status', ['Cancelled', 'Draft'])
                 ->orderBy('date')->get(['id', 'userid', 'invoicenum', 'date', 'status', 'subtotal', 'tax', 'tax2', 'credit']) as $iv) {
        $gross = (float) $iv->subtotal + (float) $iv->tax + (float) $iv->tax2;
        // Η εφαρμοσμένη πίστωση εξοφλεί το παραστατικό, όπως και μια πληρωμή.
        $paid  = ($allocated[(int) $iv->id] ?? 0.0) + (float) $iv->credit;
        $d = round($gross - $paid, 2);
        if (abs($d) < 0.01) { continue; }
        /* Ανεξόφλητο παραστατικό χωρίς καμία πληρωμή ΔΕΝ είναι εύρημα — έτσι
           ακριβώς πρέπει να είναι, και μετριέται ήδη στα ανεξόφλητα του WHMCS.
           Κρατάμε μόνο όσα έχουν κάποια είσπραξη που δεν συμφωνεί. */
        $unpaidLike = in_array($iv->status, ['Unpaid', 'Overdue', 'Collections', 'Payment Pending'], true);
        if ($unpaidLike && $paid <= 0.005) { continue; }
        /* Σημασμένο «Paid» με λιγότερες εισπράξεις: θεωρείται εξοφλημένο (βλ.
           cnp_assumed_paid) — ήταν ο τρόπος δουλειάς επί χρόνια. Δεν είναι
           ασυμφωνία· φαίνεται χωριστά, ως πληροφορία. Υπερείσπραξη όμως ναι. */
        if ($iv->status === 'Paid' && $d > 0) { continue; }
        $byClient[(int) $iv->userid][] = ['invoice' => (int) $iv->id,
            'num' => (string) ($iv->invoicenum ?: $iv->id), 'date' => substr((string) $iv->date, 0, 10),
            'status' => (string) $iv->status, 'gross' => round($gross, 2), 'paid' => round($paid, 2), 'diff' => $d,
            'why' => $paid <= 0 ? 'χωρίς καμία εγγραφή πληρωμής'
                : ($unpaidLike ? 'πληρωμένο κατά ένα μέρος, μετράει ολόκληρο ως ανεξόφλητο'
                : ($d > 0 ? 'μερική πληρωμή' : 'εισπράχθηκαν περισσότερα'))];
    }
    foreach ($byClient as $cid => $rows) {
        usort($rows, function ($a, $b) { return abs($b['diff']) <=> abs($a['diff']); });
        $byClient[$cid] = $rows;
    }

    // Πληρωμές που δεν κούμπωσαν σε παραστατικό: μειώνουν τη διαφορά χωρίς να
    // φαίνονται σε καμία γραμμή παραστατικού, οπότε πρέπει να δηλωθούν.
    $unalloc = [];
    foreach (Capsule::table('tblaccounts')->whereIn('userid', $ids)->where('invoiceid', 0)
                 ->where('gateway', '!=', '')->whereNotNull('gateway')
                 ->selectRaw('userid, SUM(amountin) - SUM(amountout) p')->groupBy('userid')->get() as $r) {
        $unalloc[(int) $r->userid] = round((float) $r->p, 2);
    }

    /* Πληρωμές πάνω σε ΑΚΥΡΩΜΕΝΑ παραστατικά: το ακυρωμένο βγαίνει από τα
       τιμολογημένα, η πληρωμή του όμως μένει στις εισπράξεις — και η διαφορά
       εμφανίζεται χωρίς κανένα ένοχο παραστατικό να τη δικαιολογεί. */
    $cancelled = [];
    foreach (Capsule::table('tblaccounts')->whereIn('tblaccounts.userid', $ids)
                 ->join('tblinvoices', 'tblinvoices.id', '=', 'tblaccounts.invoiceid')
                 ->whereIn('tblinvoices.status', ['Cancelled', 'Draft'])
                 ->selectRaw('tblaccounts.userid uid, SUM(tblaccounts.amountin) - SUM(tblaccounts.amountout) p, COUNT(*) n')
                 ->groupBy('tblaccounts.userid')->get() as $r) {
        $cancelled[(int) $r->uid] = ['sum' => round((float) $r->p, 2), 'n' => (int) $r->n];
    }

    return ['inv' => $byClient, 'unalloc' => $unalloc, 'cancelled' => $cancelled];
}

function cnp_zombies(callable $nameOf)
{
    $out = [];
    foreach (Capsule::table('tblhosting')->whereNotNull('subscriptionid')->where('subscriptionid', '!=', '')
                 ->whereIn('domainstatus', ['Cancelled', 'Terminated', 'Fraud'])->get() as $h) {
        $sub = trim((string) $h->subscriptionid);

        /* Ημερομηνία ακύρωσης: termination_date, αλλιώς αίτημα πελάτη, αλλιώς
           τελευταία μεταβολή. Πολλές παλιές εγγραφές έχουν 0000-00-00 παντού,
           οπότε μένει άγνωστη — και τότε δεν ισχυριζόμαστε τίποτα γι\' αυτήν. */
        $term = (string) ($h->termination_date ?? '');
        if ($term === '' || strpos($term, '0000') === 0) { $term = ''; }
        $cr = Capsule::table('tblcancelrequests')->where('relid', $h->id)->orderBy('id', 'desc')->first();
        $cancel = $term ?: ($cr ? substr((string) $cr->date, 0, 10) : '');
        $src = $term ? 'τερματισμός' : ($cr ? 'αίτημα πελάτη' : '');
        if (!$cancel && $h->lastupdate && strpos((string) $h->lastupdate, '0000') !== 0) {
            $cancel = substr((string) $h->lastupdate, 0, 10);
            $src = 'τελευταία μεταβολή';
        }

        /* Έγκυρο αναγνωριστικό συνδρομής; Οι συνδρομές PayPal είναι της μορφής
           I-XXXXXXXXXXXX. Τετριμμένοι αριθμοί (π.χ. «108») είναι κατάλοιπα
           παλιών εγγραφών — με LIKE στα IPN πιάνουν οτιδήποτε περιέχει τα
           ψηφία και βγάζουν εντελώς πλασματικά ποσά. */
        $realSub = (strlen($sub) >= 8 && !ctype_digit($sub));

        $subTx = [];
        if ($realSub) {
            foreach (Capsule::table('tblgatewaylog')->where('data', 'like', '%' . $sub . '%')->get() as $g) {
                if (preg_match('/(?:^|\n)\s*txn_id\s*=>\s*(\S+)/', (string) $g->data, $m)) { $subTx[] = trim($m[1]); }
            }
            $subTx = array_values(array_unique($subTx));
        }

        // Οι πληρωμές ΤΗΣ ΣΥΓΚΕΚΡΙΜΕΝΗΣ συνδρομής — όχι η τελευταία πληρωμή του
        // πελάτη, που μπορεί να αφορά άλλη, ζωντανή υπηρεσία.
        $pays = [];
        if ($subTx) {
            foreach (Capsule::table('tblaccounts')->whereIn('transid', $subTx)
                         ->where('amountin', '>', 0)->orderBy('date')->get() as $pay) {
                $pays[] = [
                    'date'     => substr((string) $pay->date, 0, 10),
                    'amount'   => (float) $pay->amountin,
                    'transid'  => (string) $pay->transid,
                    'invoice'  => (int) $pay->invoiceid,
                    'refunded' => Capsule::table('tblaccounts')->where('refundid', $pay->id)->exists(),
                ];
            }
        }

        /* Το εύρημα δεν είναι «πλήρωσε κάποτε» — είναι «εισπράξαμε ΜΕΤΑ την
           ακύρωση και δεν το επιστρέψαμε». Όταν η ημερομηνία ακύρωσης είναι
           άγνωστη, κρατάμε ως ένδειξη τις ανεπίστρεπτες πληρωμές που δεν
           κούμπωσαν σε κανένα παραστατικό. */
        $openAmt = 0.0; $openN = 0; $orphan = 0.0;
        foreach ($pays as $pp) {
            if ($pp['refunded']) { continue; }
            if ($cancel && $pp['date'] > $cancel) { $openAmt += $pp['amount']; $openN++; }
            if (!$pp['invoice']) { $orphan += $pp['amount']; }
        }
        $last = $pays ? $pays[count($pays) - 1] : null;

        $out[] = ['service' => (int) $h->id, 'client' => (int) $h->userid, 'name' => $nameOf((int) $h->userid),
            'domain' => (string) $h->domain, 'status' => (string) $h->domainstatus,
            'amount' => (float) $h->amount, 'cycle' => (string) $h->billingcycle,
            'sub' => $sub, 'realSub' => $realSub,
            'cancel' => $cancel ?: null, 'cancelSrc' => $src,
            'lastPay' => $last ? $last['date'] : null,
            'lastAmt' => $last ? $last['amount'] : null,
            'refunded' => $last ? (bool) $last['refunded'] : false,
            'payN' => count($pays), 'openN' => $openN,
            'openAmt' => round($openAmt, 2),   // εισπράξεις μετά την ακύρωση, χωρίς επιστροφή
            'orphan' => round($orphan, 2),     // ανεπίστρεπτες πληρωμές χωρίς παραστατικό
            'pays' => array_slice(array_reverse($pays), 0, 6),
            'afterCancel' => ($openN > 0 || $orphan > 0)];
    }
    usort($out, function ($a, $b) {
        return ($b['openAmt'] + $b['orphan']) <=> ($a['openAmt'] + $a['orphan'])
            ?: strcmp((string) $b['lastPay'], (string) $a['lastPay']);
    });
    return $out;
}

function cnp_credit_chain($clientId)
{
    static $cache = [];
    if (isset($cache[$clientId])) {
        return $cache[$clientId];
    }

    $queue = [];      // [invoiceId πηγής, υπόλοιπο]
    $out   = [];

    foreach (Capsule::table('tblcredit')->where('clientid', (int) $clientId)->orderBy('id')->get() as $r) {
        $amt = (float) $r->amount;

        if ($amt > 0) {                       // υπερπληρωμή → μπαίνει στην ουρά
            $src = (int) $r->relid;
            if (!$src && preg_match('/Invoice #(\d+)/', (string) $r->description, $m)) { $src = (int) $m[1]; }
            $queue[] = [$src, $amt];
            continue;
        }

        // Αρνητικό: καταναλώνει πίστωση για κάποιο παραστατικό
        $dst = (int) $r->relid;
        if (!$dst && preg_match('/Invoice #(\d+)/', (string) $r->description, $m)) { $dst = (int) $m[1]; }
        $need = -$amt;

        while ($need > 0.001 && $queue) {
            [$src, $left] = $queue[0];
            $take = min($left, $need);
            $need -= $take;
            $queue[0][1] -= $take;
            if ($queue[0][1] <= 0.001) { array_shift($queue); }

            if ($src && $dst) {
                $out[$src][] = ['invoice' => $dst, 'amount' => round($take, 2)];
            }
        }
    }

    // Συμπλήρωσε τους αριθμούς παραστατικών
    foreach ($out as $src => $list) {
        foreach ($list as $i => $x) {
            $out[$src][$i]['num'] = (string) (Capsule::table('tblinvoices')->where('id', $x['invoice'])->value('invoicenum') ?: ('#' . $x['invoice']));
        }
    }

    return $cache[$clientId] = $out;
}

/**
 * Γλώσσα του πελάτη, από το κείμενό του.
 *
 * Πριν μετρήσουμε γράμματα, πετάμε ό,τι είναι γλωσσικά ουδέτερο: emails, URLs,
 * ετικέτες HTML, ονόματα αρχείων. Ένα ελληνικό μήνυμα γεμάτο συνδέσμους έβγαινε
 * «μεικτό» και έχανε την ανίχνευση.
 */
function cnp_lang_hint($text)
{
    $t = (string) $text;
    $t = preg_replace('/<[^>]{1,400}>/u', ' ', $t);                       // HTML
    $t = preg_replace('/\b[\w.+-]+@[\w.-]+\.[a-z]{2,}\b/ui', ' ', $t);  // emails
    $t = preg_replace('/\bhttps?:\/\/\S+/ui', ' ', $t);                 // σύνδεσμοι
    $t = preg_replace('/\b[\w-]+\.(gr|com|net|org|eu|io|co)\b/ui', ' ', $t); // domains
    $t = preg_replace('/\b[\w-]+\.(php|js|css|png|jpg|pdf|zip|log|conf)\b/ui', ' ', $t);

    $letters = preg_replace('/[^\p{L}]+/u', '', $t);
    if ($letters === '') {
        return null;
    }
    $greek = preg_match_all('/\p{Greek}/u', $letters);
    $latin = preg_match_all('/\p{Latin}/u', $letters);
    $total = $greek + $latin;
    if ($total < 12) {
        return null;   // πολύ μικρό δείγμα για ασφαλή κρίση
    }
    /* Αρκετά ελληνικά γράμματα = ελληνικά. Καμία λατινογενής γλώσσα δεν γράφει
       με ελληνικό αλφάβητο, οπότε η παρουσία τους είναι από μόνη της απόδειξη —
       δεν χρειάζεται να είναι και πλειοψηφία. */
    if ($greek >= 10 && $greek / $total > 0.15) {
        return 'ελληνικά';
    }
    if ($latin / $total > 0.85) {
        return 'αγγλικά (ή greeklish — κρίνε το από το νόημα)';
    }
    return null;
}

/**
 * Το κείμενο του πελάτη πάνω στο οποίο κρίνεται η γλώσσα. Το τελευταίο μήνυμα
 * μπορεί να είναι «ok, thanks» — πολύ μικρό για ασφαλή κρίση. Τότε μαζεύουμε
 * και προηγούμενα δικά του μηνύματα, από το πιο πρόσφατο προς τα πίσω.
 */
function cnp_lang_sample(array $customerMsgs, $minLetters = 40)
{
    $out = '';
    foreach (array_reverse($customerMsgs) as $m) {
        $out .= ' ' . $m;
        if (mb_strlen(preg_replace('/[^\p{L}]+/u', '', $out)) >= $minLetters) {
            break;
        }
    }
    return trim($out);
}

function cnp_words($text, $max = 40)
{
    $t = mb_strtolower((string) $text, 'UTF-8');
    $t = strtr($t, ['ά' => 'α', 'έ' => 'ε', 'ή' => 'η', 'ί' => 'ι', 'ό' => 'ο', 'ύ' => 'υ', 'ώ' => 'ω',
        'ϊ' => 'ι', 'ϋ' => 'υ', 'ΐ' => 'ι', 'ΰ' => 'υ', 'ς' => 'σ']);
    preg_match_all('/[a-zα-ω0-9]{3,}/u', $t, $m);
    /* ΠΡΟΣΟΧΗ: η λίστα περνά από την ΙΔΙΑ κανονικοποίηση με το κείμενο. Αλλιώς
       λέξεις σαν «της», «σας», «μας» γίνονται «τησ», «σασ», «μασ» στο κείμενο
       και δεν ταιριάζουν ποτέ με τη λίστα — μετρώνταν ως ουσιαστικές λέξεις και
       μόλυναν κάθε σύγκριση ομοιότητας. */
    $stop = ['και', 'για', 'την', 'τον', 'της', 'του', 'των', 'στο', 'στη', 'στον', 'στην', 'στις', 'στους',
        'που', 'απο', 'από', 'δεν', 'εχω', 'εχει', 'ενα', 'μια', 'εναν', 'ειναι', 'οτι', 'αλλα', 'μου', 'σας',
        'μας', 'τους', 'τις', 'τη', 'το', 'οι', 'με', 'σε', 'ως', 'αν', 'θα', 'να', 'κατα', 'μετα', 'προσ',
        'ολα', 'ολο', 'οταν', 'οπωσ', 'καθε', 'ή', 'the', 'and', 'for', 'with', 'have', 'has', 'this', 'that',
        'not', 'you', 'your', 'are', 'was', 'from', 'can', 'will', 'please', 'hello', 'thanks', 'regards',
        'προβλημα', 'θεμα', 'παρακαλω', 'καλημερα', 'καλησπερα', 'ευχαριστω', 'ευχαριστουμε', 'εταιρειασ',
        /* Θόρυβος από συνδέσμους και υπογραφές: υπάρχει σε κάθε μήνυμα και σε
           κάθε άρθρο, οπότε ταίριαζε άσχετα θέματα μεταξύ τους. */
        'https', 'http', 'www', 'com', 'net', 'org', 'gov', 'mailto', 'html', 'php', 'aspx', 'jpg', 'png',
        'cloudon', 'support', 'team', 'mail', 'email',
        /* Σκελετός των tickets που γράφει η AI ρεσεψιόν — ίδιος σε όλα. */
        'summary', 'notes', 'action', 'items'];
    $stop = array_flip(array_map(function ($w) {
        return strtr($w, ['ά' => 'α', 'έ' => 'ε', 'ή' => 'η', 'ί' => 'ι', 'ό' => 'ο', 'ύ' => 'υ', 'ώ' => 'ω',
            'ϊ' => 'ι', 'ϋ' => 'υ', 'ΐ' => 'ι', 'ΰ' => 'υ', 'ς' => 'σ']);
    }, $stop));
    $out = [];
    foreach ($m[0] as $w) {
        if (!isset($stop[$w])) {
            $out[$w] = true;
        }
        if (count($out) >= $max) {
            break;
        }
    }
    return array_keys($out);
}

/**
 * Καθαρισμός rich-text HTML (ασφαλή tags μόνο· χωρίς 4-byte για utf8mb3 DB).
 * $max: όριο χαρακτήρων — τα μεγάλα πεδία (descr/solution) κρατούν τη χωρητικότητά τους (60k).
 */
/* ================= ΠΑΡΑΠΟΝΑ ΠΕΛΑΤΩΝ =================
   Όποιος μιλάει με πελάτη ακούει και παράπονα. Αν δεν γραφτούν εκείνη τη
   στιγμή, χάνονται — και μαζί τους το μοτίβο που τα γεννάει. Το παράπονο δεν
   είναι ticket (αίτημα) ούτε επικοινωνία (καταγραφή επαφής): έχει κύκλο ζωής
   και απολογισμό, γι' αυτό ζει χωριστά. */

/** Ποιοι μαθαίνουν αμέσως ένα κρίσιμο παράπονο: όσοι το χειρίζονται. */
function cnp_cx_watchers($exceptId = 0)
{
    $ids = [];
    foreach (Capsule::table('tbladmins')->where('disabled', 0)
        ->get(['id', 'firstname', 'lastname', 'username']) as $a) {
        if ((int) $a->id === (int) $exceptId) { continue; }
        if (cnp_is_bot(trim($a->firstname . ' ' . $a->lastname), $a->username)) { continue; }
        if (Db::isFullAccess($a->id) || cnp_has_cap($a->id, false, 'support.complaints.edit')) {
            $ids[] = (int) $a->id;
        }
    }
    return array_values(array_unique($ids));
}

/** Τι αφορά το παράπονο. Σταθερή λίστα: το νόημα είναι να συγκρίνεις μήνες. */
