/**
 * Βρίσκει ή δημιουργεί τον WHMCS πελάτη για μια προσφορά, από τα στοιχεία του
 * εγγράφου (επωνυμία, ΑΦΜ, email, τηλέφωνο, διεύθυνση). Αν δημιουργηθεί νέος
 * λογαριασμός, στέλνει αυτόματα τους κωδικούς σύνδεσης στο MyCloudOn.
 *
 * @param array $cfg   Το config της προσφοράς (κλειδί 'o' με τα στοιχεία).
 * @param array $meta  (out) ['created'=>bool,'emailed'=>bool,'email'=>str,'reason'=>str]
 * @return int  clientid ή 0 αν δεν ήταν εφικτό.
 */
function cnp_offer_ensure_client(array $cfg, $adminId, array &$meta)
{
    $meta = ['created' => false, 'emailed' => false, 'email' => '', 'reason' => ''];
    $o = is_array($cfg['o'] ?? null) ? $cfg['o'] : [];
    $company = trim((string) ($o['client'] ?? ''));
    $contact = trim((string) ($o['attn'] ?? ''));
    $email = filter_var(trim((string) ($o['cemail'] ?? '')), FILTER_VALIDATE_EMAIL);
    $phone = trim((string) ($o['cphone'] ?? ''));
    $afm = preg_replace('/\D+/', '', (string) ($o['afm'] ?? ''));
    $address = trim((string) ($o['address'] ?? ''));
    $city = trim((string) ($o['city'] ?? ''));
    $doy = trim((string) ($o['doy'] ?? ''));
    $meta['email'] = (string) $email;

    if (!$email) { $meta['reason'] = 'no_email'; return 0; }

    // Ήδη υπάρχων πελάτης με αυτό το email → σύνδεση, χωρίς νέους κωδικούς.
    $existing = (int) Capsule::table('tblclients')->where('email', $email)->value('id');
    if ($existing) { return $existing; }

    // Ονοματεπώνυμο: προτεραιότητα στο πρόσωπο επικοινωνίας, αλλιώς από την επωνυμία.
    $first = ''; $last = '';
    if ($contact !== '') {
        $parts = preg_split('/\s+/u', $contact, 2);
        $first = $parts[0]; $last = $parts[1] ?? '-';
    } elseif ($company !== '') {
        $parts = preg_split('/\s+/u', $company, 2);
        $first = $parts[0]; $last = $parts[1] ?? '-';
    } else {
        $meta['reason'] = 'no_name'; return 0;
    }

    // Διεύθυνση: το ΑΑΔΕ-string είναι «οδός, ΤΚ, πόλη» — βγάζουμε ΤΚ (5ψήφιο) & οδό.
    $postcode = '00000'; $street = $address;
    if (preg_match('/\b(\d{5})\b/', $address, $mz)) { $postcode = $mz[1]; }
    $street = trim(preg_replace('/,?\s*\b\d{5}\b.*$/u', '', $address)) ?: ($address ?: '—');

    $pass = cnp_gen_password();
    $res = localAPI('AddClient', [
        'firstname' => $first, 'lastname' => $last ?: '-',
        'companyname' => $company, 'email' => $email,
        'address1' => $street, 'city' => $city ?: '—', 'state' => $city ?: '—',
        'postcode' => $postcode, 'country' => 'GR',
        'phonenumber' => $phone ?: '0000000000',
        'tax_id' => $afm,
        'password2' => $pass,
        'notes' => 'Δημιουργήθηκε αυτόματα από προσφορά (Project Manager)'
            . ($afm ? ' — ΑΦΜ ' . $afm : '') . ($doy ? ', ΔΟΥ ' . $doy : ''),
        'noemail' => true, 'skipvalidation' => true,
    ], 'pdelis');
    if (($res['result'] ?? '') !== 'success' || empty($res['clientid'])) {
        $meta['reason'] = 'whmcs:' . ($res['message'] ?? 'fail');
        return 0;
    }
    $cid = (int) $res['clientid'];
    $meta['created'] = true;

    // Αποστολή κωδικών σύνδεσης στο MyCloudOn.
    $loginUrl = rtrim((string) (Capsule::table('tblconfiguration')->where('setting', 'SystemURL')->value('value')
        ?: 'https://my.cloudon.gr/'), '/') . '/clientarea.php';
    $who = $company ?: trim($first . ' ' . $last);
    $body = 'Καλησπέρα σας,<br><br>'
        . 'δημιουργήσαμε τον λογαριασμό σας στο <b>MyCloudOn</b>, ώστε να μπορείτε να δείτε '
        . 'την προσφορά σας, τα προϊόντα/υπηρεσίες σας και τα αιτήματά σας.<br><br>'
        . '<b>Σύνδεση:</b> <a href="' . htmlspecialchars($loginUrl) . '">' . htmlspecialchars($loginUrl) . '</a><br>'
        . '<b>Email:</b> ' . htmlspecialchars($email) . '<br>'
        . '<b>Κωδικός:</b> ' . htmlspecialchars($pass) . '<br><br>'
        . 'Για την ασφάλειά σας, αλλάξτε τον κωδικό μετά την πρώτη σύνδεση '
        . '(Λογαριασμός → Αλλαγή κωδικού).<br><br>'
        . 'Με εκτίμηση,<br>Η ομάδα της CloudOn';
    $wrap = '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#243447;'
        . 'line-height:1.6;max-width:640px">' . $body . '</div>';
    try {
        $mail = new \PHPMailer\PHPMailer\PHPMailer(true);
        $mail->CharSet = 'UTF-8';
        $mail->setFrom('noreply@cloudon.gr', 'CloudOn');
        $mail->addAddress($email, $who);
        $mail->isHTML(true);
        $mail->Subject = 'Ο λογαριασμός σας στο MyCloudOn';
        $mail->Body = $wrap;
        $mail->AltBody = "Σύνδεση: $loginUrl\nEmail: $email\nΚωδικός: $pass";
        $mail->send();
        $meta['emailed'] = true;
    } catch (\Throwable $e) {
        $meta['reason'] = 'mail:' . $e->getMessage();
    }
    logActivity('CloudOn PM: αυτόματος πελάτης #' . $cid . ' «' . $who . '» από προσφορά (admin '
        . $adminId . ')' . ($meta['emailed'] ? ' — κωδικοί στάλθηκαν' : ' — κωδικοί ΔΕΝ στάλθηκαν'));
    return $cid;
}

/**
 * Εξασφαλίζει WHMCS quote για μια προσφορά, ώστε να φαίνεται native στο portal
 * του πελάτη («Quotes», με accept/decline). Οι γραμμές έρχονται από το
 * lineItems() του τύπου (itemized) — μία πηγή με τις μελλοντικές χρεώσεις.
 * Idempotent: αν υπάρχει ήδη quote, το επιστρέφει.
 *
 * @return int quoteid ή 0.
 */
function cnp_offer_ensure_quote($offer, $type, array $cfg, $adminId)
{
    if ((int) ($offer->quoteid ?? 0) > 0) { return (int) $offer->quoteid; }
    $cid = (int) ($offer->clientid ?? 0);
    if (!$cid) { return 0; }
    $items = $type->lineItems($cfg);
    if (!$items) {
        $items = [['desc' => $offer->title ?: 'Προσφορά', 'qty' => 1.0,
            'unit' => (float) ($offer->amount ?? 0), 'taxable' => true]];
    }
    $li = [];
    foreach ($items as $it) {
        $li[] = ['desc' => (string) $it['desc'], 'qty' => (float) ($it['qty'] ?? 1),
            'up' => (float) ($it['unit'] ?? 0), 'discount' => 0, 'taxable' => !empty($it['taxable'])];
    }
    $r = localAPI('CreateQuote', [
        'subject' => $offer->title ?: 'Προσφορά', 'stage' => 'Delivered',
        'validuntil' => $offer->expected_close ?: date('Y-m-d', strtotime('+30 days')),
        'userid' => $cid,
        'lineitems' => base64_encode(serialize($li)),
    ], 'pdelis');
    if (($r['result'] ?? '') === 'success' && !empty($r['quoteid'])) {
        $qid = (int) $r['quoteid'];
        Capsule::table('mod_cpm_offers')->where('id', (int) $offer->id)->update(['quoteid' => $qid]);
        logActivity('CPM: δημιουργία WHMCS quote #' . $qid . ' από προσφορά #' . (int) $offer->id
            . ' (portal πελάτη)');
        return $qid;
    }
    return 0;
}

/**
 * Ασφαλές fetch URL που δίνει ο χρήστης (εισαγωγή γνώσης από τεκμηρίωση).
 * 🔒 SSRF: μόνο http/https, ΟΧΙ ιδιωτικά/loopback IP, όριο μεγέθους & redirects.
 */
function cnp_safe_fetch($url, $maxBytes = 3000000)
{
    $p = parse_url((string) $url);
    if (!$p || !in_array(strtolower($p['scheme'] ?? ''), ['http', 'https'], true) || empty($p['host'])) {
        return ['ok' => false, 'error' => 'Μη έγκυρο URL (μόνο http/https)'];
    }
    $ips = @gethostbynamel($p['host']);
    if (!$ips) {
        $ips = filter_var($p['host'], FILTER_VALIDATE_IP) ? [$p['host']] : [];
    }
    if (!$ips) {
        return ['ok' => false, 'error' => 'Το domain δεν αναλύεται'];
    }
    foreach ($ips as $ip) {
        if (!filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_NO_PRIV_RANGE | FILTER_FLAG_NO_RES_RANGE)) {
            return ['ok' => false, 'error' => 'Δεν επιτρέπονται εσωτερικές διευθύνσεις'];
        }
    }
    $ch = curl_init($url);
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 25, CURLOPT_CONNECTTIMEOUT => 10,
        CURLOPT_FOLLOWLOCATION => true, CURLOPT_MAXREDIRS => 3,
        CURLOPT_PROTOCOLS => CURLPROTO_HTTP | CURLPROTO_HTTPS,
        CURLOPT_REDIR_PROTOCOLS => CURLPROTO_HTTP | CURLPROTO_HTTPS,
        CURLOPT_USERAGENT => 'Mozilla/5.0 (compatible; CloudOnProjects/1.0)',
        CURLOPT_BUFFERSIZE => 65536, CURLOPT_NOPROGRESS => false,
        CURLOPT_PROGRESSFUNCTION => function ($r, $dl) use ($maxBytes) { return $dl > $maxBytes ? 1 : 0; },
    ]);
    $body = curl_exec($ch);
    $code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    $eff = curl_getinfo($ch, CURLINFO_EFFECTIVE_URL);
    curl_close($ch);
    if ($body === false || $code >= 400) {
        return ['ok' => false, 'error' => 'Η σελίδα δεν κατέβηκε (HTTP ' . $code . ')'];
    }
    return ['ok' => true, 'body' => $body, 'url' => $eff ?: $url, 'code' => $code];
}

/**
 * Ο cursor της επόμενης σελίδας ενός Confluence api/v2 response, ως «&cursor=…».
 * ΔΕΝ χρησιμοποιούμε αυτούσιο το _links.next: έρχεται με πρόθεμα «/wiki/» (Atlassian Cloud)
 * που δεν ισχύει σε custom domain → η σελιδοποίηση σταματούσε στην 1η σελίδα.
 */
function cnp_cursor_of($json)
{
    $n = $json['_links']['next'] ?? '';
    return ($n && preg_match('/[?&]cursor=([^&]+)/', $n, $m)) ? '&cursor=' . $m[1] : '';
}

/** Το root ενός URL (https://host) — για να βρούμε το wp-json. */
function cnp_site_root($url)
{
    $p = parse_url($url);
    return $p['scheme'] . '://' . $p['host'] . (!empty($p['port']) ? ':' . $p['port'] : '');
}

/**
 * Μετατρέπει σχετικά src/href σε απόλυτα (με βάση το URL του άρθρου) και πετά το
 * srcset/sizes — αλλιώς οι εικόνες σπάνε όταν το περιεχόμενο εμφανίζεται στο δικό μας domain.
 */
function cnp_absolutize_html($html, $base)
{
    $p = parse_url($base);
    if (empty($p['host'])) { return $html; }
    $root = ($p['scheme'] ?? 'https') . '://' . $p['host'];
    $dir = $root . preg_replace('#/[^/]*$#', '/', $p['path'] ?? '/');
    $html = preg_replace('/\s(?:srcset|sizes|data-lazy-srcset)\s*=\s*("[^"]*"|\'[^\']*\')/i', '', $html);
    return preg_replace_callback('/\s(src|href)\s*=\s*"([^"]*)"/i', function ($m) use ($root, $dir) {
        $u = trim($m[2]);
        if ($u === '' || preg_match('#^(https?:|mailto:|tel:|data:|\#)#i', $u)) { return $m[0]; }
        if (strpos($u, '//') === 0) { return ' ' . $m[1] . '="https:' . $u . '"'; }
        if ($u[0] === '/') { return ' ' . $m[1] . '="' . $root . $u . '"'; }
        return ' ' . $m[1] . '="' . $dir . $u . '"';
    }, $html);
}

/** Κύριο περιεχόμενο από HTML σελίδα (χωρίς μενού/υποσέλιδα) + τίτλος. */
function cnp_html_article($html)
{
    $title = '';
    if (preg_match('/<h1[^>]*>(.*?)<\/h1>/is', $html, $m)) {
        $title = trim(html_entity_decode(strip_tags($m[1]), ENT_QUOTES, 'UTF-8'));
    }
    if ($title === '' && preg_match('/<title[^>]*>(.*?)<\/title>/is', $html, $m)) {
        $title = trim(html_entity_decode(strip_tags($m[1]), ENT_QUOTES, 'UTF-8'));
    }
    $html = preg_replace('#<(script|style|nav|header|footer|form|noscript|svg)\b[^>]*>.*?</\1>#is', ' ', $html);
    $body = '';
    foreach (['#<article\b[^>]*>(.*?)</article>#is', '#<main\b[^>]*>(.*?)</main>#is',
        '#<div[^>]*class="[^"]*(?:entry-content|betterdocs-content|post-content)[^"]*"[^>]*>(.*?)</div>\s*</div>#is'] as $rx) {
        if (preg_match($rx, $html, $m)) { $body = $m[1]; break; }
    }
    if ($body === '' && preg_match('#<body\b[^>]*>(.*?)</body>#is', $html, $m)) { $body = $m[1]; }
    return ['title' => mb_substr($title, 0, 200), 'html' => $body];
}

/** Κατηγορίες tickets (area/cause) — cached ανά request. */
function cnp_ticket_cats()
{
    static $c = null;
    if ($c !== null) {
        return $c;
    }
    $c = ['area' => [], 'cause' => []];
    foreach (Capsule::table('mod_cpm_ticket_cats')->orderBy('sort')->orderBy('id')->get() as $r) {
        $c[$r->kind === 'cause' ? 'cause' : 'area'][] = ['id' => (int) $r->id, 'name' => $r->name, 'color' => $r->color];
    }
    return $c;
}

/** 🖥 Guacamole SSO: φτιάχνει token+URL που μπαίνει ΚΑΤΕΥΘΕΙΑΝ στη σύνδεση (json-auth). */
function cnp_guac_launch($protocol, $host, $port, $user, $pass, $extra = [])
{
    $secret = (string) Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')
        ->where('setting', 'guac_secret')->value('value');
    $base = rtrim((string) Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')
        ->where('setting', 'guac_url')->value('value'), '/');
    if ($secret === '' || $base === '') {
        return null;
    }
    $key = hex2bin($secret);
    $conn = 'remote';
    $params = array_merge(['hostname' => $host, 'port' => (string) $port,
        'username' => $user, 'password' => $pass], $extra);
    $payload = ['username' => 'tech-' . (int) ($_SESSION['pm_admin'] ?? 0) . '-' . substr(md5(microtime()), 0, 6),
        'expires' => (string) ((time() + 3600) * 1000),
        'connections' => [$conn => ['protocol' => $protocol, 'parameters' => $params]]];
    $json = json_encode($payload, JSON_UNESCAPED_UNICODE);
    $sig = hash_hmac('sha256', $json, $key, true);
    $blob = base64_encode(openssl_encrypt($sig . $json, 'AES-128-CBC', $key, OPENSSL_RAW_DATA, str_repeat("\0", 16)));
    $ch = curl_init($base . '/api/tokens');
    $opts = [CURLOPT_RETURNTRANSFER => true, CURLOPT_POST => true, CURLOPT_TIMEOUT => 15,
        CURLOPT_POSTFIELDS => http_build_query(['data' => $blob])];
    $gip = (string) Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')
        ->where('setting', 'guac_ip')->value('value');
    if ($gip !== '' && preg_match('#^https?://([^/:]+)#', $base, $mh)) {
        $opts[CURLOPT_RESOLVE] = [$mh[1] . ':443:' . $gip, $mh[1] . ':80:' . $gip];
    }
    curl_setopt_array($ch, $opts);
    $resp = json_decode((string) curl_exec($ch), true);
    curl_close($ch);
    if (empty($resp['authToken'])) {
        return null;
    }
    // client identifier: base64( conn + NUL + 'c' + NUL + 'json' )
    $clientId = base64_encode($conn . "\0c\0json");
    return $base . '/#/client/' . $clientId . '?token=' . rawurlencode($resp['authToken']);
}

/** Ποιος επιτρέπεται να απαντά σε ΠΕΛΑΤΕΣ: διαχειριστές + επικεφαλής ομάδων. */
function cnp_can_reply_clients($adminId, $isFull)
{
    if ($isFull) {
        return true;
    }
    try {
        return Capsule::table('mod_cpm_team_members')->where('admin_id', (int) $adminId)
            ->where('is_leader', 1)->exists();
    } catch (\Throwable $e) {
        return false;
    }
}

/* ───────── Δικαιώματα σε ενότητες του μενού ─────────
   Ένας ορισμός, μία φορά: τον διαβάζουν και ο έλεγχος του server και η οθόνη
   των ομάδων, ώστε να μη γίνει η λίστα δύο λίστες που αποκλίνουν. */
/** Τα προϊόντα WHMCS που πιστώνουν προαγορά (ρύθμιση `prepaid_hours_map`). */
function cnp_prepaid_products()
{
    $raw = (string) Capsule::table('tbladdonmodules')->where('module', 'supportcontracts')
        ->where('setting', 'prepaid_hours_map')->value('value');
    $map = json_decode($raw, true);
    if (!is_array($map)) {
        return [];
    }
    $out = [];
    foreach ($map as $pid => $hours) {
        $name = Capsule::table('tblproducts')->where('id', (int) $pid)->value('name');
        $out[] = ['id' => (int) $pid, 'hours' => (float) $hours,
            'name' => $name ?: ('Προϊόν #' . (int) $pid), 'exists' => (bool) $name];
    }
    usort($out, function ($a, $b) { return $a['hours'] <=> $b['hours']; });
    return $out;
}
/** Λογαριασμός-ρομπότ ή συστήματος, όχι άνθρωπος της ομάδας. */
function cnp_is_bot($name, $username = '')
{
    return (bool) preg_match('/\b(bot|debug|good ?day|chat ?bot|team team|support team)\b/i',
        trim($name . ' ' . $username));
}
/**
 * Οι απαντήσεις σε tickets κρατούν το ΟΝΟΜΑ του χειριστή, όχι id. Χαρτογράφηση
 * ονόματος/username → id, με την ίδια λογική που χρησιμοποιεί η «Απόδοση
 * χειριστών»: τα bot/chatbot μένουν έξω γιατί δεν είναι άνθρωποι της ομάδας.
 */
function cnp_admin_by_name($name)
{
    static $map = null;
    if ($map === null) {
        $map = [];
        foreach (Capsule::table('tbladmins')->where('disabled', 0)
            ->get(['id', 'firstname', 'lastname', 'username']) as $a) {
            $nm = trim($a->firstname . ' ' . $a->lastname);
            if (cnp_is_bot($nm, $a->username)) {
                continue;
            }
            foreach (array_filter([$nm, (string) $a->username]) as $k) {
                $map[mb_strtolower($k)] = (int) $a->id;
            }
        }
    }
    return $map[mb_strtolower(trim((string) $name))] ?? 0;
}
/* ═══ ΑΔΕΙΕΣ — βοηθητικά ═══════════════════════════════════════════════ */

/** Πόσες ημέρες ενός τύπου (ή όλων εκτός κάποιων) μέσα σε ένα έτος δικαιώματος. */
function cnp_leave_sum($staffId, $year, $type = null, array $except = [])
{
    $q = Capsule::table('mod_cpm_leaves')->where('staff_id', (int) $staffId)
        ->where('year', (int) $year)->whereIn('status', Leave::COUNTS);
    if ($type !== null) { $q->where('type', $type); }
    if ($except) { $q->whereNotIn('type', $except); }
    return (float) $q->sum('days');
}

/** Πώς γράφεται μια περίοδος για άνθρωπο. */
function cnp_leave_span($r)
{
    $f = $r->date_from ?? null;
    $t = $r->date_to ?? null;
    if (!$f) { return (string) ($r->raw_period ?? '—'); }
    $fmt = function ($d) { return date('d/m/Y', strtotime($d)); };
    return ($t && $t !== $f) ? $fmt($f) . ' – ' . $fmt($t) : $fmt($f);
}

/**
 * Η κατάσταση που ΒΛΕΠΕΙ ο χρήστης.
 *
 * Το `taken` δεν το πατάει κανείς: μια εγκεκριμένη άδεια που πέρασε είναι
 * ληφθείσα, και μια που τρέχει σήμερα είναι «σε εξέλιξη». Το υπολογίζουμε
 * κάθε φορά αντί να τρέχει cron που «κλείνει» άδειες — λιγότερα κινούμενα μέρη.
 */
function cnp_leave_phase($r, $today = null)
{
    $today = $today ?: date('Y-m-d');
    if (in_array($r->status, ['rejected', 'cancelled'], true)) { return $r->status; }
    if ($r->status === 'requested') { return 'requested'; }
    $f = $r->date_from ?? null;
    $t = $r->date_to ?: $f;
    if (!$f) { return $r->status; }
    if ($t < $today) { return 'taken'; }
    if ($f <= $today && $t >= $today) { return 'running'; }
    return 'upcoming';
}

function cnp_leave_row($r)
{
    $st = Capsule::table('mod_cpm_leave_staff')->where('id', $r->staff_id)->first();
    return [
        'id'        => (int) $r->id,
        'staffId'   => (int) $r->staff_id,
        'adminId'   => $st ? (int) $st->admin_id : 0,
        'name'      => $st ? Db::adminName($st->admin_id) : '—',
        'year'      => (int) $r->year,
        'type'      => (string) $r->type,
        'typeLabel' => Leave::typeLabel($r->type),
        'deducts'   => Leave::deducts($r->type),
        'days'      => (float) $r->days,
        'from'      => (string) $r->date_from,
        'to'        => (string) $r->date_to,
        'span'      => cnp_leave_span($r),
        'raw'       => (string) $r->raw_period,
        'status'    => (string) $r->status,
        'phase'     => cnp_leave_phase($r),
        'ergani'    => (string) $r->ergani,
        'flag'      => (string) $r->flag,
        'flagLabel' => $r->flag ? (Leave::FLAGS[$r->flag] ?? $r->flag) : '',
        'note'      => (string) $r->note,
        'source'    => (string) $r->source_id,
        'approvedBy' => $r->approved_by ? Db::adminName($r->approved_by) : '',
    ];
}

/** Τα έτη δικαιώματος που υπάρχουν στα δεδομένα — για το φίλτρο. */
function cnp_leave_years_seen()
{
    $y = Capsule::table('mod_cpm_leave_years')->distinct()->orderBy('year', 'desc')
        ->pluck('year')->all();
    $cur = (int) date('Y');
    if (!in_array($cur, array_map('intval', $y), true)) { array_unshift($y, $cur); }
    return array_values(array_map('intval', $y));
}

function cnp_leave_types()
{
    $out = [];
    foreach (Leave::TYPES as $code => $d) {
        $out[] = ['code' => $code, 'label' => $d[0], 'deducts' => $d[1]];
    }
    return $out;
}

/** Φιλτραρισμένη λίστα αδειών — ίδια αριθμητική με τα πλακίδια. */
function cnp_leave_query(array $in)
{
    $q = Capsule::table('mod_cpm_leaves as l')
        ->join('mod_cpm_leave_staff as s', 's.id', '=', 'l.staff_id');
    if (!empty($in['staffId'])) { $q->where('l.staff_id', (int) $in['staffId']); }
    if (!empty($in['adminId'])) { $q->where('s.admin_id', (int) $in['adminId']); }
    if (!empty($in['year']))    { $q->where('l.year', (int) $in['year']); }
    if (!empty($in['type']))    { $q->where('l.type', (string) $in['type']); }
    if (!empty($in['flag']))    { $q->where('l.flag', (string) $in['flag']); }
    if (!empty($in['status']))  { $q->where('l.status', (string) $in['status']); }
    if (!empty($in['erganiMissing'])) {
        $q->where(function ($w) { $w->whereNull('l.ergani')->orWhere('l.ergani', ''); })
          ->whereIn('l.status', ['approved', 'taken']);
    }
    if (!empty($in['q'])) {
        /* Ταύτιση ΟΠΟΥΔΗΠΟΤΕ μέσα στο κείμενο — όπως παντού στο εργαλείο. */
        $needle = '%' . trim((string) $in['q']) . '%';
        $q->where(function ($w) use ($needle) {
            $w->where('l.note', 'like', $needle)->orWhere('l.raw_period', 'like', $needle)
              ->orWhere('l.ergani', 'like', $needle)->orWhere('l.source_id', 'like', $needle);
        });
    }
    $rows = [];
    foreach ($q->orderBy('l.date_from', 'desc')->orderBy('l.id', 'desc')
            ->limit(500)->get(['l.*']) as $r) {
        $rows[] = cnp_leave_row($r);
    }
    return ['rows' => $rows, 'count' => count($rows)];
}

/** Η καρτέλα ενός εργαζομένου: υπόλοιπα ανά έτος + οι άδειές του. */
function cnp_leave_person($st, $withLeaves = false)
{
    $years = [];
    foreach (Leave::balance($st->id) as $y => $b) {
        $years[] = ['year' => $y] + $b + ['deadline' => Leave::carryDeadline($y)];
    }
    $out = [
        'staffId'   => (int) $st->id,
        'adminId'   => (int) $st->admin_id,
        'name'      => Db::adminName($st->admin_id),
        'afm'       => (string) $st->afm,
        'hire'      => (string) $st->hire_date,
        'priorMonths' => (int) ($st->prior_months ?? 0),
        'years'     => $years,
        'remaining' => Leave::remainingTotal($st->id),
        'expiring'  => Leave::expiring($st->id),
        'sickThisYear' => cnp_leave_sum($st->id, (int) date('Y'), 'SICK'),
    ];
    if ($withLeaves) {
        $out += cnp_leave_query(['staffId' => (int) $st->id]);
    }
    return $out;
}

/**
 * Γράφει άδεια (νέα ή υπάρχουσα) και κρατά το ημερολόγιο συγχρονισμένο.
 *
 * @param string|null $forceStatus 'requested' όταν ζητάει ο ίδιος ο εργαζόμενος —
 *                                 δεν του επιτρέπουμε να γράψει «εγκεκριμένη».
 */
function cnp_leave_write($id, $staff, array $in, $byAdminId, $forceStatus = null)
{
    $type = (string) ($in['type'] ?? 'ANNUAL');
    if (!isset(Leave::TYPES[$type])) { fail('Άγνωστος τύπος άδειας'); }
    $from = trim((string) ($in['from'] ?? ''));
    $to   = trim((string) ($in['to'] ?? '')) ?: $from;
    if ($from === '') { fail('Βάλε ημερομηνία έναρξης'); }
    if ($to < $from) { fail('Η λήξη είναι πριν από την έναρξη'); }

    /* Οι ημέρες ΔΕΝ υπολογίζονται από τις ημερομηνίες (αργίες, μισές μέρες).
       Αν δεν δοθούν, προτείνουμε τις εργάσιμες — και ο χειριστής τις βλέπει. */
    $days = isset($in['days']) && $in['days'] !== ''
        ? round((float) $in['days'], 2) : (float) Leave::suggestDays($from, $to);

    /* Το έτος ΔΙΚΑΙΩΜΑΤΟΣ δεν είναι το έτος της ημερομηνίας: άδεια του 2025
       λαμβάνεται νόμιμα ως τις 31/3/2026. Αν δεν δοθεί ρητά, το μαντεύουμε
       συντηρητικά — μέσα στο πρώτο τρίμηνο χρεώνεται στο προηγούμενο έτος. */
    if (isset($in['year']) && (int) $in['year'] > 2000) {
        $year = (int) $in['year'];
    } else {
        $y = (int) date('Y', strtotime($from));
        $year = ((int) date('n', strtotime($from)) <= 3) ? $y - 1 : $y;
    }

    $vals = [
        'staff_id'   => (int) $staff->id,
        'year'       => $year,
        'type'       => $type,
        'days'       => $days,
        'date_from'  => $from,
        'date_to'    => $to,
        'raw_period' => trim((string) ($in['raw'] ?? '')) ?: null,
        'ergani'     => trim((string) ($in['ergani'] ?? '')) ?: null,
        'flag'       => isset(Leave::FLAGS[(string) ($in['flag'] ?? '')]) ? $in['flag'] : null,
        'note'       => trim((string) ($in['note'] ?? '')) ?: null,
        'updated_at' => date('Y-m-d H:i:s'),
    ];
    if ($forceStatus !== null) {
        $vals['status'] = $forceStatus;
    } elseif (isset($in['status']) && isset(Leave::FLOW[(string) $in['status']])) {
        $vals['status'] = (string) $in['status'];
    }

    if ($id) {
        Capsule::table('mod_cpm_leaves')->where('id', (int) $id)->update($vals);
    } else {
        $vals['status'] = $vals['status'] ?? ($forceStatus ?: 'approved');
        $vals['created_by'] = (int) $byAdminId;
        $vals['created_at'] = date('Y-m-d H:i:s');
        $id = (int) Capsule::table('mod_cpm_leaves')->insertGetId($vals);
    }
    cnp_leave_mirror($id);

    /* Ο υπεύθυνος μαθαίνει ότι υπάρχει αίτημα — χωρίς αυτό, το αίτημα κάθεται. */
    if ($forceStatus === 'requested') {
        foreach (Capsule::table('tbladmins')->where('disabled', 0)->pluck('id') as $aid) {
            if ((int) $aid !== (int) $byAdminId && cnp_has_cap((int) $aid, false, 'hr.leave.approve')) {
                Db::pushNotification((int) $aid, 'leave',
                    'Αίτημα άδειας: ' . Db::adminName($staff->admin_id) . ' — '
                    . date('d/m/Y', strtotime($from)) . ($to !== $from ? ' – ' . date('d/m/Y', strtotime($to)) : ''),
                    '#/leave');
            }
        }
    }

    $bal = Leave::balance($staff->id, $type);
    return ['ok' => true, 'id' => (int) $id, 'days' => $days, 'year' => $year,
        'balance' => $bal[$year] ?? null];
}

/**
 * Καθρέφτισμα στο κοινό ημερολόγιο.
 *
 * Το ημερολόγιο και η ζώνη διαθεσιμότητας διαβάζουν ήδη `mod_cpm_events` με
 * kind='leave' — υπήρχαν πριν από αυτό το κύκλωμα. Αντί να τα ξαναγράψουμε,
 * κρατάμε ένα αντίγραφο συγχρονισμένο: μία πηγή αλήθειας (οι άδειες), μία
 * προβολή (το ημερολόγιο). ΜΟΝΟ εγκεκριμένες φαίνονται — ένα αίτημα δεν είναι
 * απουσία μέχρι να εγκριθεί.
 */
function cnp_leave_mirror($leaveId)
{
    $r = Capsule::table('mod_cpm_leaves')->where('id', (int) $leaveId)->first();
    if (!$r) { return; }
    $st = Capsule::table('mod_cpm_leave_staff')->where('id', $r->staff_id)->first();
    $show = $st && in_array($r->status, ['approved', 'taken'], true) && $r->date_from;

    if (!$show) {
        if ($r->event_id) {
            Capsule::table('mod_cpm_events')->where('id', (int) $r->event_id)->delete();
            Capsule::table('mod_cpm_leaves')->where('id', (int) $r->id)->update(['event_id' => null]);
        }
        return;
    }
    $ev = [
        'kind'      => 'leave',
        'title'     => Leave::typeLabel($r->type) . ' — ' . Db::adminName($st->admin_id),
        'start_dt'  => $r->date_from . ' 00:00:00',
        'end_dt'    => ($r->date_to ?: $r->date_from) . ' 23:59:59',
        'all_day'   => 1,
        'attendees' => ',' . (int) $st->admin_id . ',',
        'scope'     => 'internal',
        'notes'     => trim((string) $r->note) ?: null,
    ];
    if ($r->event_id && Capsule::table('mod_cpm_events')->where('id', (int) $r->event_id)->exists()) {
        Capsule::table('mod_cpm_events')->where('id', (int) $r->event_id)->update($ev);
    } else {
        $ev['created_by'] = (int) ($r->created_by ?: $st->admin_id);
        $ev['created_at'] = date('Y-m-d H:i:s');
        $eid = (int) Capsule::table('mod_cpm_events')->insertGetId($ev);
        Capsule::table('mod_cpm_leaves')->where('id', (int) $r->id)->update(['event_id' => $eid]);
    }
}

/** Πόσα «κρέμονται» από κάθε προϊόν — ώστε να μη σβήνεται ό,τι κουβαλά ιστορικό. */
/**
 * ΤΙ ΗΤΑΝ Η ΚΛΗΣΗ. Λεξιλόγιο, όχι ελεύθερο κείμενο: αν ο καθένας γράφει δικά
 * του, δεν βγαίνει ποτέ «πού πήγε ο χρόνος». Το «τι ακριβώς» το λέει η
 * περίληψη· αυτό εδώ είναι το είδος, για να αθροίζεται.
 */
/**
 * ΑΠΟ ΠΟΤΕ ΖΗΤΑΜΕ ΧΑΡΑΚΤΗΡΙΣΜΟ ΚΛΗΣΕΩΝ.
 *
 * Απόφαση 22/09/2026: ΟΧΙ αναδρομικά. Τη στιγμή που άνοιξε το κύκλωμα υπήρχαν
 * 15.986 κλήσεις και μόνο μία χαρακτηρισμένη — το να ζητούσαμε να συμπληρωθούν
 * όλες θα ήταν ένα βουνό που κανείς δεν ανεβαίνει, και θα έκαιγε το κύκλωμα από
 * την πρώτη μέρα. Μετράει ό,τι έγινε ΑΠΟ ΤΗΝ ΕΝΑΡΞΗ ΚΑΙ ΜΕΤΑ.
 *
 * Η αφετηρία γράφεται μία φορά, την πρώτη που ρωτηθεί, και μένει.
 */
function cnp_calls_label_from()
{
    $v = (string) Db::pref(0, 'calls_label_from', '');
    if ($v === '') {
        $v = date('Y-m-d');
        Db::setPref(0, 'calls_label_from', $v);
    }
    return $v;
}

/**
 * ΥΠΑΡΧΕΙ ΟΝΤΩΣ ΤΟ VM; — ρωτάει τη Hetzner, δεν υποθέτει.
 *
 * Η πρώτη εκδοχή αυτού του ελέγχου κοιτούσε μόνο τον ΔΙΚΟ ΜΑΣ πίνακα
 * (mod_hetzner_instances) και φώναζε «δεν έκλεισε ο κύκλος» για τρεις
 * υπηρεσίες. Και οι τρεις ήταν κανονικά διαγραμμένες στη Hetzner — απλώς η
 * εγγραφή σύνδεσης δεν είχε καθαριστεί. Δηλαδή ψευδής συναγερμός, που είναι
 * χειρότερος από καμία ένδειξη: την επόμενη φορά κανείς δεν την κοιτάζει.
 *
 * Επιστρέφει 'live' | 'gone' | 'unknown'. Το 'unknown' ΔΕΝ γίνεται ποτέ
 * συναγερμός: αν δεν μπορέσαμε να ρωτήσουμε, δεν ξέρουμε.
 *
 * Η απάντηση κρατιέται 12 ώρες — τα μηχανήματα δεν εξαφανίζονται κάθε λεπτό,
 * και η κάρτα της ημέρας δεν πρέπει να περιμένει εξωτερικό API σε κάθε άνοιγμα.
 */
function cnp_vm_alive($serverId, $projectId)
{
    $serverId = (int) $serverId;
    if (!$serverId) { return 'unknown'; }

    $key = 'hzchk:' . $serverId;
    $hit = (string) Db::pref(0, $key, '');
    if ($hit !== '' && strpos($hit, ':') !== false) {
        [$state, $ts] = explode(':', $hit, 2);
        if (time() - (int) $ts < 12 * 3600 && in_array($state, ['live', 'gone'], true)) { return $state; }
    }

    $apiFile = __DIR__ . '/../modules/servers/hetznercloud/lib/Api.php';
    if (!is_file($apiFile)) { return 'unknown'; }
    require_once $apiFile;
    $cls = 'WHMCS\Module\Server\HetznerCloud\Api';
    if (!class_exists($cls)) { return 'unknown'; }

    $tok = (string) Capsule::table('mod_hetzner_projects')->where('id', (int) $projectId)->value('api_token');
    if ($tok === '') { return 'unknown'; }
    try { $plain = (string) (localAPI('DecryptPassword', ['password2' => $tok])['password'] ?? ''); }
    catch (\Throwable $e) { $plain = ''; }
    if (!preg_match('/^[A-Za-z0-9]{40,80}$/', $plain)) { $plain = $tok; }

    $state = 'unknown';
    try {
        $api = new $cls($plain, 15);
        $api->getServer($serverId);
        $state = 'live';
    } catch (\Throwable $e) {
        $m = $e->getMessage();
        /* ΜΟΝΟ το ρητό «δεν βρέθηκε» σημαίνει διαγραμμένο. Ένα δίκτυο που
           έπεσε δεν είναι απόδειξη ότι το μηχάνημα έφυγε. */
        $state = (stripos($m, 'not_found') !== false || strpos($m, '404') !== false) ? 'gone' : 'unknown';
    }
    if ($state !== 'unknown') { Db::setPref(0, $key, $state . ':' . time()); }
    return $state;
}

