/**
 * ΛΕΠΤΑ ΟΜΙΛΙΑΣ στο τηλέφωνο, από τα CDR του 3CX.
 *
 * Είναι πραγματική δουλειά που ΚΑΝΕΝΑ χρονόμετρο δεν πιάνει: ο χειριστής δεν
 * σταματά να πατήσει «έναρξη» επειδή χτύπησε το τηλέφωνο. Χωρίς αυτό, κάποιος
 * με δεκαέξι ώρες ομιλίας την εβδομάδα φαινόταν να «μην καταγράφει χρόνο».
 *
 * Μετριέται ο ΧΡΟΝΟΣ ΟΜΙΛΙΑΣ, όχι η διάρκεια της κλήσης: το κουδούνισμα και η
 * αναμονή δεν είναι δουλειά.
 *
 * @return array<string,int> ημερομηνία => λεπτά
 */
function cnp_phone_minutes($adminId, $from, $to)
{
    $out = [];
    foreach (Capsule::table('mod_cpm_calls')
        ->where('admin_id', (int) $adminId)
        ->where('talk_seconds', '>', 0)
        ->where('started_at', '>=', $from . ' 00:00:00')
        ->where('started_at', '<=', $to . ' 23:59:59')
        ->selectRaw('DATE(started_at) d, SUM(talk_seconds) s')
        ->groupBy('d')->get() as $r) {
        $out[(string) $r->d] = (int) round(((int) $r->s) / 60);
    }
    return $out;
}

function cnp_product_usage()
{
    $out = [];
    foreach ([['mod_cpm_tasks', 'product_id'], ['mod_cpm_client_products', 'product_id'],
              ['mod_cpm_agent_skills', 'product_id'], ['mod_cpm_projects', 'product_id']] as [$t, $c]) {
        foreach (Capsule::table($t)->whereNotNull($c)->where($c, '>', 0)
                    ->select($c, Capsule::raw('COUNT(*) n'))->groupBy($c)->get() as $r) {
            $out[(int) $r->$c] = ($out[(int) $r->$c] ?? 0) + (int) $r->n;
        }
    }
    return $out;
}

function cnp_area_defs()
{
    /* Ένα δικαίωμα = μία ενότητα του μενού, με το ίδιο όνομα. Η σειρά εδώ είναι
       η σειρά του μενού, ώστε η καρτέλα της ομάδας να διαβάζεται σαν το μενού.
       Η ενότητα «Τα δικά μου» (Η μέρα μου, πλάνο, χρόνος, βιβλιοθήκη, κωδικοί,
       προφίλ) ΔΕΝ έχει δικαίωμα: είναι προσωπικές οθόνες, τις βλέπει κάθε
       χειριστής. Όλα τα υπόλοιπα κυκλώματα δίνονται από τις ΟΜΑΔΕΣ. */
    return [
        'clients'  => ['Πελάτες', 'Πελάτης 360°, CRM & leads, προσφορές, επικοινωνίες, καμπάνιες'],
        'support'  => ['Υποστήριξη', 'Tickets και βάση γνώσης'],
        /* ΤΗΛΕΦΩΝΙΚΟ ΚΕΝΤΡΟ (20/09/2026). Τα δικαιώματα `comms.*` υπήρχαν και
           ελέγχονταν, αλλά ΔΕΝ εμφανίζονταν πουθενά στην οθόνη δικαιωμάτων:
           η περιοχή «comms» δεν ήταν δηλωμένη εδώ, οπότε κόβονταν σιωπηλά.
           Αποτέλεσμα: ολόκληρο το κύκλωμα του κέντρου δεν μπορούσε να δοθεί σε
           καμία ομάδα — το έβλεπαν μόνο οι πλήρεις διαχειριστές. */
        'comms'    => ['Τηλεφωνικό κέντρο', 'Κατάλογος, κλήσεις, δρομολόγηση, κίνηση πελάτη, διασύνδεση 3CX'],
        'projects' => ['Έργα & υλοποιήσεις', 'Έργα, board, λίστα, χρονοδιάγραμμα, modules, departments'],
        /* Η «Η ομάδα» ήταν εκτός μοντέλου (chat/ημερολόγιο/standup/remote τα έβλεπαν
           όλοι, χωρίς δικαίωμα). Μπήκε ως κανονικό κύκλωμα (12/9/2026) ώστε να
           φαίνονται ΟΛΑ τα κυκλώματα και να δίνονται με λεπτομέρεια. */
        'team'     => ['Η ομάδα', 'Chat & φωνή, κοινό ημερολόγιο, standup, απομακρυσμένες συνδέσεις'],
        /* Η «Διοίκηση» ήταν μία ενιαία ενότητα, οπότε για να δώσεις σε έναν
           project manager το KPI έπρεπε να του δώσεις και τα οικονομικά και τις
           ρυθμίσεις. Σπασμένη σε τρία, δίνεται κατά ενότητα. */
        'prepaid'  => ['Προαγορά χρόνου', 'Συμβόλαια, υπόλοιπα, ακάλυπτος χρόνος, μηνιαίες αναφορές'],
        'reports'  => ['Αναφορές & απόδοση', 'Δραστηριότητα, πλάνο ημέρας, KPI, ανάλυση ριζών, απόδοση'],
        'finance'  => ['Οικονομικά', 'Κερδοφορία, συμφωνία πληρωμών, λογιστικός έλεγχος, αναστολές'],
        'hr'       => ['Προσωπικό', 'Άδειες και υπόλοιπα, βιογραφικά και αξιολογήσεις υποψηφίων'],
        'admin'    => ['Σύστημα', 'Ομάδες & δικαιώματα, χρήστες, ρυθμίσεις, automations, πακέτα'],
    ];
}
function cnp_area_keys()
{
    return array_keys(cnp_area_defs());
}
/** Οι περιοχές που δίνει κάθε ομάδα. */
/** Παλιά ονόματα δικαιωμάτων → σημερινά. */
function cnp_area_alias(array $keys)
{
    $al = ['sales' => 'clients'];
    $out = [];
    foreach ($keys as $k) { $out[] = $al[$k] ?? $k; }
    return array_unique($out);
}
function cnp_team_areas($teamId)
{
    $raw = (string) Capsule::table('mod_cpm_teams')->where('id', (int) $teamId)->value('areas');
    return array_values(array_intersect(cnp_perm_keys(),
        cnp_area_alias(array_filter(array_map('trim', explode(',', $raw))))));
}
/**
 * Ειδικότητες/πρόσβαση χειριστή.
 * full → όλα. Αλλιώς: ένωση των περιοχών ΤΩΝ ΟΜΑΔΩΝ ΤΟΥ + του προσωπικού pref
 * `areas` (που μένει ως εξαίρεση για μεμονωμένες περιπτώσεις).
 * Χωρίς ομάδα και χωρίς pref κρατάμε την ιστορική προεπιλογή, εκτός αν η
 * ρύθμιση `strict_areas` είναι ενεργή — τότε καμία πρόσβαση.
 */
function cnp_admin_areas($adminId, $isFull)
{
    if ($isFull) {
        return cnp_area_keys();
    }
    static $memo = [];
    if (isset($memo[(int) $adminId])) {
        return $memo[(int) $adminId];
    }
    $out = [];
    if (Capsule::schema()->hasColumn('mod_cpm_teams', 'areas')) {
        $rows = Capsule::table('mod_cpm_team_members as m')
            ->join('mod_cpm_teams as t', 't.id', '=', 'm.team_id')
            ->where('m.admin_id', (int) $adminId)->pluck('t.areas')->all();
        foreach ($rows as $raw) {
            foreach (array_filter(array_map('trim', explode(',', (string) $raw))) as $a) {
                $out[] = $a;
            }
        }
    }
    $hasTeam = (bool) $out || Capsule::table('mod_cpm_team_members')
        ->where('admin_id', (int) $adminId)->exists();
    $pref = array_filter(array_map('trim', explode(',', Db::pref($adminId, 'areas', ''))));
    $out = array_values(array_intersect(cnp_perm_keys(), cnp_area_alias(array_merge($out, $pref))));

    if (!$out && !$hasTeam && !$pref) {
        $strict = Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')
            ->where('setting', 'strict_areas')->value('value');
        // Ιστορική προεπιλογή: όλα εκτός Διοίκησης & HR.
        $out = ($strict === 'on') ? [] : ['clients', 'support', 'projects'];
    }
    return $memo[(int) $adminId] = $out;
}

/**
 * Βαθμολογία lead (0-100) με ανάλυση παραγόντων.
 * $l = record lead, $intCount = πλήθος επικοινωνιών, $lastInt = τελευταία επικοινωνία (datetime|null).
 * Επιστρέφει ['score'=>int, 'temp'=>'hot|warm|cold', 'factors'=>[['label','pts','on']...]].
 */
function cnp_lead_score($l, $intCount, $lastInt)
{
    $stageW = ['target' => 5, 'contacted' => 20, 'interested' => 42, 'offer' => 68, 'won' => 100, 'lost' => 0];
    $factors = [];
    $add = function ($label, $pts, $on) use (&$factors) { $factors[] = ['label' => $label, 'pts' => $pts, 'on' => (bool) $on]; };

    $sw = $stageW[$l->stage] ?? 5;
    $add('Στάδιο funnel', $sw, true);
    $score = $sw;

    $hasEmail = trim($l->email ?? '') !== '';
    $hasPhone = trim($l->phone ?? '') !== '';
    $add('Email επαφής', 8, $hasEmail); if ($hasEmail) { $score += 8; }
    $add('Τηλέφωνο επαφής', 8, $hasPhone); if ($hasPhone) { $score += 8; }

    $hasVal = (float) ($l->value ?? 0) > 0;
    $add('Εκτιμώμενη αξία', 10, $hasVal); if ($hasVal) { $score += 10; }

    // πρόσφατη δραστηριότητα
    $recPts = 0; $recLbl = 'Καμία πρόσφατη επαφή';
    if ($lastInt) {
        $days = (time() - strtotime($lastInt)) / 86400;
        if ($days <= 7) { $recPts = 16; $recLbl = 'Επαφή < 7 ημερών'; }
        elseif ($days <= 30) { $recPts = 9; $recLbl = 'Επαφή < 30 ημερών'; }
        else { $recPts = 0; $recLbl = 'Χωρίς πρόσφατη επαφή (>30ημ)'; }
    }
    $add($recLbl, 16, $recPts > 0); $score += $recPts;

    // όγκος επικοινωνίας
    $engPts = min(14, (int) $intCount * 3);
    $add('Εμπλοκή (' . (int) $intCount . ' επικοινωνίες)', 14, $engPts > 0); $score += $engPts;

    // προγραμματισμένη επόμενη ενέργεια
    $hasNext = !empty($l->next_action);
    $add('Προγραμματισμένη ενέργεια', 8, $hasNext); if ($hasNext) { $score += 8; }

    // ποιότητα πηγής
    $src = mb_strtolower(trim($l->source ?? ''));
    $goodSrc = $src !== '' && (strpos($src, 'referr') !== false || strpos($src, 'σύστασ') !== false || strpos($src, 'πελάτ') !== false || strpos($src, 'existing') !== false);
    $add('Ποιοτική πηγή (σύσταση)', 6, $goodSrc); if ($goodSrc) { $score += 6; }

    $score = max(0, min(100, (int) round($score)));
    $temp = $score >= 70 ? 'hot' : ($score >= 40 ? 'warm' : 'cold');
    return ['score' => $score, 'temp' => $temp, 'factors' => $factors];
}

/* ── Θυρίδα κωδικών: κλειδί + AES-256-GCM κρυπτογράφηση ── */
function cnp_vault_key()
{
    static $k = null;
    if ($k !== null) { return $k; }
    $v = Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')->where('setting', 'pm_vault_key')->value('value');
    if (!$v) {
        $v = base64_encode(random_bytes(32));
        Capsule::table('tbladdonmodules')->insert(['module' => 'cloudonprojects', 'setting' => 'pm_vault_key', 'value' => $v]);
    }
    $k = base64_decode($v);
    return $k;
}
function cnp_vault_enc($plain)
{
    $iv = random_bytes(12); $tag = '';
    $ct = openssl_encrypt((string) $plain, 'aes-256-gcm', cnp_vault_key(), OPENSSL_RAW_DATA, $iv, $tag);
    return base64_encode($iv . $tag . $ct);
}
function cnp_vault_dec($blob)
{
    $raw = base64_decode((string) $blob);
    if (strlen($raw) < 28) { return ''; }
    $iv = substr($raw, 0, 12); $tag = substr($raw, 12, 16); $ct = substr($raw, 28);
    $p = openssl_decrypt($ct, 'aes-256-gcm', cnp_vault_key(), OPENSSL_RAW_DATA, $iv, $tag);
    return $p === false ? '' : $p;
}
/** Τύποι εξοπλισμού για τη θυρίδα κωδικών. */
