/** «Πώς και πού θα γίνει», σε μία φράση — ίδια σε οθόνη και σε email. */
function cnp_meeting_how($mode, $place, $location, $clientName = '')
{
    if ($mode === 'video') {
        return ['🎥', 'Βιντεοκλήση', $location];
    }
    if ($mode === 'phone') {
        return ['📞', 'Τηλεφωνικά', $location];
    }
    if ($mode === 'onsite') {
        $p = ['office' => 'Δια ζώσης — στα γραφεία μας',
              'client' => 'Δια ζώσης — στον χώρο του πελάτη' . ($clientName ? ' (' . $clientName . ')' : ''),
              'other' => 'Δια ζώσης'][$place] ?? 'Δια ζώσης';
        return ['📍', $p, $location];
    }
    return ['', '', $location];
}

/** Κατάσταση → 3CX για όλους όσοι έχουν εσωτερικό: στέλνει μόνο ό,τι άλλαξε. Επιστρέφει πόσοι στάλθηκαν. */
function cnp_presence_sweep($now = null)
{
    if (!Pbx3cxPresence::enabled()) { return 0; }
    $n = 0;
    foreach (Pbx3cxPresence::mappedAdmins() as $aid) {
        try {
            $r = Pbx3cxPresence::sync($aid, cnp_presence($aid, $now));
            if ($r && !empty($r['ok']) && empty($r['skip'])) { $n++; }
        } catch (\Throwable $e) { /* ένας χειριστής δεν χαλάει τη σάρωση */ }
    }
    return $n;
}

/** Ένα αίτημα «σε ζητούν» σε μορφή οθόνης — ίδια δομή σε λίστα και σε καρτέλα. */
/**
 * Μία καταγραφή κλήσης, όπως τη διαβάζει η οθόνη.
 *
 * «Ποιος» = πελάτης αν είναι δεμένη, αλλιώς lead, αλλιώς ό,τι όνομα γράφτηκε, αλλιώς ο
 * αριθμός. Ποτέ κενό: μια κλήση χωρίς «ποιος» δεν λέει τίποτα σε όποιον τη διαβάσει αύριο.
 */
function cnp_call_row($r)
{
    $who = '';
    $whoKind = '';
    if (!empty($r->clientid)) { $who = clientLabel((int) $r->clientid); $whoKind = 'client'; }
    elseif (!empty($r->lead_id)) {
        $who = (string) (Capsule::table('mod_cpm_leads')->where('id', (int) $r->lead_id)->value('name') ?: '');
        $whoKind = 'lead';
    }
    /* Το «free» σημαίνει ΕΛΕΥΘΕΡΟ ΟΝΟΜΑ. Δινόταν όμως και όταν το caller ήταν
       κενό, οπότε μια κλήση με σκέτο αριθμό εμφανιζόταν ως «γραμμένο όνομα» —
       και η φόρμα διόρθωσης πρόσφερε τον αριθμό ως όνομα. */
    /* Το caller συχνά κρατά ΤΟΝ ΙΔΙΟ ΤΟΝ ΑΡΙΘΜΟ — έτσι αποθηκεύεται μια κλήση
       από άγνωστο. Δεν είναι όνομα: αν το λέγαμε «γραμμένο όνομα», η φόρμα
       διόρθωσης θα πρότεινε τον αριθμό ως επωνυμία πελάτη. */
    if ($who === '' && trim((string) $r->caller) !== ''
        && !preg_match('/^[\d+\s()\-\.]+$/', trim((string) $r->caller))) {
        $who = trim((string) $r->caller);
        $whoKind = 'free';
    }
    if ($who === '' && trim((string) $r->caller) !== '') {
        $who = trim((string) $r->caller);      // αριθμός στο caller → είναι τηλέφωνο
        $whoKind = 'phone';
    }
    if ($who === '') { $who = (string) ($r->phone ?: 'Άγνωστος'); $whoKind = $whoKind ?: 'phone'; }
    $fup = $r->followup_date ?: null;
    return ['id' => (int) $r->id, 'at' => $r->happened_at,
        'who' => $who, 'whoKind' => $whoKind,
        'clientId' => (int) ($r->clientid ?: 0), 'leadId' => (int) ($r->lead_id ?: 0),
        'phone' => (string) ($r->phone ?: ''), 'dir' => $r->direction ?: 'in',
        'summary' => (string) $r->summary, 'detail' => (string) ($r->detail ?? ''),
        'minutes' => (int) $r->minutes,
        'by' => (int) ($r->admin_id ?: 0), 'byName' => $r->admin_id ? Db::adminName((int) $r->admin_id) : '',
        'task' => (int) ($r->task_id ?: 0), 'ticket' => (int) ($r->ticketid ?: 0),
        'followup' => $fup, 'followupDone' => (int) ($r->followup_done ?: 0) === 1,
        'followupLate' => $fup && !((int) ($r->followup_done ?: 0) === 1) && $fup < date('Y-m-d'),
        'followupNote' => (string) ($r->followup_note ?? '')];
}

function cnp_request_dto($r, $adminId)
{
    $kinds = ['help' => ['🆘', 'Ζητά βοήθεια'], 'checkin' => ['❓', 'Ρωτά τι γίνεται'], 'mention' => ['💬', 'Σε ανέφερε'],
        'offer' => ['📄', 'Ζητά προσφορά'], 'voice' => ['🔊', 'Κλήση στη φωνή']];
    $k = $r->kind ?: 'help';
    $t = $r->task_id ? Db::task((int) $r->task_id) : null;
    return ['id' => (int) $r->id, 'kind' => $k, 'icon' => ($kinds[$k] ?? $kinds['help'])[0], 'kindLbl' => ($kinds[$k] ?? $kinds['help'])[1],
        'fromId' => (int) $r->from_admin, 'from' => Db::adminName((int) $r->from_admin),
        'toId' => (int) $r->to_admin, 'to' => Db::adminName((int) $r->to_admin),
        'mine' => (int) $r->from_admin === $adminId, 'forMe' => (int) $r->to_admin === $adminId,
        'message' => (string) $r->message, 'status' => (string) $r->status,
        'answer' => $r->answer ?: '', 'answerNote' => (string) ($r->answer_note ?? ''),
        'taskId' => $r->task_id ? (int) $r->task_id : 0, 'taskTitle' => $t ? (string) $t->title : '',
        'projectId' => !empty($r->project_id) ? (int) $r->project_id : 0,
        'projectName' => !empty($r->project_id) ? (string) (Capsule::table('mod_cpm_projects')->where('id', (int) $r->project_id)->value('name') ?: '') : '',
        'at' => $r->created_at, 'seen' => !empty($r->seen_at), 'doneAt' => $r->done_at];
}

/** Χρονόμετρα αποσυνδεδεμένων — η λογική ζει στο Db ώστε να τη φτάνει και το cron. */
function cnp_close_ghost_timers($now = null)
{
    return Db::closeGhostTimers($now, CNP_PRESENCE_GONE);
}

/**
 * Η σύσκεψη που τρέχει ΤΩΡΑ για κάποιον — και μόνο εφόσον την έχει αποδεχθεί.
 * Η αποδοχή της πρόσκλησης ΕΙΝΑΙ η χειροκίνητη πράξη· από εκεί και πέρα η
 * κατάσταση αλλάζει μόνη της στην ώρα της και επανέρχεται στη λήξη.
 */
function cnp_meeting_now($adminId, $now = null)
{
    $now = $now ?: time();
    $nowS = date('Y-m-d H:i:s', $now);
    $m = Capsule::table('mod_cpm_events as e')
        ->join('mod_cpm_event_rsvp as r', function ($j) use ($adminId) {
            $j->on('r.event_id', '=', 'e.id')
              ->where('r.kind', '=', 'admin')->where('r.ref', '=', $adminId);
        })
        ->whereIn('e.kind', ['meeting', 'appointment'])
        ->where('e.all_day', 0)
        ->where('r.status', 'accepted')
        ->where('e.attendees', 'like', '%,' . $adminId . ',%')
        ->where('e.start_dt', '<=', $nowS)
        /* Η ΔΙΚΗ ΤΟΥ ώρα λήξης: η παράταση που πήρε ο ίδιος, αλλιώς το πλάνο.
           Και αν έχει ΔΗΛΩΣΕΙ ότι βγήκε, δεν είναι πια σε σύσκεψη — άσχετα με
           το τι κάνουν οι υπόλοιποι στην ίδια αίθουσα. */
        ->whereNull('r.left_at')
        ->whereRaw('COALESCE(r.until_dt, e.end_dt) >= ?', [$nowS])
        ->orderBy('e.start_dt')
        ->first(['e.id', 'e.title', 'e.start_dt', 'e.mode', 'e.scope', 'e.clientid',
                 Capsule::raw('COALESCE(r.until_dt, e.end_dt) as end_dt')]);
    return $m ?: null;
}

/**
 * Η κατάσταση ενός χειριστή τώρα.
 * manual = το δήλωσε ο ίδιος · until = πότε λήγει η δήλωση (0 = μέχρι να την αλλάξει)
 */
function cnp_presence($adminId, $now = null)
{
    $now = $now ?: time();
    $defs = cnp_presence_defs();
    $seen = (int) Db::pref($adminId, 'last_seen', '0');
    $idle = $seen ? max(0, $now - $seen) : null;
    $man = cnp_presence_legacy((string) Db::pref($adminId, 'chat_status', ''));
    $until = (int) Db::pref($adminId, 'chat_until', '0');
    $reason = (string) Db::pref($adminId, 'chat_reason', '');

    /* Έληξε η δήλωση («σε σύσκεψη για μία ώρα») → επιστροφή σε αυτόματο. */
    if ($man !== '' && $until > 0 && $now >= $until) {
        Db::setPref($adminId, 'chat_status', '');
        Db::setPref($adminId, 'chat_reason', '');
        Db::setPref($adminId, 'chat_until', '0');
        Db::setPref($adminId, 'chat_set_at', '0');
        $man = '';
        $reason = '';
        $until = 0;
    }
    if (!isset($defs[$man])) {
        $man = '';
    }

    $manual = $man !== '';
    if ($manual) {
        /* Μοναδική εξαίρεση: «Διαθέσιμος» με κλειστή εφαρμογή πάνω από μισή ώρα
           δεν στέκει — δεν θέλουμε πράσινη κουκκίδα σε άδεια καρέκλα. */
        $status = ($man === 'online' && ($idle === null || $idle >= CNP_PRESENCE_GONE)) ? 'away' : $man;
        $manual = ($status === $man);
    } else {
        $status = ($idle !== null && $idle < CNP_PRESENCE_ONLINE) ? 'online'
            : (($idle !== null && $idle < CNP_PRESENCE_GONE) ? 'away' : 'offline');
    }

    /* Τρέχουσα σύσκεψη που αποδέχτηκε: υπερισχύει και του παλμού και παλιότερης
       δήλωσης. Δεν υπερισχύει όμως δήλωσης που έκανε ΜΕΣΑ στη σύσκεψη — αν
       βγήκε νωρίτερα και το είπε, ισχύει αυτό που είπε. */
    $meeting = null;
    $mt = cnp_meeting_now($adminId, $now);
    if ($mt) {
        $mtStart = strtotime($mt->start_dt);
        $setAt = (int) Db::pref($adminId, 'chat_set_at', '0');
        if (!($manual && $setAt >= $mtStart)) {
            $status = 'meeting';
            $manual = true;                 // αποδέχτηκε την πρόσκληση — δική του πράξη
            $reason = $mt->title;
            $until = strtotime($mt->end_dt);
            $meeting = ['id' => (int) $mt->id, 'title' => $mt->title, 'mode' => $mt->mode,
                'scope' => $mt->scope, 'end' => $mt->end_dt];
        }
    }

    /* Ο λόγος πρέπει ΠΑΝΤΑ να φαίνεται: αν τον δήλωσε, δείξε τον· αν όχι, δείξε
       τουλάχιστον από πότε λείπει, ώστε να ξέρεις τι περιμένεις. */
    $untilTxt = ($manual && $until) ? ('έως ' . date('H:i', $until)) : '';
    $hint = '';
    if ($manual && $reason !== '') {
        $hint = $reason;
    } elseif ($status !== 'online' && $seen) {
        $hint = 'τελευταία κίνηση ' . (date('Y-m-d', $seen) === date('Y-m-d')
            ? date('H:i', $seen) : date('d/m H:i', $seen));
    } elseif ($status !== 'online') {
        $hint = 'δεν έχει μπει ποτέ';
    }

    return ['status' => $status, 'label' => $defs[$status][0], 'color' => $defs[$status][1],
        'manual' => $manual, 'reason' => $manual ? $reason : '', 'until' => $manual ? $until : 0,
        'untilTxt' => $untilTxt, 'hint' => $hint, 'meeting' => $meeting,
        'mute' => $manual ? (bool) $defs[$status][2] : false,
        'idle' => $idle, 'seen' => $seen ? date('Y-m-d H:i:s', $seen) : null];
}

/** Σκορ ομοιότητας δύο συνόλων λέξεων. */
function cnp_overlap(array $a, array $b)
{
    if (!$a || !$b) {
        return 0;
    }
    $n = count(array_intersect($a, $b));
    return $n >= 2 ? $n : ($n === 1 && count($a) <= 4 ? 1 : 0);
}

/**
 * Άρθρα γνώσης που ταιριάζουν σε ένα κείμενο — με ζύγιση σπανιότητας.
 *
 * Το απλό «πόσες κοινές λέξεις» έβγαζε θόρυβο: μια λέξη σαν «data» ή «σύστημα»
 * υπάρχει στα μισά άρθρα και ταίριαζε τα πάντα με τα πάντα («test» → «Λίστα
 * Self Test»). Εδώ κάθε λέξη ζυγίζεται με το πόσο σπάνια είναι στη βάση (IDF):
 * το «rdns» μετράει πολύ, το «σύστημα» σχεδόν καθόλου.
 *
 * Ψάχνει και μέσα στη ΛΥΣΗ, όχι μόνο σε τίτλο/λέξεις-κλειδιά — εκεί κρύβεται
 * το μεγαλύτερο μέρος της γνώσης.
 *
 * Καλύτερα τίποτα παρά λάθος άρθρο: κάτω από το κατώφλι δεν επιστρέφεται τίποτα.
 */
/**
 * Παρόμοια ΛΥΜΕΝΑ αιτήματα — με ζύγιση σπανιότητας (IDF), όπως η τράπεζα λύσεων.
 *
 * Το απλό «πόσες κοινές λέξεις» πρότεινε ό,τι να ’ναι: δύο κοινές λέξεις
 * αρκούσαν για να περάσει ένα παλιό αίτημα, και λέξεις σαν «2026»,
 * «ημερομηνία» ή «σχετικά» υπάρχουν σχεδόν σε κάθε ticket. Έτσι ένα αίτημα
 * για πρόβλημα σε mail server πρότεινε «Αλλαγή συμμετοχής συνταγής».
 *
 * Τώρα κάθε κοινή λέξη μετράει όσο ΣΠΑΝΙΑ είναι μέσα στα ίδια τα αιτήματα:
 * το «2026» σχεδόν καθόλου, ένα νούμερο τηλεφώνου ή το «rdns» πολύ. Κάτω από
 * το κατώφλι δεν προτείνεται τίποτα — λάθος παραπομπή είναι χειρότερη από
 * καμία, γιατί στέλνει τον συνάδελφο να διαβάσει άσχετη λύση.
 *
 * Ο ΙΔΙΟΣ πελάτης παίρνει προβάδισμα (μισή μονάδα), αλλά ΔΕΝ παρακάμπτει το
 * κατώφλι: «το ξαναρώτησε» πρέπει να σημαίνει ότι όντως ρώτησε το ίδιο.
 */
function cnp_similar_tickets($tid, $tk, array $tw0, $limit = 4, $floor = 0.25)
{
    if (!$tw0) {
        return [];
    }
    $cand = [];
    $df = [];
    foreach (Capsule::table('tbltickets')->where('id', '!=', $tid)
        ->where('status', 'Closed')->orderBy('lastreply', 'desc')
        ->limit(300)->get(['id', 'tid', 'title', 'message', 'userid', 'name', 'email', 'lastreply']) as $t9) {
        $w = cnp_words($t9->title . ' ' . mb_substr((string) $t9->message, 0, 400), 60);
        if (!$w) {
            continue;
        }
        $cand[] = ['t' => $t9, 'w' => array_flip($w)];
        foreach ($w as $x) {
            $df[$x] = ($df[$x] ?? 0) + 1;
        }
    }
    if (!$cand) {
        return [];
    }
    /* Το ίδιο το αίτημα μετράει κι αυτό στο πλήθος: αλλιώς οι λέξεις που έχει
       μόνο αυτό θα φαίνονταν «άγνωστες» αντί για μοναδικές. */
    foreach ($tw0 as $w) { $df[$w] = ($df[$w] ?? 0) + 1; }
    $n = count($cand) + 1;

    /* ΛΕΞΕΙΣ ΠΟΥ ΔΕΝ ΜΠΟΡΟΥΝ ΝΑ ΤΑΙΡΙΑΞΟΥΝ ΜΕ ΤΙΠΟΤΑ ΔΕΝ ΜΕΤΡΑΝΕ.
       Ένα αίτημα «rDNS request» είναι γεμάτο hostnames και IP που υπάρχουν
       μόνο σε αυτό. Επειδή είναι σπανιότατα, το IDF τους έδινε τεράστιο βάρος:
       γέμιζαν τον παρονομαστή και έπνιγαν τις πραγματικές κοινές λέξεις, οπότε
       δύο ολόιδια αιτήματα rDNS έβγαιναν ανόμοια. Όποια λέξη εμφανίζεται σε ΕΝΑ
       μόνο αίτημα αγνοείται — δεν μπορεί να αποδείξει ομοιότητα με κανένα. */
    $w2 = function ($w) use ($n, $df) {
        $d = $df[$w] ?? 0;
        if ($d < 2) { return 0.0; }
        $v = log(1 + $n / $d);
        /* Τα σκέτα νούμερα (οκτάδες IP, αριθμοί τιμολογίων, χρονιές) μετράνε
           υποδιπλάσια: σπάνια μεν, αλλά δεν λένε τίποτα για το ΘΕΜΑ. */
        return pow(ctype_digit($w) ? $v * 0.4 : $v, 2);
    };
    /* ΚΑΝΟΝΙΚΟΠΟΙΗΣΗ. Με σκέτο άθροισμα, ένα ΜΕΓΑΛΟ κείμενο μάζευε βαθμούς
       χωρίς να μοιάζει με τίποτα: τα αιτήματα που γράφει η AI ρεσεψιόν (40+
       λέξεις) «ταίριαζαν» με τα πάντα. Τώρα μετράμε ΤΙ ΠΟΣΟΣΤΟ της ουσίας των
       δύο κειμένων είναι κοινό (συνημίτονο) — ανεξάρτητα από το μήκος τους. */
    $mq = 0.0;
    foreach ($tw0 as $w) { $mq += $w2($w); }
    $mq = sqrt(max(1e-9, $mq));
    /* ΚΑΙ ΜΕ EMAIL, ΟΧΙ ΜΟΝΟ ΜΕ ΠΕΛΑΤΗ WHMCS. Τα περισσότερα αιτήματα έρχονται
       με email από αποστολέα που δεν είναι εγγεγραμμένος πελάτης (userid = 0),
       οπότε το «ο ίδιος πελάτης το έχει ξαναρωτήσει» δεν ενεργοποιούνταν ποτέ —
       ούτε καν όταν ο ίδιος άνθρωπος ρωτούσε το ίδιο πράγμα τρίτη φορά. */
    $myMail = mb_strtolower(trim((string) ($tk->email ?? '')));
    $out = [];
    foreach ($cand as $c) {
        $same = $tk->userid
            ? ((int) $c['t']->userid === (int) $tk->userid)
            : ($myMail !== '' && mb_strtolower(trim((string) $c['t']->email)) === $myMail);
        $dot = 0.0;
        $hit = 0;
        foreach ($tw0 as $w) {
            if (isset($c['w'][$w]) && $w2($w) > 0) { $dot += $w2($w); $hit++; }
        }
        /* Μία και μόνη κοινή λέξη δεν είναι ομοιότητα, όσο σπάνια κι αν είναι —
           εκτός αν το αίτημα είναι τόσο σύντομο που δεν έχει άλλες. */
        if ($hit < 2 && count($tw0) > 4) {
            continue;
        }
        $md = 0.0;
        foreach (array_keys($c['w']) as $w) { $md += $w2($w); }
        $sc = $dot / ($mq * sqrt(max(1e-9, $md)));
        /* Ο ίδιος πελάτης κρίνεται πιο χαλαρά — εκεί η επανάληψη έχει νόημα
           ακόμη κι αν το διατύπωσε αλλιώς. Χαλαρότερα, όχι ελεύθερα. */
        if ($sc < ($same ? $floor * 0.75 : $floor)) {
            continue;
        }
        $sol = (string) Capsule::table('tblticketreplies')->where('tid', $c['t']->id)
            ->where('admin', '!=', '')->whereNotNull('admin')->orderBy('id', 'desc')->value('message');
        $out[] = ['id' => (int) $c['t']->id, 'tid' => $c['t']->tid, 'title' => $c['t']->title,
            'client' => $c['t']->userid ? clientLabel($c['t']->userid) : $c['t']->name,
            'same' => $same, 'last' => substr($c['t']->lastreply, 0, 10),
            'solution' => $sol ? mb_substr(trim(preg_replace('/\s+/u', ' ', strip_tags($sol))), 0, 700) : null,
            'score' => round($sc, 3)];
    }
    usort($out, function ($a, $b) {
        return ($b['same'] <=> $a['same']) ?: ($b['score'] <=> $a['score']);
    });
    return array_slice($out, 0, $limit);
}

/* Κατώφλι σε ΠΟΣΟΣΤΟ κάλυψης, όχι σε βαθμούς: μετρήθηκε σε 377 άρθρα ότι το
   σωστό άρθρο βγαίνει πρώτο στο 95% ακόμη και στο 0,35 — άρα το 0,30 κόβει
   θόρυβο χωρίς να χάνει πραγματικά ταιριάσματα. */
function cnp_kb_suggest($text, $limit = 3, $floor = 0.30)
{
    static $idf = null, $docs = null;

    $tw = cnp_words($text, 60);
    if (!$tw) {
        return [];
    }

    if ($docs === null) {
        $docs = [];
        $df = [];
        foreach (Capsule::table('mod_cpm_kb')->get(['id', 'title', 'keywords', 'tags', 'solution']) as $k) {
            // Τίτλος και λέξεις-κλειδιά μετρούν διπλά: εκεί είναι η ουσία του άρθρου.
            $head = cnp_words($k->title . ' ' . $k->keywords . ' ' . $k->tags, 60);
            $body = cnp_words(mb_substr(strip_tags((string) $k->solution), 0, 4000), 120);
            $docs[] = ['id' => (int) $k->id, 'title' => $k->title, 'solution' => $k->solution,
                'head' => array_flip($head), 'body' => array_flip($body)];
            foreach (array_unique(array_merge($head, $body)) as $w) {
                $df[$w] = ($df[$w] ?? 0) + 1;
            }
        }
        $n = max(1, count($docs));
        $idf = [];
        foreach ($df as $w => $c) {
            $idf[$w] = log(1 + $n / $c);   // σπάνια λέξη → μεγάλο βάρος
        }
    }
    if (!$docs) {
        return [];
    }

    /* ΚΑΝΟΝΙΚΟΠΟΙΗΣΗ ΣΤΟ ΜΗΚΟΣ ΤΟΥ ΑΙΤΗΜΑΤΟΣ. Με σκέτο άθροισμα, όσο πιο μακρύ
       το κείμενο τόσο πιο «σχετικό» φαινόταν κάθε άρθρο: τα αιτήματα που γράφει
       η AI ρεσεψιόν (40+ λέξεις) πιάνονταν σε κοινές λέξεις όπως «εκτός»,
       «στοιχεία», «ημερομηνία» και πρότειναν «Tax free» σε βλάβη mail server.
       Τώρα το σκορ λέει ΤΙ ΠΟΣΟΣΤΟ της ουσίας του αιτήματος καλύπτει το άρθρο. */
    $mq = 0.0;
    foreach ($tw as $w) {
        if (!ctype_digit($w)) { $mq += $idf[$w] ?? 0; }
    }
    if ($mq <= 0) {
        return [];
    }

    $out = [];
    foreach ($docs as $d) {
        $sc = 0.0; $hits = []; $headHits = 0;
        foreach ($tw as $w) {
            /* Σκέτα νούμερα δεν είναι γνώση: οι οκτάδες μιας IP (128, 140, 119)
               είναι σπανιότατες, άρα έπαιρναν τεράστιο βάρος και ταίριαζαν
               αίτημα rDNS με άρθρο τιμολογιακής πολιτικής. */
            if (ctype_digit($w)) { continue; }
            $iw = $idf[$w] ?? 0;
            if ($iw <= 0) { continue; }
            if (isset($d['head'][$w]))      { $sc += $iw * 2.0; $hits[] = $w; $headHits++; }
            elseif (isset($d['body'][$w]))  { $sc += $iw * 0.6; $hits[] = $w; }
        }
        $sc /= $mq;
        /* Απαιτούμε τουλάχιστον μία λέξη στον ΤΙΤΛΟ ή στις λέξεις-κλειδιά: μόνο
           με λέξεις από το σώμα, το ταίριασμα είναι σύμπτωση, όχι θέμα. */
        if ($sc >= $floor && count($hits) >= 2 && $headHits >= 1) {
            $out[] = ['id' => $d['id'], 'title' => $d['title'], 'solution' => $d['solution'],
                'score' => round($sc, 3), 'words' => array_slice(array_unique($hits), 0, 6)];
        }
    }
    usort($out, function ($a, $b) { return $b['score'] <=> $a['score']; });
    return array_slice($out, 0, $limit);
}

function taskDto($t, $minsMap = null, $checkMap = null, $attMap = null, $tkNoMap = null)
{
    return [
        'id' => (int) $t->id, 'title' => $t->title, 'status' => (int) $t->status_id,
        'prio' => (int) $t->priority, 'assignee' => $t->assignee ? (int) $t->assignee : null,
        'ball' => $t->action_user ? (int) $t->action_user : null,
        'due' => $t->due_date, 'sched' => $t->schedule_date, 'start' => $t->start_date ?? null,
        /* Από ποιο κανάλι μας ήρθε το αίτημα — και πότε άνοιξε. */
        'source' => isset($t->source) ? (string) $t->source : '',
        'createdAt' => $t->created_at ?? null,
        'startT' => isset($t->start_time) && $t->start_time ? substr($t->start_time, 0, 5) : null,
        'dueT' => isset($t->due_time) && $t->due_time ? substr($t->due_time, 0, 5) : null,
        'type' => $t->type_id ? (int) $t->type_id : null,
        'est' => $t->estimate_minutes ? (int) $t->estimate_minutes : null,
        'ticket' => $t->ticketid ? (int) $t->ticketid : null,
        /* Ο ορατός αριθμός: του WHMCS όταν υπάρχει σύνδεση, αλλιώς ό,τι γράφτηκε
           χειροκίνητα για ticket της παλιάς πλατφόρμας. Ένα πεδίο στην οθόνη. */
        'ticketNo' => $tkNoMap !== null ? ($tkNoMap[(int) $t->id] ?? null) : null,
        'ticketRef' => isset($t->ticket_ref) && $t->ticket_ref !== '' ? (string) $t->ticket_ref : null,
        'dept' => isset($t->dept_id) && $t->dept_id ? (int) $t->dept_id : null,
        'module' => isset($t->module_id) && $t->module_id ? (int) $t->module_id : null,
        'delivery' => !empty($t->is_delivery),
        'isOffer' => !empty($t->is_offer),                       // αφορά προσφορά → προτεραιότητα
        'internal' => !empty($t->internal),                       // εσωτερική διαδικασία / R&D — χωρίς πελάτη
        'offerId' => isset($t->offer_id) && $t->offer_id ? (int) $t->offer_id : null,   // η ΣΥΓΚΕΚΡΙΜΕΝΗ προσφορά
        'offerRef' => isset($t->offer_ref) && $t->offer_ref !== null ? (string) $t->offer_ref : '',   // ο αριθμός που πληκτρολογήθηκε
        'creator' => isset($t->created_by) && $t->created_by ? (int) $t->created_by : null,   // ο επιβλέπων
        'billOk' => !empty($t->billing_ok),
        /* null = αυτόματο (υπάρχει πελάτης → χρεώσιμο)· 0 = δεν χρεώνεται ποτέ· 1 = πάντα. */
        'billDefault' => isset($t->bill_default) && $t->bill_default !== null ? (int) $t->bill_default : null,
        'billOkBy' => isset($t->billing_ok_by) && $t->billing_ok_by ? (int) $t->billing_ok_by : null,
        'billOkAt' => $t->billing_ok_at ?? null,
        'done' => (bool) $t->completed_at,
        'doneAt' => $t->completed_at,
        'doneNote' => $t->completed_note ?? null,
        'doneBy' => isset($t->completed_by) && $t->completed_by ? (int) $t->completed_by : null,
        'mins' => $minsMap !== null ? (int) ($minsMap[(int) $t->id] ?? 0) : null,
        'check' => $checkMap !== null ? ($checkMap[(int) $t->id] ?? null) : null,
        'att' => $attMap !== null ? (int) ($attMap[(int) $t->id] ?? 0) : null,
    ];
}

/**
 * «@Όνομα» μέσα σε κείμενο (ζητούμενο, ενέργεια) → ειδοποίηση στον αναφερόμενο.
 * Αντικαθιστά τα εσωτερικά μηνύματα της εργασίας: γράφεις @Νίκος και ο Νίκος το
 * βλέπει στο dashboard του και στο καμπανάκι (GoodDay-style «πρόσεξέ με»).
 * Ταιριάζει username, όνομα, επώνυμο ή «όνομα επώνυμο», χωρίς τόνους/πεζά.
 * Επιστρέφει τα ids που ειδοποιήθηκαν (ποτέ τον ίδιο τον συντάκτη).
 */
/* Παράθυρο αυτο-διόρθωσης: πόση ώρα μετά το άνοιγμα μπορεί ο δημιουργός να
   σβήσει μια εργασία που άνοιξε κατά λάθος. */
if (!defined('CNP_TASK_DEL_WINDOW')) { define('CNP_TASK_DEL_WINDOW', 3600); }

/**
 * Ποιος επιτρέπεται να διαγράψει μια εργασία.
 *
 * Οι διαχειριστές πάντα. Ο δημιουργός ΜΟΝΟ μέσα στο παράθυρο: η διαγραφή
 * υπάρχει για το «την άνοιξα κατά λάθος», όχι για να εξαφανίζεται δουλειά που
 * έχει ήδη χρόνο, σχόλια και ιστορικό άλλων ανθρώπων.
 *
 * @return array{0:bool,1:string,2:int} [επιτρέπεται, αιτία/μήνυμα, δευτερόλεπτα που απομένουν]
 */
function cnp_task_delete_right($t, $adminId, $isFull)
{
    if ($isFull) {
        return [true, 'admin', 0];
    }
    if ((int) $t->created_by !== (int) $adminId) {
        return [false, 'Μόνο ο διαχειριστής ή αυτός που άνοιξε την εργασία μπορεί να τη διαγράψει.', 0];
    }
    $born = strtotime((string) $t->created_at);
    $left = $born ? CNP_TASK_DEL_WINDOW - (time() - $born) : 0;
    if ($left <= 0) {
        return [false, 'Πέρασε η ώρα μέσα στην οποία μπορούσες να τη διαγράψεις — ζήτα από διαχειριστή.', 0];
    }
    return [true, 'owner', (int) $left];
}

/**
 * Ποιος δίνει την έγκριση χρέωσης χρόνου.
 *
 * Είναι ΕΝΑ συγκεκριμένο πρόσωπο, όχι «το λογιστήριο» και όχι όποιος τυχαίνει
 * να είναι διαχειριστής: η χρέωση προς τον πελάτη θέλει έναν υπεύθυνο. Το
 * ποιος ορίζεται σε ρύθμιση (mod_cpm_prefs, admin_id=0) ώστε να αλλάζει χωρίς
 * κώδικα.
 *
 * @return int admin id, ή 0 αν δεν έχει οριστεί / ο ορισμένος δεν είναι πια ενεργός
 */
function cnp_billing_approver()
{
    static $memo = null;
    if ($memo !== null) {
        return $memo;
    }
    $id = (int) Capsule::table('mod_cpm_prefs')->where('admin_id', 0)
        ->where('pref', 'billing_approver')->value('value');
    if ($id) {
        $live = Capsule::table('tbladmins')->where('id', $id)->where('disabled', 0)->exists();
        if (!$live) { $id = 0; }   // έφυγε/απενεργοποιήθηκε → μη κλειδώσει η έγκριση
    }
    return $memo = $id;
}

/**
 * Επιτρέπεται σε αυτόν τον χρήστη να εγκρίνει χρέωση;
 *
 * Αν έχει οριστεί εγκρίνων, είναι ΜΟΝΟ αυτός — ούτε οι υπόλοιποι διαχειριστές.
 * Αν δεν έχει οριστεί (ή ο ορισμένος δεν υπάρχει πια), πέφτουμε πίσω στους
 * διαχειριστές, ώστε να μη μείνουν εργασίες κλειδωμένες για πάντα.
 */
function cnp_can_approve_billing($adminId, $isFull)
{
    $ap = cnp_billing_approver();
    return $ap ? ((int) $adminId === $ap) : (bool) $isFull;
}

/**
 * «Αυτή η εργασία περιμένει έγκριση χρέωσης» — φτάνει στον εγκρίνοντα αμέσως.
 *
 * Καλείται σε κάθε σημείο που δημιουργείται ή ξεκλειδώνει χρεώσιμος χρόνος.
 * Στέλνει ΚΑΙ in-app ειδοποίηση (που ανάβει και το pop-up) ΚΑΙ email, γιατί ο
 * σκοπός είναι να μην περιμένει η εργασία: μπορεί να μην είναι στην εφαρμογή.
 *
 * Δεν ξαναστέλνει για την ίδια εργασία μέσα σε 6 ώρες — αλλιώς κάθε καταχώρηση
 * χρόνου θα γινόταν χωριστό email.
 */
/**
 * Τύποι εργασίας που ΔΕΝ χρεώνονται ποτέ.
 * Ένα bug είναι δικό μας λάθος· δεν το πληρώνει ο πελάτης, άρα δεν έχει νόημα
 * ούτε χρεώσιμος χρόνος ούτε έγκριση χρέωσης. Κρατιέται με βάση το ΟΝΟΜΑ του
 * τύπου, ώστε να μη σπάσει αν αλλάξουν τα ids.
 */
function cnp_nonbillable_type($typeId)
{
    static $ids = null;
    if ($ids === null) {
        $ids = [];
        foreach (Capsule::table('mod_cpm_task_types')->get(['id', 'name']) as $ty) {
            if (preg_match('/bug|σφάλμα/iu', (string) $ty->name)) {
                $ids[] = (int) $ty->id;
            }
        }
    }
    return $typeId && in_array((int) $typeId, $ids, true);
}
/** Επιτρέπεται καθόλου χρέωση σε αυτή την εργασία; */
function cnp_task_billable_ok($t)
{
    return $t && !cnp_nonbillable_type($t->type_id ?? 0);
}

function cnp_billing_request($t, $byAdminId)
{
    if (!$t || !empty($t->billing_ok) || !cnp_task_billable_ok($t)) {
        return;
    }
    $mins = (int) Capsule::table('mod_cpm_timelogs')->where('task_id', $t->id)
        ->where('billable', 1)->where('running', 0)->sum('minutes');
    if ($mins <= 0) {
        return;
    }
    $url = '/project/#/task/' . (int) $t->id;
    $targets = cnp_billing_approver() ? [cnp_billing_approver()] : cnp_full_admin_ids();
    $recent = Capsule::table('mod_cpm_notifications')->where('type', 'billreq')->where('url', $url)
        ->where('created_at', '>', date('Y-m-d H:i:s', time() - 6 * 3600))->exists();
    if ($recent) {
        return;
    }
    $who = Db::adminName($byAdminId);
    $hrs = $mins >= 60 ? round($mins / 60, 1) . 'ω' : $mins . chr(39);
    $title = mb_substr((string) $t->title, 0, 90);
    foreach ($targets as $aid) {
        if ((int) $aid === (int) $byAdminId) {
            continue;                       // κατέγραψε τον χρόνο η ίδια → δεν αυτο-ειδοποιείται
        }
        Db::pushNotification($aid, 'billreq',
            mb_substr('Εκκρεμεί έγκριση χρέωσης: ' . $hrs . ' στην «' . $title . '»', 0, 240), $url);
        /* sendTo, ΟΧΙ send: το send σέβεται τον καθολικό διακόπτη email του
           module, που είναι κλειστός. Αυτή η ειδοποίηση είναι λειτουργική —
           χωρίς την έγκριση η εργασία δεν κλείνει — οπότε πρέπει να φεύγει. */
        try {
            $to9 = Notify::adminEmail($aid);
            if ($to9) { Notify::sendTo($to9, 'Εκκρεμεί έγκριση χρέωσης — ' . $title,
                '<p><b>' . htmlspecialchars($hrs, ENT_QUOTES, 'UTF-8') . ' χρεώσιμος χρόνος</b> περιμένει την έγκρισή σου.</p>'
                . '<p>Εργασία: <b>' . htmlspecialchars($title, ENT_QUOTES, 'UTF-8') . '</b> (#' . (int) $t->id . ')<br>'
                . 'Καταχωρήθηκε από: ' . htmlspecialchars($who, ENT_QUOTES, 'UTF-8') . '</p>'
                . '<p>Η εργασία <b>δεν κλείνει</b> πριν εγκριθεί η χρέωση.</p>'
                . '<p><a href="' . htmlspecialchars(Notify::baseUrl() . $url, ENT_QUOTES, 'UTF-8')
                . '" style="background:#0090dd;color:#fff;padding:9px 16px;border-radius:8px;text-decoration:none;display:inline-block">Άνοιγμα εργασίας</a></p>'); }
        } catch (\Throwable $e) { /* αποτυχία email δεν χαλάει την καταχώρηση χρόνου */ }
    }
}

/**
 * Καταγράφει και ανακοινώνει τη μετάθεση ενός έργου.
 *
 * «Αναπρογραμματισμός» = άλλαξε η έναρξη ή η παράδοση υπάρχοντος έργου. Δεν
 * μετράει το να μπει ημερομηνία εκεί που δεν υπήρχε καμία (αυτό είναι
 * συμπλήρωση, όχι μετάθεση) — αλλιώς κάθε έργο θα ανακοινωνόταν μια φορά
 * χωρίς λόγο.
 *
 * Ειδοποιούνται ο υπεύθυνος του έργου και οι διαχειριστές: η μετάθεση
 * παράδοσης είναι απόφαση που αφορά και άλλους, όχι εσωτερική λεπτομέρεια.
 */
function cnp_log_reschedule($before, array $after, $adminId, $reason = '')
{
    $oldS = $before->start_date ?: null;
    $oldD = $before->due_date ?: null;
    $newS = $after['start_date'] ?? null;
    $newD = $after['due_date'] ?? null;

    /* Μετάθεση = άλλαξε ημερομηνία που ΥΠΗΡΧΕ. Δύο περιπτώσεις:
         - μετακινήθηκε   → καταγράφεται με «πόσες ημέρες»
         - ΑΦΑΙΡΕΘΗΚΕ     → καταγράφεται κι αυτό· το να σβήσεις την προθεσμία
                             είναι μεγαλύτερη αλλαγή από το να τη μετακινήσεις,
                             και χωρίς αυτό θα ήταν τρόπος να την παρακάμψεις.
       Το να ΜΠΕΙ ημερομηνία εκεί που δεν υπήρχε καμία δεν είναι μετάθεση. */
    $moved   = function ($old, $new) { return $old && $new && $old !== $new; };
    $cleared = function ($old, $new) { return $old && !$new; };
    $sMoved = $moved($oldS, $newS);
    $dMoved = $moved($oldD, $newD);
    $sGone  = $cleared($oldS, $newS);
    $dGone  = $cleared($oldD, $newD);
    if (!$sMoved && !$dMoved && !$sGone && !$dGone) {
        return;
    }

    /* Θετικό = πήγε πίσω (αργότερα). Σε αφαίρεση δεν υπάρχει «πόσο». */
    $days = $dMoved ? (int) round((strtotime($newD) - strtotime($oldD)) / 86400)
        : ($sMoved ? (int) round((strtotime($newS) - strtotime($oldS)) / 86400) : 0);

    Capsule::table('mod_cpm_reschedules')->insert([
        'project_id' => (int) $before->id, 'admin_id' => (int) $adminId,
        'old_start' => $oldS, 'new_start' => $newS,
        'old_due' => $oldD, 'new_due' => $newD,
        'days' => $days, 'reason' => mb_substr($reason, 0, 500) ?: null,
        'created_at' => date('Y-m-d H:i:s'),
    ]);

    $who = Db::adminName($adminId);
    $dir = $days > 0 ? 'πίσω' : 'μπροστά';
    if ($dGone) {
        $what = 'ΑΦΑΙΡΕΘΗΚΕ η προθεσμία παράδοσης (ήταν ' . cnp_dgr($oldD) . ')';
    } elseif ($sGone) {
        $what = 'ΑΦΑΙΡΕΘΗΚΕ η ημερομηνία έναρξης (ήταν ' . cnp_dgr($oldS) . ')';
    } elseif ($dMoved) {
        $what = 'παράδοση ' . cnp_dgr($oldD) . ' → ' . cnp_dgr($newD) . ' (' . abs($days) . ' ημ. ' . $dir . ')';
    } else {
        $what = 'έναρξη ' . cnp_dgr($oldS) . ' → ' . cnp_dgr($newS) . ' (' . abs($days) . ' ημ. ' . $dir . ')';
    }
    $msg = 'Αναπρογραμματισμός «' . mb_substr((string) $before->name, 0, 70) . '»: ' . $what . ' — ' . $who;
    $url = '/project/#/board/' . (int) $before->id;

    /* Υπεύθυνος έργου + διαχειριστές, χωρίς διπλοεγγραφή και χωρίς αυτο-ειδοποίηση. */
    $targets = cnp_full_admin_ids();
    if (!empty($before->manager_id)) { $targets[] = (int) $before->manager_id; }
    foreach (array_unique($targets) as $aid) {
        if ((int) $aid === (int) $adminId) { continue; }
        Db::pushNotification($aid, 'resched', mb_substr($msg, 0, 240), $url);
        try {
            $to9 = Notify::adminEmail($aid);
            if ($to9) {
                Notify::sendTo($to9, 'Αναπρογραμματισμός έργου — ' . mb_substr((string) $before->name, 0, 70),
                    '<p><b>' . htmlspecialchars((string) $before->name, ENT_QUOTES, 'UTF-8') . '</b></p>'
                    . '<p>' . htmlspecialchars($what, ENT_QUOTES, 'UTF-8') . '</p>'
                    . ($reason ? '<p>Αιτιολογία: <i>' . htmlspecialchars($reason, ENT_QUOTES, 'UTF-8') . '</i></p>' : '')
                    . '<p>Από: ' . htmlspecialchars($who, ENT_QUOTES, 'UTF-8') . '</p>'
                    . '<p><a href="' . htmlspecialchars(Notify::baseUrl() . $url, ENT_QUOTES, 'UTF-8')
                    . '" style="background:#0090dd;color:#fff;padding:9px 16px;border-radius:8px;text-decoration:none;display:inline-block">Άνοιγμα έργου</a></p>');
            }
        } catch (\Throwable $e) { /* το email δεν εμποδίζει την αποθήκευση */ }
    }
    logActivity('CloudOn PM: ' . $msg);
}

/** Ημερομηνία σε ελληνική μορφή για μηνύματα. */
function cnp_dgr($d)
{
    return $d ? date('d/m/Y', strtotime($d)) : '—';
}

/** Οι ομάδες στις οποίες αυτός ο χρήστης είναι επικεφαλής (mod_cpm_team_members.is_leader). */
function cnp_led_teams($adminId)
{
    if (!Capsule::schema()->hasTable('mod_cpm_team_members')) {
        return [];
    }
    return array_map('intval', Capsule::table('mod_cpm_team_members')
        ->where('admin_id', (int) $adminId)->where('is_leader', 1)->pluck('team_id')->all());
}

/**
 * Ποιους ανθρώπους επιτρέπεται να «βλέπει» κάποιος ως παρουσία/απόδοση.
 *
 * Ένας κανόνας, μία πηγή: Full και ομάδα κλιμάκωσης (Manager) βλέπουν όλους·
 * ο ΕΠΙΚΕΦΑΛΗΣ ομάδας βλέπει τη δική του ομάδα· μέλος της ομάδας project
 * management βλέπει τις ομάδες όπου ανήκει. Όποιος δεν πατάει σε τίποτε από
 * αυτά, δεν βλέπει κανέναν — και η κάρτα δεν εμφανίζεται καν.
 *
 * @return array{all:bool,ids:?int[],label:string}  ids===null σημαίνει «όλοι».
 */
function cnp_team_scope($adminId, $isFull)
{
    $adminId = (int) $adminId;
    if ($isFull || in_array($adminId, DayPlan::escalateTo(), true)) {
        return ['all' => true, 'ids' => null, 'label' => ''];
    }
    $teams = cnp_led_teams($adminId);
    if (in_array($adminId, DayPlan::owners(), true)) {
        $teams = array_values(array_unique(array_merge($teams, array_map('intval',
            Capsule::table('mod_cpm_team_members')->where('admin_id', $adminId)->pluck('team_id')->all()))));
    }
    if (!$teams) {
        return ['all' => false, 'ids' => [], 'label' => ''];
    }
    $ids = array_map('intval', Capsule::table('mod_cpm_team_members')
        ->whereIn('team_id', $teams)->pluck('admin_id')->all());
    $ids[] = $adminId;
    return ['all' => false, 'ids' => array_values(array_unique($ids)),
        'label' => implode(' · ', array_map('strval', Capsule::table('mod_cpm_teams')
            ->whereIn('id', $teams)->orderBy('name')->pluck('name')->all()))];
}

/**
 * Πόση ώρα ήταν συνδεδεμένος κάποιος σήμερα, και από πότε.
 *
 * Το tbladminlog κρατά μία γραμμή ανά συνεδρία (logintime → logouttime/lastvisit).
 * Αθροίζουμε ΜΟΝΟ το κομμάτι που πέφτει μέσα στη σημερινή ημέρα, ώστε μια
 * συνεδρία που ξεκίνησε χθες το βράδυ να μη χρεώνει δεκάξι ώρες στο σήμερα.
 *
 * @return array<string,array{mins:int,since:?string,until:?string}> κλειδί = username πεζά
 */
function cnp_conn_today()
{
    $out = [];
    $day0 = strtotime(date('Y-m-d') . ' 00:00:00');
    $now = time();
    try {
        foreach (Capsule::table('tbladminlog')
            ->where(function ($q) use ($day0) {
                $q->where('logintime', '>=', date('Y-m-d H:i:s', $day0))
                  ->orWhere('lastvisit', '>=', date('Y-m-d H:i:s', $day0))
                  ->orWhere('logouttime', '>=', date('Y-m-d H:i:s', $day0));
            })->get(['adminusername', 'logintime', 'logouttime', 'lastvisit']) as $r) {
            $u = strtolower(trim((string) $r->adminusername));
            if ($u === '') { continue; }
            $a = $r->logintime ? strtotime($r->logintime) : 0;
            $b = max($r->logouttime ? strtotime($r->logouttime) : 0, $r->lastvisit ? strtotime($r->lastvisit) : 0, $a);
            if (!$a) { continue; }
            $a = max($a, $day0);
            $b = min(max($b, $a), $now);
            if (!isset($out[$u])) { $out[$u] = ['mins' => 0, 'since' => null, 'until' => null]; }
            $out[$u]['mins'] += (int) round(($b - $a) / 60);
            if ($out[$u]['since'] === null || $a < strtotime($out[$u]['since'])) { $out[$u]['since'] = date('Y-m-d H:i:s', $a); }
            if ($out[$u]['until'] === null || $b > strtotime($out[$u]['until'])) { $out[$u]['until'] = date('Y-m-d H:i:s', $b); }
        }
    } catch (\Throwable $e) { }
    return $out;
}

/**
 * Το παράθυρο παρουσίας κάποιου ΣΗΜΕΡΑ: από πότε είναι μέσα και πόση ώρα.
 *
 * Δύο πηγές, γιατί καμία δεν αρκεί μόνη της: ο σφυγμός της εφαρμογής (pref
 * seen_first → last_seen) ξέρει πότε ήταν πραγματικά μπροστά στην οθόνη, αλλά
 * ξεκινά από τη μέρα που μπήκε ο κώδικας· το tbladminlog ξέρει τα logins αλλά
 * το lastvisit του δεν ενημερώνεται πάντα. Κρατάμε το μεγαλύτερο διάστημα.
 *
 * @return array{mins:int,since:?string,last:?string}
 */
function cnp_seen_span($adminId, $username = '', array $logCache = [])
{
    $day = date('Y-m-d');
    $since = null; $last = null; $mins = 0;
    $ls = (int) Db::pref((int) $adminId, 'last_seen', '0');
    if ($ls && date('Y-m-d', $ls) === $day) { $last = $ls; }
    $fs = (string) Db::pref((int) $adminId, 'seen_first', '');
    if (strpos($fs, $day . '|') === 0) {
        $since = (int) substr($fs, strlen($day) + 1);
        if ($last !== null && $last >= $since) { $mins = (int) round(($last - $since) / 60); }
    }
    $lg = $logCache[strtolower(trim((string) $username))] ?? null;
    if ($lg) {
        if ((int) $lg['mins'] > $mins) { $mins = (int) $lg['mins']; }
        $ls2 = $lg['since'] ? strtotime($lg['since']) : 0;
        if ($ls2 && ($since === null || $ls2 < $since)) { $since = $ls2; }
        $lu2 = $lg['until'] ? strtotime($lg['until']) : 0;
        if ($lu2 && ($last === null || $lu2 > $last)) { $last = $lu2; }
    }
    if ($since !== null && $last !== null && $mins < (int) round(($last - $since) / 60)) {
        $mins = (int) round(($last - $since) / 60);
    }
    return ['mins' => max(0, $mins),
        'since' => $since ? date('Y-m-d H:i:s', $since) : null,
        'last' => $last ? date('Y-m-d H:i:s', $last) : null];
}

/** Τα μέλη μιας ομάδας (admin ids), μαζί με τον επικεφαλής. */
function cnp_team_members($teamId)
{
    return array_map('intval', Capsule::table('mod_cpm_team_members')
        ->where('team_id', (int) $teamId)->pluck('admin_id')->all());
}

/**
 * Ανάθεση σε ΑΛΛΟΝ χωρίς χρόνο υλοποίησης δεν επιτρέπεται.
 *
 * Κρατάς όσες πρόχειρες θέλεις στον ΕΑΥΤΟ σου — εκεί η εργασία περιμένει να
 * σχεδιαστεί και κανείς δεν την περιμένει. Τη στιγμή που τη δίνεις σε άλλον,
 * πρέπει να ξέρει πότε ξεκινά και πότε τελειώνει· αλλιώς του φορτώνεις κάτι
 * που δεν μπορεί να προγραμματίσει.
 *
 * (Ο ρόλος στο WHMCS δεν χρησιμεύει εδώ: οι πραγματικοί υπεύθυνοι της ομάδας
 *  είναι «agents», οπότε κριτήριο είναι η ιδιοκτησία, όχι το δικαίωμα.)
 *
 * @return bool true αν χρειάζονται ημερομηνίες
 */
function cnp_assignee_needs_dates($newAssignee, $actorId)
{
    if (!$newAssignee) {
        return false;                       // «κανείς» = δεν έχει ανατεθεί
    }
    return (int) $newAssignee !== (int) $actorId;
}

/**
 * Είναι ελεύθερος αυτός ο άνθρωπος σε αυτό το διάστημα;
 *
 * Επιστρέφει τις ΑΝΟΙΧΤΕΣ εργασίες του που επικαλύπτονται χρονικά. Χωρίς ώρα,
 * η εργασία πιάνει ΟΛΗ την ημέρα — αυτή είναι η ειλικρινής ανάγνωση: αν κανείς
 * δεν δήλωσε ώρες, δεν ξέρουμε ότι χωράει κι άλλο.
 *
 * Δύο διαστήματα συγκρούονται όταν το ένα ξεκινά πριν τελειώσει το άλλο.
 */
function cnp_busy_conflicts($adminId, $start, $startT, $due, $dueT, $exceptTask = 0)
{
    if (!$adminId || !$start || !$due) {
        return [];
    }
    $a1 = $start . ' ' . ($startT ?: '00:00:00');
    $a2 = $due . ' ' . ($dueT ?: '23:59:59');
    $doneIds = Capsule::table('mod_cpm_statuses')->where('is_done', 1)->pluck('id')->all() ?: [0];

    $rows = Capsule::table('mod_cpm_tasks as t')
        ->leftJoin('mod_cpm_projects as p', 'p.id', '=', 't.project_id')
        ->where('t.assignee', (int) $adminId)
        ->whereNotIn('t.status_id', $doneIds)
        ->where('t.id', '<>', (int) $exceptTask)
        ->whereNotNull('t.start_date')->whereNotNull('t.due_date')
        /* Προ-φιλτράρισμα στις ημέρες· η ακριβής σύγκριση με ώρες γίνεται από κάτω. */
        ->where('t.start_date', '<=', $due)->where('t.due_date', '>=', $start)
        ->orderBy('t.start_date')->limit(30)
        ->get(['t.id', 't.title', 't.start_date', 't.start_time', 't.due_date', 't.due_time',
            'p.name as pname']);

    $hits = [];
    foreach ($rows as $r) {
        $b1 = $r->start_date . ' ' . ($r->start_time ?: '00:00:00');
        $b2 = $r->due_date . ' ' . ($r->due_time ?: '23:59:59');
        if ($a1 <= $b2 && $b1 <= $a2) {
            $hits[] = ['id' => (int) $r->id, 'title' => $r->title,
                'project' => $r->pname ? cnp_pn($r->pname) : '',
                'start' => $r->start_date, 'startT' => $r->start_time ? substr($r->start_time, 0, 5) : null,
                'due' => $r->due_date, 'dueT' => $r->due_time ? substr($r->due_time, 0, 5) : null];
        }
    }
    return $hits;
}

/**
 * Επιτρέπεται να δει ΠΟΣΑ χρωστάει ο πελάτης;
 *
 * Το «έχει ή δεν έχει οφειλή» το χρειάζεται ο χειριστής για να παραπέμψει στο
 * λογιστήριο. Το ΠΟΣΟ είναι οικονομικό στοιχείο και δίνεται μόνο σε όποιον έχει
 * ρητά «Οικονομικά → Ανοιχτά υπόλοιπα» (οι διαχειριστές το έχουν εξ ορισμού).
 */
function cnp_can_see_balances($adminId, $isFull)
{
    return cnp_has_cap($adminId, $isFull, 'finance.balances');
}

/** Η στήλη «αναμονής» — η πρώτη μη-τελική κατάσταση (Backlog). */
/**
 * Σημαίνει αυτή η κατάσταση «τελείωσα τη δουλειά πάνω της»;
 * Ναι για κάθε ολοκληρωμένη, και για ό,τι είναι ΜΕΤΑ το στάδιο εκτέλεσης.
 * Όχι για Backlog και για το ίδιο το «σε εξέλιξη» — εκεί η δουλειά ξεκινά.
 */
function cnp_status_ends_work($statusId)
{
    /* 20/09/2026: το λέει ρητά η ΦΑΣΗ της κατάστασης (after/done/cancel), όχι η σειρά της. */
    return Db::statusEndsWork((int) $statusId);
}

function cnp_backlog_status_id()
{
    static $id = null;
    if ($id === null) {
        $id = (int) Capsule::table('mod_cpm_statuses')->where('is_done', 0)
            ->orderBy('sort')->orderBy('id')->value('id');
    }
