        'followup_date' => preg_match('/^\d{4}-\d{2}-\d{2}$/', $in['followup'] ?? '') ? $in['followup'] : null,
        'followup_note' => mb_substr(trim($in['followupNote'] ?? ''), 0, 200) ?: null]);
    out(['ok' => true]);

case 'complaints':
    $st9 = (string) ($_GET['status'] ?? 'live');       // live = ανοιχτά + σε χειρισμό
    $q9 = Capsule::table('mod_cpm_complaints');
    if ($st9 === 'live') { $q9->whereIn('status', ['open', 'progress']); }
    elseif (in_array($st9, ['open', 'progress', 'resolved', 'rejected'], true)) { $q9->where('status', $st9); }
    if (!empty($_GET['client'])) { $q9->where('clientid', (int) $_GET['client']); }
    if (!empty($_GET['cat'])) { $q9->where('category', (string) $_GET['cat']); }
    if (!empty($_GET['mine'])) { $q9->where('owner_id', $adminId); }
    $rows9 = [];
    foreach ($q9->orderByRaw("FIELD(status,'open','progress','resolved','rejected')")
        ->orderBy('severity', 'desc')->orderBy('id', 'desc')->limit(300)->get() as $r9) {
        $rows9[] = cnp_cx_row($r9);
    }
    /* Σύνοψη: όχι μόνο πόσα, αλλά τι επαναλαμβάνεται και πόσο αργούμε. */
    $all9 = Capsule::table('mod_cpm_complaints');
    $openN = (int) (clone $all9)->whereIn('status', ['open', 'progress'])->count();
    $critN = (int) (clone $all9)->whereIn('status', ['open', 'progress'])->where('severity', 3)->count();
    $mon9 = date('Y-m-01') . ' 00:00:00';
    $newN = (int) (clone $all9)->where('created_at', '>=', $mon9)->count();
    $days = [];
    foreach ((clone $all9)->whereNotNull('resolved_at')->where('resolved_at', '>=', date('Y-m-d', strtotime('-90 days')))
        ->get(['created_at', 'resolved_at']) as $r9) {
        $days[] = max(0, (strtotime($r9->resolved_at) - strtotime($r9->created_at)) / 86400);
    }
    $byCat = [];
    foreach ((clone $all9)->where('created_at', '>=', date('Y-m-d', strtotime('-180 days')))
        ->select(Capsule::raw('category, COUNT(*) n'))->groupBy('category')->orderByRaw('n DESC')->get() as $r9) {
        $byCat[] = ['id' => $r9->category, 'name' => cnp_cx_cats()[$r9->category][0] ?? $r9->category,
            'color' => cnp_cx_cats()[$r9->category][1] ?? '#8595ac', 'n' => (int) $r9->n];
    }
    $worst = [];
    foreach ((clone $all9)->whereNotNull('clientid')->where('created_at', '>=', date('Y-m-d', strtotime('-180 days')))
        ->select(Capsule::raw('clientid, COUNT(*) n'))->groupBy('clientid')
        ->havingRaw('COUNT(*) > 1')->orderByRaw('n DESC')->limit(5)->get() as $r9) {
        $worst[] = ['client' => (int) $r9->clientid, 'name' => clientLabel((int) $r9->clientid), 'n' => (int) $r9->n];
    }
    out(['rows' => $rows9, 'cats' => array_map(function ($k, $v) {
            return ['id' => $k, 'name' => $v[0], 'color' => $v[1]];
        }, array_keys(cnp_cx_cats()), cnp_cx_cats()),
        'sources' => cnp_cx_sources(),
        'canClose' => cnp_has_cap($adminId, $FULL, 'support.complaints.edit'),
        'admins' => array_map(function ($a) { return ['id' => (int) $a->id,
            'name' => trim($a->firstname . ' ' . $a->lastname)]; }, Db::admins()->all()),
        'summary' => ['open' => $openN, 'critical' => $critN, 'month' => $newN,
            'resolved' => (int) (clone $all9)->where('status', 'resolved')->count(),
            'rejected' => (int) (clone $all9)->where('status', 'rejected')->count(),
            'total' => (int) (clone $all9)->count(),
            'avgDays' => $days ? round(array_sum($days) / count($days), 1) : null,
            'byCat' => $byCat, 'repeat' => $worst]]);

case 'complaint':
    $cxid = (int) ($_GET['id'] ?? $in['id'] ?? 0);
    $cx9 = Capsule::table('mod_cpm_complaints')->where('id', $cxid)->first();
    if (!$cx9) { fail('notfound', 404); }
    $notes9 = [];
    foreach (Capsule::table('mod_cpm_complaint_notes')->where('complaint_id', $cxid)
        ->orderBy('id')->get() as $n9) {
        $notes9[] = ['at' => $n9->created_at, 'kind' => $n9->kind, 'body' => $n9->body,
            'who' => $n9->admin_id ? Db::adminName($n9->admin_id) : 'Σύστημα'];
    }
    out(['cx' => cnp_cx_row($cx9) + ['detail' => $cx9->detail, 'resolution' => $cx9->resolution,
            'cause' => $cx9->cause, 'lead' => (int) $cx9->lead_id, 'project' => (int) $cx9->project_id],
        'notes' => $notes9,
        'canClose' => cnp_has_cap($adminId, $FULL, 'support.complaints.edit')]);

case 'complaint_save':
    $cxid = (int) ($in['id'] ?? 0);
    $sum9 = mb_substr(trim((string) ($in['summary'] ?? '')), 0, 255);
    if ($sum9 === '') { fail('Γράψε σε μία γραμμή το παράπονο'); }
    $cid9 = (int) ($in['client'] ?? 0) ?: null;
    if ($cid9 && !Capsule::table('tblclients')->where('id', $cid9)->exists()) { $cid9 = null; }
    $row9 = [
        'clientid' => $cid9, 'lead_id' => (int) ($in['lead'] ?? 0) ?: null,
        'contact' => mb_substr(trim((string) ($in['contact'] ?? '')), 0, 120) ?: null,
        'category' => array_key_exists((string) ($in['category'] ?? ''), cnp_cx_cats()) ? $in['category'] : 'other',
        'severity' => min(3, max(1, (int) ($in['severity'] ?? 2))),
        'summary' => $sum9,
        'detail' => mb_substr(trim((string) ($in['detail'] ?? '')), 0, 8000) ?: null,
        'source' => array_key_exists((string) ($in['source'] ?? ''), cnp_cx_sources()) ? $in['source'] : 'call',
        'ticketid' => (int) ($in['ticket'] ?? 0) ?: null,
        'project_id' => (int) ($in['project'] ?? 0) ?: null,
        'updated_at' => date('Y-m-d H:i:s'),
    ];
    if ($cxid) {
        Capsule::table('mod_cpm_complaints')->where('id', $cxid)->update($row9);
        Db::cxNote($cxid, $adminId, 'note', 'Ενημέρωση στοιχείων');
    } else {
        $row9['owner_id'] = (int) ($in['owner'] ?? 0) ?: null;
        $row9['status'] = 'open';
        $row9['created_by'] = $adminId;
        $row9['created_at'] = date('Y-m-d H:i:s');
        $cxid = (int) Capsule::table('mod_cpm_complaints')->insertGetId($row9);
        Db::cxNote($cxid, $adminId, 'note', 'Καταχωρήθηκε');
        /* Κρίσιμο παράπονο δεν περιμένει να το δει κάποιος στη λίστα. */
        if ($row9['severity'] === 3) {
            foreach (cnp_cx_watchers($adminId) as $w9) {
                Db::pushNotification($w9, 'complaint',
                    '⚠ Κρίσιμο παράπονο: ' . mb_substr($sum9, 0, 90),
                    'addonmodules.php?module=cloudonprojects&pmlaunch=1#/complaints');
            }
        }
        if ($row9['owner_id'] && $row9['owner_id'] !== $adminId) {
            Db::pushNotification($row9['owner_id'], 'complaint',
                'Σου ανατέθηκε παράπονο: ' . mb_substr($sum9, 0, 90),
                'addonmodules.php?module=cloudonprojects&pmlaunch=1#/complaints');
        }
    }
    out(['ok' => true, 'id' => $cxid]);

case 'complaint_status':                 // ανάθεση, κατάσταση, «ενημερώθηκε ο πελάτης»
    $cxid = (int) ($in['id'] ?? 0);
    $cx9 = Capsule::table('mod_cpm_complaints')->where('id', $cxid)->first();
    if (!$cx9) { fail('notfound', 404); }
    $upd9 = ['updated_at' => date('Y-m-d H:i:s')];
    if (array_key_exists('owner', $in)) {
        $ow9 = (int) $in['owner'] ?: null;
        $upd9['owner_id'] = $ow9;
        Db::cxNote($cxid, $adminId, 'assign', $ow9 ? 'Ανατέθηκε σε ' . Db::adminName($ow9) : 'Αφαιρέθηκε η ανάθεση');
        if ($ow9 && $ow9 !== $adminId) {
            Db::pushNotification($ow9, 'complaint', 'Σου ανατέθηκε παράπονο: ' . mb_substr($cx9->summary, 0, 90),
                'addonmodules.php?module=cloudonprojects&pmlaunch=1#/complaints');
        }
    }
    if (array_key_exists('informed', $in)) {
        $upd9['informed'] = !empty($in['informed']) ? 1 : 0;
        Db::cxNote($cxid, $adminId, 'informed',
            $upd9['informed'] ? 'Ενημερώθηκε ο πελάτης' : 'Αναιρέθηκε η ενημέρωση πελάτη');
    }
    if (!empty($in['status']) && in_array($in['status'], ['open', 'progress'], true)) {
        $upd9['status'] = $in['status'];
        $upd9['resolved_at'] = null;
        $upd9['resolved_by'] = null;
        Db::cxNote($cxid, $adminId, 'status', 'Κατάσταση: ' . (cnp_cx_status()[$in['status']][0] ?? $in['status']));
    }
    Capsule::table('mod_cpm_complaints')->where('id', $cxid)->update($upd9);
    out(['ok' => true]);

case 'complaint_resolve':                // κλείσιμο με έκβαση — χωριστό δικαίωμα
    $cxid = (int) ($in['id'] ?? 0);
    $cx9 = Capsule::table('mod_cpm_complaints')->where('id', $cxid)->first();
    if (!$cx9) { fail('notfound', 404); }
    $how9 = ($in['status'] ?? 'resolved') === 'rejected' ? 'rejected' : 'resolved';
    $res9 = mb_substr(trim((string) ($in['resolution'] ?? '')), 0, 4000);
    if ($res9 === '') { fail('Γράψε τι έγινε — χωρίς έκβαση το παράπονο δεν κλείνει'); }
    Capsule::table('mod_cpm_complaints')->where('id', $cxid)->update([
        'status' => $how9, 'resolution' => $res9,
        'cause' => mb_substr(trim((string) ($in['cause'] ?? '')), 0, 120) ?: null,
        'resolved_by' => $adminId, 'resolved_at' => date('Y-m-d H:i:s'),
        'informed' => !empty($in['informed']) ? 1 : (int) $cx9->informed,
        'updated_at' => date('Y-m-d H:i:s')]);
    Db::cxNote($cxid, $adminId, 'resolve',
        ($how9 === 'rejected' ? 'Κρίθηκε αβάσιμο' : 'Λύθηκε') . ': ' . $res9);
    if ((int) $cx9->created_by && (int) $cx9->created_by !== $adminId) {
        Db::pushNotification((int) $cx9->created_by, 'complaint',
            'Έκλεισε το παράπονο που κατέγραψες: ' . mb_substr($cx9->summary, 0, 80),
            'addonmodules.php?module=cloudonprojects&pmlaunch=1#/complaints');
    }
    out(['ok' => true]);

case 'complaint_note':
    $cxid = (int) ($in['id'] ?? 0);
    $b9 = mb_substr(trim((string) ($in['body'] ?? '')), 0, 4000);
    if (!$cxid || $b9 === '') { fail('input'); }
    if (!Capsule::table('mod_cpm_complaints')->where('id', $cxid)->exists()) { fail('notfound', 404); }
    Db::cxNote($cxid, $adminId, 'note', $b9);
    Capsule::table('mod_cpm_complaints')->where('id', $cxid)
        ->update(['updated_at' => date('Y-m-d H:i:s')]);
    out(['ok' => true]);


/* ================= ΚΑΤΑΓΡΑΦΗ ΚΛΗΣΗΣ =================
   Χτύπησε το τηλέφωνο, το κλείνεις, και σε δεκαπέντε δευτερόλεπτα μένει γραπτό
   ποιος πήρε, τι ζήτησε, και τι γίνεται με αυτό. Δεν φτιάχνεται νέο μητρώο:
   γράφει στις `mod_cpm_interactions`, εκεί που ζουν όλες οι επικοινωνίες. */


case 'call_who':                         // ποιος καλεί: πελάτης ή lead, με όνομα ή αριθμό
    $q9 = trim((string) ($_GET['q'] ?? ''));
    $res9 = [];
    if (mb_strlen($q9) >= 3) {
        $dig = cnp_phone_norm($q9);
        $like = '%' . $q9 . '%';
        /* Ο αριθμός είναι το κλειδί: όταν χτυπά το τηλέφωνο, αυτό έχεις. */
        /* Τα τηλέφωνα είναι αποθηκευμένα μορφοποιημένα («+30.21 2102 2756»),
           οπότε η σύγκριση γίνεται σε σκέτα ψηφία και στις δύο πλευρές. */
        $bare9 = "REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(phonenumber,' ',''),'.',''),'-',''),'(',''),')',''),'+','')";
        if (strlen($dig) >= 6) {
            foreach (Capsule::table('tblclients')->whereRaw($bare9 . ' LIKE ?', ['%' . $dig . '%'])
                ->limit(6)->get(['id', 'firstname', 'lastname', 'companyname', 'phonenumber']) as $c9) {
                $res9[] = ['type' => 'client', 'id' => (int) $c9->id,
                    'name' => $c9->companyname ?: trim($c9->firstname . ' ' . $c9->lastname),
                    'phone' => $c9->phonenumber, 'why' => 'τηλέφωνο'];
            }
        }
        foreach (Capsule::table('tblclients')->where(function ($w) use ($like) {
            $w->where('companyname', 'like', $like)->orWhere('firstname', 'like', $like)
              ->orWhere('lastname', 'like', $like)->orWhere('email', 'like', $like);
        })->limit(8)->get(['id', 'firstname', 'lastname', 'companyname', 'phonenumber']) as $c9) {
            $res9[] = ['type' => 'client', 'id' => (int) $c9->id,
                'name' => $c9->companyname ?: trim($c9->firstname . ' ' . $c9->lastname),
                'phone' => $c9->phonenumber, 'why' => 'όνομα'];
        }
        if (Capsule::schema()->hasTable('mod_cpm_leads')) {
            foreach (Capsule::table('mod_cpm_leads')->where(function ($w) use ($like, $dig) {
                $w->where('company', 'like', $like)->orWhere('email', 'like', $like);
                if (strlen($dig) >= 6) {
                    $w->orWhereRaw("REPLACE(REPLACE(REPLACE(phone,' ',''),'.',''),'-','') LIKE ?", ['%' . $dig . '%']);
                }
            })->limit(5)->get(['id', 'company', 'phone']) as $l9) {
                $res9[] = ['type' => 'lead', 'id' => (int) $l9->id, 'name' => $l9->company,
                    'phone' => $l9->phone, 'why' => 'lead'];
            }
        }
        /* Διπλότυπα: ο ίδιος πελάτης μπορεί να βρέθηκε και από αριθμό και από όνομα. */
        $seen9 = [];
        $res9 = array_values(array_filter($res9, function ($r) use (&$seen9) {
            $k = $r['type'] . $r['id'];
            if (isset($seen9[$k])) { return false; }
            $seen9[$k] = 1;
            return true;
        }));
    }
    out(['results' => array_slice($res9, 0, 10)]);

case 'calllog':                          /* ☎ Καταγραφές κλήσεων — τι μας ζήτησαν και τι απαντήσαμε.
      ΜΟΝΟ χειροκίνητες καταγραφές (mod_cpm_interactions kind=call). Τα CDR του 3CX ζουν
      στη «Τηλεφωνική δραστηριότητα»: άλλο πράγμα «χτύπησε το τηλέφωνο», άλλο «να τι είπαμε». */
    $fromC = (string) ($_GET['from'] ?? date('Y-m-d', strtotime('-30 days')));
    $toC = (string) ($_GET['to'] ?? date('Y-m-d'));
    $qC = trim((string) ($_GET['q'] ?? ''));
    $whoC = (int) ($_GET['admin'] ?? 0);
    $cliC = (int) ($_GET['client'] ?? 0);
    $viewC = in_array($_GET['view'] ?? 'all', ['all', 'followup', 'loose', 'mine'], true) ? $_GET['view'] : 'all';

    $baseC = function () use ($fromC, $toC) {
        return Capsule::table('mod_cpm_interactions')->where('kind', 'call')
            ->where('happened_at', '>=', $fromC . ' 00:00:00')->where('happened_at', '<=', $toC . ' 23:59:59');
    };
    $qq = $baseC();
    if ($whoC) { $qq->where('admin_id', $whoC); }
    if ($cliC) { $qq->where('clientid', $cliC); }
    if ($viewC === 'mine') { $qq->where('admin_id', $adminId); }
    if ($viewC === 'followup') { $qq->whereNotNull('followup_date')->where('followup_done', 0); }
    /* «Ξεκρέμαστες» = καμία συνέχεια πουθενά. Αυτές χάνονται, γι' αυτό έχουν δικό τους φίλτρο. */
    if ($viewC === 'loose') {
        $qq->where(function ($w) { $w->whereNull('task_id')->orWhere('task_id', 0); })
           ->where(function ($w) { $w->whereNull('ticketid')->orWhere('ticketid', 0); })
           ->where(function ($w) { $w->whereNull('followup_date')->orWhere('followup_done', 1); });
    }
    if ($qC !== '') {
        $qq->where(function ($w) use ($qC) {
            $w->where('summary', 'like', '%' . $qC . '%')->orWhere('detail', 'like', '%' . $qC . '%')
              ->orWhere('caller', 'like', '%' . $qC . '%')->orWhere('phone', 'like', '%' . $qC . '%');
        });
    }
    $rowsC = [];
    foreach ($qq->orderByDesc('happened_at')->limit(400)->get() as $r) {
        $rowsC[] = cnp_call_row($r);
    }
    /* Τα νούμερα μετριούνται στο ΙΔΙΟ διάστημα με τη λίστα, αλλιώς δεν δένουν με τις γραμμές. */
    $totC = (int) $baseC()->count();
    $minsC = (int) $baseC()->sum('minutes');
    $fupC = (int) $baseC()->whereNotNull('followup_date')->where('followup_done', 0)->count();
    $looseC = (int) $baseC()
        ->where(function ($w) { $w->whereNull('task_id')->orWhere('task_id', 0); })
        ->where(function ($w) { $w->whereNull('ticketid')->orWhere('ticketid', 0); })
        ->where(function ($w) { $w->whereNull('followup_date')->orWhere('followup_done', 1); })->count();
    $mineC = (int) $baseC()->where('admin_id', $adminId)->count();
    $byWho = [];
    foreach ($baseC()->selectRaw('admin_id, COUNT(*) n, SUM(minutes) m')->groupBy('admin_id')->get() as $w) {
        if (!$w->admin_id) { continue; }
        $byWho[] = ['id' => (int) $w->admin_id, 'name' => Db::adminName((int) $w->admin_id),
            'n' => (int) $w->n, 'mins' => (int) $w->m];
    }
    usort($byWho, function ($a, $b) { return $b['n'] <=> $a['n']; });
    out(['rows' => $rowsC, 'from' => $fromC, 'to' => $toC, 'view' => $viewC,
        'counts' => ['total' => $totC, 'mins' => $minsC, 'followup' => $fupC, 'loose' => $looseC, 'mine' => $mineC],
        'byWho' => $byWho,
        'canEdit' => cnp_has_cap($adminId, $FULL, 'support.calllog.edit')]);

case 'calllog_save':                     /* Διόρθωση καταγραφής: περίληψη, χρόνος, follow-up. */
    $idC = (int) ($in['id'] ?? 0);
    $rowC = Capsule::table('mod_cpm_interactions')->where('id', $idC)->where('kind', 'call')->first();
    if (!$rowC) { fail('Δεν βρέθηκε η καταγραφή', 404); }
    /* Τη δική σου τη διορθώνεις πάντα· αλλουνού μόνο με ρητό δικαίωμα. */
    if ((int) $rowC->admin_id !== $adminId && !cnp_has_cap($adminId, $FULL, 'support.calllog.edit')) {
        fail('Η καταγραφή είναι άλλου — χρειάζεται «Καταγραφές κλήσεων: επεξεργασία»', 403);
    }
    $updC = [];
    if (isset($in['summary'])) {
        $sumC = trim(preg_replace('/[\x{10000}-\x{10FFFF}]/u', '', (string) $in['summary']));
        if ($sumC === '') { fail('Η περίληψη δεν μπορεί να μείνει κενή'); }
        $updC['summary'] = mb_substr($sumC, 0, 255);
    }
    if (isset($in['detail'])) { $updC['detail'] = mb_substr(trim(preg_replace('/[\x{10000}-\x{10FFFF}]/u', '', (string) $in['detail'])), 0, 4000); }
    if (isset($in['minutes'])) { $updC['minutes'] = max(0, min(600, (int) $in['minutes'])); }
    if (array_key_exists('followup_date', $in)) {
        $fd = trim((string) $in['followup_date']);
        $updC['followup_date'] = $fd !== '' ? substr($fd, 0, 10) : null;
        if ($fd === '') { $updC['followup_done'] = 0; }
    }
    if (isset($in['followup_done'])) { $updC['followup_done'] = !empty($in['followup_done']) ? 1 : 0; }

    /* ΠΟΙΟΣ ΗΤΑΝ. Οι καταγραφές που γίνονται πάνω στην ώρα κρατούν μόνο τον
       αριθμό — κανείς δεν σταματά να ψάξει πελάτη ενώ μιλάει. Χωρίς τρόπο να
       συμπληρωθεί μετά, η κλήση μένει για πάντα «+30694…» και δεν προσμετράται
       στο ιστορικό του πελάτη. */
    if (array_key_exists('clientid', $in)) {
        $cidC = (int) $in['clientid'];
        if ($cidC && !Capsule::table('tblclients')->where('id', $cidC)->exists()) { fail('Άγνωστος πελάτης'); }
        $updC['clientid'] = $cidC ?: null;
        if ($cidC) { $updC['caller'] = null; }   // ο πελάτης υπερισχύει του ελεύθερου ονόματος
    }
    if (array_key_exists('caller', $in)) {
        $updC['caller'] = mb_substr(trim((string) $in['caller']), 0, 120) ?: null;
    }
    if (array_key_exists('phone', $in)) {
        $phC = preg_replace('/[^0-9+]/', '', (string) $in['phone']);
        $updC['phone'] = mb_substr($phC, 0, 32) ?: null;
    }

    if (!$updC) { fail('Τίποτα να αλλάξει'); }
    Capsule::table('mod_cpm_interactions')->where('id', $idC)->update($updC);
    out(['ok' => true, 'row' => cnp_call_row(Capsule::table('mod_cpm_interactions')->where('id', $idC)->first())]);

case 'call_recent':                      // οι τελευταίες μου κλήσεις — για τη λίστα «σήμερα»
    $rows9 = [];
    foreach (Capsule::table('mod_cpm_interactions')->where('kind', 'call')
        ->where('admin_id', $adminId)->orderBy('id', 'desc')->limit(15)->get() as $r9) {
        $rows9[] = ['id' => (int) $r9->id, 'at' => $r9->happened_at,
            'who' => $r9->clientid ? clientLabel((int) $r9->clientid) : ($r9->caller ?: 'Άγνωστος'),
            'phone' => $r9->phone, 'dir' => $r9->direction ?: 'in',
            'summary' => $r9->summary, 'minutes' => (int) $r9->minutes,
            'task' => (int) $r9->task_id, 'ticket' => (int) $r9->ticketid,
            'followup' => $r9->followup_date];
    }
    out(['rows' => $rows9]);

case 'cancels':
    /* ΑΚΥΡΩΣΕΙΣ ΥΠΗΡΕΣΙΩΝ — τι έκλεισε και αν έκλεισε ΣΩΣΤΑ.
       ΔΕΝ διαχειριζόμαστε υπηρεσίες από εδώ (αυτό ζει στο cloudonadminpanel):
       εδώ είναι μόνο η επιβεβαίωση ότι ο κύκλος έκλεισε — ή η ειδοποίηση ότι δεν.

       ΚΑΤΟΝΟΜΑΖΟΥΜΕ, ΔΕΝ ΑΘΡΟΙΖΟΥΜΕ. «Καμία εκκρεμότητα» δεν επιβεβαιώνει
       τίποτα: για να ξέρεις ότι οι τρεις σημερινές έκλεισαν σωστά, πρέπει να
       δεις τις τρεις. Ημερομηνία ακύρωσης = termination_date, η μέρα που
       ίσχυσε — όχι η μέρα που το ζήτησε ο πελάτης. */
    $cnDays = max(1, min(90, (int) ($_GET['days'] ?? $in['days'] ?? 7)));
    $cnHasVm = Capsule::schema()->hasTable('mod_hetzner_instances');
    $cnToday = date('Y-m-d');

    $cnBase = function () use ($cnHasVm) {
        $q = Capsule::table('tblhosting as h')
            ->leftJoin('tblproducts as p', 'p.id', '=', 'h.packageid')
            ->leftJoin('tblcancelrequests as cr', 'cr.relid', '=', 'h.id');
        if ($cnHasVm) {
            $q->leftJoin('mod_hetzner_instances as hi', 'hi.service_id', '=', 'h.id')
              ->addSelect('hi.server_id', 'hi.project_id');
        }
        return $q->addSelect('h.id as srv', 'h.domainstatus', 'h.userid', 'h.termination_date',
            'cr.id as crid', 'cr.date as crdate', 'cr.type', 'cr.reason', 'p.name as proion');
    };

    /* Η κατάσταση ΚΑΘΕ ακύρωσης, με όνομα και ετυμηγορία. */
    $cnState = ['stale' => 0];
    $cnSeen = [];   // η ίδια υπηρεσία περνά από δύο λίστες — μετράμε ΜΙΑ φορά
    $cnRow = function ($r) use ($cnHasVm, &$cnState, &$cnSeen) {
        $srvId = $cnHasVm ? (int) ($r->server_id ?: 0) : 0;
        if ($srvId) {
            $vm = cnp_vm_alive($srvId, $r->project_id);
            /* Το μηχάνημα έφυγε αλλά η εγγραφή σύνδεσης έμεινε: ο κύκλος
               ΕΚΛΕΙΣΕ σωστά, απλώς θέλει νοικοκύρεμα στα αρχεία μας. */
            if ($vm === 'gone' && empty($cnSeen[$srvId])) {
                $cnState['stale']++;
                $cnSeen[$srvId] = true;
            }
        } else {
            $vm = 'none';     // δεν ήταν VM — δεν υπάρχει τίποτα να σβηστεί
        }
        $ok = ($vm === 'gone' || $vm === 'none');
        return [
            'service' => (int) $r->srv, 'status' => (string) $r->domainstatus,
            'at' => $r->termination_date,
            'product' => (string) $r->proion,
            'clientId' => (int) $r->userid, 'client' => clientLabel((int) $r->userid),
            'asked' => (bool) $r->crid, 'askedAt' => $r->crdate,
            /* ΤΙ ΖΗΤΗΣΕ Ο ΠΕΛΑΤΗΣ. Το WHMCS κρατά δύο είδη και η διαφορά
               μετράει: «άμεση» σημαίνει ότι έπρεπε να κοπεί τότε, «στη λήξη»
               ότι δικαιούται να τη χρησιμοποιεί ως το τέλος της περιόδου. */
            'type' => (string) $r->type,
            'typeLbl' => $r->type === 'Immediate' ? 'άμεση ακύρωση'
                : ($r->type === 'End of Billing Period' ? 'στη λήξη της συνδρομής'
                : (string) $r->type),
            'reason' => mb_substr(trim((string) $r->reason), 0, 120),
            'vm' => $srvId, 'vmState' => $vm,
            'ok' => $ok,
            /* Το «none» σημαίνει «δεν εκκρεμεί μηχάνημα» — ΟΧΙ «δεν υπήρξε ποτέ».
               Όταν ο server σβηστεί σωστά, φεύγει και η αντιστοίχιση, οπότε δεν
               ξέρουμε πια αν η υπηρεσία είχε VM. Και δεν έχει σημασία: αυτό που
               ρωτάμε είναι αν έμεινε κάτι πίσω. */
            'note' => $vm === 'live' ? 'το μηχάνημα τρέχει ακόμη'
                : ($vm === 'unknown' ? 'δεν απάντησε η Hetzner — δεν ελέγχθηκε'
                : ($vm === 'gone' ? 'το μηχάνημα σβήστηκε' : 'δεν εκκρεμεί μηχάνημα')),
        ];
    };

    $cnPick = function ($from, $to) use ($cnBase, $cnRow) {
        $out = [];
        foreach ($cnBase()->whereIn('h.domainstatus', ['Cancelled', 'Terminated'])
            ->whereNotNull('h.termination_date')
            ->where('h.termination_date', '>=', $from)
            ->where('h.termination_date', '<=', $to)
            ->orderBy('h.termination_date', 'desc')->orderBy('h.id', 'desc')
            ->limit(40)->get() as $r) { $out[] = $cnRow($r); }
        return $out;
    };

    /* ΣΗΜΕΡΑ. Αν δεν έγινε καμία, δείχνουμε τις τελευταίες ημέρες — ώστε το
       μπλοκ να μη λέει ποτέ «τίποτα» χωρίς να δείχνει τι έκλεισε τελευταία. */
    $cnRowsToday = $cnPick($cnToday, $cnToday);
    $cnRecent = $cnRowsToday ? [] : $cnPick(date('Y-m-d', strtotime('-' . $cnDays . ' days')), $cnToday);

    /* ΑΝΟΙΧΤΑ: το ζήτησε ο πελάτης, η υπηρεσία τρέχει ακόμη. */
    $cnOpen = [];
    foreach ($cnBase()->whereIn('h.domainstatus', ['Active', 'Suspended'])
        ->whereNotNull('cr.id')->orderBy('cr.date', 'desc')->get() as $r) {
        $cnOpen[] = $cnRow($r);
    }

    /* ΠΡΟΒΛΗΜΑΤΑ ΠΑΝΤΟΥ, όχι μόνο σήμερα: ένα μηχάνημα που ξεχάστηκε πριν έναν
       μήνα κοστίζει κάθε μέρα. Αυτά ανεβαίνουν πάντα στην κορυφή. */
    $cnBad = [];
    if ($cnHasVm) {
        foreach ($cnBase()->whereIn('h.domainstatus', ['Cancelled', 'Terminated'])
            ->whereNotNull('hi.server_id')->orderBy('h.id', 'desc')->get() as $r) {
            $row = $cnRow($r);
            if ($row['vmState'] === 'live' || $row['vmState'] === 'unknown') { $cnBad[] = $row; }
        }
    }

    out(['ok' => true, 'days' => $cnDays, 'today' => $cnRowsToday, 'recent' => $cnRecent,
         'open' => $cnOpen, 'bad' => $cnBad, 'stale' => $cnState['stale'], 'vmAware' => $cnHasVm]);

case 'calls_pending':
    /* ΟΙ ΔΙΚΕΣ ΣΟΥ ΚΛΗΣΕΙΣ ΠΟΥ ΔΕΝ ΕΧΟΥΝ ΧΑΡΑΚΤΗΡΙΣΤΕΙ.
       Ο χρόνος ομιλίας μετριέται μόνος του και μετράει στη μέρα σου έτσι κι
       αλλιώς. Ο χαρακτηρισμός δεν τον προσθέτει — τον ΕΞΗΓΕΙ: χωρίς αυτόν
       ξέρουμε ότι μίλησες δύο ώρες, δεν ξέρουμε σε τι. */
    $cpDays = max(1, min(30, (int) ($_GET['days'] ?? $in['days'] ?? 7)));
    $cpFrom = date('Y-m-d 00:00:00', strtotime('-' . $cpDays . ' days'));
    /* Ποτέ πριν από την έναρξη του κυκλώματος — δες cnp_calls_label_from(). */
    $cpStart = cnp_calls_label_from() . ' 00:00:00';
    if ($cpFrom < $cpStart) { $cpFrom = $cpStart; }
    $cpQ = Capsule::table('mod_cpm_calls')->where('admin_id', $adminId)
        ->where('talk_seconds', '>', 0)
        ->whereNull('logged_at')
        ->where('started_at', '>=', $cpFrom);
    $cpTot = (clone $cpQ)->count();
    $cpMin = (int) round(((int) (clone $cpQ)->sum('talk_seconds')) / 60);
    $cpRows = $cpQ->orderBy('started_at', 'desc')->limit(60)->get();
    $cpBook = cnp_book_names(array_column($cpRows->all(), 'other_e164'));
    $cpOut = [];
    foreach ($cpRows as $c) {
        $cpOut[] = [
            'id' => (int) $c->id, 'at' => $c->started_at, 'dir' => $c->direction,
            'mins' => (int) round(((int) $c->talk_seconds) / 60),
            'secs' => (int) $c->talk_seconds,
            'other' => $c->other_e164 ?: ($c->direction === 'out' ? (string) $c->to_no : (string) $c->from_no),
            'client' => $c->clientid ? (int) $c->clientid : 0,
            'who' => $c->clientid ? clientLabel((int) $c->clientid)
                : ($cpBook[$c->other_e164] ?? ''),
            /* Εσωτερική: και οι δύο πλευρές είναι εσωτερικά (2–4 ψηφία). Τις
               ξεχωρίζουμε γιατί χαρακτηρίζονται μαζικά με ένα κλικ. */
            'internal' => (bool) (preg_match('/^\d{2,4}$/', (string) $c->from_dn)
                && preg_match('/^\d{2,4}$/', (string) $c->to_dn)),
        ];
    }
    out(['ok' => true, 'rows' => $cpOut, 'total' => $cpTot, 'mins' => $cpMin,
         'days' => $cpDays, 'kinds' => cnp_call_kinds()]);

case 'calls_label':
    /* ΧΑΡΑΚΤΗΡΙΣΜΟΣ, με δυνατότητα ΠΟΛΛΩΝ ΜΑΖΙ. Με διακόσιες κλήσεις την
       εβδομάδα, μία φόρμα ανά κλήση δεν συμπληρώνεται ποτέ — και μια
       υποχρέωση που δεν τηρείται είναι χειρότερη από καμία. */
    $clIds = array_slice(array_values(array_unique(array_map('intval',
        (array) ($in['ids'] ?? [])))), 0, 50);
    $clIds = array_values(array_filter($clIds));
    if (!$clIds) { fail('Δεν διάλεξες κλήση'); }
    $clKind = isset(cnp_call_kinds()[$in['kind'] ?? '']) ? (string) $in['kind'] : '';
    if (!$clKind) { fail('Πες τι ήταν'); }
    $clSum = mb_substr(trim(preg_replace('/[\x{10000}-\x{10FFFF}]/u', '',
        (string) ($in['summary'] ?? ''))), 0, 255);

    $clUpd = ['category' => $clKind, 'logged_by' => $adminId, 'logged_at' => date('Y-m-d H:i:s')];
    if ($clSum !== '') { $clUpd['summary'] = $clSum; }
    if (array_key_exists('task', $in)) {
        $clT = (int) $in['task'];
        $clUpd['task_id'] = $clT ?: null;
        /* Το έργο προκύπτει από την εργασία — δεν το ζητάμε δεύτερη φορά. */
        if ($clT) {
            $clTk = Db::task($clT);
            if ($clTk) { $clUpd['project_id'] = $clTk->project_id ? (int) $clTk->project_id : null; }
        }
    }
    if (array_key_exists('project', $in) && !isset($clUpd['project_id'])) {
        $clUpd['project_id'] = (int) $in['project'] ?: null;
    }
    if (array_key_exists('client', $in)) {
        $clC = (int) $in['client'];
        if ($clC && Capsule::table('tblclients')->where('id', $clC)->exists()) { $clUpd['clientid'] = $clC; }
    }
    /* ΜΟΝΟ δικές σου κλήσεις: ο χαρακτηρισμός είναι δήλωση για τη δική σου ώρα. */
    $clN = Capsule::table('mod_cpm_calls')->whereIn('id', $clIds)
        ->where('admin_id', $adminId)->update($clUpd);
    out(['ok' => true, 'n' => (int) $clN]);

case 'my_calls_open':                    // ΟΙ ΔΙΚΕΣ ΣΟΥ κλήσεις που δεν έχουν καταγραφεί
    /* Χωρίς αυτό, η «Καταγραφή κλήσης» ζητούσε να ξαναγράψεις ό,τι ήδη ξέρει το
       τηλεφωνικό κέντρο: ποιον πήρες, πότε, πόση ώρα. Εδώ τα φέρνουμε έτοιμα —
       ο συνάδελφος γράφει μόνο ΤΙ έγινε. */
    $mcFrom = date('Y-m-d 00:00:00', strtotime('-' . max(1, min(14, (int) ($_GET['days'] ?? 3))) . ' days'));
    $mcOut = [];
    $mcRows = Capsule::table('mod_cpm_calls')->where('admin_id', $adminId)
        ->where('started_at', '>=', $mcFrom)->whereNull('logged_at')
        ->orderBy('started_at', 'desc')->limit(15)->get();
    $mcBook = cnp_book_names(array_column($mcRows->all(), 'other_e164'));
    foreach ($mcRows as $mc) {
        $mcOut[] = [
            'id' => (int) $mc->id, 'at' => $mc->started_at, 'dir' => $mc->direction,
            'talk' => (int) $mc->talk_seconds, 'answered' => (bool) $mc->answered,
            'handled' => (string) $mc->handled,
            'client' => $mc->clientid ? (int) $mc->clientid : 0,
            'clientName' => $mc->clientid ? clientLabel((int) $mc->clientid) : '',
            'other' => $mc->other_e164 ?: ($mc->direction === 'out' ? (string) $mc->to_no : (string) $mc->from_no),
            'book' => $mc->clientid ? '' : ($mcBook[$mc->other_e164] ?? ''),
            'bookId' => $mc->book_id ? (int) $mc->book_id : 0,
            'anon' => $mc->client_match === 'anon'];
    }
    out(['items' => $mcOut]);

case 'call_log':                         // η καταχώρηση
    $sum9 = mb_substr(trim((string) ($in['summary'] ?? '')), 0, 255);
    if ($sum9 === '') { fail('Γράψε τι ζήτησε ο καλών'); }
    $cid9 = (int) ($in['client'] ?? 0) ?: null;
    $lid9 = (int) ($in['lead'] ?? 0) ?: null;
    if ($cid9 && !Capsule::table('tblclients')->where('id', $cid9)->exists()) { $cid9 = null; }
    $mins9 = max(0, min(600, (int) ($in['minutes'] ?? 0)));
    $dir9 = ($in['direction'] ?? 'in') === 'out' ? 'out' : 'in';
    $caller9 = mb_substr(trim((string) ($in['caller'] ?? '')), 0, 120) ?: null;
    $phone9 = mb_substr(trim((string) ($in['phone'] ?? '')), 0, 40) ?: null;
    $detail9 = mb_substr(trim((string) ($in['detail'] ?? '')), 0, 4000) ?: null;
    $fup9 = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string) ($in['followup'] ?? '')) ? $in['followup'] : null;

    /* ── τι βγαίνει από την κλήση ── */
    $taskId9 = 0;
    $tkId9 = 0;
    $want9 = (string) ($in['then'] ?? 'none');   // none | task | ticket
    if ($want9 === 'task') {
        if (!cnp_has_cap($adminId, $FULL, 'projects.board')) {
            fail('Δεν έχεις δικαίωμα δημιουργίας εργασίας', 403);
        }
        $pid9 = (int) ($in['project'] ?? 0) ?: null;
        $asg9 = (int) ($in['assignee'] ?? 0) ?: $adminId;
        $taskId9 = (int) Db::saveTask(0, [
            'project_id' => $pid9,
            'title' => mb_substr(($caller9 || $cid9 ? '☎ ' : '☎ ') . $sum9, 0, 200),
            'descr' => cnp_clean_html(nl2br(trim(($phone9 ? 'Τηλέφωνο: ' . $phone9 . "\n" : '')
                . ($detail9 ?: '')))) ?: null,
            'assignee' => $asg9,
            'action_user' => null,          // η μπάλα μένει κενή στη δημιουργία (ίδιος κανόνας παντού)
            'due_date' => $fup9,
            'created_by' => $adminId,
        ], $adminId);
        if ($taskId9 && $asg9 !== $adminId) { Notify::assigned($taskId9, $asg9, $adminId); }
    } elseif ($want9 === 'ticket') {
        if (!cnp_has_cap($adminId, $FULL, 'support.tickets')) {
            fail('Δεν έχεις δικαίωμα δημιουργίας ticket', 403);
        }
        if (!$cid9) { fail('Για ticket χρειάζεται πελάτης'); }
        $dept9 = (int) ($in['dept'] ?? 0) ?: (int) Capsule::table('tblticketdepartments')
            ->orderBy('order')->value('id');
        try {
            $r9 = localAPI('OpenTicket', ['clientid' => $cid9, 'deptid' => $dept9,
                'subject' => mb_substr($sum9, 0, 200),
                'message' => trim("Τηλεφωνική επικοινωνία" . ($phone9 ? ' (' . $phone9 . ')' : '')
                    . "\n\n" . ($detail9 ?: $sum9)),
                'priority' => 'Medium', 'markdown' => false, 'noemail' => true],
                Capsule::table('tbladmins')->where('id', $adminId)->value('username'));
            if (($r9['result'] ?? '') === 'success') {
                $tkId9 = (int) ($r9['id'] ?? 0);
                Capsule::table('tbltickets')->where('id', $tkId9)->update(['flag' => $adminId]);
            } else {
                fail('Το ticket δεν άνοιξε: ' . ($r9['message'] ?? 'άγνωστο σφάλμα'), 500);
            }
        } catch (\Throwable $e9) {
            fail('Το ticket δεν άνοιξε: ' . $e9->getMessage(), 500);
        }
    }

    Db::addInteraction(['lead_id' => $lid9, 'clientid' => $cid9, 'kind' => 'call',
        'summary' => $sum9, 'detail' => $detail9, 'admin_id' => $adminId,
        'happened_at' => date('Y-m-d H:i:s'),
        'phone' => $phone9, 'caller' => $caller9, 'direction' => $dir9, 'minutes' => $mins9 ?: null,
        'task_id' => $taskId9 ?: null, 'ticketid' => $tkId9 ?: null,
        'followup_date' => $fup9,
        'followup_note' => mb_substr(trim((string) ($in['followupNote'] ?? '')), 0, 200) ?: null]);

    /* Ο χρόνος της κλήσης μπαίνει στην εργασία, ώστε να περάσει από τη μηχανή
       κάλυψης (προαγορά ή προσφορά) όπως κάθε άλλος χρεώσιμος χρόνος. */
    $timed9 = false;
    if ($mins9 > 0 && $taskId9) {
        $eid9 = Db::addTime($taskId9, $adminId, $mins9, !empty($in['billable']),
            'Τηλεφωνική επικοινωνία' . ($phone9 ? ' ' . $phone9 : ''));
        Time::push($eid9, (int) $cid9);   // ο πελάτης της κλήσης, που η εργασία δεν τον ξέρει
        $timed9 = true;
    }
    /* Αν η καταγραφή ξεκίνησε από πραγματική κλήση του PBX, σημειώνεται ΚΑΙ
       εκεί — αλλιώς η ίδια κλήση θα ζητούσε καταγραφή για πάντα, και στην
       «Τηλεφωνική δραστηριότητα» θα έμοιαζε αγνοημένη ενώ έχει απαντηθεί. */
    $pbxId9 = (int) ($in['pbxCall'] ?? 0);
    if ($pbxId9) {
        $row9 = Capsule::table('mod_cpm_calls')->where('id', $pbxId9)->first();
        /* Μόνο δική σου κλήση — δεν γράφεις στο όνομα άλλου. */
        if ($row9 && (int) $row9->admin_id === $adminId) {
            Capsule::table('mod_cpm_calls')->where('id', $pbxId9)->update([
                'summary'     => mb_substr($sum9, 0, 500),
                'bill_status' => !empty($in['billable']) ? 'billable' : 'free',
                'bill_reason' => !empty($in['billable'])
                    ? mb_substr(trim((string) ($in['billWhy'] ?? $sum9)), 0, 255) : null,
                'logged_by'   => $adminId,
                'logged_at'   => date('Y-m-d H:i:s'),
                'followup'    => $fup9 ? 1 : 0,
                'clientid'    => $cid9 ?: $row9->clientid,
                'interaction_id' => null]);
        }
    }
    out(['ok' => true, 'task' => $taskId9, 'ticket' => $tkId9, 'timed' => $timed9,
        'pbx' => $pbxId9 ?: 0,
        'billNeedsTask' => $mins9 > 0 && !$taskId9 && !empty($in['billable'])]);

/* ================= ΛΙΣΤΑ / ΗΜΕΡΟΛΟΓΙΟ / ΧΡΟΝΟΣ ================= */
case 'list':
    $f = ['project_id' => (int) ($_GET['fp'] ?? 0), 'status_id' => (int) ($_GET['fs'] ?? 0),
          'assignee' => (int) ($_GET['fa'] ?? 0),
          'client' => (int) ($_GET['fc'] ?? 0), 'creator' => (int) ($_GET['fb'] ?? 0),
          'product' => (int) ($_GET['fpr'] ?? 0), 'dept' => (int) ($_GET['fd'] ?? 0),
          'priority' => ($_GET['fr'] ?? '') !== '' ? (int) $_GET['fr'] : '',
          'q' => trim($_GET['q'] ?? ''), 'open_only' => (int) ($_GET['open'] ?? 1),
          'mine_only' => !empty($_GET['mine']) ? $adminId : 0];
    /* «#123» ή σκέτο «123» = αναζήτηση με αριθμό εργασίας — βρίσκει ΚΑΙ κλειστές. */
    if (preg_match('/^#?(\d{1,9})$/', $f['q'], $mId)) {
        $f['id'] = (int) $mId[1]; $f['q'] = ''; $f['open_only'] = 0;
    }
    if (!$FULL) {
        $f['restrict_admin'] = $adminId;
    }
    $rows = Db::tasksFiltered($f);
    $mins = Db::minutesForTasks(array_map(function ($r) { return (int) $r->id; }, $rows->all()));
    $list = [];
    foreach ($rows as $t) {
        $d = taskDto($t);
        $d['project'] = (int) $t->project_id;      // το χρειάζεται το φίλτρο/chips ανά project
        $d['pname'] = cnp_pn($t->project_name);
        $d['pcolor'] = $t->project_color ?: '#8595ac';
        $d['mins'] = (int) ($mins[(int) $t->id] ?? 0);
        $d['creator'] = (int) $t->created_by;
        $d['client'] = isset($t->clientid) && $t->clientid ? (int) $t->clientid : null;
        $d['clientName'] = isset($t->clientid) && $t->clientid ? clientLabel($t->clientid) : '';
        $list[] = $d;
    }
    out(['tasks' => $list]);

case 'calendar':
    $ym = preg_match('/^\d{4}-\d{2}$/', $_GET['ym'] ?? '') ? $_GET['ym'] : date('Y-m');
    /* Προβολές μέρα/εβδομάδα (21/9/2026): το διάστημα μπορεί να πέφτει σε δύο μήνες, γι' αυτό
       δέχεται from/to. Χωρίς αυτά κρατά τη συμπεριφορά «ολόκληρος ο μήνας». */
    $dFrom = preg_match('/^\d{4}-\d{2}-\d{2}$/', $_GET['from'] ?? '') ? $_GET['from'] : ($ym . '-01');
    $dTo = preg_match('/^\d{4}-\d{2}-\d{2}$/', $_GET['to'] ?? '') ? $_GET['to'] : date('Y-m-t', strtotime($ym . '-01'));
    if ($dTo < $dFrom) { $dTo = $dFrom; }
    $items = [];
    foreach (Db::tasksBetween($dFrom, $dTo) as $t) {
        if (!$FULL && (int) $t->assignee !== $adminId && !Db::canSeeProject($adminId, $t->project_id)) {
            continue;
        }
        $items[] = ['id' => (int) $t->id, 'title' => $t->title, 'due' => $t->due_date, 'status' => (int) $t->status_id,
            'prio' => (int) $t->priority, 'done' => (bool) $t->completed_at,
            'color' => $t->project_color ?: '#8595ac', 'pname' => cnp_pn($t->project_name)];
    }
    $evs = [];
    $mStart = $dFrom . ' 00:00:00';
    $mEnd = $dTo . ' 23:59:59';
    foreach (Capsule::table('mod_cpm_events')
        ->where('start_dt', '<=', $mEnd)->where('end_dt', '>=', $mStart)
        ->orderBy('start_dt')->get() as $e) {
        $att = array_filter(array_map('intval', explode(',', $e->attendees)));
        $rs9 = [];
        foreach (Capsule::table('mod_cpm_event_rsvp')->where('event_id', $e->id)->get() as $r9) {
            $rs9[$r9->kind . $r9->ref] = $r9->status;
        }
        $evs[] = ['id' => (int) $e->id, 'kind' => $e->kind, 'title' => $e->title, 'rsvp' => $rs9,
            'start' => $e->start_dt, 'end' => $e->end_dt, 'allDay' => (bool) $e->all_day,
            'attendees' => array_values($att),
            'client' => $e->clientid ? (int) $e->clientid : null,
            'clientName' => $e->clientid ? clientLabel($e->clientid) : null,
            'location' => $e->location, 'notes' => $e->notes,
            'scope' => $e->scope, 'mode' => $e->mode, 'place' => $e->place, 'purpose' => $e->purpose,
            /* «Πέρασε η ώρα;» το κρίνει ο server: το ρολόι του browser μπορεί να
               είναι σε άλλη ζώνη ή απλώς λάθος. */
            'over' => strtotime($e->end_dt) < time(),
            'by' => (int) $e->created_by, 'canEdit' => $FULL || (int) $e->created_by === $adminId];
    }
    out(['ym' => $ym, 'from' => $dFrom, 'to' => $dTo, 'items' => $items, 'events' => $evs]);

case 'event_save':                      // ομαδικό ημερολόγιο: meeting/ραντεβού/άδεια
    $eid = (int) ($in['id'] ?? 0);
    $kind = in_array($in['kind'] ?? '', ['meeting', 'appointment', 'leave', 'other'], true) ? $in['kind'] : 'meeting';
    $title = mb_substr(trim($in['title'] ?? ''), 0, 255);
    $startD = $in['start'] ?? '';
    $endD = $in['end'] ?? '';
    if ($title === '' || !strtotime($startD) || !strtotime($endD)) {
        fail('Τίτλος και ημερομηνίες είναι υποχρεωτικά');
    }
    if (strtotime($endD) < strtotime($startD)) {
        fail('Η λήξη είναι πριν την έναρξη');
    }
    $att = array_filter(array_map('intval', (array) ($in['attendees'] ?? [])));
    if (!$att) {
        $att = [$adminId];
    }
    /* ── Με ποιον και πώς ──────────────────────────────────────────────────
       Δύο ανεξάρτητες ερωτήσεις: μια σύσκεψη με πελάτη μπορεί κάλλιστα να γίνει
       στα γραφεία μας, και μια εσωτερική σε βιντεοκλήση. Το location μένει η
       λεπτομέρεια — σύνδεσμος, τηλέφωνο ή διεύθυνση, ανάλογα με τον τρόπο. */
    $cliId = (int) ($in['client'] ?? 0) ?: null;
    $scope = in_array($in['scope'] ?? '', ['internal', 'client'], true)
        ? $in['scope'] : ($cliId ? 'client' : 'internal');
    $mode = in_array($in['mode'] ?? '', ['onsite', 'video', 'phone'], true) ? $in['mode'] : null;
    $place = in_array($in['place'] ?? '', ['office', 'client', 'other'], true) ? $in['place'] : null;
    $loc = mb_substr(trim($in['location'] ?? ''), 0, 190);
    $purposes = cnp_meeting_purposes();
    $purpose = (string) ($in['purpose'] ?? '');
    $purpose = isset($purposes[$scope][$purpose]) ? $purpose : null;
    if (in_array($kind, ['meeting', 'appointment'], true)) {
        if ($scope === 'client' && !$cliId) {
            fail('Διάλεξε τον πελάτη της σύσκεψης από τη λίστα');
        }
        if ($scope === 'client' && !$purpose) {
            fail('Διάλεξε τον σκοπό της σύσκεψης (παρουσίαση, εκπαίδευση, τεχνικό ζήτημα…)');
        }
        if (!$mode) {
            fail('Διάλεξε πώς θα γίνει: δια ζώσης, βιντεοκλήση ή τηλεφωνικά');
        }
        if ($mode === 'onsite') {
            $place = $place ?: 'office';
            if ($place === 'other' && $loc === '') {
                fail('Γράψε τη διεύθυνση της συνάντησης');
            }
            if ($place === 'office') { $loc = $loc ?: 'Γραφεία CloudOn'; }
            if ($place === 'client') { $loc = $loc ?: ($cliId ? 'Στον χώρο του πελάτη' : 'Στον χώρο του πελάτη'); }
        } else {
            $place = null;
            if ($loc === '') {
                fail($mode === 'video' ? 'Βάλε τον σύνδεσμο της βιντεοκλήσης'
                    : 'Γράψε το τηλέφωνο της κλήσης');
            }
        }
    } else {
        $mode = null;
        $place = null;
        $purpose = null;
    }
    $data = ['kind' => $kind, 'title' => $title,
        'start_dt' => date('Y-m-d H:i:s', strtotime($startD)),
        'end_dt' => date('Y-m-d H:i:s', strtotime($endD)),
        'all_day' => !empty($in['allDay']) ? 1 : 0,
        'attendees' => ',' . implode(',', $att) . ',',
        'clientid' => $cliId,
        'scope' => $scope, 'mode' => $mode, 'place' => $place, 'purpose' => $purpose,
        'location' => $loc ?: null,
        'notes' => cnp_clean_html($in['notes'] ?? '') ?: null];
    if ($eid) {
        $ev = Capsule::table('mod_cpm_events')->where('id', $eid)->first();
        if (!$ev || (!$FULL && (int) $ev->created_by !== $adminId)) {
            fail('event', 403);
        }
        Capsule::table('mod_cpm_events')->where('id', $eid)->update($data);
    } else {
        $eid = Capsule::table('mod_cpm_events')->insertGetId($data
            + ['created_by' => $adminId, 'created_at' => date('Y-m-d H:i:s')]);
        /* Όποιος τη στήνει, δηλώνει και ότι θα είναι εκεί — έτσι δουλεύει κάθε
           ημερολόγιο, και έτσι πιάνει και η αυτόματη κατάσταση την ώρα της. */
        if (in_array($adminId, $att, true)) {
            Capsule::table('mod_cpm_event_rsvp')->updateOrInsert(
                ['event_id' => $eid, 'kind' => 'admin', 'ref' => $adminId],
                ['status' => 'accepted', 'responded_at' => date('Y-m-d H:i:s')]);
        }
        // ειδοποίησε τους συμμετέχοντες: καμπανάκι + EMAIL πρόσκλησης (τα email από το προφίλ τους)
        $kindL = ['meeting' => 'Meeting', 'appointment' => 'Ραντεβού', 'leave' => 'Άδεια', 'other' => 'Συμβάν'][$kind];
        $ts0 = strtotime($startD);
        $ts1 = strtotime($endD);
        $whenT = !empty($in['allDay'])
            ? date('d/m/Y', $ts0) . ($ts1 - $ts0 > 86400 ? ' – ' . date('d/m/Y', $ts1) : '')
            : date('d/m/Y H:i', $ts0) . ' – ' . date('H:i', $ts1);
        $gcalT = 'https://calendar.google.com/calendar/render?action=TEMPLATE'
            . '&text=' . rawurlencode($title)
            . '&dates=' . gmdate('Ymd\THis\Z', $ts0) . '/' . gmdate('Ymd\THis\Z', $ts1)
            . ($data['location'] ? '&location=' . rawurlencode($data['location']) : '');
        $isLinkT = $data['location'] && preg_match('#^https?://#', $data['location']);
        $cliNmT = $cliId ? clientLabel($cliId) : '';
        [$hIco, $hTxt, $hDet] = cnp_meeting_how($mode, $place, $data['location'], $cliNmT);
        $withT = ($scope === 'client'
            ? '👤 Με πελάτη: <strong>' . htmlspecialchars($cliNmT) . '</strong>'
            : '👥 Εσωτερική — με την ομάδα')
            . ($purpose ? ' · ' . htmlspecialchars($purposes[$scope][$purpose]) : '');
        $bodyT = '<p><strong>' . htmlspecialchars($title) . '</strong> — σε προσκάλεσε ο/η ' . htmlspecialchars(Db::adminName($adminId)) . '</p>'
            . '<p style="background:#eef7fd;border-left:4px solid #0090dd;padding:10px 14px;">🗓 <strong>' . $whenT . '</strong>'
            . ($hTxt ? '<br />' . $withT . '<br />' . $hIco . ' ' . htmlspecialchars($hTxt) : '')
            . ($hDet ? '<br />' . ($isLinkT
                ? 'Σύνδεσμος: <a href="' . htmlspecialchars($hDet) . '">' . htmlspecialchars($hDet) . '</a>'
                : htmlspecialchars($hDet)) : '') . '</p>'
            . ($data['notes'] ? '<p>' . nl2br(htmlspecialchars($data['notes'])) . '</p>' : '')
            . '<p><a href="' . htmlspecialchars($gcalT) . '">➕ Προσθήκη στο ημερολόγιο</a> · '
            . '<a href="https://my.cloudon.gr/projectmanagement/#/calendar">Άνοιγμα στο πάνελ (RSVP)</a></p>';
        foreach ($att as $a) {
            if ($a !== $adminId) {
                Db::pushNotification($a, 'info', "📅 $kindL: $title — " . date('d/m H:i', $ts0), '/projectmanagement/#/calendar');
                if ($kind !== 'leave') {
                    cnp_meet_mail($a, "📅 $kindL: $title — " . date('d/m/Y H:i', $ts0), $bodyT);
                }
            }
        }
        // επιπλέον εξωτερικοί προσκεκλημένοι (σκέτα emails)
        foreach (array_filter(array_map('trim', explode(',', (string) ($in['extraEmails'] ?? '')))) as $xm) {
            if (filter_var($xm, FILTER_VALIDATE_EMAIL)) {
                \WHMCS\Module\Addon\CloudonProjects\Notify::sendTo($xm, "📅 Πρόσκληση: $title — " . date('d/m/Y H:i', $ts0), $bodyT);
            }
        }
        // 📧 πρόσκληση στον πελάτη (email με link + Add to Calendar)
        if (!empty($in['inviteClient']) && $data['clientid'] && in_array($kind, ['meeting', 'appointment'], true)) {
            $ts0 = strtotime($startD);
            $ts1 = strtotime($endD);
            $gcal = 'https://calendar.google.com/calendar/render?action=TEMPLATE'
                . '&text=' . rawurlencode($title)
                . '&dates=' . gmdate('Ymd\THis\Z', $ts0) . '/' . gmdate('Ymd\THis\Z', $ts1)
                . ($data['location'] ? '&location=' . rawurlencode($data['location']) : '')
                . '&details=' . rawurlencode('Πρόσκληση από CloudOn' . ($data['notes'] ? ' — ' . mb_substr($data['notes'], 0, 300) : ''));
            $when = !empty($in['allDay'])
                ? date('d/m/Y', $ts0) . ($ts1 - $ts0 > 86400 ? ' – ' . date('d/m/Y', $ts1) : '')
                : date('d/m/Y H:i', $ts0) . ' – ' . date('H:i', $ts1);
            $isLink = $data['location'] && preg_match('#^https?://#', $data['location']);
            $msg = '<p>Αγαπητέ/ή πελάτη,</p>'
                . '<p>Σας προσκαλούμε σε <strong>' . ($kind === 'meeting' ? 'συνάντηση' : 'ραντεβού') . '</strong>: '
                . '<strong>' . htmlspecialchars($title) . '</strong></p>'
                . '<p style="background:#eef7fd;border-left:4px solid #0090dd;padding:10px 14px;">'
                . '🗓 <strong>' . $when . '</strong>'
                . ($data['location'] ? '<br />' . ($isLink
                    ? '🎥 Σύνδεσμος συμμετοχής: <a href="' . htmlspecialchars($data['location']) . '">' . htmlspecialchars($data['location']) . '</a>'
                    : '📍 Τοποθεσία: ' . htmlspecialchars($data['location'])) : '') . '</p>'
                . '<p><a href="' . htmlspecialchars($gcal) . '">➕ Προσθήκη στο ημερολόγιό σας (Google Calendar)</a></p>'
                . (function () use ($eid, $data) {
                    $base9 = 'https://my.cloudon.gr/projectmanagement/api.php?a=event_rsvp_public&t='
                        . pm_mint_rsvp($eid, $data['clientid']);
                    return '<table cellpadding="0" cellspacing="0" style="margin:14px 0"><tr>'
                        . '<td style="background:#2dbd6e;border-radius:10px;"><a href="' . $base9 . '&r=accept" '
                        . 'style="display:inline-block;padding:11px 22px;color:#ffffff;text-decoration:none;font-weight:bold;">✔ Επιβεβαιώνω τη συμμετοχή μου</a></td>'
                        . '<td style="width:12px;"></td>'
                        . '<td style="background:#e2515f;border-radius:10px;"><a href="' . $base9 . '&r=decline" '
                        . 'style="display:inline-block;padding:11px 22px;color:#ffffff;text-decoration:none;font-weight:bold;">✖ Δεν με εξυπηρετεί</a></td>'
                        . '</tr></table>';
                })()
                . '<p>Αν η ώρα δεν σας εξυπηρετεί, απαντήστε σε αυτό το email για εναλλακτική.</p>'
                . '<p>Με εκτίμηση,<br />Η ομάδα της CloudOn</p>';
            $er = localAPI('SendEmail', ['customtype' => 'general', 'id' => $data['clientid'],
                'customsubject' => '🗓 Πρόσκληση: ' . $title . ' — ' . date('d/m/Y', $ts0),
                'custommessage' => $msg]);
            if (($er['result'] ?? '') === 'success' && function_exists('logActivity')) {
                logActivity('CPM: πρόσκληση meeting «' . $title . '» στον πελάτη #' . $data['clientid'] . " (event #$eid)");
            }
        }
    }
    out(['ok' => true, 'id' => $eid]);

case 'event_busy':                       // ποιοι από τους επιλεγμένους έχουν ήδη κάτι τότε
    $bs = strtotime((string) ($in['start'] ?? $_GET['start'] ?? ''));
    $be = strtotime((string) ($in['end'] ?? $_GET['end'] ?? ''));
    $bids = array_values(array_unique(array_filter(array_map('intval',
        is_array($in['attendees'] ?? null) ? $in['attendees'] : explode(',', (string) ($_GET['attendees'] ?? ''))))));
    if (!$bs || !$be || !$bids) {
        out(['busy' => []]);
    }
    $bExc = (int) ($in['id'] ?? $_GET['id'] ?? 0);
    $busyOut = [];
    foreach ($bids as $bA) {
        $cl = Capsule::table('mod_cpm_events')
            ->where('id', '!=', $bExc)
            ->where('attendees', 'like', '%,' . $bA . ',%')
            ->where('start_dt', '<', date('Y-m-d H:i:s', $be))
            ->where('end_dt', '>', date('Y-m-d H:i:s', $bs))
            ->orderBy('start_dt')->first(['id', 'title', 'start_dt', 'end_dt', 'kind', 'all_day']);
        if ($cl) {
            $busyOut[] = ['admin' => $bA, 'name' => Db::adminName($bA), 'title' => $cl->title,
                'kind' => $cl->kind,
                'when' => $cl->all_day ? 'όλη μέρα'
                    : date('H:i', strtotime($cl->start_dt)) . '–' . date('H:i', strtotime($cl->end_dt))];
        }
    }
    out(['busy' => $busyOut]);

case 'event_del':
    $ev = Capsule::table('mod_cpm_events')->where('id', (int) ($in['id'] ?? 0))->first();
    if (!$ev || (!$FULL && (int) $ev->created_by !== $adminId)) {
        fail('event', 403);
    }
    Capsule::table('mod_cpm_events')->where('id', $ev->id)->delete();
    out(['ok' => true]);

case 'time':
    $from = preg_match('/^\d{4}-\d{2}-\d{2}$/', $_GET['from'] ?? '') ? $_GET['from'] : date('Y-m-01');
    $to = preg_match('/^\d{4}-\d{2}-\d{2}$/', $_GET['to'] ?? '') ? $_GET['to'] : date('Y-m-d');
    /* Χωρίς «Χρόνος ομάδας» βλέπεις ΜΟΝΟ τον δικό σου χρόνο — ο server το επιβάλλει,
       δεν το αφήνει στην οθόνη. Η ίδια οθόνη σερβίρει και τις δύο χρήσεις. */
    $canTeam = cnp_has_cap($adminId, $FULL, 'reports.time');
    $fa = $canTeam ? (int) ($_GET['fa'] ?? 0) : $adminId;
    $flt = ['project_id' => (int) ($_GET['fp'] ?? 0), 'admin_id' => $fa,
        'dept_id' => (int) ($_GET['fd'] ?? 0)];
    $rows = Db::timeReport($from, $to, $flt);
    $entries = [];
    $tot = ['w' => 0, 'b' => 0, 'nb' => 0, 'c' => 0];
    /* Το ΠΡΟΪΟΝ είναι η διάσταση που λείπει για την εσωτερική ανάπτυξη: «πόσο μας
       κόστισε φέτος η εξέλιξη του PharmacyOne» δεν απαντιέται ανά πελάτη. */
    $agg = ['project' => [], 'client' => [], 'admin' => [], 'product' => []];
    foreach ($rows as $r) {
        $m = (int) $r->minutes;
        $tot['w'] += $m;
        $tot[(int) $r->billable ? 'b' : 'nb'] += $m;
        $tot['c'] += (int) $r->charged_minutes;
        foreach ([['project', $r->project_name], ['client', $r->clientid ? clientLabel($r->clientid) : '— εσωτερικά —'],
                  ['admin', Db::adminName($r->admin_id)],
                  ['product', $r->product_name ?: '— χωρίς προϊόν —']] as $g) {
            [$grp, $key] = $g;
            if (!isset($agg[$grp][$key])) {
                $agg[$grp][$key] = ['w' => 0, 'b' => 0, 'c' => 0];
            }
            $agg[$grp][$key]['w'] += $m;
            if ((int) $r->billable) {
                $agg[$grp][$key]['b'] += $m;
            }
            $agg[$grp][$key]['c'] += (int) $r->charged_minutes;
        }
        $entries[] = ['at' => $r->created_at, 'task' => (int) $r->task_id, 'title' => $r->task_title,
            'pname' => cnp_pn($r->project_name), 'pcolor' => $r->project_color ?: '#8595ac',
            'client' => $r->clientid ? clientLabel($r->clientid) : null,
            'by' => Db::adminName($r->admin_id), 'mins' => $m,
            'billable' => (bool) $r->billable, 'charged' => (int) $r->charged_minutes, 'note' => $r->note];
    }
    /* Όσοι μετράνε χρόνο ΑΥΤΗ ΤΗ ΣΤΙΓΜΗ. Δεν μπαίνουν στα καταχωρημένα σύνολα (ούτε στο
       CSV) — είναι ακόμη ανοιχτοί — αλλά φαίνονται χωριστά ώστε να μη χρειάζεται να
       σταματήσει κανείς τον χρόνο του για να μετρηθεί η δουλειά του. */
    $tot['r'] = 0;
    $running = [];
    foreach (Db::runningTimers($flt) as $r) {
        $el = max(0, (int) floor((time() - strtotime($r->started_at)) / 60));
        $tot['r'] += $el;
        $who = Db::adminName($r->admin_id);
        $keys = ['project' => $r->project_name,
            'client' => $r->clientid ? clientLabel($r->clientid) : '— εσωτερικά —',
            'admin' => $who,
            'product' => $r->product_name ?: '— χωρίς προϊόν —'];
        foreach ($keys as $grp => $key) {
            if (!isset($agg[$grp][$key])) { $agg[$grp][$key] = ['w' => 0, 'b' => 0, 'c' => 0]; }
            $agg[$grp][$key]['r'] = ($agg[$grp][$key]['r'] ?? 0) + $el;
        }
        /* Τα «keys» είναι ΑΚΡΙΒΩΣ τα κλειδιά των συγκεντρωτικών πινάκων, ώστε η οθόνη
           να ξαναϋπολογίζει ζωντανά το «σε εξέλιξη» χωρίς να μαντεύει ονόματα. */
        $running[] = ['task' => (int) $r->task_id, 'title' => $r->task_title,
            'pname' => cnp_pn($r->project_name), 'pcolor' => $r->project_color ?: '#8595ac',
            'client' => $r->clientid ? clientLabel($r->clientid) : null,
            'by' => $who, 'startedAt' => $r->started_at, 'mins' => $el, 'note' => $r->note,
            'keys' => $keys];
    }

    foreach ($agg as &$grp) {
        uasort($grp, function ($a, $b) { return ($b['w'] + ($b['r'] ?? 0)) <=> ($a['w'] + ($a['r'] ?? 0)); });
    }
    unset($grp);

    /* ── ΑΝΑΛΥΣΗ ΑΝΑ ΕΡΓΑΣΙΑ ───────────────────────────────────────────────────
       Η λίστα καταχωρήσεων απαντά «πότε»· η ερώτηση όμως είναι «σε ΤΙ δούλεψε».
       Ομαδοποιούμε τον χρόνο ανά εργασία, με τις επιμέρους καταχωρήσεις μέσα. */
    $byTask = [];
    foreach ($entries as $e) {
        $k = (int) $e['task'];
        if (!isset($byTask[$k])) {
            $byTask[$k] = ['task' => $k, 'title' => $e['title'], 'pname' => $e['pname'],
                'pcolor' => $e['pcolor'], 'client' => $e['client'],
                'mins' => 0, 'billable' => 0, 'charged' => 0, 'who' => [], 'logs' => []];
        }
        $byTask[$k]['mins'] += $e['mins'];
        if ($e['billable']) { $byTask[$k]['billable'] += $e['mins']; }
        $byTask[$k]['charged'] += $e['charged'];
        $byTask[$k]['who'][$e['by']] = true;
        $byTask[$k]['logs'][] = ['at' => $e['at'], 'by' => $e['by'], 'mins' => $e['mins'],
            'billable' => $e['billable'], 'note' => $e['note']];
    }
    foreach ($byTask as &$bt) { $bt['who'] = array_keys($bt['who']); }
    unset($bt);
    usort($byTask, function ($a, $b) { return $b['mins'] <=> $a['mins']; });

    /* ── ΤΙ ΠΑΡΑΔΟΘΗΚΕ ─────────────────────────────────────────────────────────
       Μια μέρα χωρίς χρονόμετρο ΔΕΝ είναι άδεια μέρα: μπορεί να έκλεισαν πέντε
       εργασίες. Γι' αυτό δίπλα στον χρόνο δείχνουμε και τι ολοκληρώθηκε και το
       ημερολόγιο ενεργειών του μητρώου. */
    $doneList = [];
    foreach (Db::completedReport($from, $to, $flt) as $r) {
        $doneList[] = ['task' => (int) $r->id, 'title' => $r->title, 'at' => $r->completed_at,
            'by' => $r->completed_by ? Db::adminName($r->completed_by) : null,
            'note' => $r->completed_note,
            'pname' => cnp_pn($r->project_name), 'pcolor' => $r->project_color ?: '#8595ac',
            'client' => $r->clientid ? clientLabel($r->clientid) : null,
            'ticketRef' => $r->ticket_ref ?: null];
    }
    $ACT = ['create' => 'δημιούργησε', 'edit' => 'άλλαξε', 'status' => 'κατάσταση',
        'assign' => 'ανέθεσε', 'comment' => 'σχολίασε', 'time' => 'χρόνος',
        'timer' => 'χρονόμετρο', 'billing' => 'χρέωση', 'auto' => 'αυτόματο'];
    $acts = [];
    foreach (Db::activityReport($from, $to, $flt) as $r) {
        $acts[] = ['at' => $r->created_at, 'by' => Db::adminName($r->admin_id),
            'task' => (int) $r->task_id, 'title' => $r->task_title,
            'action' => $ACT[$r->action] ?? $r->action, 'kind' => $r->action,
            'detail' => $r->detail,
            'pname' => cnp_pn($r->project_name), 'pcolor' => $r->project_color ?: '#8595ac'];
    }

    out(['from' => $from, 'to' => $to, 'entries' => $entries, 'totals' => $tot,
        'agg' => $agg, 'running' => $running, 'now' => date('c'), 'canTeam' => $canTeam,
        'byTask' => array_values($byTask), 'done' => $doneList, 'acts' => $acts]);

/* ================= ΠΡΟΣΦΟΡΕΣ ================= */
case 'offers':
    $stages = [];
    foreach (Db::offerStages() as $k => $m) {
        $stages[] = ['key' => $k, 'title' => $m[0], 'color' => $m[1], 'closed' => (bool) $m[2], 'won' => (bool) $m[3]];
    }
    $offers = [];
    foreach (Db::offers((int) ($_GET['client'] ?? 0)) as $o) {
        if (!$FULL && (int) $o->assignee !== $adminId && (int) $o->created_by !== $adminId) {
            continue;
        }
        $offers[] = ['id' => (int) $o->id, 'title' => $o->title, 'stage' => $o->stage,
            'kind' => $o->kind ?: 'plain',
            'client' => $o->clientid ? (int) $o->clientid : null, 'clientName' => clientLabel($o->clientid),
            'value' => $o->quoteid && $o->quote_total !== null ? (float) $o->quote_total : (float) ($o->amount ?? 0),
            'amount' => $o->amount !== null ? (float) $o->amount : null,
            'quote' => $o->quoteid ? (int) $o->quoteid : null, 'quoteStage' => $o->quote_stage,
            'assignee' => $o->assignee ? (int) $o->assignee : null,
            'expected' => $o->expected_close, 'descr' => $o->descr, 'lead' => $o->lead_id ? (int) $o->lead_id : null,
            /* Παρακολούθηση: πότε φύγε, αν απάντησαν, πότε ξαναχτυπάμε. Οι μέρες
               υπολογίζονται εδώ ώστε η οθόνη να μη μαντεύει ζώνες ώρας. */
            'sentAt' => $o->sent_at, 'repliedAt' => $o->replied_at, 'reply' => $o->reply,
            // Αναμονή μετράει μόνο όσο δεν έχουμε απάντηση — «όχι» είναι κι αυτό απάντηση.
            'waitDays' => ($o->sent_at && !$o->replied_at && !$o->reply)
                ? (int) floor((strtotime('today') - strtotime((string) $o->sent_at)) / 86400) : null,
            'followup' => $o->followup_date, 'followupNote' => $o->followup_note,
            'followupIn' => $o->followup_date
                ? (int) floor((strtotime((string) $o->followup_date) - strtotime('today')) / 86400) : null,
            'validUntil' => ($o->quote_validuntil && strpos((string) $o->quote_validuntil, '0000') !== 0)
                ? substr((string) $o->quote_validuntil, 0, 10) : null,
            // Η αλυσίδα: από ποιο lead ήρθε, σε ποιο έργο κατέληξε.
            'project' => (int) (Capsule::table('mod_cpm_projects')->where('offer_id', $o->id)->value('id') ?: 0) ?: null,
            'leadName' => $o->lead_id
                ? (string) (Capsule::table('mod_cpm_leads')->where('id', $o->lead_id)->value('company')
                    ?: Capsule::table('mod_cpm_leads')->where('id', $o->lead_id)->value('contact') ?: '')
                : null,
            'validIn' => ($o->quote_validuntil && strpos((string) $o->quote_validuntil, '0000') !== 0)
                ? (int) floor((strtotime((string) $o->quote_validuntil) - strtotime('today')) / 86400) : null];
    }
    out(['stages' => $stages, 'offers' => $offers]);

case 'delete_offer':
    $od7 = Db::offer((int) ($in['offer'] ?? 0));
    if (!$od7) { fail('offer', 404); }
    /* Διαγράφει μόνο την προσφορά του PM· το τυχόν δεμένο WHMCS Quote ΔΕΝ πειράζεται.
       Δικαίωμα: Full admin, ή όποιος έχει τη ρητή δυνατότητα «Διαγραφή προσφορών»
       (δίνεται ανά ομάδα), ή ο ιδιοκτήτης/δημιουργός της ίδιας της προσφοράς.
       (Οι υιοθετημένες από WHMCS quotes δεν έχουν ιδιοκτήτη — γι' αυτό χρειάζεται
       η ρητή δυνατότητα, ώστε αξιόπιστα άτομα να μπορούν να τις σβήνουν.) */
    $canDel7 = $FULL || cnp_has_cap($adminId, $FULL, 'clients.offers.delete')
        || (int) $od7->assignee === $adminId || (int) $od7->created_by === $adminId;
    if (!$canDel7) {
        fail('Δεν έχεις δικαίωμα διαγραφής προσφοράς — ζήτησέ το από διαχειριστή (δυνατότητα «Διαγραφή προσφορών»)', 403);
    }
    Capsule::table('mod_cpm_offers')->where('id', (int) $od7->id)->delete();
    /* Αν ήταν δεμένη σε WHMCS quote, βάζουμε tombstone ώστε το adoptQuotes()
       να ΜΗΝ την ξαναϋιοθετήσει στην επόμενη φόρτωση (αλλιώς «ξαναγεννιόταν»
       στο «Νέα»). Το ίδιο το quote στο WHMCS μένει άθικτο. */
    if ((int) ($od7->quoteid ?? 0) > 0) {
        Capsule::table('mod_cpm_offer_dismissed')->insertOrIgnore([
            'quoteid' => (int) $od7->quoteid, 'admin_id' => $adminId,
            'created_at' => date('Y-m-d H:i:s')]);
    }
    logActivity('CPM: διαγραφή προσφοράς #' . (int) $od7->id . ($od7->quoteid ? ' (Quote #' . (int) $od7->quoteid . ' αμετάβλητο)' : ''));
    out(['ok' => true, 'quote' => (int) ($od7->quoteid ?? 0)]);

case 'move_offer':
    $o = Db::offer((int) ($in['offer'] ?? 0));
    if (!$o || (!$FULL && (int) $o->assignee !== $adminId && (int) $o->created_by !== $adminId)) {
        fail('offer', 403);
    }
    $stage = (string) ($in['stage'] ?? '');
    $ok = Db::moveOffer($o->id, $stage, $adminId);
    /* Χαμένη προσφορά δεν καλύπτει τίποτα: ο χρόνος που κρατούσε ξαναγίνεται
       ακάλυπτος, για να ξαναμπεί σε επόμενη πρόταση. */
    if ($ok && $stage === 'lost') {
        Capsule::table('mod_cpm_timelogs')->where('cover_offer_id', (int) $o->id)
            ->update(['cover' => null, 'cover_offer_id' => null, 'cover_minutes' => null]);
    }
    if ($ok && $o->quoteid) {
        $qs = ['draft' => 'Draft', 'sent' => 'Delivered', 'accepted' => 'Accepted', 'lost' => 'Lost'][$stage] ?? null;
        if ($qs) {
            Capsule::table('tblquotes')->where('id', (int) $o->quoteid)->update(['stage' => $qs]);
        }
    }
    out(['ok' => (bool) $ok]);

case 'save_offer':
    $oid = (int) ($in['offer'] ?? 0);
    if ($oid) {
        $o = Db::offer($oid);
        if (!$o || (!$FULL && (int) $o->assignee !== $adminId && (int) $o->created_by !== $adminId)) {
            fail('offer', 403);
        }
    }
    $stage = array_key_exists($in['stage'] ?? '', Db::offerStages()) ? $in['stage'] : 'new';
    $data = ['title' => mb_substr(trim($in['title'] ?? ''), 0, 200) ?: 'Χωρίς τίτλο',
        'clientid' => (int) ($in['client'] ?? 0) ?: null,
        'amount' => ($in['amount'] ?? '') !== '' && $in['amount'] !== null ? round((float) $in['amount'], 2) : null,
        'stage' => $stage, 'assignee' => (int) ($in['assignee'] ?? 0) ?: null,
        'expected_close' => preg_match('/^\d{4}-\d{2}-\d{2}$/', $in['expected'] ?? '') ? $in['expected'] : null,
        'descr' => cnp_clean_html($in['descr'] ?? '', 60000),   // rich-text
        'closed_at' => Db::offerStages()[$stage][2] ? date('Y-m-d H:i:s') : null];
    if (!$oid) {
        $data['created_by'] = $adminId;
    }
    $savedOid = Db::saveOffer($oid, $data);
    if ((int) ($in['task'] ?? 0)) { cnp_link_offer_to_task((int) $in['task'], $savedOid, $adminId); }
    out(['ok' => true, 'id' => $savedOid]);

case 'offer_track':                      // αποστολή / απάντηση / επόμενο follow-up
    $o = Db::offer((int) ($in['offer'] ?? 0));
    if (!$o) {
        fail('offer', 404);
    }
    $d = [];
    foreach (['sent' => 'sent_at', 'replied' => 'replied_at', 'followup' => 'followup_date'] as $k => $col) {
        if (array_key_exists($k, $in)) {
            $d[$col] = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string) $in[$k]) ? $in[$k] : null;
        }
    }
    if (array_key_exists('reply', $in)) {
        $d['reply'] = in_array($in['reply'], ['yes', 'no', 'thinking'], true) ? $in['reply'] : null;
    }
    if (array_key_exists('followupNote', $in)) {
        $d['followup_note'] = mb_substr(trim((string) $in['followupNote']), 0, 200) ?: null;
    }
    /* «Έγινε το follow-up»: κρατάμε πότε έγινε και καθαρίζουμε την ημερομηνία,
       ώστε να μη μένει για πάντα κόκκινο. Νέα ημερομηνία ορίζεται χωριστά. */
    if (!empty($in['followupDone'])) {
        $d['followup_done_on'] = date('Y-m-d');
        $d['followup_date'] = null;
    }
    if ($d) {
        $d['updated_at'] = date('Y-m-d H:i:s');
        Capsule::table('mod_cpm_offers')->where('id', $o->id)->update($d);
    }
    out(['ok' => true]);

case 'offer_timeline':                   // επικοινωνίες + ορόσημα μιας προσφοράς
    $o = Db::offer((int) ($_GET['offer'] ?? 0));
    if (!$o) {
        fail('offer', 404);
    }
    $ev = [];
    foreach (Capsule::table('mod_cpm_interactions')->where('offer_id', $o->id)->get() as $i) {
        $ev[] = ['type' => 'interaction', 'kind' => $i->kind, 'text' => $i->summary,
            'by' => $i->admin_id ? Db::adminName((int) $i->admin_id) : null,
            'at' => $i->happened_at ?: $i->created_at,
            'fup' => $i->followup_date && !$i->followup_done ? $i->followup_date : null];
    }
    // Ορόσημα από την ίδια την προσφορά — για να διαβάζεται η ιστορία ολόκληρη.
    if ($o->created_at) {
        $ev[] = ['type' => 'milestone', 'kind' => 'new', 'text' => 'Δημιουργήθηκε η προσφορά', 'at' => $o->created_at];
    }
    if ($o->sent_at) {
        $ev[] = ['type' => 'milestone', 'kind' => 'sent', 'text' => 'Στάλθηκε στον πελάτη', 'at' => $o->sent_at . ' 09:00:00'];
    }
    if ($o->replied_at) {
        $lbl = ['yes' => 'Αποδέχτηκε', 'no' => 'Απέρριψε', 'thinking' => 'Το σκέφτεται'];
        $ev[] = ['type' => 'milestone', 'kind' => 'reply',
            'text' => ($lbl[(string) $o->reply] ?? 'Απάντησε'), 'at' => $o->replied_at . ' 09:00:00'];
    }
    usort($ev, function ($a, $b) { return strcmp((string) $b['at'], (string) $a['at']); });
    out(['events' => array_slice($ev, 0, 60)]);

case 'offer_comments':                   // νήμα σχολίων/ερωτήσεων (ομάδα)
    $ocO = Db::offer((int) ($_GET['offer'] ?? $in['offer'] ?? 0));
    if (!$ocO) { fail('offer', 404); }
    if (!$FULL && (int) $ocO->assignee !== $adminId && (int) $ocO->created_by !== $adminId) {
        fail('offer', 403);
    }
    $ocRows = [];
    foreach (Capsule::table('mod_cpm_offer_comments')->where('offer_id', (int) $ocO->id)
                 ->orderBy('id')->get() as $c) {
        $ocRows[] = ['id' => (int) $c->id, 'mine' => $c->by_type === 'admin',
            'byType' => $c->by_type,
            'who' => $c->by_type === 'client'
                ? clientLabel((int) $ocO->clientid) : Db::adminName((int) $c->by_id),
            'body' => (string) $c->body, 'at' => $c->created_at,
            'unread' => ($c->by_type === 'client' && !$c->read_by_team_at)];
    }
    // Οι ερωτήσεις του πελάτη θεωρούνται διαβασμένες από την ομάδα μόλις ανοιχτεί το νήμα.
    Capsule::table('mod_cpm_offer_comments')->where('offer_id', (int) $ocO->id)
        ->where('by_type', 'client')->whereNull('read_by_team_at')
        ->update(['read_by_team_at' => date('Y-m-d H:i:s')]);
    out(['comments' => $ocRows, 'quote' => (int) ($ocO->quoteid ?? 0),
        'clientId' => (int) ($ocO->clientid ?? 0)]);

case 'offer_comment_add':                // απάντηση ομάδας στον πελάτη
    $oaO = Db::offer((int) ($in['offer'] ?? 0));
    if (!$oaO) { fail('offer', 404); }
    if (!$FULL && (int) $oaO->assignee !== $adminId && (int) $oaO->created_by !== $adminId) {
        fail('offer', 403);
    }
    $oaBody = trim((string) ($in['body'] ?? ''));
    $oaBody = mb_substr(preg_replace('/[\x{10000}-\x{10FFFF}]/u', '', $oaBody), 0, 4000);
    if ($oaBody === '') { fail('Γράψε κείμενο'); }
    $oaId = (int) Capsule::table('mod_cpm_offer_comments')->insertGetId([
        'offer_id' => (int) $oaO->id, 'quoteid' => (int) ($oaO->quoteid ?? 0),
        'by_type' => 'admin', 'by_id' => $adminId, 'body' => $oaBody,
        'created_at' => date('Y-m-d H:i:s'), 'read_by_team_at' => date('Y-m-d H:i:s')]);
    // Ειδοποίηση πελάτη με email (ώστε να δει την απάντηση στο portal).
    $oaMailed = false;
    $oaCli = (int) ($oaO->clientid ?? 0);
    $oaMail = $oaCli ? filter_var((string) Capsule::table('tblclients')->where('id', $oaCli)->value('email'),
        FILTER_VALIDATE_EMAIL) : '';
    if ($oaMail && (int) ($oaO->quoteid ?? 0) > 0) {
        $link = 'https://my.cloudon.gr/viewquote.php?id=' . (int) $oaO->quoteid . '#cloudon-comments';
        $adm = Capsule::table('tbladmins')->where('id', $adminId)->first(['firstname', 'lastname', 'email']);
        $admName = trim((string) ($adm->firstname ?? '') . ' ' . (string) ($adm->lastname ?? '')) ?: 'CloudOn';
        $bodyHtml = '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#243447;line-height:1.6;max-width:640px">'
            . 'Καλησπέρα σας,<br><br>έχετε νέα απάντηση για την προσφορά σας:<br><br>'
            . '<div style="padding:11px 14px;border-left:3px solid #0097e4;background:#f4f8fc">'
            . nl2br(htmlspecialchars($oaBody, ENT_QUOTES, 'UTF-8')) . '</div><br>'
            . 'Δείτε την και απαντήστε εδώ: <a href="' . htmlspecialchars($link) . '">' . htmlspecialchars($link) . '</a><br><br>'
            . 'Με εκτίμηση,<br>' . htmlspecialchars($admName) . '<br>CloudOn</div>';
        try {
            $mail = new \PHPMailer\PHPMailer\PHPMailer(true);
            $mail->CharSet = 'UTF-8';
            $mail->setFrom('noreply@cloudon.gr', 'CloudOn');
            $mail->addAddress($oaMail);
            if (filter_var((string) ($adm->email ?? ''), FILTER_VALIDATE_EMAIL)) {
                $mail->addReplyTo((string) $adm->email, $admName);
            }
            $mail->isHTML(true);
            $mail->Subject = 'Απάντηση για την προσφορά σας — CloudOn';
            $mail->Body = $bodyHtml;
            $mail->AltBody = strip_tags(str_ireplace('<br>', "\n", $bodyHtml));
            $mail->send();
            $oaMailed = true;
        } catch (\Throwable $e) {
        }
    }
    logActivity('CPM: απάντηση σε ερώτηση προσφοράς #' . (int) $oaO->id . ($oaMailed ? ' (email στον πελάτη)' : ''));
    out(['ok' => true, 'id' => $oaId, 'emailed' => $oaMailed]);

case 'create_quote':
    $o = Db::offer((int) ($in['offer'] ?? 0));
    if (!$o || $o->quoteid || !$o->clientid) {
        fail('offer');
    }
    $r = localAPI('CreateQuote', ['subject' => $o->title, 'stage' => 'Draft',
        'validuntil' => $o->expected_close ?: date('Y-m-d', strtotime('+30 days')),
        'userid' => (int) $o->clientid,
        'lineitems' => base64_encode(serialize([['desc' => $o->title, 'qty' => 1,
            'up' => (float) ($o->amount ?? 0), 'discount' => 0, 'taxable' => true]]))], 'pdelis');
    if (($r['result'] ?? '') === 'success' && !empty($r['quoteid'])) {
        Db::saveOffer($o->id, ['quoteid' => (int) $r['quoteid'], 'stage' => 'draft']);
        out(['ok' => true, 'quote' => (int) $r['quoteid']]);
    }
    fail($r['message'] ?? 'CreateQuote failed');

/* ================= ΚΟΣΤΟΛΟΓΗΣΗ PHARMACYONE =================
   Η προσφορά PharmacyOne δεν είναι ελεύθερο κείμενο με ένα ποσό: είναι μια
   ρύθμιση από την οποία βγαίνουν και το ποσό και το έγγραφο. Ο υπολογισμός
   γίνεται ΜΟΝΟ στον server (lib/Pharmacy.php), ώστε να μη γίνεται ποτέ να
   διαφέρει η τιμή της προσφοράς από τους αριθμούς που διαβάζει ο πελάτης. */
case 'pharmacy_defs':                    // ο κατάλογος: παράμετροι, modules, τιμοκατάλογος
    out(['params' => array_map(function ($d) {
            return ['cell' => $d[0], 'lab' => $d[1], 'type' => $d[2], 'hint' => $d[3] ?? '',
                'grp' => $d[4] ?? 'Παράμετροι εγκατάστασης'];
        }, Pharmacy::paramDefs()),
        'groups' => array_map(function ($g) {
            return ['title' => $g['title'], 'items' => array_map(function ($it) {
                return ['cell' => $it[0], 'lab' => $it[1]];
            }, $g['items'])];
        }, Pharmacy::moduleGroups()),
        'rates' => array_map(function ($d) {
            // noDisc: γραμμή που καμία εκπτωτική πολιτική δεν αγγίζει
            return ['cell' => $d[0], 'lab' => $d[1], 'adj' => $d[2],
                'noDisc' => in_array($d[0], Pharmacy::NO_DISCOUNT_CELLS, true)];
        }, Pharmacy::rateRows()),
        'editions' => Pharmacy::defaultEditions(),
        'features' => array_map(function ($f) { return ['lab' => $f[0], 'on' => $f[1]]; }, Pharmacy::features()),
        'defaults' => ['p' => Pharmacy::defaultParams(), 'yn' => Pharmacy::defaultModules(),
            'q' => Pharmacy::defaultQty(), 'r' => Pharmacy::defaultRates(),
            'rd' => Pharmacy::defaultLineDiscounts()],
        'hourRate' => Pharmacy::HOUR_RATE,
        'nextProtocol' => cnp_offer_protocol_peek(),
        'canEditBase' => $FULL,          // ποιος βλέπει «Αποθήκευση βασικού τιμοκαταλόγου»
        'me' => Db::adminName($adminId)]);

case 'pharmacy_catalog_save':            // ΓΕΝΙΚΟΣ τιμοκατάλογος — ισχύει για όλες τις νέες προσφορές
    if (!$FULL) { fail('Μόνο διαχειριστής μπορεί να αλλάξει τον βασικό τιμοκατάλογο', 403); }
    Pharmacy::saveBaseCatalog(
        is_array($in['rates'] ?? null) ? $in['rates'] : [],
        is_array($in['editions'] ?? null) ? $in['editions'] : [],
        is_array($in['disc'] ?? null) ? $in['disc'] : [],
        is_array($in['rd'] ?? null) ? $in['rd'] : []);
    logActivity('CPM: αλλαγή ΒΑΣΙΚΟΥ τιμοκαταλόγου PharmacyOne (admin ' . $adminId . ')');
    out(['ok' => true, 'rates' => Pharmacy::defaultRates(), 'editions' => Pharmacy::defaultEditions(),
        'params' => Pharmacy::defaultParams()]);

case 'pharmacy_catalog_reset':           // επαναφορά εργοστασιακών τιμών
    if (!$FULL) { fail('Μόνο διαχειριστής', 403); }
    Pharmacy::resetBaseCatalog();
    logActivity('CPM: επαναφορά εργοστασιακού τιμοκαταλόγου PharmacyOne (admin ' . $adminId . ')');
    out(['ok' => true, 'rates' => Pharmacy::defaultRates(), 'editions' => Pharmacy::defaultEditions(),
        'params' => Pharmacy::defaultParams()]);

case 'pharmacy_calc':                    // ζωντανή προεπισκόπηση καθώς αλλάζεις παραμέτρους
    $cfg9 = is_array($in['config'] ?? null) ? $in['config'] : [];
    $res9 = Pharmacy::calc($cfg9);
    $lines9 = [];
    foreach (Pharmacy::buckets() as $b9 => $bd9) {
        $lines9[$b9] = ['title' => $bd9[0], 'sum' => $bd9[1], 'head' => $bd9[2], 'rows' => []];
    }
    foreach (Pharmacy::bucketLines($res9, $res9['cfg']['sel']) as $b9 => $rows9) {
        $lines9[$b9]['rows'] = $rows9;
        $lines9[$b9]['total'] = array_sum(array_column($rows9, 'amount'));
    }
    out(['totals' => $res9['totals'], 'buckets' => array_values($lines9),
        'amount' => Pharmacy::offerAmount($cfg9), 'cfg' => $res9['cfg']]);

case 'pharmacy_ai_draft':                 // ✨ Copilot: από περιγραφή → ρύθμιση + στοιχεία πελάτη
    $keyD = (string) (Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')
        ->where('setting', 'ai_api_key')->value('value') ?: '');
    if ($keyD === '') { fail('Δεν έχει οριστεί AI API key — βάλ\' το στις Ρυθμίσεις'); }
    $descD = trim((string) ($in['text'] ?? ''));
    if (mb_strlen($descD) < 5) { fail('Γράψε μια περιγραφή του τι θέλει ο πελάτης'); }

    /* Ο κατάλογος δίνεται στο μοντέλο ως πλαίσιο — έτσι διαλέγει ΜΟΝΟ έγκυρα κελιά. */
    $pDefs = Pharmacy::paramDefs();
    $pLines = [];
    foreach ($pDefs as $pd) { $pLines[] = $pd[0] . ' = ' . $pd[1] . ' (' . ($pd[2] === 'pct' ? 'ποσοστό %' : 'αριθμός') . ')'; }
    $mLines = [];
    foreach (Pharmacy::moduleGroups() as $g) {
        foreach ($g['items'] as $it) { $mLines[] = $it[0] . ' = ' . $it[1] . ' [' . $g['title'] . ']'; }
    }
    $eLines = [];
    foreach (Pharmacy::defaultEditions() as $ei => $ed) { $eLines[] = $ei . ' = ' . $ed['name'] . ' (' . $ed['soft1'] . ')'; }

    $promptD = "Είσαι βοηθός πωλήσεων της CloudOn για προσφορές φαρμακείου (PharmacyOne).\n"
        . "Από την περιγραφή του πελάτη, ΣΥΜΠΛΗΡΩΣΕ μια ρύθμιση προσφοράς. Επίστρεψε ΜΟΝΟ ένα JSON object, χωρίς σχόλια.\n\n"
        . "ΠΑΡΑΜΕΤΡΟΙ (κλειδί → τι μετράει· δώσε ΑΡΙΘΜΟ ποσότητας/πλήθους — ΠΟΤΕ τιμή/κόστος):\n" . implode("\n", $pLines) . "\n\n"
        . "MODULES (κλειδί → όνομα· βάλε στο 'modules' ΜΟΝΟ όσα ζητά ρητά ή προφανώς η περιγραφή):\n" . implode("\n", $mLines) . "\n\n"
        . "ΕΚΔΟΣΕΙΣ (δείκτης 'edition' 0-3): " . implode(' · ', $eLines) . "\n\n"
        . "ΚΑΝΟΝΕΣ:\n"
        . "- Χρησιμοποίησε ΜΟΝΟ κλειδιά από τους παραπάνω καταλόγους. Μη βγάζεις τιμές/ποσά — ο υπολογισμός γίνεται αλλού.\n"
        . "- Αν δεν αναφέρεται κάτι, ΜΗΝ το βάζεις (θα πάρει προεπιλογή). Χρήστες: αν δεν λέει, βάλε 1.\n"
        . "- Αναγνώρισε ΣΤΟΙΧΕΙΑ ΠΕΛΑΤΗ από την περιγραφή: επωνυμία, ΑΦΜ (9 ψηφία), υπόψη (ονοματεπώνυμο), τηλέφωνο, email, διεύθυνση, Δ.Ο.Υ., πόλη. Ό,τι δεν υπάρχει → κενό.\n"
        . "- Διάλεξε 'edition' που ταιριάζει (default 2 αν αβέβαιο).\n"
        . "- 'qty': τεμάχια ανά module όταν η περιγραφή λέει πλήθος (π.χ. 3 σταθμοί picking → {\"L22\":3}). Αλλιώς παράλειψέ το.\n\n"
        . "Σχήμα JSON:\n"
        . "{\"edition\":2,\"params\":{\"I4\":3},\"modules\":[\"N16\"],\"qty\":{\"L22\":2},"
        . "\"client\":{\"name\":\"\",\"afm\":\"\",\"attn\":\"\",\"phone\":\"\",\"email\":\"\",\"address\":\"\",\"doy\":\"\",\"city\":\"\"},"
        . "\"summary\":\"μία πρόταση στα ελληνικά: τι κατάλαβα\"}\n\n"
        . "ΠΕΡΙΓΡΑΦΗ ΠΕΛΑΤΗ:\n" . $descD;

    $modelD = trim((string) (Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')
        ->where('setting', 'offer_ai_model')->value('value') ?: '')) ?: 'claude-opus-5';
    $resD = cnp_anthropic($keyD, $modelD, [['type' => 'text', 'text' => $promptD]], 1500);
    if (empty($resD['ok'])) { fail($resD['error'] ?? 'Αποτυχία AI', 502); }
    $aiD = cnp_json_extract($resD['text']);
    if (!is_array($aiD)) { fail('Δεν κατάλαβα την περιγραφή — δοκίμασε πιο συγκεκριμένα', 422); }

    /* ── Αυστηρή επικύρωση: μόνο έγκυρα κελιά· καμία τιμή/κόστος από το AI. ── */
    $okParams = [];
    foreach ($pDefs as $pd) { $okParams[$pd[0]] = $pd[2]; }
    $okMods = [];
    foreach (Pharmacy::moduleGroups() as $g) { foreach ($g['items'] as $it) { $okMods[$it[0]] = true; } }

    $cfgD = ['p' => [], 'yn' => [], 'q' => [], 'sel' => 2, 'o' => []];
    $cfgD['sel'] = (isset($aiD['edition']) && (int) $aiD['edition'] >= 0 && (int) $aiD['edition'] <= 3) ? (int) $aiD['edition'] : 2;
    foreach ((array) ($aiD['params'] ?? []) as $cell => $val) {
        if (!isset($okParams[$cell]) || !is_numeric($val)) { continue; }
        $v = (float) $val;
        if ($okParams[$cell] === 'pct') { $v = $v > 1 ? $v / 100 : $v; $v = max(0, min(1, $v)); }
        else { $v = max(0, min(9999, $v)); }
        $cfgD['p'][$cell] = $v;
    }
    foreach ((array) ($aiD['modules'] ?? []) as $cell) {
        if (isset($okMods[(string) $cell])) { $cfgD['yn'][(string) $cell] = 1; }
    }
    /* Τεμάχια ανά module (στήλη «Τεμ» του φύλλου) — δηλωμένη ποσότητα σημαίνει και «μέσα». */
    foreach ((array) ($aiD['qty'] ?? []) as $cell => $val) {
        if (!isset($okMods[(string) $cell]) || !is_numeric($val)) { continue; }
        $qv = max(0, min(9999, (float) $val));
        $cfgD['q'][(string) $cell] = $qv;
        if ($qv > 0) { $cfgD['yn'][(string) $cell] = 1; }
    }
    $cl = is_array($aiD['client'] ?? null) ? $aiD['client'] : [];
    $afmD = preg_replace('/\D+/', '', (string) ($cl['afm'] ?? ''));
    $cfgD['o'] = [
        'client' => mb_substr(trim((string) ($cl['name'] ?? '')), 0, 200),
        'afm' => mb_strlen($afmD) === 9 ? $afmD : '',
        'attn' => mb_substr(trim((string) ($cl['attn'] ?? '')), 0, 120),
        'cphone' => mb_substr(trim((string) ($cl['phone'] ?? '')), 0, 40),
        'cemail' => mb_substr(trim((string) ($cl['email'] ?? '')), 0, 120),
        'address' => mb_substr(trim((string) ($cl['address'] ?? '')), 0, 200),
        'doy' => mb_substr(trim((string) ($cl['doy'] ?? '')), 0, 80),
        'city' => mb_substr(trim((string) ($cl['city'] ?? '')), 0, 80) ?: 'Αθήνα',
    ];
    $cfgFull = Pharmacy::normalize($cfgD);
    out(['ok' => true, 'cfg' => $cfgFull, 'amount' => Pharmacy::offerAmount($cfgFull),
        'summary' => mb_substr(trim((string) ($aiD['summary'] ?? '')), 0, 400),
        'afm' => $cfgD['o']['afm']]);

case 'pharmacy_save':                    // δημιουργία / ενημέρωση της προσφοράς
    $oid9 = (int) ($in['offer'] ?? 0);
    $cfg9 = is_array($in['config'] ?? null) ? $in['config'] : [];
    $cfg9 = Pharmacy::normalize($cfg9);
    $cid9 = (int) ($in['client'] ?? 0) ?: null;
    if ($cid9 && !Capsule::table('tblclients')->where('id', $cid9)->exists()) { $cid9 = null; }
    $ed9 = Pharmacy::defaultEditions()[$cfg9['sel']];
    $nm9 = trim((string) ($in['clientName'] ?? $cfg9['o']['client'] ?? ''));
    if ($cid9 && $nm9 === '') { $nm9 = clientLabel($cid9); }
    $cfg9['o']['client'] = $nm9;
    /* Αυτόματος αριθμός: μόνο για νέα προσφορά όταν δεν έχει οριστεί ρητά. */
    $prot9 = trim((string) ($cfg9['o']['protocol'] ?? ''));
    if (!$oid9 && ($prot9 === '' || substr($prot9, -1) === '-')) {
        $cfg9['o']['protocol'] = cnp_offer_protocol_reserve();
    }
    $title9 = mb_substr(trim((string) ($in['title'] ?? '')) ?: ($ed9['name'] . ' — ' . ($nm9 ?: 'νέος πελάτης')), 0, 200);
    $amount9 = Pharmacy::offerAmount($cfg9);

    $row9 = ['title' => $title9, 'clientid' => $cid9, 'amount' => $amount9,
        'kind' => 'pharmacyone', 'config' => json_encode($cfg9, JSON_UNESCAPED_UNICODE),
        'updated_at' => date('Y-m-d H:i:s')];
    if ($oid9) {
        $ex9 = Db::offer($oid9);
        if (!$ex9) { fail('offer', 404); }
        if (!$FULL && (int) $ex9->assignee !== $adminId && (int) $ex9->created_by !== $adminId) {
            fail('Η προσφορά ανήκει σε άλλον', 403);
        }
        Capsule::table('mod_cpm_offers')->where('id', $oid9)->update($row9);
    } else {
        $row9['stage'] = 'draft';
        $row9['assignee'] = $adminId;
        $row9['created_by'] = $adminId;
        $row9['created_at'] = date('Y-m-d H:i:s');
        $row9['expected_close'] = date('Y-m-d', strtotime('+' . max(1, (int) $cfg9['o']['validDays']) . ' days'));
        $oid9 = (int) Capsule::table('mod_cpm_offers')->insertGetId($row9);
    }
    if ((int) ($in['task'] ?? 0)) { cnp_link_offer_to_task((int) $in['task'], $oid9, $adminId); }
    out(['ok' => true, 'offer' => $oid9, 'amount' => $amount9, 'title' => $title9]);

case 'pharmacy_doc':                     // το έγγραφο της προσφοράς, έτοιμο για εκτύπωση
    $oid9 = (int) ($_GET['offer'] ?? $in['offer'] ?? 0);
    $cli9 = 0;
    if ($oid9) {
        $o9 = Db::offer($oid9);
        if (!$o9 || $o9->kind !== 'pharmacyone') { fail('offer', 404); }
        $cli9 = (int) $o9->clientid;
        $cfg9 = json_decode((string) $o9->config, true) ?: [];
        if ($cli9 && empty($cfg9['o']['client'])) { $cfg9['o']['client'] = clientLabel($cli9); }
    } else {
        $cfg9 = is_array($in['config'] ?? null) ? $in['config'] : [];
    }
    // Δρομολόγηση μέσω του μητρώου τύπων (F0): ίδιο αποτέλεσμα με PharmacyOne,
    // αλλά έτοιμο για κάθε τύπο προσφοράς.
    $ptype9 = OfferTypes::get(isset($o9) && $o9 ? (string) $o9->kind : 'pharmacyone');
    out(['html' => $ptype9->docHtml($cfg9), 'css' => $ptype9->docCss(),
        'amount' => $ptype9->amount($cfg9),
        'cfg' => $ptype9->normalize($cfg9), 'client' => $cli9]);

case 'pbx_email':                        // τηλεφωνικό κέντρο: ίδια ροή αποστολής, άλλος τύπος
case 'pharmacy_email':                   // αποστολή της προσφοράς στον πελάτη ως PDF συνημμένο
    $kindE = $action === 'pbx_email' ? 'pbx' : 'pharmacyone';
    $oidE = (int) ($in['offer'] ?? 0);
    $postedCfg = is_array($in['config'] ?? null) ? $in['config'] : null;
    $oE = null;
    if ($oidE) {
        $oE = Db::offer($oidE);
        if (!$oE || $oE->kind !== $kindE) { fail('offer', 404); }
        if (!$FULL && (int) $oE->assignee !== $adminId && (int) $oE->created_by !== $adminId
            && !cnp_has_cap($adminId, $FULL, 'clients.offers.delete')) {
            fail('Δεν έχεις δικαίωμα αποστολής αυτής της προσφοράς', 403);
        }
    }
    // Ζωντανό config αν στάλθηκε (τυχόν edits χωρίς αποθήκευση)· αλλιώς το αποθηκευμένο.
    $cfgE = $postedCfg !== null ? $postedCfg : ($oE ? (json_decode((string) $oE->config, true) ?: []) : []);
    $etype = OfferTypes::get(($oE && $oE->kind) ? (string) $oE->kind : $kindE);
    $cfgN = $etype->normalize($cfgE);
    $toE = filter_var(trim((string) ($in['to'] ?? ($cfgN['o']['cemail'] ?? ''))), FILTER_VALIDATE_EMAIL);
    if (!$toE) { fail('Δώσε έγκυρο email παραλήπτη'); }
    $company = trim((string) ($cfgN['o']['client'] ?? '')) ?: 'σας';
    $proto   = trim((string) ($cfgN['o']['protocol'] ?? ''));
    $subjectE = mb_substr(trim((string) ($in['subject'] ?? '')), 0, 190)
        ?: ('Οικονομική προσφορά CloudOn' . ($proto ? ' — ' . $proto : ''));
    $coverE = trim((string) ($in['message'] ?? ''));

    /* 1) Το έγγραφο ως αυτοτελές HTML (base = host, ώστε να φορτώσουν τα logos). */
    $docHtml = '<!doctype html><html lang="el"><head><meta charset="utf-8">'
        . '<base href="https://my.cloudon.gr/">'
        . '<style>' . $etype->docCss() . '</style></head><body>'
        . $etype->docHtml($cfgE) . '</body></html>';

    /* 2) PDF μέσω του Chromium (Playwright) — pixel-perfect όπως το print. */
    $tmpDir = sys_get_temp_dir();
    $stampE = 'phof_' . bin2hex(random_bytes(6));
    $htmlF = $tmpDir . '/' . $stampE . '.html';
    $pdfF  = $tmpDir . '/' . $stampE . '.pdf';
    file_put_contents($htmlF, $docHtml);
    $nodeBin = '/opt/plesk/node/20/bin/node';
    $renderJs = __DIR__ . '/../modules/addons/cloudonprojects/lib/pdf-render.js';
    $cmdE = 'PLAYWRIGHT_BROWSERS_PATH=/opt/pw-browsers HOME=' . escapeshellarg($tmpDir) . ' '
        . escapeshellarg($nodeBin) . ' ' . escapeshellarg($renderJs) . ' '
        . escapeshellarg($htmlF) . ' ' . escapeshellarg($pdfF) . ' 2>&1';
    $outE = []; $rcE = 1;
    exec($cmdE, $outE, $rcE);
    @unlink($htmlF);
    if ($rcE !== 0 || !is_file($pdfF) || filesize($pdfF) < 500) {
        @unlink($pdfF);
        logActivity('CPM: αποτυχία PDF προσφοράς — ' . implode(' | ', array_slice($outE, -3)));
        fail('Αποτυχία δημιουργίας PDF — δοκίμασε ξανά ή ειδοποίησε διαχειριστή');
    }

    /* 3) Αποστολή email με το PDF συνημμένο (PHPMailer, τοπικός MTA). */
    $adm = Capsule::table('tbladmins')->where('id', $adminId)->first(['firstname', 'lastname', 'email']);
    $admEmail = filter_var((string) ($adm->email ?? ''), FILTER_VALIDATE_EMAIL);
    $admName = trim((string) ($adm->firstname ?? '') . ' ' . (string) ($adm->lastname ?? '')) ?: 'CloudOn';
    if ($coverE !== '') {
        $bodyHtml = nl2br(strip_tags(cnp_clean_html($coverE), '<b><strong><i><em><br><a><p><ul><ol><li>'));
    } else {
        $bodyHtml = 'Αγαπητοί συνεργάτες,<br><br>'
            . 'σας αποστέλλουμε συνημμένα την οικονομική μας προσφορά'
            . ($proto ? ' (αρ. πρωτοκόλλου ' . htmlspecialchars($proto) . ')' : '') . '.<br><br>'
            . 'Παραμένουμε στη διάθεσή σας για οποιαδήποτε διευκρίνιση.<br><br>'
            . 'Με εκτίμηση,<br>' . htmlspecialchars($admName) . '<br>CloudOn';
    }
    $wrap = '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#243447;'
        . 'line-height:1.6;max-width:640px">' . $bodyHtml . '</div>';
    $fname = 'Prosfora' . ($proto ? '-' . preg_replace('/[^A-Za-z0-9\-]/', '', $proto) : '') . '.pdf';
    $sentOk = false; $errE = '';
    try {
        $mail = new \PHPMailer\PHPMailer\PHPMailer(true);
        $mail->CharSet = 'UTF-8';
        $mail->setFrom('noreply@cloudon.gr', 'CloudOn');
        $mail->addAddress($toE);
        if ($admEmail) { $mail->addReplyTo($admEmail, $admName); }
        $mail->isHTML(true);
        $mail->Subject = $subjectE;
        $mail->Body = $wrap;
        $mail->AltBody = trim(preg_replace('/\s*\n\s*/', "\n", strip_tags(str_ireplace(['<br>', '<br/>', '<br />'], "\n", $wrap))));
        $mail->addAttachment($pdfF, $fname);
        $mail->send();
        $sentOk = true;
    } catch (\Throwable $e) {
        $errE = $e->getMessage();
    }
    @unlink($pdfF);
    if (!$sentOk) {
        logActivity('CPM: αποτυχία email προσφοράς προς ' . $toE . ' — ' . $errE);
        fail('Το email δεν στάλθηκε: ' . $errE);
    }

    /* 4) Λογαριασμός πελάτη: με την αποστολή, εξασφαλίζουμε WHMCS account ώστε ο
       πελάτης να μπαίνει στο MyCloudOn και να βλέπει την προσφορά του. Αν είναι
       νέος, φεύγουν αυτόματα οι κωδικοί σύνδεσης. */
    $acct = ['created' => false, 'emailed' => false];
    $linkedCid = ($oE && (int) $oE->clientid > 0) ? (int) $oE->clientid : 0;
    if (!$linkedCid) {
        $cmeta = [];
        $newCid = cnp_offer_ensure_client($cfgE, $adminId, $cmeta);
        if ($newCid) {
            $linkedCid = $newCid;
            $acct['created'] = !empty($cmeta['created']);
            $acct['emailed'] = !empty($cmeta['emailed']);
            if ($oidE) { Capsule::table('mod_cpm_offers')->where('id', $oidE)->update(['clientid' => $newCid]); }
        }
    }

    /* 4β) WHMCS quote: ώστε ο πελάτης να το βλέπει native στο portal («Quotes»),
       itemized από τα lineItems του τύπου. Idempotent. */
    $quoteCreated = false;
    if ($oidE && $linkedCid) {
        $oFresh = Db::offer($oidE);
        if ($oFresh) {
            $hadQuote = (int) ($oFresh->quoteid ?? 0) > 0;
            $qidE = cnp_offer_ensure_quote($oFresh, $etype, $cfgE, $adminId);
            if ($qidE && !$hadQuote) { $quoteCreated = true; }
        }
    }

    /* 5) Καταγραφή + tracking: σημειώνεται η αποστολή, μετακίνηση new/draft → sent. */
    if ($oidE && $oE) {
        $updE = [];
        if (empty($oE->sent_at)) { $updE['sent_at'] = date('Y-m-d'); }
        if ($updE) { Capsule::table('mod_cpm_offers')->where('id', $oidE)->update($updE); }
        if (in_array((string) $oE->stage, ['new', 'draft'], true)) {
            Db::moveOffer($oidE, 'sent', $adminId);
            if ((int) ($oE->quoteid ?? 0) > 0) {
                Capsule::table('tblquotes')->where('id', (int) $oE->quoteid)->update(['stage' => 'Delivered']);
            }
        }
    }
    logActivity('CPM: αποστολή προσφοράς ' . $etype->label() . ($proto ? ' ' . $proto : '') . ' στον πελάτη ' . $toE
        . ($oidE ? ' (offer #' . $oidE . ')' : '') . ($acct['created'] ? ' + νέος λογαριασμός MyCloudOn' : ''));
    out(['ok' => true, 'to' => $toE, 'client' => $linkedCid ?: null,
        'accountCreated' => $acct['created'], 'credentialsSent' => $acct['emailed'],
        'quoteCreated' => $quoteCreated]);

/* ================= ΤΗΛΕΦΩΝΙΚΑ ΚΕΝΤΡΑ (3CX / Yeastar) — ξεχωριστό από PharmacyOne ================= */
case 'pbx_defs':                         // πλατφόρμες, κατηγορίες, βασικός τιμοκατάλογος
    out(['platforms' => Pbx::platforms(), 'cats' => Pbx::CATS, 'items' => Pbx::defaultItems(),
        'payMethods' => Pbx::PAY_METHODS, 'intro' => Pbx::DEFAULT_INTRO, 'delivery' => Pbx::DEFAULT_DELIVERY,
        'nextProtocol' => cnp_offer_protocol_peek(), 'canEditBase' => $FULL, 'me' => Db::adminName($adminId)]);

case 'pbx_catalog_save':                 // ΒΑΣΙΚΟΣ τιμοκατάλογος τηλεφωνικών κέντρων (όλες οι νέες προσφορές)
    if (!$FULL) { fail('Μόνο διαχειριστής μπορεί να αλλάξει τον βασικό τιμοκατάλογο', 403); }
    Pbx::saveBaseCatalog(is_array($in['items'] ?? null) ? $in['items'] : []);
    logActivity('CPM: αλλαγή ΒΑΣΙΚΟΥ τιμοκαταλόγου τηλεφωνικών κέντρων (admin ' . $adminId . ')');
    out(['ok' => true, 'items' => Pbx::defaultItems()]);

case 'pbx_catalog_reset':
    if (!$FULL) { fail('Μόνο διαχειριστής', 403); }
    Pbx::resetBaseCatalog();
    logActivity('CPM: επαναφορά εργοστασιακού τιμοκαταλόγου τηλεφωνικών κέντρων (admin ' . $adminId . ')');
    out(['ok' => true, 'items' => Pbx::defaultItems()]);

case 'pbx_calc':                         // ζωντανή προεπισκόπηση — ο υπολογισμός γίνεται ΜΟΝΟ εδώ
    $rP = Pbx::calc(is_array($in['config'] ?? null) ? $in['config'] : []);
    out(['cfg' => $rP['cfg'], 'lines' => $rP['lines'], 'missing' => $rP['missing'],
        'totals' => ['rec' => $rP['rec'], 'once' => $rP['once'], 'raw' => $rP['raw'], 'discAmt' => $rP['discAmt'],
            'net' => $rP['net'], 'vat' => $rP['vat'], 'gross' => $rP['gross'], 'y2net' => $rP['y2net'], 'y2' => $rP['y2']],
        'amount' => $rP['net']]);

case 'pbx_save':                         // δημιουργία / ενημέρωση προσφοράς τηλεφωνικού κέντρου
    $oidP = (int) ($in['offer'] ?? 0);
    $cfgP = Pbx::normalize(is_array($in['config'] ?? null) ? $in['config'] : []);
    $cidP = (int) ($in['client'] ?? 0) ?: null;
    if ($cidP && !Capsule::table('tblclients')->where('id', $cidP)->exists()) { $cidP = null; }
    $nmP = trim((string) ($in['clientName'] ?? $cfgP['o']['client'] ?? ''));
    if ($cidP && $nmP === '') { $nmP = clientLabel($cidP); }
    $cfgP['o']['client'] = $nmP;
    $protP = trim((string) ($cfgP['o']['protocol'] ?? ''));
    if (!$oidP && ($protP === '' || substr($protP, -1) === '-')) { $cfgP['o']['protocol'] = cnp_offer_protocol_reserve(); }
    $platP = Pbx::platforms()[$cfgP['plat']]['name'];
    $titleP = mb_substr(trim((string) ($in['title'] ?? '')) ?: ('Τηλ. κέντρο ' . $platP . ' — ' . ($nmP ?: 'νέος πελάτης')), 0, 200);
    $amountP = Pbx::offerAmount($cfgP);
    $rowP = ['title' => $titleP, 'clientid' => $cidP, 'amount' => $amountP, 'kind' => 'pbx',
        'config' => json_encode($cfgP, JSON_UNESCAPED_UNICODE), 'updated_at' => date('Y-m-d H:i:s')];
    if ($oidP) {
        $exP = Db::offer($oidP);
        if (!$exP || $exP->kind !== 'pbx') { fail('offer', 404); }
        if (!$FULL && (int) $exP->assignee !== $adminId && (int) $exP->created_by !== $adminId) { fail('Η προσφορά ανήκει σε άλλον', 403); }
        Capsule::table('mod_cpm_offers')->where('id', $oidP)->update($rowP);
    } else {
        $rowP['stage'] = 'draft'; $rowP['assignee'] = $adminId; $rowP['created_by'] = $adminId;
        $rowP['created_at'] = date('Y-m-d H:i:s');
        $rowP['expected_close'] = date('Y-m-d', strtotime('+' . max(1, (int) $cfgP['o']['validDays']) . ' days'));
        $oidP = (int) Capsule::table('mod_cpm_offers')->insertGetId($rowP);
    }
    if ((int) ($in['task'] ?? 0)) { cnp_link_offer_to_task((int) $in['task'], $oidP, $adminId); }
    out(['ok' => true, 'offer' => $oidP, 'amount' => $amountP, 'title' => $titleP]);

case 'pbx_doc':                          // το έγγραφο (αποθηκευμένη προσφορά ή ζωντανή ρύθμιση)
    $oidP = (int) ($_GET['offer'] ?? $in['offer'] ?? 0);
    $cliP = 0;
    if ($oidP) {
        $oP = Db::offer($oidP);
        if (!$oP || $oP->kind !== 'pbx') { fail('offer', 404); }
        $cliP = (int) $oP->clientid;
        $cfgP = json_decode((string) $oP->config, true) ?: [];
        if ($cliP && empty($cfgP['o']['client'])) { $cfgP['o']['client'] = clientLabel($cliP); }
    } else {
        $cfgP = is_array($in['config'] ?? null) ? $in['config'] : [];
    }
    $tP = OfferTypes::get('pbx');
    out(['html' => $tP->docHtml($cfgP), 'css' => $tP->docCss(), 'amount' => $tP->amount($cfgP),
        'cfg' => $tP->normalize($cfgP), 'client' => $cliP]);

/* ================= CRM: ΕΠΑΦΕΣ / ΕΠΙΚΟΙΝΩΝΙΕΣ ================= */
case 'contacts':
    $q = trim($_GET['q'] ?? '');
    $last = Db::lastContactMap();
    $stages = Db::leadStages();
    $rows = [];
    foreach (Db::leads() as $l) {
        if (!$FULL && (int) $l->assignee !== $adminId && (int) $l->created_by !== $adminId) {
            continue;
        }
        $name = $l->company ?: $l->contact ?: '—';
        if ($q !== '' && mb_stripos($name . ' ' . $l->contact . ' ' . $l->email . ' ' . $l->phone, $q) === false) {
            continue;
        }
        $m = $stages[$l->stage] ?? $stages['target'];
        $rows[] = ['kind' => 'lead', 'id' => (int) $l->id, 'name' => $name,
            'sub' => $l->contact && $l->company ? $l->contact : null,
            'badge' => $m[0], 'color' => $m[1], 'phone' => $l->phone, 'email' => $l->email,
            'last' => $last['lead:' . $l->id] ?? null,
            'next' => !$m[2] ? $l->next_action : null, 'who' => $l->assignee ? Db::adminName($l->assignee) : null];
    }
    if ($FULL) {
        $cids = [];
        foreach (array_keys($last) as $k) {
            if (strpos($k, 'client:') === 0) {
                $cids[] = (int) substr($k, 7);
            }
        }
        $cq = Capsule::table('tblclients');
        if ($q !== '') {
            $like = '%' . $q . '%';
            $cq->where(function ($w) use ($like) {
                $w->where('firstname', 'like', $like)->orWhere('lastname', 'like', $like)
                  ->orWhere('companyname', 'like', $like)->orWhere('email', 'like', $like);
            })->limit(30);
        } elseif ($cids) {
            $cq->whereIn('id', $cids);
        } else {
            $cq->whereRaw('1=0');
        }
        foreach ($cq->get(['id', 'firstname', 'lastname', 'companyname', 'email', 'phonenumber']) as $c) {
            $rows[] = ['kind' => 'client', 'id' => (int) $c->id,
                'name' => $c->companyname ?: trim($c->firstname . ' ' . $c->lastname), 'sub' => null,
                'badge' => 'Πελάτης', 'color' => '#16a26a', 'phone' => $c->phonenumber, 'email' => $c->email,
                'last' => $last['client:' . $c->id] ?? null, 'next' => null, 'who' => null];
        }
    }
    usort($rows, function ($a, $b) { return strcmp((string) $b['last'], (string) $a['last']); });
    out(['rows' => $rows]);

case 'comms':
    $recent = [];
    foreach (Db::recentInteractions(60) as $i) {
        if (!$FULL && (int) $i->admin_id !== $adminId) {
            continue;
        }
        $recent[] = ['id' => (int) $i->id, 'kind' => $i->kind, 'summary' => $i->summary,
            'by' => Db::adminName($i->admin_id), 'at' => $i->happened_at,
            'lead' => $i->lead_id ? (int) $i->lead_id : null,
            'who' => $i->lead_id ? ($i->lead_company ?: $i->lead_contact) : clientLabel($i->clientid),
            'followup' => $i->followup_date, 'followupNote' => $i->followup_note,
            'followupDone' => (bool) $i->followup_done];
    }
    out(['recent' => $recent]);

case 'followup_done':
    $i = Db::interaction((int) ($in['id'] ?? 0));
    if (!$i || (!$FULL && (int) $i->admin_id !== $adminId)) {
        fail('interaction', 403);
    }
    Capsule::table('mod_cpm_interactions')->where('id', $i->id)->update(['followup_done' => 1]);
    out(['ok' => true]);

/* ================= ΣΤΟΧΟΙ ΠΡΟΪΟΝΤΩΝ ================= */
case 'targets':
    $ym = preg_match('/^\d{4}-\d{2}$/', $_GET['ym'] ?? '') ? $_GET['ym'] : date('Y-m');
    $from = $ym . '-01';
    $to = date('Y-m-t', strtotime($from));
    // client → πωλητής (από το lead που έκλεισε: assignee)
    $lead2seller = [];
    foreach (Capsule::table('mod_cpm_leads')->where('clientid', '>', 0)->where('assignee', '>', 0)
        ->orderBy('id')->get(['clientid', 'assignee']) as $l) {
        $lead2seller[(int) $l->clientid] = (int) $l->assignee;   // τελευταίο lead κερδίζει
    }
    // πωλήσεις μήνα ανά προϊόν + πωλητή
    $agg = [];   // pid => sellerId(0=χωρίς) => [units, value]
    foreach (Capsule::table('tblhosting')->whereBetween('regdate', [$from, $to])
        ->whereNotIn('domainstatus', ['Cancelled', 'Fraud'])->get(['packageid', 'userid', 'amount']) as $r) {
        $pid = (int) $r->packageid;
        $seller = $lead2seller[(int) $r->userid] ?? 0;
        $agg[$pid][$seller] = $agg[$pid][$seller] ?? [0, 0.0];
        $agg[$pid][$seller][0]++;
        $agg[$pid][$seller][1] += (float) $r->amount;
    }
    // στόχοι ανά προϊόν + πωλητή
    $tg = [];   // pid => adminId => [tUnits, tValue, id]
    foreach (Capsule::table('mod_cpm_product_targets')->get() as $t) {
        $tg[(int) $t->product_id][(int) $t->admin_id] = [(int) $t->target_units, (float) $t->target_value, (int) $t->id];
    }
    $pids = array_values(array_unique(array_merge(array_keys($agg), array_keys($tg))));
    $pnames = $pids ? Capsule::table('tblproducts')->whereIn('id', $pids)->pluck('name', 'id')->all() : [];
    $cards = [];
    foreach ($pids as $pid) {
        $ovT = $tg[$pid][0] ?? [0, 0.0, 0];               // εταιρικός στόχος (admin 0)
        $ou = 0; $ov = 0.0;
        foreach (($agg[$pid] ?? []) as $uv) { $ou += $uv[0]; $ov += $uv[1]; }
        $people = [];
        $set = array_unique(array_merge(array_keys($tg[$pid] ?? []), array_keys($agg[$pid] ?? [])));
        foreach ($set as $a) {
            if ($a === 0) { continue; }
            $t = $tg[$pid][$a] ?? [0, 0.0, 0];
            $s = $agg[$pid][$a] ?? [0, 0.0];
            $people[] = ['admin' => $a, 'name' => Db::adminName($a),
                'tUnits' => $t[0], 'tValue' => $t[1], 'tid' => $t[2], 'units' => $s[0], 'value' => $s[1]];
        }
        usort($people, function ($x, $y) { return $y['value'] <=> $x['value']; });
        $un = $agg[$pid][0] ?? [0, 0.0];
        $cards[] = ['product' => $pid, 'name' => $pnames[$pid] ?? ('#' . $pid),
            'tUnits' => $ovT[0], 'tValue' => $ovT[1], 'tid' => $ovT[2], 'units' => $ou, 'value' => $ov,
            'people' => $people, 'unattrUnits' => $un[0], 'unattrValue' => $un[1]];
    }
    usort($cards, function ($x, $y) { return $y['value'] <=> $x['value']; });
    $sellers = [];
    foreach (Db::admins() as $a) {
        $nm = trim($a->firstname . ' ' . $a->lastname);
        if (preg_match('/\b(bot|test|debug|cnptest|system)\b/i', $nm)) { continue; }
        $sellers[] = ['id' => (int) $a->id, 'name' => $nm];
    }
    $products = [];
    $gNames = Capsule::table('tblproductgroups')->pluck('name', 'id')->all();
    foreach (Capsule::table('tblproducts')->where('hidden', 0)->orderBy('name')->get(['id', 'name', 'gid']) as $p) {
        $products[] = ['id' => (int) $p->id, 'name' => $p->name, 'group' => $gNames[(int) $p->gid] ?? ''];
    }
    out(['ym' => $ym, 'cards' => $cards, 'sellers' => $sellers, 'products' => $products]);

case 'save_ptarget':
    $pid = (int) ($in['product'] ?? 0);
    if (!$pid || !Capsule::table('tblproducts')->where('id', $pid)->exists()) {
        fail('product');
    }
    $adm = (int) ($in['admin'] ?? 0);   // 0 = εταιρικός στόχος, >0 = ανά πωλητή
    $u = max(0, (int) ($in['units'] ?? 0));
    $v = round((float) ($in['value'] ?? 0), 2);
    if ($u === 0 && $v == 0.0) {   // κενό = διαγραφή αυτού του στόχου
        Capsule::table('mod_cpm_product_targets')->where('product_id', $pid)->where('admin_id', $adm)->delete();
        out(['ok' => true, 'deleted' => true]);
    }
    Capsule::table('mod_cpm_product_targets')->updateOrInsert(
        ['product_id' => $pid, 'admin_id' => $adm],
        ['target_units' => $u, 'target_value' => $v, 'created_at' => date('Y-m-d H:i:s')]);
    out(['ok' => true]);

case 'del_ptarget':
    Db::deleteProductTarget((int) ($in['id'] ?? 0));
    out(['ok' => true]);

/* ================= ΠΕΛΑΤΗΣ 360 ================= */
case 'client360':
    // Ανοιχτό και στους χειριστές — αλλά τα οικονομικά (ποσά) μόνο σε διαχειριστές
    $q = trim($_GET['q'] ?? '');
    $cid = (int) ($_GET['id'] ?? 0);
    if (!$cid && $q !== '') {
        if (ctype_digit($q)) {
            $cid = (int) $q;
        } else {
            $like = '%' . $q . '%';
            $matches = [];
            foreach (Capsule::table('tblclients')->where(function ($w) use ($like) {
                $w->where('firstname', 'like', $like)->orWhere('lastname', 'like', $like)
                  ->orWhere('companyname', 'like', $like)->orWhere('email', 'like', $like);
            })->limit(12)->get(['id', 'firstname', 'lastname', 'companyname', 'email']) as $m) {
                $matches[] = ['id' => (int) $m->id, 'name' => $m->companyname ?: trim($m->firstname . ' ' . $m->lastname), 'email' => $m->email];
            }
            if (count($matches) === 1) {
                $cid = $matches[0]['id'];
            } else {
                out(['matches' => $matches]);
            }
        }
    }
    if (!$cid) {
        out(['matches' => []]);
    }
    $cl = Capsule::table('tblclients')->where('id', $cid)
        ->first(['id', 'firstname', 'lastname', 'companyname', 'email', 'status']);
    if (!$cl) {
        fail('client', 404);
    }
    $months = in_array((int) ($_GET['months'] ?? 6), [3, 6, 12, 120], true) ? (int) $_GET['months'] : 6;
    $doneIds = Capsule::table('mod_cpm_statuses')->where('is_done', 1)->pluck('id')->all() ?: [0];
    $scBal = null;
    try {
        if (Capsule::schema()->hasTable('mod_supportcontracts_clients')) {
            $scBal = Capsule::table('mod_supportcontracts_clients')->where('userid', $cid)->value('balance_minutes');
        }
    } catch (\Throwable $e) {
    }
    // 📦 Υπηρεσίες/προγράμματα από εμάς (ενεργά + σε αναστολή)
    $svcs = [];
    foreach (Capsule::table('tblhosting as h')
        ->join('tblproducts as p', 'p.id', '=', 'h.packageid')
        ->where('h.userid', $cid)->whereIn('h.domainstatus', ['Active', 'Suspended'])
        ->orderBy('h.nextduedate')
        ->get(['h.id', 'h.domain', 'h.domainstatus', 'h.nextduedate', 'h.billingcycle',
            'h.amount', 'h.dedicatedip', 'p.name as pname']) as $sv) {
        $svcs[] = ['id' => (int) $sv->id, 'product' => $sv->pname, 'domain' => $sv->domain,
            'ip' => $sv->dedicatedip, 'status' => $sv->domainstatus,
            'due' => $sv->nextduedate > '0000-00-00' ? $sv->nextduedate : null,
            'cycle' => $sv->billingcycle,
            'amount' => $FULL ? (float) $sv->amount : null];
    }
    // 🛡️ SLA / συμβόλαιο υποστήριξης
    $slaInfo = null;
    try {
        if (Capsule::schema()->hasTable('mod_supportcontracts_clients')) {
            $sc = Capsule::table('mod_supportcontracts_clients')->where('userid', $cid)->first();
            if ($sc) {
                $met = null;
                $tot9 = Capsule::table('mod_supportcontracts_tickets as st')
                    ->join('tbltickets as t', 't.id', '=', 'st.ticketid')
                    ->where('t.userid', $cid)->whereNotNull('st.first_response_at')
                    ->where('t.date', '>=', date('Y-m-d', strtotime('-90 days')));
                $cnt9 = (clone $tot9)->count();
                if ($cnt9 > 0) {
                    $met = round((clone $tot9)->where('st.sla_met', 1)->count() / $cnt9 * 100);
                }
                $slaInfo = ['enabled' => (bool) $sc->enabled, 'priority' => $sc->priority,
                    'label' => $sc->label,
                    'response' => trim($sc->sla_response_value . ' ' . $sc->sla_response_unit),
                    'bizHours' => trim(($sc->biz_start ?? '') . '–' . ($sc->biz_end ?? '')),
                    'balance' => (int) $sc->balance_minutes, 'met90' => $met];
            }
        }
    } catch (\Throwable $e) {
    }
    // 💶 Ανοιχτό υπόλοιπο: διαχειριστές=ποσό, χειριστές=ΝΑΙ/ΟΧΙ
    $owedAmt = (float) Capsule::table('tblinvoices')->where('userid', $cid)->where('status', 'Unpaid')->sum('total');
    $owedCnt = (int) Capsule::table('tblinvoices')->where('userid', $cid)->where('status', 'Unpaid')->count();
    // 👥 πρόσωπα επαφής + τηλέφωνο
    $phone9 = Capsule::table('tblclients')->where('id', $cid)->value('phonenumber');
    $people9 = [];
    try {
        foreach (Capsule::table('mod_cpm_people')->where('clientid', $cid)->get() as $pp) {
            $people9[] = ['name' => $pp->name, 'title' => $pp->title, 'phone' => $pp->phone, 'email' => $pp->email];
        }
    } catch (\Throwable $e) {
    }
    $myPk = (int) Capsule::table('mod_cpm_client_package')->where('clientid', $cid)->value('package_id');
    $allPk = [];
    foreach (Capsule::table('mod_cpm_support_packages')->orderBy('sort')->get(['id', 'name']) as $pk) {
        $allPk[] = ['id' => (int) $pk->id, 'name' => $pk->name];
    }
    out(['client' => ['id' => $cid, 'status' => (string) $cl->status,
        'name' => $cl->companyname ?: trim($cl->firstname . ' ' . $cl->lastname),
            'email' => $cl->email, 'phone' => $phone9],
        'package' => $myPk ?: null, 'packages' => $FULL ? $allPk : [],
        'remote' => (function () use ($cid) {
            try {
                $q = Capsule::table('mod_cpm_remote_sessions')->where('clientid', $cid)->whereNotNull('ended_at');
                return ['sessions90' => (clone $q)->where('started_at', '>=', date('Y-m-d', strtotime('-90 days')))->count(),
                    'mins90' => (int) (clone $q)->where('started_at', '>=', date('Y-m-d', strtotime('-90 days')))->sum('minutes'),
                    'monthMins' => (int) (clone $q)->where('started_at', '>=', date('Y-m-01'))->sum('minutes')];
            } catch (\Throwable $e) {
                return null;
            }
        })(),
        'services' => $svcs,
        'sla' => $slaInfo,
        /* Ήταν δεμένο στο $FULL, που έκανε τη δυνατότητα «Ανοιχτά υπόλοιπα»
           αδύνατο να δοθεί σε κάποιον που δεν είναι διαχειριστής. */
        'owed' => ['flag' => $owedCnt > 0,
            'canSee' => cnp_can_see_balances($adminId, $FULL),
            'amount' => cnp_can_see_balances($adminId, $FULL) ? round($owedAmt, 2) : null,
            'count' => cnp_can_see_balances($adminId, $FULL) ? $owedCnt : null],
        'people' => $people9,
        'full' => $FULL,
        'summary' => [
            'services' => Capsule::table('tblhosting')->where('userid', $cid)->where('domainstatus', 'Active')->count(),
            'openTasks' => Capsule::table('mod_cpm_tasks as t')->leftJoin('mod_cpm_projects as p', 'p.id', '=', 't.project_id')
                ->where('p.clientid', $cid)->whereNotIn('t.status_id', $doneIds)->count(),
            'openTickets' => Capsule::table('tbltickets')->where('userid', $cid)->whereNotIn('status', ['Closed', 'Cancelled'])->count(),
            'scBalance' => $scBal !== null ? (int) $scBal : null,
        ],
        /* Δομημένη πλοήγηση, όχι μόνο μετρητές: από τον πελάτη πρέπει να φτάνεις
           στα έργα του, στις εργασίες τους και στα tickets του — και αντίστροφα.
           Το χρονολόγιο δείχνει «τι έγινε πότε»· αυτά δείχνουν «τι υπάρχει». */
        'projects' => (function () use ($cid, $doneIds) {
            $out = [];
            foreach (Capsule::table('mod_cpm_projects')->where('clientid', $cid)
                         ->orderByDesc('id')->get(['id', 'name', 'color', 'status', 'deptid', 'due_date', 'manager_id']) as $p) {
                $tot = (int) Capsule::table('mod_cpm_tasks')->where('project_id', $p->id)->count();
                $open = (int) Capsule::table('mod_cpm_tasks')->where('project_id', $p->id)
                    ->whereNotIn('status_id', $doneIds)->count();
                $out[] = ['id' => (int) $p->id, 'name' => $p->name, 'color' => $p->color,
                    'archived' => $p->status === 'archived',
                    'dept' => $p->deptid ? (string) Capsule::table('tblticketdepartments')->where('id', $p->deptid)->value('name') : null,
                    'deptId' => $p->deptid ? (int) $p->deptid : null,
                    'manager' => $p->manager_id ? Db::adminName((int) $p->manager_id) : null,
                    'due' => ($p->due_date && strpos((string) $p->due_date, '0000') !== 0) ? $p->due_date : null,
                    'tasks' => $tot, 'open' => $open];
            }
            return $out;
        })(),
        'openTasks' => (function () use ($cid, $doneIds) {
            $out = [];
            foreach (Capsule::table('mod_cpm_tasks as t')->leftJoin('mod_cpm_projects as p', 'p.id', '=', 't.project_id')
                         ->where('p.clientid', $cid)->whereNotIn('t.status_id', $doneIds)
                         ->orderBy('t.due_date')->limit(25)
                         ->get(['t.id', 't.title', 't.due_date', 't.assignee', 't.ticketid', 't.dept_id',
                             'p.name as pname', 'p.id as pid']) as $t) {
                $out[] = ['id' => (int) $t->id, 'title' => $t->title, 'project' => cnp_pn($t->pname),
                    'projectId' => (int) $t->pid, 'ticket' => $t->ticketid ? (int) $t->ticketid : null,
                    'deptId' => $t->dept_id ? (int) $t->dept_id : null,
                    'dept' => $t->dept_id ? (string) Capsule::table('tblticketdepartments')
                        ->where('id', $t->dept_id)->value('name') : null,
                    'assignee' => $t->assignee ? Db::adminName((int) $t->assignee) : null,
                    'due' => ($t->due_date && strpos((string) $t->due_date, '0000') !== 0) ? $t->due_date : null];
            }
            return $out;
        })(),
        'openTicketList' => (function () use ($cid) {
            $out = [];
            foreach (Capsule::table('tbltickets')->where('userid', $cid)
                         ->whereNotIn('status', ['Closed', 'Cancelled'])->orderByDesc('lastreply')->limit(25)
                         ->get(['id', 'tid', 'title', 'status', 'did', 'lastreply']) as $t) {
                $out[] = ['id' => (int) $t->id, 'tid' => $t->tid, 'title' => $t->title, 'status' => $t->status,
                    'dept' => (string) Capsule::table('tblticketdepartments')->where('id', $t->did)->value('name'),
                    'last' => $t->lastreply];
            }
            return $out;
        })(),
        'months' => $months,
        'timeline' => Db::clientTimeline($cid, date('Y-m-d', strtotime('-' . $months . ' months')))]);

/* ================= ΚΕΡΔΟΦΟΡΙΑ ================= */
case 'profit':
    $from = preg_match('/^\d{4}-\d{2}-\d{2}$/', $_GET['from'] ?? '') ? $_GET['from'] : date('Y-01-01');
    $to = preg_match('/^\d{4}-\d{2}-\d{2}$/', $_GET['to'] ?? '') ? $_GET['to'] : date('Y-m-d');
    $costH = (float) str_replace(',', '.', (string) (Capsule::table('tbladdonmodules')
        ->where('module', 'cloudonprojects')->where('setting', 'cost_per_hour')->value('value') ?: 0));
    $mins = [];
    foreach (Capsule::table('mod_cpm_timelogs as l')
        ->join('mod_cpm_tasks as t', 't.id', '=', 'l.task_id')
        ->leftJoin('mod_cpm_projects as p', 'p.id', '=', 't.project_id')
        ->where('l.running', 0)->whereBetween('l.created_at', [$from . ' 00:00:00', $to . ' 23:59:59'])
        ->selectRaw('COALESCE(p.clientid, l.sc_userid, 0) as cid, SUM(l.minutes) m')->groupBy('cid')->get() as $r) {
        $mins[(int) $r->cid] = (int) $r->m;
    }
    $exp = [];
    $expList = [];
    foreach (Db::expenses($from, $to) as $e) {
        $exp[(int) ($e->clientid ?: 0)] = ($exp[(int) ($e->clientid ?: 0)] ?? 0) + (float) $e->amount;
        $expList[] = ['id' => (int) $e->id, 'at' => $e->spent_at, 'project' => $e->project_name,
            'client' => $e->clientid ? clientLabel($e->clientid) : null,
            'descr' => $e->descr, 'amount' => (float) $e->amount];
    }
    $cids = array_values(array_filter(array_unique(array_merge(array_keys($mins), array_keys($exp)))));
    $rev = [];
    if ($cids) {
        foreach (Capsule::table('tblaccounts')->whereIn('userid', $cids)
            ->whereBetween('date', [$from . ' 00:00:00', $to . ' 23:59:59'])
            ->selectRaw('userid, SUM(amountin) - SUM(amountout) as v')->groupBy('userid')->get() as $r) {
            $rev[(int) $r->userid] = (float) $r->v;
        }
    }
    $clients = [];
    foreach ($cids as $cid2) {
        $labor = round(($mins[$cid2] ?? 0) / 60 * $costH, 2);
        $e2 = round($exp[$cid2] ?? 0, 2);
        $r2 = round($rev[$cid2] ?? 0, 2);
        $clients[] = ['id' => $cid2, 'name' => clientLabel($cid2) ?: '—', 'mins' => $mins[$cid2] ?? 0,
            'labor' => $labor, 'exp' => $e2, 'rev' => $r2, 'profit' => round($r2 - $labor - $e2, 2)];
    }
    usort($clients, function ($a, $b) { return $a['profit'] <=> $b['profit']; });
    $projList = [];
    foreach (Db::projects(true) as $p) {
        $projList[] = ['id' => (int) $p->id, 'name' => $p->name];
    }
    out(['from' => $from, 'to' => $to, 'costH' => $costH, 'clients' => $clients,
        'expenses' => $expList, 'projects' => $projList]);

case 'add_expense':
    $pid = (int) ($in['project'] ?? 0);
    $amt = (float) ($in['amount'] ?? 0);
    if (!$pid || $amt <= 0 || !Db::project($pid)) {
        fail('input');
    }
    Db::addExpense($pid, trim($in['descr'] ?? '') ?: 'Έξοδο', $amt,
        preg_match('/^\d{4}-\d{2}-\d{2}$/', $in['at'] ?? '') ? $in['at'] : date('Y-m-d'), $adminId);
    out(['ok' => true]);

case 'del_expense':
    Db::deleteExpense((int) ($in['id'] ?? 0));
    out(['ok' => true]);

/* ================= ΠΡΟΑΓΟΡΑΣΜΕΝΟΣ ΧΡΟΝΟΣ =================
   Το μητρώο είναι ΕΝΑ: οι πίνακες του supportcontracts. Εδώ δεν φτιάχνεται
   δεύτερη τράπεζα χρόνου — απλώς γίνεται δουλεύσιμη από το PM, όπου ζει και ο
   χρόνος που την αναλώνει. Δες lib/Cover.php για το ποια πηγή πληρώνει τι. */
case 'prepaid':
    $pcRows = [];
    $pcTot = ['balance' => 0, 'offer' => 0, 'open' => 0, 'clients' => 0, 'low' => 0];
    $lowLimit = (int) round(((float) (Capsule::table('tbladdonmodules')->where('module', 'supportcontracts')
        ->where('setting', 'low_balance_hours')->value('value') ?: 2)) * 60);
    $withContract = [];
    if (Capsule::schema()->hasTable('mod_supportcontracts_clients')) {
        foreach (Capsule::table('mod_supportcontracts_clients')->orderBy('id')->get() as $pc) {
            $withContract[] = (int) $pc->userid;
        }
    }
    /* Και όποιος έχει ακάλυπτο χρόνο χωρίς συμβόλαιο: αλλιώς η δουλειά που
       πρέπει να τιμολογηθεί δεν φαίνεται πουθενά. */
    foreach (Capsule::table('mod_cpm_timelogs')->whereNotNull('sc_userid')->where('billable', 1)
        ->distinct()->pluck('sc_userid') as $u9) {
        if (!in_array((int) $u9, $withContract, true)) { $withContract[] = (int) $u9; }
    }
    foreach ($withContract as $uid9) {
        $st = Cover::clientState($uid9);
        if (!$st['contract'] && !$st['uncovered']) { continue; }
        $pcRows[] = ['client' => $uid9, 'name' => clientLabel($uid9)] + $st;
        $pcTot['clients']++;
        $pcTot['balance'] += $st['balance'];
        $pcTot['offer'] += $st['offerLeft'];
        $pcTot['open'] += $st['uncovered'];
        if ($st['contract'] && $st['balance'] <= $lowLimit) { $pcTot['low']++; }
    }
    usort($pcRows, function ($a, $b) {
        if ($a['uncovered'] !== $b['uncovered']) { return $b['uncovered'] <=> $a['uncovered']; }
        return $a['balance'] <=> $b['balance'];
    });
    out(['rows' => $pcRows, 'totals' => $pcTot, 'low' => $lowLimit,
        'step' => (int) (Capsule::table('tbladdonmodules')->where('module', 'supportcontracts')
            ->where('setting', 'charge_step_minutes')->value('value') ?: 15),
        'rate' => (float) (Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')
            ->where('setting', 'hour_rate')->value('value') ?: 0),
        'products' => cnp_prepaid_products()]);

case 'prepaid_client':
    $uid9 = (int) ($_GET['client'] ?? $in['client'] ?? 0);
    if (!$uid9 || !Capsule::table('tblclients')->where('id', $uid9)->exists()) { fail('client'); }
    $from9 = preg_match('/^\d{4}-\d{2}-\d{2}$/', $_GET['from'] ?? '') ? $_GET['from'] : date('Y-m-01');
    $to9 = preg_match('/^\d{4}-\d{2}-\d{2}$/', $_GET['to'] ?? '') ? $_GET['to'] : date('Y-m-d');
    $ledger = [];
    if (Capsule::schema()->hasTable('mod_supportcontracts_ledger')) {
        foreach (Capsule::table('mod_supportcontracts_ledger')->where('userid', $uid9)
            ->orderBy('id', 'desc')->limit(120)->get() as $lg) {
            $ledger[] = ['at' => $lg->created_at, 'type' => $lg->type, 'minutes' => (int) $lg->minutes,
                'after' => (int) $lg->balance_after, 'note' => $lg->note,
                'by' => $lg->admin_id ? Db::adminName($lg->admin_id) : null];
        }
    }
    $ct = Capsule::schema()->hasTable('mod_supportcontracts_clients')
        ? Capsule::table('mod_supportcontracts_clients')->where('userid', $uid9)->first() : null;
    out(['client' => $uid9, 'name' => clientLabel($uid9), 'state' => Cover::clientState($uid9),
        'ledger' => $ledger, 'uncovered' => Cover::uncoveredRows($uid9),
        'breakdown' => Cover::breakdown($uid9, $from9 . ' 00:00:00', date('Y-m-d', strtotime($to9 . ' +1 day')) . ' 00:00:00'),
        'from' => $from9, 'to' => $to9,
        'contract' => $ct ? ['enabled' => (int) $ct->enabled, 'label' => $ct->label,
            'priority' => (int) $ct->priority, 'report_email' => $ct->report_email,
            'report_freq' => $ct->report_freq ?: 'monthly', 'covered' => $ct->covered,
            'notes' => $ct->notes, 'sla_value' => (int) $ct->sla_response_value,
            'sla_unit' => $ct->sla_response_unit] : null,
        'rate' => (float) (Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')
            ->where('setting', 'hour_rate')->value('value') ?: 0)]);

case 'prepaid_save':                    // δημιουργία / επεξεργασία συμβολαίου
    $uid9 = (int) ($in['client'] ?? 0);
    if (!$uid9 || !Capsule::table('tblclients')->where('id', $uid9)->exists()) { fail('client'); }
    if (!Time::scReady()) { fail('Το module Support Contracts δεν είναι διαθέσιμο', 500); }
    $data9 = ['enabled' => !empty($in['enabled']) ? 1 : 0,
        'label' => mb_substr(trim((string) ($in['label'] ?? '')), 0, 100) ?: null,
        'priority' => min(2, max(0, (int) ($in['priority'] ?? 0))),
        'report_email' => mb_substr(trim((string) ($in['report_email'] ?? '')), 0, 255) ?: null,
        'covered' => mb_substr(trim((string) ($in['covered'] ?? '')), 0, 4000) ?: null,
        'notes' => mb_substr(trim((string) ($in['notes'] ?? '')), 0, 4000) ?: null];
    $freq9 = (string) ($in['report_freq'] ?? 'monthly');
    if (in_array($freq9, ['monthly', 'weekly', 'both', 'off'], true)
        && Capsule::schema()->hasColumn('mod_supportcontracts_clients', 'report_freq')) {
        $data9['report_freq'] = $freq9;
    }
    if (isset($in['sla_value'])) { $data9['sla_response_value'] = max(1, (int) $in['sla_value']); }
    if (isset($in['sla_unit']) && in_array($in['sla_unit'], ['hours', 'days'], true)) {
        $data9['sla_response_unit'] = $in['sla_unit'];
    }
    ScDb::saveContract($uid9, $data9);
    out(['ok' => true, 'state' => Cover::clientState($uid9)]);

case 'prepaid_move':                    // χειροκίνητη πίστωση / χρέωση
    $uid9 = (int) ($in['client'] ?? 0);
    $mins9 = (int) ($in['minutes'] ?? 0);
    if (!$uid9 || !$mins9) { fail('input'); }
    if (!Time::scReady() || !ScDb::contract($uid9)) { fail('Ο πελάτης δεν έχει συμβόλαιο προαγοράς'); }
    $type9 = $mins9 > 0 ? 'topup' : 'adjust';
    $note9 = mb_substr(trim((string) ($in['note'] ?? '')), 0, 200)
        ?: ($mins9 > 0 ? 'Χειροκίνητη πίστωση' : 'Χειροκίνητη διόρθωση');
    $bal9 = ScDb::applyMovement($uid9, $mins9, $type9, $note9, null, $adminId,
        'cpm-manual-' . $adminId . '-' . time());
    out(['ok' => true, 'balance' => (int) $bal9]);

case 'prepaid_offer':                   // ακάλυπτος χρόνος → προσφορά προς τον πελάτη
    $uid9 = (int) ($in['client'] ?? 0);
    $ids9 = array_values(array_filter(array_map('intval', (array) ($in['entries'] ?? []))));
    $rate9 = round((float) ($in['rate'] ?? 0), 2);
    if (!$uid9 || !$ids9) { fail('Διάλεξε τουλάχιστον μία καταχώρηση'); }
    if ($rate9 <= 0) { fail('Δώσε τιμή ανά ώρα'); }
    $rows9 = Capsule::table('mod_cpm_timelogs')->whereIn('id', $ids9)
        ->where('sc_userid', $uid9)->where('billable', 1)->get();
    $open9 = 0;
    $lines9 = [];
    foreach ($rows9 as $r9) {
        $o9 = (int) $r9->charged_minutes - (int) $r9->cover_minutes;
        if ($o9 <= 0) { continue; }
        $open9 += $o9;
        $t9 = Db::task((int) $r9->task_id);
        $lines9[] = '• ' . substr($r9->created_at, 0, 10) . ' — '
            . ($t9 ? $t9->title : 'Εργασία #' . (int) $r9->task_id) . ' · ' . Cover::fmt($o9);
    }
    if (!$open9) { fail('Οι καταχωρήσεις που διάλεξες είναι ήδη καλυμμένες'); }
    $amt9 = round($open9 / 60 * $rate9, 2);
    $oid9 = Capsule::table('mod_cpm_offers')->insertGetId([
        'title' => mb_substr(trim((string) ($in['title'] ?? '')) ?: ('Εργασίες εκτός προαγοράς — ' . date('m/Y')), 0, 200),
        'clientid' => $uid9, 'amount' => $amt9, 'stage' => 'draft', 'assignee' => $adminId,
        'covered_minutes' => $open9, 'created_by' => $adminId,
        'descr' => 'Χρόνος που δεν καλύφθηκε από προαγορά (' . Cover::fmt($open9) . ' × '
            . number_format($rate9, 2, ',', '.') . " €/ώρα):\n" . implode("\n", $lines9),
        'created_at' => date('Y-m-d H:i:s'), 'updated_at' => date('Y-m-d H:i:s')]);
    /* Οι καταχωρήσεις δεσμεύονται από τη στιγμή που μπαίνουν στην προσφορά —
       αλλιώς ο ίδιος ακάλυπτος χρόνος θα έμπαινε και σε δεύτερη. Αν η προσφορά
       χαθεί, ελευθερώνονται (δες `move_offer`). */
    foreach ($rows9 as $r9) {
        $o9 = (int) $r9->charged_minutes - (int) $r9->cover_minutes;
        if ($o9 <= 0) { continue; }
        Capsule::table('mod_cpm_timelogs')->where('id', (int) $r9->id)->update([
            'cover' => 'offer', 'cover_offer_id' => (int) $oid9,
            'cover_minutes' => (int) $r9->charged_minutes]);
    }
    Capsule::table('tbladdonmodules')->updateOrInsert(
        ['module' => 'cloudonprojects', 'setting' => 'hour_rate'], ['value' => (string) $rate9]);
    out(['ok' => true, 'offer' => (int) $oid9, 'minutes' => $open9, 'amount' => $amt9]);

case 'prepaid_report':                   // προεπισκόπηση αναφοράς περιόδου
case 'prepaid_report_send':              // …και αποστολή της
    $uid9 = (int) ($_GET['client'] ?? $in['client'] ?? 0);
    $f9 = preg_match('/^\d{4}-\d{2}-\d{2}$/', $_GET['from'] ?? $in['from'] ?? '')
        ? ($_GET['from'] ?? $in['from']) : date('Y-m-01', strtotime('-1 month'));
    $t9 = preg_match('/^\d{4}-\d{2}-\d{2}$/', $_GET['to'] ?? $in['to'] ?? '')
        ? ($_GET['to'] ?? $in['to']) : date('Y-m-d');
    if (!$uid9 || !Capsule::table('tblclients')->where('id', $uid9)->exists()) { fail('client'); }
    if ($action === 'prepaid_report') {
        $rp9 = Report::build($uid9, $f9, $t9);
        out(['subject' => $rp9['subject'], 'html' => $rp9['html'], 'to' => $rp9['to'], 'empty' => $rp9['empty']]);
    }
    $res9 = Report::send($uid9, $f9, $t9,
        Capsule::table('tbladmins')->where('id', $adminId)->value('username'));
    if (empty($res9['ok'])) { fail($res9['error'] ?? 'Δεν στάλθηκε', 500); }
    /* Η αποστολή γράφεται στις κινήσεις του πελάτη, ώστε να φαίνεται ποιος και
       πότε την έστειλε — αλλιώς δεν ξέρεις αν έφυγε δύο φορές. */
    if (Time::scReady() && ScDb::contract($uid9)) {
        ScDb::applyMovement($uid9, 0, 'adjust',
            'Στάλθηκε αναφορά περιόδου ' . date('d/m/Y', strtotime($f9)) . ' – ' . date('d/m/Y', strtotime($t9)),
            null, $adminId, 'cpm-report-' . $uid9 . '-' . $f9 . '-' . $t9);
    }
    out(['ok' => true, 'to' => $res9['to']]);
case 'prepaid_offer_cover':             // πόσο χρόνο καλύπτει μια προσφορά
    $oid9 = (int) ($in['offer'] ?? 0);
    if (!$oid9 || !Capsule::table('mod_cpm_offers')->where('id', $oid9)->exists()) { fail('offer'); }
    Capsule::table('mod_cpm_offers')->where('id', $oid9)
        ->update(['covered_minutes' => max(0, (int) ($in['minutes'] ?? 0)) ?: null,
            'updated_at' => date('Y-m-d H:i:s')]);
    out(['ok' => true]);

/* ================= ΟΜΑΔΕΣ ================= */
case 'teams':
    $teams = [];
    $assigned = [];
    foreach (Db::teams() as $tm) {
        $members = [];
        foreach (Db::teamMembers($tm->id) as $m) {
            $assigned[(int) $m->admin_id] = 1;
            $isF9 = Db::isFullAccess((int) $m->admin_id);
            $members[] = ['id' => (int) $m->admin_id, 'name' => Db::adminName($m->admin_id),
                'ini' => initials(Db::adminName($m->admin_id)),
                'role' => $m->role_title, 'leader' => (bool) $m->is_leader,
                'full' => $isF9,
                // Τι ΙΣΧΥΕΙ τελικά γι' αυτόν — ένωση όλων των ομάδων του + προσωπικά.
                'areas' => cnp_admin_areas((int) $m->admin_id, $isF9),
                // Ξεχωριστά τα προσωπικά, ώστε να φαίνεται γιατί έχει παραπάνω από την ομάδα.
                'personal' => array_values(array_intersect(cnp_perm_keys(),
                    array_filter(array_map('trim', explode(',', Db::pref((int) $m->admin_id, 'areas', '')))))),
                /* Τι του δίνουν οι ΑΛΛΕΣ του ομάδες. Αν αυτή εδώ δεν προσθέτει
                   τίποτα πάνω από εκείνες, η συμμετοχή είναι διακοσμητική και
                   αξίζει να το ξέρει αυτός που τη στήνει. */
                'otherAreas' => (function () use ($m, $tm) {
                    $o = [];
                    foreach (Capsule::table('mod_cpm_team_members as x')
                                 ->join('mod_cpm_teams as t2', 't2.id', '=', 'x.team_id')
                                 ->where('x.admin_id', (int) $m->admin_id)
                                 ->where('x.team_id', '<>', (int) $tm->id)
                                 ->pluck('t2.areas') as $raw) {
                        foreach (array_filter(array_map('trim', explode(',', (string) $raw))) as $a) { $o[$a] = 1; }
                    }
                    return array_keys($o);
                })()];
        }
        $projNames = Capsule::table('mod_cpm_project_teams as pt')
            ->join('mod_cpm_projects as p', 'p.id', '=', 'pt.project_id')
            ->where('pt.team_id', $tm->id)->pluck('p.name')->all();
        $teams[] = ['id' => (int) $tm->id, 'name' => $tm->name, 'color' => $tm->color,
            'descr' => $tm->descr, 'members' => $members, 'projects' => $projNames,
            'areas' => cnp_team_areas($tm->id),
            'depts' => array_map('intval', Capsule::table('mod_cpm_team_depts')
                ->where('team_id', $tm->id)->pluck('dept_id')->all())];
    }
    $solo = [];
    foreach (Db::admins() as $a) {
        if (!isset($assigned[(int) $a->id])) {
            $isF8 = Db::isFullAccess($a->id);
            $solo[] = ['id' => (int) $a->id, 'name' => trim($a->firstname . ' ' . $a->lastname),
                'full' => $isF8, 'areas' => cnp_admin_areas((int) $a->id, $isF8)];
        }
    }
    $rolesCfg = (string) (Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')
        ->where('setting', 'team_roles')->value('value')
        ?: 'Διαχειριστής έργου,Senior Τεχνικός,Τεχνικός,Υποστήριξη,Πωλήσεις,Λογιστήριο,Developer');
    /* Το δέντρο δικαιωμάτων: ενότητα → δυνατότητες. Η καρτέλα της ομάδας
       τσεκάρει δυνατότητες· το κλειδί της ενότητας σημαίνει «όλες». */
    $areaDefs = [];
    foreach (cnp_area_defs() as $k => $v) {
        $caps9 = [];
        foreach (cnp_caps_of($k) as $ck => $cv) {
            $caps9[] = ['id' => $ck, 'kind' => $cv[0], 'name' => $cv[1], 'descr' => $cv[2],
                'needs' => $cv[3] ?? null];
        }
        $areaDefs[] = ['id' => $k, 'name' => $v[0], 'descr' => $v[1], 'caps' => $caps9];
    }
    $presets9 = [];
    if (Capsule::schema()->hasTable('mod_cpm_perm_presets')) {
        foreach (Capsule::table('mod_cpm_perm_presets')->orderBy('sort')->orderBy('id')->get() as $p9) {
            $presets9[] = ['id' => (int) $p9->id, 'name' => $p9->name, 'descr' => $p9->descr,
                'caps' => array_values(array_filter(array_map('trim', explode(',', (string) $p9->caps))))];
        }
    }
    $strict9 = Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')
        ->where('setting', 'strict_areas')->value('value') === 'on';
    out(['teams' => $teams, 'solo' => $solo, 'areaDefs' => $areaDefs, 'strict' => $strict9,
        'presets' => $presets9,
        'depts' => array_map(function ($d) {
            return ['id' => $d['id'], 'name' => $d['name'], 'color' => $d['color']];
        }, cnp_depts()),
        'roles' => array_values(array_filter(array_map('trim', explode(',', $rolesCfg)))), 'canManage' => $FULL]);

case 'preset_save':                      // πρότυπο δικαιωμάτων (γεμίζει τα κουτάκια μιας ομάδας)
    $pid9 = (int) ($in['id'] ?? 0);
    $nm9 = mb_substr(trim((string) ($in['name'] ?? '')), 0, 60);
    if ($nm9 === '') { fail('Δώσε όνομα προτύπου'); }
    $row = ['name' => $nm9, 'descr' => mb_substr(trim((string) ($in['descr'] ?? '')), 0, 200) ?: null,
        'caps' => implode(',', cnp_perm_clean((array) ($in['caps'] ?? []))),
        'sort' => (int) ($in['sort'] ?? 0)];
    if ($pid9) {
        Capsule::table('mod_cpm_perm_presets')->where('id', $pid9)->update($row);
    } else {
        $row['created_at'] = date('Y-m-d H:i:s');
        $pid9 = Capsule::table('mod_cpm_perm_presets')->insertGetId($row);
    }
    out(['ok' => true, 'id' => (int) $pid9]);

case 'preset_del':
    Capsule::table('mod_cpm_perm_presets')->where('id', (int) ($in['id'] ?? 0))->delete();
    out(['ok' => true]);
case 'save_team':
    $row9 = ['name' => mb_substr(trim($in['name'] ?? ''), 0, 80) ?: 'Χωρίς όνομα',
        'color' => preg_match('/^#[0-9a-fA-F]{6}$/', $in['color'] ?? '') ? $in['color'] : '#0090dd',
        'descr' => mb_substr(trim($in['descr'] ?? ''), 0, 500)];
    /* Τα δικαιώματα γράφονται μόνο όταν σταλούν ρητά — αλλιώς μια αποθήκευση
       ονόματος θα τα μηδένιζε σιωπηλά. */
    if (array_key_exists('areas', $in)) {
        $row9['areas'] = implode(',', cnp_perm_clean((array) $in['areas']));
    }
    $tid = Db::saveTeam((int) ($in['id'] ?? 0), $row9);
    /* Ποια departments εξυπηρετεί η ομάδα — μόνο όταν σταλεί ρητά. */
    if (array_key_exists('depts', $in)) {
        $valid9 = array_column(cnp_depts(), 'id');
        Capsule::table('mod_cpm_team_depts')->where('team_id', $tid)->delete();
        foreach (array_unique(array_map('intval', (array) $in['depts'])) as $dd) {
            if (in_array($dd, $valid9, true)) {
                Capsule::table('mod_cpm_team_depts')->insert(['team_id' => $tid, 'dept_id' => $dd]);
            }
        }
    }
    out(['ok' => true, 'id' => $tid]);

case 'del_team':
    Db::deleteTeam((int) ($in['id'] ?? 0));
    out(['ok' => true]);

case 'team_member_add':
    $tid = (int) ($in['team'] ?? 0);
    $aid2 = (int) ($in['admin'] ?? 0);
    if (!$tid || !$aid2 || !Db::team($tid)) {
        fail('input');
    }
    Db::addTeamMember($tid, $aid2, mb_substr(trim($in['role'] ?? ''), 0, 60) ?: null, !empty($in['leader']) ? 1 : 0);
    out(['ok' => true]);

case 'team_member_del':
    Db::removeTeamMember((int) ($in['team'] ?? 0), (int) ($in['admin'] ?? 0));
    out(['ok' => true]);

/* ================= PROJECTS PORTFOLIO ================= */
case 'portfolio':
    $projs = [];
    $depts = [];
    foreach (Capsule::table('tblticketdepartments')->orderBy('order')->get(['id', 'name']) as $dp) {
        $depts[] = ['id' => (int) $dp->id, 'name' => $dp->name];
    }
    $src = $FULL ? Db::projects(true) : Db::projectsFor($adminId, true);
    $prodNames = Capsule::table('mod_cpm_products')->pluck('name', 'id')->all();
    $todoBy = [];
    try {
        foreach (Capsule::table('mod_cpm_project_todos')->groupBy('project_id')
            ->get(['project_id', Capsule::raw('COUNT(*) t'), Capsule::raw('SUM(done_at IS NOT NULL) d')]) as $r8) {
            $todoBy[(int) $r8->project_id] = [(int) $r8->d, (int) $r8->t];
        }
    } catch (\Throwable $e) {
    }
    $spentBy = [];
    try {
        foreach (Capsule::table('mod_cpm_timelogs as tl')
            ->join('mod_cpm_tasks as t', 't.id', '=', 'tl.task_id')
            ->where('tl.running', 0)
            ->groupBy('t.project_id')
            ->get([Capsule::raw('t.project_id as pid'), Capsule::raw('SUM(tl.minutes) as m')]) as $r9) {
            $spentBy[(int) $r9->pid] = (int) $r9->m;
        }
    } catch (\Throwable $e) {
    }
    foreach ($src as $p) {
        [$done, $total, $pct] = Db::projectProgress($p->id);
        $delta = Db::snapshotDelta($p->id, 7);
        $projs[] = ['id' => (int) $p->id, 'name' => $p->name, 'color' => $p->color,
            'kind' => $p->kind ?? 'dept',
            'budget' => $p->budget !== null ? (float) $p->budget : null,
            'estHours' => $p->est_hours !== null ? (float) $p->est_hours : null,
            'start' => $p->start_date, 'due' => $p->due_date,
            'manager' => isset($p->manager_id) && $p->manager_id ? (int) $p->manager_id : null,
            /* Οι ιδιωτικές σημειώσεις φεύγουν ΜΟΝΟ στον υπεύθυνο και στους
               διαχειριστές — για τους υπόλοιπους δεν υπάρχει καν το πεδίο. */
            'pmNotes' => ($FULL || (isset($p->manager_id) && (int) $p->manager_id === $adminId))
                ? (string) ($p->pm_notes ?? '') : null,
            'canPmNotes' => (bool) ($FULL || (isset($p->manager_id) && (int) $p->manager_id === $adminId)),
            'canEdit' => cnp_can_edit_project($adminId, $FULL, $p),
            'offerId' => $p->offer_id ? (int) $p->offer_id : null,
            'spentMins' => $spentBy[(int) $p->id] ?? 0,
            'todos' => $todoBy[(int) $p->id] ?? null,
            'client' => $p->clientid ? (int) $p->clientid : null, 'clientName' => clientLabel($p->clientid),
            'dept' => $p->deptid ? (int) $p->deptid : null, 'parent' => $p->parent_id ? (int) $p->parent_id : null,
            'product' => isset($p->product_id) && $p->product_id ? (int) $p->product_id : null,
            /* Το όνομα, όχι μόνο το id: στην εσωτερική ανάπτυξη η στήλη «προϊόν»
               αντικαθιστά τη στήλη «πελάτης» — εκεί δεν υπάρχει πελάτης. */
            'productName' => isset($p->product_id) && $p->product_id
                ? ($prodNames[(int) $p->product_id] ?? null) : null,
            'pstatus' => $p->pstatus, 'health' => $p->health, 'archived' => $p->status === 'archived',
            'visible' => (bool) $p->client_visible, 'done' => $done, 'total' => $total, 'pct' => $pct,
            'trend' => $delta ? $delta[1] - $delta[0] : null,
            'members' => $FULL ? Db::projectMembers($p->id) : [],
            'teams' => $FULL ? Db::projectTeams($p->id) : []];
    }
    $teamsL = [];
    foreach (Db::teams() as $tm) {
        $teamsL[] = ['id' => (int) $tm->id, 'name' => $tm->name, 'color' => $tm->color];
    }
    out(['projects' => $projs, 'depts' => $depts, 'teams' => $teamsL,
        'canManage' => $FULL,
        'canDelete' => cnp_has_cap($adminId, $FULL, 'projects.portfolio.delete'),
        'canShare' => cnp_has_cap($adminId, $FULL, 'projects.share'),
        'canRecur' => cnp_has_cap($adminId, $FULL, 'projects.recurring'),
        'canCreate' => cnp_can_create_project($adminId, $FULL)]);      // νέο έργο

case 'save_project':
    $pid = (int) ($in['id'] ?? 0);
    if ($pid) {
        if (!cnp_can_edit_project($adminId, $FULL, Db::project($pid))) {
            fail('Μόνο ο υπεύθυνος του έργου ή διαχειριστής μπορεί να το αλλάξει', 403);
        }
    } elseif (!cnp_can_create_project($adminId, $FULL)) {
        fail('Δεν έχεις πρόσβαση στην ενότητα «Έργα & υλοποιήσεις»', 403);
    }
    /* Η ραχοκοκαλιά: πελάτης → (προϊόν) → τμήμα → έργο. Σε ΝΕΟ έργο πελάτη πελάτης και
       τμήμα είναι υποχρεωτικά. Το ΠΡΟΪΟΝ είναι προαιρετικό (απόφαση 14/9/2026): υπάρχει
       δουλειά που δεν ταυτίζεται με είδος (μεταφορικές, marketplaces…) και δουλειά που
       ξεκινά πριν ανοίξει το είδος — δένεται αργότερα, και οι εργασίες την ακολουθούν. */
    /* Τρεις διαδρομές, όχι δύο (απόφαση 15/9/2026):
         client   — δουλειά ΓΙΑ πελάτη· πελάτης και τμήμα υποχρεωτικά
         internal — ΕΣΩΤΕΡΙΚΗ ΑΝΑΠΤΥΞΗ / R&D: εξέλιξη δικού μας προϊόντος ή νέα
                    έρευνα. ΔΕΝ έχει πελάτη — αν είχε, το κόστος της θα φαινόταν
                    ως δουλειά για εκείνον και θα μόλυνε και την καρτέλα του και
                    τα χρεώσιμα. Το «προϊόν» εδώ σημαίνει ΤΙ ΕΞΕΛΙΣΣΟΥΜΕ.
         dept     — παλιά ουρά τμήματος· μένει μόνο για τα υπάρχοντα. */
    $kind9 = in_array($in['kind'] ?? '', ['dept', 'client', 'internal'], true) ? $in['kind'] : 'dept';
    if (!$pid && $kind9 === 'client') {
        if (!(int) ($in['client'] ?? 0)) { fail('Διάλεξε πελάτη — χωρίς αυτόν το έργο δεν έχει θέση στην ιεραρχία'); }
        if (!(int) ($in['dept'] ?? 0)) { fail('Διάλεξε τμήμα — ποιο τμήμα αναλαμβάνει το έργο;'); }
    }
    if ($kind9 === 'internal' && !(int) ($in['dept'] ?? 0)) {
        fail('Διάλεξε τμήμα — ποιο τμήμα κάνει την ανάπτυξη;');
    }
    $data = ['name' => mb_substr(trim($in['name'] ?? ''), 0, 120) ?: 'Χωρίς όνομα',
        /* Εσωτερικό έργο ΔΕΝ κρατά πελάτη, ό,τι κι αν στάλθηκε από την οθόνη. */
        'clientid' => $kind9 === 'internal' ? null : ((int) ($in['client'] ?? 0) ?: null),
        'deptid' => (int) ($in['dept'] ?? 0) ?: null,
        'product_id' => (int) ($in['product'] ?? 0) ?: null,
        'color' => preg_match('/^#[0-9a-fA-F]{6}$/', $in['color'] ?? '') ? $in['color'] : '#0090dd',
        'descr' => cnp_clean_html($in['descr'] ?? '', 60000),   // rich-text
        /* Χωρίς πελάτη δεν υπάρχει portal να το δείξει — και δεν θέλουμε να διαρρεύσει
           ποτέ εσωτερική ανάπτυξη σε πελατειακή οθόνη. */
        'client_visible' => ($kind9 !== 'internal' && !empty($in['visible'])) ? 1 : 0,
        'parent_id' => ((int) ($in['parent'] ?? 0) && (int) $in['parent'] !== $pid) ? (int) $in['parent'] : null,
        'pstatus' => array_key_exists($in['pstatus'] ?? '', Db::projectStatuses()) ? $in['pstatus'] : null,
        'health' => array_key_exists($in['health'] ?? '', Db::healthColors()) ? $in['health'] : null,
        'kind' => $kind9,
        'budget' => ($in['budget'] ?? '') !== '' && $in['budget'] !== null
            ? round((float) str_replace(',', '.', (string) $in['budget']), 2) : null,
        'est_hours' => ($in['estHours'] ?? '') !== '' && $in['estHours'] !== null
            ? round((float) str_replace(',', '.', (string) $in['estHours']), 1) : null,
        // Υπεύθυνος έργου: σε αυτόν κλιμακώνουν οι προθεσμίες που χάνονται.
        'manager_id' => (int) ($in['manager'] ?? 0) ?: ($pid ? null : $adminId),
        'start_date' => preg_match('/^\d{4}-\d{2}-\d{2}$/', $in['start'] ?? '') ? $in['start'] : null,
        'due_date' => preg_match('/^\d{4}-\d{2}-\d{2}$/', $in['due'] ?? '') ? $in['due'] : null];

    /* Αναπρογραμματισμός: κρατάμε τις παλιές ημερομηνίες ΠΡΙΝ γραφτούν από πάνω.
       Χωρίς αυτό η μετάθεση ενός έργου ήταν αόρατη — κανείς δεν μάθαινε ότι η
       παράδοση έφυγε δύο εβδομάδες μπροστά. */
    $before9 = $pid ? Db::project($pid) : null;

    $pid = Db::saveProject($pid, $data);

    if ($before9) {
        cnp_log_reschedule($before9, $data, $adminId, trim((string) ($in['reschedReason'] ?? '')));
    }
    /* Έργο σε προϊόν που δεν φιγουράρει στον πελάτη (π.χ. πούλημα πριν τη χρέωση):
       το προϊόν μπαίνει στην καρτέλα του, αλλιώς το έργο θα κρεμόταν στο κενό. */
    if (!empty($data['product_id']) && !empty($data['clientid'])) {
        $has9 = Capsule::table('mod_cpm_client_products')->where('clientid', $data['clientid'])
            ->where('product_id', $data['product_id'])->first();
        if (!$has9) {
            Capsule::table('mod_cpm_client_products')->insert(['clientid' => $data['clientid'],
                'product_id' => $data['product_id'], 'source' => 'manual', 'status' => 'active',
                'services' => 0, 'created_at' => date('Y-m-d H:i:s')]);
        } elseif ($has9->status !== 'active') {
            Capsule::table('mod_cpm_client_products')->where('id', $has9->id)->update(['status' => 'active']);
        }
    }
    if (array_key_exists('members', $in)) {
        Db::saveProjectMembers($pid, (array) $in['members']);
    }
    if (array_key_exists('teams', $in)) {
        Db::saveProjectTeams($pid, (array) $in['teams']);
    }
    out(['ok' => true, 'id' => $pid]);

case 'project_from_offer':             // κερδισμένη προσφορά → έργο πελάτη
    if (!cnp_can_create_project($adminId, $FULL)) {
        fail('Δεν έχεις πρόσβαση στην ενότητα «Έργα & υλοποιήσεις»', 403);
    }
    $of9 = Capsule::table('mod_cpm_offers')->where('id', (int) ($in['offer'] ?? 0))->first();
    if (!$of9) {
        fail('offer', 404);
    }
    $ex9 = Capsule::table('mod_cpm_projects')->where('offer_id', $of9->id)->first(['id', 'name']);
    if ($ex9) {
        out(['ok' => true, 'id' => (int) $ex9->id, 'existing' => true]);
    }
    $amount9 = $of9->quoteid
        ? (float) (Capsule::table('tblquotes')->where('id', $of9->quoteid)->value('total') ?: 0)
        : (float) ($of9->amount ?: 0);
    $pid9 = Db::saveProject(0, [
        'name' => mb_substr('Έργο: ' . $of9->title, 0, 120),
        'kind' => 'client',
        'clientid' => $of9->clientid ?: null,
        'budget' => $amount9 ?: null,
        'offer_id' => (int) $of9->id,
        'pstatus' => 'new', 'health' => 'green',
        'color' => '#7b5cd6', 'client_visible' => 0,
        'descr' => "Δημιουργήθηκε από προσφορά #{$of9->id}" . ($of9->quoteid ? " / Quote #{$of9->quoteid}" : ''),
    ]);
    Db::saveTask(0, ['project_id' => $pid9, 'title' => 'Kick-off: πλάνο & ανάλυση έργου',
        'status_id' => Db::firstStatusId()], $adminId);
    if (function_exists('logActivity')) {
        logActivity('CPM: έργο #' . $pid9 . ' από προσφορά #' . $of9->id . ' (admin #' . $adminId . ')');
    }
    out(['ok' => true, 'id' => $pid9]);

case 'ptodos':                         // 📋 παραδοτέα/TODO έργου
    $pid7 = (int) ($_GET['project'] ?? 0);
    if (!$pid7 || !Db::canSeeProject($adminId, $pid7)) {
        fail('project', 403);
    }
    out(['todos' => array_map(function ($t) {
        return ['id' => (int) $t->id, 'title' => $t->title,
            'done' => (bool) $t->done_at,
            'doneBy' => $t->done_by ? Db::adminName($t->done_by) : null,
            'doneAt' => $t->done_at ? substr($t->done_at, 0, 10) : null];
    }, Capsule::table('mod_cpm_project_todos')->where('project_id', $pid7)
        ->orderBy('sort')->orderBy('id')->get()->all())]);

case 'ptodo_add':
    $pid7 = (int) ($in['project'] ?? 0);
    $t7 = mb_substr(trim($in['title'] ?? ''), 0, 255);
    if (!$pid7 || $t7 === '' || !Db::canSeeProject($adminId, $pid7)) {
        fail('input', 403);
    }
    $id7 = Capsule::table('mod_cpm_project_todos')->insertGetId(['project_id' => $pid7,
        'title' => $t7, 'created_by' => $adminId, 'created_at' => date('Y-m-d H:i:s'),
        'sort' => (int) Capsule::table('mod_cpm_project_todos')->where('project_id', $pid7)->max('sort') + 1]);
    out(['ok' => true, 'id' => $id7]);

case 'ptodo_toggle':
    $td = Capsule::table('mod_cpm_project_todos')->where('id', (int) ($in['id'] ?? 0))->first();
    if (!$td || !Db::canSeeProject($adminId, $td->project_id)) {
        fail('todo', 403);
    }
    Capsule::table('mod_cpm_project_todos')->where('id', $td->id)->update($td->done_at
        ? ['done_at' => null, 'done_by' => null]
        : ['done_at' => date('Y-m-d H:i:s'), 'done_by' => $adminId]);
    out(['ok' => true, 'done' => !$td->done_at]);

case 'ptodo_del':
    $td = Capsule::table('mod_cpm_project_todos')->where('id', (int) ($in['id'] ?? 0))->first();
    if (!$td || !Db::canSeeProject($adminId, $td->project_id)) {
        fail('todo', 403);
    }
    Capsule::table('mod_cpm_project_todos')->where('id', $td->id)->delete();
    out(['ok' => true]);

case 'archive_project':
    $p = Db::project((int) ($in['id'] ?? 0));
    if (!cnp_can_edit_project($adminId, $FULL, $p)) {
        fail('Μόνο ο υπεύθυνος του έργου ή διαχειριστής', 403);
    }
    if ($p) {
        Db::saveProject($p->id, ['status' => $p->status === 'archived' ? 'active' : 'archived']);
    }
    out(['ok' => (bool) $p]);

case 'project_pm_notes':                  // ιδιωτικές σημειώσεις υπεύθυνου έργου
    /* Ξεχωριστή ενέργεια επίτηδες: το `save_project` χτίζει ΟΛΑ τα πεδία από το
       input, οπότε μια κλήση «μόνο για τις σημειώσεις» θα μηδένιζε budget,
       ημερομηνίες, υπεύθυνο και τα υπόλοιπα. */
    $pp = Db::project((int) ($in['id'] ?? 0));
    if (!$pp) { fail('project', 404); }
    if (!$FULL && (int) $pp->manager_id !== $adminId) {
        fail('Μόνο ο υπεύθυνος του έργου κρατάει ιδιωτικές σημειώσεις', 403);
    }
    Capsule::table('mod_cpm_projects')->where('id', (int) $pp->id)
        ->update(['pm_notes' => mb_substr((string) ($in['notes'] ?? ''), 0, 20000)]);
    out(['ok' => true]);

case 'task_share':                       // Στείλε εργασία σε συνάδελφο (chat) ή σε email
    $t = Db::task((int) ($in['task'] ?? 0));
    if (!$t || !Db::canSeeTask($adminId, $t)) { fail('task', 404); }

    $viaS  = in_array($in['via'] ?? '', ['chat', 'email', 'both'], true) ? $in['via'] : 'chat';
    $toIds = array_values(array_unique(array_filter(array_map('intval', (array) ($in['to'] ?? [])))));
    $mailTo = trim((string) ($in['email'] ?? ''));
    $noteS = trim((string) ($in['note'] ?? ''));
    if ($mailTo !== '' && !filter_var($mailTo, FILTER_VALIDATE_EMAIL)) {
        fail('Μη έγκυρη διεύθυνση email');
    }
    if (!$toIds && $mailTo === '') { fail('Διάλεξε συνάδελφο ή γράψε διεύθυνση email'); }

    /* Η σύνοψη φτιάχνεται ΜΙΑ φορά: ο παραλήπτης πρέπει να καταλάβει τι του
       στέλνεις χωρίς να ανοίξει την εργασία — αλλιώς το «σου στέλνω αυτό» δεν
       λέει τίποτα περισσότερο από ένα link. */
    $projS = $t->project_id
        ? (string) Capsule::table('mod_cpm_projects')->where('id', $t->project_id)->value('name') : '';
    $cliS = '';
    if ($t->project_id) {
        $cidS = Capsule::table('mod_cpm_projects')->where('id', $t->project_id)->value('clientid');
        if ($cidS) { $cliS = (string) clientLabel((int) $cidS); }
    }
    $stS = (string) Capsule::table('mod_cpm_statuses')->where('id', $t->status_id)->value('title');
    $urlS = '/project/#/task/' . (int) $t->id;
    $absS = Notify::baseUrl() . $urlS;
    $meS = Db::adminName($adminId);

    $lines = [];
    if ($projS !== '') { $lines[] = 'Έργο: ' . $projS . ($cliS !== '' ? ' · ' . $cliS : ''); }
    if ($stS !== '')   { $lines[] = 'Κατάσταση: ' . $stS; }
    if ($t->assignee)  { $lines[] = 'Ανάδοχος: ' . Db::adminName((int) $t->assignee); }
    if ($t->due_date)  { $lines[] = 'Λήξη: ' . cnp_dgr($t->due_date); }

    $sentChat = 0; $sentMail = 0;
    if ($viaS === 'chat' || $viaS === 'both') {
        foreach ($toIds as $oth) {
            if ($oth === $adminId) { continue; }
            $chS = 'd' . min($adminId, $oth) . '-' . max($adminId, $oth);
            /* Η DB είναι utf8mb3: το 📋 (4-byte) αποθηκεύεται ως «????». Βάζουμε
               3-byte σύμβολο που επιβιώνει. */
            $bodyS = '☑ **#' . (int) $t->id . ' ' . $t->title . '**'
                . ($lines ? "\n" . implode(' · ', $lines) : '')
                . ($noteS !== '' ? "\n\n" . $noteS : '')
                . "\n" . $absS;
            Capsule::table('mod_cpm_chat')->insert(['channel' => $chS, 'admin_id' => $adminId,
                'body' => mb_substr($bodyS, 0, 4000), 'created_at' => date('Y-m-d H:i:s')]);
            Db::pushNotification($oth, 'comment',
                mb_substr('💬 ' . $meS . ' σου έστειλε την εργασία #' . (int) $t->id . ': ' . $t->title, 0, 240),
                $urlS);
            $sentChat++;
        }
    }
    if ($viaS === 'email' || $viaS === 'both') {
        $targets = [];
        foreach ($toIds as $oth) {
            $e = Notify::adminEmail($oth);
            if ($e) { $targets[$e] = Db::adminName($oth); }
        }
        if ($mailTo !== '') { $targets[$mailTo] = ''; }
        $htmlS = '<p><b>' . htmlspecialchars((string) $t->title, ENT_QUOTES, 'UTF-8') . '</b> (#' . (int) $t->id . ')</p>'
            . ($lines ? '<p>' . htmlspecialchars(implode(' · ', $lines), ENT_QUOTES, 'UTF-8') . '</p>' : '')
            . ($noteS !== '' ? '<p style="border-left:3px solid #0090dd;padding-left:10px;color:#3e506a">'
                . nl2br(htmlspecialchars($noteS, ENT_QUOTES, 'UTF-8')) . '</p>' : '')
            . '<p>Στάλθηκε από: ' . htmlspecialchars($meS, ENT_QUOTES, 'UTF-8') . '</p>'
            . '<p><a href="' . htmlspecialchars($absS, ENT_QUOTES, 'UTF-8')
            . '" style="background:#0090dd;color:#fff;padding:9px 16px;border-radius:8px;text-decoration:none;display:inline-block">Άνοιγμα εργασίας</a></p>';
        foreach ($targets as $addr => $nm) {
            try {
                if (Notify::sendTo($addr, 'Εργασία #' . (int) $t->id . ' — ' . mb_substr((string) $t->title, 0, 70), $htmlS)) {
                    $sentMail++;
                }
            } catch (\Throwable $e) { /* μια αποτυχία δεν ακυρώνει τις υπόλοιπες */ }
        }
    }
    Db::logActivity((int) $t->id, $adminId, 'edit',
        'Κοινοποίηση: ' . $sentChat . ' chat, ' . $sentMail . ' email');
    out(['ok' => true, 'chat' => $sentChat, 'mail' => $sentMail]);

case 'task_handoff':                     // Παράδοση σκυτάλης σε συνάδελφο
    $t = Db::task((int) ($in['task'] ?? 0));
    if (!$t || !Db::canSeeTask($adminId, $t)) { fail('task', 404); }
    if (!cnp_task_write_ok($adminId, $FULL, $t)) {
        fail('Χρειάζεται δικαίωμα «Board: επεξεργασία» — ή να είναι δική σου εργασία', 403);
    }
    $toH = (int) ($in['to'] ?? 0);
    if (!$toH || !Capsule::table('tbladmins')->where('id', $toH)->where('disabled', 0)->exists()) {
        fail('Διάλεξε σε ποιον παραδίδεις');
    }
    if ($toH === $adminId) { fail('Παραδίδεις στον εαυτό σου — διάλεξε άλλον συνάδελφο'); }
    $didH  = trim((string) ($in['did'] ?? ''));
    $nextH = trim((string) ($in['next'] ?? ''));
    if ($nextH === '') { fail('Γράψε τι πρέπει να κάνει — αλλιώς η παράδοση είναι απλώς μετακύλιση'); }

    /* Η παράδοση είναι ΔΥΟ πράγματα μαζί: κλείνει το δικό μου κομμάτι και
       ανοίγει το δικό του. Αν γραφόταν μόνο η ανάθεση, θα χανόταν το «τι έγινε
       ως εδώ» — που είναι ακριβώς αυτό που χρειάζεται ο επόμενος. */
    if ($didH !== '') {
        Db::addCheckItem((int) $t->id, mb_substr($didH, 0, 500), $adminId);
        Capsule::table('mod_cpm_checklist')->where('task_id', $t->id)
            ->orderBy('id', 'desc')->limit(1)->update(['done' => 1]);
    }
    Db::addCheckItem((int) $t->id, mb_substr($nextH, 0, 500), $adminId);

    /* Ίδιος κανόνας και στην παράδοση: αν περνά και η ανάθεση σε agent,
       χρειάζεται χρόνος υλοποίησης — αλλιώς η σκυτάλη πάει στο κενό. */
    if (!empty($in['move']) && cnp_assignee_needs_dates($toH, $adminId)) {
        $dueChk = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string) ($in['due'] ?? '')) ? $in['due'] : ($t->due_date ?: null);
        if (!$t->start_date || !$dueChk) {
            http_response_code(409);
            out(['error' => 'Για να περάσει η ανάθεση στον/στην ' . Db::adminName($toH)
                    . ' χρειάζεται έναρξη και λήξη.',
                'need' => 'dates', 'task' => (int) $t->id, 'assignee' => $toH,
                'start' => $t->start_date ?: null, 'due' => $dueChk]);
        }
    }

    $upd = ['action_user' => $toH];
    /* Η ανάθεση ακολουθεί τη σκυτάλη: αλλιώς ο φόρτος θα έδειχνε την εργασία
       ακόμη σε μένα ενώ τη δουλεύει άλλος. */
    if (!empty($in['move'])) { $upd['assignee'] = $toH; }
    $dueH = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string) ($in['due'] ?? '')) ? $in['due'] : null;
    if ($dueH) { $upd['due_date'] = $dueH; }
    Capsule::table('mod_cpm_tasks')->where('id', $t->id)->update($upd);

    $whoH = Db::adminName($adminId);
    $logH = 'Παράδοση σε ' . Db::adminName($toH)
        . ($didH !== '' ? ' · έγινε: ' . mb_substr($didH, 0, 120) : '')
        . ' · ζητείται: ' . mb_substr($nextH, 0, 120);
    Db::logActivity((int) $t->id, $adminId, 'assign', $logH);

    $urlH = '/project/#/task/' . (int) $t->id;
    Db::pushNotification($toH, 'action',
        mb_substr('Σου παραδόθηκε: ' . $t->title . ' — ' . $nextH, 0, 240), $urlH);
    try {
        $toMail = Notify::adminEmail($toH);
        if ($toMail) {
            Notify::sendTo($toMail, 'Σου παραδόθηκε εργασία — ' . mb_substr((string) $t->title, 0, 70),
                '<p><b>' . htmlspecialchars((string) $t->title, ENT_QUOTES, 'UTF-8') . '</b> (#' . (int) $t->id . ')</p>'
                . ($didH !== '' ? '<p><b>Τι έγινε ως εδώ:</b><br>' . nl2br(htmlspecialchars($didH, ENT_QUOTES, 'UTF-8')) . '</p>' : '')
                . '<p><b>Τι χρειάζεται από εσένα:</b><br>' . nl2br(htmlspecialchars($nextH, ENT_QUOTES, 'UTF-8')) . '</p>'
                . ($dueH ? '<p>Προθεσμία: <b>' . cnp_dgr($dueH) . '</b></p>' : '')
                . '<p>Από: ' . htmlspecialchars($whoH, ENT_QUOTES, 'UTF-8') . '</p>'
                . '<p><a href="' . htmlspecialchars(Notify::baseUrl() . $urlH, ENT_QUOTES, 'UTF-8')
                . '" style="background:#0090dd;color:#fff;padding:9px 16px;border-radius:8px;text-decoration:none;display:inline-block">Άνοιγμα εργασίας</a></p>');
        }
    } catch (\Throwable $e) { /* το email δεν ακυρώνει την παράδοση */ }
    Notify::watchers((int) $t->id, $adminId, $t->title . ' → παραδόθηκε σε ' . Db::adminName($toH), null);

    out(['ok' => true, 'to' => $toH, 'name' => Db::adminName($toH)]);

case 'task_delete':
    $t = Db::task((int) ($in['id'] ?? 0));
    if (!$t) { fail('task', 404); }
    list($canDel, $whyDel) = cnp_task_delete_right($t, $adminId, $FULL);
    if (!$canDel) { fail($whyDel, 403); }

    $tid = (int) $t->id;
    $tTitle = (string) $t->title;
    $tProj = (int) $t->project_id;
    /* Τι χάνεται μαζί — μπαίνει στην ειδοποίηση των διαχειριστών, ώστε η
       διαγραφή να μη φαίνεται «αθώα» όταν δεν ήταν. */
    $lostMins = (int) Capsule::table('mod_cpm_timelogs')->where('task_id', $tid)->sum('minutes');
    $lostCmts = (int) Capsule::table('mod_cpm_comments')->where('task_id', $tid)->count();

    /* Τα αρχεία φεύγουν μέσω Storage ώστε να σβήσει και το φυσικό blob,
       όχι μόνο η εγγραφή. */
    foreach (Capsule::table('mod_cpm_files')->where('task_id', $tid)->pluck('id') as $fid) {
        try { Storage::delete((int) $fid); } catch (\Throwable $e) { /* ένα ορφανό αρχείο δεν μπλοκάρει τη διαγραφή */ }
    }
    /* Συνημμένα του νέου μηχανισμού (Storage): του ζητουμένου, των ενεργειών και των
       μηνυμάτων — μαζί με το φυσικό αρχείο στο cloud. Και οι αντιδράσεις των ενεργειών. */
    $ckIdsD = Capsule::table('mod_cpm_checklist')->where('task_id', $tid)->pluck('id')->all();
    $cmIdsD = Capsule::table('mod_cpm_comments')->where('task_id', $tid)->pluck('id')->all();
    $stQ = Capsule::table('mod_cpm_storage')->where('module', 'task')->where(function ($w) use ($tid, $ckIdsD, $cmIdsD) {
        $w->where(function ($x) use ($tid) { $x->where('ref_type', 'task')->where('ref_id', $tid); });
        if ($ckIdsD) { $w->orWhere(function ($x) use ($ckIdsD) { $x->where('ref_type', 'check')->whereIn('ref_id', $ckIdsD); }); }
        if ($cmIdsD) { $w->orWhere(function ($x) use ($cmIdsD) { $x->where('ref_type', 'comment')->whereIn('ref_id', $cmIdsD); }); }
    });
    foreach ($stQ->pluck('id') as $sid) { try { Storage::delete((int) $sid); } catch (\Throwable $e) { } }
    if ($ckIdsD && Capsule::schema()->hasTable('mod_cpm_check_react')) { Capsule::table('mod_cpm_check_react')->whereIn('check_id', $ckIdsD)->delete(); }
    foreach (['mod_cpm_activity', 'mod_cpm_checklist', 'mod_cpm_comments', 'mod_cpm_deps',
                 'mod_cpm_field_values', 'mod_cpm_files', 'mod_cpm_help', 'mod_cpm_interactions',
                 'mod_cpm_reminders', 'mod_cpm_timelogs', 'mod_cpm_watchers'] as $tb) {
        if (Capsule::schema()->hasTable($tb)) { Capsule::table($tb)->where('task_id', $tid)->delete(); }
    }
    /* Εξαρτήσεις προς ΚΑΙ από την εργασία — αλλιώς άλλες εργασίες μένουν
       μπλοκαρισμένες από κάτι που δεν υπάρχει πια. */
    Capsule::table('mod_cpm_deps')->where('depends_on', $tid)->delete();
    Capsule::table('mod_cpm_tasks')->where('id', $tid)->delete();

    /* Πρόχειρο που ακυρώθηκε αμέσως (άνοιξε κατά λάθος, ✕ → «Όχι»): δεν είναι
       «διαγραφή» που πρέπει να μάθουν οι διαχειριστές — μόνο ίχνος στο log. */
    if (!empty($in['draft']) && (int) $t->created_by === $adminId && (time() - (int) strtotime((string) $t->created_at)) < 900) {
        logActivity('CloudOn PM: ακυρώθηκε πρόχειρη εργασία #' . $tid . ' «' . mb_substr($tTitle, 0, 70) . '» από ' . Db::adminName($adminId));
        out(['ok' => true, 'project' => $tProj, 'draft' => true]);
    }
    /* Κάθε διαγραφή φτάνει στους διαχειριστές. Ο ίδιος ο δράστης δεν
       ειδοποιείται για τη δική του πράξη. */
    $who = Db::adminName($adminId);
    $extra = [];
    if ($lostMins) {
        $extra[] = $lostMins >= 60
            ? round($lostMins / 60, 1) . 'ω καταγεγραμμένου χρόνου'
            : $lostMins . '\' καταγεγραμμένου χρόνου';
    }
    if ($lostCmts) { $extra[] = $lostCmts . ' σχόλια'; }
    $msg = 'Διαγράφηκε εργασία #' . $tid . ' «' . mb_substr($tTitle, 0, 70) . '» από ' . $who
        . ($extra ? ' — μαζί με ' . implode(' και ', $extra) : '');
    foreach (cnp_full_admin_ids() as $aid) {
        if ($aid === $adminId) { continue; }
        Db::pushNotification($aid, 'deleted', mb_substr($msg, 0, 240),
            $tProj ? '/project/#/board/' . $tProj : '/project/#/projects');
    }
    logActivity('CloudOn PM: ' . $msg . ' (admin ' . $adminId . ')');
    out(['ok' => true, 'project' => $tProj]);

case 'project_delete':
    $p = Db::project((int) ($in['id'] ?? 0));
    if (!$p) { fail('project', 404); }
    $tIds = Capsule::table('mod_cpm_tasks')->where('project_id', $p->id)->pluck('id')->all();
    /* Χωρίς ρητή επιβεβαίωση δεν σβήνουμε έργο που έχει εργασίες — η διαγραφή
       παίρνει μαζί χρόνο, σχόλια, checklists και ιστορικό. */
    if ($tIds && empty($in['withTasks'])) {
        fail('Το έργο έχει ' . count($tIds) . ' εργασίες', 409);
    }
    foreach (['mod_cpm_activity', 'mod_cpm_comments', 'mod_cpm_checklist', 'mod_cpm_timelogs',
                 'mod_cpm_watchers', 'mod_cpm_deps', 'mod_cpm_task_deps', 'mod_cpm_ticket_idle'] as $tb) {
        if ($tIds && Capsule::schema()->hasTable($tb)) {
            $col = Capsule::schema()->hasColumn($tb, 'task_id') ? 'task_id'
                : (Capsule::schema()->hasColumn($tb, 'tid') ? 'tid' : null);
            if ($col) { Capsule::table($tb)->whereIn($col, $tIds)->delete(); }
        }
    }
    foreach (['mod_cpm_expenses', 'mod_cpm_fields', 'mod_cpm_project_members', 'mod_cpm_project_shares',
                 'mod_cpm_project_teams', 'mod_cpm_project_todos', 'mod_cpm_recurring',
                 'mod_cpm_share_comments', 'mod_cpm_snapshots', 'mod_cpm_todos', 'mod_cpm_worknote'] as $tb) {
        if (Capsule::schema()->hasTable($tb)) {
            Capsule::table($tb)->where('project_id', $p->id)->delete();
        }
    }
    Capsule::table('mod_cpm_tasks')->where('project_id', $p->id)->delete();
    /* Υπο-έργα ανεβαίνουν ένα επίπεδο αντί να μείνουν ορφανά. */
    Capsule::table('mod_cpm_projects')->where('parent_id', $p->id)
        ->update(['parent_id' => $p->parent_id ? (int) $p->parent_id : null]);
    Capsule::table('mod_cpm_projects')->where('id', $p->id)->delete();
    logActivity('CloudOn PM: διαγραφή έργου «' . $p->name . '» (' . count($tIds) . ' εργασίες) από admin ' . $adminId);
    out(['ok' => true, 'tasks' => count($tIds)]);

case 'recurring':
    $recs = [];
    foreach (Db::recurringAll() as $r) {
        $recs[] = ['id' => (int) $r->id, 'title' => $r->title, 'project' => (int) $r->project_id,
            'pname' => cnp_pn($r->project_name), 'pcolor' => $r->project_color ?: '#8595ac',
            'freq' => $r->freq, 'every' => (int) $r->every, 'next' => $r->next_run,
            'dueDays' => (int) $r->due_days, 'assignee' => $r->assignee ? (int) $r->assignee : null,
            'prio' => (int) $r->priority, 'active' => (bool) $r->active, 'last' => $r->last_run];
    }
    out(['recurring' => $recs]);

case 'save_recurring':
    $freq = in_array($in['freq'] ?? '', ['daily', 'weekly', 'monthly', 'yearly'], true) ? $in['freq'] : 'monthly';
    Db::saveRecurring((int) ($in['id'] ?? 0), [
        'project_id' => (int) ($in['project'] ?? 0),
        'title' => mb_substr(trim($in['title'] ?? ''), 0, 200) ?: 'Χωρίς τίτλο',
        'descr' => cnp_clean_html($in['descr'] ?? '', 60000),   // rich-text
        'priority' => min(2, max(0, (int) ($in['prio'] ?? 0))),
        'assignee' => (int) ($in['assignee'] ?? 0) ?: null,
        'freq' => $freq, 'every' => max(1, (int) ($in['every'] ?? 1)),
        'next_run' => preg_match('/^\d{4}-\d{2}-\d{2}$/', $in['next'] ?? '') ? $in['next'] : date('Y-m-d'),
        'due_days' => max(0, (int) ($in['dueDays'] ?? 0)),
        'active' => !empty($in['active']) ? 1 : 0]);
    out(['ok' => true]);

case 'del_recurring':
    Db::deleteRecurring((int) ($in['id'] ?? 0));
    out(['ok' => true]);

/* ================= TICKET INBOX ================= */
case 'tickets':
    $view = $_GET['view'] ?? 'open';
    $q = trim($_GET['q'] ?? '');
    $fArea = (int) ($_GET['area'] ?? 0);
    $fCause = (int) ($_GET['cause'] ?? 0);
    $tq = Capsule::table('tbltickets');
    if (($fArea || $fCause) && $view !== 'mine' && $view !== 'unassigned') {
        $tq->orderBy('lastreply', 'desc');   // φίλτρο κατηγορίας: όλα τα statuses
    } elseif ($view === 'closed') {
        $tq->where('status', 'Closed')->orderBy('lastreply', 'desc');
    } else {
        $tq->whereNotIn('status', ['Closed', 'Cancelled'])->orderBy('lastreply', 'desc');
        if ($view === 'mine') {
            $tq->where('flag', $adminId);
        } elseif ($view === 'unassigned') {
            $tq->where(function ($w) { $w->where('flag', 0)->orWhereNull('flag'); });
        }
    }
    if (!$FULL && $view !== 'unassigned') {
        $tq->where('flag', $adminId); // agents: δικά τους (+ αδέσποτα στο unassigned)
    }
    if ($q !== '') {
        $like = '%' . $q . '%';
        $tq->where(function ($w) use ($like) {
            $w->where('title', 'like', $like)->orWhere('tid', 'like', $like)->orWhere('name', 'like', $like);
        });
    }
    if ($fArea || $fCause) {
        $tq->whereIn('tbltickets.id', function ($sub) use ($fArea, $fCause) {
            $sub->select('ticketid')->from('mod_cpm_ticket_class');
            if ($fArea) { $sub->where('area_id', $fArea); }
            if ($fCause) { $sub->where('cause_id', $fCause); }
        });
    }
    $rows = $tq->limit(100)->get(['id', 'tid', 'did', 'userid', 'name', 'title', 'status', 'urgency',
        'date', 'lastreply', 'flag', 'adminunread', 'clientunread']);
    $classMap = [];
    if (count($rows)) {
        foreach (Capsule::table('mod_cpm_ticket_class')->whereIn('ticketid', $rows->pluck('id')->all())->get() as $cl) {
            $classMap[(int) $cl->ticketid] = $cl;
        }
    }
    // SLA map
    $slaMap = [];
    try {
        if (count($rows) && Capsule::schema()->hasTable('mod_supportcontracts_tickets')) {
            foreach (Capsule::table('mod_supportcontracts_tickets')->whereIn('ticketid', $rows->pluck('id')->all())
                ->get(['ticketid', 'sla_due', 'first_response_at']) as $s) {
                $slaMap[(int) $s->ticketid] = $s;
            }
        }
    } catch (\Throwable $e) {
    }
    /* Ποιος περιμένει ποιον: αν το τελευταίο μήνυμα είναι του πελάτη περιμένει
       ΕΜΑΣ· αν είναι δικό μας, η μπάλα πήγε στον πελάτη. Το δεύτερο δεν είναι
       εκκρεμότητά μας — αλλά μετά από μέρες σιωπής θέλει υπενθύμιση, γι' αυτό
       φαίνεται ξεχωριστά αντί να χαθεί. */
    $list = [];
    foreach ($rows as $tk) {
        $lastRep = Capsule::table('tblticketreplies')->where('tid', $tk->id)->orderBy('id', 'desc')
            ->first(['admin', 'date']);
        $waiting = (!$lastRep || $lastRep->admin === null || $lastRep->admin === '');
        $sinceTs = strtotime((string) (($lastRep ? $lastRep->date : null) ?: $tk->date));
        $waitH = max(0, (int) floor((time() - $sinceTs) / 3600));
        if ($view === 'waiting' && !$waiting) {
            continue;
        }
        if ($view === 'wclient' && $waiting) {
            continue;
        }
        $s = $slaMap[(int) $tk->id] ?? null;
        $list[] = ['id' => (int) $tk->id, 'tid' => $tk->tid, 'title' => $tk->title,
            'client' => $tk->userid ? clientLabel($tk->userid) : $tk->name,
            'status' => $tk->status, 'urgency' => $tk->urgency,
            'last' => $tk->lastreply, 'age' => (int) floor((time() - strtotime($tk->date)) / 86400),
            'flag' => (int) $tk->flag ?: null, 'unread' => (bool) $tk->adminunread,
            'waiting' => $waiting,
            'waitOn' => $waiting ? 'us' : 'client',
            'waitH' => $waitH,
            'slaDue' => ($s && $s->sla_due && !$s->first_response_at) ? $s->sla_due : null,
            'area' => isset($classMap[(int) $tk->id]) ? (int) $classMap[(int) $tk->id]->area_id ?: null : null,
            'cause' => isset($classMap[(int) $tk->id]) ? (int) $classMap[(int) $tk->id]->cause_id ?: null : null];
    }
    /* Τα χρώματα καταστάσεων τα χρειάζεται ΚΑΙ η λίστα (21/9/2026): χωρίς αυτά η οθόνη
       έσκαγε σε κάθε προβολή με tickets. */
    $stColL = Capsule::table('tblticketstatuses')->pluck('color', 'title')->all();
    out(['statusColors' => $stColL, 'tickets' => $list, 'cats' => cnp_ticket_cats()]);

case 'ticket':
    $tid = (int) ($_GET['id'] ?? 0);
    $tk = Capsule::table('tbltickets')->where('id', $tid)->first();
    if (!$tk) {
        fail('ticket', 404);
    }
    if (!$FULL && (int) $tk->flag !== $adminId && (int) $tk->flag !== 0) {
        fail('ticket', 403);
    }
    $attList = function ($str, $rid) {
        $out = [];
        foreach (array_values(array_filter(explode('|', (string) $str))) as $i => $f) {
            $out[] = ['i' => $i, 'rid' => $rid,
                'name' => preg_replace('/^\\d+_/', '', $f)];
        }
        return $out;
    };
    $conv = [[
        'by' => $tk->name ?: clientLabel($tk->userid), 'admin' => false,
        'at' => $tk->date, 'body' => $tk->message, 'att' => $attList($tk->attachment ?? '', 0),
    ]];
    /* Ψευδώνυμο: ποιες απαντήσεις γράφτηκαν «ως Support Team» και από ποιον
       πραγματικά — ώστε εσωτερικά να φαίνεται ο αληθινός συντάκτης. */
    $aliasMap = [];
    if (Capsule::schema()->hasTable('mod_cpm_ticket_alias')) {
        foreach (Capsule::table('mod_cpm_ticket_alias')->where('tid', $tid)
                     ->get(['reply_id', 'real_admin_id']) as $ar) {
            $aliasMap[(int) $ar->reply_id] = (int) $ar->real_admin_id;
        }
    }
    $aliasName = '';
    if ($aliasMap) {
        $au = (string) (Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')
            ->where('setting', 'ticket_alias_admin')->value('value') ?: 'support');
        $ad = Capsule::table('tbladmins')->where('username', $au)->first(['firstname', 'lastname']);
        $aliasName = $ad ? trim($ad->firstname . ' ' . $ad->lastname) : 'Support Team';
    }
    foreach (Capsule::table('tblticketreplies')->where('tid', $tid)->orderBy('id')->get() as $r) {
        $reply = ['by' => $r->admin ?: ($r->name ?: clientLabel($r->userid)),
            'admin' => $r->admin !== '' && $r->admin !== null, 'at' => $r->date, 'body' => $r->message,
            'att' => $attList($r->attachment ?? '', (int) $r->id)];
        if (isset($aliasMap[(int) $r->id])) {
            $reply['by'] = Db::adminName($aliasMap[(int) $r->id]);   // εσωτερικά: ο πραγματικός συντάκτης
            $reply['alias'] = $aliasName ?: 'Support Team';          // δημόσια εμφανίστηκε ως…
        }
        $conv[] = $reply;
    }
    // εσωτερική συνομιλία (linked task comments)
    $task = Db::taskForTicket($tid);
    $notes = [];
    if ($task) {
        foreach (Db::comments($task->id) as $c) {
            $notes[] = ['by' => Db::adminName($c->admin_id), 'byId' => (int) $c->admin_id,
                'to' => $c->to_admin !== null ? (int) $c->to_admin : null,
                'at' => $c->created_at, 'body' => $c->comment];
        }
    }
    $sla = null;
    try {
        if (Capsule::schema()->hasTable('mod_supportcontracts_tickets')) {
            $s = Capsule::table('mod_supportcontracts_tickets')->where('ticketid', $tid)->first(['sla_due', 'first_response_at']);
            if ($s && $s->sla_due && !$s->first_response_at) {
                $sla = $s->sla_due;
            }
        }
    } catch (\Throwable $e) {
    }
    // 💡 αυτόματες προτάσεις: KB λύσεις + παρόμοια tickets που λύθηκαν
    $suggest = ['kb' => [], 'similar' => [], 'repeat' => 0];
    try {
        $tw0 = cnp_words($tk->title . ' ' . mb_substr($tk->message, 0, 600));
        if ($tw0) {
            /* Ζυγισμένο ταίριασμα (βλ. cnp_kb_suggest): σπάνιες λέξεις μετράνε,
               κοινές όχι· ψάχνει και στο σώμα της λύσης· κάτω από το κατώφλι
               δεν προτείνει τίποτα, γιατί λάθος άρθρο είναι χειρότερο από κανένα. */
            $suggest['kb'] = cnp_kb_suggest($tk->title . ' ' . mb_substr($tk->message, 0, 800), 3);
            /* Ταιριάζουμε τίτλο ΚΑΙ σώμα του παλιού αιτήματος: ο ίδιος πελάτης
               σπάνια γράφει τον ίδιο τίτλο δύο φορές, αλλά περιγράφει το ίδιο
               πρόβλημα. Με μόνο τον τίτλο χάναμε τις επαναλήψεις. */
            $suggest['similar'] = cnp_similar_tickets($tid, $tk, $tw0);
            $suggest['repeat'] = count(array_filter($suggest['similar'], function ($x) { return $x['same']; }));
        }
    } catch (\Throwable $e) {
    }
    // 🎟 χρήση/όριο tickets της ομάδας του πελάτη (τρέχων μήνας)
    $tq9 = null;
    if ($tk->userid) {
        try {
            $pk9 = (int) Capsule::table('mod_cpm_client_package')->where('clientid', $tk->userid)->value('package_id');
            $qr9 = $pk9 ? Capsule::table('mod_cpm_support_packages')->where('id', $pk9)->first() : null;
            if ($qr9 && (int) $qr9->t_month > 0) {
                $m0 = date('Y-m-01 00:00:00');
                $used9 = Capsule::table('tbltickets')->where('userid', $tk->userid)->where('date', '>=', $m0)->count();
                $ph9 = Capsule::table('mod_cpm_ticket_usage')->where('userid', $tk->userid)
                    ->where('channel', 'phone')->where('created_at', '>=', $m0)->count();
                $em9 = Capsule::table('mod_cpm_ticket_usage')->where('userid', $tk->userid)
                    ->where('channel', 'email')->where('created_at', '>=', $m0)->count();
                $tq9 = ['used' => $used9, 'quota' => (int) $qr9->t_month, 'package' => $qr9->name,
                    'email' => ['u' => $em9, 'q' => (int) $qr9->email_month],
                    'phone' => ['u' => $ph9, 'q' => (int) $qr9->phone_month],
                    'over' => $used9 > (int) $qr9->t_month];
            }
        } catch (\Throwable $e) {
        }
    }
    $statuses = Capsule::table('tblticketstatuses')->orderBy('sortorder')->pluck('title')->all();
    $statusColors = Capsule::table('tblticketstatuses')->pluck('color', 'title')->all();

    /* ── Συμφραζόμενα πελάτη ──────────────────────────────────────────────
       Χωρίς αυτά ο τεχνικός βλέπει μόνο επωνυμία και κείμενο: δεν ξέρει σε
       ποια από τις υπηρεσίες του πελάτη αναφέρεται, ούτε πώς να τον βρει.
       Τα μαζεύουμε εδώ ώστε να μη χρειάζεται να ανοίξει το WHMCS παράλληλα. */
    $ctx = null;
    if ((int) $tk->userid) {
        $cl = Capsule::table('tblclients')->where('id', (int) $tk->userid)->first();
        if ($cl) {
            // Το πεδίο service κρατάει «S<id>» για υπηρεσία, «D<id>» για domain.
            $relId = 0;
            $relKind = '';
            if (preg_match('/^([SD])(\d+)$/', (string) $tk->service, $m9)) {
                $relKind = $m9[1];
                $relId = (int) $m9[2];
            }

            $svc = [];
            foreach (Capsule::table('tblhosting')->where('userid', $cl->id)
                         ->orderByRaw("FIELD(domainstatus,'Active','Suspended','Pending','Terminated','Cancelled','Fraud')")
                         ->orderBy('id', 'desc')->get() as $h9) {
                $svc[] = [
                    'id'      => (int) $h9->id,
                    'name'    => (string) (Capsule::table('tblproducts')->where('id', $h9->packageid)->value('name') ?: '—'),
                    'domain'  => (string) $h9->domain,
                    'status'  => (string) $h9->domainstatus,
                    'nextdue' => $h9->nextduedate && $h9->nextduedate !== '0000-00-00' ? $h9->nextduedate : null,
                    'ip'      => (string) $h9->dedicatedip,
                    'related' => ($relKind === 'S' && (int) $h9->id === $relId),
                ];
            }

            $dom = [];
            foreach (Capsule::table('tbldomains')->where('userid', $cl->id)
                         ->orderBy('id', 'desc')->limit(20)->get() as $d9) {
                $dom[] = ['id' => (int) $d9->id, 'domain' => (string) $d9->domain,
                    'status' => (string) $d9->status, 'expiry' => $d9->expirydate,
                    'related' => ($relKind === 'D' && (int) $d9->id === $relId)];
            }

            $ctx = [
                'id'       => (int) $cl->id,
                'name'     => trim($cl->firstname . ' ' . $cl->lastname),
                'company'  => (string) $cl->companyname,
                'email'    => (string) $cl->email,
                'phone'    => (string) $cl->phonenumber,
                'country'  => (string) $cl->country,
                'city'     => (string) $cl->city,
                'status'   => (string) $cl->status,
                'since'    => substr((string) $cl->datecreated, 0, 10),
                'ip'       => (string) ($tk->ipaddress ?? ''),
                'services' => $svc,
                'domains'  => $dom,
                // Ο επικοινωνών μπορεί να είναι υπο-επαφή, όχι ο κάτοχος.
                'contact'  => (int) $tk->contactid
                    ? (function ($cid) {
                        $c9 = Capsule::table('tblcontacts')->where('id', $cid)->first();
                        return $c9 ? ['name' => trim($c9->firstname . ' ' . $c9->lastname), 'email' => $c9->email] : null;
                    })((int) $tk->contactid)
                    : null,
                'openTickets' => (int) Capsule::table('tbltickets')->where('userid', $cl->id)
                    ->whereNotIn('status', ['Closed'])->count(),
                'unpaid' => (float) Capsule::table('tblinvoices')->where('userid', $cl->id)
                    ->where('status', 'Unpaid')->sum('total'),
            ];
        }
    } elseif ($tk->email || $tk->name) {
        // Ticket από μη εγγεγραμμένο — ό,τι ξέρουμε είναι στο ίδιο το ticket.
        $ctx = ['id' => null, 'name' => (string) $tk->name, 'email' => (string) $tk->email,
            'ip' => (string) ($tk->ipaddress ?? ''), 'guest' => true,
            'services' => [], 'domains' => []];
    }

    out(['ctx' => $ctx,
        'ticket' => ['id' => $tid, 'tid' => $tk->tid, 'title' => $tk->title,
            'client' => $tk->userid ? clientLabel($tk->userid) : $tk->name, 'clientId' => (int) $tk->userid ?: null,
            'email' => $tk->email, 'status' => $tk->status, 'urgency' => $tk->urgency,
            'flag' => (int) $tk->flag ?: null, 'dept' => (int) $tk->did, 'slaDue' => $sla],
        'suggest' => $suggest, 'quota' => $tq9,
        'class' => (function () use ($tid) {
            $cl = Capsule::table('mod_cpm_ticket_class')->where('ticketid', $tid)->first();
            return ['area' => $cl && $cl->area_id ? (int) $cl->area_id : null,
                'cause' => $cl && $cl->cause_id ? (int) $cl->cause_id : null,
                'note' => $cl->note ?? null,
                'by' => $cl && $cl->classified_by ? Db::adminName($cl->classified_by) : null];
        })(),
        'cats' => cnp_ticket_cats(),
        'conv' => $conv, 'notes' => $notes,
        'task' => $task ? (int) $task->id : null,
        'statuses' => $statuses, 'statusColors' => $statusColors]);

case 'ticket_reply':
    if (!empty($_FILES)) {          // multipart (με συνημμένα) → πεδία από $_POST
        $in = $_POST;
    }
    $tid = (int) ($in['ticket'] ?? 0);
    $msg = trim($in['body'] ?? '');
    $tk = Capsule::table('tbltickets')->where('id', $tid)->first(['flag', 'tid']);
    if (!$tk || $msg === '') {
        fail('input');
    }
    if (!$FULL && (int) $tk->flag !== $adminId && (int) $tk->flag !== 0) {
        fail('ticket', 403);
    }
    if (!cnp_can_reply_clients($adminId, $FULL)) {
        fail('Μόνο ο επικεφαλής ομάδας ή διαχειριστής απαντά στον πελάτη — χρησιμοποίησε εσωτερική σημείωση', 403);
    }
    // συνημμένα: έλεγχος ΠΡΙΝ σταλεί η απάντηση, αποθήκευση WHMCS-style στο attachmentsnew
    $attNames = [];
    $attDir = __DIR__ . '/../attachmentsnew';
    if (!empty($_FILES['files'])) {
        $ff = $_FILES['files'];
        $names = is_array($ff['name']) ? $ff['name'] : [$ff['name']];
        foreach ($names as $k => $nm) {
            $err = is_array($ff['error']) ? $ff['error'][$k] : $ff['error'];
            $sz = is_array($ff['size']) ? $ff['size'][$k] : $ff['size'];
            if ($err !== UPLOAD_ERR_OK) {
                fail('upload');
            }
            if ($sz > 20 * 1024 * 1024) {
                fail('Μέγιστο 20MB ανά αρχείο');
            }
            $ext = strtolower(pathinfo($nm, PATHINFO_EXTENSION));
            if (in_array($ext, ['php', 'phtml', 'phar', 'cgi', 'sh', 'exe', 'htaccess'], true)) {
                fail('Μη επιτρεπτός τύπος αρχείου');
            }
        }
        foreach ($names as $k => $nm) {
            $tmp = is_array($ff['tmp_name']) ? $ff['tmp_name'][$k] : $ff['tmp_name'];
            $safe = preg_replace('/[^A-Za-z0-9._-]/', '_', $nm) ?: 'file';
            $stored = random_int(100000, 999999) . '_' . mb_substr($safe, 0, 160);
            if (!move_uploaded_file($tmp, $attDir . '/' . $stored)) {
                fail('write');
            }
            $attNames[] = $stored;
        }
    }
    $uname = Capsule::table('tbladmins')->where('id', $adminId)->value('username');
    /* Ψευδώνυμο «Support Team»: η απάντηση αναρτάται με τον δημόσιο λογαριασμό,
       ώστε ο πελάτης να δει «Support Team» αντί για το όνομα του χειριστή. Ο
       πραγματικός συντάκτης καταγράφεται εσωτερικά (mod_cpm_ticket_alias). Την
       επιλογή την έχει μόνο όποιος απαντά στον πελάτη. */
    $aliasOn = !empty($in['alias']);
    $replyUser = $uname;
    if ($aliasOn) {
        $aliasUser = (string) (Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')
            ->where('setting', 'ticket_alias_admin')->value('value') ?: 'support');
        $aa = Capsule::table('tbladmins')->where('username', $aliasUser)
            ->where('disabled', 0)->first(['id']);
        if ($aa) {
            $replyUser = $aliasUser;
        } else {
            $aliasOn = false;       // δεν υπάρχει έγκυρος λογαριασμός → κανονική απάντηση
        }
    }
    // Ανάρτηση ΩΣ $replyUser, αλλά με δικαιώματα/έλεγχο του πραγματικού χειριστή ($uname).
    $r = localAPI('AddTicketReply', ['ticketid' => $tid, 'message' => $msg, 'adminusername' => $replyUser]
        + (!empty($in['status']) ? ['status' => $in['status']] : []), $uname);
    if (($r['result'] ?? '') !== 'success') {
        foreach ($attNames as $s) {     // μην αφήσεις ορφανά στο δίσκο
            @unlink($attDir . '/' . $s);
        }
        fail($r['message'] ?? 'reply failed');
    }
    $rid = ($attNames || $aliasOn)
        ? (int) Capsule::table('tblticketreplies')->where('tid', $tid)->max('id') : 0;
    if ($attNames && $rid) {
        Capsule::table('tblticketreplies')->where('id', $rid)->update(['attachment' => implode('|', $attNames)]);
    }
    if ($aliasOn && $rid) {
        Capsule::table('mod_cpm_ticket_alias')->insert([
            'reply_id' => $rid, 'tid' => $tid, 'real_admin_id' => $adminId,
            'created_at' => date('Y-m-d H:i:s')]);
    }
    out(['ok' => true]);

case 'profile':                        // το προφίλ ΜΟΥ (κάθε χρήστης)
    $me8 = Capsule::table('tbladmins')->where('id', $adminId)
        ->first(['username', 'firstname', 'lastname', 'email', 'roleid', 'created_at']);
    $role8 = Capsule::table('tbladminroles')->where('id', (int) $me8->roleid)->value('name');
    $teams8 = Capsule::table('mod_cpm_team_members as tm')
        ->join('mod_cpm_teams as t', 't.id', '=', 'tm.team_id')
        ->where('tm.admin_id', $adminId)
        ->get(['t.name', 't.color', 'tm.role_title', 'tm.is_leader'])->all();
    $projs8 = Db::visibleProjectIds($adminId);
    $projList8 = Capsule::table('mod_cpm_projects')->where('status', 'active')
        ->when($projs8 !== null, function ($q) use ($projs8) { $q->whereIn('id', $projs8 ?: [0]); })
        ->orderBy('name')->get(['id', 'name', 'color'])->all();
    out(['profile' => [
        'username' => $me8->username, 'first' => $me8->firstname, 'last' => $me8->lastname,
        'email' => $me8->email, 'role' => $role8 ?: ('#' . $me8->roleid), 'full' => $FULL,
        'since' => substr((string) $me8->created_at, 0, 10)],
        'teams' => array_map(function ($t) { return ['name' => $t->name, 'color' => $t->color,
            'role' => $t->role_title, 'leader' => (bool) $t->is_leader]; }, $teams8),
        'projects' => array_map(function ($p) { return ['id' => (int) $p->id, 'name' => $p->name,
            'color' => $p->color]; }, $projList8),
        'allProjects' => $projs8 === null,
        'prefs' => ['notify_email' => Db::pref($adminId, 'notify_email', 'on'),
            'digest' => Db::pref($adminId, 'digest', 'on'),
            'lang' => Db::pref($adminId, 'lang', 'el') === 'en' ? 'en' : 'el',
            'meet_link' => Db::pref($adminId, 'meet_link', '')]]);

case 'profile_save':                   // στοιχεία μου (self μόνο)
    $email8 = trim($in['email'] ?? '');
    if ($email8 !== '' && !filter_var($email8, FILTER_VALIDATE_EMAIL)) {
        fail('Άκυρο email');
    }
    Capsule::table('tbladmins')->where('id', $adminId)->update([
        'firstname' => mb_substr(trim($in['first'] ?? ''), 0, 60),
        'lastname' => mb_substr(trim($in['last'] ?? ''), 0, 60),
        'email' => $email8, 'updated_at' => date('Y-m-d H:i:s')]);
    if (array_key_exists('meetLink', $in)) {
        Db::setPref($adminId, 'meet_link', mb_substr(trim((string) $in['meetLink']), 0, 190));
    }
    out(['ok' => true]);

case 'profile_pass':                   // αλλαγή δικού μου κωδικού με επιβεβαίωση τρέχοντος
    $curHash = Capsule::table('tbladmins')->where('id', $adminId)->value('password');
    if (!password_verify((string) ($in['current'] ?? ''), (string) $curHash)) {
        fail('Λάθος τρέχων κωδικός');
    }
    $np = (string) ($in['new'] ?? '');
    if (strlen($np) < 8) {
        fail('Ο νέος κωδικός θέλει τουλάχιστον 8 χαρακτήρες');
    }
    if ($np !== ($in['confirm'] ?? '')) {
        fail('Οι δύο κωδικοί δεν ταιριάζουν');
    }
    Capsule::table('tbladmins')->where('id', $adminId)
        ->update(['password' => password_hash($np, PASSWORD_DEFAULT),
            'passwordhash' => password_hash($np, PASSWORD_DEFAULT), 'updated_at' => date('Y-m-d H:i:s')]);
    out(['ok' => true]);

case 'profile_pref':                   // προσωπικές προτιμήσεις ειδοποιήσεων
    $key8 = (string) ($in['key'] ?? '');
    if ($key8 === 'lang') {                       // γλώσσα διεπαφής ανά χρήστη (el|en)
        Db::setPref($adminId, 'lang', ($in['value'] ?? '') === 'en' ? 'en' : 'el');
        out(['ok' => true]);
    }
    if ($key8 === 'myday_layout') {
        /* Μόνο γνωστά κλειδιά μπλοκ, με προαιρετικό «-» για κρυμμένο. Δεν αποθηκεύουμε
           ό,τι στείλει ο browser: η τιμή γυρίζει στο boot και μπαίνει σε HTML. */
        $okB = ['day', 'team', 'att', 'plan', 'queue', 'coach', 'dl', 'sup', 'wait', 'ov'];
        $keep = [];
        foreach (explode(',', (string) ($in['value'] ?? '')) as $kk) {
            $kk = trim($kk);
            $bare = ltrim($kk, '-');
            if ($bare !== '' && in_array($bare, $okB, true) && !in_array($bare, array_map(function ($x) { return ltrim($x, '-'); }, $keep), true)) {
                $keep[] = (strpos($kk, '-') === 0 ? '-' : '') . $bare;
            }
        }
        Db::setPref($adminId, 'myday_layout', implode(',', $keep));
        out(['ok' => true, 'value' => implode(',', $keep)]);
    }
    if (!in_array($key8, ['notify_email', 'digest'], true)) {
        fail('pref');
    }
    Db::setPref($adminId, $key8, ($in['value'] ?? '') === 'on' ? 'on' : 'off');
    out(['ok' => true]);

case 'triage':                          // 🎯 Πλάνο ημέρας — πρόταση tickets (managers)
    // Η πρόσβαση ελέγχεται από την πύλη περιοχών («Αναφορές & απόδοση»).


    $now = time();
    $slaBy = [];
    try {
        foreach (Capsule::table('mod_supportcontracts_tickets')->whereNotNull('sla_due')->get() as $st9) {
            $slaBy[(int) $st9->ticketid] = $st9;
        }
    } catch (\Throwable $e) {
    }
    $prioBy = [];
    try {
        foreach (Capsule::table('mod_supportcontracts_clients')->where('enabled', 1)->get(['userid', 'priority']) as $pc) {
            $prioBy[(int) $pc->userid] = $pc->priority;
        }
    } catch (\Throwable $e) {
    }
    $rows9 = Capsule::table('tbltickets')
        ->whereNotIn('status', ['Closed', 'Cancelled'])
        ->get(['id', 'tid', 'title', 'userid', 'name', 'urgency', 'status', 'date', 'lastreply', 'flag']);
    $ids9 = array_map(function ($r) { return (int) $r->id; }, $rows9->all());
    // ποιος μίλησε τελευταίος; (admin κενό = πελάτης)
    $lastAdmin = [];
    if ($ids9) {
        foreach (Capsule::table('tblticketreplies')->whereIn('tid', $ids9)
            ->orderBy('id')->get(['tid', 'admin']) as $r9) {
            $lastAdmin[(int) $r9->tid] = trim((string) $r9->admin) !== '';
        }
    }
    $list9 = [];
    foreach ($rows9 as $t9) {
        $why = [];
        // 1) κρισιμότητα ticket
        $u = ['High' => 30, 'Medium' => 15, 'Low' => 5][$t9->urgency] ?? 10;
        $why['urgency'] = $u;
        // 2) περιμένει απάντησή μας + πόσο
        $waiting = !array_key_exists((int) $t9->id, $lastAdmin) ? true : !$lastAdmin[(int) $t9->id];
        $wh = max(0, ($now - strtotime($t9->lastreply)) / 3600);
        $w = $waiting ? min(30, round($wh * 1.5, 1)) : 0;
        $why['wait'] = $w;
        // 3) SLA πελάτη
        $sv = 0;
        $slaDue = null;
        if (isset($slaBy[(int) $t9->id])) {
            $st9 = $slaBy[(int) $t9->id];
            $slaDue = $st9->sla_due;
            if (!$st9->first_response_at) {
                $left = (strtotime($st9->sla_due) - $now) / 3600;
                $sv = $left < 0 ? 40 : ($left < 2 ? 30 : ($left < 8 ? 15 : 5));
            }
        }
        $why['sla'] = $sv;
        // 4) προτεραιότητα συμβολαίου πελάτη
        $cp = ['High' => 15, 'Medium' => 7][$prioBy[(int) $t9->userid] ?? ''] ?? 0;
        $why['contract'] = $cp;
        // 5) παλαιότητα
        $ageD = max(0, ($now - strtotime($t9->date)) / 86400);
        $why['age'] = min(10, round($ageD / 2, 1));
        $score = array_sum($why);
        $list9[] = ['id' => (int) $t9->id, 'tid' => $t9->tid, 'title' => $t9->title,
            'client' => $t9->userid ? clientLabel($t9->userid) : $t9->name,
            'urgency' => $t9->urgency, 'status' => $t9->status,
            'flag' => $t9->flag ? (int) $t9->flag : null,
            'waiting' => $waiting, 'waitH' => round($wh, 1),
            'slaDue' => $slaDue, 'contractPrio' => $prioBy[(int) $t9->userid] ?? null,
            'ageDays' => round($ageD, 1),
            'score' => round($score, 1), 'why' => $why];
    }
    usort($list9, function ($a, $b) { return $b['score'] <=> $a['score']; });
    // 💡 πρόταση ανάθεσης: ποιος έχει λύσει παρόμοια (top 20, μόνο ανανάθετα)
    $nameToId = [];
    foreach (Capsule::table('tbladmins')->where('disabled', 0)->get(['id', 'firstname', 'lastname']) as $a9) {
        $nameToId[trim($a9->firstname . ' ' . $a9->lastname)] = (int) $a9->id;
    }
    $closed9 = Capsule::table('tbltickets')->where('status', 'Closed')
        ->orderBy('lastreply', 'desc')->limit(300)->get(['id', 'title'])->all();
    foreach (array_slice($list9, 0, 20) as $k9 => $t9) {
        if ($t9['flag']) {
            continue;
        }
        $tw9 = cnp_words($t9['title']);
        $solvers = [];
        foreach ($closed9 as $c9) {
            if (cnp_overlap($tw9, cnp_words($c9->title)) > 0) {
                $adm = Capsule::table('tblticketreplies')->where('tid', $c9->id)
                    ->where('admin', '!=', '')->orderBy('id', 'desc')->value('admin');
                if ($adm && isset($nameToId[trim($adm)])) {
                    $solvers[trim($adm)] = ($solvers[trim($adm)] ?? 0) + 1;
                }
            }
        }
        if ($solvers) {
            arsort($solvers);
            $top9 = array_key_first($solvers);
            $list9[$k9]['suggestAssignee'] = ['id' => $nameToId[$top9], 'name' => $top9, 'solved' => $solvers[$top9]];
        }
    }
    $sum9 = ['open' => count($list9),
        'waiting' => count(array_filter($list9, function ($x) { return $x['waiting']; })),
        'slaRisk' => count(array_filter($list9, function ($x) { return $x['why']['sla'] >= 15; })),
        'high' => count(array_filter($list9, function ($x) { return $x['urgency'] === 'High'; })),
        'unassigned' => count(array_filter($list9, function ($x) { return !$x['flag']; }))];
    out(['plan' => array_slice($list9, 0, 20), 'summary' => $sum9]);

/* ============ 📚 ΒΑΣΗ ΓΝΩΣΗΣ ============ */
case 'ksearch':                         // «το έχω ξαναλύσει;» — ψάξιμο σε KB + ιστορικό tickets
    $q9 = trim($_GET['q'] ?? '');
    if (mb_strlen($q9) < 3) {
        fail('q');
    }
    $qw = cnp_words($q9);
    if (!$qw) {
        fail('q');
    }
    // KB — ταίριασμα λέξεων + fallback σε υποσυμβολοσειρά (ώστε το search «να πιάνει τα πάντα»)
    $qRaw = mb_strtolower($q9, 'UTF-8');
    $kbHits = [];
    foreach (Capsule::table('mod_cpm_kb')->get() as $k9) {
        $hay = $k9->title . ' ' . $k9->keywords . ' ' . $k9->tags . ' ' . $k9->solution;
        $kw = cnp_words($k9->title . ' ' . $k9->keywords . ' ' . $k9->tags . ' ' . mb_substr($k9->solution, 0, 2000));
        $sc = cnp_overlap($qw, $kw);
        if ($sc === 0 && mb_strpos(mb_strtolower($hay, 'UTF-8'), $qRaw) !== false) {
            $sc = 1;                                   // δεν έπιασε λέξη, αλλά υπάρχει αυτούσιο το κείμενο
        }
        if ($sc > 0) {
            $kbHits[] = ['id' => (int) $k9->id, 'title' => $k9->title, 'tags' => $k9->tags,
                'keywords' => $k9->keywords, 'solution' => $k9->solution, 'uses' => (int) $k9->uses,
                'areaId' => (int) $k9->area_id,
                'relAreas' => array_values(array_filter(array_map('intval', explode(',', (string) $k9->rel_areas)))),
                'by' => $k9->created_by ? Db::adminName($k9->created_by) : null,
                'at' => substr((string) $k9->created_at, 0, 10), 'score' => $sc];
        }
    }
    usort($kbHits, function ($a, $b) { return $b['score'] <=> $a['score']; });
    // ιστορικό tickets: πρόφιλτρο SQL με LIKE στις 2 πιο σπάνιες λέξεις, μετά scoring
    $tHits = [];
    $cand = Capsule::table('tbltickets');
    $cand->where(function ($qq) use ($qw) {
        foreach (array_slice($qw, 0, 6) as $w) {
            $qq->orWhere('title', 'like', '%' . $w . '%')
               ->orWhere('message', 'like', '%' . $w . '%')
               ->orWhereExists(function ($sub) use ($w) {
                   $sub->selectRaw('1')->from('tblticketreplies')
                       ->whereColumn('tblticketreplies.tid', 'tbltickets.id')
                       ->where('tblticketreplies.message', 'like', '%' . $w . '%');
               });
        }
    });
    foreach ($cand->orderBy('lastreply', 'desc')->limit(200)->get(['id', 'tid', 'title', 'userid', 'name', 'status', 'lastreply', 'message']) as $t9) {
        $tw = cnp_words($t9->title . ' ' . mb_substr($t9->message, 0, 600));
        $sc = cnp_overlap($qw, $tw);
        // bonus: λύθηκε (Closed) → πιο χρήσιμο ως προηγούμενο
        if ($sc > 0) {
            $tHits[] = ['id' => (int) $t9->id, 'tid' => $t9->tid, 'title' => $t9->title,
                'client' => $t9->userid ? clientLabel($t9->userid) : $t9->name,
                'status' => $t9->status, 'last' => substr($t9->lastreply, 0, 10),
                'score' => $sc + ($t9->status === 'Closed' ? 1 : 0)];
        }
    }
    usort($tHits, function ($a, $b) { return $b['score'] <=> $a['score']; });
    out(['kb' => array_slice($kbHits, 0, 10), 'tickets' => array_slice($tHits, 0, 15)]);

case 'kb_draft':                        // AI προσχέδιο KB από κλεισμένο ticket
    $tid3 = (int) ($in['ticket'] ?? 0);
    $tk3 = Capsule::table('tbltickets')->where('id', $tid3)->first();
    if (!$tk3) {
        fail('ticket', 404);
    }
    $key = (string) (Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')
        ->where('setting', 'ai_api_key')->value('value') ?: '');
    if ($key === '') {   // χωρίς AI: βασικό προσχέδιο
        out(['ok' => true, 'draft' => ['title' => $tk3->title, 'keywords' => implode(' ', array_slice(cnp_words($tk3->title), 0, 8)), 'solution' => '']]);
    }
    $convTxt = "ΠΕΛΑΤΗΣ: " . mb_substr($tk3->message, 0, 2500) . "\n";
    foreach (Capsule::table('tblticketreplies')->where('tid', $tid3)->orderBy('id')->limit(20)->get() as $r) {
        $who = ($r->admin !== '' && $r->admin !== null) ? 'ΟΜΑΔΑ' : 'ΠΕΛΑΤΗΣ';
        $convTxt .= $who . ': ' . mb_substr($r->message, 0, 1500) . "\n";
    }
    $prompt = "Από την παρακάτω συνομιλία ticket υποστήριξης, φτιάξε εγγραφή για βάση γνώσης στα ελληνικά. Απάντησε ΜΟΝΟ με JSON χωρίς markdown: {\"title\": \"σύντομος τίτλος προβλήματος\", \"keywords\": \"λέξεις-κλειδιά χωρισμένες με κόμμα\", \"solution\": \"η λύση βήμα-βήμα όπως εφαρμόστηκε\"}. Αν η συνομιλία δεν περιέχει σαφή λύση, βάλε στο solution ό,τι έγινε.\n\nΘΕΜΑ: {$tk3->title}\n\nΣΥΝΟΜΙΛΙΑ:\n$convTxt";
    $ch = curl_init('https://api.anthropic.com/v1/messages');
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 60, CURLOPT_POST => true,
        CURLOPT_HTTPHEADER => ['Content-Type: application/json', 'x-api-key: ' . $key, 'anthropic-version: 2023-06-01'],
        CURLOPT_POSTFIELDS => json_encode(['model' => 'claude-haiku-4-5-20251001', 'max_tokens' => 1200,
            'messages' => [['role' => 'user', 'content' => $prompt]]]),
    ]);
    $resp = curl_exec($ch);
    curl_close($ch);
    $j = json_decode((string) $resp, true);
    $txt = $j['content'][0]['text'] ?? '';
    $draft = json_decode(trim(preg_replace('/^```json|```$/m', '', trim($txt))), true);
    if (!is_array($draft) || empty($draft['title'])) {
        $draft = ['title' => $tk3->title, 'keywords' => implode(' ', array_slice(cnp_words($tk3->title), 0, 8)), 'solution' => $txt];
    }
    out(['ok' => true, 'draft' => ['title' => mb_substr($draft['title'], 0, 255),
        'keywords' => mb_substr($draft['keywords'] ?? '', 0, 500),
        'solution' => mb_substr($draft['solution'] ?? '', 0, 60000)]]);

case 'mynext':                          /* Προσωπικό top-3 με αριθμητικό σκορ.
    Δεν το καλεί πλέον η «Η μέρα μου» — τη θέση του πήρε το 'queue' του myday,
    που λέει ΓΙΑΤΙ προτεραιοποιείται κάτι αντί για αδιαφανή βαθμό. Μένει για
    εξωτερικές κλήσεις/κινητό. */
    $now = time();
    $slaBy = [];
    try {
        foreach (Capsule::table('mod_supportcontracts_tickets')->whereNotNull('sla_due')->get() as $st9) {
            $slaBy[(int) $st9->ticketid] = $st9;
        }
    } catch (\Throwable $e) {
    }
    $rows9 = Capsule::table('tbltickets')->whereNotIn('status', ['Closed', 'Cancelled'])
        ->where(function ($q9) use ($adminId) { $q9->where('flag', $adminId)->orWhere('flag', 0); })
        ->get(['id', 'tid', 'title', 'userid', 'name', 'urgency', 'date', 'lastreply', 'flag']);
    $ids9 = array_map(function ($r) { return (int) $r->id; }, $rows9->all());
    $lastAdmin = [];
    if ($ids9) {
        foreach (Capsule::table('tblticketreplies')->whereIn('tid', $ids9)->orderBy('id')->get(['tid', 'admin']) as $r9) {
            $lastAdmin[(int) $r9->tid] = trim((string) $r9->admin) !== '';
        }
    }
    $list9 = [];
    foreach ($rows9 as $t9) {
        $u = ['High' => 30, 'Medium' => 15, 'Low' => 5][$t9->urgency] ?? 10;
        $waiting = !($lastAdmin[(int) $t9->id] ?? false);
        $w = $waiting ? min(30, round(max(0, ($now - strtotime($t9->lastreply)) / 3600) * 1.5, 1)) : 0;
        $sv = 0;
        if (isset($slaBy[(int) $t9->id]) && !$slaBy[(int) $t9->id]->first_response_at) {
            $left = (strtotime($slaBy[(int) $t9->id]->sla_due) - $now) / 3600;
            $sv = $left < 0 ? 40 : ($left < 2 ? 30 : ($left < 8 ? 15 : 5));
        }
        $score = $u + $w + $sv + ((int) $t9->flag === $adminId ? 5 : 0);   // δικά μου ελαφρώς μπροστά
        $list9[] = ['id' => (int) $t9->id, 'tid' => $t9->tid, 'title' => $t9->title,
            'client' => $t9->userid ? clientLabel($t9->userid) : $t9->name,
            'mine' => (int) $t9->flag === $adminId, 'waiting' => $waiting,
            'score' => round($score, 1)];
    }
    usort($list9, function ($a, $b) { return $b['score'] <=> $a['score']; });
    out(['next' => array_slice($list9, 0, 3)]);

case 'recurrent':                       // 🔁 επαναλαμβανόμενα προβλήματα 90 ημερών
    $since = date('Y-m-d', strtotime('-90 days'));
    $sigs = [];
    foreach (Capsule::table('tbltickets')->where('date', '>=', $since)
        ->get(['id', 'tid', 'title', 'userid', 'name', 'status', 'date']) as $t9) {
        $sigs[] = ['t' => $t9, 'w' => cnp_words($t9->title, 12)];
    }
    $used = [];
    $clusters = [];
    foreach ($sigs as $i => $a) {
        if (isset($used[$i]) || !$a['w']) {
            continue;
        }
        $grp = [$a];
        $used[$i] = true;
        foreach ($sigs as $j => $b) {
            if ($j <= $i || isset($used[$j])) {
                continue;
            }
            if (cnp_overlap($a['w'], $b['w']) >= 2) {
                $grp[] = $b;
                $used[$j] = true;
            }
        }
        if (count($grp) >= 3) {   // «επαναλαμβανόμενο» = 3+ φορές στο τρίμηνο
            $cl = [];
            foreach ($grp as $g) {
                $cl[] = ['id' => (int) $g['t']->id, 'tid' => $g['t']->tid, 'title' => $g['t']->title,
                    'client' => $g['t']->userid ? clientLabel($g['t']->userid) : $g['t']->name,
                    'date' => substr($g['t']->date, 0, 10), 'status' => $g['t']->status];
            }
            $clusters[] = ['label' => $grp[0]['t']->title, 'count' => count($grp),
                'clients' => array_values(array_unique(array_map(function ($x) { return $x['client']; }, $cl))),
                'tickets' => $cl];
        }
    }
    usort($clusters, function ($a, $b) { return $b['count'] <=> $a['count']; });
    out(['clusters' => array_slice($clusters, 0, 10)]);

case 'catalog_products':                // ο κατάλογος προϊόντων (για κάθε επιλογέα)
    require_once __DIR__ . '/../modules/addons/cloudonprojects/lib/Catalog.php';
    out(['products' => \WHMCS\Module\Addon\CloudonProjects\Catalog::products(),
        'depts' => Capsule::table('tblticketdepartments')->orderBy('order')->get(['id', 'name'])
            ->map(function ($d) { return ['id' => (int) $d->id, 'name' => $d->name]; })->all()]);

case 'client_tree':
    /* Η εικόνα ενός πελάτη με τη σειρά που τη σκέφτεται ο κόσμος:
       ΠΕΛΑΤΗΣ → τα ΠΡΟΪΟΝΤΑ που αγόρασε → η ΑΝΑΓΚΗ ανά τμήμα → έργα & αιτήματα. */
    require_once __DIR__ . '/../modules/addons/cloudonprojects/lib/Catalog.php';
    $cid = (int) ($_GET['client'] ?? $in['client'] ?? 0);
    if (!$cid) { fail('client'); }
    $cl = Capsule::table('tblclients')->where('id', $cid)->first(['id', 'firstname', 'lastname', 'companyname']);
    if (!$cl) { fail('client', 404); }

    $depts = Capsule::table('tblticketdepartments')->orderBy('order')->get(['id', 'name']);
    $prodRows = Capsule::table('mod_cpm_client_products as cp')
        ->join('mod_cpm_products as p', 'p.id', '=', 'cp.product_id')
        ->where('cp.clientid', $cid)->orderBy('p.sort')
        ->get(['p.id', 'p.name', 'p.color', 'cp.services', 'cp.source', 'cp.status']);

    /* Όλη η δουλειά του πελάτη, μία φορά από τη βάση — και μετά μοιράζεται στο δέντρο. */
    $tks = Capsule::table('tbltickets as t')
        ->leftJoin('mod_cpm_ticket_class as tc', 'tc.ticketid', '=', 't.id')
        ->where('t.userid', $cid)->get(['t.id', 't.did', 't.status', 't.title', 'tc.product_id']);
    $pjs = Capsule::table('mod_cpm_projects')->where('clientid', $cid)
        ->get(['id', 'name', 'deptid', 'product_id', 'pstatus', 'health']);
    $pjIds = array_map(function ($p) { return (int) $p->id; }, $pjs->all());
    $tsk = $pjIds ? Capsule::table('mod_cpm_tasks')->whereIn('project_id', $pjIds)
        ->get(['id', 'project_id', 'dept_id', 'product_id', 'completed_at']) : collect([]);

    $openT = function ($st) { return !in_array($st, ['Closed', 'Κλειστό', 'Resolved'], true); };
    $bucket = [];                                   // [product_id][dept_id] => μετρητές
    $touch = function (&$b, $p, $d) {
        $p = (int) $p; $d = (int) $d;
        if (!isset($b[$p][$d])) { $b[$p][$d] = ['tickets' => 0, 'ticketsOpen' => 0, 'tasks' => 0,
            'tasksOpen' => 0, 'projects' => []]; }
    };
    foreach ($tks as $t) {
        $touch($bucket, (int) $t->product_id, (int) $t->did);
        $bucket[(int) $t->product_id][(int) $t->did]['tickets']++;
        if ($openT($t->status)) { $bucket[(int) $t->product_id][(int) $t->did]['ticketsOpen']++; }
    }
    foreach ($pjs as $p) {
        $touch($bucket, (int) $p->product_id, (int) $p->deptid);
        $bucket[(int) $p->product_id][(int) $p->deptid]['projects'][] = ['id' => (int) $p->id,
            'name' => $p->name, 'pstatus' => $p->pstatus, 'health' => $p->health];
    }
    foreach ($tsk as $t) {
        $pj = null;
        foreach ($pjs as $p) { if ((int) $p->id === (int) $t->project_id) { $pj = $p; break; } }
        $pid = (int) ($t->product_id ?: ($pj->product_id ?? 0));
        $did = (int) ($t->dept_id ?: ($pj->deptid ?? 0));
        $touch($bucket, $pid, $did);
        $bucket[$pid][$did]['tasks']++;
        if (!$t->completed_at) { $bucket[$pid][$did]['tasksOpen']++; }
    }

    $dn = [];
    foreach ($depts as $d) { $dn[(int) $d->id] = $d->name; }
    $dn[0] = '— χωρίς τμήμα —';
    $mk = function ($pid) use ($bucket, $dn) {
        $out = [];
        foreach (($bucket[$pid] ?? []) as $did => $b) {
            if (!$b['tickets'] && !$b['tasks'] && !$b['projects']) { continue; }
            $out[] = ['id' => $did, 'name' => $dn[$did] ?? ('#' . $did)] + $b;
        }
        usort($out, function ($a, $b) { return $a['id'] <=> $b['id']; });
        return $out;
    };
    $products = [];
    foreach ($prodRows as $p) {
        $products[] = ['id' => (int) $p->id, 'name' => $p->name, 'color' => $p->color,
            'services' => (int) $p->services, 'source' => $p->source, 'status' => $p->status,
            'depts' => $mk((int) $p->id)];
    }
    /* Προϊόν που έχει δουλειά αλλά δεν φιγουράρει στην καρτέλα (π.χ. ticket που μόλις
       ταξινομήθηκε): μπαίνει κι αυτό, αλλιώς η δουλειά του θα ήταν αόρατη. */
    $seen9 = array_column($products, 'id');
    foreach (array_keys($bucket) as $pid9) {
        if (!$pid9 || in_array((int) $pid9, $seen9, true)) { continue; }
        $pr9 = Capsule::table('mod_cpm_products')->where('id', $pid9)->first(['id', 'name', 'color']);
        if (!$pr9) { continue; }
        $products[] = ['id' => (int) $pr9->id, 'name' => $pr9->name, 'color' => $pr9->color,
            'services' => 0, 'source' => 'manual', 'status' => 'active', 'depts' => $mk((int) $pid9)];
    }

    /* Δουλειά που δεν κρέμεται σε κανένα προϊόν — η λίστα εκκρεμοτήτων της μετάβασης. */
    $orphan = $mk(0);

    /* Υπηρεσίες που χρεώνονται αλλά δεν ανήκουν σε προϊόν: τίποτα δεν μένει αόρατο. */
    $map = \WHMCS\Module\Addon\CloudonProjects\Catalog::mapByPackage();
    $unmapped = [];
    foreach (Capsule::table('tblhosting as h')->join('tblproducts as pr', 'pr.id', '=', 'h.packageid')
        ->where('h.userid', $cid)->where('h.domainstatus', 'Active')
        ->get(['pr.id', 'pr.name']) as $h) {
        if (!empty($map[(int) $h->id])) { continue; }
        $unmapped[$h->name] = ($unmapped[$h->name] ?? 0) + 1;
    }
    $un = [];
    foreach ($unmapped as $n => $c) { $un[] = ['name' => $n, 'n' => $c]; }

    out(['client' => ['id' => (int) $cl->id,
            'name' => $cl->companyname ?: trim($cl->firstname . ' ' . $cl->lastname)],
        'products' => $products, 'orphan' => $orphan, 'unmapped' => $un,
        'depts' => $depts->map(function ($d) { return ['id' => (int) $d->id, 'name' => $d->name]; })->all()]);

case 'client_product_set':              // χειροκίνητη προσθήκη/αφαίρεση προϊόντος σε πελάτη
    require_once __DIR__ . '/../modules/addons/cloudonprojects/lib/Catalog.php';
    $cid = (int) ($in['client'] ?? 0);
    $prd = (int) ($in['product'] ?? 0);
    $on  = !empty($in['on']);
    if (!$cid || !$prd) { fail('Λείπει πελάτης ή προϊόν'); }
    $ex = Capsule::table('mod_cpm_client_products')->where('clientid', $cid)->where('product_id', $prd)->first();
    if ($on && !$ex) {
        Capsule::table('mod_cpm_client_products')->insert(['clientid' => $cid, 'product_id' => $prd,
            'source' => 'manual', 'status' => 'active', 'services' => 0, 'created_at' => date('Y-m-d H:i:s')]);
    } elseif (!$on && $ex) {
        /* Αν το έφερε η χρέωση, δεν το σβήνουμε — το σημειώνουμε ως ανενεργό. */
        if ($ex->source === 'manual' && !$ex->services) {
            Capsule::table('mod_cpm_client_products')->where('id', $ex->id)->delete();
        } else {
            Capsule::table('mod_cpm_client_products')->where('id', $ex->id)->update(['status' => 'past']);
        }
    } elseif ($on && $ex && $ex->status !== 'active') {
        Capsule::table('mod_cpm_client_products')->where('id', $ex->id)->update(['status' => 'active']);
    }
    out(['ok' => true]);

case 'client_contacts':                 // τηλέφωνα, emails και υποκαταστήματα ενός πελάτη
    $cid = (int) ($_GET['client'] ?? $in['client'] ?? 0);
    if (!$cid) { fail('client'); }
    $cl = Capsule::table('tblclients')->where('id', $cid)
        ->first(['id', 'email', 'phonenumber', 'address1', 'city']);
    if (!$cl) { fail('client', 404); }
    $br = Capsule::table('mod_cpm_client_branches')->where('clientid', $cid)
        ->orderBy('sort')->orderBy('id')->get()->map(function ($b) {
            return ['id' => (int) $b->id, 'name' => $b->name, 'address' => (string) $b->address,
                'city' => (string) $b->city, 'note' => (string) $b->note, 'active' => (int) $b->active];
        })->all();
    $ct = Capsule::table('mod_cpm_client_contacts')->where('clientid', $cid)
        ->orderBy('kind')->orderBy('sort')->orderBy('id')->get()->map(function ($c) {
            return ['id' => (int) $c->id, 'kind' => $c->kind, 'value' => $c->value,
                'label' => (string) $c->label, 'branch' => $c->branch_id ? (int) $c->branch_id : null];
        })->all();
    out(['whmcs' => ['email' => (string) $cl->email, 'phone' => (string) $cl->phonenumber,
            'address' => trim($cl->address1 . ' ' . $cl->city)],
        'contacts' => $ct, 'branches' => $br]);

case 'client_contact_save':
    $cid = (int) ($in['client'] ?? 0);
    $val = trim((string) ($in['value'] ?? ''));
    $kind = ($in['kind'] ?? 'phone') === 'email' ? 'email' : 'phone';
    if (!$cid || $val === '') { fail('Λείπει τιμή'); }
    if ($kind === 'email' && !filter_var($val, FILTER_VALIDATE_EMAIL)) { fail('Μη έγκυρο email'); }
    $row = ['clientid' => $cid, 'kind' => $kind, 'value' => mb_substr($val, 0, 160),
        'label' => mb_substr(trim((string) ($in['label'] ?? '')), 0, 60),
        'branch_id' => (int) ($in['branch'] ?? 0) ?: null];
    $id = (int) ($in['id'] ?? 0);
    if ($id) { Capsule::table('mod_cpm_client_contacts')->where('id', $id)->update($row); }
    else { $id = (int) Capsule::table('mod_cpm_client_contacts')
        ->insertGetId($row + ['created_at' => date('Y-m-d H:i:s')]); }
    out(['ok' => true, 'id' => $id]);

case 'client_contact_del':
    Capsule::table('mod_cpm_client_contacts')->where('id', (int) ($in['id'] ?? 0))->delete();
    out(['ok' => true]);

case 'client_branch_save':
    $cid = (int) ($in['client'] ?? 0);
    $nm = trim((string) ($in['name'] ?? ''));
    if (!$cid || $nm === '') { fail('Δώσε όνομα υποκαταστήματος'); }
    $row = ['clientid' => $cid, 'name' => mb_substr($nm, 0, 120),
        'address' => mb_substr(trim((string) ($in['address'] ?? '')), 0, 200),
        'city' => mb_substr(trim((string) ($in['city'] ?? '')), 0, 80),
        'note' => mb_substr(trim((string) ($in['note'] ?? '')), 0, 300),
        'active' => empty($in['inactive']) ? 1 : 0];
    $id = (int) ($in['id'] ?? 0);
    if ($id) { Capsule::table('mod_cpm_client_branches')->where('id', $id)->update($row); }
    else { $id = (int) Capsule::table('mod_cpm_client_branches')
        ->insertGetId($row + ['created_at' => date('Y-m-d H:i:s')]); }
    out(['ok' => true, 'id' => $id]);

case 'client_branch_del':
    $bid = (int) ($in['id'] ?? 0);
    /* Τα στοιχεία επικοινωνίας του υποκαταστήματος δεν χάνονται — ξεκρεμιούνται. */
    Capsule::table('mod_cpm_client_contacts')->where('branch_id', $bid)->update(['branch_id' => null]);
    Capsule::table('mod_cpm_client_branches')->where('id', $bid)->delete();
    out(['ok' => true]);

case 'client_health':                   // ❤️ υγεία πελατών — ποιοι «καίγονται»
    $since = date('Y-m-d', strtotime('-90 days'));
    $stats = [];
    foreach (Capsule::table('tbltickets')->where('date', '>=', $since)->where('userid', '>', 0)
        ->get(['userid', 'status']) as $t9) {
        $stats[(int) $t9->userid]['tickets'] = ($stats[(int) $t9->userid]['tickets'] ?? 0) + 1;
        if (!in_array($t9->status, ['Closed', 'Cancelled'], true)) {
            $stats[(int) $t9->userid]['open'] = ($stats[(int) $t9->userid]['open'] ?? 0) + 1;
        }
    }
    try {
        foreach (Capsule::table('mod_supportcontracts_tickets as st')
            ->join('tbltickets as t', 't.id', '=', 'st.ticketid')
            ->where('t.date', '>=', $since)->where('st.sla_met', 0)->whereNotNull('st.first_response_at')
            ->get(['t.userid']) as $b9) {
            $stats[(int) $b9->userid]['breach'] = ($stats[(int) $b9->userid]['breach'] ?? 0) + 1;
        }
    } catch (\Throwable $e) {
    }
    foreach (Capsule::table('tblinvoices')->where('status', 'Unpaid')
        ->groupBy('userid')->get(['userid', Capsule::raw('SUM(total) s'), Capsule::raw('COUNT(*) c')]) as $u9) {
        $stats[(int) $u9->userid]['owed'] = (float) $u9->s;
        $stats[(int) $u9->userid]['owedCnt'] = (int) $u9->c;
    }
    $outH = [];
    foreach ($stats as $cid9 => $x) {
        $score = 100
            - min(30, ($x['tickets'] ?? 0) * 2)          // πολλά tickets = τριβή
            - min(25, ($x['breach'] ?? 0) * 8)           // σπασμένα SLA
            - min(25, ($x['owed'] ?? 0) > 0 ? 10 + min(15, ($x['owedCnt'] ?? 0) * 5) : 0)
            - min(20, ($x['open'] ?? 0) * 5);            // ανοιχτές εκκρεμότητες τώρα
        $outH[] = ['client' => $cid9, 'name' => clientLabel($cid9), 'score' => max(0, (int) $score),
            'tickets90' => $x['tickets'] ?? 0, 'open' => $x['open'] ?? 0,
            'slaBreaches' => $x['breach'] ?? 0,
            'owedFlag' => ($x['owed'] ?? 0) > 0,
            'owed' => cnp_can_see_balances($adminId, $FULL) ? round($x['owed'] ?? 0, 2) : null];
    }
    usort($outH, function ($a, $b) { return $a['score'] <=> $b['score']; });
    out(['clients' => array_slice($outH, 0, 15)]);

case 'kb_list':
    /* ΧΩΡΙΣ το πλήρες `solution`: με 1.000+ άρθρα το payload έφτανε 22MB και ο browser
       κόλλαγε. Στέλνουμε μόνο μετα-δεδομένα + απόσπασμα· το πλήρες κείμενο έρχεται με
       kb_get όταν ανοίξει το άρθρο. */
    $items9 = array_map(function ($k9) {
        // κενό ΠΡΙΝ το strip_tags — αλλιώς «</td><td>» κολλάει τις λέξεις («ΚατηγορίαΕρώτηση»)
        $plain9 = preg_replace('/<[^>]+>/', ' ', (string) $k9->solution);
        $plain9 = trim(preg_replace('/\s+/u', ' ',
            html_entity_decode($plain9, ENT_QUOTES | ENT_HTML5, 'UTF-8')));
        return ['id' => (int) $k9->id, 'title' => $k9->title, 'keywords' => $k9->keywords,
            'tags' => $k9->tags, 'excerpt' => mb_substr($plain9, 0, 400), 'uses' => (int) $k9->uses,
            'areaId' => (int) $k9->area_id,
            'relAreas' => array_values(array_filter(array_map('intval', explode(',', (string) $k9->rel_areas)))),
            'by' => $k9->created_by ? Db::adminName($k9->created_by) : null,
            'byId' => (int) $k9->created_by, 'src' => (string) $k9->source_url,
            'at' => substr((string) $k9->created_at, 0, 10)];
    }, Capsule::table('mod_cpm_kb')
        ->select('id', 'title', 'keywords', 'tags', 'area_id', 'rel_areas', 'uses', 'created_by', 'created_at',
            'source_url', Capsule::raw('LEFT(solution, 1200) as solution'))
        ->orderBy('uses', 'desc')->orderBy('id', 'desc')->get()->all());
    // προϊόντα = η ενιαία ταξινομία περιοχών (Ρυθμίσεις → Κατηγορίες tickets)
    $prods9 = [];
    foreach (cnp_ticket_cats()['area'] as $a9) {
        $n9 = 0;
        foreach ($items9 as $it9) {
            if ($it9['areaId'] === $a9['id'] || in_array($a9['id'], $it9['relAreas'], true)) {
                $n9++;
            }
        }
        $prods9[] = $a9 + ['count' => $n9];
    }
    $unfiled9 = 0;
    foreach ($items9 as $it9) {
        if (!$it9['areaId']) {
            $unfiled9++;
        }
    }
    out(['items' => $items9, 'products' => $prods9, 'unfiled' => $unfiled9]);

case 'kb_save':
    $kid = (int) ($in['id'] ?? 0);
    $valid9 = array_column(cnp_ticket_cats()['area'], 'id');
    $area9 = (int) ($in['areaId'] ?? 0);
    $rel9 = array_values(array_unique(array_filter(array_map('intval', (array) ($in['relAreas'] ?? [])),
        function ($x) use ($valid9, $area9) { return in_array($x, $valid9, true) && $x !== $area9; })));
    $data9 = ['title' => mb_substr(trim($in['title'] ?? ''), 0, 255),
        'keywords' => mb_substr(trim($in['keywords'] ?? ''), 0, 500),
        'tags' => mb_substr(trim($in['tags'] ?? ''), 0, 190),
        'area_id' => in_array($area9, $valid9, true) ? $area9 : 0,
        'rel_areas' => implode(',', array_slice($rel9, 0, 12)),
        'solution' => cnp_clean_html($in['solution'] ?? '', 60000),   // rich-text
        'updated_at' => date('Y-m-d H:i:s')];
    if ($data9['title'] === '' || $data9['solution'] === '') {
        fail('Τίτλος και λύση είναι υποχρεωτικά');
    }
    if ($kid) {
        Capsule::table('mod_cpm_kb')->where('id', $kid)->update($data9);
    } else {
        $kid = Capsule::table('mod_cpm_kb')->insertGetId($data9
            + ['created_by' => $adminId, 'created_at' => date('Y-m-d H:i:s')]);
    }
    out(['ok' => true, 'id' => $kid]);

case 'kb_get':                           // πλήρες κείμενο ΕΝΟΣ άρθρου (on demand)
    $kg = Capsule::table('mod_cpm_kb')->where('id', (int) ($_GET['id'] ?? $in['id'] ?? 0))->first();
    if (!$kg) { fail('notfound', 404); }
    out(['ok' => true, 'id' => (int) $kg->id, 'title' => $kg->title,
        'solution' => (string) $kg->solution, 'src' => (string) $kg->source_url]);

case 'kb_bulk':                          // μαζικές ενέργειες σε άρθρα γνώσης
    $idsB = array_values(array_filter(array_map('intval', (array) ($in['ids'] ?? []))));
    if (!$idsB) { fail('Δεν διάλεξες άρθρα'); }
    $opB = (string) ($in['op'] ?? '');
    if ($opB === 'delete') {
        if (!$FULL) { fail('Μόνο διαχειριστής μπορεί να διαγράψει', 403); }
        $n = Capsule::table('mod_cpm_kb')->whereIn('id', $idsB)->delete();
        out(['ok' => true, 'op' => 'delete', 'n' => $n]);
    }
    if ($opB === 'area') {
        $validB = array_column(cnp_ticket_cats()['area'], 'id');
        $aB = (int) ($in['areaId'] ?? 0);
        if ($aB && !in_array($aB, $validB, true)) { fail('Άγνωστο προϊόν'); }
        $n = Capsule::table('mod_cpm_kb')->whereIn('id', $idsB)
            ->update(['area_id' => $aB, 'updated_at' => date('Y-m-d H:i:s')]);
        out(['ok' => true, 'op' => 'area', 'n' => $n]);
    }
    if ($opB === 'tags') {
        $n = Capsule::table('mod_cpm_kb')->whereIn('id', $idsB)
            ->update(['tags' => mb_substr(trim($in['tags'] ?? ''), 0, 190), 'updated_at' => date('Y-m-d H:i:s')]);
        out(['ok' => true, 'op' => 'tags', 'n' => $n]);
    }
    fail('Άγνωστη ενέργεια');

case 'kb_import_probe':                  // 🌐 ανάλυση URL τεκμηρίωσης πριν την εισαγωγή
    $urlI = trim($in['url'] ?? '');
    $rootI = null;
    if ($urlI === '') { fail('Δώσε URL'); }
    if (!preg_match('#^https?://#i', $urlI)) { $urlI = 'https://' . $urlI; }
    $rootI = cnp_site_root($urlI);
    // 1) WordPress REST — πιάνει BetterDocs/σελίδες/άρθρα με μία κλήση
    $found = [];
    foreach (['docs', 'pages', 'posts'] as $ptype) {
        $probe = cnp_safe_fetch($rootI . '/wp-json/wp/v2/' . $ptype . '?per_page=100&_fields=id,title,link,doc_category,categories', 4000000);
        if (empty($probe['ok'])) { continue; }
        $arr = json_decode($probe['body'], true);
        if (!is_array($arr) || !$arr || isset($arr['code'])) { continue; }
        foreach ($arr as $it) {
            if (empty($it['id'])) { continue; }
            $found[] = ['id' => (int) $it['id'], 'type' => $ptype,
                'title' => html_entity_decode(strip_tags($it['title']['rendered'] ?? ''), ENT_QUOTES, 'UTF-8'),
                'link' => (string) ($it['link'] ?? ''),
                'cat' => (int) (($it['doc_category'][0] ?? $it['categories'][0] ?? 0))];
        }
        if ($found) { break; }
    }
    if ($found) {
        // ονόματα κατηγοριών (ό,τι ταξινομία βρέθηκε)
        $cats = [];
        foreach (['doc_category', 'categories'] as $tax) {
            $cp = cnp_safe_fetch($rootI . '/wp-json/wp/v2/' . $tax . '?per_page=100&_fields=id,name,count');
            if (empty($cp['ok'])) { continue; }
            $ca = json_decode($cp['body'], true);
            if (!is_array($ca) || isset($ca['code'])) { continue; }
            foreach ($ca as $c) { $cats[(int) $c['id']] = html_entity_decode($c['name'], ENT_QUOTES, 'UTF-8'); }
            if ($cats) { break; }
        }
        // ήδη εισαγμένα (για να μη διπλογράψουμε)
        $have = [];
        foreach (Capsule::table('mod_cpm_kb')->whereIn('source_url', array_column($found, 'link'))
            ->pluck('source_url') as $u) { $have[$u] = true; }
        foreach ($found as &$f) {
            $f['catName'] = $cats[$f['cat']] ?? '';
            $f['exists'] = isset($have[$f['link']]);
        }
        unset($f);
        out(['ok' => true, 'mode' => 'wp', 'site' => $rootI, 'total' => count($found),
            'cats' => $cats, 'items' => $found]);
    }
    // 2) Confluence / Atlassian wiki (π.χ. wiki.soft1.eu) — api/v2
    $spaceKey = null; $pageId = null;
    if (preg_match('#/(?:space|spaces|display)/([A-Za-z0-9_~-]{2,40})#', $urlI, $mk)) { $spaceKey = $mk[1]; }
    if (preg_match('#/(?:pages/)?(\d{5,})#', $urlI, $mp)) { $pageId = $mp[1]; }
    if ($spaceKey || $pageId) {
        $conf = [];
        // 2α. αν το URL δείχνει σε σελίδα → ΟΛΟ το δέντρο από κάτω (τα άμεσα παιδιά είναι
        //     συνήθως ευρετήρια· η ουσία βρίσκεται βαθύτερα).
        if ($pageId) {
            $base = '/api/v2/pages/' . $pageId . '/descendants?limit=250&depth=10';
            $cur = '';
            for ($guard = 0; $guard < 8; $guard++) {
                $cr = cnp_safe_fetch($rootI . $base . $cur);
                if (empty($cr['ok'])) { break; }
                $cj = json_decode($cr['body'], true);
                foreach ($cj['results'] ?? [] as $c) {
                    if (($c['type'] ?? 'page') !== 'page') { continue; }
                    $conf[] = ['id' => (string) $c['id'], 'type' => 'confluence', 'title' => (string) $c['title'],
                        'link' => $rootI . '/pages/' . $c['id'], 'cat' => 0];
                }
                $cur = cnp_cursor_of($cj);
                if ($cur === '') { break; }
            }
        }
        // 2β. αλλιώς (ή αν δεν είχε παιδιά) → όλο το space, με σελιδοποίηση
        if (!$conf && $spaceKey) {
            $sr = cnp_safe_fetch($rootI . '/api/v2/spaces?keys=' . rawurlencode($spaceKey));
            $sj = !empty($sr['ok']) ? json_decode($sr['body'], true) : null;
            $sid = $sj['results'][0]['id'] ?? null;
            if ($sid) {
                $base = '/api/v2/spaces/' . $sid . '/pages?limit=250';
                $cur = '';
                for ($guard = 0; $guard < 8; $guard++) {
                    $pr = cnp_safe_fetch($rootI . $base . $cur);
                    if (empty($pr['ok'])) { break; }
                    $pj = json_decode($pr['body'], true);
                    foreach ($pj['results'] ?? [] as $c) {
                        $conf[] = ['id' => (string) $c['id'], 'type' => 'confluence', 'title' => (string) $c['title'],
                            'link' => $rootI . '/pages/' . $c['id'], 'cat' => 0];
                    }
                    $cur = cnp_cursor_of($pj);
                    if ($cur === '') { break; }
                }
            }
        }
        if ($conf) {
            $have = [];
            foreach (Capsule::table('mod_cpm_kb')->whereIn('source_url', array_column($conf, 'link'))
                ->pluck('source_url') as $u) { $have[$u] = true; }
            foreach ($conf as &$c2) { $c2['catName'] = $spaceKey ?: 'Wiki'; $c2['exists'] = isset($have[$c2['link']]); }
            unset($c2);
            out(['ok' => true, 'mode' => 'confluence', 'site' => $rootI, 'total' => count($conf),
                'cats' => [], 'items' => $conf,
                'note' => 'Οι σελίδες-ευρετήρια (χωρίς δικό τους κείμενο) παραλείπονται αυτόματα κατά την εισαγωγή.']);
        }
    }

    // 3) απλή σελίδα
    $pg = cnp_safe_fetch($urlI);
    if (empty($pg['ok'])) { fail($pg['error']); }
    $art = cnp_html_article($pg['body']);
    if (trim(strip_tags($art['html'])) === '') { fail('Δεν βρέθηκε περιεχόμενο σε αυτή τη σελίδα'); }
    out(['ok' => true, 'mode' => 'page', 'site' => $rootI,
        'items' => [['id' => 0, 'title' => $art['title'] ?: $urlI, 'link' => $pg['url'], 'cat' => 0,
            'catName' => '', 'exists' => Capsule::table('mod_cpm_kb')->where('source_url', $pg['url'])->exists()]]]);

case 'kb_import_commit':                 // εισαγωγή επιλεγμένων άρθρων στην τράπεζα
    $items = (array) ($in['items'] ?? []);
    if (!$items) { fail('Δεν διάλεξες άρθρα'); }
    if (count($items) > 120) { fail('Πολλά άρθρα μαζί — διάλεξε έως 120'); }
    $validI = array_column(cnp_ticket_cats()['area'], 'id');
    $areaI = in_array((int) ($in['areaId'] ?? 0), $validI, true) ? (int) $in['areaId'] : 0;
    $tagI = mb_substr(trim($in['tags'] ?? ''), 0, 190);
    $ok = 0; $skip = 0; $errs = [];
    foreach ($items as $it) {
        $link = trim($it['link'] ?? '');
        if ($link === '') { continue; }
        $exists = Capsule::table('mod_cpm_kb')->where('source_url', $link)->first();
        if ($exists && empty($in['overwrite'])) { $skip++; continue; }
        $html = ''; $title = trim($it['title'] ?? '');
        if (($it['type'] ?? '') === 'confluence' && !empty($it['id'])) {   // Confluence api/v2
            $r = cnp_safe_fetch(cnp_site_root($link) . '/api/v2/pages/'
                . preg_replace('/\D/', '', $it['id']) . '?body-format=export_view');
            if (!empty($r['ok'])) {
                $j = json_decode($r['body'], true);
                $html = (string) ($j['body']['export_view']['value'] ?? '');
                if ($title === '') { $title = (string) ($j['title'] ?? ''); }
            }
            if (trim(strip_tags(cnp_clean_html($html, 60000))) === '') { $skip++; continue; }  // σελίδα-ευρετήριο
        } elseif (!empty($it['id']) && !empty($it['type'])) {     // WP REST → καθαρό content
            $r = cnp_safe_fetch(cnp_site_root($link) . '/wp-json/wp/v2/' . preg_replace('/[^a-z]/', '', $it['type'])
                . '/' . (int) $it['id'] . '?_fields=title,content,link');
            if (!empty($r['ok'])) {
                $j = json_decode($r['body'], true);
                $html = (string) ($j['content']['rendered'] ?? '');
                if ($title === '') { $title = html_entity_decode(strip_tags($j['title']['rendered'] ?? ''), ENT_QUOTES, 'UTF-8'); }
            }
        }
        if ($html === '') {                                        // fallback: κατέβασε τη σελίδα
            $r = cnp_safe_fetch($link);
            if (empty($r['ok'])) { $errs[] = $title ?: $link; continue; }
            $a = cnp_html_article($r['body']);
            $html = $a['html'];
            if ($title === '') { $title = $a['title']; }
        }
        $clean = cnp_clean_html(cnp_absolutize_html($html, $link), 60000);
        if ($title === '' || trim(strip_tags($clean)) === '') { $errs[] = $title ?: $link; continue; }
        // (1) κενό ΑΝΤΙ για κάθε tag — αλλιώς τα κελιά πινάκων κολλάνε σε μία λέξη
        //     («publishκατηγοριαερωτησηαπαντησηναι»).
        // (2) html_entity_decode ΠΡΙΝ την εξαγωγή: το Confluence κωδικοποιεί τα ελληνικά ως
        //     &alpha;&omicron;… και οι λέξεις γέμιζαν «alpha, omicron, chi».
        $plain = html_entity_decode(preg_replace('/<[^>]+>/', ' ', $clean), ENT_QUOTES | ENT_HTML5, 'UTF-8');
        $kw = implode(', ', array_slice(cnp_words($title . ' ' . mb_substr($plain, 0, 1800)), 0, 18));
        // 4-byte (emoji) εκτός — DB utf8mb3, αλλιώς αποθηκεύεται ως ????
        $title = trim(preg_replace('/[\x{10000}-\x{10FFFF}]/u', '', $title));
        $row = ['title' => mb_substr($title, 0, 255), 'keywords' => mb_substr($kw, 0, 500),
            'solution' => $clean, 'tags' => $tagI, 'area_id' => $areaI, 'rel_areas' => '',
            'source_url' => mb_substr($link, 0, 500), 'updated_at' => date('Y-m-d H:i:s')];
        if ($exists) {
            Capsule::table('mod_cpm_kb')->where('id', $exists->id)->update($row);
        } else {
            Capsule::table('mod_cpm_kb')->insert($row + ['created_by' => $adminId, 'created_at' => date('Y-m-d H:i:s')]);
        }
        $ok++;
    }
    out(['ok' => true, 'imported' => $ok, 'skipped' => $skip, 'failed' => count($errs),
        'failedTitles' => array_slice($errs, 0, 10)]);

case 'kb_del':
    Capsule::table('mod_cpm_kb')->where('id', (int) ($in['id'] ?? 0))->delete();
    out(['ok' => true]);

case 'kb_use':                          // μέτρηση χρησιμότητας (κλικ σε πρόταση)
    Capsule::table('mod_cpm_kb')->where('id', (int) ($in['id'] ?? 0))->increment('uses');
    out(['ok' => true]);

/* ============ 🖥 REMOTE ΣΥΝΕΔΡΙΕΣ (χρονομέτρηση + χρέωση) ============ */
case 'rdp_file':                        // ⬇ έτοιμο .rdp αρχείο (ανοίγει το mstsc)
    $ip9 = trim($_GET['ip'] ?? '');
    if (!filter_var($ip9, FILTER_VALIDATE_IP) && !preg_match('/^[a-zA-Z0-9.\-]{3,190}$/', $ip9)) {
        fail('ip');
    }
    $label9 = preg_replace('/[^a-zA-Z0-9.\-]/', '_', $_GET['label'] ?? $ip9);
    $rdp = "full address:s:$ip9\r\n"
        . "prompt for credentials:i:1\r\n"
        . "screen mode id:i:2\r\n"
        . "desktopwidth:i:1920\r\ndesktopheight:i:1080\r\n"
        . "session bpp:i:32\r\n"
        . "compression:i:1\r\n"
        . "audiomode:i:0\r\n"
        . "redirectclipboard:i:1\r\n"
        . "redirectprinters:i:0\r\n"
        . "autoreconnection enabled:i:1\r\n"
        . "authentication level:i:2\r\n"
        . "negotiate security layer:i:1\r\n";
    header('Content-Type: application/x-rdp');
    header('Content-Disposition: attachment; filename="CloudOn-' . $label9 . '.rdp"');
    header('Content-Length: ' . strlen($rdp));
    echo $rdp;
    exit;

case 'remote_active':                   // η τρέχουσα ανοιχτή συνεδρία μου
