case 'users':                          // λίστα χειριστών — δικαίωμα «Σύστημα»
    $fullRoles = array_filter(array_map('intval', explode(',',
        (string) (Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')
            ->where('setting', 'full_access_roles')->value('value') ?: '1'))));
    out(['users' => array_map(function ($a) use ($fullRoles) {
            $isFullU = in_array((int) $a->roleid, $fullRoles, true);
            return ['id' => (int) $a->id, 'username' => $a->username,
                'name' => trim($a->firstname . ' ' . $a->lastname), 'email' => $a->email,
                'roleid' => (int) $a->roleid, 'disabled' => (bool) $a->disabled,
                'full' => $isFullU, 'areas' => cnp_admin_areas((int) $a->id, $isFullU),
                /* Τα δικαιώματα δίνονται από τις ΟΜΑΔΕΣ. Εδώ τα δείχνουμε μόνο,
                   μαζί με τυχόν παλιά προσωπική εξαίρεση ώστε να μπορεί να λυθεί. */
                'teams' => Capsule::table('mod_cpm_team_members as m')
                    ->join('mod_cpm_teams as t', 't.id', '=', 'm.team_id')
                    ->where('m.admin_id', (int) $a->id)->pluck('t.name')->all(),
                'personal' => array_values(array_intersect(cnp_perm_keys(),
                    array_filter(array_map('trim', explode(',', Db::pref((int) $a->id, 'areas', ''))))))];
        }, Capsule::table('tbladmins')->orderBy('disabled')->orderBy('username')->get()->all()),
        'areaNames' => (function () {
            $nm = [];
            foreach (cnp_area_defs() as $k => $v) { $nm[$k] = $v[0]; }
            foreach (cnp_caps() as $k => $v) {
                $ar = substr($k, 0, strpos($k, '.'));
                $nm[$k] = (cnp_area_defs()[$ar][0] ?? $ar) . ' → ' . $v[1];
            }
            return $nm;
        })(),
        /* Ποιοι ΡΟΛΟΙ του WHMCS φτάνουν πραγματικά στην εφαρμογή. Χρειάζονται
           ΔΥΟ πράγματα, και τα δύο εκτός του δικού μας συστήματος:
             1. ο ρόλος στη λίστα `access` του addon — αλλιώς «Access has not
                been given for your admin role group»
             2. το δικαίωμα WHMCS #46 «Addon Modules» — αλλιώς
                accessdenied.php?permid=46, πριν καν φορτώσει το addon.
           Χωρίς αυτά, όσα δικαιώματα κι αν οριστούν εδώ δεν μετράνε. */
        'addonRoles' => (function () {
            $acc = array_values(array_filter(array_map('intval', explode(',',
                (string) Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')
                    ->where('setting', 'access')->value('value')))));
            $out = [];
            foreach ($acc as $rid) {
                if (Capsule::table('tbladminperms')->where('roleid', $rid)->where('permid', 46)->exists()) {
                    $out[] = $rid;
                }
            }
            return $out;
        })(),
        'roles' => array_map(function ($r) use ($fullRoles) {
            return ['id' => (int) $r->id, 'name' => $r->name,
                'full' => in_array((int) $r->id, $fullRoles, true)];
        }, Capsule::table('tbladminroles')->orderBy('id')->get()->all())]);

case 'addon_access_grant':               // δώσε στον ρόλο πρόσβαση στο addon
    if (!$FULL) { fail('perm', 403); }
    $rid9 = (int) ($in['role'] ?? 0);
    if (!$rid9 || !Capsule::table('tbladminroles')->where('id', $rid9)->exists()) { fail('role'); }
    $row9 = Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')->where('setting', 'access');
    $cur9 = array_values(array_filter(array_map('intval', explode(',', (string) $row9->value('value')))));
    $did9 = [];
    if (!in_array($rid9, $cur9, true)) {
        $cur9[] = $rid9;
        sort($cur9);
        $row9->update(['value' => implode(',', $cur9)]);
        $did9[] = 'access';
    }
    // Το WHMCS #46 «Addon Modules» — χωρίς αυτό η σελίδα δεν ανοίγει καν.
    if (!Capsule::table('tbladminperms')->where('roleid', $rid9)->where('permid', 46)->exists()) {
        Capsule::table('tbladminperms')->insert(['roleid' => $rid9, 'permid' => 46]);
        $did9[] = 'perm46';
    }
    if ($did9) {
        logActivity('CloudOn PM: πρόσβαση στο addon για τον ρόλο #' . $rid9
            . ' [' . implode('+', $did9) . '] (από admin ' . $adminId . ')');
    }
    out(['ok' => true, 'roles' => $cur9, 'granted' => $did9]);

case 'user_areas_save':                 // προσωπική εξαίρεση: ενότητες εκτός ομάδας
    $uid7 = (int) ($in['id'] ?? 0);
    if (!$uid7 || !Capsule::table('tbladmins')->where('id', $uid7)->exists()) { fail('user'); }
    $areas7 = cnp_perm_clean((array) ($in['areas'] ?? []));
    Db::setPref($uid7, 'areas', implode(',', $areas7));
    out(['ok' => true, 'areas' => $areas7]);

case 'user_save':
    if (!$FULL) {
        fail('perm', 403);
    }
    $uid = (int) ($in['id'] ?? 0);
    $roleid = (int) ($in['roleid'] ?? 0);
    if (!Capsule::table('tbladminroles')->where('id', $roleid)->exists()) {
        fail('Άκυρος ρόλος');
    }
    $email = trim($in['email'] ?? '');
    if ($email !== '' && !filter_var($email, FILTER_VALIDATE_EMAIL)) {
        fail('Άκυρο email');
    }
    $row = ['firstname' => mb_substr(trim($in['first'] ?? ''), 0, 60),
        'lastname' => mb_substr(trim($in['last'] ?? ''), 0, 60),
        'email' => $email, 'roleid' => $roleid];
    if ($uid) {
        if (!Capsule::table('tbladmins')->where('id', $uid)->exists()) {
            fail('user', 404);
        }
        Capsule::table('tbladmins')->where('id', $uid)->update($row + ['updated_at' => date('Y-m-d H:i:s')]);
        out(['ok' => true, 'id' => $uid]);
    }
    $uname = preg_replace('/[^A-Za-z0-9._-]/', '', trim($in['username'] ?? ''));
    if (strlen($uname) < 3) {
        fail('Username τουλάχιστον 3 χαρακτήρες (λατινικά/αριθμοί)');
    }
    if (Capsule::table('tbladmins')->whereRaw('LOWER(username) = ?', [strtolower($uname)])->exists()) {
        fail('Το username υπάρχει ήδη');
    }
    $plain = substr(strtr(base64_encode(random_bytes(24)), '+/', 'Kx'), 0, 14);
    $depts = ',' . implode(',', Capsule::table('tblticketdepartments')->pluck('id')->all()) . ',';
    $uuid = sprintf('%08x-%04x-4%03x-%04x-%012x', random_int(0, 0xffffffff), random_int(0, 0xffff),
        random_int(0, 0xfff), random_int(0x8000, 0xbfff), random_int(0, 0xffffffffffff));
    $uid = Capsule::table('tbladmins')->insertGetId($row + ['username' => $uname,
        'password' => password_hash($plain, PASSWORD_DEFAULT),
        'passwordhash' => password_hash($plain, PASSWORD_DEFAULT),   // WHMCS 9 ελέγχει ΑΥΤΟ στο login
        'uuid' => $uuid, 'authmodule' => '', 'authdata' => '', 'signature' => '', 'notes' => 'Δημιουργήθηκε από CloudOn Projects',
        'template' => 'blend', 'language' => '', 'disabled' => 0, 'loginattempts' => 0,
        'supportdepts' => $depts, 'ticketnotifications' => '', 'homewidgets' => '',
        'created_at' => date('Y-m-d H:i:s'), 'updated_at' => date('Y-m-d H:i:s')]);
    out(['ok' => true, 'id' => $uid, 'password' => $plain]);

case 'user_pass':                      // reset κωδικού → νέος, εμφανίζεται μία φορά
    if (!$FULL) {
        fail('perm', 403);
    }
    $uid = (int) ($in['id'] ?? 0);
    if (!Capsule::table('tbladmins')->where('id', $uid)->exists()) {
        fail('user', 404);
    }
    $plain = substr(strtr(base64_encode(random_bytes(24)), '+/', 'Kx'), 0, 14);
    Capsule::table('tbladmins')->where('id', $uid)
        ->update(['password' => password_hash($plain, PASSWORD_DEFAULT),
            'passwordhash' => password_hash($plain, PASSWORD_DEFAULT), 'loginattempts' => 0,
            'updated_at' => date('Y-m-d H:i:s')]);

    /* Προαιρετική αποστολή στον ίδιο τον χειριστή. Παρακάμπτουμε το
       Notify::send(): εκείνο σέβεται τη γενική ρύθμιση ειδοποιήσεων και την
       προσωπική εξαίρεση του χρήστη — ένας κωδικός πρόσβασης δεν είναι
       ειδοποίηση, πρέπει να φύγει. Ο κωδικός ΔΕΝ καταγράφεται πουθενά. */
    $sent = false;
    $mailTo = '';
    if (!empty($in['send'])) {
        $u9 = Capsule::table('tbladmins')->where('id', $uid)
            ->first(['username', 'firstname', 'lastname', 'email']);
        $mailTo = trim((string) $u9->email);
        if (!filter_var($mailTo, FILTER_VALIDATE_EMAIL)) {
            out(['ok' => true, 'password' => $plain, 'sent' => false,
                'mailError' => 'Ο χειριστής δεν έχει έγκυρο email — ο κωδικός εμφανίζεται μόνο εδώ']);
        }
        $url9 = 'https://' . ($_SERVER['HTTP_HOST'] ?? 'my.cloudon.gr') . '/project/';
        $sent = Notify::sendTo($mailTo,
            'Ο νέος σου κωδικός πρόσβασης — CloudOn Project Manager',
            '<p>Γεια σου ' . htmlspecialchars(trim($u9->firstname . ' ' . $u9->lastname) ?: $u9->username, ENT_QUOTES, 'UTF-8') . ',</p>'
            . '<p>Ο κωδικός σου μηδενίστηκε από διαχειριστή. Τα νέα στοιχεία εισόδου:</p>'
            . '<p style="font-size:15px;line-height:2">Χρήστης: <b>' . htmlspecialchars($u9->username, ENT_QUOTES, 'UTF-8') . '</b><br>'
            . 'Κωδικός: <b style="font-family:monospace;font-size:17px;letter-spacing:1px">'
            . htmlspecialchars($plain, ENT_QUOTES, 'UTF-8') . '</b></p>'
            . '<p><a href="' . htmlspecialchars($url9, ENT_QUOTES, 'UTF-8') . '">Είσοδος στην εφαρμογή</a></p>'
            . '<p style="color:#8291a9;font-size:12.5px">Άλλαξέ τον μόλις μπεις, από «Το προφίλ μου». '
            . 'Αν δεν ζήτησες εσύ αυτή την αλλαγή, ενημέρωσε αμέσως τον διαχειριστή.</p>');
        // Καταγράφεται ΟΤΙ στάλθηκε — ποτέ ο κωδικός.
        logActivity('CloudOn PM: reset κωδικού για «' . $u9->username . '» και αποστολή στο '
            . $mailTo . ' (από admin ' . $adminId . ')');
    }
    out(['ok' => true, 'password' => $plain, 'sent' => $sent, 'mailTo' => $mailTo,
        'mailError' => (!empty($in['send']) && !$sent) ? 'Η αποστολή απέτυχε — δώσε τον κωδικό με άλλον τρόπο' : '']);

case 'user_toggle':
    if (!$FULL) {
        fail('perm', 403);
    }
    $uid = (int) ($in['id'] ?? 0);
    if ($uid === $adminId) {
        fail('Δεν μπορείς να απενεργοποιήσεις τον εαυτό σου');
    }
    $u = Capsule::table('tbladmins')->where('id', $uid)->first(['disabled']);
    if (!$u) {
        fail('user', 404);
    }
    Capsule::table('tbladmins')->where('id', $uid)->update(['disabled' => $u->disabled ? 0 : 1,
        'updated_at' => date('Y-m-d H:i:s')]);
    out(['ok' => true, 'disabled' => !$u->disabled]);

case 'user_del':
    if (!$FULL) {
        fail('perm', 403);
    }
    $uid = (int) ($in['id'] ?? 0);
    if ($uid === $adminId) {
        fail('Δεν μπορείς να διαγράψεις τον εαυτό σου');
    }
    $u = Capsule::table('tbladmins')->where('id', $uid)->first(['roleid', 'username']);
    if (!$u) {
        fail('user', 404);
    }
    // μην μείνει το σύστημα χωρίς κανέναν ενεργό διαχειριστή
    $fullRoles = array_filter(array_map('intval', explode(',',
        (string) (Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')
            ->where('setting', 'full_access_roles')->value('value') ?: '1'))));
    if (in_array((int) $u->roleid, $fullRoles, true)
        && Capsule::table('tbladmins')->whereIn('roleid', $fullRoles)->where('disabled', 0)->where('id', '!=', $uid)->count() === 0) {
        fail('Είναι ο τελευταίος ενεργός διαχειριστής');
    }
    Capsule::table('tbladmins')->where('id', $uid)->delete();
    // καθάρισμα συμμετοχών στο app (ιστορικό tasks/χρόνου μένει άθικτο)
    Capsule::table('mod_cpm_project_members')->where('admin_id', $uid)->delete();
    Capsule::table('mod_cpm_team_members')->where('admin_id', $uid)->delete();
    Capsule::table('mod_cpm_watchers')->where('admin_id', $uid)->delete();
    Capsule::table('mod_cpm_notifications')->where('admin_id', $uid)->delete();
    out(['ok' => true]);

case 'ticket_att':                     // ασφαλές κατέβασμα συνημμένου ticket
    $tid = (int) ($_GET['ticket'] ?? 0);
    $rid = (int) ($_GET['rid'] ?? 0);
    $idx = (int) ($_GET['i'] ?? 0);
    $tk = Capsule::table('tbltickets')->where('id', $tid)->first(['flag', 'attachment']);
    if (!$tk) {
        fail('ticket', 404);
    }
    if (!$FULL && (int) $tk->flag !== $adminId && (int) $tk->flag !== 0) {
        fail('ticket', 403);
    }
    if ($rid) {
        $row = Capsule::table('tblticketreplies')->where('id', $rid)->where('tid', $tid)->first(['attachment']);
        $attStr = $row->attachment ?? '';
    } else {
        $attStr = $tk->attachment ?? '';
    }
    $parts = array_values(array_filter(explode('|', (string) $attStr)));
    $stored = $parts[$idx] ?? null;
    $path = $stored ? realpath(__DIR__ . '/../attachmentsnew/' . $stored) : false;
    if (!$stored || !$path || strpos($path, realpath(__DIR__ . '/../attachmentsnew') . DIRECTORY_SEPARATOR) !== 0 || !is_file($path)) {
        fail('file', 404);
    }
    header('Content-Type: application/octet-stream');
    header('Content-Disposition: attachment; filename="' . preg_replace('/^\\d+_/', '', $stored) . '"');
    header('Content-Length: ' . filesize($path));
    readfile($path);
    exit;

case 'ticket_update':
    $tid = (int) ($in['ticket'] ?? 0);
    $tk = Capsule::table('tbltickets')->where('id', $tid)->first(['flag']);
    if (!$tk) {
        fail('ticket', 404);
    }
    if (!$FULL && (int) $tk->flag !== $adminId && (int) $tk->flag !== 0) {
        fail('ticket', 403);
    }
    $upd = ['ticketid' => $tid];
    if (array_key_exists('status', $in) && $in['status'] !== '') {
        $upd['status'] = $in['status'];
    }
    if ($FULL && array_key_exists('flag', $in)) {
        $upd['flag'] = (int) $in['flag']; // ανάθεση: μόνο διαχειριστές
    }
    if ($FULL && array_key_exists('urgency', $in) && in_array($in['urgency'], ['Low', 'Medium', 'High'], true)) {
        $upd['priority'] = $in['urgency'];
    }
    $uname = Capsule::table('tbladmins')->where('id', $adminId)->value('username');
    $r = localAPI('UpdateTicket', $upd, $uname);
    /* Ο trigger ticket_status ήταν τεκμηριωμένος αλλά δεν πυροδοτούνταν ΠΟΤΕ —
       όποιος έφτιαχνε κανόνα πάνω του δεν θα καταλάβαινε γιατί δεν τρέχει. */
    if (($r['result'] ?? '') === 'success' && isset($upd['status'])) {
        if (!class_exists(Auto::class)) {
            require_once __DIR__ . '/../modules/addons/cloudonprojects/lib/Auto.php';
        }
        try {
            Auto::run('ticket_status', ['ticketId' => $tid, 'status' => (string) $upd['status']]);
        } catch (\Throwable $e) {
        }
    }
    out(['ok' => ($r['result'] ?? '') === 'success', 'msg' => $r['message'] ?? null]);

case 'ticket_delete':
    /* ΟΡΙΣΤΙΚΗ ΔΙΑΓΡΑΦΗ ΑΙΤΗΜΑΤΟΣ.
       Το δικαίωμα ελέγχεται στον server από τον κατάλογο ενεργειών
       (support.tickets.delete) — δεν αρκεί να κρυφτεί το κουμπί.

       Δύο βήματα επίτηδες: πρώτα `probe`, που λέει ΤΙ χάνεται, και μετά η
       διαγραφή. Δεν θέλουμε «είσαι σίγουρος;» στα τυφλά όταν από πίσω
       κρέμονται απαντήσεις πελάτη, καταγεγραμμένος χρόνος ή συνημμένα. */
    $tid = (int) ($in['ticket'] ?? 0);
    $tk  = Capsule::table('tbltickets')->where('id', $tid)->first(['id', 'tid', 'title', 'status', 'userid', 'name', 'email']);
    if (!$tk) {
        fail('ticket', 404);
    }
    $nRep = (int) Capsule::table('tblticketreplies')->where('tid', $tid)->count();
    $nNot = (int) Capsule::table('tblticketnotes')->where('ticketid', $tid)->count();
    $nAtt = (int) Capsule::table('tblticketreplies')->where('tid', $tid)->where('attachment', '!=', '')->count()
          + (Capsule::table('tbltickets')->where('id', $tid)->where('attachment', '!=', '')->count() ? 1 : 0);

    /* Η εργασία που άνοιξε από το ticket. Αν έχει πάνω της πραγματική δουλειά
       (χρόνο ή σχόλια) ΔΕΝ τη σβήνουμε μαζί: ξεκολλάει και μένει. Αλλιώς είναι
       απλώς ο δίδυμος του ticket και φεύγει μαζί του. */
    $tsk = Capsule::table('mod_cpm_tasks')->where('ticketid', $tid)->first(['id', 'title']);
    $tskMins = $tsk ? (int) Capsule::table('mod_cpm_timelogs')->where('task_id', $tsk->id)->sum('minutes') : 0;
    $tskCmts = $tsk ? (int) Capsule::table('mod_cpm_comments')->where('task_id', $tsk->id)->count() : 0;
    $tskKeep = $tsk && ($tskMins > 0 || $tskCmts > 0);

    if (!empty($in['probe'])) {
        out(['ok' => true, 'tid' => (string) $tk->tid, 'title' => (string) $tk->title,
            'status' => (string) $tk->status, 'replies' => $nRep, 'notes' => $nNot, 'atts' => $nAtt,
            'task' => $tsk ? ['id' => (int) $tsk->id, 'mins' => $tskMins, 'comments' => $tskCmts,
                'keep' => $tskKeep] : null]);
    }

    /* Η εργασία πρώτα, όσο υπάρχει ακόμη ο σύνδεσμος. */
    if ($tsk && !$tskKeep) {
        foreach (Capsule::table('mod_cpm_files')->where('task_id', $tsk->id)->pluck('id') as $fid9) {
            try { Storage::delete((int) $fid9); } catch (\Throwable $e) { }
        }
        foreach (['mod_cpm_activity', 'mod_cpm_checklist', 'mod_cpm_comments', 'mod_cpm_deps',
                     'mod_cpm_field_values', 'mod_cpm_files', 'mod_cpm_help', 'mod_cpm_interactions',
                     'mod_cpm_reminders', 'mod_cpm_timelogs', 'mod_cpm_watchers'] as $tb9) {
            if (Capsule::schema()->hasTable($tb9)) { Capsule::table($tb9)->where('task_id', $tsk->id)->delete(); }
        }
        Capsule::table('mod_cpm_deps')->where('depends_on', $tsk->id)->delete();
        Capsule::table('mod_cpm_tasks')->where('id', $tsk->id)->delete();
    } elseif ($tsk) {
        Capsule::table('mod_cpm_tasks')->where('id', $tsk->id)->update(['ticketid' => null]);
    }

    $uname9 = Capsule::table('tbladmins')->where('id', $adminId)->value('username');
    $r9 = localAPI('DeleteTicket', ['ticketid' => $tid], $uname9);
    if (($r9['result'] ?? '') !== 'success') {
        fail($r9['message'] ?? 'Το WHMCS δεν διέγραψε το αίτημα', 500);
    }

    /* Δικά μας υπολείμματα. Οι «δείκτες» επικοινωνίας λένε μόνο «άνοιξε ticket
       #…» και δεν έχουν νόημα χωρίς αυτό· οι υπόλοιπες επικοινωνίες είναι
       πραγματικές, οπότε απλώς ξεκολλάνε. */
    Capsule::table('mod_cpm_interactions')->where('ticketid', $tid)->where('kind', 'ticket')->delete();
    Capsule::table('mod_cpm_interactions')->where('ticketid', $tid)->update(['ticketid' => null]);
    foreach (['mod_cpm_ticket_class' => 'ticketid', 'mod_cpm_ticket_alias' => 'tid',
                 'mod_cpm_ticket_idle' => 'ticket_id', 'mod_cpm_ticket_usage' => 'ticketid'] as $tb9 => $cl9) {
        if (Capsule::schema()->hasTable($tb9)) { Capsule::table($tb9)->where($cl9, $tid)->delete(); }
    }
    /* Το mod_cpm_ai_calls ΔΕΝ πειράζεται: η κλήση όντως έγινε και η Τηλεφωνική
       δραστηριότητα δείχνει «ticket διαγράφηκε» — αυτό είναι το σωστό. */

    $who9 = Db::adminName($adminId);
    $lost9 = [];
    if ($nRep) { $lost9[] = $nRep . ($nRep === 1 ? ' απάντηση' : ' απαντήσεις'); }
    if ($nNot) { $lost9[] = $nNot . ($nNot === 1 ? ' σημείωση' : ' σημειώσεις'); }
    if ($nAtt) { $lost9[] = $nAtt . ($nAtt === 1 ? ' συνημμένο' : ' συνημμένα'); }
    if ($tsk && !$tskKeep) { $lost9[] = 'την εργασία #' . $tsk->id; }
    $msg9 = 'Διαγράφηκε αίτημα #' . $tk->tid . ' «' . mb_substr((string) $tk->title, 0, 70) . '» από ' . $who9
        . ($lost9 ? ' — μαζί με ' . implode(', ', $lost9) : '')
        . ($tskKeep ? ' · η εργασία #' . $tsk->id . ' κρατήθηκε (έχει δουλειά πάνω της)' : '');
    foreach (cnp_full_admin_ids() as $aid9) {
        if ($aid9 === $adminId) { continue; }
        Db::pushNotification($aid9, 'deleted', mb_substr($msg9, 0, 240), '/project/#/inbox');
    }
    logActivity('CloudOn PM: ' . $msg9 . ' (admin ' . $adminId . ')');
    out(['ok' => true, 'taskKept' => $tskKeep ? (int) $tsk->id : 0]);

case 'ticket_note':
    $tid = (int) ($in['ticket'] ?? 0);
    $msg = trim($in['body'] ?? '');
    $tk = Capsule::table('tbltickets')->where('id', $tid)->first(['tid', 'title', 'did']);
    if (!$tk || $msg === '') {
        fail('input');
    }
    $task = Db::taskForTicket($tid);
    if (!$task) {
        // Εργασία από ticket: ανήκει στο department του, χωρίς έργο.
        $ntid = Db::saveTask(0, ['project_id' => null, 'dept_id' => (int) $tk->did,
            'title' => '[#' . $tk->tid . '] ' . mb_substr($tk->title, 0, 180),
            'status_id' => Db::firstStatusId(), 'ticketid' => $tid], $adminId);
        $task = Db::task($ntid);
    }
    if (!$task) {
        fail('task');
    }
    $to = ($in['to'] ?? '') !== '' && $in['to'] !== null ? (int) $in['to'] : null;
    Db::addComment($task->id, $adminId, mb_substr($msg, 0, 60000), $to);
    Notify::commented($task->id, $adminId, $msg);
    if ($to !== null) {
        Notify::commentTo($task->id, $adminId, $msg, $to);
    }
    Notify::watchers($task->id, $adminId, 'Σχόλιο στο: ' . $task->title, null);
    out(['ok' => true]);

/* ================= UNIFIED SEARCH (⌘K) ================= */
/* ── @mentions: «πρόσεξέ με» (GoodDay-style). Ο αναφερόμενος παίρνει ειδοποίηση
   (καμπανάκι + Web Push) και τη βλέπει στο dashboard του («Η μέρα μου»). ── */
case 'mentions':                         // ανοιχτές αναφορές προς εμένα
    $items = [];
    foreach (Capsule::table('mod_cpm_notifications')->where('admin_id', $adminId)
        ->where('type', 'mention')->where('is_read', 0)->orderByDesc('id')->limit(15)->get() as $n) {
        $taskId = preg_match('/[?&]id=(\d+)/', (string) $n->url, $mm) ? (int) $mm[1] : 0;
        $items[] = ['id' => (int) $n->id, 'text' => $n->title, 'at' => $n->created_at, 'taskId' => $taskId];
    }
    out(['items' => $items]);

case 'mention_read':                     // την είδα → φεύγει από το dashboard
    Db::markNotifRead($adminId, (int) ($in['id'] ?? 0));
    out(['ok' => true]);

case 'search':
    $q = trim($_GET['q'] ?? '');
    if (mb_strlen($q) < 2) {
        out(['tasks' => [], 'tickets' => [], 'leads' => [], 'clients' => []]);
    }
    $like = '%' . $q . '%';
    $tasks = [];
    /* «#123» → η εργασία με αυτόν τον αριθμό, πρώτη-πρώτη (και αν είναι κλειστή). */
    if (preg_match('/^#?(\d{1,9})$/', $q, $mId)) {
        $tq = Capsule::table('mod_cpm_tasks as t')->leftJoin('mod_cpm_projects as p', 'p.id', '=', 't.project_id')
            ->where('t.id', (int) $mId[1])->select('t.id', 't.title', 't.assignee', 't.project_id', 'p.name as pname', 'p.color as pcolor')->first();
        if ($tq && ($FULL || (int) $tq->assignee === $adminId || Db::canSeeProject($adminId, $tq->project_id))) {
            $tasks[] = ['id' => (int) $tq->id, 'title' => '#' . $tq->id . ' ' . $tq->title, 'pname' => cnp_pn($tq->pname), 'pcolor' => $tq->pcolor ?: '#8595ac'];
        }
    }
    /* Και με τον αριθμό ticket: του WHMCS (μέσω της σύνδεσης) ή της παλιάς πλατφόρμας.
       Ο συνάδελφος θυμάται «το 4821», όχι τον τίτλο της εργασίας. */
    $tqq = Capsule::table('mod_cpm_tasks as t')->leftJoin('mod_cpm_projects as p', 'p.id', '=', 't.project_id')
        ->leftJoin('tbltickets as k', 'k.id', '=', 't.ticketid')
        ->where(function ($w) use ($like) {
            $w->where('t.title', 'like', $like)
              ->orWhere('t.ticket_ref', 'like', $like)
              ->orWhere('k.tid', 'like', $like);
        })
        ->orderBy('t.id', 'desc')->limit(6)
        ->select('t.id', 't.title', 't.assignee', 't.project_id', 't.ticket_ref', 'k.tid as tkno',
            'p.name as pname', 'p.color as pcolor');
    foreach ($tqq->get() as $t) {
        if (!$FULL && (int) $t->assignee !== $adminId && !Db::canSeeProject($adminId, $t->project_id)) {
            continue;
        }
        /* Οι εργασίες από ticket έχουν ήδη το «[#αριθμός]» στον τίτλο τους — δεν το
           γράφουμε δεύτερη φορά. */
        $no = $t->tkno ?: $t->ticket_ref;
        $show = $no && mb_strpos((string) $t->title, (string) $no) === false;
        $tasks[] = ['id' => (int) $t->id,
            'title' => ($show ? '🎫 #' . $no . ' · ' : '') . $t->title,
            'pname' => cnp_pn($t->pname), 'pcolor' => $t->pcolor ?: '#8595ac'];
    }
    $tickets = [];
    $tkq = Capsule::table('tbltickets')->where(function ($w) use ($like) {
        $w->where('title', 'like', $like)->orWhere('tid', 'like', $like)->orWhere('name', 'like', $like);
    })->orderBy('lastreply', 'desc')->limit(6);
    if (!$FULL) {
        $tkq->where('flag', $adminId);
    }
    foreach ($tkq->get(['id', 'tid', 'title', 'status']) as $t) {
        $tickets[] = ['id' => (int) $t->id, 'tid' => $t->tid, 'title' => $t->title, 'status' => $t->status];
    }
    $leads = [];
    foreach (Capsule::table('mod_cpm_leads')->where(function ($w) use ($like) {
        $w->where('company', 'like', $like)->orWhere('contact', 'like', $like)->orWhere('email', 'like', $like);
    })->limit(5)->get() as $l) {
        if (!$FULL && (int) $l->assignee !== $adminId && (int) $l->created_by !== $adminId) {
            continue;
        }
        $leads[] = ['id' => (int) $l->id, 'name' => $l->company ?: $l->contact, 'stage' => $l->stage];
    }
    $clients = [];
    /* Ο πελάτης είναι η πρώτη λέξη που γράφει κανείς στην αναζήτηση. Φτάνει να έχει
       πρόσβαση στην καρτέλα — δεν χρειάζεται να είναι διαχειριστής. */
    if (cnp_has_cap($adminId, $FULL, 'clients.card')) {
        foreach (Capsule::table('tblclients')->where(function ($w) use ($like) {
            $w->where('firstname', 'like', $like)->orWhere('lastname', 'like', $like)
              ->orWhere('companyname', 'like', $like)->orWhere('email', 'like', $like);
            cnp_afm_where($w, $like);
        })->limit(6)->get(['id', 'firstname', 'lastname', 'companyname', 'email', 'tax_id']) as $c) {
            $mail9 = preg_match('/@noreply\.cloudon\.gr$/i', (string) $c->email) ? '' : (string) $c->email;
            $clients[] = ['id' => (int) $c->id, 'email' => $mail9,
                'afm' => (string) $c->tax_id,
                'name' => html_entity_decode($c->companyname ?: trim($c->firstname . ' ' . $c->lastname),
                    ENT_QUOTES, 'UTF-8')];
        }
    }
    out(['tasks' => $tasks, 'tickets' => $tickets, 'leads' => $leads, 'clients' => $clients]);

/* ================= ΡΥΘΜΙΣΕΙΣ (in-app) ================= */
case 'settings_get':
    $keys = ['auto_task', 'notify_email', 'request_form', 'sales_target', 'cost_per_hour', 'team_roles', 'full_access_roles', 'ai_api_key', 'cv_ai_model',
        'overrun_on', 'overrun_pct', 'storage_driver', 's3_endpoint', 's3_region', 's3_bucket', 's3_key', 's3_secret', 's3_prefix'];
    $vals = [];
    foreach ($keys as $k) {
        $vals[$k] = (string) (Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')
            ->where('setting', $k)->value('value') ?? '');
    }
    /* Υπέρβαση εκτίμησης: ανοιχτή από προεπιλογή (ποτέ δεν αποθηκεύτηκε = on), 10%. */
    if (!Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')->where('setting', 'overrun_on')->exists()) { $vals['overrun_on'] = 'on'; }
    if ($vals['overrun_pct'] === '') { $vals['overrun_pct'] = '10'; }
    $vals['s3_secret_set'] = $vals['s3_secret'] !== '' ? '1' : '';   // δεν εκθέτουμε το secret
    $vals['s3_secret'] = '';
    /* Το AI key είναι μυστικό όπως κάθε άλλο: δεν φεύγει ποτέ προς τον browser.
       Στέλνουμε μόνο ένδειξη ότι υπάρχει και τα 4 τελευταία ψηφία, ώστε να
       αναγνωρίζεται ποιο κλειδί είναι χωρίς να αποκαλύπτεται. */
    $vals['ai_api_key_set']  = $vals['ai_api_key'] !== '' ? '1' : '';
    $vals['ai_api_key_tail'] = $vals['ai_api_key'] !== '' ? mb_substr($vals['ai_api_key'], -4) : '';
    $vals['ai_api_key'] = '';
    $sts = [];
    foreach (Db::statuses() as $s) {
        $cnt = Capsule::table('mod_cpm_tasks')->where('status_id', $s->id)->count();
        $sts[] = ['id' => (int) $s->id, 'title' => $s->title, 'color' => $s->color,
            'done' => (bool) $s->is_done, 'phase' => (string) ($s->phase ?? 'wait'), 'sort' => (int) $s->sort, 'tasks' => $cnt];
    }
    $phases = Db::PHASES;
    $types = [];
    foreach (Db::taskTypes() as $ty) {
        $types[] = ['id' => (int) $ty->id, 'name' => $ty->name, 'icon' => $ty->icon, 'color' => $ty->color,
            'reqA' => (bool) $ty->req_assignee, 'reqD' => (bool) $ty->req_due, 'reqE' => (bool) $ty->req_estimate];
    }
    /* Οι ομάδες χρειάζονται στις ρυθμίσεις των καρτών διαχείρισης (ποιος παίρνει, ποιος κλιμακώνει). */
    out(['phases' => $phases, 'settings' => $vals, 'statuses' => $sts, 'types' => $types,
        'teams' => array_map(function ($t) { return ['id' => (int) $t->id, 'name' => (string) $t->name]; },
            Capsule::table('mod_cpm_teams')->orderBy('name')->get(['id', 'name'])->all()),
        'cardsDefaults' => ['team' => DayPlan::teamId(), 'escTeam' => DayPlan::escTeamId()] + DayPlan::thresholds()]);

case 'settings_save':
    $allowed = ['auto_task', 'notify_email', 'request_form', 'sales_target', 'cost_per_hour', 'team_roles', 'full_access_roles', 'ai_api_key', 'cv_ai_model',
        'ticket_autoclose', 'ticket_autoclose_days', 'strict_areas', 'overrun_on', 'overrun_pct',
        'cards_on', 'cards_team', 'cards_esc_team', 'cards_age_days', 'cards_idle_days', 'cards_unassigned_days',
        'storage_driver', 's3_endpoint', 's3_region', 's3_bucket', 's3_key', 's3_secret', 's3_prefix'];
    foreach ((array) ($in['settings'] ?? []) as $k => $v) {
        if (!in_array($k, $allowed, true)) {
            continue;
        }
        // Κενό σε πεδίο μυστικού σημαίνει «μην αλλάξεις», όχι «σβήσε».
        if (in_array($k, ['s3_secret', 'ai_api_key'], true) && trim((string) $v) === '') { continue; }
        $v = mb_substr(trim((string) $v), 0, 500);
        $ex = Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')->where('setting', $k);
        if ($ex->exists()) {
            $ex->update(['value' => $v]);
        } else {
            Capsule::table('tbladdonmodules')->insert(['module' => 'cloudonprojects', 'setting' => $k, 'value' => $v]);
        }
    }
    out(['ok' => true]);

case 'storage_test':                      // health check σύνδεσης S3 (+ auto CORS)
    $stt = Storage::s3Test();
    if (!empty($stt['ok'])) {
        $cors = Storage::applyCors(['https://my.cloudon.gr']);
        $stt['msg'] .= ' · ' . $cors['msg'];
        if (empty($cors['ok'])) { $stt['ok'] = false; }
    }
    out($stt);

/* ── Γενικό API αρχείων (όλα τα modules, μέσω Storage) ── */
case 'file_presign_put':                  // direct-to-S3 upload (μεγάλα/βίντεο)
    $module = (string) ($in['module'] ?? '');
    if (!cnp_file_authz($adminId, $FULL, $module)) { fail('forbidden', 403); }
    if (!Storage::isS3()) { out(['mode' => 'multipart']); }   // local driver → ο client πέφτει σε file_upload
    $name = (string) ($in['filename'] ?? 'file');
    if (!cnp_file_ext_ok($name)) { fail('Μη επιτρεπτός τύπος αρχείου', 400); }
    $size = (int) ($in['size'] ?? 0);
    if ($size > 5 * 1024 * 1024 * 1024) { fail('Πολύ μεγάλο αρχείο (όριο 5GB)', 400); }
    $mime = mb_substr((string) ($in['mime'] ?? 'application/octet-stream'), 0, 120);
    $key = Storage::newKey($module ?: 'general', pathinfo($name, PATHINFO_EXTENSION), 's3');
    out(['mode' => 'direct', 'uploadUrl' => Storage::presignPutKey($key, $mime, 900), 'key' => $key,
        'headers' => ['Content-Type' => $mime]]);

case 'file_confirm':                      // καταχώρηση μετά από direct-to-S3 upload
    $module = (string) ($in['module'] ?? '');
    if (!cnp_file_authz($adminId, $FULL, $module)) { fail('forbidden', 403); }
    if ($module === 'library' && !cnp_lib_can($adminId, (int) ($in['ref_id'] ?? 0), true)) { fail('forbidden', 403); }
    $key = (string) ($in['key'] ?? '');
    $prefix = trim(Storage::config('s3_prefix', ''), '/');
    $rel = ($prefix !== '' && strpos($key, $prefix . '/') === 0) ? substr($key, strlen($prefix) + 1) : $key;
    if (!preg_match('#^' . preg_quote($module ?: 'general', '#') . '/\d{4}/\d{2}/[a-f0-9]{32}#', $rel)) { fail('Μη έγκυρο key', 400); }
    if (!Storage::exists($key, 's3')) { fail('Το αρχείο δεν βρέθηκε στο storage', 404); }
    $mime = mb_substr((string) ($in['mime'] ?? 'application/octet-stream'), 0, 120);
    $size = (int) ($in['size'] ?? 0);
    try { $h = Storage::s3()->headObject(['Bucket' => Storage::bucket(), 'Key' => $key]); $size = (int) $h['ContentLength']; if (!empty($h['ContentType'])) { $mime = $h['ContentType']; } } catch (\Throwable $e) {}
    $rec = Storage::registerExternal(['module' => $module, 'ref_type' => (string) ($in['ref_type'] ?? ''), 'ref_id' => (int) ($in['ref_id'] ?? 0),
        'storage_key' => $key, 'orig_name' => (string) ($in['orig_name'] ?? 'file'), 'mime' => $mime, 'size' => $size, 'uploaded_by' => $adminId]);
    out(['ok' => true, 'file' => cnp_file_row($rec)]);

case 'file_upload':                       // server-side upload (μικρά ή local driver) — multipart
    if (!empty($_FILES)) { $in = $_POST; }
    $module = (string) ($in['module'] ?? '');
    if (!cnp_file_authz($adminId, $FULL, $module)) { fail('forbidden', 403); }
    if ($module === 'library' && !cnp_lib_can($adminId, (int) ($in['ref_id'] ?? 0), true)) { fail('forbidden', 403); }
    $f = $_FILES['file'] ?? null;
    if (!$f || $f['error'] !== UPLOAD_ERR_OK) { fail('Σφάλμα ανεβάσματος', 400); }
    if (!cnp_file_ext_ok($f['name'])) { fail('Μη επιτρεπτός τύπος αρχείου', 400); }
    if ($f['size'] > 50 * 1024 * 1024) { fail('Πολύ μεγάλο για server upload — απαιτείται S3 (direct)', 400); }
    $rec = Storage::store(['module' => $module, 'ref_type' => (string) ($in['ref_type'] ?? ''), 'ref_id' => (int) ($in['ref_id'] ?? 0),
        'src' => $f['tmp_name'], 'orig_name' => $f['name'], 'mime' => $f['type'] ?: 'application/octet-stream', 'uploaded_by' => $adminId]);
    out(['ok' => true, 'file' => cnp_file_row($rec)]);

case 'file_list':                         // λίστα αρχείων ανά οντότητα
    $module = (string) ($_GET['module'] ?? '');
    if (!cnp_file_authz($adminId, $FULL, $module)) { fail('forbidden', 403); }
    if ($module === 'library' && !cnp_lib_can($adminId, (int) ($_GET['ref_id'] ?? 0))) { fail('forbidden', 403); }
    $q = Capsule::table('mod_cpm_storage')->where('module', $module);
    if (isset($_GET['ref_type'])) { $q->where('ref_type', (string) $_GET['ref_type']); }
    if (isset($_GET['ref_id'])) { $q->where('ref_id', (int) $_GET['ref_id']); }
    out(['files' => array_map('cnp_file_row', $q->orderByDesc('id')->limit(500)->get()->all())]);

case 'file_get':                          // προβολή/λήψη (s3→302 presigned, local→proxy stream)
    $rec = Storage::record((int) ($_GET['id'] ?? 0));
    if (!$rec) { fail('file', 404); }
    if (!cnp_file_authz($adminId, $FULL, $rec['module'])) { fail('file', 403); }
    if ($rec['module'] === 'library' && !cnp_lib_can($adminId, (int) $rec['ref_id'])) { fail('file', 403); }
    $mime = $rec['mime'] ?: 'application/octet-stream';
    /* Inline μόνο για παθητικούς τύπους· ό,τι θα μπορούσε να εκτελεστεί (html, svg,
       πηγαίος κώδικας) φεύγει ως λήψη — ακόμη κι αν ο τύπος έρθει «πειραγμένος». */
    $dl = !empty($_GET['dl']) || !cnp_mime_inline_ok($mime);
    if ($rec['driver'] === 's3') {
        header('Location: ' . Storage::presign($rec['id'], 300, $dl), true, 302);
        exit;
    }
    $stream = Storage::openRead($rec['id']);
    if (!$stream) { fail('file', 404); }
    header('Content-Type: ' . $mime);
    header('X-Content-Type-Options: nosniff');
    header('Content-Disposition: ' . ($dl ? 'attachment' : 'inline') . '; filename="' . rawurlencode($rec['orig_name'] ?: 'file') . '"');
    if ($rec['size']) { header('Content-Length: ' . (int) $rec['size']); }
    fpassthru($stream); fclose($stream); exit;

case 'file_delete':
    $rec = Storage::record((int) ($in['id'] ?? 0));
    if (!$rec) { fail('file', 404); }
    if (!cnp_file_authz($adminId, $FULL, $rec['module'])) { fail('forbidden', 403); }
    if ($rec['module'] === 'library' && !cnp_lib_can($adminId, (int) $rec['ref_id'], true)) { fail('forbidden', 403); }
    /* Πριν, όποιος είχε πρόσβαση στο module διέγραφε ΟΠΟΙΟΔΗΠΟΤΕ αρχείο με το id.
       Τώρα: ο ίδιος που το ανέβασε, ή Full, ή «Board: επεξεργασία». */
    if (!$FULL && (int) ($rec['uploaded_by'] ?? 0) !== $adminId && !cnp_has_cap($adminId, $FULL, 'projects.board.edit')) {
        fail('Μόνο όποιος ανέβασε το αρχείο μπορεί να το διαγράψει', 403);
    }
    Storage::delete($rec['id']);
    out(['ok' => true]);

case 'status_save':
    $sid = (int) ($in['id'] ?? 0);
    /* Η ΦΑΣΗ είναι το νόημα της στήλης (βλ. Db::PHASES)· η is_done βγαίνει από αυτήν. */
    $phase = (string) ($in['phase'] ?? '');
    if (!isset(Db::PHASES[$phase])) { $phase = !empty($in['done']) ? 'done' : 'wait'; }
    $data = ['title' => mb_substr(trim($in['title'] ?? ''), 0, 60) ?: 'Στήλη',
        'color' => preg_match('/^#[0-9a-fA-F]{6}$/', $in['color'] ?? '') ? $in['color'] : '#8291a9',
        'phase' => $phase, 'is_done' => in_array($phase, ['done', 'cancel'], true) ? 1 : 0];
    if ($sid) {
        Capsule::table('mod_cpm_statuses')->where('id', $sid)->update($data);
    } else {
        $data['sort'] = 1 + (int) Capsule::table('mod_cpm_statuses')->max('sort');
        $sid = Capsule::table('mod_cpm_statuses')->insertGetId($data);
    }
    out(['ok' => true, 'id' => $sid]);

case 'status_move':                      // σειρά στηλών: πάνω/κάτω — αυτή η σειρά είναι ο πίνακας kanban
    $mvId = (int) ($in['id'] ?? 0); $mvDir = ($in['dir'] ?? '') === 'up' ? -1 : 1;
    $mvAll = array_values(Db::statuses()->all());
    $mvI = null;
    foreach ($mvAll as $i => $r) { if ((int) $r->id === $mvId) { $mvI = $i; } }
    if ($mvI === null) { fail('Δεν βρέθηκε η στήλη'); }
    $mvJ = $mvI + $mvDir;
    if ($mvJ < 0 || $mvJ >= count($mvAll)) { out(['ok' => true]); }
    /* Οι τελικές μένουν στο τέλος: αλλαγή σειράς μόνο μέσα στην ίδια ομάδα (ανοιχτές / τελικές). */
    $grp = function ($r) { return in_array((string) $r->phase, ['done', 'cancel'], true) ? 1 : 0; };
    if ($grp($mvAll[$mvI]) !== $grp($mvAll[$mvJ])) { out(['ok' => true]); }
    [$mvAll[$mvI], $mvAll[$mvJ]] = [$mvAll[$mvJ], $mvAll[$mvI]];
    foreach ($mvAll as $i => $r) { Capsule::table('mod_cpm_statuses')->where('id', $r->id)->update(['sort' => $i + 1]); }
    out(['ok' => true]);

case 'status_del':
    $sid = (int) ($in['id'] ?? 0);
    if (Capsule::table('mod_cpm_tasks')->where('status_id', $sid)->exists()) {
        fail('Η στήλη έχει tasks — μετακίνησέ τα πρώτα');
    }
    if (Capsule::table('mod_cpm_statuses')->count() <= 2) {
        fail('Χρειάζονται τουλάχιστον 2 στήλες');
    }
    Capsule::table('mod_cpm_statuses')->where('id', $sid)->delete();
    out(['ok' => true]);

case 'type_save':
    $tid2 = (int) ($in['id'] ?? 0);
    $data = ['name' => mb_substr(trim($in['name'] ?? ''), 0, 60) ?: 'Τύπος',
        'icon' => preg_match('/^fa-[a-z0-9-]+$/', $in['icon'] ?? '') ? $in['icon'] : 'fa-tasks',
        'color' => preg_match('/^#[0-9a-fA-F]{6}$/', $in['color'] ?? '') ? $in['color'] : '#8595ac',
        'req_assignee' => !empty($in['reqA']) ? 1 : 0, 'req_due' => !empty($in['reqD']) ? 1 : 0,
        'req_estimate' => !empty($in['reqE']) ? 1 : 0];
    if ($tid2) {
        Capsule::table('mod_cpm_task_types')->where('id', $tid2)->update($data);
    } else {
        $data['sort'] = 1 + (int) Capsule::table('mod_cpm_task_types')->max('sort');
        $tid2 = Capsule::table('mod_cpm_task_types')->insertGetId($data);
    }
    out(['ok' => true, 'id' => $tid2]);

case 'type_del':
    $tid2 = (int) ($in['id'] ?? 0);
    Capsule::table('mod_cpm_tasks')->where('type_id', $tid2)->update(['type_id' => null]);
    Capsule::table('mod_cpm_task_types')->where('id', $tid2)->delete();
    out(['ok' => true]);

/* ================= CANNED RESPONSES ================= */
case 'canned':
    $rows = [];
    foreach (Capsule::table('mod_cpm_canned')->orderBy('sort')->orderBy('id')->get() as $cn) {
        $rows[] = ['id' => (int) $cn->id, 'title' => $cn->title, 'body' => $cn->body];
