    out(['canned' => $rows]);

case 'canned_save':
    $cid2 = (int) ($in['id'] ?? 0);
    $data = ['title' => mb_substr(trim($in['title'] ?? ''), 0, 80) ?: 'Απάντηση',
        'body' => mb_substr(trim($in['body'] ?? ''), 0, 20000)];
    if ($cid2) {
        Capsule::table('mod_cpm_canned')->where('id', $cid2)->update($data);
    } else {
        $cid2 = Capsule::table('mod_cpm_canned')->insertGetId($data + ['sort' => 0]);
