/* ================= GANTT / ΔΙΑΘΕΣΙΜΟΤΗΤΑ ΟΜΑΔΑΣ ================= */
case 'gantt':
    $from = preg_match('/^\d{4}-\d{2}-\d{2}$/', $_GET['from'] ?? '') ? $_GET['from'] : date('Y-m-d', strtotime('-7 days'));
    $to = preg_match('/^\d{4}-\d{2}-\d{2}$/', $_GET['to'] ?? '') ? $_GET['to'] : date('Y-m-d', strtotime('+35 days'));
    $doneIds = Capsule::table('mod_cpm_statuses')->where('is_done', 1)->pluck('id')->all() ?: [0];
    $rows = Capsule::table('mod_cpm_tasks as t')
        ->leftJoin('mod_cpm_projects as p', 'p.id', '=', 't.project_id')
        ->select('t.*', 'p.name as pname', 'p.color as pcolor')
        ->whereNotIn('t.status_id', $doneIds)
        ->where(function ($w) {
            $w->whereNotNull('t.start_date')->orWhereNotNull('t.due_date')->orWhereNotNull('t.schedule_date');
        })->get();
    $tasks = [];
    $load = [];      // ανά χειριστή ανά ημέρα (λεπτά)
    $projIds = [];
    foreach ($rows as $t) {
        if (!$FULL && (int) $t->assignee !== $adminId && !Db::canSeeProject($adminId, $t->project_id)) {
            continue;
        }
        $start = $t->start_date ?: ($t->schedule_date ?: $t->due_date);
        $end = $t->due_date ?: $start;
        if ($end < $start) {
            $end = $start;
        }
        if ($end < $from || $start > $to) {
            continue;
        }
        $est = (int) $t->estimate_minutes;
        $days = [];
        for ($d = $start; $d <= $end; $d = date('Y-m-d', strtotime($d . ' +1 day'))) {
            if ((int) date('N', strtotime($d)) <= 5) {
                $days[] = $d;
            }
        }
        $perDay = $est > 0 && count($days) ? $est / count($days) : ($est === 0 ? 60 : 0);
        $aKey = (int) $t->assignee;
        foreach ($days as $d) {
            if ($d >= $from && $d <= $to && $aKey) {
                $load[$aKey][$d] = ($load[$aKey][$d] ?? 0) + $perDay;
            }
        }
        $projIds[(int) $t->project_id] = 1;
        $tasks[] = ['id' => (int) $t->id, 'title' => $t->title, 'project' => (int) $t->project_id, '_bid' => (int) $t->id,
            'assignee' => $aKey ?: null, 'start' => $start, 'end' => $end,
            'color' => $t->pcolor ?: '#8595ac', 'pname' => cnp_pn($t->pname), 'prio' => (int) $t->priority,
            'est' => $est ?: null, 'ticket' => $t->ticketid ? (int) $t->ticketid : null];
    }
    // projects δέντρο (όσα έχουν tasks + οι γονείς τους)
    $projects = [];
    $all = $FULL ? Db::projects(true) : Db::projectsFor($adminId, true);
    $byId = [];
    foreach ($all as $p) {
        $byId[(int) $p->id] = $p;
    }
    foreach (array_keys($projIds) as $pidG) {
        if (isset($byId[$pidG]) && $byId[$pidG]->parent_id) {
            $projIds[(int) $byId[$pidG]->parent_id] = 1; // φέρε και τον γονιό
        }
    }
    foreach ($all as $p) {
        if (!isset($projIds[(int) $p->id])) {
            continue;
        }
        $projects[] = ['id' => (int) $p->id, 'name' => $p->name, 'color' => $p->color,
            'parent' => $p->parent_id ? (int) $p->parent_id : null,
            'client' => clientLabel($p->clientid)];
    }
    $gBlocked = Db::blockedMap(array_column($tasks, '_bid'));
    foreach ($tasks as &$gt) {
        $gt['blocked'] = isset($gBlocked[$gt['_bid']]) ? count($gBlocked[$gt['_bid']]) : 0;
        unset($gt['_bid']);
    }
    unset($gt);
    // 🌴 άδειες: ανά admin ποιες μέρες λείπει (για τη ζώνη διαθεσιμότητας)
    $leaves = [];
    try {
        foreach (Capsule::table('mod_cpm_events')->where('kind', 'leave')
            ->where('start_dt', '<=', $to . ' 23:59:59')->where('end_dt', '>=', $from . ' 00:00:00')->get() as $lv) {
            foreach (array_filter(array_map('intval', explode(',', $lv->attendees))) as $a) {
                $d0 = max(strtotime(substr($lv->start_dt, 0, 10)), strtotime($from));
                $d1 = min(strtotime(substr($lv->end_dt, 0, 10)), strtotime($to));
                for ($d = $d0; $d <= $d1; $d += 86400) {
                    $leaves[$a][date('Y-m-d', $d)] = true;
                }
            }
        }
    } catch (\Throwable $e) {
    }
    out(['from' => $from, 'to' => $to, 'projects' => $projects, 'tasks' => $tasks, 'load' => $load, 'leaves' => $leaves]);

case 'scheduler':                        // Πρόγραμμα ανά άνθρωπο — λωρίδες στον χρόνο
    $fromS = preg_match('/^\d{4}-\d{2}-\d{2}$/', $_GET['from'] ?? '') ? $_GET['from'] : date('Y-m-d', strtotime('monday this week'));
    $daysS = min(120, max(3, (int) ($_GET['days'] ?? 21)));
    $toS = date('Y-m-d', strtotime($fromS . ' +' . ($daysS - 1) . ' days'));
    $teamS = (int) ($_GET['team'] ?? 0);
    $doneS = Capsule::table('mod_cpm_statuses')->where('is_done', 1)->pluck('id')->all() ?: [0];

    /* Ποιοι μπαίνουν στις λωρίδες: μια ομάδα, ή όλοι. Οι λωρίδες είναι ΑΝΘΡΩΠΟΙ
       — αυτό είναι όλο το νόημα: βλέπεις το πιάτο του καθενός δίπλα-δίπλα. */
    $people = [];
    if ($teamS) {
        foreach (Capsule::table('mod_cpm_team_members')->where('team_id', $teamS)->pluck('admin_id') as $a) {
            $people[(int) $a] = true;
        }
    } else {
        foreach (Db::admins() as $a) {
            if (!cnp_is_bot(Db::adminName($a->id), $a->username ?? '')) { $people[(int) $a->id] = true; }
        }
    }
    $ids = array_keys($people);
    if (!$ids) { $ids = [0]; }

    $rowsS = Capsule::table('mod_cpm_tasks as t')
        ->leftJoin('mod_cpm_projects as p', 'p.id', '=', 't.project_id')
        ->leftJoin('mod_cpm_statuses as st', 'st.id', '=', 't.status_id')
        /* Η εργασία μπαίνει στη λωρίδα ΟΠΟΙΟΥ ΤΗ ΔΟΥΛΕΥΕΙ ΤΩΡΑ: τη μπάλα (action_user) — κι αν είναι
           κενή, τον ανάδοχο (21/9/2026). Έτσι ο ανάδοχος που παρέδωσε τη σκυτάλη δεν φαίνεται
           φορτωμένος, και αυτός που την πήρε τη βλέπει στο πιάτο του. */
        ->where(function ($w) use ($ids) { $w->whereIn('t.action_user', $ids)->orWhere(function ($x) use ($ids) { $x->whereIn('t.assignee', $ids)->where(function ($y) { $y->whereNull('t.action_user')->orWhere('t.action_user', 0); }); }); })
        ->whereNotIn('t.status_id', $doneS)
        ->whereNotNull('t.start_date')->whereNotNull('t.due_date')
        ->where('t.start_date', '<=', $toS)->where('t.due_date', '>=', $fromS)
        ->orderBy('t.start_date')
        ->get(['t.id', 't.title', 't.assignee', 't.action_user', 't.start_date', 't.start_time', 't.due_date', 't.due_time',
            't.schedule_date', 't.priority', 't.estimate_minutes',
            'p.name as pname', 'p.color as pcolor', 'st.title as sname']);

    /* ▶ Ποιες εργασίες έχουν χρονόμετρο που τρέχει ΤΩΡΑ (από τον ανάδοχό τους): φαίνονται «ζωντανές» στο πρόγραμμα. */
    $runS = [];
    foreach (Capsule::table('mod_cpm_timelogs')->where('running', 1)->get(['task_id', 'admin_id']) as $rl) { $runS[(int) $rl->task_id] = (int) $rl->admin_id; }
    $byPerson = [];
    foreach ($rowsS as $t) {
        $whoS = (int) $t->action_user ?: (int) $t->assignee;
        if (!isset($people[$whoS])) { continue; }
        $byPerson[$whoS][] = [
            'assignee' => (int) $t->assignee, 'ball' => (int) $t->action_user ?: 0,
            /* Ποιος τρέχει χρονόμετρο ΤΩΡΑ στην εργασία — μπορεί να μην είναι ο ανάδοχος (π.χ. πήρε τη μπάλα). */
            'runBy' => isset($runS[(int) $t->id]) ? $runS[(int) $t->id] : 0,
            'runByName' => isset($runS[(int) $t->id]) ? Db::adminName($runS[(int) $t->id]) : '',
            'id' => (int) $t->id, 'title' => $t->title,
            'start' => $t->start_date, 'end' => $t->due_date,
            'startT' => $t->start_time ? substr($t->start_time, 0, 5) : null,
            'endT' => $t->due_time ? substr($t->due_time, 0, 5) : null,
            'deadline' => $t->schedule_date,
            'late' => $t->schedule_date && $t->schedule_date < date('Y-m-d'),
            'prio' => (int) $t->priority, 'est' => (int) $t->estimate_minutes,
            'project' => $t->pname ? cnp_pn($t->pname) : '', 'color' => $t->pcolor ?: '#0090dd',
            'status' => $t->sname ?: ''];
    }

    $lanes = [];
    foreach ($ids as $aid) {
        if (!$aid) { continue; }
        $prA = cnp_presence($aid);
        $lanes[] = ['id' => $aid, 'name' => Db::adminName($aid), 'ini' => initials(Db::adminName($aid)),
            'presence' => $prA['status'], 'presenceLbl' => $prA['label'], 'presenceCol' => $prA['color'],
            'tasks' => $byPerson[$aid] ?? []];
    }
    /* Πρώτα όποιος έχει δουλειά — οι άδειες λωρίδες κάτω, για να μη σπρώχνουν. */
    usort($lanes, function ($a, $b) { return count($b['tasks']) <=> count($a['tasks']); });

    /* Εργασίες ΧΩΡΙΣ διάστημα: δεν μπαίνουν σε λωρίδα γιατί δεν ξέρουμε πού —
       αλλά πρέπει να φαίνονται, αλλιώς «χάνονται» από το πρόγραμμα. */
    $unsched = [];
    foreach (Capsule::table('mod_cpm_tasks as t')->leftJoin('mod_cpm_projects as p', 'p.id', '=', 't.project_id')
        ->where(function ($w) use ($ids) { cnp_scope_team($w, $ids, 't.'); })
        ->whereNotIn('t.status_id', $doneS)
        ->where(function ($w) { $w->whereNull('t.start_date')->orWhereNull('t.due_date'); })
        ->orderBy('t.id', 'desc')->limit(60)
        ->get(['t.id', 't.title', 't.assignee', 't.priority', 'p.name as pname', 'p.color as pcolor']) as $t) {
        $unsched[] = ['id' => (int) $t->id, 'title' => $t->title, 'who' => (int) $t->assignee,
            'whoName' => Db::adminName((int) $t->assignee),
            'prio' => (int) $t->priority,
            'project' => $t->pname ? cnp_pn($t->pname) : '', 'color' => $t->pcolor ?: '#8595ac'];
    }

    $teams = [];
    foreach (Capsule::table('mod_cpm_teams')->orderBy('sort')->orderBy('id')->get(['id', 'name', 'color']) as $tm) {
        $teams[] = ['id' => (int) $tm->id, 'name' => $tm->name, 'color' => $tm->color];
    }
    out(['from' => $fromS, 'to' => $toS, 'days' => $daysS, 'team' => $teamS,
        'lanes' => $lanes, 'unscheduled' => $unsched, 'teams' => $teams]);

case 'gantt_move':
    $t6 = Db::task((int) ($in['task'] ?? 0));
    if (!$t6 || !Db::canSeeTask($adminId, $t6)) {
        fail('task', 403);
    }
    $st6 = preg_match('/^\d{4}-\d{2}-\d{2}$/', $in['start'] ?? '') ? $in['start'] : null;
    $en6 = preg_match('/^\d{4}-\d{2}-\d{2}$/', $in['end'] ?? '') ? $in['end'] : null;
    if (!$st6 || !$en6 || $en6 < $st6) {
        fail('dates');
    }
    Db::saveTask($t6->id, ['start_date' => $st6, 'due_date' => $en6], $adminId);
    Db::logActivity($t6->id, $adminId, 'edit', 'Gantt: ' . $st6 . ' → ' . $en6);
    out(['ok' => true]);

/* ================= ΕΞΑΡΤΗΣΕΙΣ + ΑΡΧΕΙΑ ================= */
case 'dep_add':
    $t7 = Db::task((int) ($in['task'] ?? 0));
    if (!$t7 || !Db::canSeeTask($adminId, $t7)) {
        fail('task', 403);
    }
    $ok7 = Db::addDep($t7->id, (int) ($in['on'] ?? 0));
    out(['ok' => (bool) $ok7]);

case 'dep_del':
    Db::delDep((int) ($in['id'] ?? 0));
    out(['ok' => true]);

/* Τα task attachments ενοποιήθηκαν στο γενικό Storage layer (file_* endpoints, module=task).
   Τα παλιά cases files/file_upload/file_get/file_del (mod_cpm_files, local) αφαιρέθηκαν. */

/* ---- realtime version (ελαφρύ polling — Κ6) ---- */
/* ============ 🎥 CLOUDON MEET (WebRTC signaling) ============ */
case 'rtc_join':
    $room = preg_replace('/[^a-zA-Z0-9\-]/', '', $in['room'] ?? '');
    if ($room === '' || ($adminId <= 0 && $MEET_ROOM !== $room)) {
        fail('room', 403);
    }
    $winJ = pm_meet_window($room);
    if ($winJ && $winJ['ended']) {
        out(['error' => 'Το meeting «' . $winJ['title'] . '» ολοκληρώθηκε στις ' . date('H:i', $winJ['endTs']) . ' — για συνέχεια χρειάζεται νέο meeting', 'ended' => true]);
    }
    $peer = substr(bin2hex(random_bytes(8)), 0, 12);
    $name = $adminId > 0 ? Db::adminName($adminId) : (mb_substr(trim($in['name'] ?? ''), 0, 60) ?: 'Επισκέπτης');
    // καθάρισμα: πεθαμένοι peers + παλιά μηνύματα
    /* 120s (ήταν 40s): laptop σε sleep ή αλλαγή δικτύου ΔΕΝ σβήνει τον συμμετέχοντα — και
       το rtc_poll τον ξαναγράφει αν λείπει (18/9/2026). */
    Capsule::table('mod_cpm_rtc_peers')->where('last_seen', '<', date('Y-m-d H:i:s', time() - 120))->delete();
    Capsule::table('mod_cpm_rtc_msgs')->where('created_at', '<', date('Y-m-d H:i:s', time() - 600))->delete();
    Capsule::table('mod_cpm_rtc_peers')->insert(['room' => $room, 'peer' => $peer, 'name' => $name,
        'admin_id' => $adminId > 0 ? $adminId : null, 'last_seen' => date('Y-m-d H:i:s')]);
    $roster = [];
    foreach (Capsule::table('mod_cpm_rtc_peers')->where('room', $room)->where('peer', '!=', $peer)->get() as $p9) {
        $roster[] = ['peer' => $p9->peer, 'name' => $p9->name];
    }
    out(['peer' => $peer, 'name' => $name, 'roster' => $roster]);

case 'rtc_signal':
    $room = preg_replace('/[^a-zA-Z0-9\-]/', '', $in['room'] ?? '');
    if ($room === '' || ($adminId <= 0 && $MEET_ROOM !== $room)) {
        fail('room', 403);
    }
    $kind = in_array($in['kind'] ?? '', ['offer', 'answer', 'ice', 'bye'], true) ? $in['kind'] : null;
    if (!$kind || empty($in['peer']) || empty($in['to'])) {
        fail('input');
    }
    Capsule::table('mod_cpm_rtc_msgs')->insert(['room' => $room,
        'to_peer' => preg_replace('/[^a-f0-9]/', '', $in['to']),
        'from_peer' => preg_replace('/[^a-f0-9]/', '', $in['peer']),
        'kind' => $kind, 'payload' => mb_substr((string) ($in['payload'] ?? ''), 0, 200000),
        'created_at' => date('Y-m-d H:i:s')]);
    out(['ok' => true]);

case 'rtc_poll':
    $room = preg_replace('/[^a-zA-Z0-9\-]/', '', $_GET['room'] ?? '');
    if ($room === '' || ($adminId <= 0 && $MEET_ROOM !== $room)) {
        fail('room', 403);
    }
    $peer = preg_replace('/[^a-f0-9]/', '', $_GET['peer'] ?? '');
    if ($peer === '') { fail('input'); }
    /* Upsert, όχι update: αν η γραμμή μου σβήστηκε (καθάρισμα «νεκρών» από άλλο join ενώ
       είχα πρόβλημα δικτύου), ξαναμπαίνω στη λίστα μόλις ξαναμιλήσω — αλλιώς έμενα αόρατος
       για πάντα ενώ η οθόνη μου έδειχνε «συνδεδεμένος» (18/9/2026). */
    $nameP = $adminId > 0 ? Db::adminName($adminId) : (mb_substr(trim((string) ($_GET['name'] ?? '')), 0, 60) ?: 'Επισκέπτης');
    $upd = Capsule::table('mod_cpm_rtc_peers')->where('room', $room)->where('peer', $peer)->update(['last_seen' => date('Y-m-d H:i:s')]);
    $restored = false;
    if (!$upd && !Capsule::table('mod_cpm_rtc_peers')->where('room', $room)->where('peer', $peer)->exists()) {
        Capsule::table('mod_cpm_rtc_peers')->insert(['room' => $room, 'peer' => $peer, 'name' => $nameP,
            'admin_id' => $adminId > 0 ? $adminId : null, 'last_seen' => date('Y-m-d H:i:s')]);
        $restored = true;
    }
    $after = (int) ($_GET['after'] ?? 0);
    $msgs = [];
    foreach (Capsule::table('mod_cpm_rtc_msgs')->where('room', $room)->where('to_peer', $peer)
        ->where('id', '>', $after)->orderBy('id')->limit(100)->get() as $m9) {
        $msgs[] = ['id' => (int) $m9->id, 'from' => $m9->from_peer, 'kind' => $m9->kind, 'payload' => $m9->payload];
    }
    $roster = [];
    /* 75s (ήταν 30s): tab στο παρασκήνιο >5΄ ή κλειδωμένο κινητό ρίχνει τα polls σε 1/λεπτό —
       δεν σημαίνει ότι έφυγε. Το «bye» είναι η ρητή αποχώρηση. */
    foreach (Capsule::table('mod_cpm_rtc_peers')->where('room', $room)
        ->where('last_seen', '>', date('Y-m-d H:i:s', time() - 75))->get() as $p9) {
        $roster[] = ['peer' => $p9->peer, 'name' => $p9->name];
    }
    /* Ώρα λήξης (μπορεί να άλλαξε με παράταση) και, στα τελευταία 6΄, αν χωράει +15΄. */
    $winP = pm_meet_window($room);
    $extP = null;
    if ($winP && $adminId > 0 && $winP['endTs'] - time() <= 360) { $extP = pm_meet_extend_check($winP, 15); }
    out(['messages' => $msgs, 'roster' => $roster, 'restored' => $restored, 'now' => time(),
        'end' => $winP ? $winP['endTs'] * 1000 : 0, 'extendOk' => $extP ? $extP['ok'] : null, 'extendWhy' => $extP ? $extP['why'] : '']);

case 'rtc_leave':
    $room = preg_replace('/[^a-zA-Z0-9\-]/', '', $in['room'] ?? '');
    $peer = preg_replace('/[^a-f0-9]/', '', $in['peer'] ?? '');
    Capsule::table('mod_cpm_rtc_peers')->where('room', $room)->where('peer', $peer)->delete();
    out(['ok' => true]);

case 'meet_extend':                     // παράταση meeting από μέσα από την κλήση — ΜΟΝΟ αν χωράει
    $roomX = preg_replace('/[^a-zA-Z0-9\-]/', '', $in['room'] ?? '');
    $winX = pm_meet_window($roomX);
    if (!$winX) { fail('Το δωμάτιο δεν ανήκει σε meeting του ημερολογίου'); }
    if ($winX['ended']) { out(['error' => 'Το meeting έχει ήδη ολοκληρωθεί — χρειάζεται νέο', 'ended' => true]); }
    $evX = Capsule::table('mod_cpm_events')->where('id', $winX['id'])->first();
    $attX = array_filter(array_map('intval', explode(',', (string) $evX->attendees)));
    if (!$FULL && (int) $evX->created_by !== $adminId && !in_array($adminId, $attX, true)) { fail('Μόνο συμμετέχων ή ο διοργανωτής παρατείνει', 403); }
    $minsX = in_array((int) ($in['mins'] ?? 15), [10, 15, 30], true) ? (int) $in['mins'] : 15;
    $chk = pm_meet_extend_check($winX, $minsX);
    if (!$chk['ok']) { fail($chk['why']); }
    Capsule::table('mod_cpm_events')->where('id', $winX['id'])->update(['end_dt' => date('Y-m-d H:i:s', $chk['newEnd'])]);
    foreach ($attX as $aX) {
        if ($aX === $adminId) { continue; }
        Db::pushNotification($aX, 'info', '⏰ ' . Db::adminName($adminId) . ' παρέτεινε το meeting «' . $evX->title . '» έως ' . date('H:i', $chk['newEnd']), '/projectmanagement/#/calendar');
    }
    out(['ok' => true, 'end' => $chk['newEnd'] * 1000, 'endTxt' => date('H:i', $chk['newEnd'])]);

case 'rtc_invite':                      // πρόσκληση ΚΑΤΑ ΤΗ ΔΙΑΡΚΕΙΑ του meeting (μόνο ομάδα)
    if ($adminId <= 0) {
        fail('perm', 403);
    }
    $room = preg_replace('/[^a-zA-Z0-9\-]/', '', $in['room'] ?? '');
    if ($room === '') {
        fail('room');
    }
    $url9 = 'https://my.cloudon.gr/projectmanagement/meet.php?room=' . $room . '&t=' . pm_mint_meet($room);
    $byName = Db::adminName($adminId);
    $body9 = '<p><strong>' . htmlspecialchars($byName) . '</strong> σας προσκαλεί σε meeting <strong>που είναι σε εξέλιξη τώρα</strong>.</p>'
        . '<p style="background:#eef7fd;border-left:4px solid #0090dd;padding:10px 14px;">'
        . '🎥 <a href="' . htmlspecialchars($url9) . '"><strong>Συμμετοχή στο meeting</strong></a></p>'
        . '<p>Ανοίγει απευθείας στον browser — χωρίς εγκατάσταση ή λογαριασμό.</p>';
    if (!empty($in['admin'])) {
        $to9 = (int) $in['admin'];
        Db::pushNotification($to9, 'action', '🎥 ' . $byName . ' σε καλεί ΤΩΡΑ σε meeting!', $url9);
        \WHMCS\Module\Addon\CloudonProjects\Notify::send($to9, '🎥 Σε καλούν σε meeting ΤΩΡΑ', $body9);
        out(['ok' => true, 'sent' => Db::adminName($to9)]);
    }
    if (!empty($in['email']) && filter_var($in['email'], FILTER_VALIDATE_EMAIL)) {
        \WHMCS\Module\Addon\CloudonProjects\Notify::sendTo(trim($in['email']), '🎥 Πρόσκληση σε meeting σε εξέλιξη — CloudOn', $body9);
        out(['ok' => true, 'sent' => trim($in['email'])]);
    }
    out(['ok' => true, 'url' => $url9]);

case 'meet_room':                       // δημιουργία δωματίου + guest URL
    $room = 'm' . substr(bin2hex(random_bytes(6)), 0, 10);
    $base = 'https://my.cloudon.gr/projectmanagement/meet.php';
    out(['room' => $room,
        'url' => $base . '?room=' . $room . '&t=' . pm_mint_meet($room)]);

/* ============ ✔ RSVP MEETINGS ============ */
case 'event_rsvp':                      // απάντηση μέλους ομάδας
    $ev = Capsule::table('mod_cpm_events')->where('id', (int) ($in['id'] ?? 0))->first();
    if (!$ev) {
        fail('event', 404);
    }
    $att9 = array_filter(array_map('intval', explode(',', $ev->attendees)));
    if (!in_array($adminId, $att9, true)) {
        fail('Δεν είσαι στους συμμετέχοντες', 403);
    }
    $st9 = ($in['status'] ?? '') === 'declined' ? 'declined' : 'accepted';
    Capsule::table('mod_cpm_event_rsvp')->updateOrInsert(
        ['event_id' => $ev->id, 'kind' => 'admin', 'ref' => $adminId],
        ['status' => $st9, 'responded_at' => date('Y-m-d H:i:s')]);
    if ((int) $ev->created_by !== $adminId) {
        Db::pushNotification($ev->created_by, 'info',
            ($st9 === 'accepted' ? '✅ ' : '❌ ') . Db::adminName($adminId)
            . ($st9 === 'accepted' ? ' αποδέχθηκε' : ' δεν μπορεί') . ': ' . $ev->title,
            '/projectmanagement/#/calendar');
    }
    out(['ok' => true, 'status' => $st9]);

case 'event_rsvp_public':               // απάντηση πελάτη από το email (χωρίς login)
    $v9 = pm_verify_rsvp($_GET['t'] ?? '');
    if (!$v9) {
        header('Content-Type: text/html; charset=utf-8');
        echo '<meta name="viewport" content="width=device-width,initial-scale=1"><body style="font-family:sans-serif;text-align:center;padding:60px 20px"><h2>⏰ Ο σύνδεσμος έληξε</h2><p>Επικοινωνήστε μαζί μας για νέο.</p></body>';
        exit;
    }
    [$evId9, $cid9] = $v9;
    $ev = Capsule::table('mod_cpm_events')->where('id', $evId9)->first();
    $st9 = ($_GET['r'] ?? '') === 'decline' ? 'declined' : 'accepted';
    if ($ev && (int) $ev->clientid === $cid9) {
        Capsule::table('mod_cpm_event_rsvp')->updateOrInsert(
            ['event_id' => $evId9, 'kind' => 'client', 'ref' => $cid9],
            ['status' => $st9, 'responded_at' => date('Y-m-d H:i:s')]);
        Db::pushNotification($ev->created_by, 'info',
            ($st9 === 'accepted' ? '✅ Ο πελάτης αποδέχθηκε' : '❌ Ο πελάτης ΔΕΝ μπορεί') . ': ' . $ev->title,
            '/projectmanagement/#/calendar');
        if (function_exists('logActivity')) {
            logActivity('CPM: RSVP πελάτη #' . $cid9 . ' → ' . $st9 . ' (event #' . $evId9 . ')');
        }
    }
    header('Content-Type: text/html; charset=utf-8');
    echo '<meta name="viewport" content="width=device-width,initial-scale=1"><body style="font-family:sans-serif;text-align:center;padding:60px 20px;background:#f4f6fa">'
        . '<div style="max-width:440px;margin:0 auto;background:#fff;border-radius:16px;padding:36px 28px;box-shadow:0 8px 30px rgba(16,42,67,.12)">'
        . ($st9 === 'accepted'
            ? '<div style="font-size:52px">✅</div><h2 style="color:#152238">Ευχαριστούμε!</h2><p style="color:#44566c">Η συμμετοχή σας επιβεβαιώθηκε' . ($ev ? ' για <b>' . htmlspecialchars($ev->title) . '</b><br>🗓 ' . date('d/m/Y H:i', strtotime($ev->start_dt)) : '') . '.</p>'
            : '<div style="font-size:52px">📅</div><h2 style="color:#152238">Καταγράφηκε</h2><p style="color:#44566c">Λάβαμε ότι δεν σας εξυπηρετεί η ώρα — θα επικοινωνήσουμε για εναλλακτική.</p>')
        . '<p style="color:#8291a9;font-size:13px">CloudOn — Innovative e-business solutions</p></div></body>';
    exit;

/* ============ 💬 ΕΣΩΤΕΡΙΚΟ CHAT ============ */
case 'chat_group_get':                  // ποιοι είναι μέσα — και μπορώ να το αλλάξω;
    $gg = Capsule::table('mod_cpm_chat_groups')->where('id', (int) ($_GET['id'] ?? 0))->first();
    if (!$gg) { fail('group', 404); }
    $ggMem = array_values(array_filter(array_map('intval', explode(',', (string) $gg->members))));
    /* Μόνο μέλος βλέπει τα μέλη. Μια ομάδα συνομιλίας δεν είναι δημόσια λίστα. */
    if (!$FULL && !in_array($adminId, $ggMem, true)) { fail('group', 403); }
    $ggPeople = [];
    foreach (Db::admins() as $a6) {
        $ggPeople[] = ['id' => (int) $a6->id, 'name' => Db::adminName((int) $a6->id)];
    }
    out(['ok' => true, 'id' => (int) $gg->id, 'name' => (string) $gg->name,
        'members' => array_map(function ($mId) {
            return ['id' => $mId, 'name' => Db::adminName($mId)];
        }, $ggMem),
        'createdBy' => (int) $gg->created_by,
        'createdByName' => Db::adminName((int) $gg->created_by),
        'createdAt' => $gg->created_at,
        /* Αλλάζει όποιος την έφτιαξε ή διαχειριστής. Αν μπορούσε ο καθένας, θα
           μπορούσες να βγάλεις έξω αυτόν που σε έβαλε μέσα. */
        'canEdit' => ($FULL || (int) $gg->created_by === $adminId),
        'people' => $ggPeople]);

case 'chat_group_save':                 // δημιουργία ΚΑΙ αλλαγή ομάδας συνομιλίας
    $gname = mb_substr(trim($in['name'] ?? ''), 0, 80);
    $gId0 = (int) ($in['id'] ?? 0);
    $gmem = array_values(array_unique(array_merge([$adminId],
        array_filter(array_map('intval', (array) ($in['members'] ?? []))))));
    if ($gname === '' || count($gmem) < 2) {
        fail('Όνομα και τουλάχιστον ένα ακόμη μέλος');
    }
    if ($gId0) {
        /* ΑΛΛΑΓΗ ΥΠΑΡΧΟΥΣΑΣ. */
        $gOld = Capsule::table('mod_cpm_chat_groups')->where('id', $gId0)->first();
        if (!$gOld) { fail('group', 404); }
        if (!$FULL && (int) $gOld->created_by !== $adminId) {
            fail('Την ομάδα την αλλάζει όποιος τη δημιούργησε', 403);
        }
        /* Ο δημιουργός μένει ΠΑΝΤΑ μέσα: αλλιώς η ομάδα θα έμενε χωρίς κανέναν
           που μπορεί να την αλλάξει. Ο `$adminId` μπαίνει ήδη παραπάνω, αλλά ο
           διαχειριστής μπορεί να επεξεργάζεται ξένη ομάδα. */
        $gmem = array_values(array_unique(array_merge([(int) $gOld->created_by], $gmem)));
        $gPrev = array_values(array_filter(array_map('intval', explode(',', (string) $gOld->members))));
        Capsule::table('mod_cpm_chat_groups')->where('id', $gId0)
            ->update(['name' => $gname, 'members' => ',' . implode(',', $gmem) . ',']);
        /* Ειδοποιούμε ΜΟΝΟ όποιον όντως μπήκε τώρα — όχι όλη την ομάδα σε κάθε
           μετονομασία. */
        foreach (array_diff($gmem, $gPrev) as $gm) {
            if ($gm !== $adminId) {
                Db::pushNotification($gm, 'info', 'Προστέθηκες στην ομάδα «' . $gname . '»', '/project/#/chat');
            }
        }
        out(['ok' => true, 'id' => $gId0,
            'added' => count(array_diff($gmem, $gPrev)),
            'removed' => count(array_diff($gPrev, $gmem))]);
    }
    $gid = Capsule::table('mod_cpm_chat_groups')->insertGetId(['name' => $gname,
        'members' => ',' . implode(',', $gmem) . ',',
        'created_by' => $adminId, 'created_at' => date('Y-m-d H:i:s')]);
    foreach ($gmem as $gm) {
        if ($gm !== $adminId) {
            Db::pushNotification($gm, 'info', 'Προστέθηκες στην ομάδα «' . $gname . '»', '/project/#/chat');
        }
    }
    out(['ok' => true, 'id' => $gid]);

case 'chat_group_del':                  // διαγραφή/αποχώρηση
    $gr = Capsule::table('mod_cpm_chat_groups')->where('id', (int) ($in['id'] ?? 0))->first();
    if (!$gr) {
        fail('group', 404);
    }
    if ($FULL || (int) $gr->created_by === $adminId) {
        Capsule::table('mod_cpm_chat_groups')->where('id', $gr->id)->delete();
        Capsule::table('mod_cpm_chat')->where('channel', 'g' . $gr->id)->delete();
        out(['ok' => true, 'deleted' => true]);
    }
    // απλό μέλος: αποχωρεί
    $mem = array_values(array_diff(array_filter(array_map('intval', explode(',', $gr->members))), [$adminId]));
    Capsule::table('mod_cpm_chat_groups')->where('id', $gr->id)
        ->update(['members' => ',' . implode(',', $mem) . ',']);
    out(['ok' => true, 'left' => true]);

case 'chat_channels':
    Db::setPref($adminId, 'last_seen', (string) time());
    $now6 = time();
    $reads = [];
    foreach (Capsule::table('mod_cpm_chat_reads')->where('admin_id', $adminId)->get() as $r6) {
        $reads[$r6->channel] = (int) $r6->last_id;
    }
    $chans = [['id' => 'team', 'name' => '# Ομάδα', 'kind' => 'team',
        'unread' => Capsule::table('mod_cpm_chat')->where('channel', 'team')
            ->where('id', '>', $reads['team'] ?? 0)->where('admin_id', '!=', $adminId)->count()]];
    foreach (Capsule::table('mod_cpm_chat_groups')
        ->where('members', 'like', '%,' . $adminId . ',%')->orderBy('name')->get() as $g6) {
        $ch = 'g' . $g6->id;
        $chans[] = ['id' => $ch, 'name' => $g6->name, 'kind' => 'group',
            'groupId' => (int) $g6->id, 'mine' => (int) $g6->created_by === $adminId,
            'members' => count(array_filter(explode(',', $g6->members))),
            'unread' => Capsule::table('mod_cpm_chat')->where('channel', $ch)
                ->where('id', '>', $reads[$ch] ?? 0)->where('admin_id', '!=', $adminId)->count()];
    }
    foreach (Db::admins() as $a6) {
        if ((int) $a6->id === $adminId) {
            continue;
        }
        $ch = 'd' . min($adminId, (int) $a6->id) . '-' . max($adminId, (int) $a6->id);
        $pr6 = cnp_presence((int) $a6->id, $now6);
        $chans[] = ['id' => $ch, 'name' => trim($a6->firstname . ' ' . $a6->lastname),
            'kind' => 'dm', 'admin' => (int) $a6->id, 'status' => $pr6['status'],
            'label' => $pr6['label'], 'manual' => $pr6['manual'], 'mute' => $pr6['mute'],
            'untilTxt' => $pr6['untilTxt'], 'hint' => $pr6['hint'], 'reason' => $pr6['reason'],
            'unread' => Capsule::table('mod_cpm_chat')->where('channel', $ch)
                ->where('id', '>', $reads[$ch] ?? 0)->where('admin_id', '!=', $adminId)->count()];
    }
    out(['channels' => $chans, 'me' => cnp_presence($adminId, $now6),
        'myStatus' => Db::pref($adminId, 'chat_status', 'online'),
        'myReason' => Db::pref($adminId, 'chat_reason', '')]);

case 'chat_msgs':
    $ch = preg_replace('/[^a-z0-9\-]/', '', $_GET['channel'] ?? 'team');
    if (!cnp_chat_access($ch, $adminId)) {
        fail('channel', 403);
    }
    Db::setPref($adminId, 'last_seen', (string) time());
    $after = (int) ($_GET['after'] ?? 0);
    $q6 = Capsule::table('mod_cpm_chat')->where('channel', $ch);
    $msgs = $after > 0
        ? $q6->where('id', '>', $after)->orderBy('id')->limit(200)->get()
        : $q6->orderBy('id', 'desc')->limit(60)->get()->reverse()->values();
    $outM = [];
    $maxId = $after;
    /* Αντιδράσεις: ανά μήνυμα, {code: [ονόματα]} + τα δικά μου. Για τα μηνύματα που φέρνουμε, συν όσα
       άλλαξαν αντίδραση τα τελευταία 15΄ (react_at) ώστε να ενημερώνονται όσοι τα έχουν ήδη στην οθόνη. */
    $reactFor = function (array $ids) use ($adminId) {
        $out = [];
        if (!$ids) { return $out; }
        foreach (Capsule::table('mod_cpm_chat_react')->whereIn('msg_id', $ids)->orderBy('id')->get() as $r) {
            $out[(int) $r->msg_id][$r->code][] = ['id' => (int) $r->admin_id, 'name' => Db::adminName((int) $r->admin_id), 'me' => (int) $r->admin_id === $adminId];
        }
        return $out;
    };
    $idsM = array_map(function ($m) { return (int) $m->id; }, is_array($msgs) ? $msgs : $msgs->all());
    $reactsM = $reactFor($idsM);
    $quoteOf = function ($rid) {
        if (!$rid) { return null; }
        $q = Capsule::table('mod_cpm_chat')->where('id', (int) $rid)->first();
        if (!$q) { return null; }
        $txt = !empty($q->deleted_at) ? '🚫 διαγράφηκε' : ($q->body ? mb_substr(preg_replace('/(\?\?\?\?\s?)+/', '', trim((string) $q->body)), 0, 120) : ($q->mime && strpos((string) $q->mime, 'audio/') === 0 ? '🎙 φωνητικό' : '📎 ' . (string) $q->filename));
        return ['id' => (int) $q->id, 'by' => (int) $q->admin_id, 'name' => Db::adminName((int) $q->admin_id), 'text' => $txt];
    };
    foreach ($msgs as $m9) {
        $maxId = max($maxId, (int) $m9->id);
        if (!empty($m9->deleted_at)) {
            $outM[] = ['id' => (int) $m9->id, 'by' => (int) $m9->admin_id, 'body' => '', 'at' => $m9->created_at, 'file' => null, 'deleted' => true];
            continue;
        }
        $outM[] = ['id' => (int) $m9->id, 'by' => (int) $m9->admin_id,
            /* utf8mb3: 4-byte emoji που σώθηκαν παλιά ως «????» δεν έχουν νόημα στην οθόνη */
            'body' => $m9->body === null ? null : preg_replace('/(\?\?\?\?\s?)+/', '', (string) $m9->body), 'at' => $m9->created_at,
            'edited' => !empty($m9->edited_at),
            'reply' => $quoteOf($m9->reply_to ?? 0),
            'reacts' => $reactsM[(int) $m9->id] ?? (object) [],
            /* Διόρθωση μόνο το πρώτο λεπτό (κανόνας 18/9/2026): πόσα δευτερόλεπτα μένουν */
            'editLeft' => (int) $m9->admin_id === $adminId && !$m9->filename ? max(0, 60 - (time() - strtotime($m9->created_at))) : 0,
            'file' => $m9->filename ? ['name' => $m9->filename, 'size' => (int) $m9->size, 'id' => (int) $m9->id,
                'mime' => $m9->mime, 'kind' => Storage::kindFromMime($m9->mime),
                'url' => 'api.php?a=chat_file&id=' . (int) $m9->id] : null];
    }
    /* Διαγραφές των τελευταίων 15΄ σε αυτό το κανάλι: όποιος έχει ήδη το μήνυμα στην οθόνη το αφαιρεί. */
    $delIds = Capsule::table('mod_cpm_chat')->where('channel', $ch)->where('deleted_at', '>=', date('Y-m-d H:i:s', time() - 900))->pluck('id')->all();
    /* Επεξεργασίες των τελευταίων 15΄: το νέο κείμενο μπαίνει στη θέση του παλιού σε όσους το βλέπουν. */
    $edits = [];
    foreach (Capsule::table('mod_cpm_chat')->where('channel', $ch)->whereNull('deleted_at')->where('edited_at', '>=', date('Y-m-d H:i:s', time() - 900))->get(['id', 'body']) as $e9) {
        $edits[] = ['id' => (int) $e9->id, 'body' => preg_replace('/(\?\?\?\?\s?)+/', '', (string) $e9->body)];
    }
    // mark read (με ώρα — για τις αποδείξεις ανάγνωσης)
    if ($maxId > 0) {
        if (Capsule::table('mod_cpm_chat_reads')->where('admin_id', $adminId)->where('channel', $ch)->exists()) {
            Capsule::table('mod_cpm_chat_reads')->where('admin_id', $adminId)->where('channel', $ch)
                ->where('last_id', '<', $maxId)->update(['last_id' => $maxId, 'updated_at' => date('Y-m-d H:i:s')]);
        } else {
            Capsule::table('mod_cpm_chat_reads')->insert(['admin_id' => $adminId, 'channel' => $ch, 'last_id' => $maxId, 'updated_at' => date('Y-m-d H:i:s')]);
        }
    }
    /* ✓✓ Ποιος έχει διαβάσει μέχρι πού: οι υπόλοιποι του καναλιού με το τελευταίο id που είδαν και πότε.
       DM: ο άλλος. Ομάδα/#Ομάδα: όλα τα μέλη. Η οθόνη γράφει «Διαβάστηκε» κάτω από τα δικά μου. */
    $membersR = [];
    if ($ch === 'team') {
        $membersR = Capsule::table('tbladmins')->where('disabled', 0)->pluck('id')->all();
    } elseif (preg_match('/^d(\d+)-(\d+)$/', $ch, $mR)) {
        $membersR = [(int) $mR[1], (int) $mR[2]];
    } elseif (preg_match('/^g(\d+)$/', $ch, $mR)) {
        $membersR = array_filter(array_map('intval', explode(',', (string) Capsule::table('mod_cpm_chat_groups')->where('id', (int) $mR[1])->value('members'))));
    }
    $membersR = array_values(array_diff(array_map('intval', $membersR), [$adminId]));
    $reads = [];
    $rowsR = [];
    foreach (Capsule::table('mod_cpm_chat_reads')->where('channel', $ch)->whereIn('admin_id', $membersR ?: [0])->get() as $rr) { $rowsR[(int) $rr->admin_id] = $rr; }
    foreach ($membersR as $mid9) {
        $rr = $rowsR[$mid9] ?? null;
        $reads[] = ['id' => $mid9, 'name' => Db::adminName($mid9), 'lastId' => $rr ? (int) $rr->last_id : 0, 'at' => $rr ? $rr->updated_at : null];
    }
    $reactUpd = [];
    if ($after > 0) {
        $chg = Capsule::table('mod_cpm_chat')->where('channel', $ch)->where('react_at', '>=', date('Y-m-d H:i:s', time() - 900))->pluck('id')->all();
        $chg = array_map('intval', $chg);
        $rr9 = $reactFor($chg);
        foreach ($chg as $cid9) { $reactUpd[] = ['id' => $cid9, 'reacts' => $rr9[$cid9] ?? (object) []]; }
    }
    out(['messages' => $outM, 'deleted' => array_map('intval', $delIds), 'edited' => $edits, 'reads' => $reads, 'members' => count($membersR), 'reactUpd' => $reactUpd]);

case 'chat_react':                      // 👍 ✅ … πάνω σε μήνυμα chat (toggle)
    $mR = Capsule::table('mod_cpm_chat')->where('id', (int) ($in['id'] ?? 0))->first();
    $codeR = (string) ($in['code'] ?? '');
    if (!$mR || !empty($mR->deleted_at) || !cnp_chat_access($mR->channel, $adminId) || !in_array($codeR, ['up', 'ok', 'eyes', 'heart', 'party', 'think', 'down'], true)) { fail('input'); }
    $qR = Capsule::table('mod_cpm_chat_react')->where('msg_id', (int) $mR->id)->where('admin_id', $adminId)->where('code', $codeR);
    if ($qR->exists()) { $qR->delete(); $onR = false; }
    else { Capsule::table('mod_cpm_chat_react')->insert(['msg_id' => (int) $mR->id, 'admin_id' => $adminId, 'code' => $codeR, 'created_at' => date('Y-m-d H:i:s')]); $onR = true; }
    Capsule::table('mod_cpm_chat')->where('id', (int) $mR->id)->update(['react_at' => date('Y-m-d H:i:s')]);
    out(['ok' => true, 'on' => $onR]);

case 'chat_edit':                       // επεξεργασία δικού μου ΓΡΑΠΤΟΥ μηνύματος
    $mE = Capsule::table('mod_cpm_chat')->where('id', (int) ($in['id'] ?? 0))->first();
    if (!$mE || !cnp_chat_access($mE->channel, $adminId) || !empty($mE->deleted_at)) { fail('message', 404); }
    if ((int) $mE->admin_id !== $adminId) { fail('Μπορείς να αλλάξεις μόνο δικά σου μηνύματα', 403); }
    if ($mE->filename) { fail('Μήνυμα με αρχείο/φωνητικό δεν επεξεργάζεται — σβήσ’ το και στείλε νέο'); }
    if (time() - strtotime($mE->created_at) > 60) { fail('Η διόρθωση επιτρέπεται μόνο το πρώτο λεπτό — μετά, σβήσ’ το και στείλε νέο'); }
    $bodyE = mb_substr(trim(preg_replace('/[\x{10000}-\x{10FFFF}]/u', '', (string) ($in['body'] ?? ''))), 0, 4000);
    if ($bodyE === '') { fail('Κενό μήνυμα — αν θέλεις να το αφαιρέσεις, πάτα διαγραφή'); }
    if ($bodyE !== (string) $mE->body) {
        Capsule::table('mod_cpm_chat')->where('id', (int) $mE->id)->update(['body' => $bodyE, 'edited_at' => date('Y-m-d H:i:s')]);
    }
    out(['ok' => true, 'body' => $bodyE]);

case 'chat_del':                        // διαγραφή δικού μου μηνύματος (Full: οποιουδήποτε) — soft, με αφαίρεση αρχείου
    $mD = Capsule::table('mod_cpm_chat')->where('id', (int) ($in['id'] ?? 0))->first();
    if (!$mD || !cnp_chat_access($mD->channel, $adminId)) { fail('message', 404); }
    if ((int) $mD->admin_id !== $adminId && !$FULL) { fail('Μπορείς να σβήσεις μόνο δικά σου μηνύματα', 403); }
    if (!empty($mD->deleted_at)) { out(['ok' => true]); }
    if ($mD->storage_id) { try { Storage::delete((int) $mD->storage_id); } catch (\Throwable $e) { } }
    Capsule::table('mod_cpm_chat')->where('id', (int) $mD->id)->update(['body' => null, 'filename' => null, 'storage_id' => null, 'mime' => null, 'size' => null,
        'deleted_at' => date('Y-m-d H:i:s'), 'deleted_by' => $adminId]);
    out(['ok' => true]);

case 'chat_send':
    if (!empty($_FILES)) {
        $in = $_POST;   // multipart με αρχείο
    }
    $ch = preg_replace('/[^a-z0-9\-]/', '', $in['channel'] ?? 'team');
    if (!cnp_chat_access($ch, $adminId)) {
        fail('channel', 403);
    }
    /* utf8mb3: τα 4-byte emoji θα γίνονταν «????» — κόβονται πριν την αποθήκευση */
    $body = mb_substr(trim(preg_replace('/[\x{10000}-\x{10FFFF}]/u', '', (string) ($in['body'] ?? ''))), 0, 4000);
    $fn = null;
    $sz = null;
    $storageId = null;
    $fmime = null;
    if (!empty($_FILES['file']) && $_FILES['file']['error'] === UPLOAD_ERR_OK) {
        if ($_FILES['file']['size'] > 50 * 1024 * 1024) {
            fail('Μέγιστο 50MB (για μεγαλύτερα βίντεο χρησιμοποίησε τα Συνημμένα σε task/CV)');
        }
        if (!cnp_file_ext_ok($_FILES['file']['name'])) {
            fail('Μη επιτρεπτός τύπος αρχείου');
        }
        $fn = mb_substr($_FILES['file']['name'], 0, 190);
        $sz = (int) $_FILES['file']['size'];
        $fmime = $_FILES['file']['type'] ?: 'application/octet-stream';
        $rec = Storage::store(['module' => 'chat', 'ref_type' => $ch, 'ref_id' => 0, 'src' => $_FILES['file']['tmp_name'],
            'orig_name' => $fn, 'mime' => $fmime, 'uploaded_by' => $adminId]);
        $storageId = (int) $rec['id'];
    }
    if ($body === '' && !$fn) {
        fail('empty');
    }
    /* Απάντηση με παράθεμα: μόνο σε μήνυμα του ΙΔΙΟΥ καναλιού */
    $replyTo = (int) ($in['reply_to'] ?? 0);
    if ($replyTo && !Capsule::table('mod_cpm_chat')->where('id', $replyTo)->where('channel', $ch)->exists()) { $replyTo = 0; }
    $mid = Capsule::table('mod_cpm_chat')->insertGetId(['channel' => $ch, 'admin_id' => $adminId,
        'body' => $body ?: null, 'filename' => $fn, 'storage_id' => $storageId, 'mime' => $fmime, 'size' => $sz,
        'reply_to' => $replyTo ?: null, 'created_at' => date('Y-m-d H:i:s')]);
    Db::setPref($adminId, 'last_seen', (string) time());
    // καμπανάκι στους παραλήπτες (DM: ο άλλος, ομάδα: όλα τα μέλη) — εκτός offline
    $recips = [];
    if (preg_match('/^d(\d+)-(\d+)$/', $ch, $m6)) {
        $recips = [(int) $m6[1] === $adminId ? (int) $m6[2] : (int) $m6[1]];
    } elseif (preg_match('/^g(\d+)$/', $ch, $m6)) {
        $gr = Capsule::table('mod_cpm_chat_groups')->where('id', (int) $m6[1])->first();
        $recips = array_diff(array_filter(array_map('intval', explode(',', $gr->members ?? ''))), [$adminId]);
        $gname = $gr->name ?? '';
    }
    foreach ($recips as $other) {
        if (!cnp_presence($other)['mute']) {
            Db::pushNotification($other, 'comment', '💬 ' . (isset($gname) ? "[$gname] " : '') . Db::adminName($adminId) . ': '
                . mb_substr($body ?: (strpos((string) $fmime, 'audio/') === 0 ? '🎙 φωνητικό μήνυμα' : '📎 ' . $fn), 0, 80), '/projectmanagement/#/chat');
        }
    }
    out(['ok' => true, 'id' => $mid]);

case 'chat_file':                       // κατέβασμα/προβολή συνημμένου chat (auth: μέλος καναλιού)
    $m9 = Capsule::table('mod_cpm_chat')->where('id', (int) ($_GET['id'] ?? 0))->first();
    if (!$m9 || (!$m9->stored && !$m9->storage_id)) {
        fail('file', 404);
    }
    if (!cnp_chat_access($m9->channel, $adminId)) {
        fail('file', 403);
    }
    if ($m9->storage_id) {                                  // νέο: μέσω Storage (S3/local) — κρατά channel auth
        $srec = Storage::record((int) $m9->storage_id);
        if (!$srec) { fail('file', 404); }
        $dl = !empty($_GET['dl']);
        if ($srec['driver'] === 's3') { header('Location: ' . Storage::presign($srec['id'], 300, $dl), true, 302); exit; }
        $stream = Storage::openRead($srec['id']);
        if (!$stream) { fail('file', 404); }
        $mime = $srec['mime'] ?: 'application/octet-stream';
        $preview = ($mime === 'application/pdf' || strpos($mime, 'image/') === 0 || strpos($mime, 'video/') === 0 || strpos($mime, 'audio/') === 0);
        header('Content-Type: ' . $mime);
        header('X-Content-Type-Options: nosniff');
        header('Content-Disposition: ' . (($dl || !$preview) ? 'attachment' : 'inline') . '; filename="' . rawurlencode($srec['orig_name'] ?: 'file') . '"');
        if ($srec['size']) { header('Content-Length: ' . (int) $srec['size']); }
        fpassthru($stream); fclose($stream); exit;
    }
    $path = realpath(__DIR__ . '/../attachments/cloudonprojects/' . $m9->stored);
    if (!$path || strpos($path, realpath(__DIR__ . '/../attachments/cloudonprojects') . DIRECTORY_SEPARATOR) !== 0 || !is_file($path)) {
        fail('file', 404);
    }
    header('Content-Type: application/octet-stream');
    header('Content-Disposition: attachment; filename="' . $m9->filename . '"');
    header('Content-Length: ' . filesize($path));
    readfile($path);
    exit;

case 'chat_status':                     // Χειροκίνητη δήλωση κατάστασης (+ λόγος + διάρκεια)
    $defsS = cnp_presence_defs();
    $stS = trim((string) ($in['status'] ?? ''));
    Db::setPref($adminId, 'last_seen', (string) time());   // προφανώς είναι εδώ
    if ($stS === '' || $stS === 'auto') {
        /* Επιστροφή σε αυτόματο — ο παλμός της εφαρμογής αποφασίζει ξανά. */
        Db::setPref($adminId, 'chat_status', '');
        Db::setPref($adminId, 'chat_reason', '');
        Db::setPref($adminId, 'chat_until', '0');
        Db::setPref($adminId, 'chat_set_at', '0');
        /* ΚΑΙ ΣΤΟ ΤΗΛΕΦΩΝΟ. Σε «αυτόματο» στέλνουμε ό,τι αποφάσισε ο παλμός —
           αλλιώς το κέντρο θα έμενε κολλημένο στην τελευταία χειροκίνητη. */
        $prAuto = cnp_presence($adminId);
        $syncA = Pbx3cxPresence::sync($adminId, $prAuto) ?: ['ok' => true, 'skip' => 'mode'];
        out(['ok' => true, 'presence' => $prAuto, 'pbx' => $syncA]);
    }
    $stS = cnp_presence_legacy($stS);
    /* ΜΟΝΟ ΟΣΕΣ ΕΠΙΛΕΓΟΝΤΑΙ. Το «εκτός» το βάζει ο παλμός — δεν δηλώνεται. */
    if (!isset($defsS[$stS]) || empty($defsS[$stS][3])) {
        fail('Άγνωστη κατάσταση', 400);
    }
    /* «ΣΕ ΣΥΣΚΕΨΗ» ΘΕΛΕΙ ΠΑΝΤΑ ΛΗΞΗ. Οι υπόλοιπες καταστάσεις μπορούν να μείνουν
       μέχρι να τις αλλάξεις — αυτή όχι: κατεβάζει το τηλέφωνο σε «Out of office»
       στο 3CX, και μια σύσκεψη χωρίς τέλος σημαίνει χειριστής άφαντος για ώρες
       χωρίς κανείς να ξέρει γιατί. Με λήξη, η κατάσταση σβήνει μόνη της. */
    if ($stS === 'meeting') {
        $dChk = (string) ($in['mins'] ?? '0');
        if ($dChk !== 'eod' && (int) $dChk <= 0) {
            fail('Η σύσκεψη θέλει διάρκεια — διάλεξε πόση ώρα ή «ως το τέλος της ημέρας», '
               . 'ώστε το τηλέφωνο να ξανανοίξει μόνο του.', 400);
        }
    }
    // η σύνδεση DB είναι utf8mb3 — αφαίρεσε 4-byte chars (emoji) για να μη γίνουν «????»
    $reason = preg_replace('/[\x{10000}-\x{10FFFF}]/u', '', trim((string) ($in['reason'] ?? '')));
    /* Διάρκεια: λεπτά, ή 'eod' για μέχρι το τέλος της ημέρας, ή 0 = μέχρι να την αλλάξει. */
    $durS = (string) ($in['mins'] ?? '0');
    if ($durS === 'eod') {
        $untilS = strtotime('today 23:59');
    } else {
        $mS = max(0, min(720, (int) $durS));
        $untilS = $mS ? time() + $mS * 60 : 0;
    }
    Db::setPref($adminId, 'chat_status', $stS);
    Db::setPref($adminId, 'chat_reason', mb_substr($reason, 0, 80));
    Db::setPref($adminId, 'chat_until', (string) $untilS);
    Db::setPref($adminId, 'chat_set_at', (string) time());   // ποια δήλωση είναι πιο φρέσκια
    /* ΚΑΙ ΣΤΟ ΤΗΛΕΦΩΝΟ. Αν δηλώνεις «σε σύσκεψη» στο εργαλείο, δεν έχει νόημα
       να συνεχίζει να χτυπάει το τηλέφωνο επειδή ξέχασες το δεύτερο πρόγραμμα. */
    $syncM = Pbx3cxPresence::push($adminId, $stS);
    out(['ok' => true, 'presence' => cnp_presence($adminId), 'pbx' => $syncM]);

/* ============ 🏷 ΚΑΤΗΓΟΡΙΟΠΟΙΗΣΗ TICKETS (root-cause) ============ */
case 'ticket_classify':                 // ο διαχειριστής/επικεφαλής ταξινομεί
    if (!cnp_can_reply_clients($adminId, $FULL)) {
        fail('Μόνο διαχειριστής ή επικεφαλής ταξινομεί tickets', 403);
    }
    $tid7 = (int) ($in['ticket'] ?? 0);
    if (!$tid7 || !Capsule::table('tbltickets')->where('id', $tid7)->exists()) {
        fail('ticket', 404);
    }
    $area7 = (int) ($in['area'] ?? 0) ?: null;
    $cause7 = (int) ($in['cause'] ?? 0) ?: null;
    $note7 = cnp_clean_html($in['note'] ?? '');
    Capsule::table('mod_cpm_ticket_class')->updateOrInsert(['ticketid' => $tid7],
        ['area_id' => $area7, 'cause_id' => $cause7,
         'note' => $note7 !== '' ? $note7 : null,
         'classified_by' => $adminId, 'classified_at' => date('Y-m-d H:i:s')]);
    if (function_exists('logActivity')) {
        logActivity('CPM: ticket #' . $tid7 . ' ταξινομήθηκε (area=' . ($area7 ?: '-') . ' cause=' . ($cause7 ?: '-') . ') admin #' . $adminId);
    }
    out(['ok' => true]);

case 'classify_suggest':               // ✨ AI προτείνει area+cause από το περιεχόμενο
    if (!cnp_can_reply_clients($adminId, $FULL)) {
        fail('perm', 403);
    }
    $tid7 = (int) ($in['ticket'] ?? 0);
    $tk7 = Capsule::table('tbltickets')->where('id', $tid7)->first();
    if (!$tk7) {
        fail('ticket', 404);
    }
    $key7 = (string) (Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')
        ->where('setting', 'ai_api_key')->value('value') ?: '');
    if ($key7 === '') {
        fail('Δεν έχει οριστεί AI API key στις Ρυθμίσεις');
    }
    $cats7 = cnp_ticket_cats();
    $areaList = implode(', ', array_map(function ($a) { return $a['id'] . '=' . $a['name']; }, $cats7['area']));
    $causeList = implode(', ', array_map(function ($c) { return $c['id'] . '=' . $c['name']; }, $cats7['cause']));
    $conv7 = mb_substr($tk7->title . "\n" . $tk7->message, 0, 2500);
    foreach (Capsule::table('tblticketreplies')->where('tid', $tid7)->orderBy('id')->limit(8)->get() as $r) {
        $conv7 .= "\n" . mb_substr($r->message, 0, 800);
    }
    $prompt7 = "Είσαι ταξινομητής tickets IT εταιρείας. Διάλεξε την ΚΑΛΥΤΕΡΗ Περιοχή/Προϊόν και Ρίζα-προβλήματος από τις λίστες. "
        . "Απάντησε ΜΟΝΟ με JSON χωρίς markdown: {\"area_id\": <id ή 0>, \"cause_id\": <id ή 0>}.\n\n"
        . "ΠΕΡΙΟΧΕΣ: $areaList\nΡΙΖΕΣ: $causeList\n\nTICKET:\n$conv7";
    $ch7 = curl_init('https://api.anthropic.com/v1/messages');
    curl_setopt_array($ch7, [CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 45, CURLOPT_POST => true,
        CURLOPT_HTTPHEADER => ['Content-Type: application/json', 'x-api-key: ' . $key7, 'anthropic-version: 2023-06-01'],
        CURLOPT_POSTFIELDS => json_encode(['model' => 'claude-haiku-4-5-20251001', 'max_tokens' => 100,
            'messages' => [['role' => 'user', 'content' => $prompt7]]])]);
    $j7 = json_decode((string) curl_exec($ch7), true);
    curl_close($ch7);
    $txt7 = $j7['content'][0]['text'] ?? '';
    $sug7 = json_decode(trim(preg_replace('/^```json|```$/m', '', trim($txt7))), true);
    out(['ok' => true, 'area' => (int) ($sug7['area_id'] ?? 0) ?: null, 'cause' => (int) ($sug7['cause_id'] ?? 0) ?: null]);

case 'kb_match':                        // 📚 άρθρα γνώσης που ταιριάζουν σε area/cause
    $terms = trim($_GET['q'] ?? '');
    if ($terms === '') {
        out(['items' => []]);
    }
    $qw = cnp_words($terms);
    $hits = [];
    foreach (Capsule::table('mod_cpm_kb')->get() as $k) {
        $sc = cnp_overlap($qw, cnp_words($k->title . ' ' . $k->keywords . ' ' . $k->tags));
        if ($sc > 0) {
            $hits[] = ['id' => (int) $k->id, 'title' => $k->title, 'solution' => $k->solution, 'score' => $sc];
        }
    }
    usort($hits, function ($a, $b) { return $b['score'] <=> $a['score']; });
    out(['items' => array_slice($hits, 0, 4)]);

case 'tcats':                           // λίστα κατηγοριών (+ πλήθος για διαχείριση)
    $counts = [];
    foreach (Capsule::table('mod_cpm_ticket_class')
        ->select(Capsule::raw('area_id, cause_id'))->get() as $cl) {
        if ($cl->area_id) { $counts['a' . $cl->area_id] = ($counts['a' . $cl->area_id] ?? 0) + 1; }
        if ($cl->cause_id) { $counts['c' . $cl->cause_id] = ($counts['c' . $cl->cause_id] ?? 0) + 1; }
    }
    $out7 = ['area' => [], 'cause' => []];
    foreach (Capsule::table('mod_cpm_ticket_cats')->orderBy('sort')->orderBy('id')->get() as $r) {
        $k = $r->kind === 'cause' ? 'cause' : 'area';
        $out7[$k][] = ['id' => (int) $r->id, 'name' => $r->name, 'color' => $r->color,
            'used' => (int) ($counts[($k === 'cause' ? 'c' : 'a') . $r->id] ?? 0)];
    }
    out($out7);

case 'tcat_save':
    $kind7 = ($in['kind'] ?? '') === 'cause' ? 'cause' : 'area';
    $nm7 = mb_substr(trim($in['name'] ?? ''), 0, 80);
    if ($nm7 === '') {
        fail('Δώσε όνομα');
    }
    $col7 = preg_match('/^#[0-9a-fA-F]{6}$/', $in['color'] ?? '') ? $in['color'] : '#0090dd';
    $cid7 = (int) ($in['id'] ?? 0);
    if ($cid7) {
        Capsule::table('mod_cpm_ticket_cats')->where('id', $cid7)->update(['name' => $nm7, 'color' => $col7]);
    } else {
        $cid7 = Capsule::table('mod_cpm_ticket_cats')->insertGetId(['kind' => $kind7, 'name' => $nm7,
            'color' => $col7, 'sort' => (int) Capsule::table('mod_cpm_ticket_cats')->where('kind', $kind7)->max('sort') + 1]);
    }
    /* Η περιοχή και το προϊόν είναι ΤΟ ΙΔΙΟ πράγμα (ενοποίηση 22/09/2026).
       Ό,τι αλλάξει εδώ ακολουθεί και ο κατάλογος — αλλιώς οι δύο λίστες
       ξαναρχίζουν να αποκλίνουν, που ήταν ακριβώς το πρόβλημα. */
    if ($kind7 === 'area') {
        $pRow = Capsule::table('mod_cpm_products')->where('area_id', $cid7)->first();
        if ($pRow) {
            Capsule::table('mod_cpm_products')->where('id', $pRow->id)
                ->update(['name' => $nm7, 'color' => $col7]);
        } else {
            Capsule::table('mod_cpm_products')->insert(['name' => $nm7, 'color' => $col7,
                'area_id' => $cid7, 'active' => 1, 'sort' => 900,
                'created_at' => date('Y-m-d H:i:s')]);
        }
    }
    out(['ok' => true, 'id' => $cid7]);

case 'tcat_reorder':                     // νέα σειρά περιοχών/ριζών (drag ή ↑↓)
    $kindR = ($in['kind'] ?? '') === 'cause' ? 'cause' : 'area';
    $idsR = (array) ($in['ids'] ?? []);
    if (!$idsR) { fail('Δεν δόθηκε σειρά'); }
    foreach ($idsR as $i => $cid) {
        Capsule::table('mod_cpm_ticket_cats')->where('id', (int) $cid)->where('kind', $kindR)
            ->update(['sort' => $i + 1]);
    }
    out(['ok' => true]);

case 'tcat_del':
    $cid7 = (int) ($in['id'] ?? 0);
    Capsule::table('mod_cpm_ticket_cats')->where('id', $cid7)->delete();
    Capsule::table('mod_cpm_ticket_class')->where('area_id', $cid7)->update(['area_id' => null]);
    Capsule::table('mod_cpm_ticket_class')->where('cause_id', $cid7)->update(['cause_id' => null]);
    out(['ok' => true]);

case 'rootcause':                       // 🔬 ανάλυση ριζών (full)
    // Η πρόσβαση ελέγχεται από την πύλη περιοχών («Αναφορές & απόδοση»).


    $since7 = date('Y-m-d', strtotime('-' . (in_array((int) ($_GET['days'] ?? 90), [30, 90, 180, 365], true) ? (int) $_GET['days'] : 90) . ' days'));
    $cats7 = cnp_ticket_cats();
    $areaN = []; foreach ($cats7['area'] as $a) { $areaN[$a['id']] = $a; }
    $causeN = []; foreach ($cats7['cause'] as $c) { $causeN[$c['id']] = $c; }
    // ταξινομημένα tickets στο διάστημα
    $daysN = in_array((int) ($_GET['days'] ?? 90), [30, 90, 180, 365], true) ? (int) $_GET['days'] : 90;
    $prevSince = date('Y-m-d', strtotime('-' . ($daysN * 2) . ' days'));
    $rows7 = Capsule::table('mod_cpm_ticket_class as cl')
        ->join('tbltickets as t', 't.id', '=', 'cl.ticketid')
        ->where('t.date', '>=', $prevSince)
        ->get(['cl.ticketid', 'cl.area_id', 'cl.cause_id', 't.userid', 't.status', 't.date']);
    // διαχώρισε τρέχουσα vs προηγούμενη περίοδο + μηνιαία buckets
    $prevCause = []; $monthly = [];
    foreach ($rows7 as $r) {
        $inCur = $r->date >= $since7;
        if (!$inCur && $r->cause_id) { $prevCause[$r->cause_id] = ($prevCause[$r->cause_id] ?? 0) + 1; }
        if ($inCur && $r->cause_id) {
            $ym = substr($r->date, 0, 7);
            $monthly[$ym][$r->cause_id] = ($monthly[$ym][$r->cause_id] ?? 0) + 1;
        }
    }
    $rows7 = $rows7->filter(function ($r) use ($since7) { return $r->date >= $since7; });
    // χρόνος ανά ticket (μέσω linked task timelogs)
    $timeByTicket = [];
    try {
        foreach (Capsule::table('mod_cpm_timelogs as tl')
            ->join('mod_cpm_tasks as tk', 'tk.id', '=', 'tl.task_id')
            ->whereNotNull('tk.ticketid')->where('tl.running', 0)
            ->groupBy('tk.ticketid')->get([Capsule::raw('tk.ticketid as tid'), Capsule::raw('SUM(tl.minutes) m')]) as $r) {
            $timeByTicket[(int) $r->tid] = (int) $r->m;
        }
    } catch (\Throwable $e) {
    }
    $byCause = []; $byArea = []; $matrix = []; $total7 = 0; $classified7 = 0;
    foreach ($rows7 as $r) {
        $total7++;
        if ($r->cause_id) {
            $classified7++;
            $byCause[$r->cause_id]['n'] = ($byCause[$r->cause_id]['n'] ?? 0) + 1;
            $byCause[$r->cause_id]['min'] = ($byCause[$r->cause_id]['min'] ?? 0) + ($timeByTicket[(int) $r->ticketid] ?? 0);
        }
        if ($r->area_id) {
            $byArea[$r->area_id]['n'] = ($byArea[$r->area_id]['n'] ?? 0) + 1;
        }
        if ($r->area_id && $r->cause_id) {
            $matrix[$r->area_id][$r->cause_id] = ($matrix[$r->area_id][$r->cause_id] ?? 0) + 1;
        }
    }
    $topCauses = [];
    foreach ($byCause as $cid => $d) {
        $topCauses[] = ['id' => $cid, 'name' => $causeN[$cid]['name'] ?? '?', 'color' => $causeN[$cid]['color'] ?? '#888',
            'count' => $d['n'], 'minutes' => $d['min'] ?? 0,
            'delta' => $d['n'] - ($prevCause[$cid] ?? 0)];
    }
    usort($topCauses, function ($a, $b) { return $b['count'] <=> $a['count']; });
    $topAreas = [];
    foreach ($byArea as $aid => $d) {
        $topAreas[] = ['id' => $aid, 'name' => $areaN[$aid]['name'] ?? '?', 'color' => $areaN[$aid]['color'] ?? '#888', 'count' => $d['n']];
    }
    usort($topAreas, function ($a, $b) { return $b['count'] <=> $a['count']; });
    // total tickets στο διάστημα (για ποσοστό ταξινόμησης)
    $allTk = (int) Capsule::table('tbltickets')->where('date', '>=', $since7)->count();
    // μηνιαία σειρά (τελευταίοι μήνες) για τις top-5 ρίζες
    ksort($monthly);
    $months = array_keys($monthly);
    $top5 = array_slice(array_map(function ($x) { return $x['id']; }, $topCauses), 0, 5);
    $series = [];
    foreach ($months as $ym) {
        $row = ['ym' => $ym];
        foreach ($top5 as $cid) { $row[$cid] = $monthly[$ym][$cid] ?? 0; }
        $series[] = $row;
    }
    out(['topCauses' => $topCauses, 'topAreas' => $topAreas,
        'matrix' => $matrix, 'areas' => $cats7['area'], 'causes' => $cats7['cause'],
        'classified' => $classified7, 'totalClassified' => $total7, 'allTickets' => $allTk,
        'series' => $series, 'top5' => $top5]);

case 'standup':                         // 🏃 Standup dashboard — απασχόληση περιόδου + on-time
    $period = in_array($_GET['p'] ?? 'week', ['week', 'month'], true) ? $_GET['p'] : 'week';
    if ($period === 'month') {
        $ps = date('Y-m-01'); $pe = date('Y-m-t');
    } else {
        $ps = date('Y-m-d', strtotime('monday this week')); $pe = date('Y-m-d', strtotime('sunday this week'));
    }
    $doneIds = Capsule::table('mod_cpm_statuses')->where('is_done', 1)->pluck('id')->all() ?: [0];
    $bugType = (int) Capsule::table('mod_cpm_task_types')->where('name', 'like', '%Bug%')->value('id');
    $vis = $FULL ? null : Db::visibleProjectIds($adminId);
    $tScope = function ($q) use ($FULL, $adminId, $vis) {
        if (!$FULL) {
            $q->where(function ($w) use ($adminId, $vis) {
                /* Ό,τι κρατάω εγώ — και ό,τι μου ανατέθηκε χωρίς να το κρατά άλλος. */
                $w->where('t.action_user', $adminId)
                  ->orWhere(function ($x) use ($adminId) {
                      $x->where('t.assignee', $adminId)
                        ->where(function ($y) { $y->whereNull('t.action_user')->orWhere('t.action_user', 0); });
                  });
                if ($vis) { $w->orWhereIn('t.project_id', $vis ?: [0]); }
            });
        }
        return $q;
    };
    // στατιστικά περιόδου + λίστες drill-down (κλικ στην κάρτα → τα στοιχεία)
    $drill = [];
    $newProjRows = Capsule::table('mod_cpm_projects')->where('created_at', '>=', $ps . ' 00:00:00')
        ->when($vis !== null, function ($q) use ($vis) { $q->whereIn('id', $vis ?: [0]); })
        ->orderByDesc('created_at')->get(['id', 'name', 'clientid', 'kind']);
    $newProj = count($newProjRows);
    $drill['newProjects'] = $newProjRows->map(function ($p) {
        return ['type' => 'project', 'id' => (int) $p->id, 'title' => $p->name,
            'sub' => $p->kind === 'client' ? clientLabel($p->clientid) : 'Τμήμα'];
    })->all();
    $bugRows = $tScope(Capsule::table('mod_cpm_tasks as t')->leftJoin('mod_cpm_projects as p', 'p.id', '=', 't.project_id'))
        ->where('t.type_id', $bugType)->whereNotIn('t.status_id', $doneIds)
        ->get(['t.id', 't.title', 'p.name as pname']);
    $bugsOpen = count($bugRows);
    $drill['bugs'] = $bugRows->map(function ($t) {
        return ['type' => 'task', 'id' => (int) $t->id, 'title' => $t->title, 'sub' => cnp_pn($t->pname)];
    })->all();
    $dueRows = $tScope(Capsule::table('mod_cpm_tasks as t')->leftJoin('mod_cpm_projects as p', 'p.id', '=', 't.project_id'))
        ->whereBetween('t.due_date', [$ps, $pe])->whereNotIn('t.status_id', $doneIds)
        ->orderBy('t.due_date')->get(['t.id', 't.title', 't.due_date', 'p.name as pname']);
    $dueThis = count($dueRows);
    $drill['deadlines'] = $dueRows->map(function ($t) {
        return ['type' => 'task', 'id' => (int) $t->id, 'title' => $t->title, 'sub' => cnp_pn($t->pname) . ' · λήγει ' . $t->due_date];
    })->all();
    $doneRows = $tScope(Capsule::table('mod_cpm_tasks as t')->leftJoin('mod_cpm_projects as p', 'p.id', '=', 't.project_id'))
        ->whereBetween('t.completed_at', [$ps . ' 00:00:00', $pe . ' 23:59:59'])
        ->orderByDesc('t.completed_at')->get(['t.id', 't.title', 't.completed_at', 'p.name as pname']);
    $doneThis = count($doneRows);
    $drill['completed'] = $doneRows->map(function ($t) {
        return ['type' => 'task', 'id' => (int) $t->id, 'title' => $t->title, 'sub' => $t->pname . ' · ' . substr($t->completed_at, 0, 10)];
    })->all();
    // roster ανά μέλος
    $admins = $FULL ? Db::admins() : Capsule::table('tbladmins')->where('id', $adminId)->get();
    $teamIds = [];
    try {
        $teamIds = array_map('intval', Capsule::table('mod_cpm_team_members')->pluck('admin_id')->all());
    } catch (\Throwable $e) {
    }
    $roster = [];
    $minsBy = [];
    try {
        foreach (Capsule::table('mod_cpm_timelogs')->where('running', 0)
            ->whereBetween('created_at', [$ps . ' 00:00:00', $pe . ' 23:59:59'])
            ->groupBy('admin_id')->get(['admin_id', Capsule::raw('SUM(minutes) m')]) as $r) {
            $minsBy[(int) $r->admin_id] = (int) $r->m;
        }
    } catch (\Throwable $e) {
    }
    foreach ($admins as $a) {
        $aid = (int) $a->id;
        $nm = Db::adminName($aid);
        // αγνόησε bots/test/system accounts
        if (preg_match('/\b(bot|test|debug|cnptest|system)\b/i', $nm)) { continue; }
        $open = cnp_scope_mine(Capsule::table('mod_cpm_tasks')->whereNotIn('status_id', $doneIds), $aid)->count();
        $overdue = cnp_scope_mine(Capsule::table('mod_cpm_tasks')->whereNotIn('status_id', $doneIds), $aid)
            ->whereNotNull('due_date')->where('due_date', '<', date('Y-m-d'))->count();
        $dueP = Capsule::table('mod_cpm_tasks')->where('assignee', $aid)->whereNotIn('status_id', $doneIds)
            ->whereBetween('due_date', [$ps, $pe])->count();
        // on-time: ολοκληρωμένα με deadline μέσα στην περίοδο
        /* ball-rule: ok — πιστώνεται όποιος την έκλεισε (δες `perf`). */
        $cl = Capsule::table('mod_cpm_tasks')
            ->whereRaw('COALESCE(completed_by, assignee) = ?', [$aid])->whereNotNull('due_date')
            ->whereBetween('completed_at', [$ps . ' 00:00:00', $pe . ' 23:59:59'])
            ->get(['due_date', 'completed_at']);
        $onT = 0; $late = 0;
        foreach ($cl as $t) { if (substr($t->completed_at, 0, 10) <= $t->due_date) { $onT++; } else { $late++; } }
        $tkOpen = Capsule::table('tbltickets')->where('flag', $aid)->whereNotIn('status', ['Closed', 'Cancelled'])->count();
        $mins = $minsBy[$aid] ?? 0;
        $activity = $open + $overdue + $dueP + $onT + $late + $tkOpen + $mins;
        // κράτα: ο ίδιος πάντα, μέλη ομάδας (για να φαίνεται και το «τίποτα») ή όποιον έχει δραστηριότητα
        if ($aid !== $adminId && !in_array($aid, $teamIds, true) && $activity === 0) { continue; }
        $roster[] = ['id' => $aid, 'name' => $nm,
            'open' => $open, 'overdue' => $overdue, 'dueP' => $dueP,
            'onTime' => $onT, 'late' => $late,
            'score' => ($onT + $late) ? round($onT / ($onT + $late) * 100) : null,
            'tickets' => $tkOpen, 'mins' => $mins];
    }
    // ταξινόμηση: εκπρόθεσμα ↓, μετά ανοιχτά ↓ (πιεσμένοι πρώτοι)
    usort($roster, function ($a, $b) {
        return ($b['overdue'] <=> $a['overdue']) ?: ($b['open'] <=> $a['open']) ?: ($b['mins'] <=> $a['mins']);
    });
    // εξέλιξη projects (ανοιχτά)
    $projs = [];
    foreach (($FULL ? Db::projects(false) : Db::projectsFor($adminId, false)) as $p) {
        if (in_array($p->pstatus, ['done'], true)) { continue; }
        [$pd, $pt, $ppct] = Db::projectProgress($p->id);
        $days = $p->due_date ? (int) floor((strtotime($p->due_date) - time()) / 86400) : null;
        $projs[] = ['id' => (int) $p->id, 'name' => $p->name, 'kind' => $p->kind ?? 'dept',
            'client' => clientLabel($p->clientid), 'health' => $p->health, 'pstatus' => $p->pstatus,
            'done' => $pd, 'total' => $pt, 'pct' => $ppct,
            'due' => $p->due_date ?: null, 'daysLeft' => $days];
    }
    usort($projs, function ($a, $b) {
        $ad = $a['daysLeft'] === null ? 9999 : $a['daysLeft']; $bd = $b['daysLeft'] === null ? 9999 : $b['daysLeft'];
        return $ad <=> $bd;
    });
    // tickets εξέλιξη
    $tkOpenRows = Capsule::table('tbltickets')->whereNotIn('status', ['Closed', 'Cancelled'])
        ->when(!$FULL, function ($q) use ($adminId) { $q->where('flag', $adminId); })
        ->orderByDesc('lastreply')->get(['id', 'tid', 'title', 'status']);
    $tkOpen = count($tkOpenRows);
    $drill['ticketsOpen'] = $tkOpenRows->map(function ($t) {
        return ['type' => 'ticket', 'id' => (int) $t->id, 'title' => '#' . $t->tid . ' ' . $t->title, 'sub' => $t->status];
    })->all();
    $tkClosedRows = Capsule::table('tbltickets')->where('status', 'Closed')
        ->whereBetween('lastreply', [$ps . ' 00:00:00', $pe . ' 23:59:59'])
        ->when(!$FULL, function ($q) use ($adminId) { $q->where('flag', $adminId); })
        ->orderByDesc('lastreply')->get(['id', 'tid', 'title', 'lastreply']);
    $tkClosedP = count($tkClosedRows);
    $drill['ticketsClosed'] = $tkClosedRows->map(function ($t) {
        return ['type' => 'ticket', 'id' => (int) $t->id, 'title' => '#' . $t->tid . ' ' . $t->title, 'sub' => 'έκλεισε ' . substr($t->lastreply, 0, 10)];
    })->all();
    out(['period' => $period, 'from' => $ps, 'to' => $pe, 'full' => $FULL,
        'stats' => ['newProjects' => $newProj, 'bugs' => $bugsOpen, 'deadlines' => $dueThis, 'completed' => $doneThis,
            'ticketsOpen' => $tkOpen, 'ticketsClosed' => $tkClosedP],
        'drill' => $drill, 'roster' => $roster, 'projects' => array_slice($projs, 0, 20)]);

/* ═══════════ 🔗 Δημόσιο link project για πελάτη (χωρίς credentials) ═══════════ */
case 'share_info':
case 'share_save':
case 'share_revoke':
case 'share_reply':
    $pid = (int) ($_GET['project'] ?? $_POST['project'] ?? ($in['project'] ?? 0));
    $proj = $pid ? Capsule::table('mod_cpm_projects')->where('id', $pid)->first() : null;
    if (!$proj) { fail('project', 404); }
    // δικαίωμα: full ή ορατότητα έργου
    $canShare = $FULL || in_array($pid, Db::visibleProjectIds($adminId), true);
    if (!$canShare) { fail('forbidden', 403); }
    $mkUrl = function ($tok) use ($pid) {
        $host = $_SERVER['HTTP_HOST'] ?? 'my.cloudon.gr';
        return 'https://' . $host . '/project/share.php?p=' . $pid . '&t=' . $tok;
    };
    $row = Capsule::table('mod_cpm_project_shares')->where('project_id', $pid)->first();

    if ($action === 'share_save') {
        $exp = trim($in['expires_at'] ?? '');
        $exp = preg_match('/^\d{4}-\d{2}-\d{2}$/', $exp) ? $exp . ' 23:59:59' : null;
        $canC = !empty($in['can_comment']) ? 1 : 0;
        $rotate = !empty($in['rotate']);
        if ($row && !$rotate) {
            Capsule::table('mod_cpm_project_shares')->where('id', $row->id)
                ->update(['expires_at' => $exp, 'can_comment' => $canC, 'revoked' => 0]);
            $tok = $row->token;
        } else {
            $tok = bin2hex(random_bytes(20));
            if ($row) {
                Capsule::table('mod_cpm_project_shares')->where('id', $row->id)
                    ->update(['token' => $tok, 'expires_at' => $exp, 'can_comment' => $canC, 'revoked' => 0]);
            } else {
                Capsule::table('mod_cpm_project_shares')->insert(['project_id' => $pid, 'token' => $tok,
                    'expires_at' => $exp, 'can_comment' => $canC, 'revoked' => 0, 'views' => 0,
                    'created_by' => $adminId, 'created_at' => date('Y-m-d H:i:s')]);
            }
        }
        logActivity("CNP: project share link " . ($rotate ? 'rotated' : 'saved') . " #$pid by admin $adminId");
        out(['url' => $mkUrl($tok), 'token' => $tok, 'expires_at' => $exp, 'can_comment' => $canC, 'revoked' => 0]);
    }

    if ($action === 'share_revoke') {
        if ($row) { Capsule::table('mod_cpm_project_shares')->where('id', $row->id)->update(['revoked' => 1]); }
        out(['ok' => true]);
    }

    if ($action === 'share_reply') {                 // απάντηση ομάδας στο thread του πελάτη
        $body = trim($in['body'] ?? '');
        if ($body === '') { fail('empty', 422); }
        Capsule::table('mod_cpm_share_comments')->insert(['project_id' => $pid, 'author' => Db::adminName($adminId),
            'body' => mb_substr($body, 0, 2000), 'from_team' => 1, 'admin_id' => $adminId,
            'created_at' => date('Y-m-d H:i:s')]);
        out(['ok' => true]);
    }

    // share_info
    $comments = Capsule::table('mod_cpm_share_comments')->where('project_id', $pid)
        ->orderBy('created_at')->get()->map(function ($c) {
            return ['author' => $c->author, 'body' => $c->body, 'team' => (int) $c->from_team, 'at' => $c->created_at];
        })->all();
    out(['exists' => (bool) $row,
        'url' => $row ? $mkUrl($row->token) : null,
        'expires_at' => $row && $row->expires_at ? substr($row->expires_at, 0, 10) : null,
        'can_comment' => $row ? (int) $row->can_comment : 0,
        'revoked' => $row ? (int) $row->revoked : 0,
        'views' => $row ? (int) $row->views : 0,
        'last_view' => $row ? $row->last_view : null,
        'comments' => $comments]);

case 'agenda':                          // 🗒 Ανοιχτά projects & tickets — αναλυτικά για meeting
    $doneIds = Capsule::table('mod_cpm_statuses')->where('is_done', 1)->pluck('id')->all() ?: [0];
    $today0 = date('Y-m-d');
    // ---- Ανοιχτά projects (αναλυτικά) ----
    $projects = [];
    foreach (($FULL ? Db::projects(false) : Db::projectsFor($adminId, false)) as $p) {
        if (in_array($p->pstatus, ['done'], true)) { continue; }
        [$pd, $pt, $ppct] = Db::projectProgress($p->id);
        $lastUpd = Capsule::table('mod_cpm_tasks')->where('project_id', $p->id)->max('updated_at');
        $nextT = Capsule::table('mod_cpm_tasks as t')->where('t.project_id', $p->id)
            ->whereNotIn('t.status_id', $doneIds)
            ->orderByRaw('t.priority DESC')->orderByRaw('t.due_date IS NULL, t.due_date ASC')
            ->first(['t.title', 't.assignee', 't.due_date']);
        $todos = Capsule::table('mod_cpm_project_todos')->where('project_id', $p->id)
            ->whereNull('done_at')->orderBy('sort')->orderBy('id')->limit(5)->pluck('title')->all();
        $todoTotal = Capsule::table('mod_cpm_project_todos')->where('project_id', $p->id)->count();
        $todoDone = Capsule::table('mod_cpm_project_todos')->where('project_id', $p->id)->whereNotNull('done_at')->count();
        $openTasks = Capsule::table('mod_cpm_tasks')->where('project_id', $p->id)->whereNotIn('status_id', $doneIds)->count();
        $ownerIds = Capsule::table('mod_cpm_tasks')->where('project_id', $p->id)->whereNotIn('status_id', $doneIds)
            ->whereNotNull('assignee')->distinct()->pluck('assignee')->all();
        $owners = array_values(array_filter(array_map(function ($id) { return $id ? Db::adminName((int) $id) : null; }, $ownerIds)));
        $spentMins = (int) Capsule::table('mod_cpm_timelogs as tl')->join('mod_cpm_tasks as t', 't.id', '=', 'tl.task_id')
            ->where('t.project_id', $p->id)->where('tl.running', 0)->sum('tl.minutes');
        $days = $p->due_date ? (int) floor((strtotime($p->due_date) - time()) / 86400) : null;
        $staleD = $lastUpd ? (int) floor((time() - strtotime($lastUpd)) / 86400) : null;
        $projects[] = ['id' => (int) $p->id, 'name' => $p->name, 'kind' => $p->kind ?? 'dept',
            'client' => $p->clientid ? clientLabel($p->clientid) : null, 'clientid' => (int) $p->clientid,
            'health' => $p->health, 'pstatus' => $p->pstatus,
            'done' => $pd, 'total' => $pt, 'pct' => $ppct, 'openTasks' => $openTasks,
            'todoDone' => $todoDone, 'todoTotal' => $todoTotal, 'pendingTodos' => $todos,
            'due' => $p->due_date ?: null, 'daysLeft' => $days,
            'lastUpdate' => $lastUpd ? substr($lastUpd, 0, 10) : null, 'staleDays' => $staleD,
            'owners' => $owners, 'spentMins' => $spentMins, 'budget' => $p->budget ? (float) $p->budget : null,
            'next' => $nextT ? ['title' => $nextT->title, 'who' => $nextT->assignee ? Db::adminName((int) $nextT->assignee) : null,
                'due' => $nextT->due_date ?: null] : null];
    }
    usort($projects, function ($a, $b) {
        $ad = $a['daysLeft'] === null ? 9999 : $a['daysLeft']; $bd = $b['daysLeft'] === null ? 9999 : $b['daysLeft'];
        return $ad <=> $bd;
    });
    // ---- Ανοιχτά tickets (αναλυτικά) ----
    $cats = cnp_ticket_cats();
    $areaN = []; foreach ($cats['area'] as $a) { $areaN[$a['id']] = $a; }
    $causeN = []; foreach ($cats['cause'] as $c) { $causeN[$c['id']] = $c; }
    $depN = [];
    foreach (Capsule::table('tblticketdepartments')->get(['id', 'name']) as $dp) { $depN[(int) $dp->id] = $dp->name; }
    $tickets = [];
    $tq = Capsule::table('tbltickets')->whereNotIn('status', ['Closed', 'Cancelled']);
    if (!$FULL) { $tq->where('flag', $adminId); }
    foreach ($tq->orderByRaw("FIELD(urgency,'High','Medium','Low')")->orderBy('lastreply')->get() as $tk) {
        $lastRep = Capsule::table('tblticketreplies')->where('tid', $tk->id)->orderByDesc('id')->first(['admin', 'date']);
        $waitUs = !$lastRep ? true : (trim((string) $lastRep->admin) === '');   // πελάτης απάντησε τελευταίος → περιμένει εμάς
        $cl = Capsule::table('mod_cpm_ticket_class')->where('ticketid', $tk->id)->first(['area_id', 'cause_id', 'note']);
        $cid = $tk->userid ? clientLabel($tk->userid) : ($tk->name ?: 'Guest');
        $tickets[] = ['id' => (int) $tk->id, 'tid' => $tk->tid, 'title' => $tk->title,
            'client' => $cid, 'dept' => $depN[(int) $tk->did] ?? '—', 'status' => $tk->status,
            'urgency' => $tk->urgency, 'assignee' => $tk->flag ? Db::adminName((int) $tk->flag) : null,
            'age' => (int) floor((time() - strtotime($tk->date)) / 86400),
            'idle' => (int) floor((time() - strtotime($tk->lastreply ?: $tk->date)) / 86400),
            'waitUs' => $waitUs,
            'area' => $cl && $cl->area_id && isset($areaN[$cl->area_id]) ? $areaN[$cl->area_id] : null,
            'cause' => $cl && $cl->cause_id && isset($causeN[$cl->cause_id]) ? $causeN[$cl->cause_id] : null,
            'note' => $cl->note ?? null];
    }
    out(['projects' => $projects, 'tickets' => $tickets,
        'counts' => ['projects' => count($projects), 'tickets' => count($tickets),
            'waitUs' => count(array_filter($tickets, function ($t) { return $t['waitUs']; }))]]);

/* ═══════ WHMCS: διαχείριση Τμημάτων & Ticket Statuses (full μόνο) ═══════ */
case 'wh_ticket_manage':
    $depsW = [];
    foreach (Capsule::table('tblticketdepartments')->orderBy('order')->get() as $dp) {
        $depsW[] = ['id' => (int) $dp->id, 'name' => $dp->name, 'email' => $dp->email,
            'hidden' => (int) $dp->hidden,
            'tickets' => (int) Capsule::table('tbltickets')->where('did', $dp->id)->count()];
    }
    $statW = [];
    $coreW = ['Open', 'Answered', 'Customer-Reply', 'Closed'];
    foreach (Capsule::table('tblticketstatuses')->orderBy('sortorder')->get() as $s) {
        $statW[] = ['id' => (int) $s->id, 'title' => $s->title, 'color' => $s->color ?: '#888888',
            'core' => in_array($s->title, $coreW, true) ? 1 : 0,
            'used' => (int) Capsule::table('tbltickets')->where('status', $s->title)->count()];
    }
    out(['depts' => $depsW, 'statuses' => $statW]);

case 'wh_dept_save':
    $nm = mb_substr(trim($in['name'] ?? ''), 0, 100);
    if ($nm === '') { fail('Δώσε όνομα τμήματος'); }
    $em = filter_var(trim($in['email'] ?? ''), FILTER_VALIDATE_EMAIL) ? trim($in['email']) : '';
    $did = (int) ($in['id'] ?? 0);
    if ($did) {
        Capsule::table('tblticketdepartments')->where('id', $did)->update(['name' => $nm, 'email' => $em]);
    } else {
        $ord = (int) Capsule::table('tblticketdepartments')->max('order') + 1;
        Capsule::table('tblticketdepartments')->insert(['name' => $nm, 'email' => $em, 'order' => $ord,
            'clientsonly' => '', 'piperepliesonly' => '', 'noautoresponder' => '', 'hidden' => '',
            'host' => '', 'port' => '', 'login' => '', 'password' => '']);
    }
    out(['ok' => true]);

case 'wh_dept_del':
    $did = (int) ($in['id'] ?? 0);
    if (Capsule::table('tbltickets')->where('did', $did)->exists()) {
        fail('Το τμήμα έχει tickets — μετακίνησέ τα πρώτα ή κρύψ\' το', 409);
    }
    Capsule::table('tblticketdepartments')->where('id', $did)->delete();
    out(['ok' => true]);

case 'wh_tstatus_save':
    $ti = mb_substr(trim($in['title'] ?? ''), 0, 60);
    if ($ti === '') { fail('Δώσε τίτλο status'); }
    $col = preg_match('/^#[0-9a-fA-F]{6}$/', $in['color'] ?? '') ? $in['color'] : '#888888';
    $sid = (int) ($in['id'] ?? 0);
    if ($sid) {
        $old = Capsule::table('tblticketstatuses')->where('id', $sid)->value('title');
        // αν αλλάζει ο τίτλος, μετονόμασε και στα tickets ώστε να μη «χαθούν»
        if ($old && $old !== $ti) {
            Capsule::table('tbltickets')->where('status', $old)->update(['status' => $ti]);
        }
        Capsule::table('tblticketstatuses')->where('id', $sid)->update(['title' => $ti, 'color' => $col]);
    } else {
        $ord = (int) Capsule::table('tblticketstatuses')->max('sortorder') + 1;
        Capsule::table('tblticketstatuses')->insert(['title' => $ti, 'color' => $col, 'sortorder' => $ord,
            'showactive' => 1, 'showawaiting' => 0, 'autoclose' => 0]);
    }
    out(['ok' => true]);

case 'wh_tstatus_del':
    $sid = (int) ($in['id'] ?? 0);
    $st = Capsule::table('tblticketstatuses')->where('id', $sid)->first();
    if (!$st) { fail('status'); }
    if (in_array($st->title, ['Open', 'Answered', 'Customer-Reply', 'Closed'], true)) {
        fail('Βασικό status του WHMCS — δεν διαγράφεται', 409);
    }
    if (Capsule::table('tbltickets')->where('status', $st->title)->exists()) {
        fail('Υπάρχουν tickets με αυτό το status — άλλαξέ τα πρώτα', 409);
    }
    Capsule::table('tblticketstatuses')->where('id', $sid)->delete();
    out(['ok' => true]);

/* ═══════ CRM Tasks / Δραστηριότητες ανά lead ═══════ */
case 'lead_tasks':
    $lid = (int) ($_GET['lead'] ?? $in['lead'] ?? 0);
    $rows = Capsule::table('mod_cpm_lead_tasks')->where('lead_id', $lid)
        ->orderBy('done')->orderByRaw('due_date IS NULL, due_date ASC')->orderByDesc('id')->get();
    $out = [];
    foreach ($rows as $t) {
        $out[] = ['id' => (int) $t->id, 'title' => $t->title, 'kind' => $t->kind,
            'due' => $t->due_date, 'assignee' => $t->assignee ? (int) $t->assignee : null,
            'who' => $t->assignee ? Db::adminName((int) $t->assignee) : null,
            'done' => (bool) $t->done];
    }
    out(['tasks' => $out]);

case 'lead_task_save':
    $lid = (int) ($in['lead'] ?? 0);
    $title = mb_substr(trim($in['title'] ?? ''), 0, 200);
    if (!$lid || $title === '') { fail('input'); }
    $data = ['title' => $title,
        'kind' => in_array($in['kind'] ?? '', ['call', 'email', 'meeting', 'todo'], true) ? $in['kind'] : 'todo',
        'due_date' => preg_match('/^\d{4}-\d{2}-\d{2}$/', $in['due'] ?? '') ? $in['due'] : null,
        'assignee' => (int) ($in['assignee'] ?? 0) ?: null];
    $tid = (int) ($in['id'] ?? 0);
    if ($tid) {
        Capsule::table('mod_cpm_lead_tasks')->where('id', $tid)->update($data);
    } else {
        $data['lead_id'] = $lid; $data['created_by'] = $adminId; $data['created_at'] = date('Y-m-d H:i:s');
        Capsule::table('mod_cpm_lead_tasks')->insert($data);
    }
    out(['ok' => true]);

case 'lead_task_toggle':
    $tid = (int) ($in['id'] ?? 0);
    $t = Capsule::table('mod_cpm_lead_tasks')->where('id', $tid)->first();
    if (!$t) { fail('task'); }
    $nd = $t->done ? 0 : 1;
    Capsule::table('mod_cpm_lead_tasks')->where('id', $tid)
        ->update(['done' => $nd, 'done_at' => $nd ? date('Y-m-d H:i:s') : null]);
    out(['ok' => true, 'done' => (bool) $nd]);

case 'lead_task_del':
    Capsule::table('mod_cpm_lead_tasks')->where('id', (int) ($in['id'] ?? 0))->delete();
    out(['ok' => true]);

/* ============ 🔐 ΘΥΡΙΔΑ ΚΩΔΙΚΩΝ (ανά χειριστή· admin βλέπει όλα) ============ */
case 'vault_list':
    $kinds = cnp_vault_kinds();
    $mine = !empty($_GET['mine']) || !$FULL;
    $q = Capsule::table('mod_cpm_vault');
    if (!$FULL) {
        // Περιορισμένος χειριστής: ΠΑΝΤΑ δικά του Ή κοινά (ομάδας) — ποτέ ιδιωτικά άλλων.
        $q->where(function ($w) use ($adminId) { $w->where('admin_id', $adminId)->orWhere('shared', 1); });
    } elseif ($mine) {
        // Πλήρης διαχειριστής + «Μόνο δικά μου»: ΑΥΣΤΗΡΑ δικά του — όχι κοινόχρηστα άλλων,
        // αλλιώς αν όλες οι καταχωρήσεις είναι κοινές το φίλτρο δεν άλλαζε τίποτα.
        $q->where('admin_id', $adminId);
    }
    $rows = $q->orderBy('descr')->get();
    $cids = array_values(array_filter($rows->pluck('client_id')->all()));
    $cmap = [];
    if ($cids) {
        foreach (Capsule::table('tblclients')->whereIn('id', $cids)->get(['id', 'companyname', 'firstname', 'lastname']) as $c) {
            $cmap[(int) $c->id] = $c->companyname ?: trim($c->firstname . ' ' . $c->lastname);
        }
    }
    $items = [];
    foreach ($rows as $r) {
        $items[] = ['id' => (int) $r->id, 'descr' => $r->descr, 'kind' => $r->kind, 'kindLbl' => $kinds[$r->kind] ?? $r->kind,
            'username' => $r->username, 'ips' => $r->ips, 'url' => $r->url, 'location' => $r->location,
            'clientId' => $r->client_id ? (int) $r->client_id : null,
            'clientName' => $r->client_id ? ($cmap[(int) $r->client_id] ?? ('#' . $r->client_id)) : null,
            'purpose' => $r->purpose, 'shared' => (bool) $r->shared, 'owner' => (int) $r->admin_id,
            'ownerName' => Db::adminName($r->admin_id), 'canEdit' => ((int) $r->admin_id === $adminId || $FULL),
            'updated' => $r->updated_at];
    }
    out(['items' => $items, 'kinds' => $kinds, 'full' => $FULL, 'me' => $adminId, 'mine' => $mine]);

case 'vault_save':
    $descr = mb_substr(trim($in['descr'] ?? ''), 0, 150);
    if ($descr === '') { fail('Δώσε περιγραφή'); }
    // ο τύπος είναι ελεύθερο κείμενο (προτάσεις + custom, π.χ. «SoftOne», «Microsoft 365»)
    $kind = mb_substr(trim($in['kind'] ?? ''), 0, 40) ?: 'Άλλο';
    $data = ['descr' => $descr, 'kind' => $kind, 'username' => mb_substr(trim($in['username'] ?? ''), 0, 150),
        'ips' => mb_substr(trim($in['ips'] ?? ''), 0, 300), 'url' => mb_substr(trim($in['url'] ?? ''), 0, 300),
        'location' => mb_substr(trim($in['location'] ?? ''), 0, 150),
        'client_id' => (int) ($in['client'] ?? 0) ?: null, 'purpose' => mb_substr(trim($in['purpose'] ?? ''), 0, 200),
        'shared' => !empty($in['shared']) ? 1 : 0, 'updated_at' => date('Y-m-d H:i:s')];
    $pass = (string) ($in['password'] ?? '');
    $id = (int) ($in['id'] ?? 0);
    if ($id) {
        $own = (int) Capsule::table('mod_cpm_vault')->where('id', $id)->value('admin_id');
        if (!$own) { fail('notfound', 404); }
        if ($own !== $adminId && !$FULL) { fail('forbidden', 403); }
        if ($pass !== '') { $data['password_enc'] = cnp_vault_enc($pass); }  // αλλαγή κωδικού μόνο αν δόθηκε νέος
        Capsule::table('mod_cpm_vault')->where('id', $id)->update($data);
    } else {
        $data['admin_id'] = $adminId; $data['password_enc'] = cnp_vault_enc($pass); $data['created_at'] = date('Y-m-d H:i:s');
        $id = Capsule::table('mod_cpm_vault')->insertGetId($data);
    }
    out(['ok' => true, 'id' => $id]);

case 'vault_reveal':                     // αποκάλυψη κωδικού on-demand (owner, full, ή κοινό)
    $id = (int) ($in['id'] ?? $_GET['id'] ?? 0);
    $r = Capsule::table('mod_cpm_vault')->where('id', $id)->first();
    if (!$r) { fail('notfound', 404); }
    if ((int) $r->admin_id !== $adminId && !$FULL && !$r->shared) { fail('forbidden', 403); }
    out(['password' => cnp_vault_dec($r->password_enc)]);

case 'vault_del':
    $id = (int) ($in['id'] ?? 0);
    $r = Capsule::table('mod_cpm_vault')->where('id', $id)->first();
    if ($r && ((int) $r->admin_id === $adminId || $FULL)) { Capsule::table('mod_cpm_vault')->where('id', $id)->delete(); }
    out(['ok' => true]);

/* ============ 📚 ΒΙΒΛΙΟΘΗΚΗ ΧΕΙΡΙΣΤΗ (ιδιωτική· έγγραφα/σημειώσεις/links) ============ */
case 'lib_list':
    $q = trim($_GET['q'] ?? '');
    $cat = trim($_GET['cat'] ?? '');
    $scope = ($_GET['scope'] ?? 'mine') === 'shared' ? 'shared' : 'mine';
    $qry = Capsule::table('mod_cpm_library');
    if ($scope === 'shared') { $qry->where('shared', 1); }
    else { $qry->where('admin_id', $adminId); }
    if ($cat !== '') { $qry->where('category', $cat); }
    if (mb_strlen($q) >= 1) {
        $like = '%' . $q . '%';
        $qry->where(function ($w) use ($like) {
            $w->where('title', 'like', $like)->orWhere('body', 'like', $like)->orWhere('tags', 'like', $like)
              ->orWhere('category', 'like', $like)->orWhere('url', 'like', $like)->orWhere('filename', 'like', $like);
        });
    }
    $rows = $qry->orderByDesc('pinned')->orderByDesc('updated_at')->get();
    $items = []; $today = date('Y-m-d');
    foreach ($rows as $r) {
        $expDays = $r->expires_at ? (int) floor((strtotime($r->expires_at) - strtotime($today)) / 86400) : null;
        $items[] = ['id' => (int) $r->id, 'kind' => $r->kind, 'title' => $r->title, 'category' => $r->category,
            'tags' => $r->tags, 'body' => $r->kind === 'note' ? $r->body : '', 'url' => $r->url,
            'filename' => $r->filename, 'size' => (int) $r->size, 'pinned' => (bool) $r->pinned,
            'expires' => $r->expires_at, 'expDays' => $expDays, 'shared' => (bool) $r->shared,
            'owner' => (int) $r->admin_id, 'ownerName' => Db::adminName($r->admin_id), 'canEdit' => ((int) $r->admin_id === $adminId),
            'updated' => $r->updated_at];
    }
    $catQ = Capsule::table('mod_cpm_library');
    if ($scope === 'shared') { $catQ->where('shared', 1); } else { $catQ->where('admin_id', $adminId); }
    $cats = $catQ->where('category', '<>', '')->distinct()->orderBy('category')->pluck('category')->all();
    // πλήθος shared (για badge στο toggle)
    $sharedN = (int) Capsule::table('mod_cpm_library')->where('shared', 1)->count();
    out(['items' => $items, 'cats' => $cats, 'scope' => $scope, 'sharedN' => $sharedN]);

case 'lib_save':
    $title = mb_substr(trim($in['title'] ?? ''), 0, 200);
    if ($title === '') { fail('Δώσε τίτλο'); }
    $id = (int) ($in['id'] ?? 0);
    $existing = $id ? Capsule::table('mod_cpm_library')->where('id', $id)->first() : null;
    if ($id && (!$existing || (int) $existing->admin_id !== $adminId)) { fail('forbidden', 403); }
    $kind = $existing ? $existing->kind : (in_array($in['kind'] ?? '', ['note', 'link'], true) ? $in['kind'] : 'note');
    $data = ['title' => $title, 'category' => mb_substr(trim($in['category'] ?? ''), 0, 80),
        'tags' => mb_substr(trim($in['tags'] ?? ''), 0, 200),
        'expires_at' => ($in['expires'] ?? '') ?: null, 'shared' => !empty($in['shared']) ? 1 : 0,
        'exp_notified' => 0, 'updated_at' => date('Y-m-d H:i:s')];
    if ($kind === 'note') { $data['body'] = cnp_clean_html($in['body'] ?? ''); }
    if ($kind === 'link') { $data['url'] = mb_substr(trim($in['url'] ?? ''), 0, 500); }
    if ($id) {
        Capsule::table('mod_cpm_library')->where('id', $id)->update($data);
    } else {
        $data['kind'] = $kind; $data['admin_id'] = $adminId; $data['created_at'] = date('Y-m-d H:i:s');
        $id = Capsule::table('mod_cpm_library')->insertGetId($data);
    }
    out(['ok' => true, 'id' => $id]);

case 'lib_upload':                       // multipart
    $f = $_FILES['file'] ?? null;
    if (!$f || $f['error'] !== UPLOAD_ERR_OK) { fail('upload'); }
    if ($f['size'] > 25 * 1024 * 1024) { fail('Μέγιστο 25MB'); }
    $ext = strtolower(pathinfo($f['name'], PATHINFO_EXTENSION));
    if (in_array($ext, ['php', 'phtml', 'phar', 'cgi', 'sh', 'exe', 'htaccess'], true)) { fail('Μη επιτρεπτός τύπος'); }
    $dir = __DIR__ . '/../attachments/cloudonprojects';
    if (!is_dir($dir)) { @mkdir($dir, 0750, true); }
    $stored = uniqid('lib', true) . '.dat';
    if (!move_uploaded_file($f['tmp_name'], $dir . '/' . $stored)) { fail('write'); }
    Capsule::table('mod_cpm_library')->insert(['admin_id' => $adminId, 'kind' => 'file',
        'title' => mb_substr(($_POST['title'] ?? '') ?: $f['name'], 0, 200), 'category' => mb_substr(trim($_POST['category'] ?? ''), 0, 80),
        'tags' => mb_substr(trim($_POST['tags'] ?? ''), 0, 200), 'filename' => mb_substr($f['name'], 0, 200),
        'stored' => $stored, 'size' => (int) $f['size'], 'expires_at' => ($_POST['expires'] ?? '') ?: null,
        'shared' => !empty($_POST['shared']) ? 1 : 0, 'created_at' => date('Y-m-d H:i:s'), 'updated_at' => date('Y-m-d H:i:s')]);
    out(['ok' => true]);

case 'manual_img':                       // εικόνες οδηγού (μόνο για συνδεδεμένους — protected)
    $f = preg_replace('/[^a-z0-9_]/i', '', $_GET['f'] ?? '');
    $path = __DIR__ . '/manual-src/manual_' . $f . '.png';
    if ($f === '' || !is_file($path)) { fail('img', 404); }
    header('Content-Type: image/png');
    header('X-Content-Type-Options: nosniff');
    header('Cache-Control: private, max-age=86400');
    header('Content-Length: ' . filesize($path));
    readfile($path);
    exit;

case 'lib_get':
    $r = Capsule::table('mod_cpm_library')->where('id', (int) ($_GET['id'] ?? 0))->first();
    if (!$r || $r->kind !== 'file' || ((int) $r->admin_id !== $adminId && !$r->shared)) { fail('file', 404); }
    $path = realpath(__DIR__ . '/../attachments/cloudonprojects/' . basename($r->stored));
    if (!$path || !is_file($path)) { fail('file', 404); }
    header('Content-Type: application/octet-stream');
    header('X-Content-Type-Options: nosniff');
    header('Content-Disposition: attachment; filename="' . rawurlencode($r->filename) . '"');
    header('Content-Length: ' . filesize($path));
    readfile($path);
    exit;

case 'lib_pin':
    $r = Capsule::table('mod_cpm_library')->where('id', (int) ($in['id'] ?? 0))->where('admin_id', $adminId)->first();
    if ($r) { Capsule::table('mod_cpm_library')->where('id', $r->id)->update(['pinned' => $r->pinned ? 0 : 1]); }
    out(['ok' => true]);

case 'lib_del':
    $r = Capsule::table('mod_cpm_library')->where('id', (int) ($in['id'] ?? 0))->where('admin_id', $adminId)->first();
    if ($r) {
        if ($r->stored) { @unlink(__DIR__ . '/../attachments/cloudonprojects/' . basename($r->stored)); }
        Capsule::table('mod_cpm_library')->where('id', $r->id)->delete();
    }
    out(['ok' => true]);

/* ============ ✅ ΠΛΑΝΟ ΧΕΙΡΙΣΤΗ ανά project («πού έμεινα») ============ */
case 'todos_list':
    $doneIds = Capsule::table('mod_cpm_statuses')->where('is_done', 1)->pluck('id')->all() ?: [0];
    /* ΜΠΑΛΑ, ΟΧΙ ΑΝΑΘΕΣΗ. Εδώ ο Βάκρινος έβλεπε εργασίες που τις τρέχει άλλος. */
    $myOpenTasks = cnp_scope_mine(
        Capsule::table('mod_cpm_tasks as t')->leftJoin('mod_cpm_projects as p', 'p.id', '=', 't.project_id')
            ->whereNotIn('t.status_id', $doneIds), $adminId, 't.')
        ->select('t.id', 't.title', 't.project_id', 'p.name as pname', 'p.color as pcolor')->get();
    $todoRows = Capsule::table('mod_cpm_todos')->where('admin_id', $adminId)->orderBy('done')->orderBy('sort')->orderBy('id')->get();
    $noteRows = Capsule::table('mod_cpm_worknote')->where('admin_id', $adminId)->get()->keyBy('project_id');
    $proj = [];
    $ensure = function ($pid, $pname, $pcolor) use (&$proj, $noteRows) {
        if (!isset($proj[$pid])) {
            $proj[$pid] = ['id' => $pid, 'name' => $pname, 'color' => $pcolor, 'tasks' => [], 'todos' => [],
                'note' => isset($noteRows[$pid]) ? $noteRows[$pid]->note : ''];
        }
    };
    foreach ($myOpenTasks as $t) {
        // project_id 0 = εργασίες χωρίς έργο· μπαίνουν σε δική τους ομάδα.
        $pk = (int) $t->project_id;
        $ensure($pk, cnp_pn($t->pname), $t->pcolor ?: '#8595ac');
        $proj[$pk]['tasks'][] = ['id' => (int) $t->id, 'title' => $t->title];
    }
    $needNames = [];
    foreach ($todoRows as $t) { if ($t->project_id && !isset($proj[(int) $t->project_id])) { $needNames[(int) $t->project_id] = 1; } }
    foreach ($noteRows as $pid => $n) { if ($pid && !isset($proj[$pid])) { $needNames[$pid] = 1; } }
    if ($needNames) {
        foreach (Capsule::table('mod_cpm_projects')->whereIn('id', array_keys($needNames))->get(['id', 'name', 'color']) as $p) {
            $ensure((int) $p->id, $p->name, $p->color);
        }
    }
    foreach ($todoRows as $t) {
        $pid = (int) $t->project_id;
        if (!isset($proj[$pid])) { $ensure($pid, $pid ? '—' : 'Γενικά', '#8291a9'); }
        $proj[$pid]['todos'][] = ['id' => (int) $t->id, 'text' => $t->text, 'done' => (bool) $t->done,
            'remind' => $t->remind_at, 'overdue' => $t->remind_at && !$t->done && strtotime($t->remind_at) < time()];
    }
    // «Γενικά» πάντα διαθέσιμο για ελεύθερες σημειώσεις
    if (!isset($proj[0]) && !$todoRows->count()) { $ensure(0, 'Γενικά', '#8291a9'); }
    $groups = array_values($proj);
    usort($groups, function ($a, $b) {
        if ($a['id'] === 0) { return 1; }
        if ($b['id'] === 0) { return -1; }
        $ao = count($a['tasks']); $bo = count($b['tasks']);
        if ($ao !== $bo) { return $bo <=> $ao; }
        return strcmp($a['name'], $b['name']);
    });

    /* ── Επίπεδη λίστα: αυτό διαβάζει η to-do οθόνη ──
       Το έργο είναι ετικέτα, όχι φάκελος. Γράφεις πρώτα τι έχεις να κάνεις και
       το χρεώνεις σε έργο μόνο αν χρειάζεται. */
    $items = [];
    foreach ($todoRows as $t) {
        $pid = (int) $t->project_id;
        $items[] = ['id' => (int) $t->id, 'text' => $t->text, 'done' => (bool) $t->done,
            'project' => $pid, 'pname' => $pid ? ($proj[$pid]['name'] ?? '—') : null,
            'pcolor' => $pid ? ($proj[$pid]['color'] ?? '#8595ac') : null,
            'remind' => $t->remind_at, 'sort' => (int) $t->sort,
            'doneAt' => $t->done_at, 'createdAt' => $t->created_at];
    }
    /* Οι σημειώσεις «πού έμεινα» δεν χάνονται: βγαίνουν χωριστά, για να
       φαίνονται πάνω από τη λίστα χωρίς να την πνίγουν. */
    $notes = [];
    foreach ($noteRows as $pid => $nr) {
        $txt = trim(strip_tags(str_replace(['<br>', '<br/>', '<br />'], "\n", (string) $nr->note)));
        if ($txt === '') { continue; }
        $notes[] = ['project' => (int) $pid, 'name' => $pid ? ($proj[$pid]['name'] ?? '—') : 'Γενικά',
            'color' => $pid ? ($proj[$pid]['color'] ?? '#8595ac') : '#8291a9',
            'note' => $txt, 'at' => $nr->updated_at];
    }
    /* Τα ανοιχτά μου tasks που ΔΕΝ είναι ήδη στη λίστα — για το «φέρε τα tasks μου». */
    $have = array_map('mb_strtolower', array_column($items, 'text'));
    $free = [];
    foreach ($myOpenTasks as $t) {
        if (in_array(mb_strtolower($t->title), $have, true)) { continue; }
        $free[] = ['id' => (int) $t->id, 'title' => $t->title, 'project' => (int) $t->project_id,
            'pname' => cnp_pn($t->pname), 'pcolor' => $t->pcolor ?: '#8595ac'];
    }
    /* Λίστα έργων για το πεδίο επιλογής: όσα με αφορούν. */
    $pick = [];
    foreach ($groups as $g) {
        if ($g['id']) { $pick[] = ['id' => $g['id'], 'name' => $g['name'], 'color' => $g['color']]; }
    }
    out(['groups' => $groups, 'items' => $items, 'notes' => $notes, 'tasks' => $free, 'projects' => $pick]);

case 'todo_add':
    $text = mb_substr(trim($in['text'] ?? ''), 0, 300);
    if ($text === '') { fail('empty'); }
    $remind = ($in['remind'] ?? '') ? date('Y-m-d H:i:s', strtotime($in['remind'])) : null;
    $sort = (int) Capsule::table('mod_cpm_todos')->where('admin_id', $adminId)->where('project_id', (int) ($in['project'] ?? 0))->max('sort') + 1;
    $id = Capsule::table('mod_cpm_todos')->insertGetId(['admin_id' => $adminId, 'project_id' => (int) ($in['project'] ?? 0),
        'text' => $text, 'sort' => $sort, 'remind_at' => $remind, 'remind_sent' => 0, 'created_at' => date('Y-m-d H:i:s')]);
    out(['ok' => true, 'id' => $id]);

case 'todo_update':                      // επεξεργασία κειμένου/υπενθύμισης
    $r = Capsule::table('mod_cpm_todos')->where('id', (int) ($in['id'] ?? 0))->where('admin_id', $adminId)->first();
    if (!$r) { fail('notfound', 404); }
    $upd = [];
    if (isset($in['text']) && trim($in['text']) !== '') { $upd['text'] = mb_substr(trim($in['text']), 0, 300); }
    if (array_key_exists('remind', $in)) {
        $upd['remind_at'] = $in['remind'] ? date('Y-m-d H:i:s', strtotime($in['remind'])) : null;
        $upd['remind_sent'] = 0;
    }
    if (array_key_exists('project', $in)) {
        $np = (int) $in['project'];
        $upd['project_id'] = ($np && Capsule::table('mod_cpm_projects')->where('id', $np)->exists()) ? $np : 0;
    }
    if ($upd) { Capsule::table('mod_cpm_todos')->where('id', $r->id)->update($upd); }
    out(['ok' => true]);

case 'todo_reorder':                     // νέα σειρά (drag) — λίστα ids
    $ids = $in['ids'] ?? [];
    foreach ($ids as $i => $tid) {
        Capsule::table('mod_cpm_todos')->where('id', (int) $tid)->where('admin_id', $adminId)->update(['sort' => $i + 1]);
    }
    out(['ok' => true]);

case 'my_todos':                         // «Η μέρα μου»: τα ανοιχτά μου todos (flat)
    $doneIds = Capsule::table('mod_cpm_statuses')->where('is_done', 1)->pluck('id')->all() ?: [0];
    $rows = Capsule::table('mod_cpm_todos')->where('admin_id', $adminId)->where('done', 0)->orderBy('project_id')->orderBy('sort')->orderBy('id')->get();
    $pnames = [];
    $pids = array_values(array_filter(array_unique($rows->pluck('project_id')->all())));
    if ($pids) {
        foreach (Capsule::table('mod_cpm_projects')->whereIn('id', $pids)->get(['id', 'name', 'color']) as $p) {
            $pnames[(int) $p->id] = ['name' => $p->name, 'color' => $p->color];
        }
    }
    $todos = [];
    foreach ($rows as $t) {
        $pid = (int) $t->project_id;
        $todos[] = ['id' => (int) $t->id, 'text' => $t->text, 'project' => $pid,
            'pname' => $pid ? ($pnames[$pid]['name'] ?? '—') : 'Γενικά', 'pcolor' => $pid ? ($pnames[$pid]['color'] ?? '#8291a9') : '#8291a9',
            'remind' => $t->remind_at, 'overdue' => $t->remind_at && strtotime($t->remind_at) < time()];
    }
    out(['todos' => $todos]);

case 'todo_toggle':
    $r = Capsule::table('mod_cpm_todos')->where('id', (int) ($in['id'] ?? 0))->where('admin_id', $adminId)->first();
    if ($r) { Capsule::table('mod_cpm_todos')->where('id', $r->id)->update(['done' => $r->done ? 0 : 1, 'done_at' => $r->done ? null : date('Y-m-d H:i:s')]); }
    out(['ok' => true]);

case 'todo_del':
    Capsule::table('mod_cpm_todos')->where('id', (int) ($in['id'] ?? 0))->where('admin_id', $adminId)->delete();
    out(['ok' => true]);

case 'todo_clear_done':
    $q9 = Capsule::table('mod_cpm_todos')->where('admin_id', $adminId)->where('done', 1);
    if (empty($in['all'])) { $q9->where('project_id', (int) ($in['project'] ?? 0)); }
    out(['ok' => true, 'removed' => $q9->delete()]);

case 'todo_seed':                        // φέρε τα ανοιχτά μου tasks μέσα στη λίστα
    /* `tasks` = συγκεκριμένα id (από την to-do οθόνη), `project` = όλα ενός έργου
       (από την προβολή ανά έργο). Και στις δύο περιπτώσεις τα ήδη γραμμένα
       παραλείπονται, ώστε το κουμπί να πατιέται ξανά χωρίς διπλότυπα. */
    $doneIds = Capsule::table('mod_cpm_statuses')->where('is_done', 1)->pluck('id')->all() ?: [0];
    $existing = array_map('mb_strtolower',
        Capsule::table('mod_cpm_todos')->where('admin_id', $adminId)->pluck('text')->all());
    $q9 = cnp_scope_mine(
        Capsule::table('mod_cpm_tasks')->whereNotIn('status_id', $doneIds), $adminId);
    $wanted = array_values(array_filter(array_map('intval', (array) ($in['tasks'] ?? []))));
    if ($wanted) {
        $q9->whereIn('id', $wanted);
    } else {
        $q9->where('project_id', (int) ($in['project'] ?? 0));
    }
    $added = 0;
    foreach ($q9->get(['id', 'title', 'project_id']) as $t) {
        if (in_array(mb_strtolower($t->title), $existing, true)) { continue; }
        $existing[] = mb_strtolower($t->title);
        Capsule::table('mod_cpm_todos')->insert(['admin_id' => $adminId,
            'project_id' => (int) $t->project_id, 'text' => mb_substr($t->title, 0, 300),
            'created_at' => date('Y-m-d H:i:s')]);
        $added++;
    }
    out(['ok' => true, 'added' => $added]);

case 'worknote_save':
    $pid = (int) ($in['project'] ?? 0);
    $note = cnp_clean_html($in['note'] ?? '');
    $ex = Capsule::table('mod_cpm_worknote')->where('admin_id', $adminId)->where('project_id', $pid)->first();
    if ($ex) { Capsule::table('mod_cpm_worknote')->where('id', $ex->id)->update(['note' => $note, 'updated_at' => date('Y-m-d H:i:s')]); }
    else { Capsule::table('mod_cpm_worknote')->insert(['admin_id' => $adminId, 'project_id' => $pid, 'note' => $note, 'updated_at' => date('Y-m-d H:i:s')]); }
    out(['ok' => true]);

/* ============ 🧑‍💼 ΠΡΟΣΛΗΨΕΙΣ / ΒΙΟΓΡΑΦΙΚΑ (ειδικότητα hr) ============ */
case 'cv_jobs':
    $jobs = [];
    foreach (Capsule::table('mod_cpm_cv_jobs')->orderByDesc('active')->orderBy('title')->get() as $jb) {
        $jobs[] = ['id' => (int) $jb->id, 'title' => $jb->title, 'active' => (bool) $jb->active,
            'descr' => $jb->descr, 'skills' => $jb->skills, 'location' => $jb->location, 'emptype' => $jb->emptype,
            'titleEn' => $jb->title_en, 'descrEn' => $jb->descr_en, 'skillsEn' => $jb->skills_en, 'emptypeEn' => $jb->emptype_en,
            'image' => (string) ($jb->image ?? ''), 'imageResolved' => cnp_cv_job_image($jb),
            'sections' => $jb->descr_json ? json_decode($jb->descr_json, true) : null,
            'count' => (int) Capsule::table('mod_cpm_cv')->where('job_id', $jb->id)->count()];
    }
    out(['jobs' => $jobs, 'statuses' => cnp_cv_statuses(), 'models' => cnp_cv_models(), 'defaultModel' => cnp_cv_default_model(),
        'imagePresets' => cnp_cv_job_presets(), 'imageBase' => 'apply-assets/jobs/',
        'customImages' => cnp_cv_job_custom_list(),
        'applyUrl' => 'https://my.cloudon.gr/project/apply.php']);

/* ================= ΑΝΟΙΧΤΑ ΥΠΟΛΟΙΠΑ & ΥΠΕΝΘΥΜΙΣΕΙΣ ΕΞΟΦΛΗΣΗΣ =================
   Η οθόνη «Αναστολές» ξεκινά από την υπηρεσία που πρέπει να πέσει. Εδώ ξεκινάμε
   από τον ΠΕΛΑΤΗ και το τι χρωστά — και το εργαλείο είναι μια ευγενική υπενθύμιση,
   ΠΡΙΝ φτάσουμε στην αναστολή. Ίδια αριθμητική με τις Αναστολές (cnp_open_balances). */
case 'balances':
    $graceB = (int) (Capsule::table('tblconfiguration')->where('setting', 'AutoSuspensionDays')->value('value') ?: 10);
    $bal = cnp_open_balances();
    if (!$bal) { out(['rows' => [], 'grace' => $graceB, 'sum' => ['clients' => 0, 'open' => 0, 'overdue' => 0, 'risk' => 0, 'notDue' => 0]]); }
    $cids = array_keys($bal);
    $clients = [];
    foreach (Capsule::table('tblclients')->whereIn('id', $cids)->get(['id', 'firstname', 'lastname', 'companyname', 'email', 'language', 'country', 'status']) as $c) {
        $clients[(int) $c->id] = $c;
    }
    /* Τελευταία υπενθύμιση & τελευταία ειδοποίηση αναστολής ανά πελάτη. */
    $lastRem = [];
    foreach (Capsule::table('mod_cpm_pay_reminders')->whereIn('client_id', $cids)->orderBy('id')->get() as $r) {
        $lastRem[(int) $r->client_id] = ['at' => $r->created_at, 'by' => Db::adminName((int) $r->admin_id),
            'channel' => (string) $r->channel, 'amount' => (float) $r->amount, 'ticket' => (int) $r->ticket_id];
    }
    $lastNot = [];
    foreach (Capsule::table('mod_cpm_suspend_notices')->whereIn('client_id', $cids)->orderBy('id')->get() as $n) {
        $lastNot[(int) $n->client_id] = ['at' => $n->created_at, 'date' => $n->suspend_date, 'by' => Db::adminName((int) $n->admin_id)];
    }
    /* Υπηρεσίες σε κίνδυνο: ενεργές υπηρεσίες του πελάτη με module (το WHMCS τις
       αναστέλλει μόνο του) ή με ληγμένη επόμενη πληρωμή. */
    $svcBy = [];
    foreach (Capsule::table('tblhosting as h')->join('tblproducts as p', 'p.id', '=', 'h.packageid')
                 ->whereIn('h.userid', $cids)->whereIn('h.domainstatus', ['Active', 'Suspended'])
                 ->get(['h.id', 'h.userid', 'h.domain', 'h.domainstatus', 'h.nextduedate', 'h.amount', 'h.billingcycle',
                     'h.overideautosuspend', 'h.overidesuspenduntil', 'p.name as pname', 'p.servertype']) as $h) {
        $exempt = !empty($h->overideautosuspend) && ((string) $h->overidesuspenduntil === '' || strpos((string) $h->overidesuspenduntil, '0000') === 0
            || strtotime((string) $h->overidesuspenduntil) >= strtotime('today'));
        $svcBy[(int) $h->userid][] = ['id' => (int) $h->id, 'label' => (string) ($h->domain ?: $h->pname), 'product' => (string) $h->pname,
            'status' => (string) $h->domainstatus, 'auto' => (string) $h->servertype !== '', 'module' => (string) $h->servertype,
            'nextDue' => (string) $h->nextduedate, 'amount' => (float) $h->amount, 'cycle' => (string) $h->billingcycle, 'exempt' => $exempt];
    }
    $rows = [];
    $sumRisk = 0; $sumNotDue = 0;
    foreach ($bal as $c => $b) {
        $cl = $clients[$c] ?? null;
        $svcs = $svcBy[$c] ?? [];
        $active = array_values(array_filter($svcs, function ($x) { return $x['status'] === 'Active' && !$x['exempt']; }));
        $suspDate = $b['oldestDue'] ? date('Y-m-d', strtotime($b['oldestDue'] . ' +' . $graceB . ' days')) : null;
        $risk = $b['overdue'] > 0.5 && $active && $b['days'] >= max(0, $graceB - 5);   // κοντά ή πέρα από το όριο
        $rows[] = ['client' => $c, 'name' => html_entity_decode(clientLabel($c), ENT_QUOTES, 'UTF-8'), 'email' => $cl ? (string) $cl->email : '',
            'lang' => $cl ? cnp_client_lang($cl) : 'el', 'clientStatus' => $cl ? (string) $cl->status : '',
            'open' => $b['open'], 'overdue' => $b['overdue'], 'notDue' => round($b['open'] - $b['overdue'], 2),
            'days' => $b['days'], 'badDue' => $b['badDue'], 'ripe' => $b['days'] >= $graceB, 'risk' => $risk,
            'suspendDate' => $suspDate, 'invs' => $b['invs'], 'services' => $svcs,
            'activeServices' => count($active), 'autoServices' => count(array_filter($active, function ($x) { return $x['auto']; })),
            'reminded' => $lastRem[$c] ?? null, 'notified' => $lastNot[$c] ?? null,
            'adminUrl' => '/cloudonadminpanel/clientssummary.php?userid=' . $c];
        if ($risk) { $sumRisk++; }
        if ($b['overdue'] <= 0.5) { $sumNotDue++; }
    }
    /* Πρώτα όσοι κινδυνεύουν, μετά όσοι χρωστούν περισσότερα. */
    usort($rows, function ($a, $b) {
        return ($b['risk'] <=> $a['risk']) ?: ($b['overdue'] <=> $a['overdue']) ?: ($b['open'] <=> $a['open']);
    });
    out(['rows' => $rows, 'grace' => $graceB, 'sum' => ['clients' => count($rows),
        'open' => round(array_sum(array_column($rows, 'open')), 2),
        'overdue' => round(array_sum(array_column($rows, 'overdue')), 2),
        'risk' => $sumRisk, 'notDue' => $sumNotDue]]);

case 'balance_reminder':                 // σύνθεση υπενθύμισης εξόφλησης (πάγιο κείμενο ή AI)
    $cid = (int) ($in['client'] ?? 0);
    $cl = $cid ? Capsule::table('tblclients')->where('id', $cid)->first() : null;
    if (!$cl) { fail('client', 404); }
    $bal = cnp_open_balances($cid)[$cid] ?? null;
    if (!$bal) { fail('Ο πελάτης δεν έχει ανοιχτό υπόλοιπο'); }
    $pick = array_map('intval', (array) ($in['invoices'] ?? []));
    $invs = array_values(array_filter($bal['invs'], function ($x) use ($pick) { return !$pick || in_array($x['id'], $pick, true); }));
    if (!$invs) { fail('Δεν επιλέχθηκε παραστατικό'); }
    $graceB = (int) (Capsule::table('tblconfiguration')->where('setting', 'AutoSuspensionDays')->value('value') ?: 10);
    $lang = cnp_client_lang($cl, (string) ($in['lang'] ?? ''));
    $money = function ($v) { return number_format((float) $v, 2, ',', '.') . ' €'; };
    $name = trim(($cl->companyname ?: ($cl->firstname . ' ' . $cl->lastname)));
    $total = 0.0; $overdue = 0.0; $oldest = null;
    $invList = ''; $i9 = 0;
    foreach ($invs as $x) {
        $i9++; $total += $x['open'];
        if ($x['days'] > 0) { $overdue += $x['open']; if ($oldest === null || strtotime($x['due']) < strtotime($oldest)) { $oldest = $x['due']; } }
        $link = 'https://my.cloudon.gr/viewinvoice.php?id=' . $x['id'];
        if ($lang === 'el') {
            $late = $x['days'] > 0 ? ' · Καθυστέρηση: ' . $x['days'] . ($x['days'] === 1 ? ' ημέρα' : ' ημέρες') : ' · Δεν έχει λήξει ακόμη';
            $invList .= $i9 . ') Παραστατικό ' . $x['num'] . "\n   Έκδοση: " . cnp_d($x['issued']) . ' · Λήξη: ' . cnp_d($x['due']) . $late . "\n"
                . '   Αξία: ' . $money($x['gross']) . ($x['paid'] > 0.005 ? ' · Έχουν εξοφληθεί: ' . $money($x['paid']) : '')
                . ' · Υπόλοιπο: ' . $money($x['open']) . "\n   Προβολή & πληρωμή: " . $link . "\n";
        } else {
            $late = $x['days'] > 0 ? ' · Overdue by: ' . $x['days'] . ($x['days'] === 1 ? ' day' : ' days') : ' · Not yet due';
            $invList .= $i9 . ') Invoice ' . $x['num'] . "\n   Issued: " . cnp_d($x['issued']) . ' · Due: ' . cnp_d($x['due']) . $late . "\n"
                . '   Amount: ' . $money($x['gross']) . ($x['paid'] > 0.005 ? ' · Paid so far: ' . $money($x['paid']) : '')
                . ' · Outstanding: ' . $money($x['open']) . "\n   View & pay: " . $link . "\n";
        }
    }
    $invList .= ($lang === 'el' ? '   ΣΥΝΟΛΟ ΑΝΟΙΧΤΟΥ ΥΠΟΛΟΙΠΟΥ: ' : '   TOTAL OUTSTANDING: ') . $money($total) . "\n";
    $suspDate = $oldest ? date('Y-m-d', strtotime($oldest . ' +' . $graceB . ' days')) : null;
    $pastDue = $suspDate && strtotime($suspDate) < strtotime('today');   // το όριο έχει ήδη περάσει
    if ($pastDue) { $suspDate = date('Y-m-d'); }

    if ($lang === 'el') {
        $subject = 'Υπενθύμιση εξόφλησης — ανοιχτό υπόλοιπο ' . $money($total);
        $body = "Αγαπητοί συνεργάτες,\n\n"
            . "σας υπενθυμίζουμε ότι στον λογαριασμό σας υπάρχει ανοιχτό υπόλοιπο " . $money($total)
            . ($overdue > 0.5 && $overdue < $total - 0.5 ? ', εκ των οποίων ' . $money($overdue) . ' είναι ληξιπρόθεσμα' : '') . ".\n\n"
            . "ΑΝΑΛΥΣΗ ΠΑΡΑΣΤΑΤΙΚΩΝ\n" . $invList . "\n"
            . ($overdue > 0.5
                ? "Για να μη διακοπεί η λειτουργία των υπηρεσιών σας, παρακαλούμε να τακτοποιήσετε το ληξιπρόθεσμο υπόλοιπο "
                  . ($pastDue ? 'άμεσα, καθώς η προθεσμία εξόφλησης έχει ήδη παρέλθει. ' : ($suspDate ? 'έως τις ' . cnp_d($suspDate) . '. ' : 'το συντομότερο. '))
                  . ($pastDue ? "Οι υπηρεσίες που συνδέονται με τα παραπάνω παραστατικά μπορεί να τεθούν σε αναστολή ανά πάσα στιγμή.\n\n"
                      : "Μετά την ημερομηνία αυτή οι υπηρεσίες που συνδέονται με τα παραπάνω παραστατικά τίθενται αυτόματα σε αναστολή.\n\n")
                : "Η εξόφληση μέχρι την ημερομηνία λήξης εξασφαλίζει την αδιάλειπτη λειτουργία των υπηρεσιών σας.\n\n")
            . "Μπορείτε να δείτε και να εξοφλήσετε τα παραστατικά από τον λογαριασμό σας στο https://my.cloudon.gr "
            . "(τραπεζική κατάθεση, κάρτα ή PayPal).\n\n"
            . "Αν η πληρωμή έχει ήδη γίνει, παρακαλούμε αγνοήστε το μήνυμα ή στείλτε μας το αποδεικτικό για να το αντιστοιχίσουμε.\n";
    } else {
        $subject = 'Payment reminder — outstanding balance ' . $money($total);
        $body = "Dear partners,\n\n"
            . "this is a friendly reminder that your account has an outstanding balance of " . $money($total)
            . ($overdue > 0.5 && $overdue < $total - 0.5 ? ', of which ' . $money($overdue) . ' is overdue' : '') . ".\n\n"
            . "INVOICES — BREAKDOWN\n" . $invList . "\n"
            . ($overdue > 0.5
                ? "To avoid any interruption of your services, please settle the overdue balance "
                  . ($pastDue ? 'immediately, as the payment deadline has already passed. ' : ($suspDate ? 'by ' . cnp_d($suspDate) . '. ' : 'as soon as possible. '))
                  . ($pastDue ? "The services linked to the above invoices may be suspended at any time.\n\n"
                      : "After that date the services linked to the above invoices are automatically suspended.\n\n")
                : "Paying by the due date keeps your services running without interruption.\n\n")
            . "You can review and pay your invoices at https://my.cloudon.gr (bank transfer, card or PayPal).\n\n"
            . "If payment has already been made, please ignore this message or send us the receipt so we can allocate it.\n";
    }

    // ✨ AI: ίδια γεγονότα, καλύτερη διατύπωση — ποτέ δικά του νούμερα
    if (($in['mode'] ?? '') === 'ai') {
        $key = (string) (Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')->where('setting', 'ai_api_key')->value('value') ?: '');
        if ($key === '') { fail('Δεν έχει οριστεί AI API key — βάλ\' το στις Ρυθμίσεις'); }
        $draft = trim((string) ($in['draft'] ?? ''));
        $prompt = "Είσαι υπεύθυνος λογιστηρίου ελληνικής εταιρείας IT/hosting (CloudOn). Γράψε μια ΕΥΓΕΝΙΚΗ υπενθύμιση "
            . "εξόφλησης προς πελάτη — συνεργάτη, όχι οφειλέτη. Στόχος: να πληρώσει έγκαιρα ώστε να μη διακοπούν οι υπηρεσίες του.\n\n"
            . "ΓΛΩΣΣΑ: " . ($lang === 'el' ? 'ελληνικά' : 'αγγλικά') . " — αποκλειστικά.\n\n"
            . "ΚΑΝΟΝΕΣ — ΚΡΙΣΙΜΟ:\n- Χρησιμοποίησε ΑΚΡΙΒΩΣ τα ποσά, ημερομηνίες, ονόματα και συνδέσμους που δίνονται. Μην προσθέσεις δικά σου νούμερα, εκπτώσεις ή διακανονισμούς.\n"
            . "- Δομή: σύντομο μήνυμα, μετά ΑΝΑΛΥΣΗ ΠΑΡΑΣΤΑΤΙΚΩΝ αντιγραμμένη ΑΥΤΟΥΣΙΑ (με τους συνδέσμους), μετά πώς πληρώνει και τι γίνεται αν δεν πληρώσει.\n"
            . "- ΜΗΝ γράψεις θέμα/Subject. ΜΗΝ κλείσεις με υπογραφή — μπαίνει αυτόματα. Σκέτο κείμενο, χωρίς markdown.\n"
            . "- Τόνος: ζεστός, επαγγελματικός, χωρίς απειλές.\n\n"
            . ($draft !== '' ? "ΤΙ ΘΕΛΕΙ ΝΑ ΠΕΙ Ο ΣΥΝΑΔΕΛΦΟΣ (πες το αυτό, μη προσθέσεις άλλα):\n" . mb_substr($draft, 0, 1500) . "\n\n" : '')
            . "ΠΕΛΑΤΗΣ: " . $name . "\nΣΥΝΟΛΟ: " . $money($total) . "\nΛΗΞΙΠΡΟΘΕΣΜΑ: " . $money($overdue) . "\n"
            . ($pastDue ? "ΠΡΟΘΕΣΜΙΑ: έχει ήδη παρέλθει — ζήτα άμεση εξόφληση\n" : ($suspDate ? "ΠΡΟΘΕΣΜΙΑ ΠΡΙΝ ΤΗΝ ΑΝΑΣΤΟΛΗ: " . cnp_d($suspDate) . "\n" : ''))
            . "ΠΛΗΡΩΜΗ: https://my.cloudon.gr (τραπεζική κατάθεση, κάρτα ή PayPal)\n\nΠΑΡΑΣΤΑΤΙΚΑ:\n" . $invList . "\nΜΗΝΥΜΑ:";
        $resA = cnp_anthropic($key, 'claude-haiku-4-5-20251001', [['type' => 'text', 'text' => $prompt]], 1400);
        $txt = trim((string) ($resA['text'] ?? ''));
        if ($txt !== '') {
            $txt = preg_replace('/^\s*(Θέμα|Subject)\s*:.*\R+/ui', '', $txt);
            $txt = preg_replace('/\R+\s*(Με εκτίμηση|Με τιμή|Best regards|Kind regards|Sincerely)\s*,?\s*\R.*$/ui', '', $txt);
            $body = trim($txt) . "\n";
        }
    }
    $lastB = Capsule::table('mod_cpm_pay_reminders')->where('client_id', $cid)->orderBy('id', 'desc')->first();
    out(['subject' => $subject, 'body' => $body, 'lang' => $lang, 'total' => round($total, 2), 'overdue' => round($overdue, 2),
        'suspendDate' => $suspDate, 'invoices' => $invs, 'email' => (string) $cl->email, 'name' => $name,
        'lastReminder' => $lastB ? ['at' => $lastB->created_at, 'by' => Db::adminName((int) $lastB->admin_id), 'channel' => $lastB->channel] : null]);

case 'balance_reminder_send':            // αποστολή: email (καταγράφεται στο WHMCS) ή ticket
    $cid = (int) ($in['client'] ?? 0);
    $cl = $cid ? Capsule::table('tblclients')->where('id', $cid)->first() : null;
    if (!$cl) { fail('client', 404); }
    $subject = mb_substr(trim((string) ($in['subject'] ?? '')), 0, 200);
    $body = trim((string) ($in['body'] ?? ''));
    if ($subject === '' || $body === '') { fail('Λείπει θέμα ή κείμενο'); }
    if (!filter_var((string) $cl->email, FILTER_VALIDATE_EMAIL)) { fail('Ο πελάτης δεν έχει έγκυρο email στο WHMCS — διόρθωσέ το πρώτα'); }
    $channel = (($in['channel'] ?? 'email') === 'ticket') ? 'ticket' : 'email';
    $bal = cnp_open_balances($cid)[$cid] ?? null;
    $amountB = $bal ? $bal['open'] : 0;
    $ticketId = 0; $tid = '';
    if ($channel === 'ticket') {
        $dept = (int) (Capsule::table('tblticketdepartments')->where('name', 'like', '%Accounting%')->value('id')
            ?: Capsule::table('tblticketdepartments')->orderBy('order')->value('id'));
        $r = localAPI('OpenTicket', ['deptid' => $dept, 'clientid' => $cid, 'subject' => $subject,
            'message' => $body, 'priority' => 'Medium', 'markdown' => false], 'pdelis');
        if (($r['result'] ?? '') !== 'success') { fail($r['message'] ?? 'Αποτυχία δημιουργίας ticket'); }
        $ticketId = (int) ($r['id'] ?? 0); $tid = (string) ($r['tid'] ?? '');
    } else {
        /* Email μέσω WHMCS (SendEmail → καταγράφεται στο Email Log του πελάτη). Το
           σκέτο κείμενο γίνεται HTML: οι σύνδεσμοι κλικάρονται, οι αλλαγές γραμμής μένουν. */
        $html = nl2br(preg_replace('~(https?://[^\s<]+)~u', '<a href="$1">$1</a>', htmlspecialchars($body, ENT_QUOTES, 'UTF-8')));
        $adm = Capsule::table('tbladmins')->where('id', $adminId)->first(['firstname', 'lastname']);
        $sig = ($cnpLangB = cnp_client_lang($cl, (string) ($in['lang'] ?? ''))) === 'el' ? 'Με εκτίμηση' : 'Kind regards';
        $msg = '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#243447;line-height:1.6;max-width:680px">'
            . $html . '<br><br>' . $sig . ',<br>' . htmlspecialchars(trim(($adm->firstname ?? '') . ' ' . ($adm->lastname ?? ''))) . '<br>CloudOn — Λογιστήριο</div>';
        $r = localAPI('SendEmail', ['customtype' => 'general', 'id' => $cid, 'customsubject' => $subject, 'custommessage' => $msg], 'pdelis');
        if (($r['result'] ?? '') !== 'success') { fail('Το email δεν στάλθηκε: ' . ($r['message'] ?? 'άγνωστο σφάλμα')); }
    }
    Capsule::table('mod_cpm_pay_reminders')->insert([
        'client_id' => $cid, 'invoices' => implode(',', array_map('intval', (array) ($in['invoices'] ?? []))),
        'amount' => round((float) $amountB, 2), 'channel' => $channel, 'ticket_id' => $ticketId ?: null,
        'admin_id' => $adminId, 'created_at' => date('Y-m-d H:i:s'),
    ]);
    logActivity('CloudOn PM: υπενθύμιση εξόφλησης προς πελάτη #' . $cid . ' (' . number_format((float) $amountB, 2, ',', '.') . ' €) μέσω '
        . ($channel === 'ticket' ? 'ticket ' . $tid : 'email ' . $cl->email) . ' από ' . Db::adminName($adminId));
    out(['ok' => true, 'channel' => $channel, 'ticket' => $ticketId, 'tid' => $tid, 'email' => (string) $cl->email]);

case 'suspend_queue':                    // 🛑 Υπηρεσίες υποψήφιες για αναστολή
    /* Ο αυτοματισμός του WHMCS εκτελείται μόνο όπου υπάρχει server module — 15%
       των υπηρεσιών — οπότε τιμωρεί άνισα όποιον τυχαίνει να είναι στη Hetzner.
       Μέχρι να ολοκληρωθεί η μετάβαση, η απόφαση παίρνεται εδώ, με τα σωστά
       νούμερα: πραγματικά ανοιχτά ΑΝΑ ΠΑΡΑΣΤΑΤΙΚΟ, όχι το total του WHMCS που
       δεν μειώνεται στις μερικές πληρωμές. */
    $graceDays = (int) (Capsule::table('tblconfiguration')->where('setting', 'AutoSuspensionDays')->value('value') ?: 10);
    $today0 = strtotime('today');

    // Ανοιχτά ανά παραστατικό, μόνο για ληξιπρόθεσμα
    $alloc = [];
    foreach (Capsule::table('tblaccounts')->where('invoiceid', '>', 0)
                 ->selectRaw('invoiceid, SUM(amountin) - SUM(CASE WHEN refundid > 0 THEN amountout ELSE 0 END) p')
                 ->groupBy('invoiceid')->get() as $r) {
        $alloc[(int) $r->invoiceid] = (float) $r->p;
    }
    $debt = [];   // clientId => ['open'=>, 'days'=>, 'invs'=>[]]
    foreach (Capsule::table('tblinvoices')->whereIn('status', ['Unpaid', 'Overdue', 'Payment Pending'])
                 ->get(['id', 'userid', 'invoicenum', 'date', 'duedate', 'status', 'subtotal', 'tax', 'tax2', 'credit']) as $iv) {
        $due = (string) $iv->duedate;
        if ($due === '' || strpos($due, '0000') === 0) { continue; }
        /* Υπάρχουν παραστατικά με πληκτρολογημένο λάθος έτος (π.χ. 0026-06-17).
           Χωρίς έλεγχο βγάζουν «730.549 ημέρες καθυστέρηση» και εκτοξεύουν τον
           πελάτη στην κορυφή. Πέφτουμε στην ημερομηνία έκδοσης και το σημαίνουμε
           ως λάθος δεδομένο, για να διορθωθεί στο WHMCS. */
        $badDue = false;
        if ((int) substr($due, 0, 4) < 2000) {
            $badDue = true;
            $due = (string) $iv->date;
            if ($due === '' || strpos($due, '0000') === 0) { continue; }
        }
        if (strtotime($due) >= $today0) { continue; }
        $open = round((float) $iv->subtotal + (float) $iv->tax + (float) $iv->tax2
            - ($alloc[(int) $iv->id] ?? 0) - (float) $iv->credit, 2);
        if ($open <= 0.5) { continue; }   // ουσιαστικά εξοφλημένο — δεν κόβουμε για σεντ
        $d = (int) floor(($today0 - strtotime($due)) / 86400);
        $cid = (int) $iv->userid;
        if (!isset($debt[$cid])) { $debt[$cid] = ['open' => 0, 'days' => 0, 'invs' => [], 'badDue' => false]; }
        $debt[$cid]['open'] += $open;
        $debt[$cid]['days'] = max($debt[$cid]['days'], $d);
        $debt[$cid]['invs'][] = ['id' => (int) $iv->id, 'num' => (string) ($iv->invoicenum ?: $iv->id),
            'due' => $due, 'days' => $d, 'open' => $open, 'badDue' => $badDue];
        if ($badDue) { $debt[$cid]['badDue'] = true; }
    }
    if (!$debt) { out(['rows' => [], 'grace' => $graceDays, 'sum' => ['clients' => 0, 'services' => 0, 'debt' => 0, 'auto' => 0]]); }

    $notified = [];
    foreach (Capsule::table('mod_cpm_suspend_notices')->orderBy('id')->get() as $n) {
        $notified[(int) $n->client_id] = ['at' => $n->created_at, 'date' => $n->suspend_date,
            'ticket' => (int) $n->ticket_id, 'by' => Db::adminName((int) $n->admin_id)];
    }
    $handled = [];
    foreach (Capsule::table('mod_cpm_suspend_actions')->orderBy('id')->get() as $a) {
        $handled[(int) $a->service_id] = ['action' => $a->action, 'note' => $a->note,
            'by' => Db::adminName((int) $a->admin_id), 'at' => $a->created_at];
    }

    /* Τι είναι «μηχάνημα»: ό,τι μπορείς πραγματικά να σβήσεις. Το WHMCS το λέει
       με type=server· προσθέτουμε όσα διαχειρίζεται module μηχανών και όσα
       ονομάζονται VPS/Proxmox αλλά έχουν λάθος type. DID, άδειες, domains και
       συμβόλαια υποστήριξης ΔΕΝ είναι μηχανήματα και δεν έχουν θέση εδώ. */
    $isMachine = function ($p) {
        if (in_array((string) $p->servertype, ['hetznercloud', 'scaleway'], true)) { return true; }
        if ((string) $p->ptype === 'server') { return true; }
        return (bool) preg_match('/\b(vps|server|proxmox|dedicated)\b/i', (string) $p->pname);
    };
    $onlyMachines = ($_GET['machines'] ?? '') === '1';
    $onlyRipe = ($_GET['ripe'] ?? '1') === '1';

    /* Η ενέργεια αναγνωρίζεται από την ΚΑΤΑΣΤΑΣΗ ΤΗΣ ΥΠΗΡΕΣΙΑΣ στο WHMCS. Ό,τι
       αλλάξεις εκεί φαίνεται εδώ αμέσως — καμία διπλή καταχώρηση. Η χειροκίνητη
       σήμανση μένει μόνο για αποφάσεις που δεν αποτυπώνονται σε status
       (π.χ. «δώσαμε παράταση»). */
    /* Το WHMCS έχει ρητή εξαίρεση ανά υπηρεσία: «Override Auto-Suspend — Do not
       suspend until». Είναι απόφαση που έχει ήδη παρθεί και ΔΕΝ την αγνοούμε:
       τέτοιες υπηρεσίες δεν εκκρεμούν και δεν προσφέρουμε κουμπί αναστολής. */
    $exemptOf = function ($h) {
        if (empty($h->overideautosuspend)) { return null; }
        $until = (string) ($h->overidesuspenduntil ?? '');
        if ($until === '' || strpos($until, '0000') === 0) { return '∞'; }
        return (strtotime($until) >= strtotime('today')) ? $until : null;
    };
    $stateOf = function ($st) {
        if (in_array($st, ['Terminated', 'Cancelled', 'Fraud'], true)) { return 'terminated'; }
        if ($st === 'Suspended') { return 'suspended'; }
        return 'pending';
    };

    $rows = [];
    foreach (Capsule::table('tblhosting as h')->join('tblproducts as p', 'p.id', '=', 'h.packageid')
                 ->whereIn('h.userid', array_keys($debt))
                 /* Τερματισμένες/ακυρωμένες ΔΕΝ μπαίνουν: είναι ιστορικό, όχι απόφαση.
                    Μένουν οι ενεργές (εκκρεμούν) και οι ανεσταλμένες (έγιναν). */
                 ->whereIn('h.domainstatus', ['Active', 'Suspended'])
                 ->get(['h.id', 'h.userid', 'h.domain', 'h.domainstatus', 'h.amount', 'h.billingcycle',
                     'h.nextduedate', 'h.dedicatedip', 'h.overideautosuspend', 'h.overidesuspenduntil',
                     'p.name as pname', 'p.servertype', 'p.type as ptype']) as $h) {
        $cid = (int) $h->userid;
        $d = $debt[$cid];
        $machine = $isMachine($h);
        if ($onlyMachines && !$machine) { continue; }
        if ($onlyRipe && $d['days'] < $graceDays) { continue; }
        $auto = ((string) $h->servertype !== '');
        $rows[] = [
            'service' => (int) $h->id, 'client' => $cid, 'name' => clientLabel($cid),
            'domain' => (string) $h->domain, 'product' => (string) $h->pname,
            'status' => (string) $h->domainstatus,
            'module' => (string) $h->servertype, 'auto' => $auto, 'machine' => $machine,
            'state' => $exemptOf($h) ? 'exempt' : $stateOf((string) $h->domainstatus),
            'exempt' => $exemptOf($h),
            'whmcsStatus' => (string) $h->domainstatus,
            'adminUrl' => '/cloudonadminpanel/clientsservices.php?userid=' . $cid . '&id=' . (int) $h->id,
            'amount' => (float) $h->amount, 'cycle' => (string) $h->billingcycle,
            'ip' => (string) $h->dedicatedip,
            'debt' => round($d['open'], 2), 'days' => $d['days'], 'badDue' => !empty($d['badDue']),
            'ripe' => $d['days'] >= $graceDays,
            'invs' => array_slice($d['invs'], 0, 4),
            'notified' => $notified[$cid] ?? null,
            'done' => $handled[(int) $h->id] ?? null,
        ];
    }
    /* Πρώτα όσες «ώριμασαν» και χρωστούν περισσότερα — αυτές θέλουν απόφαση. */
    usort($rows, function ($a, $b) {
        // Εκκρεμή πρώτα — αυτά θέλουν ενέργεια· τα τελειωμένα πάνε κάτω.
        $pa = $a['state'] === 'pending' ? 0 : 1;
        $pb = $b['state'] === 'pending' ? 0 : 1;
        return ($pa <=> $pb) ?: ($b['ripe'] <=> $a['ripe']) ?: ($b['debt'] <=> $a['debt']) ?: ($b['days'] <=> $a['days']);
    });

    $shownClients = array_unique(array_column($rows, 'client'));
    out(['rows' => $rows, 'grace' => $graceDays,
        'filters' => ['machines' => $onlyMachines, 'ripe' => $onlyRipe],
        'sum' => [
            'clients' => count($shownClients),
            'services' => count($rows),
            // Οφειλή μόνο των πελατών που εμφανίζονται, χωρίς διπλομέτρηση.
            'debt' => round(array_sum(array_map(function ($c) use ($debt) { return $debt[$c]['open']; }, $shownClients)), 2),
            'auto' => count(array_filter($rows, function ($r) { return $r['auto']; })),
            'pending' => count(array_filter($rows, function ($r) { return $r['state'] === 'pending'; })),
            'done' => count(array_filter($rows, function ($r) { return $r['state'] === 'suspended' || $r['state'] === 'terminated'; })),
            'exempt' => count(array_filter($rows, function ($r) { return $r['state'] === 'exempt'; })),
            'allDebt' => round(array_sum(array_column($debt, 'open')), 2),
            'allClients' => count($debt),
        ]]);

case 'suspend_do':                       // εκτέλεση αναστολής / σήμανση / επαναφορά
    /* Εκτελεί πραγματική διακοπή υπηρεσίας πελάτη. Η οθόνη είναι ορατή μόνο σε
       διαχειριστές πλήρους πρόσβασης· εδώ κρατάμε δικλείδες ως δίχτυ, όχι ως
       εμπόδιο: έλεγχος οφειλής ξανά στον server, αιτιολογία σε κάθε ενέργεια,
       και καταγραφή στο ημερολόγιο του WHMCS. */
    if (!$FULL) { fail('forbidden', 403); }
    $sid = (int) ($in['service'] ?? 0);
    $h = $sid ? Capsule::table('tblhosting')->where('id', $sid)->first() : null;
    if (!$h) { fail('service', 404); }
    $act = (string) ($in['do'] ?? 'suspend');

    // Ληξιπρόθεσμο υπόλοιπο του πελάτη — ίδιος υπολογισμός με την οθόνη.
    $alloc3 = [];
    foreach (Capsule::table('tblaccounts')->where('userid', $h->userid)->where('invoiceid', '>', 0)
                 ->selectRaw('invoiceid, SUM(amountin) - SUM(CASE WHEN refundid > 0 THEN amountout ELSE 0 END) p')
                 ->groupBy('invoiceid')->get() as $r) {
        $alloc3[(int) $r->invoiceid] = (float) $r->p;
    }
    $owed = 0.0;
    foreach (Capsule::table('tblinvoices')->where('userid', $h->userid)
                 ->whereIn('status', ['Unpaid', 'Overdue', 'Payment Pending'])->get() as $iv) {
        $due = (string) $iv->duedate;
        if ($due === '' || strpos($due, '0000') === 0) { continue; }
        if ((int) substr($due, 0, 4) < 2000) { $due = (string) $iv->date; }
        if (strtotime($due) >= strtotime('today')) { continue; }
        $owed += round((float) $iv->subtotal + (float) $iv->tax + (float) $iv->tax2
            - ($alloc3[(int) $iv->id] ?? 0) - (float) $iv->credit, 2);
    }
    $svcLabel = ($h->domain ?: ('#' . $sid));

    if ($act === 'unsuspend') {
        // Και εδώ μόνο μέσω WHMCS — καμία απευθείας εγγραφή κατάστασης.
        $r = localAPI('ModuleUnsuspend', ['accountid' => $sid], 'pdelis');
        if (($r['result'] ?? '') !== 'success') {
            fail('Η επαναφορά απέτυχε: ' . ($r['message'] ?? 'άγνωστο σφάλμα')
                . ' — κάν\' την από το WHMCS.');
        }
        Capsule::table('mod_cpm_suspend_actions')->where('service_id', $sid)->delete();
        logActivity('CloudOn PM: επαναφορά υπηρεσίας ' . $svcLabel . ' (#' . $sid . ') από ' . Db::adminName($adminId));
        out(['ok' => true, 'status' => 'Active']);
    }

    /* Δίχτυ: η οθόνη αφορά οφειλές. Αν ο πελάτης δεν χρωστά, η αναστολή δεν
       γίνεται από εδώ — για οτιδήποτε άλλο (π.χ. κατάχρηση) υπάρχει το WHMCS. */
    if ($owed <= 0.5) {
        fail('Ο πελάτης δεν έχει ληξιπρόθεσμη οφειλή — η αναστολή δεν γίνεται από αυτή την οθόνη.');
    }

    $reason = mb_substr(trim((string) ($in['reason'] ?? '')), 0, 190)
        ?: ('Ληξιπρόθεσμη οφειλή ' . number_format($owed, 2, ',', '.') . ' €');

    /* Ρητή εξαίρεση στο WHMCS («Do not suspend until») = απόφαση που έχει ήδη
       παρθεί. Δεν την παρακάμπτουμε από εδώ. */
    if (!empty($h->overideautosuspend)) {
        $u = (string) ($h->overidesuspenduntil ?? '');
        if ($u === '' || strpos($u, '0000') === 0 || strtotime($u) >= strtotime('today')) {
            fail('Η υπηρεσία έχει εξαίρεση στο WHMCS («Do not suspend until»'
                . ($u ? ' ' . cnp_d($u) : '') . '). Αν πρέπει να ανασταλεί, αφαίρεσε πρώτα την εξαίρεση στο WHMCS.');
        }
    }

    /* ΜΟΝΟ μέσω WHMCS. Δεν γράφουμε ποτέ εμείς το domainstatus: η κατάσταση
       επηρεάζει τιμολόγηση και ανανεώσεις, και μια απευθείας εγγραφή στη βάση
       παρακάμπτει όσα κάνει το WHMCS (module, ειδοποιήσεις, ιστορικό). Η οθόνη
       ΔΕΙΧΝΕΙ την κατάσταση· δεν την επινοεί. */
    if (($in['mode'] ?? '') !== 'module' || (string) $h->servertype === '') {
        fail('Η υπηρεσία δεν έχει module. Η αναστολή γίνεται από το WHMCS — '
            . 'άνοιξέ την με το ↗ και άλλαξε εκεί την κατάσταση.');
    }
    $r = localAPI('ModuleSuspend', ['accountid' => $sid, 'suspendreason' => $reason], 'pdelis');
    if (($r['result'] ?? '') !== 'success') {
        fail('Το module απέτυχε: ' . ($r['message'] ?? 'άγνωστο σφάλμα'));
    }
    $note = 'Αναστολή μέσω module';
    logActivity('CloudOn PM: ' . $note . ' — ' . $svcLabel . ' (#' . $sid . ') από '
        . Db::adminName($adminId) . ' — ' . $reason);

    Capsule::table('mod_cpm_suspend_actions')->where('service_id', $sid)->delete();
    Capsule::table('mod_cpm_suspend_actions')->insert([
        'service_id' => $sid, 'admin_id' => $adminId, 'action' => 'suspended',
        'note' => mb_substr($note . ' — ' . $reason, 0, 200), 'created_at' => date('Y-m-d H:i:s'),
    ]);
    out(['ok' => true, 'status' => 'Suspended']);

case 'suspend_notice':                   // σύνθεση ειδοποίησης προς τον πελάτη
    $cid = (int) ($in['client'] ?? 0);
    $cl = $cid ? Capsule::table('tblclients')->where('id', $cid)->first() : null;
    if (!$cl) { fail('client', 404); }
    $svcIds = array_map('intval', (array) ($in['services'] ?? []));
    if (!$svcIds) { fail('Δεν επιλέχθηκε υπηρεσία'); }
    $when = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string) ($in['date'] ?? '')) ? $in['date'] : date('Y-m-d', strtotime('+5 days'));

    /* Γλώσσα: ό,τι δηλώνει ο πελάτης· αλλιώς από τη χώρα. Ο χειριστής μπορεί να
       την αλλάξει από τον διάλογο — δεν μαντεύουμε πάνω στο λάθος. */
    $lang = in_array($in['lang'] ?? '', ['el', 'en'], true) ? $in['lang']
        : ((strtolower((string) $cl->language) === 'greek' || strtoupper((string) $cl->country) === 'GR') ? 'el' : 'en');

    $svcs = [];
    foreach (Capsule::table('tblhosting as h')->join('tblproducts as p', 'p.id', '=', 'h.packageid')
                 ->whereIn('h.id', $svcIds)->where('h.userid', $cid)
                 ->get(['h.id', 'h.domain', 'h.dedicatedip', 'h.amount', 'h.billingcycle', 'p.name as pname']) as $h) {
        $svcs[] = ['id' => (int) $h->id, 'label' => (string) ($h->domain ?: $h->pname),
            'product' => (string) $h->pname, 'ip' => (string) $h->dedicatedip];
    }
    if (!$svcs) { fail('Οι υπηρεσίες δεν ανήκουν σε αυτόν τον πελάτη'); }

    // Τα ληξιπρόθεσμα — η αιτία, με ονόματα και ποσά
    $alloc2 = [];
    foreach (Capsule::table('tblaccounts')->where('userid', $cid)->where('invoiceid', '>', 0)
                 ->selectRaw('invoiceid, SUM(amountin) - SUM(CASE WHEN refundid > 0 THEN amountout ELSE 0 END) p')
                 ->groupBy('invoiceid')->get() as $r) {
        $alloc2[(int) $r->invoiceid] = (float) $r->p;
    }
    $invs = []; $total = 0.0;
    foreach (Capsule::table('tblinvoices')->where('userid', $cid)
                 ->whereIn('status', ['Unpaid', 'Overdue', 'Payment Pending'])->orderBy('duedate')->get() as $iv) {
        $due = (string) $iv->duedate;
        if ($due === '' || strpos($due, '0000') === 0) { continue; }
        if ((int) substr($due, 0, 4) < 2000) { $due = (string) $iv->date; }
        if (strtotime($due) >= strtotime('today')) { continue; }
        $open = round((float) $iv->subtotal + (float) $iv->tax + (float) $iv->tax2
            - ($alloc2[(int) $iv->id] ?? 0) - (float) $iv->credit, 2);
        if ($open <= 0.5) { continue; }
        $total += $open;
        $gross = round((float) $iv->subtotal + (float) $iv->tax + (float) $iv->tax2, 2);
        $paid = round(($alloc2[(int) $iv->id] ?? 0) + (float) $iv->credit, 2);
        $invs[] = ['num' => (string) ($iv->invoicenum ?: $iv->id),
            'issued' => cnp_d($iv->date), 'due' => cnp_d($due),
            'gross' => $gross, 'paid' => $paid, 'open' => $open,
            'days' => (int) floor((strtotime('today') - strtotime($due)) / 86400)];
    }

    $money = function ($v) { return number_format((float) $v, 2, ',', '.') . ' €'; };
    $name = trim(($cl->companyname ?: ($cl->firstname . ' ' . $cl->lastname)));
    $svcList = '';
    foreach ($svcs as $x) {
        $svcList .= '- ' . $x['label'] . ' (' . $x['product'] . ($x['ip'] ? ', ' . $x['ip'] : '') . ")\n";
    }
    /* Πλήρης ανάλυση ανά παραστατικό: έκδοση, λήξη, καθυστέρηση, αξία, τι έχει
       πληρωθεί και τι μένει. Ο πελάτης πρέπει να μπορεί να το ελέγξει γραμμή
       γραμμή χωρίς να μπει στον λογαριασμό του. */
    $invList = ''; $i9 = 0;
    foreach ($invs as $x) {
        $i9++;
        if ($lang === 'el') {
            $invList .= $i9 . ') Παραστατικό ' . $x['num'] . "\n"
                . '   Έκδοση: ' . $x['issued'] . ' · Λήξη: ' . $x['due']
                . ' · Καθυστέρηση: ' . $x['days'] . ($x['days'] === 1 ? ' ημέρα' : ' ημέρες') . "\n"
                . '   Αξία: ' . $money($x['gross'])
                . ($x['paid'] > 0.005 ? ' · Έχουν εξοφληθεί: ' . $money($x['paid']) : '')
                . ' · Υπόλοιπο: ' . $money($x['open']) . "\n";
        } else {
            $invList .= $i9 . ') Invoice ' . $x['num'] . "\n"
                . '   Issued: ' . $x['issued'] . ' · Due: ' . $x['due']
                . ' · Overdue by: ' . $x['days'] . ($x['days'] === 1 ? ' day' : ' days') . "\n"
                . '   Amount: ' . $money($x['gross'])
                . ($x['paid'] > 0.005 ? ' · Paid so far: ' . $money($x['paid']) : '')
                . ' · Outstanding: ' . $money($x['open']) . "\n";
        }
    }
    $invList .= ($lang === 'el' ? '   ΣΥΝΟΛΟ ΟΦΕΙΛΗΣ: ' : '   TOTAL OUTSTANDING: ') . $money($total) . "\n";

    /* Πάγιο κείμενο: η δομή που ζητήθηκε — μήνυμα, μετά οι υπηρεσίες, μετά ο
       λόγος. Το ίδιο σκελετό ακολουθεί και η εκδοχή του AI. */
    if ($lang === 'el') {
        $subject = 'Ειδοποίηση αναστολής υπηρεσιών — ' . cnp_d($when);
        $body = "Αγαπητοί συνεργάτες,\n\n"
            . "Στον λογαριασμό σας υπάρχει ληξιπρόθεσμο υπόλοιπο " . $money($total) . ". "
            . "Εφόσον δεν εξοφληθεί, οι παρακάτω υπηρεσίες θα τεθούν σε αναστολή στις "
            . cnp_d($when) . ".\n\n"
            . "ΥΠΗΡΕΣΙΕΣ ΠΟΥ ΑΦΟΡΑ\n" . $svcList . "\n"
            . "ΑΝΑΛΥΣΗ ΛΗΞΙΠΡΟΘΕΣΜΩΝ ΠΑΡΑΣΤΑΤΙΚΩΝ\n" . $invList . "\n"
            . "Η αναστολή διακόπτει τη λειτουργία των παραπάνω υπηρεσιών μέχρι την εξόφληση. "
            . "Μπορείτε να δείτε και να εξοφλήσετε τα παραστατικά από τον λογαριασμό σας στο "
            . "https://my.cloudon.gr\n\n"
            . "Αν η πληρωμή έχει ήδη γίνει, παρακαλούμε αγνοήστε το μήνυμα ή στείλτε μας το αποδεικτικό "
            . "για να το αντιστοιχίσουμε.\n";
    } else {
        $subject = 'Service suspension notice — ' . cnp_d($when);
        $body = "Dear partners,\n\n"
            . "Your account has an overdue balance of " . $money($total) . ". "
            . "Unless it is settled, the following services will be suspended on " . cnp_d($when) . ".\n\n"
            . "SERVICES AFFECTED\n" . $svcList . "\n"
            . "OVERDUE INVOICES — BREAKDOWN\n" . $invList . "\n"
            . "Suspension stops the above services until payment is received. "
            . "You can review and pay your invoices at https://my.cloudon.gr\n\n"
            . "If payment has already been made, please ignore this message or send us the receipt "
            . "so we can allocate it.\n";
    }

    // ✨ AI: ίδια γεγονότα, καλύτερη διατύπωση — ποτέ δικά του νούμερα
    if (($in['mode'] ?? '') === 'ai') {
        $key = (string) (Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')
            ->where('setting', 'ai_api_key')->value('value') ?: '');
        if ($key === '') { fail('Δεν έχει οριστεί AI API key — βάλ\' το στις Ρυθμίσεις'); }
        $draft = trim((string) ($in['draft'] ?? ''));
        $prompt = "Είσαι υπεύθυνος λογιστηρίου ελληνικής εταιρείας IT/hosting (CloudOn). Γράψε ένα "
            . "ευγενικό αλλά σαφές μήνυμα προς πελάτη για επικείμενη αναστολή υπηρεσιών λόγω "
            . "ληξιπρόθεσμης οφειλής.\n\n"
            . "ΓΛΩΣΣΑ: " . ($lang === 'el' ? 'ελληνικά' : 'αγγλικά') . " — αποκλειστικά.\n\n"
            . "ΚΑΝΟΝΕΣ — ΚΡΙΣΙΜΟ:\n"
            . "- Χρησιμοποίησε ΑΚΡΙΒΩΣ τα ποσά, τις ημερομηνίες και τα ονόματα που δίνονται. Μην "
            . "στρογγυλοποιήσεις, μην προσθέσεις δικά σου νούμερα, μην υποσχεθείς εκπτώσεις ή διακανονισμούς.\n"
            . "- Κράτα τη δομή: σύντομο μήνυμα, μετά ΥΠΗΡΕΣΙΕΣ ΠΟΥ ΑΦΟΡΑ, μετά η ΑΝΑΛΥΣΗ των παραστατικών.\n"
            . "- Η ανάλυση των παραστατικών αντιγράφεται ΑΥΤΟΥΣΙΑ όπως σου δίνεται: κάθε "
            . "παραστατικό με έκδοση, λήξη, ΗΜΕΡΕΣ ΚΑΘΥΣΤΕΡΗΣΗΣ, αξία, εξοφλημένα και υπόλοιπο. "
            . "Μην τη συνοψίσεις και μην παραλείψεις τις ημέρες.\n"
            . "- ΜΗΝ γράψεις θέμα/Subject μέσα στο κείμενο — το θέμα είναι ξεχωριστό πεδίο.\n"
            . "- ΜΗΝ κλείσεις με υπογραφή («Με εκτίμηση», «CloudOn» κ.λπ.) — μπαίνει αυτόματα.\n"
            . "- Χωρίς placeholders και χωρίς markdown (**), σκέτο κείμενο.\n"
            . "- Τόνος: επαγγελματικός, χωρίς απειλές· είναι συνεργάτης, όχι οφειλέτης προς δίωξη.\n\n"
            . ($draft !== '' ? "ΤΙ ΘΕΛΕΙ ΝΑ ΠΕΙ Ο ΣΥΝΑΔΕΛΦΟΣ (πες το αυτό, μη προσθέσεις άλλα):\n" . mb_substr($draft, 0, 1500) . "\n\n" : '')
            . "ΠΕΛΑΤΗΣ: " . $name . "\n"
            . "ΗΜΕΡΟΜΗΝΙΑ ΑΝΑΣΤΟΛΗΣ: " . cnp_d($when) . "\n"
            . "ΣΥΝΟΛΙΚΗ ΛΗΞΙΠΡΟΘΕΣΜΗ ΟΦΕΙΛΗ: " . $money($total) . "\n\n"
            . "ΥΠΗΡΕΣΙΕΣ:\n" . $svcList . "\nΠΑΡΑΣΤΑΤΙΚΑ:\n" . $invList . "\nΜΗΝΥΜΑ:";
        $ch = curl_init('https://api.anthropic.com/v1/messages');
        curl_setopt_array($ch, [
            CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 60, CURLOPT_POST => true,
            CURLOPT_HTTPHEADER => ['Content-Type: application/json', 'x-api-key: ' . $key, 'anthropic-version: 2023-06-01'],
            CURLOPT_POSTFIELDS => json_encode([
                'model' => 'claude-haiku-4-5-20251001', 'max_tokens' => 1200,
                'messages' => [['role' => 'user', 'content' => $prompt]],
            ]),
        ]);
        $resp = curl_exec($ch);
        curl_close($ch);
        $j = json_decode((string) $resp, true);
        $txt = $j['content'][0]['text'] ?? '';
        if (trim($txt) !== '') {
            // Δίχτυ: αν παρ' όλα αυτά βάλει θέμα ή υπογραφή, τα κόβουμε.
            $txt = preg_replace('/^\s*(Θέμα|Subject)\s*:.*\R+/ui', '', trim($txt));
            $txt = preg_replace('/\R+\s*(Με εκτίμηση|Με τιμή|Best regards|Kind regards|Sincerely)\s*,?\s*\R.*$/ui', '', $txt);
            $body = trim($txt) . "\n";
        }
    }

    out(['subject' => $subject, 'body' => $body, 'lang' => $lang,
        'total' => round($total, 2), 'services' => $svcs, 'invoices' => $invs,
        'email' => (string) $cl->email, 'name' => $name]);

case 'suspend_notice_send':              // αποστολή ως ticket (μένει ίχνος, απαντά ο πελάτης)
    $cid = (int) ($in['client'] ?? 0);
    $cl = $cid ? Capsule::table('tblclients')->where('id', $cid)->first() : null;
    if (!$cl) { fail('client', 404); }
    $subject = mb_substr(trim((string) ($in['subject'] ?? '')), 0, 200);
    $body = trim((string) ($in['body'] ?? ''));
    if ($subject === '' || $body === '') { fail('Λείπει θέμα ή κείμενο'); }

    $dept = (int) (Capsule::table('tblticketdepartments')->where('name', 'like', '%Accounting%')->value('id')
        ?: Capsule::table('tblticketdepartments')->orderBy('order')->value('id'));
    $r = localAPI('OpenTicket', ['deptid' => $dept, 'clientid' => $cid, 'subject' => $subject,
        'message' => $body, 'priority' => 'Medium', 'markdown' => false], 'pdelis');
    if (($r['result'] ?? '') !== 'success') { fail($r['message'] ?? 'Αποτυχία δημιουργίας ticket'); }

    Capsule::table('mod_cpm_suspend_notices')->insert([
        'client_id' => $cid, 'ticket_id' => (int) ($r['id'] ?? 0),
        'services' => implode(',', array_map('intval', (array) ($in['services'] ?? []))),
        'suspend_date' => preg_match('/^\d{4}-\d{2}-\d{2}$/', (string) ($in['date'] ?? '')) ? $in['date'] : null,
        'admin_id' => $adminId, 'created_at' => date('Y-m-d H:i:s'),
    ]);
    logActivity('CloudOn PM: ειδοποίηση αναστολής προς πελάτη ' . $cid . ' — ticket ' . ($r['tid'] ?? ''));
    out(['ok' => true, 'ticket' => (int) ($r['id'] ?? 0), 'tid' => (string) ($r['tid'] ?? '')]);

case 'suspend_mark':                     // καταγραφή τι κάναμε χειροκίνητα
    $sid = (int) ($in['service'] ?? 0);
    if (!$sid) { fail('service'); }
    $act = in_array($in['action'] ?? '', ['suspended', 'skipped', 'paid'], true) ? $in['action'] : 'skipped';
    Capsule::table('mod_cpm_suspend_actions')->where('service_id', $sid)->delete();
    if (!empty($in['clear'])) { out(['ok' => true]); }
    Capsule::table('mod_cpm_suspend_actions')->insert([
        'service_id' => $sid, 'admin_id' => $adminId, 'action' => $act,
        'note' => mb_substr(trim((string) ($in['note'] ?? '')), 0, 200) ?: null,
        'created_at' => date('Y-m-d H:i:s'),
    ]);
    out(['ok' => true]);

case 'fin_audit_csv':                    // Οι έλεγχοι σε CSV για το λογιστήριο
    $sc = (string) ($_GET['section'] ?? '');
    $titles = ['mismatch' => 'asymfonia-vivlion', 'overpaid' => 'yperpliromena',
               'zombie' => 'zombi-syndromes', 'debt' => 'ofeiles',
               'legacy' => 'pliromena-xoris-antistoixisi'];
    if (!isset($titles[$sc])) { fail('Άγνωστη ενότητα', 404); }

    // Ξαναχρησιμοποιούμε τον ίδιο υπολογισμό μέσω εσωτερικής κλήσης.
    $_GET['section'] = $sc;
    ob_start();
    $keepOut = true;
    // Δεν μπορούμε να καλέσουμε το case· επαναλαμβάνουμε μόνο ό,τι χρειάζεται.
    ob_end_clean();

    $grossBy = []; $paidBy = []; $adjBy = []; $unpaidBy = [];
    foreach (Capsule::table('tblinvoices')->whereNotIn('status', ['Cancelled', 'Draft'])
                 ->selectRaw('userid, SUM(subtotal+tax+tax2) g')->groupBy('userid')->get() as $r) { $grossBy[(int) $r->userid] = (float) $r->g; }
    foreach (Capsule::table('tblaccounts')->where('gateway', '!=', '')->whereNotNull('gateway')
                 ->selectRaw('userid, SUM(amountin) p')->groupBy('userid')->get() as $r) { $paidBy[(int) $r->userid] = (float) $r->p; }
    // Τα σημασμένα «Paid» χωρίς γραμμή πληρωμής μετρούν ως εισπραγμένα.
    foreach (cnp_assumed_paid()['byClient'] as $uid => $amt) {
        $paidBy[$uid] = ($paidBy[$uid] ?? 0) + $amt;
    }
    foreach (Capsule::table('tblaccounts')->where('type', 'invoice_billing_adjustment_credit')
                 ->selectRaw('userid, SUM(amountin) a')->groupBy('userid')->get() as $r) { $adjBy[(int) $r->userid] = (float) $r->a; }
    foreach (Capsule::table('tblinvoices')->where('status', 'Unpaid')
                 ->selectRaw('userid, SUM(total) u')->groupBy('userid')->get() as $r) { $unpaidBy[(int) $r->userid] = (float) $r->u; }

    $nm = function ($id) {
        $x = Capsule::table('tblclients')->where('id', $id)->first();
        return $x ? trim(($x->companyname ?: ($x->firstname . ' ' . $x->lastname))) : '#' . $id;
    };
    $n3 = function ($v) { return number_format((float) $v, 2, ',', ''); };

    header('Content-Type: text/csv; charset=UTF-8');
    header('Content-Disposition: attachment; filename="' . $titles[$sc] . '-' . date('Y-m-d') . '.csv"');
    $f3 = fopen('php://output', 'w');
    fwrite($f3, "\xEF\xBB\xBF");

    if ($sc === 'mismatch') {
        fputcsv($f3, ['ID πελάτη', 'Πελάτης', 'Διαφορά πελάτη', 'Παραστατικό', 'Ημερομηνία',
            'Κατάσταση', 'Αξία', 'Εισπράχθηκαν', 'Διαφορά', 'Αιτία'], ';');
        $mm = [];
        $openBy = cnp_receivables();
        foreach ($grossBy as $cid => $g) {
            $mine = round($openBy[$cid] ?? 0, 2);
            $wh = $unpaidBy[$cid] ?? 0;
            if (abs($mine - $wh) > 1) { $mm[$cid] = round($mine - $wh, 2); }
        }
        uasort($mm, function ($a, $b) { return abs($b) <=> abs($a); });
        $gaps = cnp_book_gaps(array_keys($mm));
        foreach ($mm as $cid => $diff) {
            $rows = $gaps['inv'][$cid] ?? [];
            foreach ($rows as $x) {
                fputcsv($f3, [$cid, $nm($cid), $n3($diff), $x['num'], cnp_d($x['date']), $x['status'],
                    $n3($x['gross']), $n3($x['paid']), $n3($x['diff']), $x['why']], ';');
            }
            // Αιτίες που δεν κρέμονται σε συγκεκριμένο παραστατικό
            if (!empty($gaps['cancelled'][$cid]['sum'])) {
                fputcsv($f3, [$cid, $nm($cid), $n3($diff), '', '', '', '', $n3($gaps['cancelled'][$cid]['sum']), '',
                    'πληρωμές σε ' . $gaps['cancelled'][$cid]['n'] . ' ακυρωμένα παραστατικά'], ';');
            }
            if (!empty($gaps['unalloc'][$cid])) {
                fputcsv($f3, [$cid, $nm($cid), $n3($diff), '', '', '', '', $n3($gaps['unalloc'][$cid]), '',
                    'πληρωμές χωρίς παραστατικό'], ';');
            }
            if (!$rows && empty($gaps['cancelled'][$cid]['sum']) && empty($gaps['unalloc'][$cid])) {
                fputcsv($f3, [$cid, $nm($cid), $n3($diff), '', '', '', '', '', '', 'χωρίς εντοπισμένη αιτία'], ';');
            }
        }
    } elseif ($sc === 'overpaid') {
        fputcsv($f3, ['Παραστατικό', 'ID πελάτη', 'Πελάτης', 'Αξία', 'Εισπράχθηκαν', 'Πλήθος πληρωμών', 'Διαφορά', 'Τακτοποίηση'], ';');
        foreach (Capsule::select('SELECT invoiceid, COUNT(*) c, SUM(amountin) s FROM tblaccounts
                  WHERE gateway <> "" AND gateway IS NOT NULL AND amountin > 0 AND invoiceid > 0
                  GROUP BY invoiceid HAVING c > 1') as $r) {
            $i = Capsule::table('tblinvoices')->where('id', $r->invoiceid)->first();
            if (!$i) { continue; }
            $g = (float) ($i->subtotal + $i->tax + $i->tax2);
            if ((float) $r->s > $g + 0.01) {
                $cr = (float) Capsule::table('tblcredit')->where('clientid', $i->userid)->where('amount', '>', 0)
                    ->where('description', 'like', '%Invoice #' . $i->id . ' Overpayment%')->sum('amount');
                fputcsv($f3, [$i->invoicenum ?: '#' . $i->id, $i->userid, $nm((int) $i->userid),
                    $n3($g), $n3($r->s), $r->c, $n3((float) $r->s - $g),
                    $cr > 0 ? 'μετατράπηκε σε πίστωση' : 'ΕΚΚΡΕΜΕΙ'], ';');
            }
        }
    } elseif ($sc === 'legacy') {
        fputcsv($f3, ['Παραστατικό', 'ID πελάτη', 'Πελάτης', 'Ημερομηνία', 'Ημ. εξόφλησης',
            'Τρόπος πληρωμής', 'Αξία', 'Εισπράξεις + πίστωση', 'Από αυτά πίστωση', 'Λείπει'], ';');
        foreach (cnp_assumed_paid()['rows'] as $r) {
            fputcsv($f3, [$r['num'], $r['client'], $nm($r['client']), cnp_d($r['date']), cnp_d($r['datepaid']),
                $r['method'], $n3($r['gross']), $n3($r['paid']), $n3($r['credit']), $n3($r['gap'])], ';');
        }
    } elseif ($sc === 'zombie') {
        fputcsv($f3, ['Υπηρεσία', 'Domain', 'ID πελάτη', 'Πελάτης', 'Κατάσταση', 'Ποσό', 'Κύκλος', 'Συνδρομή',
            'Έγκυρη συνδρομή', 'Ημ. ακύρωσης', 'Πηγή ημερομηνίας', 'Πληρωμές συνδρομής',
            'Μετά την ακύρωση', 'Χωρίς παραστατικό', 'Αχρεωστήτως', 'Τελευταία πληρωμή', 'Ποσό'], ';');
        foreach (cnp_zombies($nm) as $z) {
            fputcsv($f3, [$z['service'], $z['domain'], $z['client'], $z['name'], $z['status'],
                $n3($z['amount']), $z['cycle'], $z['sub'], $z['realSub'] ? 'ΝΑΙ' : 'κατάλοιπο',
                cnp_d($z['cancel']), $z['cancelSrc'], $z['payN'],
                $n3($z['openAmt']), $n3($z['orphan']), $n3($z['openAmt'] + $z['orphan']),
                cnp_d($z['lastPay']), $z['lastAmt'] !== null ? $n3($z['lastAmt']) : ''], ';');
        }
    } else {
        fputcsv($f3, ['ID πελάτη', 'Πελάτης', 'Οφειλή', 'Ανεξόφλητα WHMCS'], ';');
        $d3 = [];
        $openBy2 = cnp_receivables();
        foreach (Capsule::table('tblclients')->where('status', 'Active')->pluck('id') as $cid) {
            $cid = (int) $cid;
            $b = round($openBy2[$cid] ?? 0, 2);
            if ($b > 1) { $d3[] = [$cid, $nm($cid), $b, $unpaidBy[$cid] ?? 0]; }
        }
        usort($d3, function ($a, $b) { return $b[2] <=> $a[2]; });
        foreach ($d3 as $r) { fputcsv($f3, [$r[0], $r[1], $n3($r[2]), $n3($r[3])], ';'); }
    }
    fclose($f3);
    exit;

case 'fin_audit':                        // Οικονομικοί έλεγχοι — τέσσερα σημεία κινδύνου
    $sec = (string) ($in['section'] ?? $_GET['section'] ?? '');

    /* Όλα με συγκεντρωτικά ερωτήματα, όχι βρόχους ανά πελάτη — αλλιώς η σελίδα
       αργεί με μερικές χιλιάδες παραστατικά. */
    $grossBy = []; $paidBy = []; $adjBy = []; $unpaidBy = [];
    foreach (Capsule::table('tblinvoices')->whereNotIn('status', ['Cancelled', 'Draft'])
                 ->selectRaw('userid, SUM(subtotal+tax+tax2) g')->groupBy('userid')->get() as $r) {
        $grossBy[(int) $r->userid] = (float) $r->g;
    }
    /* ΚΑΘΑΡΕΣ εισπράξεις: αφαιρούμε τις επιστροφές. Χωρίς αυτό ένα ποσό που
       γύρισε πίσω στον πελάτη μετριέται σαν να το κρατήσαμε. */
    foreach (Capsule::table('tblaccounts')->where('gateway', '!=', '')->whereNotNull('gateway')
                 ->selectRaw('userid, SUM(amountin) - SUM(amountout) p')->groupBy('userid')->get() as $r) {
        $paidBy[(int) $r->userid] = (float) $r->p;
    }
    // Τα σημασμένα «Paid» χωρίς γραμμή πληρωμής μετρούν ως εισπραγμένα.
    foreach (cnp_assumed_paid()['byClient'] as $uid => $amt) {
        $paidBy[$uid] = ($paidBy[$uid] ?? 0) + $amt;
    }
    foreach (Capsule::table('tblaccounts')->where('type', 'invoice_billing_adjustment_credit')
                 ->selectRaw('userid, SUM(amountin) a')->groupBy('userid')->get() as $r) {
        $adjBy[(int) $r->userid] = (float) $r->a;
    }
    foreach (Capsule::table('tblinvoices')->where('status', 'Unpaid')
                 ->selectRaw('userid, SUM(total) u')->groupBy('userid')->get() as $r) {
        $unpaidBy[(int) $r->userid] = (float) $r->u;
    }

    $nameOf = function ($id) {
        static $c = [];
        if (!isset($c[$id])) {
            $x = Capsule::table('tblclients')->where('id', $id)->first();
            $c[$id] = $x ? trim(($x->companyname ?: ($x->firstname . ' ' . $x->lastname))) : '#' . $id;
        }
        return $c[$id];
    };

    // ── 1. Ασυμφωνία βιβλίων: ο δικός μας υπολογισμός vs τα ανεξόφλητα του WHMCS
    $mismatch = [];
    $openBy = cnp_receivables();
    foreach ($grossBy as $cid => $g) {
        $mine  = round($openBy[$cid] ?? 0, 2);
        $whmcs = $unpaidBy[$cid] ?? 0;
        if (abs($mine - $whmcs) > 1) {
            $mismatch[] = ['client' => $cid, 'name' => $nameOf($cid),
                'mine' => round($mine, 2), 'whmcs' => round($whmcs, 2), 'diff' => round($mine - $whmcs, 2)];
        }
    }
    usort($mismatch, function ($a, $b) { return abs($b['diff']) <=> abs($a['diff']); });

    $gaps = cnp_book_gaps(array_column($mismatch, 'client'));
    foreach ($mismatch as $k => $m) {
        $rows = $gaps['inv'][$m['client']] ?? [];
        $mismatch[$k]['bad']  = array_slice($rows, 0, 8);
        $mismatch[$k]['badN'] = count($rows);
        $mismatch[$k]['unalloc'] = $gaps['unalloc'][$m['client']] ?? 0;
        $mismatch[$k]['onCancelled']  = $gaps['cancelled'][$m['client']]['sum'] ?? 0;
        $mismatch[$k]['onCancelledN'] = $gaps['cancelled'][$m['client']]['n'] ?? 0;
        $mismatch[$k]['oldest'] = $rows ? min(array_column($rows, 'date')) : null;
    }

    // ── 2. Υπερπληρωμένα παραστατικά
    $overpaid = [];
    foreach (Capsule::select('SELECT invoiceid, COUNT(*) c, SUM(amountin) s FROM tblaccounts
              WHERE gateway <> "" AND gateway IS NOT NULL AND amountin > 0 AND invoiceid > 0
              GROUP BY invoiceid HAVING c > 1') as $r) {
        $i = Capsule::table('tblinvoices')->where('id', $r->invoiceid)->first();
        if (!$i) { continue; }
        $g = (float) ($i->subtotal + $i->tax + $i->tax2);
        if ((float) $r->s > $g + 0.01) {
            /* Το WHMCS συνήθως μετατρέπει μόνο του το πλεόνασμα σε πίστωση
               («Invoice #X Overpayment» στο tblcredit) και αυτή ξοδεύεται σε
               επόμενα παραστατικά. Τότε δεν εκκρεμεί τίποτα — εκκρεμούν μόνο
               όσα δεν τακτοποιήθηκαν ποτέ. */
            $credited = (float) Capsule::table('tblcredit')->where('clientid', $i->userid)
                ->where('amount', '>', 0)->where('description', 'like', '%Invoice #' . $i->id . ' Overpayment%')
                ->sum('amount');
            $overpaid[] = ['invoice' => (int) $i->id, 'num' => (string) ($i->invoicenum ?: '#' . $i->id),
                'client' => (int) $i->userid, 'name' => $nameOf((int) $i->userid),
                'value' => round($g, 2), 'paid' => round((float) $r->s, 2),
                'n' => (int) $r->c, 'over' => round((float) $r->s - $g, 2),
                'credited' => round($credited, 2)];
        }
    }
    // Πρώτα όσα εκκρεμούν πραγματικά, μετά τα τακτοποιημένα.
    usort($overpaid, function ($a, $b) {
        return ($a['credited'] > 0) <=> ($b['credited'] > 0) ?: ($b['over'] <=> $a['over']);
    });

    // ── 3. Ζόμπι συνδρομές: ενεργή συνδρομή σε νεκρή υπηρεσία
    $zombie = cnp_zombies($nameOf);

    // ── 4. Πραγματικές οφειλές ενεργών πελατών
    $debt = [];
    $activeIds = Capsule::table('tblclients')->where('status', 'Active')->pluck('id')->all();
    foreach ($activeIds as $cid) {
        $cid = (int) $cid;
        $bal = round($openBy[$cid] ?? 0, 2);
        if ($bal > 1) {
            $debt[] = ['client' => $cid, 'name' => $nameOf($cid), 'balance' => round($bal, 2),
                'unpaid' => round($unpaidBy[$cid] ?? 0, 2)];
        }
    }
    usort($debt, function ($a, $b) { return $b['balance'] <=> $a['balance']; });

    /* ── 5. Σημασμένα «Paid» χωρίς αντιστοιχισμένη πληρωμή ─────────────────
       Δεν είναι οφειλή — είναι κατάλοιπο της χειροκίνητης εποχής. Μπαίνει σε
       δική του λίστα ώστε να διορθώνεται σιγά σιγά, χωρίς να μολύνει τα άλλα
       νούμερα. Τα φρέσκα είναι τα ενδιαφέροντα· γι' αυτό πρώτα τα πρόσφατα. */
    $legacy = [];
    foreach (cnp_assumed_paid()['rows'] as $r) {
        $r['name'] = $nameOf($r['client']);
        $legacy[] = $r;
    }

    $sum = [
        'legacy'   => ['n' => count($legacy), 'sum' => round(array_sum(array_column($legacy, 'gap')), 2)],
        'mismatch' => ['n' => count($mismatch), 'sum' => round(array_sum(array_map('abs', array_column($mismatch, 'diff'))), 2)],
        'overpaid' => ['n' => count(array_filter($overpaid, function ($o) { return $o['credited'] <= 0; })),
                       'sum' => round(array_sum(array_column(array_filter($overpaid, function ($o) { return $o['credited'] <= 0; }), 'over')), 2)],
        'zombie'   => ['n' => count($zombie),   'sum' => round(array_sum(array_column($zombie, 'openAmt'))
                                                    + array_sum(array_column($zombie, 'orphan')), 2)],
        'debt'     => ['n' => count($debt),     'sum' => round(array_sum(array_column($debt, 'balance')), 2)],
    ];

    $data = ['summary' => $sum];
    if ($sec === 'mismatch') { $data['rows'] = array_slice($mismatch, 0, 200); }
    elseif ($sec === 'overpaid') { $data['rows'] = array_slice($overpaid, 0, 200); }
    elseif ($sec === 'zombie')   { $data['rows'] = $zombie; }
    elseif ($sec === 'debt')     { $data['rows'] = array_slice($debt, 0, 200); }
    elseif ($sec === 'legacy')   { $data['rows'] = array_slice($legacy, 0, 300); }
    out($data);

case 'pay_statement_csv':                // Η καρτέλα σε CSV για το λογιστήριο
    $cid2 = (int) ($_GET['client'] ?? 0);
    $cl2 = $cid2 ? Capsule::table('tblclients')->where('id', $cid2)->first() : null;
    if (!$cl2) { fail('Ο πελάτης δεν βρέθηκε', 404); }

    $ev2 = [];
    foreach (Capsule::table('tblinvoices')->where('userid', $cid2)->whereNotIn('status', ['Draft'])->get() as $i) {
        $gr = (float) ($i->subtotal + $i->tax + $i->tax2);
        if ($i->status === 'Cancelled' || $gr <= 0) { continue; }
        $ev2[] = [substr($i->date, 0, 10), 'Παραστατικό ' . ($i->invoicenum ?: '#' . $i->id), $gr, 0.0, $i->status, ''];
    }
    foreach (Capsule::table('tblaccounts')->where('userid', $cid2)
                 ->where('gateway', '!=', '')->whereNotNull('gateway')->get() as $a) {
        if ((float) $a->amountin <= 0) { continue; }
        $iv = $a->invoiceid ? Capsule::table('tblinvoices')->where('id', $a->invoiceid)->first() : null;
        $ev2[] = [substr($a->date, 0, 10),
            'Πληρωμή ' . $a->gateway . ($iv ? ' — παρ. ' . ($iv->invoicenum ?: '#' . $iv->id) : ''),
            0.0, (float) $a->amountin, '', (string) $a->transid];
    }
    // Επιστροφές: χρήματα που γύρισαν στον πελάτη — χρεώνουν ξανά τον λογαριασμό.
    foreach (Capsule::table('tblaccounts')->where('userid', $cid2)
                 ->where('amountout', '>', 0)->where('refundid', '>', 0)->get() as $rf) {
        $iv = $rf->invoiceid ? Capsule::table('tblinvoices')->where('id', $rf->invoiceid)->first() : null;
        $ev2[] = [substr($rf->date, 0, 10),
            'Επιστροφή χρημάτων' . ($iv ? ' — παρ. ' . ($iv->invoicenum ?: '#' . $iv->id) : ''),
            (float) $rf->amountout, 0.0, '', (string) $rf->transid];
    }
    // Σημασμένα «Paid» χωρίς καταχωρημένη είσπραξη — θεωρούνται εξοφλημένα.
    $alloc2 = [];
    foreach (Capsule::table('tblaccounts')->where('userid', $cid2)->where('invoiceid', '>', 0)
                 ->selectRaw('invoiceid, SUM(amountin) - SUM(CASE WHEN refundid > 0 THEN amountout ELSE 0 END) p')
                 ->groupBy('invoiceid')->get() as $r) {
        $alloc2[(int) $r->invoiceid] = (float) $r->p;
    }
    foreach (Capsule::table('tblinvoices')->where('userid', $cid2)->where('status', 'Paid')->get() as $i) {
        $gap = round((float) ($i->subtotal + $i->tax + $i->tax2) - ($alloc2[(int) $i->id] ?? 0) - (float) $i->credit, 2);
        if ($gap <= 0.005) { continue; }
        $when = ($i->datepaid && strpos((string) $i->datepaid, '0000') !== 0) ? $i->datepaid : $i->date;
        $ev2[] = [substr((string) $when, 0, 10),
            'Εξόφληση χωρίς καταχωρημένη πληρωμή — παρ. ' . ($i->invoicenum ?: '#' . $i->id),
            0.0, $gap, 'σημασμένο Paid', ''];
    }

    usort($ev2, function ($x, $y) { $c = strcmp($x[0], $y[0]); return $c !== 0 ? $c : ($y[2] <=> $x[2]); });

    header('Content-Type: text/csv; charset=UTF-8');
    header('Content-Disposition: attachment; filename="kartela-' . $cid2 . '-' . date('Y-m-d') . '.csv"');
    $f2 = fopen('php://output', 'w');
    fwrite($f2, "\xEF\xBB\xBF");
    $n2 = function ($v) { return $v ? number_format((float) $v, 2, ',', '') : ''; };

    fputcsv($f2, ['Καρτέλα πελάτη', trim(($cl2->companyname ?: ($cl2->firstname . ' ' . $cl2->lastname)))], ';');
    fputcsv($f2, ['Υπεύθυνος', trim($cl2->firstname . ' ' . $cl2->lastname), 'Email', $cl2->email], ';');
    fputcsv($f2, [], ';');
    fputcsv($f2, ['Ημερομηνία', 'Κίνηση', 'Χρέωση', 'Πίστωση', 'Υπόλοιπο', 'Κατάσταση', 'Transaction ID'], ';');

    $b2 = 0.0; $d2 = 0.0; $c2 = 0.0;
    foreach ($ev2 as $e) {
        $b2 += $e[2] - $e[3];
        $d2 += $e[2];
        $c2 += $e[3];
        // Ταξινομήσαμε με ISO· στην έξοδο γράφουμε ηη/μμ/εεεε.
        fputcsv($f2, [cnp_d($e[0]), $e[1], $n2($e[2]), $n2($e[3]), number_format($b2, 2, ',', ''), $e[4], $e[5]], ';');
    }
    fputcsv($f2, [], ';');
    fputcsv($f2, ['ΣΥΝΟΛΑ', '', number_format($d2, 2, ',', ''), number_format($c2, 2, ',', ''),
        number_format($b2, 2, ',', '')], ';');
    fputcsv($f2, [$b2 > 0.005 ? 'ΟΦΕΙΛΗ ΠΕΛΑΤΗ' : ($b2 < -0.005 ? 'ΠΡΟΠΛΗΡΩΜΗ' : 'ΜΗΔΕΝΙΚΟ ΥΠΟΛΟΙΠΟ'), '', '', '',
        number_format(abs($b2), 2, ',', '')], ';');
    fclose($f2);
    exit;

case 'pay_statement':                    // Καρτέλα πελάτη: χρέωση / πίστωση / υπόλοιπο
    /* Η μόνη μορφή που διαβάζεται λογιστικά. ΧΡΕΩΣΗ = αξία παραστατικού,
       ΠΙΣΤΩΣΗ = πραγματικά χρήματα που μπήκαν. Οι εσωτερικές πιστώσεις ΔΕΝ
       μετριούνται — δεν είναι νέα χρήματα, απλώς μετακινούν υπάρχοντα, και
       αν τις μετρούσαμε θα διπλομετρούσαμε το ίδιο ποσό. */
    if (!$FULL) { fail('forbidden', 403); }
    $cid = (int) ($in['client'] ?? $_GET['client'] ?? 0);
    if (!$cid) { fail('Δώσε πελάτη'); }

    $cl = Capsule::table('tblclients')->where('id', $cid)->first();
    if (!$cl) { fail('Ο πελάτης δεν βρέθηκε', 404); }

    $ev = [];

    foreach (Capsule::table('tblinvoices')->where('userid', $cid)
                 ->whereNotIn('status', ['Draft'])->get() as $i) {
        $gross = (float) ($i->subtotal + $i->tax + $i->tax2);
        if ($i->status === 'Cancelled' || $gross <= 0) { continue; }
        $ev[] = [
            'date'   => $i->date,
            'sort'   => substr($i->date, 0, 10) . ' 00:00:00',
            'kind'   => 'invoice',
            'label'  => 'Παραστατικό ' . ($i->invoicenum ?: '#' . $i->id),
            'ref'    => (int) $i->id,
            'num'    => (string) ($i->invoicenum ?: ''),
            'debit'  => $gross,
            'credit' => 0.0,
            'note'   => $i->status,
        ];
    }

    /* Σημασμένο «Paid» χωρίς (πλήρη) καταχωρημένη είσπραξη: μπαίνει ως πίστωση,
       αλλιώς η καρτέλα δείχνει οφειλή για κάτι που έχει εξοφληθεί. Φαίνεται ως
       ξεχωριστή γραμμή, ώστε να είναι εμφανές ότι δεν υπάρχει παραστατικό
       πληρωμής από πίσω. */
    $allocIn = [];
    foreach (Capsule::table('tblaccounts')->where('userid', $cid)->where('invoiceid', '>', 0)
                 ->selectRaw('invoiceid, SUM(amountin) - SUM(CASE WHEN refundid > 0 THEN amountout ELSE 0 END) p')
                 ->groupBy('invoiceid')->get() as $r) {
        $allocIn[(int) $r->invoiceid] = (float) $r->p;
    }
    foreach (Capsule::table('tblinvoices')->where('userid', $cid)->where('status', 'Paid')->get() as $i) {
        $gap = round((float) ($i->subtotal + $i->tax + $i->tax2) - ($allocIn[(int) $i->id] ?? 0) - (float) $i->credit, 2);
        if ($gap <= 0.005) { continue; }
        $when = ($i->datepaid && strpos((string) $i->datepaid, '0000') !== 0) ? $i->datepaid : $i->date;
        $ev[] = [
            'date' => $when, 'sort' => $when, 'kind' => 'assumed',
            'label' => 'Εξόφληση χωρίς καταχωρημένη πληρωμή — παρ. ' . ($i->invoicenum ?: '#' . $i->id),
            'ref' => (int) $i->id, 'num' => (string) ($i->invoicenum ?: ''),
            'debit' => 0.0, 'credit' => $gap, 'note' => 'σημασμένο Paid',
        ];
    }

    foreach (Capsule::table('tblaccounts')->where('userid', $cid)
                 ->where('gateway', '!=', '')->whereNotNull('gateway')->get() as $a) {
        if ((float) $a->amountin <= 0) { continue; }
        $inv = $a->invoiceid ? Capsule::table('tblinvoices')->where('id', $a->invoiceid)->first() : null;
        $ev[] = [
            'date'   => $a->date,
            'sort'   => $a->date,
            'kind'   => 'payment',
            'label'  => 'Πληρωμή ' . $a->gateway . ($inv ? ' — παρ. ' . ($inv->invoicenum ?: '#' . $inv->id) : ''),
            'ref'    => (int) $a->invoiceid,
            'num'    => (string) ($inv->invoicenum ?? ''),
            'debit'  => 0.0,
            'credit' => (float) $a->amountin,
            'note'   => (string) $a->transid,
        ];
    }

    // Επιστροφές: χρήματα που γύρισαν στον πελάτη — χρεώνουν ξανά τον λογαριασμό.
    foreach (Capsule::table('tblaccounts')->where('userid', $cid)
                 ->where('amountout', '>', 0)->where('refundid', '>', 0)->get() as $rf) {
        $iv = $rf->invoiceid ? Capsule::table('tblinvoices')->where('id', $rf->invoiceid)->first() : null;
        $ev[] = [
            'date' => $rf->date, 'sort' => $rf->date, 'kind' => 'refund',
            'label' => 'Επιστροφή χρημάτων' . ($iv ? ' — παρ. ' . ($iv->invoicenum ?: '#' . $iv->id) : ''),
            'ref' => (int) $rf->invoiceid, 'num' => (string) ($iv->invoicenum ?? ''),
            'debit' => (float) $rf->amountout, 'credit' => 0.0, 'note' => (string) $rf->transid,
        ];
    }

    usort($ev, function ($x, $y) {
        $c = strcmp($x['sort'], $y['sort']);
        // Ίδια μέρα: πρώτα η χρέωση, μετά η πίστωση — έτσι διαβάζεται σωστά.
        return $c !== 0 ? $c : ($y['debit'] <=> $x['debit']);
    });

    $bal = 0.0; $td = 0.0; $tc = 0.0;
    foreach ($ev as $k => $e) {
        $bal += $e['debit'] - $e['credit'];
        $td += $e['debit'];
        $tc += $e['credit'];
        $ev[$k]['balance'] = round($bal, 2);
    }

    out([
        'client'  => ['id' => $cid, 'name' => trim(($cl->companyname ?: ($cl->firstname . ' ' . $cl->lastname))),
                      'person' => trim($cl->firstname . ' ' . $cl->lastname), 'email' => $cl->email],
        'rows'    => $ev,
        'debit'   => round($td, 2),
        'credit'  => round($tc, 2),
        'balance' => round($bal, 2),
    ]);

case 'pay_trace_export':                 // Εξαγωγή συμφωνίας σε CSV για το λογιστήριο
    $qx  = trim((string) ($_GET['q'] ?? ''));
    $all = !empty($_GET['all']);
    $from = trim((string) ($_GET['from'] ?? ''));
    $to   = trim((string) ($_GET['to'] ?? ''));

    // Μόνο πραγματικές εισπράξεις μέσω gateway — όχι εσωτερικές πιστώσεις.
    $qb = Capsule::table('tblaccounts')->where('gateway', '!=', '')->whereNotNull('gateway');
    if ($from !== '') { $qb->where('date', '>=', $from . ' 00:00:00'); }
    if ($to !== '')   { $qb->where('date', '<=', $to . ' 23:59:59'); }
    if (!$all && $qx !== '') {
        $ids = [];
        foreach (Capsule::table('tblgatewaylog')->where('data', 'like', '%' . $qx . '%')->limit(500)->get() as $g) {
            if (preg_match('/(?:^|\n)\s*txn_id\s*=>\s*(\S+)/', (string) $g->data, $m)) { $ids[] = trim($m[1]); }
        }
        $qb->where(function ($w) use ($qx, $ids) {
            $w->where('transid', 'like', '%' . $qx . '%')->orWhere('description', 'like', '%' . $qx . '%');
            if ($ids) { $w->orWhereIn('transid', $ids); }
        });
    }

    $rowsX = $qb->orderBy('date')->get();

    // Μαζική ανάγνωση των IPN: το email του πληρωτή δεν υπάρχει πουθενά αλλού.
    $payerOf = [];
    $typeOf  = [];
    foreach ($rowsX as $a) {
        if (!$a->transid) { continue; }
        $g = Capsule::table('tblgatewaylog')->where('data', 'like', '%' . $a->transid . '%')->first();
        if (!$g) { continue; }
        if (preg_match('/(?:^|\n)\s*payer_email\s*=>\s*([^\n]*)/', (string) $g->data, $m)) { $payerOf[$a->transid] = trim($m[1]); }
        if (preg_match('/(?:^|\n)\s*txn_type\s*=>\s*([^\n]*)/', (string) $g->data, $m))    { $typeOf[$a->transid]  = trim($m[1]); }
    }

    $name = 'symfonia-pliromon-' . date('Y-m-d') . '.csv';
    header('Content-Type: text/csv; charset=UTF-8');
    header('Content-Disposition: attachment; filename="' . $name . '"');

    $fh = fopen('php://output', 'w');
    fwrite($fh, "\xEF\xBB\xBF");            // BOM — αλλιώς το Excel δείχνει κινέζικα στα ελληνικά

    $num = function ($v) { return number_format((float) $v, 2, ',', ''); };   // ελληνικό δεκαδικό
    $types = ['subscr_payment' => 'Συνδρομή', 'web_accept' => 'Χειροκίνητη', 'express_checkout' => 'Express'];

    fputcsv($fh, ['Ημερομηνία', 'Ώρα', 'Ποσό', 'Προμήθεια', 'Καθαρό', 'Τρόπος πληρωμής', 'Τύπος',
        'Πληρωτής (email)', 'Transaction ID', 'ID πελάτη', 'Επωνυμία', 'Υπεύθυνος', 'Email πελάτη',
        'Παραστατικό', 'Ημ. παραστατικού', 'Ποσό παραστατικού', 'Πίστωση στο παραστατικό',
        'Υπόλοιπο', 'Κατάσταση', 'Υπερπληρωμή προς', 'Ποσό υπερπληρωμής'], ';');

    $tot = 0; $totFee = 0;
    foreach ($rowsX as $a) {
        $cl  = Capsule::table('tblclients')->where('id', $a->userid)->first();
        $inv = $a->invoiceid ? Capsule::table('tblinvoices')->where('id', $a->invoiceid)->first() : null;
        $tt  = $typeOf[$a->transid] ?? '';
        $onward = ($a->userid && $a->invoiceid)
            ? (cnp_credit_chain((int) $a->userid)[(int) $a->invoiceid] ?? []) : [];
        $tot += (float) $a->amountin;
        $totFee += (float) $a->fees;

        fputcsv($fh, [
            cnp_d($a->date), substr($a->date, 11, 5),
            $num($a->amountin), $num($a->fees), $num((float) $a->amountin - (float) $a->fees),
            $a->gateway,
            $types[$tt] ?? $tt,
            $payerOf[$a->transid] ?? '',
            $a->transid,
            $a->userid,
            $cl->companyname ?? '',
            $cl ? trim($cl->firstname . ' ' . $cl->lastname) : '',
            $cl->email ?? '',
            $inv->invoicenum ?? '',
            $inv ? cnp_d($inv->date) : '',
            $inv ? $num($inv->subtotal + $inv->tax + $inv->tax2) : '',
            $inv ? $num($inv->credit) : '',
            $inv ? $num($inv->total) : '',
            $inv->status ?? '',
            implode(' + ', array_map(function ($x) { return $x['num']; }, $onward)),
            implode(' + ', array_map(function ($x) use ($num) { return $num($x['amount']); }, $onward)),
        ], ';');
    }

    fputcsv($fh, [], ';');
    fputcsv($fh, ['ΣΥΝΟΛΟ', '', $num($tot), $num($totFee), $num($tot - $totFee)], ';');
    fclose($fh);
    exit;

case 'pay_trace':                        // Συμφωνία πληρωμών: πού πήγε κάθε είσπραξη
    /* ΓΙΑΤΙ ΥΠΑΡΧΕΙ: ένας λογαριασμός PayPal μπορεί να πληρώνει ΠΟΛΛΟΥΣ πελάτες
       WHMCS, και ένας πελάτης να πληρώνεται από πολλά πρόσωπα. Η αντιστοίχιση
       είναι πολλά-προς-πολλά και χειροκίνητα παίρνει ώρες. */
    $q = trim((string) ($in['q'] ?? $_GET['q'] ?? ''));
    if (mb_strlen($q) < 3) { fail('Δώσε email πληρωτή, transaction ID, ποσό ή όνομα (3+ χαρακτήρες)'); }

    $rows = [];
    $seen = [];

    // 1) Άμεση αναζήτηση στις κινήσεις (transid, περιγραφή)
    $direct = Capsule::table('tblaccounts')
        ->where(function ($w) use ($q) {
            $w->where('transid', 'like', '%' . $q . '%')->orWhere('description', 'like', '%' . $q . '%');
        })->orderBy('date', 'desc')->limit(200)->get();

    // 2) Αναζήτηση στα logs των gateways — εκεί ζει το email του πληρωτή
    $viaLog = [];
    foreach (Capsule::table('tblgatewaylog')->where('data', 'like', '%' . $q . '%')
                 ->orderBy('date', 'desc')->limit(300)->get() as $g) {
        if (preg_match('/(?:^|\n)\s*txn_id\s*=>\s*(\S+)/', (string) $g->data, $m)) {
            $viaLog[trim($m[1])] = $g;
        }
    }
    if ($viaLog) {
        foreach (Capsule::table('tblaccounts')->whereIn('transid', array_keys($viaLog))->get() as $a) {
            $direct->push($a);
        }
    }

    // 3) Αν μοιάζει με ποσό, ψάξε και με ποσό
    if (preg_match('/^\d+([.,]\d{1,2})?$/', $q)) {
        $amt = (float) str_replace(',', '.', $q);
        foreach (Capsule::table('tblaccounts')->whereBetween('amountin', [$amt - 0.02, $amt + 0.02])
                     ->orderBy('date', 'desc')->limit(100)->get() as $a) {
            $direct->push($a);
        }
    }

    foreach ($direct as $a) {
        if (isset($seen[$a->id])) { continue; }
        $seen[$a->id] = true;

        $cl  = Capsule::table('tblclients')->where('id', $a->userid)->first();
        $inv = $a->invoiceid ? Capsule::table('tblinvoices')->where('id', $a->invoiceid)->first() : null;

        // Στοιχεία πληρωτή από το IPN — δείχνουν ΠΟΙΟΣ πλήρωσε στ' αλήθεια
        $payer = null; $ptype = null;
        if ($a->transid && isset($viaLog[$a->transid])) {
            $g = $viaLog[$a->transid];
        } else {
            $g = $a->transid
                ? Capsule::table('tblgatewaylog')->where('data', 'like', '%' . $a->transid . '%')->first()
                : null;
        }
        if ($g) {
            foreach (['payer_email', 'txn_type'] as $k) {
                if (preg_match('/(?:^|\n)\s*' . $k . '\s*=>\s*([^\n]*)/', (string) $g->data, $m)) {
                    if ($k === 'payer_email') { $payer = trim($m[1]); } else { $ptype = trim($m[1]); }
                }
            }
        }

        $rows[] = [
            'id'       => (int) $a->id,
            'date'     => $a->date,
            'amount'   => (float) $a->amountin,
            'fees'     => (float) $a->fees,
            'gateway'  => (string) $a->gateway,
            'transid'  => (string) $a->transid,
            'kind'     => (string) $a->type,
            'payer'    => $payer,
            'ptype'    => $ptype,
            'clientId' => (int) $a->userid ?: null,
            'client'   => $cl ? trim(($cl->companyname ?: ($cl->firstname . ' ' . $cl->lastname))) : null,
            'person'   => $cl ? trim($cl->firstname . ' ' . $cl->lastname) : null,
            'email'    => $cl->email ?? null,
            'invoiceId' => (int) $a->invoiceid ?: null,
            'invoice'  => $inv->invoicenum ?? null,
            // ΠΡΟΣΟΧΗ: το tblinvoices.total είναι το ΥΠΟΛΟΙΠΟ μετά την πίστωση,
            // όχι το ποσό του παραστατικού. Το πραγματικό ποσό είναι subtotal+ΦΠΑ.
            'invTotal' => $inv ? (float) ($inv->subtotal + $inv->tax + $inv->tax2) : null,
            'invDue'   => $inv ? (float) $inv->total : null,
            'invCredit' => $inv ? (float) $inv->credit : null,
            'invStatus' => $inv->status ?? null,
            'refunded' => (bool) Capsule::table('tblaccounts')->where('refundid', $a->id)->exists(),
            // Αν αυτή η είσπραξη δημιούργησε πίστωση, πού πήγε τελικά
            'onward'   => ($a->userid && $a->invoiceid)
                ? (cnp_credit_chain((int) $a->userid)[(int) $a->invoiceid] ?? [])
                : [],
        ];
    }

    usort($rows, function ($x, $y) { return strcmp($y['date'], $x['date']); });
    $rows = array_slice($rows, 0, 150);

    // Σύνοψη ανά πελάτη — η απάντηση στο «πού πήγαν τα λεφτά»
    $byClient = [];
    foreach ($rows as $r) {
        $k = $r['clientId'] ?: 0;
        if (!isset($byClient[$k])) {
            $byClient[$k] = ['id' => $r['clientId'], 'client' => $r['client'] ?: '(χωρίς πελάτη)', 'n' => 0, 'sum' => 0.0];
        }
        $byClient[$k]['n']++;
        $byClient[$k]['sum'] += $r['amount'];
    }
    usort($byClient, function ($x, $y) { return $y['sum'] <=> $x['sum']; });

    out(['q' => $q, 'rows' => $rows, 'byClient' => array_values($byClient),
         'total' => array_sum(array_column($rows, 'amount'))]);

case 'cv_job_views':                     // επισκεψιμότητα αγγελιών (ανεξάρτητα από αιτήσεις)
    require_once __DIR__ . '/../modules/addons/cloudonprojects/lib/JobViews.php';
    $vDays = max(1, min(365, (int) ($in['days'] ?? 30)));
    $vStats = WHMCS\Module\Addon\CloudonProjects\JobViews::stats($vDays);
    $vRows = [];
    foreach (Capsule::table('mod_cpm_cv_jobs')->orderByDesc('active')->orderBy('title')->get() as $jb) {
        $s = $vStats[(int) $jb->id] ?? ['views' => 0, 'forms' => 0, 'uniques' => 0, 'last_at' => null];
        // Αιτήσεις της περιόδου, για να συγκρίνεται με τις προβολές της ίδιας περιόδου.
        $apps = (int) Capsule::table('mod_cpm_cv')->where('job_id', $jb->id)
            ->where('created_at', '>=', date('Y-m-d 00:00:00', strtotime('-' . $vDays . ' days')))->count();
        $vRows[] = [
            'id'       => (int) $jb->id,
            'title'    => $jb->title,
            'active'   => (bool) $jb->active,
            'views'    => $s['views'],
            'uniques'  => $s['uniques'],
            'forms'    => $s['forms'],
            'apps'     => $apps,
            'appsAll'  => (int) Capsule::table('mod_cpm_cv')->where('job_id', $jb->id)->count(),
            'lastAt'   => $s['last_at'],
            'series'   => array_values(WHMCS\Module\Addon\CloudonProjects\JobViews::daily((int) $jb->id, min(30, $vDays))),
        ];
    }
    $vPage = $vStats[0] ?? ['views' => 0, 'uniques' => 0];
    out([
        'days'      => $vDays,
        'rows'      => $vRows,
        'page'      => ['views' => $vPage['views'], 'uniques' => $vPage['uniques'],
                        'series' => array_values(WHMCS\Module\Addon\CloudonProjects\JobViews::daily(0, min(30, $vDays)))],
        'breakdown' => WHMCS\Module\Addon\CloudonProjects\JobViews::breakdown($vDays),
    ]);

case 'cv_job_save':                      // δημιουργία/επεξεργασία αγγελίας
    $title = mb_substr(trim($in['title'] ?? ''), 0, 190);
    if ($title === '') { fail('Δώσε τίτλο θέσης'); }
    $sections = (isset($in['sections']) && is_array($in['sections'])) ? $in['sections'] : null;
    $data = ['title' => $title, 'descr' => mb_substr(trim($in['descr'] ?? ''), 0, 12000),
        'skills' => mb_substr(trim($in['skills'] ?? ''), 0, 3000), 'location' => mb_substr(trim($in['location'] ?? ''), 0, 120),
        'emptype' => mb_substr(trim($in['emptype'] ?? ''), 0, 40), 'active' => !empty($in['active']) ? 1 : 0,
        'title_en' => mb_substr(trim($in['titleEn'] ?? ''), 0, 190), 'descr_en' => mb_substr(trim($in['descrEn'] ?? ''), 0, 12000),
        'skills_en' => mb_substr(trim($in['skillsEn'] ?? ''), 0, 3000), 'emptype_en' => mb_substr(trim($in['emptypeEn'] ?? ''), 0, 40),
        'image' => (array_key_exists($in['image'] ?? '', cnp_cv_job_presets())
            || cnp_cv_job_image_is_custom($in['image'] ?? '')) ? $in['image'] : '',
        'descr_json' => $sections ? mb_substr(json_encode($sections, JSON_UNESCAPED_UNICODE), 0, 30000) : null];
    $id = (int) ($in['id'] ?? 0);
    if ($id) { Capsule::table('mod_cpm_cv_jobs')->where('id', $id)->update($data); }
    else { $data['created_at'] = date('Y-m-d H:i:s'); $id = Capsule::table('mod_cpm_cv_jobs')->insertGetId($data); }
    out(['ok' => true, 'id' => $id]);

case 'cv_job_image_upload':              // ανέβασμα δικής μας φωτογραφίας θέσης
    $f = $_FILES['file'] ?? null;
    if (!$f || ($f['error'] ?? 1) !== UPLOAD_ERR_OK) { fail('Δεν ανέβηκε αρχείο.'); }
    if ($f['size'] > 8 * 1024 * 1024) { fail('Το αρχείο ξεπερνά τα 8 MB.'); }
    $info = @getimagesize($f['tmp_name']);
    if (!$info) { fail('Το αρχείο δεν είναι έγκυρη εικόνα.'); }
    $allowed = [IMAGETYPE_JPEG => 1, IMAGETYPE_PNG => 1, IMAGETYPE_WEBP => 1];
    if (!isset($allowed[$info[2]])) { fail('Επιτρέπονται JPG, PNG ή WebP.'); }

    $src = null;
    if ($info[2] === IMAGETYPE_JPEG) { $src = @imagecreatefromjpeg($f['tmp_name']); }
    elseif ($info[2] === IMAGETYPE_PNG) { $src = @imagecreatefrompng($f['tmp_name']); }
    elseif ($info[2] === IMAGETYPE_WEBP && function_exists('imagecreatefromwebp')) { $src = @imagecreatefromwebp($f['tmp_name']); }
    if (!$src) { fail('Δεν ήταν δυνατή η επεξεργασία της εικόνας.'); }

    // Cover 1600×900 (16:9 — πρακτικά ίδια αναλογία με τις έτοιμες 900×520)
    // center crop χωρίς παραμόρφωση.
    $tw = 1600; $th = 900;
    $sw = imagesx($src); $sh = imagesy($src);
    $scale = max($tw / $sw, $th / $sh);
    $nw = (int) ceil($sw * $scale); $nh = (int) ceil($sh * $scale);
    $dst = imagecreatetruecolor($tw, $th);
    imagecopyresampled($dst, $src, (int) (($tw - $nw) / 2), (int) (($th - $nh) / 2), 0, 0, $nw, $nh, $sw, $sh);
    imagedestroy($src);

    $dir = cnp_cv_job_custom_dir();
    if (!is_dir($dir) && !@mkdir($dir, 0755, true)) { imagedestroy($dst); fail('Ο φάκελος εικόνων δεν είναι εγγράψιμος.'); }
    $stem = 'job-' . date('Ymd') . '-' . bin2hex(random_bytes(4));
    $path = $dir . '/' . $stem . '.jpg';
    $okw = imagejpeg($dst, $path, 82);
    imagedestroy($dst);
    if (!$okw) { fail('Αποτυχία αποθήκευσης.'); }
    @chmod($path, 0644);
    out(['ok' => true, 'image' => 'custom/' . $stem]);

case 'cv_job_image_delete':              // διαγραφή ανεβασμένης φωτογραφίας
    $img = (string) ($in['image'] ?? '');
    if (!cnp_cv_job_image_is_custom($img)) { fail('Μη έγκυρη εικόνα.'); }
    // Μην τη σβήσεις αν τη χρησιμοποιεί θέση.
    $used = (int) Capsule::table('mod_cpm_cv_jobs')->where('image', $img)->count();
    if ($used > 0) { fail('Χρησιμοποιείται από ' . $used . ' θέση/θέσεις.'); }
    @unlink(__DIR__ . '/apply-assets/jobs/' . $img . '.jpg');
    out(['ok' => true]);

case 'cv_job_del':                       // διαγραφή (ή αρχειοθέτηση αν έχει υποψηφίους)
    $id = (int) ($in['id'] ?? 0);
    $cnt = (int) Capsule::table('mod_cpm_cv')->where('job_id', $id)->count();
    if ($cnt > 0) {
        Capsule::table('mod_cpm_cv_jobs')->where('id', $id)->update(['active' => 0]);
        out(['ok' => true, 'archived' => true, 'msg' => 'Έχει ' . $cnt . ' υποψηφίους — απενεργοποιήθηκε αντί διαγραφής']);
    }
    Capsule::table('mod_cpm_cv_jobs')->where('id', $id)->delete();
    out(['ok' => true, 'deleted' => true]);

case 'cv_job_draft':                     // ✨ AI σύνταξη δομημένης ΔΙΓΛΩΣΣΗΣ αγγελίας
    $title = mb_substr(trim($in['title'] ?? ''), 0, 190);
    if ($title === '') { fail('Δώσε πρώτα τίτλο θέσης'); }
    $key = trim(Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')->where('setting', 'ai_api_key')->value('value') ?: '');
    if ($key === '') { fail('Δεν έχει οριστεί κλειδί AI (Ρυθμίσεις → AI)'); }
    $skills = mb_substr(trim($in['skills'] ?? ''), 0, 2000);
    $loc = mb_substr(trim($in['location'] ?? ''), 0, 120);
    $emp = mb_substr(trim($in['emptype'] ?? ''), 0, 40);
    $hint = mb_substr(trim($in['hint'] ?? ''), 0, 1500);
    $mode = ($in['mode'] ?? '') === 'translate' ? 'translate' : 'draft';   // translate: μεταφράζει υπάρχον EL→EN
    if ($mode === 'translate') {
        $src = mb_substr(trim($in['descr'] ?? ''), 0, 12000);
        if ($src === '') { fail('Δεν υπάρχει ελληνικό κείμενο για μετάφραση'); }
        $prompt = "Μετάφρασε την παρακάτω αγγελία εργασίας από τα Ελληνικά στα Αγγλικά, διατηρώντας ΑΚΡΙΒΩΣ την ίδια δομή "
            . "(εισαγωγή, αρμοδιότητες, προσόντα, παροχές) σε επαγγελματικό ύφος.\n\nΤίτλος: {$title}\n\nΚείμενο:\n{$src}\n\n"
            . "Δώσε επίσης τον τίτλο & τα skills στα Αγγλικά. Απάντησε ΜΟΝΟ με JSON: "
            . "{\"en\":{\"title\":\"...\",\"intro\":\"...\",\"responsibilities\":[\"..\"],\"requirements\":[\"..\"],\"benefits\":[\"..\"],\"skills\":\"a, b, c\"}}";
    } else {
        $prompt = "Είσαι HR copywriter της CloudOn (πάροχος cloud/IT υπηρεσιών, έδρα Αθήνα). "
            . "Σύνταξε ελκυστική, ΑΝΑΛΥΤΙΚΗ, επαγγελματική αγγελία εργασίας για την παρακάτω θέση, ΚΑΙ στα Ελληνικά ΚΑΙ στα Αγγλικά.\n\n"
            . "Τίτλος: {$title}\n" . ($loc ? "Τοποθεσία: {$loc}\n" : '') . ($emp ? "Τύπος: {$emp}\n" : '')
            . ($skills ? "Δεξιότητες/απαιτήσεις: {$skills}\n" : '') . ($hint ? "Επιπλέον οδηγίες: {$hint}\n" : '')
            . "\nΚάθε γλώσσα να έχει: intro (2-4 προτάσεις για τη θέση & την ομάδα), responsibilities (5-8 αρμοδιότητες), "
            . "requirements (5-8 προσόντα/δεξιότητες), benefits (4-6 παροχές/ευκαιρίες εξέλιξης). Αναλυτικά & συγκεκριμένα, ΟΧΙ γενικόλογα. "
            . "Πρότεινε και 6-12 skills (comma-separated). Καθαρό κείμενο, ΟΧΙ markdown/αστεράκια.\n\n"
            . "Απάντησε ΜΟΝΟ με έγκυρο JSON: {\"el\":{\"intro\":\"..\",\"responsibilities\":[\"..\"],\"requirements\":[\"..\"],\"benefits\":[\"..\"],\"skills\":\"..\"},"
            . "\"en\":{\"title\":\"english title\",\"intro\":\"..\",\"responsibilities\":[\"..\"],\"requirements\":[\"..\"],\"benefits\":[\"..\"],\"skills\":\"..\"}}";
    }
    $res = cnp_anthropic($key, cnp_cv_default_model(), [['type' => 'text', 'text' => $prompt]], 4000);
    if (!$res['ok']) { fail($res['error']); }
    $d = cnp_json_extract($res['text']);
    if (!$d || (empty($d['el']) && empty($d['en']))) { fail('Η AI επέστρεψε μη έγκυρη απάντηση — δοκίμασε ξανά'); }
    out(['ok' => true, 'sections' => $d]);

case 'cv_list':
    $job = (int) ($_GET['job'] ?? 0); $status = $_GET['status'] ?? ''; $sq = trim($_GET['q'] ?? '');
    $dupsOnly = !empty($_GET['dups']);
    // emails που εμφανίζονται >1 φορά (διπλότυπα, χωρίς διαγραφή)
    $dupEmails = [];
    foreach (Capsule::table('mod_cpm_cv')->whereRaw("TRIM(email) <> ''")
        ->groupByRaw('LOWER(TRIM(email))')->havingRaw('COUNT(*) > 1')
        ->selectRaw('LOWER(TRIM(email)) e, COUNT(*) c')->get() as $de) { $dupEmails[$de->e] = (int) $de->c; }
    $applyBase = function ($q) use ($job, $sq, $dupsOnly, $dupEmails) {
        if ($job) { $q->where('job_id', $job); }
        if (mb_strlen($sq) >= 2) {
            $like = '%' . $sq . '%';
            $q->where(function ($w) use ($like) {
                $w->where('name', 'like', $like)->orWhere('email', 'like', $like)->orWhere('phone', 'like', $like)->orWhere('job_title', 'like', $like);
            });
        }
        if ($dupsOnly) { $q->whereIn(Capsule::raw('LOWER(TRIM(email))'), array_keys($dupEmails) ?: ['']); }
        return $q;
    };
    // πλήθη ανά στάδιο (με φίλτρο θέσης/αναζήτησης)
    $counts = [];
    foreach ($applyBase(Capsule::table('mod_cpm_cv'))->groupBy('status')->selectRaw('status, COUNT(*) c')->get() as $c) { $counts[$c->status] = (int) $c->c; }
    $totalAll = array_sum($counts);
    // σελιδοποίηση
    $per = in_array((int) ($_GET['per'] ?? 0), [25, 50, 100, 200], true) ? (int) $_GET['per'] : 50;
    $page = max(1, (int) ($_GET['page'] ?? 1));
    $lq = $applyBase(Capsule::table('mod_cpm_cv'));
    if ($status !== '') { $lq->where('status', $status); }
    $filtered = (clone $lq)->count();
    $pages = max(1, (int) ceil($filtered / $per));
    if ($page > $pages) { $page = $pages; }
    $rows = $lq->orderByDesc('applied_at')->orderByDesc('id')->offset(($page - 1) * $per)->limit($per)->get();
    $items = [];
    foreach ($rows as $r) {
        $ai = $r->ai_json ? json_decode($r->ai_json, true) : null;
        $items[] = ['id' => (int) $r->id, 'name' => $r->name, 'email' => $r->email, 'phone' => $r->phone,
            'jobTitle' => $r->job_title, 'status' => $r->status, 'rating' => (int) $r->rating,
            'aiScore' => $r->ai_score !== null ? (int) $r->ai_score : null,
            'fit' => $ai['fit'] ?? null, 'category' => $ai['category'] ?? null, 'seniority' => $ai['seniority'] ?? null,
            'decision' => $ai['decision'] ?? null, 'aiGen' => isset($ai['aiGenerated']['verdict']) ? $ai['aiGenerated']['verdict'] : null,
            'hasCv' => ($r->cv_stored !== '' || !empty($r->cv_storage_id)), 'photo' => ($r->photo !== '' || !empty($r->photo_storage_id)),
            'dup' => (trim($r->email) !== '' && isset($dupEmails[mb_strtolower(trim($r->email))])) ? $dupEmails[mb_strtolower(trim($r->email))] : 0,
            'assignee' => $r->assignee ? (int) $r->assignee : null, 'source' => $r->source, 'appliedAt' => $r->applied_at];
    }
    out(['items' => $items, 'counts' => $counts, 'totalAll' => $totalAll, 'filtered' => $filtered,
        'dupTotal' => array_sum($dupEmails), 'page' => $page, 'per' => $per, 'pages' => $pages, 'statuses' => cnp_cv_statuses()]);

case 'cv_get':
    $r = Capsule::table('mod_cpm_cv')->where('id', (int) ($_GET['id'] ?? 0))->first();
    if (!$r) { fail('notfound', 404); }
    $ai = $r->ai_json ? json_decode($r->ai_json, true) : null;
    out(['id' => (int) $r->id, 'name' => $r->name, 'email' => $r->email, 'phone' => $r->phone,
        'jobTitle' => $r->job_title, 'jobId' => $r->job_id ? (int) $r->job_id : null, 'letter' => $r->letter,
        'status' => $r->status, 'rating' => (int) $r->rating, 'notes' => $r->notes,
        'assignee' => $r->assignee ? (int) $r->assignee : null, 'aiScore' => $r->ai_score !== null ? (int) $r->ai_score : null, 'ai' => $ai, 'aiModel' => $r->ai_model,
        'interview' => $r->interview_json ? json_decode($r->interview_json, true) : null,
        'interviewEval' => $r->interview_eval ? json_decode($r->interview_eval, true) : null,
        'interviewAt' => $r->interview_at,
        'others' => (function ($r) {
            $out = [];
            if (trim($r->email) === '') { return $out; }
            foreach (Capsule::table('mod_cpm_cv')->whereRaw('LOWER(TRIM(email)) = ?', [mb_strtolower(trim($r->email))])
                ->where('id', '<>', $r->id)->orderByDesc('applied_at')->limit(20)->get() as $o) {
                $out[] = ['id' => (int) $o->id, 'name' => $o->name, 'jobTitle' => $o->job_title, 'status' => $o->status,
                    'aiScore' => $o->ai_score !== null ? (int) $o->ai_score : null, 'appliedAt' => $o->applied_at];
            }
            return $out;
        })($r),
        'comms' => (function ($cid) {
            $out = [];
            foreach (Capsule::table('mod_cpm_cv_comms')->where('cv_id', $cid)->orderByDesc('id')->limit(30)->get() as $cm) {
                $out[] = ['kind' => $cm->kind, 'subject' => $cm->subject, 'body' => $cm->body, 'by' => Db::adminName($cm->by), 'at' => $cm->created_at];
            }
            return $out;
        })((int) $r->id),
        'hasCv' => ($r->cv_stored !== '' || !empty($r->cv_storage_id)), 'photo' => ($r->photo !== '' || !empty($r->photo_storage_id)), 'cvName' => $r->cv_name, 'cvMime' => $r->cv_mime, 'source' => $r->source, 'appliedAt' => $r->applied_at]);

case 'cv_photo':                         // headshot thumbnail (auth + hr)
    $r = Capsule::table('mod_cpm_cv')->where('id', (int) ($_GET['id'] ?? 0))->first();
    if (!$r || !$r->photo) { fail('img', 404); }
    if (!empty($r->photo_storage_id)) {                     // migrated → S3/local via Storage
        $sr = Storage::record((int) $r->photo_storage_id);
        if ($sr && $sr['driver'] === 's3') { header('Location: ' . Storage::presign($sr['id'], 300), true, 302); exit; }
        if ($sr) { $st = Storage::openRead($sr['id']); if ($st) { header('Content-Type: image/jpeg'); header('X-Content-Type-Options: nosniff'); header('Cache-Control: private, max-age=86400'); fpassthru($st); fclose($st); exit; } }
    }
    $path = realpath(__DIR__ . '/../attachments/cloudonprojects/' . basename($r->photo));
    if (!$path || !is_file($path)) { fail('img', 404); }
    header('Content-Type: image/jpeg');
    header('X-Content-Type-Options: nosniff');
    header('Cache-Control: private, max-age=86400');
    header('Content-Length: ' . filesize($path));
    readfile($path);
    exit;

case 'cv_file':                          // προβολή/λήψη CV (auth + hr)
    $r = Capsule::table('mod_cpm_cv')->where('id', (int) ($_GET['id'] ?? 0))->first();
    if (!$r || (!$r->cv_stored && empty($r->cv_storage_id))) { fail('file', 404); }
    $mime = $r->cv_mime ?: 'application/octet-stream';
    $previewable = ($mime === 'application/pdf' || strpos($mime, 'image/') === 0);   // μόνο PDF/εικόνα inline
    $disp = (!empty($_GET['dl']) || !$previewable) ? 'attachment' : 'inline';
    if (!empty($r->cv_storage_id)) {                        // migrated → S3/local via Storage
        $sr = Storage::record((int) $r->cv_storage_id);
        if ($sr && $sr['driver'] === 's3') { header('Location: ' . Storage::presign($sr['id'], 300, $disp === 'attachment'), true, 302); exit; }
        if ($sr) { $stm = Storage::openRead($sr['id']); if ($stm) {
            header('Content-Type: ' . $mime); header('X-Content-Type-Options: nosniff');
            header('Content-Disposition: ' . $disp . '; filename="' . rawurlencode($r->cv_name ?: 'cv.pdf') . '"');
            if ($sr['size']) { header('Content-Length: ' . (int) $sr['size']); }
            fpassthru($stm); fclose($stm); exit;
        } }
    }
    $path = realpath(__DIR__ . '/../attachments/cloudonprojects/' . basename($r->cv_stored));
    if (!$path || !is_file($path)) { fail('file', 404); }
    header('Content-Type: ' . $mime);
    header('X-Content-Type-Options: nosniff');
    header('Content-Disposition: ' . $disp . '; filename="' . rawurlencode($r->cv_name ?: 'cv.pdf') . '"');
    header('Content-Length: ' . filesize($path));
    readfile($path);
    exit;

case 'cv_update':                        // status / rating / notes / assignee
    $r = Capsule::table('mod_cpm_cv')->where('id', (int) ($in['id'] ?? 0))->first();
    if (!$r) { fail('notfound', 404); }
    $upd = ['updated_at' => date('Y-m-d H:i:s')];
    if (isset($in['status']) && array_key_exists($in['status'], cnp_cv_statuses())) { $upd['status'] = $in['status']; }
    if (isset($in['rating'])) { $upd['rating'] = max(0, min(5, (int) $in['rating'])); }
    if (array_key_exists('notes', $in)) { $upd['notes'] = cnp_clean_html($in['notes']); }
    if (array_key_exists('assignee', $in)) { $upd['assignee'] = (int) $in['assignee'] ?: null; }
    Capsule::table('mod_cpm_cv')->where('id', $r->id)->update($upd);
    out(['ok' => true]);

case 'cv_add':                           // χειροκίνητη προσθήκη υποψηφίου (CV από άλλες πηγές) — multipart
    $name = mb_substr(trim($_POST['name'] ?? ''), 0, 150);
    if ($name === '') { fail('Δώσε ονοματεπώνυμο'); }
    $cvName = ''; $cvMime = ''; $tmpUpload = null;
    $f = $_FILES['file'] ?? null;
    if ($f && $f['error'] === UPLOAD_ERR_OK) {
        if ($f['size'] > 15 * 1024 * 1024) { fail('Μέγιστο 15MB'); }
        if (!is_uploaded_file($f['tmp_name'])) { fail('upload'); }
        $ext = strtolower(pathinfo($f['name'], PATHINFO_EXTENSION));
        if (!cnp_file_ext_ok($f['name'])) { fail('Μη επιτρεπτός τύπος'); }
        $tmpUpload = $f['tmp_name'];
        $cvName = mb_substr($f['name'], 0, 190);
        $cvMime = $ext === 'pdf' ? 'application/pdf' : (($ext === 'doc' || $ext === 'docx') ? 'application/msword' : ($f['type'] ?: 'application/octet-stream'));
    }
    $jobId = (int) ($_POST['job'] ?? 0) ?: null;
    $jobTitle = mb_substr(trim($_POST['job_title'] ?? ''), 0, 190);
    if ($jobId && $jobTitle === '') { $jobTitle = (string) Capsule::table('mod_cpm_cv_jobs')->where('id', $jobId)->value('title'); }
    $id = Capsule::table('mod_cpm_cv')->insertGetId([
        'source' => 'manual', 'name' => $name,
        'email' => mb_substr(trim($_POST['email'] ?? ''), 0, 150), 'phone' => mb_substr(trim($_POST['phone'] ?? ''), 0, 50),
        'job_id' => $jobId, 'job_title' => $jobTitle, 'letter' => mb_substr(trim($_POST['letter'] ?? ''), 0, 8000),
        'cv_stored' => '', 'cv_name' => $cvName, 'cv_mime' => $cvMime, 'status' => 'new',
        'applied_at' => date('Y-m-d H:i:s'), 'created_at' => date('Y-m-d H:i:s'), 'updated_at' => date('Y-m-d H:i:s'),
    ]);
    // CV + φωτο κατευθείαν στο Storage (S3/local)
    if ($tmpUpload) {
        $ing = CvPhoto::ingest($tmpUpload, $cvName, $cvMime, $id);
        Capsule::table('mod_cpm_cv')->where('id', $id)->update(array_filter([
            'cv_storage_id' => $ing['cv_storage_id'], 'photo_storage_id' => $ing['photo_storage_id'],
            'photo' => $ing['photo'] ?: null, 'cv_stored' => $ing['cv_stored'] ?: null,
        ], fn($v) => $v !== null));
    }
    $ev = cnp_cv_evaluate($id, cnp_cv_default_model(), true);
    out(['ok' => true, 'id' => $id, 'evaluated' => !empty($ev['ok'])]);

case 'cv_ai':                            // co-pilot: αξιολόγηση/ταξινόμηση (με επιλογή μοντέλου)
    $model = $in['model'] ?? cnp_cv_default_model();
    $res = cnp_cv_evaluate((int) ($in['id'] ?? 0), $model, true);
    if (empty($res['ok'])) { fail($res['error'] === 'notfound' ? 'notfound' : $res['error'], $res['error'] === 'notfound' ? 404 : 400); }
    out(['ok' => true, 'ai' => $res['ai'], 'score' => $res['score'], 'model' => $res['model']]);

case 'cv_email':                         // αποστολή email σε υποψήφιο (καταγράφεται)
    $r = Capsule::table('mod_cpm_cv')->where('id', (int) ($in['id'] ?? 0))->first();
    if (!$r) { fail('notfound', 404); }
    $to = filter_var(trim($r->email), FILTER_VALIDATE_EMAIL);
    if (!$to) { fail('Ο υποψήφιος δεν έχει έγκυρο email'); }
    $subject = mb_substr(trim($in['subject'] ?? ''), 0, 190);
    $body = cnp_clean_html($in['body'] ?? '');
    if ($subject === '' || trim(strip_tags($body)) === '') { fail('Συμπλήρωσε θέμα & κείμενο'); }
    $adminEmail = filter_var(Capsule::table('tbladmins')->where('id', $adminId)->value('email'), FILTER_VALIDATE_EMAIL);
    $html = '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#243447;line-height:1.55;max-width:640px">' . nl2br($body) . '</div>';
    $headers = "MIME-Version: 1.0\r\nContent-Type: text/html; charset=UTF-8\r\nFrom: CloudOn <noreply@cloudon.gr>\r\n";
    if ($adminEmail) { $headers .= 'Reply-To: ' . $adminEmail . "\r\n"; }
    $sent = @mail($to, '=?UTF-8?B?' . base64_encode($subject) . '?=', $html, $headers);
    Capsule::table('mod_cpm_cv_comms')->insert(['cv_id' => $r->id, 'kind' => 'email', 'subject' => $subject, 'body' => $body, 'by' => $adminId, 'created_at' => date('Y-m-d H:i:s')]);
    if ($r->status === 'new') { Capsule::table('mod_cpm_cv')->where('id', $r->id)->update(['status' => 'review']); }
    out(['ok' => true, 'sent' => (bool) $sent]);

case 'cv_schedule':                      // προγραμματισμός συνέντευξης + ειδοποίηση/υπενθύμιση
    $r = Capsule::table('mod_cpm_cv')->where('id', (int) ($in['id'] ?? 0))->first();
    if (!$r) { fail('notfound', 404); }
    $when = trim($in['when'] ?? '');
    $at = $when ? date('Y-m-d H:i:s', strtotime($when)) : null;
    $upd = ['interview_at' => $at, 'updated_at' => date('Y-m-d H:i:s')];
    if ($at && !in_array($r->status, ['hired', 'rejected'], true)) { $upd['status'] = 'interview'; }
    Capsule::table('mod_cpm_cv')->where('id', $r->id)->update($upd);
    if ($at) {
        Capsule::table('mod_cpm_cv_comms')->insert(['cv_id' => $r->id, 'kind' => 'interview', 'subject' => 'Προγραμματισμός συνέντευξης',
            'body' => 'Συνέντευξη ορίστηκε: ' . date('d/m/Y H:i', strtotime($at)), 'by' => $adminId, 'created_at' => date('Y-m-d H:i:s')]);
        try { Db::addReminder((int) ($r->assignee ?: $adminId), date('Y-m-d H:i:s', strtotime($at . ' -1 hour')), 'Συνέντευξη: ' . $r->name . ' (' . $r->job_title . ')', null); } catch (\Throwable $e) {
        }
        foreach (cnp_hr_admin_ids() as $aid) { Db::pushNotification($aid, 'due', '📅 Συνέντευξη: ' . $r->name . ' — ' . date('d/m H:i', strtotime($at)), '/project/#/recruit'); }
    }
    out(['ok' => true, 'interviewAt' => $at]);

case 'cv_interview_kit':                 // παραγωγή οδηγού ερωτήσεων συνέντευξης
    $r = Capsule::table('mod_cpm_cv')->where('id', (int) ($in['id'] ?? 0))->first();
    if (!$r) { fail('notfound', 404); }
    $iv = $r->interview_json ? json_decode($r->interview_json, true) : null;
    if ($iv && !empty($iv['questions']) && empty($in['regen'])) { out(['ok' => true, 'kit' => $iv]); }
    $key = trim(Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')->where('setting', 'ai_api_key')->value('value') ?: '');
    if ($key === '') { fail('Δεν έχει οριστεί κλειδί AI'); }
    $model = array_key_exists($in['model'] ?? '', cnp_cv_models()) ? $in['model'] : cnp_cv_default_model();
    $ai = $r->ai_json ? json_decode($r->ai_json, true) : null;
    $skills = ($ai && !empty($ai['skills'])) ? implode(', ', array_slice($ai['skills'], 0, 15)) : '';
    $content = [];
    $blk = cnp_cv_pdf_block($r); if ($blk) { $content[] = $blk; }
    $content[] = ['type' => 'text', 'text' =>
        "Είσαι έμπειρος recruiter. Ετοίμασε στοχευμένο ΟΔΗΓΟ ΣΥΝΕΝΤΕΥΞΗΣ για τον υποψήφιο \"{$r->name}\" για τη θέση \"{$r->job_title}\".\n"
        . ($skills !== '' ? "Δηλωμένες δεξιότητες: $skills\n" : '')
        . "Δημιούργησε 10-14 ερωτήσεις σε 4 κατηγορίες:\n"
        . "• Γνώσεις — ερωτήσεις που ΕΠΑΛΗΘΕΥΟΥΝ σε βάθος όσα δηλώνει ότι γνωρίζει (τεχνικές/πρακτικές, όχι ναι/όχι).\n"
        . "• Χαρακτήρας — behavioral, soft skills, ομαδικότητα, διαχείριση πίεσης/σύγκρουσης.\n"
        . "• Εμπειρία — πραγματικά παραδείγματα από προηγούμενη δουλειά (STAR).\n"
        . "• Κίνητρα — γιατί εδώ, στόχοι, καταλληλότητα.\n"
        . 'Απάντησε ΜΟΝΟ με JSON (ελληνικά): {"questions":[{"id":"q1","category":"Γνώσεις|Χαρακτήρας|Εμπειρία|Κίνητρα","q":"...","purpose":"τι αξιολογεί σε λίγες λέξεις"}]}'];
    $resp = cnp_anthropic($key, $model, $content, 3500);
    if (empty($resp['ok'])) { fail($resp['error']); }
    $kit = cnp_json_extract($resp['text']);
    if (!$kit || empty($kit['questions'])) { fail('AI: μη έγκυρη απάντηση (δοκίμασε ξανά)'); }
    // δώσε ids αν λείπουν, κράτα τυχόν υπάρχουσες απαντήσεις
    foreach ($kit['questions'] as $i => &$qq) { if (empty($qq['id'])) { $qq['id'] = 'q' . ($i + 1); } } unset($qq);
    $kit['answers'] = $iv['answers'] ?? [];
    $kit['generated_at'] = date('Y-m-d H:i:s'); $kit['model'] = $model;
    Capsule::table('mod_cpm_cv')->where('id', $r->id)->update(['interview_json' => json_encode($kit, JSON_UNESCAPED_UNICODE), 'updated_at' => date('Y-m-d H:i:s')]);
    out(['ok' => true, 'kit' => $kit]);

case 'cv_interview_save':                // αποθήκευση καταγεγραμμένων απαντήσεων
    $r = Capsule::table('mod_cpm_cv')->where('id', (int) ($in['id'] ?? 0))->first();
    if (!$r) { fail('notfound', 404); }
    $iv = $r->interview_json ? json_decode($r->interview_json, true) : ['questions' => []];
    $ans = [];
    foreach ((array) ($in['answers'] ?? []) as $qid => $a) {
        $qid = preg_replace('/[^a-z0-9_]/i', '', (string) $qid);
        $ans[$qid] = ['text' => mb_substr(trim(strip_tags((string) ($a['text'] ?? ''))), 0, 4000), 'rating' => max(0, min(5, (int) ($a['rating'] ?? 0)))];
    }
    $iv['answers'] = $ans;
    $iv['interviewer'] = $adminId;
    if (isset($in['when'])) { $iv['when'] = trim($in['when']); }
    if (array_key_exists('notes', $in)) { $iv['notes'] = mb_substr(trim(strip_tags((string) $in['notes'])), 0, 4000); }
    Capsule::table('mod_cpm_cv')->where('id', $r->id)->update(['interview_json' => json_encode($iv, JSON_UNESCAPED_UNICODE), 'updated_at' => date('Y-m-d H:i:s')]);
    out(['ok' => true]);

case 'cv_interview_eval':                // AI αξιολόγηση της συνέντευξης
    $r = Capsule::table('mod_cpm_cv')->where('id', (int) ($in['id'] ?? 0))->first();
    if (!$r) { fail('notfound', 404); }
    $iv = $r->interview_json ? json_decode($r->interview_json, true) : null;
    if (!$iv || empty($iv['questions'])) { fail('Δημιούργησε & κατέγραψε πρώτα τη συνέντευξη'); }
    $key = trim(Capsule::table('tbladdonmodules')->where('module', 'cloudonprojects')->where('setting', 'ai_api_key')->value('value') ?: '');
    if ($key === '') { fail('Δεν έχει οριστεί κλειδί AI'); }
    $model = array_key_exists($in['model'] ?? '', cnp_cv_models()) ? $in['model'] : cnp_cv_default_model();
    $ansMap = $iv['answers'] ?? [];
    $trans = '';
    foreach ($iv['questions'] as $qq) {
        $a = $ansMap[$qq['id']] ?? null;
        $trans .= '[' . ($qq['category'] ?? '') . "] " . ($qq['q'] ?? '') . "\n";
        $trans .= 'ΑΠΑΝΤΗΣΗ: ' . (($a && trim($a['text']) !== '') ? $a['text'] : '(δεν καταγράφηκε)') . (($a && !empty($a['rating'])) ? ' [βαθμ. συνεντευκτή: ' . $a['rating'] . '/5]' : '') . "\n\n";
    }
    $txt = "Αξιολόγησε τη ΣΥΝΕΝΤΕΥΞΗ του υποψηφίου \"{$r->name}\" για τη θέση \"{$r->job_title}\". Ακολουθούν οι ερωτήσεις και οι απαντήσεις όπως τις κατέγραψε ο συνεντευκτής.\n\n"
        . "ΣΥΝΕΝΤΕΥΞΗ:\n" . mb_substr($trans, 0, 12000) . "\n";
    if (!empty($iv['notes'])) { $txt .= "ΣΗΜΕΙΩΣΕΙΣ ΣΥΝΕΝΤΕΥΚΤΗ: " . mb_substr($iv['notes'], 0, 1500) . "\n"; }
    $txt .= "\nΑξιολόγησε: (α) χαρακτήρα & soft skills, (β) αν ΕΠΑΛΗΘΕΥΤΗΚΑΝ οι γνώσεις που δήλωνε (verified/partial/not/unclear), (γ) red flags, (δ) συνολική σύσταση.\n"
        . 'Απάντησε ΜΟΝΟ με JSON (ελληνικά): {"score":0-100,"character":"εκτίμηση χαρακτήρα 2-3 προτάσεις","knowledgeVerified":"verified|partial|not|unclear","knowledgeNote":"τι επαληθεύτηκε/όχι","strengths":["..."],"redFlags":["..."],"recommendation":"proceed|hold|reject","summary":"συνολικό συμπέρασμα"}';
    $resp = cnp_anthropic($key, $model, [['type' => 'text', 'text' => $txt]], 1500);
    if (empty($resp['ok'])) { fail($resp['error']); }
    $ev = cnp_json_extract($resp['text']);
    if (!$ev) { fail('AI: μη έγκυρη απάντηση'); }
    $ev['model'] = $model; $ev['at'] = date('Y-m-d H:i:s');
    Capsule::table('mod_cpm_cv')->where('id', $r->id)->update(['interview_eval' => json_encode($ev, JSON_UNESCAPED_UNICODE), 'updated_at' => date('Y-m-d H:i:s')]);
    out(['ok' => true, 'eval' => $ev]);

case 'topstats':                         // πάνω μενού: live σφυγμός + κατάσταση διαθεσιμότητας
    $today = date('Y-m-d');
    $doneIds = Capsule::table('mod_cpm_statuses')->where('is_done', 1)->pluck('id')->all() ?: [0];
    $tkIds = Capsule::table('tbltickets')->where('flag', $adminId)->whereNotIn('status', ['Closed', 'Cancelled'])->pluck('id')->all();
    $tickets = count($tkIds);
    $sla = 0;
    try {
        if ($tickets && Capsule::schema()->hasTable('mod_supportcontracts_tickets')) {
            $sla = (int) Capsule::table('mod_supportcontracts_tickets')->whereIn('ticketid', $tkIds)
                ->whereNotNull('sla_due')->whereNull('first_response_at')->where('sla_due', '<', date('Y-m-d H:i:s'))->count();
        }
    } catch (\Throwable $e) {
    }
    /* Ο κανόνας της μπάλας και εδώ: το «σήμερα» μετρούσε σκέτο τον ανάδοχο, οπότε
       έδειχνε δουλειά που έχει ήδη περάσει σε άλλον. */
    $todayN = (int) cnp_scope_mine(
        Capsule::table('mod_cpm_tasks')->whereNotIn('status_id', $doneIds), $adminId)
        ->whereNotNull('due_date')->where('due_date', '<=', $today)->count();
    $ball = (int) Capsule::table('mod_cpm_tasks')->where('action_user', $adminId)->whereNotIn('status_id', $doneIds)->count();
    /* Εκκρεμείς εγκρίσεις χρέωσης — μόνο για όποιον τις δίνει. */
    $billPend = 0;
    if (cnp_can_approve_billing($adminId, $FULL)) {
        $pendQ = Capsule::table('mod_cpm_timelogs as l')
            ->join('mod_cpm_tasks as t', 't.id', '=', 'l.task_id')
            ->where('l.billable', 1)->where('l.running', 0)
            ->where(function ($q) { $q->whereNull('t.billing_ok')->orWhere('t.billing_ok', 0); });
        $billPend = 0;
        foreach ($pendQ->distinct()->pluck('t.type_id', 't.id') as $tidP => $tyP) {
            if (!cnp_nonbillable_type($tyP)) { $billPend++; }
        }
    }
    $needsT = cnp_pending_for($adminId, $FULL)['count'];   // 🆘 σε ζητούν: βοήθεια, ερωτήσεις, φωνή, προσκλήσεις
    out(['needs' => $needsT, 'tickets' => $tickets, 'sla' => $sla, 'today' => $todayN, 'ball' => $ball, 'billPend' => $billPend,
        'presence' => cnp_presence($adminId),
        'status' => Db::pref($adminId, 'chat_status', 'online'), 'reason' => Db::pref($adminId, 'chat_reason', '')]);

case 'lead_products':                    // γραμμές προϊόντων ενός deal
    $lid = (int) ($_GET['lead'] ?? $in['lead'] ?? 0);
    $rows = Capsule::table('mod_cpm_lead_products')->where('lead_id', $lid)->orderBy('id')->get();
    $items = []; $total = 0.0;
    foreach ($rows as $r) {
        $lt = round((float) $r->qty * (float) $r->unit_price, 2);
        $total += $lt;
        $items[] = ['id' => (int) $r->id, 'product_id' => $r->product_id ? (int) $r->product_id : null,
            'name' => $r->name, 'qty' => (float) $r->qty, 'price' => (float) $r->unit_price, 'total' => $lt];
    }
    // κατάλογος προϊόντων για επιλογή (name → default τιμή)
    $catalog = [];
    foreach (Capsule::table('tblproducts')->where('hidden', 0)->orderBy('name')->get(['id', 'name']) as $p) {
        $catalog[] = ['id' => (int) $p->id, 'name' => $p->name];
    }
    out(['items' => $items, 'total' => round($total, 2), 'catalog' => $catalog]);

case 'lead_product_save':
    $lid = (int) ($in['lead'] ?? 0);
    $name = mb_substr(trim($in['name'] ?? ''), 0, 150);
    if (!$lid || $name === '') { fail('input'); }
    $data = ['name' => $name, 'product_id' => (int) ($in['product_id'] ?? 0) ?: null,
        'qty' => max(0, round((float) ($in['qty'] ?? 1), 2)), 'unit_price' => round((float) ($in['price'] ?? 0), 2)];
    $iid = (int) ($in['id'] ?? 0);
    if ($iid) {
        Capsule::table('mod_cpm_lead_products')->where('id', $iid)->update($data);
    } else {
        $data['lead_id'] = $lid; $data['created_at'] = date('Y-m-d H:i:s');
        Capsule::table('mod_cpm_lead_products')->insert($data);
    }
    // αυτόματη ενημέρωση αξίας deal = σύνολο γραμμών
    $sum = 0.0;
    foreach (Capsule::table('mod_cpm_lead_products')->where('lead_id', $lid)->get(['qty', 'unit_price']) as $r) {
        $sum += (float) $r->qty * (float) $r->unit_price;
    }
    Capsule::table('mod_cpm_leads')->where('id', $lid)->update(['value' => round($sum, 2)]);
    out(['ok' => true, 'total' => round($sum, 2)]);

case 'lead_product_del':
    $iid = (int) ($in['id'] ?? 0);
    $lid = (int) Capsule::table('mod_cpm_lead_products')->where('id', $iid)->value('lead_id');
    Capsule::table('mod_cpm_lead_products')->where('id', $iid)->delete();
    if ($lid) {
        $sum = 0.0;
        foreach (Capsule::table('mod_cpm_lead_products')->where('lead_id', $lid)->get(['qty', 'unit_price']) as $r) {
            $sum += (float) $r->qty * (float) $r->unit_price;
        }
        Capsule::table('mod_cpm_leads')->where('id', $lid)->update(['value' => round($sum, 2)]);
    }
    out(['ok' => true]);

case 'campaigns':                        // λίστα καμπανιών + στατιστικά απόδοσης
    $chLbl = ['email' => 'Email', 'phone' => 'Τηλεφωνική', 'event' => 'Εκδήλωση', 'social' => 'Social', 'ads' => 'Διαφήμιση', 'other' => 'Άλλο'];
    $cps = Capsule::table('mod_cpm_campaigns')->orderByRaw("FIELD(status,'active','draft','done')")->orderBy('id', 'desc')->get();
    $list = [];
    foreach ($cps as $c) {
        $mids = Capsule::table('mod_cpm_campaign_leads')->where('campaign_id', $c->id)->pluck('lead_id')->all();
        $members = count($mids); $won = 0; $wonVal = 0.0; $openN = 0;
        if ($members) {
            foreach (Capsule::table('mod_cpm_leads')->whereIn('id', $mids)->get(['stage', 'value']) as $l) {
                if ($l->stage === 'won') { $won++; $wonVal += (float) $l->value; }
                elseif ($l->stage !== 'lost') { $openN++; }
            }
        }
        $list[] = ['id' => (int) $c->id, 'name' => $c->name, 'channel' => $c->channel,
            'channelLbl' => $chLbl[$c->channel] ?? $c->channel, 'status' => $c->status,
            'budget' => (float) $c->budget, 'goal' => $c->goal, 'start' => $c->start_date, 'end' => $c->end_date,
            'members' => $members, 'won' => $won, 'open' => $openN, 'wonValue' => round($wonVal, 2),
            'conv' => $members > 0 ? round($won / $members * 100) : null,
            'roi' => ($c->budget > 0) ? round(($wonVal - (float) $c->budget) / (float) $c->budget * 100) : null];
    }
    out(['campaigns' => $list, 'channels' => $chLbl]);

case 'campaign_save':
    $name = mb_substr(trim($in['name'] ?? ''), 0, 150);
    if ($name === '') { fail('input'); }
    $data = ['name' => $name, 'channel' => $in['channel'] ?? 'email', 'status' => $in['status'] ?? 'draft',
        'budget' => round((float) ($in['budget'] ?? 0), 2), 'goal' => mb_substr(trim($in['goal'] ?? ''), 0, 190),
        'start_date' => ($in['start'] ?? '') ?: null, 'end_date' => ($in['end'] ?? '') ?: null,
        'notes' => cnp_clean_html($in['notes'] ?? '')];
    $cid = (int) ($in['id'] ?? 0);
    if ($cid) {
        Capsule::table('mod_cpm_campaigns')->where('id', $cid)->update($data);
    } else {
        $data['created_by'] = $adminId; $data['created_at'] = date('Y-m-d H:i:s');
        $cid = Capsule::table('mod_cpm_campaigns')->insertGetId($data);
    }
    out(['ok' => true, 'id' => $cid]);

case 'campaign_del':
    $cid = (int) ($in['id'] ?? 0);
    Capsule::table('mod_cpm_campaign_leads')->where('campaign_id', $cid)->delete();
    Capsule::table('mod_cpm_campaigns')->where('id', $cid)->delete();
    out(['ok' => true]);

case 'campaign_detail':                  // πεδία + μέλη + υποψήφια leads προς προσθήκη
    $cid = (int) ($_GET['id'] ?? $in['id'] ?? 0);
    $c = Capsule::table('mod_cpm_campaigns')->where('id', $cid)->first();
    if (!$c) { fail('notfound'); }
    $sMeta = Db::leadStages();
    $mids = Capsule::table('mod_cpm_campaign_leads')->where('campaign_id', $cid)->pluck('lead_id')->all();
    $members = [];
    if ($mids) {
        foreach (Capsule::table('mod_cpm_leads')->whereIn('id', $mids)->orderBy('company')->get() as $l) {
            $members[] = ['id' => (int) $l->id, 'company' => $l->company, 'contact' => $l->contact,
                'stage' => $l->stage, 'stageLbl' => $sMeta[$l->stage][0] ?? $l->stage,
                'stageCol' => $sMeta[$l->stage][1] ?? '#8291a9', 'value' => (float) $l->value];
        }
    }
    // υποψήφια: leads που δεν είναι ήδη μέλη (max 200 πιο πρόσφατα)
    $cand = [];
    $cq = Capsule::table('mod_cpm_leads')->orderBy('id', 'desc');
    if ($mids) { $cq->whereNotIn('id', $mids); }
    foreach ($cq->limit(200)->get(['id', 'company', 'contact', 'stage']) as $l) {
        $cand[] = ['id' => (int) $l->id, 'company' => $l->company, 'contact' => $l->contact,
            'stageLbl' => $sMeta[$l->stage][0] ?? $l->stage];
    }
    out(['id' => (int) $c->id, 'name' => $c->name, 'channel' => $c->channel, 'status' => $c->status,
        'budget' => (float) $c->budget, 'goal' => $c->goal, 'start' => $c->start_date, 'end' => $c->end_date,
        'notes' => $c->notes, 'members' => $members, 'candidates' => $cand]);

case 'campaign_add_lead':
    $cid = (int) ($in['campaign'] ?? 0); $lid = (int) ($in['lead'] ?? 0);
    if (!$cid || !$lid) { fail('input'); }
    $exists = Capsule::table('mod_cpm_campaign_leads')->where('campaign_id', $cid)->where('lead_id', $lid)->exists();
    if (!$exists) {
        Capsule::table('mod_cpm_campaign_leads')->insert(['campaign_id' => $cid, 'lead_id' => $lid, 'added_at' => date('Y-m-d H:i:s')]);
    }
    out(['ok' => true]);

case 'campaign_remove_lead':
    Capsule::table('mod_cpm_campaign_leads')->where('campaign_id', (int) ($in['campaign'] ?? 0))->where('lead_id', (int) ($in['lead'] ?? 0))->delete();
    out(['ok' => true]);

case 'crm_reports':                      // αναλυτικά reports πωλήσεων (διοίκηση)
    $sMeta = Db::leadStages();
    $all = Capsule::table('mod_cpm_leads')->get(['stage', 'value', 'source', 'assignee', 'created_at', 'closed_at']);
    // funnel ανά στάδιο
    $funnel = [];
    foreach ($sMeta as $k => $m) { $funnel[$k] = ['key' => $k, 'label' => $m[0], 'color' => $m[1], 'count' => 0, 'value' => 0.0]; }
    $wonN = 0; $lostN = 0; $wonVal = 0.0; $pipeline = 0.0; $openN = 0;
    $closeDays = []; $srcAgg = []; $selAgg = [];
    foreach ($all as $l) {
        $st = $l->stage; $v = (float) $l->value;
        if (isset($funnel[$st])) { $funnel[$st]['count']++; $funnel[$st]['value'] += $v; }
        $isWon = ($st === 'won'); $isLost = ($st === 'lost');
        if ($isWon) { $wonN++; $wonVal += $v;
            if ($l->closed_at && $l->created_at) { $d = (strtotime($l->closed_at) - strtotime($l->created_at)) / 86400; if ($d >= 0) { $closeDays[] = $d; } }
        } elseif ($isLost) { $lostN++; }
        else { $openN++; $pipeline += $v; }
        // ανά πηγή
        $src = trim($l->source ?? '') ?: '—';
        if (!isset($srcAgg[$src])) { $srcAgg[$src] = ['source' => $src, 'leads' => 0, 'won' => 0, 'value' => 0.0]; }
        $srcAgg[$src]['leads']++; if ($isWon) { $srcAgg[$src]['won']++; $srcAgg[$src]['value'] += $v; }
        // ανά πωλητή
        $aid = (int) ($l->assignee ?? 0);
        if ($aid) {
            if (!isset($selAgg[$aid])) { $selAgg[$aid] = ['admin' => $aid, 'leads' => 0, 'won' => 0, 'value' => 0.0]; }
            $selAgg[$aid]['leads']++; if ($isWon) { $selAgg[$aid]['won']++; $selAgg[$aid]['value'] += $v; }
        }
    }
    foreach ($srcAgg as &$s) { $s['conv'] = $s['leads'] > 0 ? round($s['won'] / $s['leads'] * 100) : 0; $s['value'] = round($s['value'], 2); } unset($s);
    foreach ($selAgg as &$s) { $s['name'] = Db::adminName($s['admin']); $s['conv'] = $s['leads'] > 0 ? round($s['won'] / $s['leads'] * 100) : 0; $s['value'] = round($s['value'], 2); } unset($s);
    usort($srcAgg, fn($a, $b) => $b['value'] <=> $a['value']);
    $selAgg = array_values($selAgg); usort($selAgg, fn($a, $b) => $b['value'] <=> $a['value']);
    // τάση 6 μηνών (won ανά μήνα κλεισίματος)
    $months = [];
    for ($i = 5; $i >= 0; $i--) { $ym = date('Y-m', strtotime("first day of -$i month")); $months[$ym] = ['ym' => $ym, 'won' => 0, 'value' => 0.0]; }
    foreach ($all as $l) {
        if ($l->stage === 'won' && $l->closed_at) { $ym = substr($l->closed_at, 0, 7); if (isset($months[$ym])) { $months[$ym]['won']++; $months[$ym]['value'] += (float) $l->value; } }
    }
    foreach ($months as &$m) { $m['value'] = round($m['value'], 2); } unset($m);
    out([
        'funnel' => array_values($funnel),
        'winRate' => ($wonN + $lostN) > 0 ? round($wonN / ($wonN + $lostN) * 100) : null,
        'won' => $wonN, 'lost' => $lostN, 'open' => $openN,
        'wonValue' => round($wonVal, 2), 'pipeline' => round($pipeline, 2),
        'avgCloseDays' => count($closeDays) ? round(array_sum($closeDays) / count($closeDays), 1) : null,
        'bySource' => array_values($srcAgg), 'bySeller' => $selAgg, 'byMonth' => array_values($months),
    ]);

case 'lead_score':                       // βαθμολογία ενός lead + ανάλυση παραγόντων
    $lid = (int) ($_GET['lead'] ?? $in['lead'] ?? 0);
    $l = Capsule::table('mod_cpm_leads')->where('id', $lid)->first();
    if (!$l) { fail('notfound'); }
    $intCount = (int) Capsule::table('mod_cpm_interactions')->where('lead_id', $lid)->count();
    $lastInt = Capsule::table('mod_cpm_interactions')->where('lead_id', $lid)->max('happened_at');
    out(cnp_lead_score($l, $intCount, $lastInt));

case 'hot_leads':                        // κατάταξη ανοιχτών leads κατά score (θερμά πρώτα)
    $open = Capsule::table('mod_cpm_leads')->whereNotIn('stage', ['won', 'lost'])->get();
    // aggregate επικοινωνιών ανά lead (μία query)
    $cntBy = []; $lastBy = [];
    foreach (Capsule::table('mod_cpm_interactions')->whereNotNull('lead_id')->where('lead_id', '>', 0)
        ->groupBy('lead_id')->get([Capsule::raw('lead_id'), Capsule::raw('COUNT(*) as c'), Capsule::raw('MAX(happened_at) as last')]) as $r) {
        $cntBy[(int) $r->lead_id] = (int) $r->c; $lastBy[(int) $r->lead_id] = $r->last;
    }
    $sMeta = Db::leadStages();
    $rows = [];
    foreach ($open as $l) {
        $sc = cnp_lead_score($l, $cntBy[$l->id] ?? 0, $lastBy[$l->id] ?? null);
        $rows[] = ['id' => (int) $l->id, 'company' => $l->company, 'contact' => $l->contact,
            'stage' => $l->stage, 'stageLbl' => $sMeta[$l->stage][0] ?? $l->stage,
            'value' => (float) $l->value, 'assignee' => $l->assignee ? (int) $l->assignee : null,
            'score' => $sc['score'], 'temp' => $sc['temp']];
    }
    usort($rows, fn($a, $b) => $b['score'] <=> $a['score']);
    out(['leads' => array_slice($rows, 0, 20), 'total' => count($rows),
        'hot' => count(array_filter($rows, fn($r) => $r['temp'] === 'hot')),
        'warm' => count(array_filter($rows, fn($r) => $r['temp'] === 'warm')),
        'cold' => count(array_filter($rows, fn($r) => $r['temp'] === 'cold'))]);

case 'leads_export':                     // εξαγωγή όλων των leads σε CSV
    $cols = ['id', 'company', 'contact', 'email', 'phone', 'source', 'stage', 'value', 'next_action', 'descr'];
    $cell = fn($v) => '"' . str_replace('"', '""', (string) $v) . '"';
    $lines = [implode(',', array_map($cell, $cols))];
    foreach (Capsule::table('mod_cpm_leads')->orderBy('id')->get() as $l) {
        $row = [];
        foreach ($cols as $c) { $row[] = $cell($l->$c ?? ''); }
        $lines[] = implode(',', $row);
    }
    out(['csv' => implode("\r\n", $lines), 'count' => count($lines) - 1, 'filename' => 'leads-' . date('Ymd') . '.csv']);

case 'leads_import_preview':             // ανάλυση CSV + εντοπισμός διπλότυπων (χωρίς αποθήκευση)
    $txt = trim((string) ($in['csv'] ?? ''));
    if ($txt === '') { fail('empty'); }
    // δείκτες υπαρχόντων leads
    $byEmail = []; $byPhone = []; $byComp = [];
    $ph = fn($p) => preg_replace('/\D+/', '', (string) $p);
    foreach (Capsule::table('mod_cpm_leads')->get(['id', 'company', 'email', 'phone']) as $x) {
        if (trim($x->email ?? '') !== '') { $byEmail[mb_strtolower(trim($x->email))] = ['id' => (int) $x->id, 'company' => $x->company]; }
        $p = $ph($x->phone); if (strlen($p) >= 8) { $byPhone[$p] = ['id' => (int) $x->id, 'company' => $x->company]; }
        if (trim($x->company ?? '') !== '') { $byComp[mb_strtolower(trim($x->company))] = ['id' => (int) $x->id, 'company' => $x->company]; }
    }
    $stageKeys = array_keys(Db::leadStages());
    $rawLines = preg_split('/\r\n|\r|\n/', $txt);
    $fields = ['company', 'contact', 'email', 'phone', 'source', 'stage', 'value', 'next_action', 'descr'];
    $aliases = ['εταιρεία' => 'company', 'εταιρια' => 'company', 'επωνυμία' => 'company', 'επαφή' => 'contact', 'όνομα' => 'contact', 'name' => 'contact',
        'τηλέφωνο' => 'phone', 'τηλ' => 'phone', 'πηγή' => 'source', 'στάδιο' => 'stage', 'αξία' => 'value', 'σημειώσεις' => 'descr', 'notes' => 'descr'];
    // κεφαλίδα;
    $first = str_getcsv($rawLines[0]);
    $map = null; $start = 0;
    $lc = array_map(fn($h) => mb_strtolower(trim($h)), $first);
    if (count(array_intersect($lc, array_merge($fields, array_keys($aliases), ['id']))) >= 2) {
        $map = [];
        foreach ($lc as $i => $h) { $key = in_array($h, $fields) ? $h : ($aliases[$h] ?? null); if ($key) { $map[$key] = $i; } }
        $start = 1;
    }
    $preview = []; $newN = 0; $dupN = 0;
    for ($i = $start; $i < count($rawLines); $i++) {
        if (trim($rawLines[$i]) === '') { continue; }
        $c = str_getcsv($rawLines[$i]);
        $get = function ($key, $ord) use ($c, $map) { $idx = $map ? ($map[$key] ?? null) : $ord; return $idx !== null && isset($c[$idx]) ? trim($c[$idx]) : ''; };
        $rec = ['company' => $get('company', 1), 'contact' => $get('contact', 2), 'email' => $get('email', 3),
            'phone' => $get('phone', 4), 'source' => $get('source', 5), 'stage' => $get('stage', 6),
            'value' => $get('value', 7), 'next_action' => $get('next_action', 8), 'descr' => $get('descr', 9)];
        if ($rec['company'] === '' && $rec['contact'] === '' && $rec['email'] === '') { continue; }
        if (!in_array($rec['stage'], $stageKeys)) { $rec['stage'] = 'target'; }
        $rec['value'] = (float) preg_replace('/[^\d.]/', '', $rec['value']);
        // dup;
        $dup = null; $by = '';
        $em = mb_strtolower($rec['email']); $pp = $ph($rec['phone']); $cm = mb_strtolower($rec['company']);
        if ($em !== '' && isset($byEmail[$em])) { $dup = $byEmail[$em]; $by = 'email'; }
        elseif (strlen($pp) >= 8 && isset($byPhone[$pp])) { $dup = $byPhone[$pp]; $by = 'τηλέφωνο'; }
        elseif ($cm !== '' && isset($byComp[$cm])) { $dup = $byComp[$cm]; $by = 'εταιρεία'; }
        if ($dup) { $dupN++; } else { $newN++; }
        $preview[] = ['rec' => $rec, 'dup' => $dup ? ['id' => $dup['id'], 'company' => $dup['company'], 'by' => $by] : null];
    }
    out(['rows' => $preview, 'newN' => $newN, 'dupN' => $dupN, 'total' => count($preview)]);

case 'leads_import_commit':              // εκτέλεση εισαγωγής με αποφάσεις ανά γραμμή
    $rows = $in['rows'] ?? [];
    $stageKeys = array_keys(Db::leadStages());
    $ins = 0; $upd = 0; $skip = 0;
    foreach ($rows as $r) {
        $act = $r['action'] ?? 'new';
        if ($act === 'skip') { $skip++; continue; }
        $rec = $r['rec'] ?? [];
        $stage = in_array($rec['stage'] ?? '', $stageKeys) ? $rec['stage'] : 'target';
        $data = [
            'company' => mb_substr(trim($rec['company'] ?? ''), 0, 120), 'contact' => mb_substr(trim($rec['contact'] ?? ''), 0, 120),
            'email' => mb_substr(trim($rec['email'] ?? ''), 0, 120), 'phone' => mb_substr(trim($rec['phone'] ?? ''), 0, 40),
            'source' => mb_substr(trim($rec['source'] ?? ''), 0, 60), 'stage' => $stage, 'value' => (float) ($rec['value'] ?? 0),
            'next_action' => ($rec['next_action'] ?? '') ?: null, 'descr' => mb_substr(trim($rec['descr'] ?? ''), 0, 2000),
        ];
        if ($act === 'update' && !empty($r['dup']['id'])) {
            Capsule::table('mod_cpm_leads')->where('id', (int) $r['dup']['id'])->update($data); $upd++;
        } else {
            $data['created_by'] = $adminId; $data['created_at'] = date('Y-m-d H:i:s');
            Capsule::table('mod_cpm_leads')->insert($data); $ins++;
        }
    }
    out(['ok' => true, 'inserted' => $ins, 'updated' => $upd, 'skipped' => $skip]);

case 'leads_dupes':                      // εντοπισμός διπλότυπων μεταξύ υπαρχόντων leads
    $ph = fn($p) => preg_replace('/\D+/', '', (string) $p);
    $sMeta = Db::leadStages();
    $groups = [];  // sig => [lead ids]
    $info = [];
    foreach (Capsule::table('mod_cpm_leads')->orderBy('id')->get() as $l) {
        $info[$l->id] = $l;
        $sigs = [];
        if (trim($l->email ?? '') !== '') { $sigs[] = 'e:' . mb_strtolower(trim($l->email)); }
        $p = $ph($l->phone); if (strlen($p) >= 8) { $sigs[] = 'p:' . $p; }
        if (trim($l->company ?? '') !== '') { $sigs[] = 'c:' . mb_strtolower(trim($l->company)); }
        foreach ($sigs as $s) { $groups[$s][] = (int) $l->id; }
    }
    $clusters = []; $seen = [];
    foreach ($groups as $sig => $ids) {
        $ids = array_values(array_unique($ids));
        if (count($ids) < 2) { continue; }
        sort($ids); $ckey = implode(',', $ids);
        if (isset($seen[$ckey])) { continue; } $seen[$ckey] = 1;
        $byLbl = ['e' => 'email', 'p' => 'τηλέφωνο', 'c' => 'εταιρεία'][$sig[0]] ?? '';
        $ls = [];
        foreach ($ids as $id) { $x = $info[$id];
            $ls[] = ['id' => (int) $id, 'company' => $x->company, 'contact' => $x->contact, 'email' => $x->email,
                'phone' => $x->phone, 'stage' => $x->stage, 'stageLbl' => $sMeta[$x->stage][0] ?? $x->stage, 'value' => (float) $x->value];
        }
        $clusters[] = ['by' => $byLbl, 'leads' => $ls];
    }
    out(['clusters' => $clusters, 'count' => count($clusters)]);

case 'lead_merge':                       // συγχώνευση: μετακίνηση σχέσεων drop→keep, διαγραφή drop
    $keep = (int) ($in['keep'] ?? 0); $drop = (int) ($in['drop'] ?? 0);
    if (!$keep || !$drop || $keep === $drop) { fail('input'); }
    Capsule::table('mod_cpm_interactions')->where('lead_id', $drop)->update(['lead_id' => $keep]);
    Capsule::table('mod_cpm_lead_tasks')->where('lead_id', $drop)->update(['lead_id' => $keep]);
    Capsule::table('mod_cpm_lead_products')->where('lead_id', $drop)->update(['lead_id' => $keep]);
    // campaign_leads: απόφυγε διπλότυπο (campaign,lead)
    $keepCamps = Capsule::table('mod_cpm_campaign_leads')->where('lead_id', $keep)->pluck('campaign_id')->all();
    Capsule::table('mod_cpm_campaign_leads')->where('lead_id', $drop)->whereIn('campaign_id', $keepCamps ?: [0])->delete();
    Capsule::table('mod_cpm_campaign_leads')->where('lead_id', $drop)->update(['lead_id' => $keep]);
    // αν το keep δεν έχει αξία αλλά το drop έχει → κράτα τη μεγαλύτερη
    $kv = (float) Capsule::table('mod_cpm_leads')->where('id', $keep)->value('value');
    $dv = (float) Capsule::table('mod_cpm_leads')->where('id', $drop)->value('value');
    if ($dv > $kv) { Capsule::table('mod_cpm_leads')->where('id', $keep)->update(['value' => $dv]); }
    Capsule::table('mod_cpm_leads')->where('id', $drop)->delete();
    out(['ok' => true]);

case 'lead_timeline':                    // ενιαίο ιστορικό lead (επικοινωνίες + tasks)
    $lid = (int) ($_GET['lead'] ?? 0);
    $ev = [];
    foreach (Capsule::table('mod_cpm_interactions')->where('lead_id', $lid)->get() as $i) {
        $ev[] = ['type' => 'interaction', 'kind' => $i->kind, 'text' => $i->summary,
            'by' => $i->admin_id ? Db::adminName((int) $i->admin_id) : null,
            'at' => $i->happened_at ?: $i->created_at,
            'fup' => $i->followup_date && !$i->followup_done ? $i->followup_date : null];
    }
    foreach (Capsule::table('mod_cpm_lead_tasks')->where('lead_id', $lid)->get() as $t) {
        $ev[] = ['type' => 'task', 'kind' => $t->kind, 'text' => $t->title,
            'by' => $t->assignee ? Db::adminName((int) $t->assignee) : null,
            'at' => $t->done ? ($t->done_at ?: $t->created_at) : $t->created_at,
            'done' => (bool) $t->done, 'due' => $t->due_date];
    }
    usort($ev, function ($a, $b) { return strcmp($b['at'] ?? '', $a['at'] ?? ''); });
    out(['events' => array_slice($ev, 0, 60)]);

case 'my_crm_tasks':                     // ανοιχτές CRM εργασίες μου (ή όλων αν full)
    $today = date('Y-m-d');
    $q = Capsule::table('mod_cpm_lead_tasks as t')->join('mod_cpm_leads as l', 'l.id', '=', 't.lead_id')
        ->where('t.done', 0);
    $out = [];
    foreach ($rows as $t) {
        $out[] = ['id' => (int) $t->id, 'title' => $t->title, 'kind' => $t->kind, 'due' => $t->due_date,
            'overdue' => $t->due_date && $t->due_date < $today,
            'lead' => (int) $t->lead_id, 'leadName' => $t->company ?: $t->contact ?: ('lead #' . $t->lead_id),
            'who' => $t->assignee ? Db::adminName((int) $t->assignee) : null];
    }
    out(['tasks' => $out]);

case 'presence_sweep':                  // από το pulse cron (κάθε 10΄) — όταν κανείς δεν έχει την εφαρμογή ανοιχτή
    if (!$CRON_OK && !$FULL) { fail('forbidden', 403); }
    $nS = cnp_presence_sweep();
    try { cnp_close_ghost_timers(); } catch (\Throwable $eG) { }
    out(['ok' => true, 'pushed' => $nS]);

case 'supervised':                      // 👁 Επιβλέπω: οι εργασίες που ΑΝΟΙΞΑ εγώ (created_by) — ανοιχτές/ολοκληρωμένες
    $doneSv = Capsule::table('mod_cpm_statuses')->where('is_done', 1)->pluck('id')->all() ?: [0];
    $which = in_array($_GET['which'] ?? 'open', ['open', 'done', 'all'], true) ? $_GET['which'] : 'open';
    $qSv = Capsule::table('mod_cpm_tasks as t')->leftJoin('mod_cpm_projects as p', 'p.id', '=', 't.project_id')
        ->select('t.*', 'p.name as pname', 'p.color as pcolor', 'p.clientid as pclient')
        ->where('t.created_by', $adminId);
    if ($which === 'open') { $qSv->whereNotIn('t.status_id', $doneSv); }
    elseif ($which === 'done') { $qSv->whereIn('t.status_id', $doneSv); }
    $rowsSv = $qSv->orderByDesc('t.updated_at')->limit(500)->get();
    $idsSv = array_map(function ($t) { return (int) $t->id; }, $rowsSv->all());
    $lastSv = [];
    if ($idsSv) {
        foreach (Capsule::table('mod_cpm_activity')->whereIn('task_id', $idsSv)->selectRaw('task_id, MAX(created_at) as l')->groupBy('task_id')->get() as $la) { $lastSv[(int) $la->task_id] = $la->l; }
    }
    $outSv = [];
    foreach ($rowsSv as $t) {
        $outSv[] = taskDto($t) + ['pname' => cnp_pn($t->pname), 'pcolor' => $t->pcolor ?: '#8595ac',
            'clientName' => $t->pclient ? clientLabel((int) $t->pclient) : '',
            'isDone' => in_array((int) $t->status_id, $doneSv, true),
            'lastAt' => $lastSv[(int) $t->id] ?? $t->updated_at, 'updatedAt' => $t->updated_at];
    }
    out(['tasks' => $outSv, 'which' => $which,
        'counts' => ['open' => (int) Capsule::table('mod_cpm_tasks')->where('created_by', $adminId)->whereNotIn('status_id', $doneSv)->count(),
                     'done' => (int) Capsule::table('mod_cpm_tasks')->where('created_by', $adminId)->whereIn('status_id', $doneSv)->count()]]);

case 'version':
    /* Ο σφυγμός κάθε 12" είναι ό,τι πιο αξιόπιστο έχουμε για «είναι μπροστά στην
       οθόνη». Πριν, το `last_seen` το πείραζαν ΜΟΝΟ οι ενέργειες του chat, οπότε
       όποιος δούλευε στο board χωρίς να ανοίξει chat έδειχνε απών. Γράφουμε μόνο
       αν έχει περάσει μισό λεπτό, για να μη γίνεται update κάθε 12". */
    $seenNow = time();
    if ($seenNow - (int) Db::pref($adminId, 'last_seen', '0') > 30) {
        Db::setPref($adminId, 'last_seen', (string) $seenNow);
    }
    /* Πρώτη κίνηση της ημέρας: το tbladminlog.lastvisit δεν ενημερώνεται αξιόπιστα,
       οπότε το «από πότε είναι μέσα» το κρατάμε μόνοι μας — μία εγγραφή την ημέρα. */
    if (strpos((string) Db::pref($adminId, 'seen_first', ''), date('Y-m-d', $seenNow) . '|') !== 0) {
        Db::setPref($adminId, 'seen_first', date('Y-m-d', $seenNow) . '|' . $seenNow);
    }
    /* Χρονόμετρα αποσυνδεδεμένων — έλεγχος κάθε 2΄, όχι σε κάθε σφυγμό. */
    if ($seenNow - (int) Db::pref(0, 'ghost_sweep_at', '0') > 120) {
        Db::setPref(0, 'ghost_sweep_at', (string) $seenNow);
        try { cnp_close_ghost_timers($seenNow); } catch (\Throwable $eG) { /* ποτέ δεν χαλάει τον σφυγμό */ }
        /* Κατάσταση → 3CX για ΟΛΟΥΣ: πιάνει όσους έφυγαν (away/offline) και τις συσκέψεις που άρχισαν/τελείωσαν. */
        try { cnp_presence_sweep($seenNow); } catch (\Throwable $eP) { }
    }
    /* Η δική μου κατάσταση → 3CX, κάθε λεπτό (στέλνεται μόνο αν άλλαξε). */
    if ($seenNow - (int) Db::pref($adminId, 'pbx_sync_at', '0') > 60) {
        Db::setPref($adminId, 'pbx_sync_at', (string) $seenNow);
        try { Pbx3cxPresence::sync($adminId, cnp_presence($adminId, $seenNow)); } catch (\Throwable $eP) { }
    }
    $a6 = (string) Capsule::table('mod_cpm_tasks')->max('updated_at');
    $b6 = (string) Capsule::table('mod_cpm_tasks')->count();
    $c6 = (string) Capsule::table('tbltickets')->max('lastreply');
    $d6 = (string) Capsule::table('mod_cpm_notifications')->where('admin_id', $adminId)->max('id');
    $e6 = (string) Capsule::table('mod_cpm_comments')->max('id');
    $f6 = (string) Capsule::table('mod_cpm_leads')->max('updated_at');
    Db::setPref($adminId, 'last_seen', (string) time());
    $reads6 = [];
    foreach (Capsule::table('mod_cpm_chat_reads')->where('admin_id', $adminId)->get() as $r6) {
        $reads6[$r6->channel] = (int) $r6->last_id;
    }
    $chatUnread = 0;
    foreach (Capsule::table('mod_cpm_chat')->where('admin_id', '!=', $adminId)
        ->groupBy('channel')->get(['channel', Capsule::raw('MAX(id) m')]) as $g6) {
        if (!cnp_chat_access($g6->channel, $adminId)) {
            continue;
        }
        if ((int) $g6->m > ($reads6[$g6->channel] ?? 0)) {
            $chatUnread += Capsule::table('mod_cpm_chat')->where('channel', $g6->channel)
                ->where('admin_id', '!=', $adminId)->where('id', '>', $reads6[$g6->channel] ?? 0)->count();
        }
    }
    $g6chat = (string) Capsule::table('mod_cpm_chat')->max('id');
    /* Τα ΚΑΙΝΟΥΡΓΙΑ αδιάβαστα μηνύματα με περιεχόμενο — όχι μόνο μετρητής. Το
       καμπανάκι δεν αρκεί όταν δουλεύεις σε άλλη οθόνη: πρέπει να δεις ΠΟΙΟΣ
       σου μίλησε και ΤΙ είπε, χωρίς να ψάξεις. Μέχρι 5, τα πιο πρόσφατα. */
    $chatNew = [];
    foreach (Capsule::table('mod_cpm_chat')->where('admin_id', '!=', $adminId)
        ->where('id', '>', (int) ($_GET['chatSince'] ?? 0))
        ->orderBy('id', 'desc')->limit(20)
        ->get(['id', 'channel', 'admin_id', 'body', 'filename', 'created_at']) as $cm) {
        if (!cnp_chat_access($cm->channel, $adminId)) { continue; }
        if ((int) $cm->id <= ($reads6[$cm->channel] ?? 0)) { continue; }
        $label = $cm->channel === 'team' ? '# Ομάδα'
            : (strpos($cm->channel, 'g') === 0
                ? (string) Capsule::table('mod_cpm_chat_groups')->where('id', (int) substr($cm->channel, 1))->value('name')
                : '');
        $chatNew[] = ['id' => (int) $cm->id, 'channel' => $cm->channel,
            'from' => Db::adminName((int) $cm->admin_id), 'fromId' => (int) $cm->admin_id,
            'where' => $label,
            'text' => mb_substr((string) ($cm->body ?: ('📎 ' . $cm->filename)), 0, 160)];
        if (count($chatNew) >= 5) { break; }
    }
    $chatNew = array_reverse($chatNew);
    /* «Ζήτα βοήθεια»: ανοιχτές εκκλήσεις προς εμένα που δεν έχω δει ακόμη το δυνατό
       popup — το frontend τις εμφανίζει και μετά καλεί help_seen. */
    $alerts = [];
    foreach (Capsule::table('mod_cpm_help')->where('to_admin', $adminId)
        ->whereNull('seen_at')->where('status', 'open')->orderBy('id')->limit(5)->get() as $hr) {
        $alerts[] = ['id' => (int) $hr->id, 'fromId' => (int) $hr->from_admin,
            'from' => Db::adminName((int) $hr->from_admin), 'message' => $hr->message,
            'kind' => $hr->kind ?: 'help',
            'taskId' => $hr->task_id ? (int) $hr->task_id : 0,
            'taskTitle' => $hr->task_id ? (string) (Db::task((int) $hr->task_id)->title ?? '') : '',
            'clientId' => $hr->task_id ? (int) Time::clientForTask(Db::task((int) $hr->task_id)) : 0,
            'at' => $hr->created_at];
    }
    /* 📅 Συσκέψεις: μια πρόσκληση δεν πρέπει να περιμένει να κοιτάξεις καμπανάκι.
       Δύο δυνατές στιγμές — όταν σε καλούν και λίγο πριν αρχίσει. Καθεμία σκάει
       ΜΙΑ φορά (το κρατάει το mod_cpm_event_alerts). */
    $meetAlerts = [];
    $nowM = time();
    $canCal = cnp_has_cap($adminId, $FULL, 'team.calendar');   // χωρίς ημερολόγιο, καμία κάρτα
    $shown = [];
    foreach (Capsule::table('mod_cpm_event_alerts')->where('admin_id', $adminId)->get() as $sa) {
        $shown[$sa->event_id . ':' . $sa->kind] = true;
    }
    $rsvpMine = [];
    foreach (Capsule::table('mod_cpm_event_rsvp')->where('kind', 'admin')->where('ref', $adminId)->get() as $rm) {
        $rsvpMine[(int) $rm->event_id] = $rm->status;
    }
    foreach ($canCal ? Capsule::table('mod_cpm_events')
        ->whereIn('kind', ['meeting', 'appointment'])
        ->where('attendees', 'like', '%,' . $adminId . ',%')
        ->where('end_dt', '>=', date('Y-m-d H:i:s', $nowM))
        ->where('start_dt', '<=', date('Y-m-d H:i:s', $nowM + 7 * 86400))
        ->orderBy('start_dt')->limit(20)->get() : [] as $evM) {
        $eidM = (int) $evM->id;
        $mine = $rsvpMine[$eidM] ?? null;
        $startM = strtotime($evM->start_dt);
        $kindM = null;
        if (!$mine && empty($shown[$eidM . ':invite'])) {
            $kindM = 'invite';                       // σε κάλεσαν και δεν έχεις απαντήσει
        } elseif ($mine === 'accepted' && $startM - $nowM <= 600 && $startM + 300 > $nowM
            && empty($shown[$eidM . ':soon'])) {
            $kindM = 'soon';                         // αρχίζει σε ≤10΄ και το δέχτηκες
        }
        if (!$kindM) {
            continue;
        }
        $meetAlerts[] = cnp_meet_row($evM, $kindM, $nowM);
        if (count($meetAlerts) >= 3) {
            break;
        }
    }

    /* ⏳ ΞΕΠΕΡΑΣΕ ΤΗΝ ΩΡΑ ΤΗΣ. Στο end_dt ο χειριστής γινόταν αυτόματα
       «διαθέσιμος» — ακόμη κι αν η σύσκεψη συνεχιζόταν. Όποιος τον έψαχνε
       νόμιζε ότι είναι ελεύθερος, και όποιος ήταν μέσα δεν είχε τρόπο να το πει.
       Ρωτάμε: τελείωσε, ή θέλει παράταση;

       Το παράθυρο των 12 ωρών είναι σκόπιμο: μια σύσκεψη του περασμένου μήνα
       δεν έχει νόημα να ρωτηθεί, και η ερώτηση θα ήταν θόρυβος. */
    if ($canCal) {
        /* ΑΝΑ ΣΥΜΜΕΤΕΧΟΝΤΑ, με τη ΔΙΚΗ ΤΟΥ ώρα. Σε σύσκεψη με πέντε άτομα, δύο
           μπορεί να έχουν φύγει και τρεις να συνεχίζουν — ο καθένας ρωτιέται
           για τον εαυτό του, και όποιος δήλωσε ότι βγήκε δεν ξαναρωτιέται. */
        foreach (Capsule::table('mod_cpm_events as e')
            ->join('mod_cpm_event_rsvp as r', function ($j) use ($adminId) {
                $j->on('r.event_id', '=', 'e.id')
                  ->where('r.kind', '=', 'admin')->where('r.ref', '=', $adminId);
            })
            ->whereIn('e.kind', ['meeting', 'appointment'])
            ->where('e.all_day', 0)
            ->where('r.status', 'accepted')
            ->whereNull('r.left_at')
            ->whereRaw('COALESCE(r.until_dt, e.end_dt) <= ?', [date('Y-m-d H:i:s', $nowM - CNP_MEET_GRACE)])
            ->whereRaw('COALESCE(r.until_dt, e.end_dt) >= ?', [date('Y-m-d H:i:s', $nowM - 12 * 3600)])
            ->orderByRaw('COALESCE(r.until_dt, e.end_dt) desc')->limit(5)
            ->get(['e.id', 'e.title', 'e.start_dt', 'e.mode', 'e.place', 'e.location',
                   'e.clientid', 'e.created_by',
                   Capsule::raw('COALESCE(r.until_dt, e.end_dt) as end_dt'),
                   Capsule::raw('r.extended_min as extended_min')]) as $evO) {
            $eidO = (int) $evO->id;
            /* Το «είδα» σβήνεται σε κάθε παράταση, ώστε να ξαναρωτήσει όταν
               περάσει και η νέα ώρα. Δες event_outcome. */
            if (!empty($shown[$eidO . ':over'])) { continue; }
            $meetAlerts[] = cnp_meet_row($evO, 'over', $nowM);
            if (count($meetAlerts) >= 4) { break; }
        }
    }
    /* ⏱ Χρονόμετρο που τρέχει πολλές ώρες: ΔΕΝ το κόβουμε — μπορεί όντως να
       δουλεύει έξω από την εφαρμογή. Απλώς ρωτάμε, μία φορά κάθε δύο ώρες.
       Η ερώτηση εμφανίζεται μόλις ξαναφανεί στην εφαρμογή, που είναι και η
       σωστή στιγμή: αν ξέχασε το Stop, τώρα θα το θυμηθεί. */
    $myTimer = null;
    $runMine = Db::runningTimer($adminId);
    if ($runMine) {
        $ranFor = time() - strtotime($runMine->started_at);
        $askedAt = (int) Db::pref($adminId, 'timer_ask_at', '0');
        if ($ranFor > 4 * 3600 && time() - $askedAt > 2 * 3600) {
            Db::setPref($adminId, 'timer_ask_at', (string) time());
            $tkMine = Db::task((int) $runMine->task_id);
            $myTimer = ['task' => (int) $runMine->task_id,
                'title' => $tkMine ? mb_substr((string) $tkMine->title, 0, 90) : '',
                'since' => $runMine->started_at,
                'sinceTxt' => date('H:i', strtotime($runMine->started_at)),
                'mins' => (int) round($ranFor / 60)];
        }
    }
    out(['chatNew' => $chatNew,
        'v' => md5($a6 . '|' . $b6 . '|' . $c6 . '|' . $d6 . '|' . $e6 . '|' . $f6 . '|' . $g6chat),
        'build' => cnp_asset_version(),
        'unread' => Db::unreadCount($adminId), 'pending' => cnp_pending_for($adminId, $FULL)['count'],
        'chatUnread' => $chatUnread, 'alerts' => $alerts,
        'meetAlerts' => $meetAlerts, 'myTimer' => $myTimer]);

case 'event_nudge':                      // «απάντησε» σε όσους δεν έχουν απαντήσει
    $nv = Capsule::table('mod_cpm_events')->where('id', (int) ($in['id'] ?? 0))->first();
    if (!$nv) {
        fail('event', 404);
    }
    if (!$FULL && (int) $nv->created_by !== $adminId) {
        fail('Μόνο ο διοργανωτής στέλνει υπενθύμιση', 403);
    }
    $nAtt = array_filter(array_map('intval', explode(',', $nv->attendees)));
    $nAns = [];
    foreach (Capsule::table('mod_cpm_event_rsvp')->where('event_id', $nv->id)->where('kind', 'admin')->get() as $nr) {
        $nAns[(int) $nr->ref] = true;
    }
    $nSent = 0;
    $nWhen = date('d/m/Y H:i', strtotime($nv->start_dt));
    foreach ($nAtt as $nA) {
        if ($nA === $adminId || isset($nAns[$nA])) {
            continue;
        }
        Db::pushNotification($nA, 'info', '📅 Απάντησε: ' . $nv->title . ' — ' . $nWhen,
            '/projectmanagement/#/calendar');
        cnp_meet_mail($nA, '📅 Εκκρεμεί η απάντησή σου: ' . $nv->title,
            '<p>Ο/Η <strong>' . htmlspecialchars(Db::adminName($adminId)) . '</strong> περιμένει να δηλώσεις '
            . 'αν θα είσαι στη σύσκεψη <strong>' . htmlspecialchars($nv->title) . '</strong> — ' . $nWhen . '.</p>'
            . '<p><a href="https://my.cloudon.gr/projectmanagement/#/calendar">Άνοιξε το ημερολόγιο και απάντησε</a></p>');
        /* Ξαναδίνουμε δικαίωμα στη δυνατή κάρτα να σκάσει — γι' αυτό είναι η υπενθύμιση. */
        Capsule::table('mod_cpm_event_alerts')
            ->where('event_id', $nv->id)->where('admin_id', $nA)->where('kind', 'invite')->delete();
        $nSent++;
    }
    out(['ok' => true, 'sent' => $nSent]);

case 'event_noshow':                     // «δεν σε είδαμε» — ξανά η πρόσκληση + ρώτα τι έγινε
    $sv = Capsule::table('mod_cpm_events')->where('id', (int) ($in['id'] ?? 0))->first();
    if (!$sv) {
        fail('event', 404);
    }
    if (!$FULL && (int) $sv->created_by !== $adminId) {
        fail('Μόνο ο διοργανωτής ρωτά για απουσία', 403);
    }
    $sWho = array_values(array_intersect(
        array_filter(array_map('intval', (array) ($in['who'] ?? []))),
        array_filter(array_map('intval', explode(',', $sv->attendees)))));
    if (!$sWho) {
        fail('Διάλεξε ποιον αφορά');
    }
    $sMsg = mb_substr(trim((string) ($in['note'] ?? '')), 0, 300);
    $sWhen = date('d/m/Y H:i', strtotime($sv->start_dt));
    [$sIco, $sHow] = cnp_meeting_how($sv->mode, $sv->place, $sv->location,
        $sv->clientid ? clientLabel((int) $sv->clientid) : '');
    $sSent = 0;
    foreach ($sWho as $sA) {
        if ($sA === $adminId) {
            continue;
        }
        Db::pushNotification($sA, 'info',
            'Δεν σε είδαμε στη σύσκεψη: ' . mb_substr((string) $sv->title, 0, 70),
            '/projectmanagement/#/calendar');
        cnp_meet_mail($sA, 'Δεν σε είδαμε στη σύσκεψη — ' . $sv->title,
            '<p>Ο/Η <strong>' . htmlspecialchars(Db::adminName($adminId)) . '</strong> σε περίμενε στη σύσκεψη '
            . '<strong>' . htmlspecialchars($sv->title) . '</strong>.</p>'
            . '<p style="background:#eef7fd;border-left:4px solid #0090dd;padding:10px 14px;">🗓 <strong>' . $sWhen . '</strong>'
            . ($sHow ? '<br />' . $sIco . ' ' . htmlspecialchars($sHow) : '') . '</p>'
            . ($sMsg !== '' ? '<p>' . nl2br(htmlspecialchars($sMsg)) . '</p>' : '')
            . '<p>Αν προέκυψε κάτι σοβαρό, <strong>πες μας το</strong> — για να δούμε αν χρειάζεται βοήθεια '
            . 'ή αν πρέπει να ξαναοριστεί η συνάντηση.</p>'
            . '<p><a href="https://my.cloudon.gr/projectmanagement/#/calendar">Άνοιξε το ημερολόγιο</a></p>');
        /* Η πρόσκληση ξαναζωντανεύει: να ξανασκάσει η δυνατή κάρτα και να απαντήσει. */
        Capsule::table('mod_cpm_event_rsvp')
            ->where('event_id', $sv->id)->where('kind', 'admin')->where('ref', $sA)->delete();
        Capsule::table('mod_cpm_event_alerts')
            ->where('event_id', $sv->id)->where('admin_id', $sA)->delete();
        $sSent++;
    }
    out(['ok' => true, 'sent' => $sSent]);

case 'event_outcome':
    /* ΤΙ ΕΓΙΝΕ ΜΕ ΤΗ ΣΥΣΚΕΨΗ ΠΟΥ ΞΕΠΕΡΑΣΕ ΤΗΝ ΩΡΑ ΤΗΣ — ΓΙΑ ΕΣΕΝΑ.
       Η απάντηση είναι ΑΤΟΜΙΚΗ: σε σύσκεψη με πέντε άτομα δύο μπορεί να έχουν
       φύγει και τρεις να συνεχίζουν. Γράφεται στη γραμμή συμμετοχής σου, όχι
       πάνω στη σύσκεψη — αλλιώς ο πρώτος που απαντά θα την έκλεινε για όλους.
       Η προγραμματισμένη ώρα της σύσκεψης ΔΕΝ πειράζεται ποτέ: είναι το πλάνο.

         done   → βγήκες· ελευθερώνεσαι αμέσως, οι υπόλοιποι συνεχίζουν.
         extend → +N λεπτά ΓΙΑ ΕΣΕΝΑ· η κατάστασή σου «Σε σύσκεψη» συνεχίζεται
                  μόνη της ως τη νέα ώρα (δες cnp_meeting_now).
         open   → συνεχίζεται χωρίς γνωστό τέλος· ένα μπλοκ, και ξαναρωτάμε.

       Δεν στέλνουμε χωριστή ανακοίνωση «είναι ακόμη απασχολημένος»: η παρουσία
       ΕΙΝΑΙ η ανακοίνωση, τη βλέπουν όλοι, και δείχνει «έως ΗΗ:ΜΜ». */
    $eoId = (int) ($in['id'] ?? 0);
    $eoEv = Capsule::table('mod_cpm_events')->where('id', $eoId)->first();
    if (!$eoEv) { fail('Δεν βρέθηκε η σύσκεψη', 404); }
    $eoR = Capsule::table('mod_cpm_event_rsvp')->where('event_id', $eoId)
        ->where('kind', 'admin')->where('ref', $adminId)->first();
    if (!$eoR) { fail('Δεν συμμετέχεις σε αυτή τη σύσκεψη', 403); }

    $eoWhat = in_array($in['what'] ?? '', ['done', 'extend', 'open'], true) ? $in['what'] : '';
    if (!$eoWhat) { fail('Πες τι έγινε'); }

    $eoMine = strtotime($eoR->until_dt ?: $eoEv->end_dt);
    $eoUpd = ['outcome_at' => date('Y-m-d H:i:s')];
    if ($eoWhat === 'done') {
        $eoUpd['outcome'] = 'done';
        $eoUpd['left_at'] = date('Y-m-d H:i:s');
        /* Βγήκες νωρίτερα: κλείνει ΤΩΡΑ για εσένα, αλλιώς έμενες «σε σύσκεψη»
           άδικα μέχρι την προγραμματισμένη ώρα. */
        $eoUpd['until_dt'] = date('Y-m-d H:i:s');
        $eoMsg = 'Καταγράφηκε ότι βγήκες';
    } else {
        $eoMin = $eoWhat === 'open' ? 30 : (int) ($in['minutes'] ?? 0);
        $eoMin = max(5, min(240, $eoMin ?: 15));
        /* Η παράταση μετριέται από ΤΩΡΑ, όχι από την παλιά λήξη: αν απαντήσεις
           είκοσι λεπτά αργότερα, «άλλο ένα τέταρτο» σημαίνει από τώρα. */
        $eoUpd['until_dt'] = date('Y-m-d H:i:s', max(time(), $eoMine) + $eoMin * 60);
        $eoUpd['extended_min'] = (int) ($eoR->extended_min ?? 0) + $eoMin;
        /* Το outcome ΜΕΝΕΙ κενό επίτηδες: δεν έχεις βγει, θα ξαναρωτηθείς. */
        $eoMsg = 'Παράταση ' . $eoMin . '΄ — έως ' . date('H:i', strtotime($eoUpd['until_dt']));
    }
    Capsule::table('mod_cpm_event_rsvp')->where('id', $eoR->id)->update($eoUpd);

    /* Η ειδοποίηση «over» σβήνεται ΓΙΑ ΕΣΕΝΑ, ώστε να ξαναρωτήσει στη νέα ώρα.
       Χωρίς αυτό, η παράταση θα ήταν σιωπηλή για πάντα. */
    Capsule::table('mod_cpm_event_alerts')->where('event_id', $eoId)
        ->where('kind', 'over')->where('admin_id', $adminId)->delete();

    /* Όταν έχουν βγει ΟΛΟΙ όσοι είχαν δεχτεί, η σύσκεψη έκλεισε πραγματικά. */
    $eoLeft = Capsule::table('mod_cpm_event_rsvp')->where('event_id', $eoId)
        ->where('status', 'accepted')->whereNull('left_at')->count();
    if (!$eoLeft) {
        Capsule::table('mod_cpm_events')->where('id', $eoId)->update([
            'outcome' => 'done', 'outcome_at' => date('Y-m-d H:i:s'), 'outcome_by' => $adminId,
            'extended_min' => (int) Capsule::table('mod_cpm_event_rsvp')->where('event_id', $eoId)
                ->max('extended_min')]);
    }

    /* Οι ΥΠΟΛΟΙΠΟΙ που είναι ακόμη μέσα μαθαίνουν ότι τραβάει: μπορεί να
       περιμένουν έξω ή να έχουν κλείσει κάτι αμέσως μετά. Όποιος έχει βγει δεν
       ενοχλείται — τον αφορά πια. */
    if ($eoWhat !== 'done') {
        foreach (Capsule::table('mod_cpm_event_rsvp')->where('event_id', $eoId)
                    ->where('status', 'accepted')->whereNull('left_at')
                    ->where('ref', '<>', $adminId)->pluck('ref') as $eoA) {
            try {
                Db::pushNotification((int) $eoA, 'meeting',
                    Db::adminName($adminId) . ': «' . mb_substr((string) $eoEv->title, 0, 50)
                    . '» συνεχίζεται έως ' . date('H:i', strtotime($eoUpd['until_dt'])), '#/calendar');
            } catch (\Throwable $e) { /* η ειδοποίηση δεν χαλάει την απάντηση */ }
        }
    }
    out(['ok' => true, 'msg' => $eoMsg, 'end' => $eoUpd['until_dt']]);

case 'event_alert_seen':                 // «το είδα» — να μη σκάσει ξανά η ίδια κάρτα
    $saE = (int) ($in['id'] ?? 0);
    $saK = in_array($in['alert'] ?? '', ['invite', 'soon', 'nudge'], true) ? $in['alert'] : 'invite';
    if ($saE) {
        Capsule::table('mod_cpm_event_alerts')->updateOrInsert(
            ['event_id' => $saE, 'admin_id' => $adminId, 'kind' => $saK],
            ['sent_at' => date('Y-m-d H:i:s')]);
    }
    out(['ok' => true]);

/* ---- αναζήτηση πελάτη (autocomplete) ---- */
case 'client_quick_add':                  // νέος πελάτης επί τόπου, από το πεδίο επιλογής
    if (!cnp_has_cap($adminId, $FULL, 'clients.new')) {
        fail('Δεν έχεις δικαίωμα δημιουργίας πελάτη', 403);
    }
    $qName = trim((string) ($in['company'] ?? ''));
    $qFirst = trim((string) ($in['first'] ?? ''));
    $qLast = trim((string) ($in['last'] ?? ''));
    $qMail = trim((string) ($in['email'] ?? ''));
    if ($qName === '' && $qFirst === '' && $qLast === '') {
        fail('Δώσε επωνυμία ή ονοματεπώνυμο');
    }
    if ($qMail !== '' && !filter_var($qMail, FILTER_VALIDATE_EMAIL)) {
        fail('Μη έγκυρο email');
    }
    /* Το WHMCS απαιτεί email και το θέλει μοναδικό. Όταν δεν το ξέρουμε ακόμη
       (τυπική περίπτωση σε lead), βάζουμε placeholder του δικού μας domain που
       δεν παραδίδεται πουθενά — και το σημειώνουμε στις σημειώσεις του πελάτη
       ώστε να φαίνεται ότι πρέπει να συμπληρωθεί. */
    $placeholder = false;
    if ($qMail === '') {
        $qMail = 'lead+' . substr(bin2hex(random_bytes(5)), 0, 8) . '@noreply.cloudon.gr';
        $placeholder = true;
    }
    if (Capsule::table('tblclients')->where('email', $qMail)->exists()) {
        fail('Υπάρχει ήδη πελάτης με αυτό το email');
    }
    // Πύλη πελάτη + κωδικοί: θέλει ΠΡΑΓΜΑΤΙΚΟ email.
    $qPortal = !empty($in['portal']);
    if ($qPortal && $placeholder) {
        fail('Για πρόσβαση στην πύλη χρειάζεται πραγματικό email πελάτη');
    }
    $qAfm = preg_replace('/\D+/', '', (string) ($in['afm'] ?? ''));
    $qDoy = trim((string) ($in['doy'] ?? ''));
    /* ΑΦΜ: έγκυρο και ΜΟΝΑΔΙΚΟ. Διπλός πελάτης με το ίδιο ΑΦΜ σημαίνει διπλά
       τιμολόγια, διπλή καρτέλα και οφειλές μοιρασμένες σε δύο εγγραφές. */
    if ($qAfm !== '') {
        if (!cnp_afm_valid($qAfm)) {
            fail('Το ΑΦΜ «' . $qAfm . '» δεν είναι έγκυρο — έλεγξε τα ψηφία.');
        }
        $own = cnp_afm_owner($qAfm);
        if ($own) {
            http_response_code(409);
            out(['error' => 'Το ΑΦΜ ' . $qAfm . ' ανήκει ήδη στον πελάτη «' . $own['label'] . '» (#' . $own['id'] . ').',
                'need' => 'afm_taken', 'client' => $own['id'], 'label' => $own['label']]);
        }
    }
    /* Αν δεν δόθηκε ονοματεπώνυμο, το βγάζουμε από την επωνυμία — το WHMCS τα
       θέλει υποχρεωτικά και χωρίς αυτά η κλήση αποτυγχάνει. */
    if ($qFirst === '' && $qLast === '') {
        $parts = preg_split('/\s+/u', $qName, 2);
        $qFirst = $parts[0];
        $qLast = $parts[1] ?? '-';
    } elseif ($qLast === '') {
        $qLast = '-';
    } elseif ($qFirst === '') {
        $qFirst = '-';
    }
    $qPass = $qPortal ? cnp_gen_password() : bin2hex(random_bytes(10));
    $res = localAPI('AddClient', [
        'firstname' => $qFirst, 'lastname' => $qLast,
        'companyname' => $qName, 'email' => $qMail,
        'address1' => trim((string) ($in['address'] ?? '')) ?: '—',
        'city' => trim((string) ($in['city'] ?? '')) ?: '—',
        'state' => trim((string) ($in['city'] ?? '')) ?: '—',
        'postcode' => trim((string) ($in['postcode'] ?? '')) ?: '00000',
        'country' => strtoupper(substr(trim((string) ($in['country'] ?? 'GR')), 0, 2)) ?: 'GR',
        'phonenumber' => trim((string) ($in['phone'] ?? '')) ?: '0000000000',
        'tax_id' => mb_strlen($qAfm) === 9 ? $qAfm : '',
        /* Η καρτέλα διαβάζει ΑΦΜ από το custom #1 και ΔΟΥ από το #82. Χωρίς αυτά η
           άντληση ΑΑΔΕ «χανόταν» και χρειαζόταν δεύτερη αποθήκευση για να φανεί. */
        'customfields' => base64_encode(serialize(array_filter([1 => $qAfm, 82 => $qDoy]))),
        'password2' => $qPass,
        'notes' => 'Δημιουργήθηκε από το Project Manager'
            . ($qAfm ? ' — ΑΦΜ ' . $qAfm : '') . ($qDoy ? ', ΔΟΥ ' . $qDoy : '')
            . ($placeholder ? ' — ΠΡΟΣΟΧΗ: προσωρινό email, χρειάζεται συμπλήρωση.' : ''),
        'noemail' => true, 'skipvalidation' => true,
    ], 'pdelis');
    if (($res['result'] ?? '') !== 'success') {
        fail('WHMCS: ' . ($res['message'] ?? 'αποτυχία δημιουργίας'));
    }
    $newId = (int) $res['clientid'];
    // Πρόσβαση πύλης: αποστολή κωδικών σύνδεσης (ίδιο μονοπάτι με τις προσφορές).
    $credSent = false;
    if ($qPortal) {
        $cmeta2 = [];
        $credSent = cnp_send_login_credentials($qMail, $qName ?: trim($qFirst . ' ' . $qLast), $qPass, $adminId);
    }
    logActivity('CloudOn PM: νέος πελάτης #' . $newId . ' «' . ($qName ?: $qFirst . ' ' . $qLast)
        . '» από admin ' . $adminId . ($placeholder ? ' (προσωρινό email)' : '')
        . ($qPortal ? ($credSent ? ' + κωδικοί πύλης' : ' + πύλη (κωδικοί ΔΕΝ στάλθηκαν)') : ''));
    out(['ok' => true, 'id' => $newId, 'name' => $qName ?: trim($qFirst . ' ' . $qLast),
        'email' => $placeholder ? '' : $qMail, 'placeholderEmail' => $placeholder,
        'portal' => $qPortal, 'credentialsSent' => $credSent,
        'label' => ($qName ?: trim($qFirst . ' ' . $qLast)) . ' (#' . $newId . ')']);

case 'clients':                           // πλήρης λίστα πελατών (ενεργοί/ανενεργοί/κλειστοί)
    $q = trim((string) ($_GET['q'] ?? $in['q'] ?? ''));
    $status = (string) ($_GET['status'] ?? $in['status'] ?? '');   // Active|Inactive|Closed|'' (όλοι)
    $page = max(1, (int) ($_GET['page'] ?? $in['page'] ?? 1));
    $per = 40;
    /* Πλήθη ανά κατάσταση για τα tabs. */
    $counts = ['all' => 0, 'Active' => 0, 'Inactive' => 0, 'Closed' => 0];
    foreach (Capsule::table('tblclients')->select('status', Capsule::raw('count(*) c'))->groupBy('status')->get() as $r) {
        if (isset($counts[$r->status])) { $counts[$r->status] = (int) $r->c; }
        $counts['all'] += (int) $r->c;
    }
    $base = Capsule::table('tblclients');
    if (in_array($status, ['Active', 'Inactive', 'Closed'], true)) { $base->where('status', $status); }
    if ($q !== '') {
        /* Σκέτος αριθμός ΔΕΝ σημαίνει «id πελάτη»: το ΑΦΜ είναι κι αυτό αριθμός,
           και το τηλέφωνο επίσης. Πριν, ένα 9ψήφιο ΑΦΜ έψαχνε πελάτη με id
           998107371 και δεν έβρισκε ποτέ τίποτα. Ψάχνουμε παντού. */
        $like = '%' . $q . '%';
        $base->where(function ($w) use ($like, $q) {
            if (ctype_digit($q)) { $w->orWhere('id', (int) $q); }
            $w->orWhere('firstname', 'like', $like)->orWhere('lastname', 'like', $like)
              ->orWhere('companyname', 'like', $like)->orWhere('email', 'like', $like)
              ->orWhere('phonenumber', 'like', $like);
            cnp_afm_where($w, $like);
        });
    }
    $total = (clone $base)->count();
    $rows = $base->orderByRaw("CASE status WHEN 'Active' THEN 0 WHEN 'Inactive' THEN 1 ELSE 2 END")
        ->orderBy('companyname')->orderBy('lastname')
        ->offset(($page - 1) * $per)->limit($per)
        ->get(['id', 'firstname', 'lastname', 'companyname', 'email', 'phonenumber', 'status', 'datecreated', 'city', 'country']);
    $ids = [];
    foreach ($rows as $r) { $ids[] = (int) $r->id; }
    /* Μετρήσεις σε παρτίδες — ένα query το καθένα για όλη τη σελίδα. */
    $canBal9 = cnp_can_see_balances($adminId, $FULL);
    $svc = []; $tk = []; $pj = []; $owed = []; $afm = []; $doy = [];
    if ($ids) {
        foreach (Capsule::table('tblhosting')->whereIn('userid', $ids)->whereIn('domainstatus', ['Active', 'Suspended'])
                 ->select('userid', Capsule::raw('count(*) c'))->groupBy('userid')->get() as $r) { $svc[(int) $r->userid] = (int) $r->c; }
        foreach (Capsule::table('tbltickets')->whereIn('userid', $ids)->whereNotIn('status', ['Closed', 'Cancelled'])
                 ->select('userid', Capsule::raw('count(*) c'))->groupBy('userid')->get() as $r) { $tk[(int) $r->userid] = (int) $r->c; }
        foreach (Capsule::table('mod_cpm_projects')->whereIn('clientid', $ids)
                 ->select('clientid', Capsule::raw('count(*) c'))->groupBy('clientid')->get() as $r) { $pj[(int) $r->clientid] = (int) $r->c; }
        foreach (Capsule::table('tblinvoices')->whereIn('userid', $ids)->where('status', 'Unpaid')
                 ->select('userid', Capsule::raw('sum(total) t'), Capsule::raw('count(*) c'))->groupBy('userid')->get() as $r) {
            $owed[(int) $r->userid] = ['a' => (float) $r->t, 'c' => (int) $r->c];
        }
        foreach (Capsule::table('tblcustomfieldsvalues')->where('fieldid', 1)->whereIn('relid', $ids)->get(['relid', 'value']) as $r) { $afm[(int) $r->relid] = (string) $r->value; }
        foreach (Capsule::table('tblcustomfieldsvalues')->where('fieldid', 82)->whereIn('relid', $ids)->get(['relid', 'value']) as $r) { $doy[(int) $r->relid] = (string) $r->value; }
    }
    $dec = function ($s) { return html_entity_decode((string) $s, ENT_QUOTES); };
    $list = [];
    foreach ($rows as $r) {
        $cid = (int) $r->id;
        $nm = $r->companyname ?: trim($r->firstname . ' ' . $r->lastname);
        $list[] = ['id' => $cid, 'name' => $dec($nm), 'company' => $dec($r->companyname),
            'first' => $dec($r->firstname), 'last' => $dec($r->lastname),
            'email' => (string) $r->email, 'phone' => (string) $r->phonenumber,
            'status' => (string) $r->status, 'active' => $r->status === 'Active',
            'city' => $dec($r->city), 'country' => (string) $r->country, 'created' => $r->datecreated,
            'afm' => html_entity_decode($afm[$cid] ?? '', ENT_QUOTES),
            'doy' => html_entity_decode($doy[$cid] ?? '', ENT_QUOTES),
            'services' => $svc[$cid] ?? 0, 'tickets' => $tk[$cid] ?? 0, 'projects' => $pj[$cid] ?? 0,
            /* Η σημαία μένει (χρειάζεται για παραπομπή στο λογιστήριο), το ποσό όχι. */
            'owedFlag' => ($owed[$cid]['c'] ?? 0) > 0,
            'owed' => $canBal9 ? round($owed[$cid]['a'] ?? 0, 2) : null,
            'owedCount' => $canBal9 ? ($owed[$cid]['c'] ?? 0) : null];
    }
    out(['clients' => $list, 'total' => $total, 'page' => $page, 'per' => $per,
        'pages' => max(1, (int) ceil($total / $per)), 'counts' => $counts,
        'canBalances' => $canBal9,
        'canEdit' => cnp_has_cap($adminId, $FULL, 'clients.card.edit'),
        'canNew' => cnp_has_cap($adminId, $FULL, 'clients.new')]);

case 'client_get':                        // επεξεργάσιμα πεδία ενός πελάτη
    $cid = (int) ($_GET['id'] ?? $in['id'] ?? 0);
    $c = Capsule::table('tblclients')->where('id', $cid)->first();
    if (!$c) { fail('client', 404); }
    $cf = [];
    foreach (Capsule::table('tblcustomfieldsvalues')->whereIn('fieldid', [1, 82, 88])->where('relid', $cid)->get(['fieldid', 'value']) as $r) {
        $cf[(int) $r->fieldid] = html_entity_decode((string) $r->value, ENT_QUOTES);
    }
    $dec = function ($s) { return html_entity_decode((string) $s, ENT_QUOTES); };
    /* Το placeholder email («lead+…@noreply.cloudon.gr») το βάζουμε ΕΜΕΙΣ επειδή το
       WHMCS απαιτεί μοναδικό email — δεν είναι διεύθυνση πελάτη και δεν πρέπει να
       εμφανίζεται σαν τέτοια, ούτε να καταλήγει σε επικοινωνία. */
    $isTmp = (bool) preg_match('/@noreply\.cloudon\.gr$/i', (string) $c->email);
    out(['client' => ['id' => $cid, 'company' => $dec($c->companyname),
        'first' => $dec($c->firstname), 'last' => $dec($c->lastname),
        'email' => $isTmp ? '' : (string) $c->email, 'tmpEmail' => $isTmp,
        'phone' => (string) $c->phonenumber,
        'address' => $dec($c->address1), 'city' => $dec($c->city),
        'postcode' => (string) $c->postcode, 'country' => (string) $c->country,
        'status' => (string) $c->status, 'afm' => $cf[1] ?? (string) $c->tax_id,
        'doy' => $cf[82] ?? '', 'mobile' => $cf[88] ?? '']]);

case 'client_update':                     // αποθήκευση αλλαγών πελάτη (incl. status + ΑΦΜ/ΔΟΥ)
    $cid = (int) ($in['id'] ?? 0);
    $c = Capsule::table('tblclients')->where('id', $cid)->first();
    if (!$c) { fail('client', 404); }
    $upd = ['clientid' => $cid];
    $has = false;
    foreach (['companyname' => 'company', 'firstname' => 'first', 'lastname' => 'last',
              'email' => 'email', 'address1' => 'address', 'city' => 'city',
              'postcode' => 'postcode', 'phonenumber' => 'phone'] as $col => $k) {
        if (array_key_exists($k, $in)) { $upd[$col] = trim((string) $in[$k]); $has = true; }
    }
    if (array_key_exists('country', $in)) { $upd['country'] = strtoupper(substr(trim((string) $in['country']), 0, 2)) ?: 'GR'; $has = true; }
    if (array_key_exists('status', $in) && in_array($in['status'], ['Active', 'Inactive', 'Closed'], true)) { $upd['status'] = $in['status']; $has = true; }
    /* Κενό email: αν ο πελάτης κρατά ακόμη προσωρινή διεύθυνση, την αφήνουμε ήσυχη —
       το WHMCS απαιτεί μοναδικό email και δεν δέχεται κενό. Αν είχε πραγματικό, δεν
       το σβήνουμε κατά λάθος από μια φόρμα που άνοιξε άδεια. */
    if (array_key_exists('email', $upd) && trim($upd['email']) === '') { unset($upd['email']); }
    if (isset($upd['email']) && !filter_var($upd['email'], FILTER_VALIDATE_EMAIL)) { fail('Μη έγκυρο email'); }
    /* ΑΦΜ (custom #1 + tax_id) & ΔΟΥ (#82) & Κινητό (#88) μέσω customfields. */
    $cf = [];
    if (array_key_exists('afm', $in)) {
        $a = preg_replace('/\s+/', '', (string) $in['afm']);
        $aDigits = preg_replace('/\D+/', '', $a);
        /* Ίδιοι έλεγχοι με τη δημιουργία — αλλιώς ο κανόνας παρακάμπτεται με
           μια επεξεργασία. Κενό ΑΦΜ επιτρέπεται (σβήσιμο). */
        if ($aDigits !== '') {
            if (!cnp_afm_valid($aDigits)) {
                fail('Το ΑΦΜ «' . $aDigits . '» δεν είναι έγκυρο — έλεγξε τα ψηφία.');
            }
            $own = cnp_afm_owner($aDigits, $cid);
            if ($own) {
                http_response_code(409);
                out(['error' => 'Το ΑΦΜ ' . $aDigits . ' ανήκει ήδη στον πελάτη «' . $own['label'] . '» (#' . $own['id'] . ').',
                    'need' => 'afm_taken', 'client' => $own['id'], 'label' => $own['label']]);
            }
        }
        $cf[1] = $a; $upd['tax_id'] = $aDigits; $has = true;
    }
    if (array_key_exists('doy', $in)) { $cf[82] = trim((string) $in['doy']); $has = true; }
    if (array_key_exists('mobile', $in)) { $cf[88] = trim((string) $in['mobile']); $has = true; }
    if ($cf) { $upd['customfields'] = base64_encode(serialize($cf)); }
    if (!$has) { fail('Τίποτα προς αλλαγή'); }
    $res = localAPI('UpdateClient', $upd, 'pdelis');
    if (($res['result'] ?? '') !== 'success') { fail('WHMCS: ' . ($res['message'] ?? 'αποτυχία ενημέρωσης')); }
    logActivity('CloudOn PM: ενημέρωση στοιχείων πελάτη #' . $cid . ' από admin ' . $adminId);
    out(['ok' => true, 'id' => $cid, 'name' => (Capsule::table('tblclients')->where('id', $cid)->value('companyname')
        ?: trim($upd['firstname'] ?? $c->firstname) . ' ' . trim($upd['lastname'] ?? $c->lastname))]);

case 'client_search':
    $q = trim($_GET['q'] ?? '');
    $res = [];
    if (mb_strlen($q) >= 2) {
        $cq = Capsule::table('tblclients')->limit(12);
        /* Μόνο ΕΝΕΡΓΟΙ πελάτες (απόφαση 14/9/2026): νέο έργο/προσφορά/κράτηση δεν
           ανοίγει σε Inactive/Closed. Με &all=1 έρχονται όλοι (π.χ. αναζήτηση ιστορικού). */
        if (($_GET['all'] ?? '') !== '1') { $cq->where('status', 'Active'); }
        /* Εννιαψήφιο = ΑΦΜ (έτσι το γράφει ο κόσμος), αλλιώς id. Στη γενική αναζήτηση
           μπαίνει και το ΑΦΜ ως κείμενο, για μερική πληκτρολόγηση. */
        /* ΤΑ ΨΗΦΙΑ ΔΕΝ ΕΙΝΑΙ ΜΟΝΟ ΝΟΥΜΕΡΑ. Πριν, σκέτος αριθμός έψαχνε ΜΟΝΟ σε id
           και ΑΦΜ — οπότε το «295» δεν έβρισκε ποτέ τον «PHARMACY295 ΙΚΕ», παρότι
           ο αριθμός είναι μέσα στην επωνυμία του. Ψάχνουμε παντού, όπως ακριβώς
           κάνει και η λίστα πελατών: ό,τι κι αν γράψεις, αν υπάρχει κάπου μέσα
           στα στοιχεία του πελάτη, θα βρεθεί. */
        $like = '%' . str_replace(['%', '_'], ['\%', '\_'], $q) . '%';
        $cq->where(function ($w) use ($q, $like) {
            if (ctype_digit($q)) { $w->orWhere('id', (int) $q); }
            $w->orWhere('firstname', 'like', $like)->orWhere('lastname', 'like', $like)
              ->orWhere('companyname', 'like', $like)->orWhere('email', 'like', $like)
              ->orWhere('phonenumber', 'like', $like)
              ->orWhereRaw("CONCAT(firstname, ' ', lastname) LIKE ?", [$like]);
            cnp_afm_where($w, $like);
        });
        /* ΣΕΙΡΑ ΠΟΥ ΒΓΑΖΕΙ ΝΟΗΜΑ: πρώτα το ακριβές id, μετά όσα ΑΡΧΙΖΟΥΝ με ό,τι
           έγραψες, και τελευταία όσα απλώς το περιέχουν — αλλιώς, με δώδεκα
           αποτελέσματα, το προφανές έπεφτε στο τέλος. */
        $pre = str_replace(['%', '_'], ['\%', '\_'], $q) . '%';
        $cq->orderByRaw(
            'CASE WHEN id = ? THEN 0 WHEN companyname LIKE ? OR firstname LIKE ? OR lastname LIKE ? THEN 1 ELSE 2 END, companyname, lastname',
            [ctype_digit($q) ? (int) $q : 0, $pre, $pre, $pre]
        );
        foreach ($cq->get(['id', 'firstname', 'lastname', 'companyname', 'email', 'status']) as $c) {
            // Το WHMCS κρατά τις επωνυμίες HTML-escaped («&amp;») — η οθόνη κάνει δικό της esc.
            $nm = html_entity_decode($c->companyname ?: trim($c->firstname . ' ' . $c->lastname), ENT_QUOTES, 'UTF-8');
            $res[] = ['id' => (int) $c->id, 'name' => $nm, 'email' => (string) $c->email,
                'status' => (string) $c->status,
                // Το `label` κρατιέται όπως ήταν — το διαβάζουν παλιές κλήσεις.
                'label' => $nm . ' (#' . $c->id . ')'];
        }
    }
    out(['results' => $res]);

/* ═══════════════════════════════════════════════════════════════════════
   ΑΔΕΙΕΣ ΠΡΟΣΩΠΙΚΟΥ

   Το κύκλωμα: ο εργαζόμενος ζητάει → ο υπεύθυνος εγκρίνει → ο χρόνος την
   κάνει «ελήφθη». Κανείς δεν χρειάζεται να θυμηθεί να κλείσει μια άδεια που
   ήδη πέρασε.

   ΤΙ ΕΙΝΑΙ ΠΡΟΣΩΠΙΚΟ ΚΑΙ ΤΙ ΟΧΙ: τα δικά σου υπόλοιπα και το δικό σου αίτημα
   δεν θέλουν δικαίωμα. Οι ΞΕΝΕΣ άδειες θέλουν — είναι στοιχεία μισθοδοσίας.
   Ο έλεγχος γίνεται ΜΕΣΑ στην ενέργεια, γιατί η ίδια οθόνη δείχνει και τα
   δικά σου και της ομάδας ανάλογα με το ποιος είσαι.
   ═══════════════════════════════════════════════════════════════════════ */

case 'leave_me':
    $lvS = Leave::staffFor($adminId);
    if (!$lvS) {
        /* Δεν είναι σφάλμα: όχι κάθε χειριστής είναι εργαζόμενος με μητρώο
           αδειών (λογαριασμοί συστήματος, εξωτερικοί συνεργάτες). */
        out(['ok' => true, 'enrolled' => false,
            'note' => 'Αν πρόκειται για λάθος, μίλα στο γραφείο προσωπικού.']);
    }
    out(['ok' => true, 'enrolled' => true] + cnp_leave_person($lvS, true));

case 'leave_request':
    $lvS = Leave::staffFor($adminId);
    if (!$lvS) { fail('Δεν είσαι στο μητρώο αδειών'); }
    out(cnp_leave_write(null, $lvS, $in, $adminId, 'requested'));

case 'leave_withdraw':
    /* Ανακαλείς ΔΙΚΟ ΣΟΥ αίτημα που δεν έχει ακόμη εγκριθεί. Εγκεκριμένη άδεια
       δεν εξαφανίζεται με ένα κλικ — την ακυρώνει ο υπεύθυνος, ώστε να μείνει
       ίχνος για τη μισθοδοσία. */
    $lvS = Leave::staffFor($adminId);
    $lvId = (int) ($in['id'] ?? 0);
    $lvRow = $lvId ? Capsule::table('mod_cpm_leaves')->where('id', $lvId)->first() : null;
    if (!$lvRow || !$lvS || (int) $lvRow->staff_id !== (int) $lvS->id) { fail('Δεν βρέθηκε'); }
    if ($lvRow->status !== 'requested') {
        fail('Έχει ήδη εγκριθεί — ζήτα από τον υπεύθυνο να την ακυρώσει');
    }
    Capsule::table('mod_cpm_leaves')->where('id', $lvId)
        ->update(['status' => 'cancelled', 'updated_at' => date('Y-m-d H:i:s')]);
    cnp_leave_mirror($lvId);
    out(['ok' => true]);

case 'leave_staff':
    /* Η εικόνα όλης της ομάδας: ανά εργαζόμενο, ανά έτος — δικαιούται,
       μεταφορά, πήρε, μένουν. Και οι αναρρωτικές ΧΩΡΙΣΤΑ, γιατί δεν χρεώνουν
       υπόλοιπο και δεν πρέπει να μπερδεύονται μαζί του. */
    $lvYear = (int) ($in['year'] ?? $_GET['year'] ?? date('Y'));
    $lvOut = [];
    $lvSkipped = 0;
    foreach (Capsule::table('mod_cpm_leave_staff')->where('active', 1)->get() as $st) {
        /* Δεν δείχνουμε άνθρωπο σε έτος που δεν ήταν ακόμη εδώ: μια σειρά με
           μηδενικά διαβάζεται ως «δεν πήρε άδεια», ενώ η αλήθεια είναι «δεν
           είχε προσληφθεί». */
        if ($st->hire_date && (int) substr($st->hire_date, 0, 4) > $lvYear) {
            $lvSkipped++;
            continue;
        }
        $bal = Leave::balance($st->id);
        $b = $bal[$lvYear] ?? ['entitled' => 0, 'carried' => 0, 'available' => 0,
            'taken' => 0, 'remaining' => 0, 'mismatch' => false, 'note' => ''];
        $sug = Leave::suggestEntitlement($st, $lvYear);
        /* ΤΙ ΕΦΥΓΕ ΜΠΡΟΣΤΑ. Η «μεταφορά» του επόμενου έτους ΕΙΝΑΙ ό,τι δεν πήρε
           φέτος και κρατήθηκε. Χωρίς αυτό η χρονιά δεν κλείνει: βλέπεις ότι
           έμειναν 5 ημέρες και δεν ξέρεις αν μεταφέρθηκαν, αποζημιώθηκαν ή
           χάθηκαν. */
        $carriedOut = (float) ($bal[$lvYear + 1]['carried'] ?? 0);
        $lvOut[] = [
            'staffId'  => (int) $st->id,
            'adminId'  => (int) $st->admin_id,
            'name'     => Db::adminName($st->admin_id),
            'afm'      => (string) $st->afm,
            'hire'     => (string) $st->hire_date,
            'entitled' => (float) $b['entitled'],
            'carried'  => (float) $b['carried'],
            'available' => (float) ($b['available'] ?? ($b['entitled'] + $b['carried'])),
            'carriedOut' => $carriedOut,
            'settled'  => !empty($b['settled']),
            'taken'    => (float) $b['taken'],
            'remaining' => (float) $b['remaining'],
            'suggest'  => $sug['days'],
            'suggestWhy' => $sug['why'],
            /* Το εργαλείο δεν διορθώνει από μόνο του τη μισθοδοσία — το δείχνει. */
            'offLaw'   => abs($sug['days'] - (float) $b['entitled']) > 0.01,
            'sick'     => cnp_leave_sum($st->id, $lvYear, 'SICK'),
            'other'    => cnp_leave_sum($st->id, $lvYear, null, ['ANNUAL', 'SICK']),
            'expiring' => Leave::expiring($st->id),
            'mismatch' => (bool) $b['mismatch'],
            'totalRemaining' => Leave::remainingTotal($st->id),
        ];
    }
    usort($lvOut, function ($a, $b) { return strcmp($a['name'], $b['name']); });
    out(['ok' => true, 'year' => $lvYear, 'rows' => $lvOut, 'notYet' => $lvSkipped,
        'years' => cnp_leave_years_seen(), 'types' => cnp_leave_types()]);

case 'leave_person':
    /* Η καρτέλα ΕΝΟΣ εργαζομένου: υπόλοιπα ανά έτος + οι άδειές του. Ίδια
       αριθμητική με το «leave_me», αλλά για άλλον — γι' αυτό θέλει cap. */
    $lvSt = Capsule::table('mod_cpm_leave_staff')
        ->where('id', (int) ($in['staffId'] ?? $_GET['staffId'] ?? 0))->first();
    if (!$lvSt) { fail('Δεν βρέθηκε ο εργαζόμενος'); }
    out(['ok' => true] + cnp_leave_person($lvSt, true) + ['types' => cnp_leave_types()]);

case 'leave_list':
    out(['ok' => true] + cnp_leave_query($in));

case 'leave_get':
    $lvRow = Capsule::table('mod_cpm_leaves')->where('id', (int) ($in['id'] ?? $_GET['id'] ?? 0))->first();
    if (!$lvRow) { fail('Δεν βρέθηκε'); }
    out(['ok' => true, 'leave' => cnp_leave_row($lvRow)]);

case 'leave_save':
    $lvId = (int) ($in['id'] ?? 0);
    $lvSt = Capsule::table('mod_cpm_leave_staff')
        ->where('id', (int) ($in['staffId'] ?? 0))->first();
    if (!$lvSt) { fail('Διάλεξε εργαζόμενο'); }
    out(cnp_leave_write($lvId ?: null, $lvSt, $in, $adminId, null));

case 'leave_decide':
    $lvId = (int) ($in['id'] ?? 0);
    $lvRow = $lvId ? Capsule::table('mod_cpm_leaves')->where('id', $lvId)->first() : null;
    if (!$lvRow) { fail('Δεν βρέθηκε'); }
    $lvTo = (string) ($in['decision'] ?? '');
    if (!in_array($lvTo, ['approved', 'rejected', 'cancelled'], true)) { fail('Άγνωστη απόφαση'); }
    /* Η έγκριση κοιτάει ΞΑΝΑ το υπόλοιπο: ανάμεσα στο αίτημα και την έγκριση
       μπορεί να έχει καταχωρηθεί άλλη άδεια. */
    if ($lvTo === 'approved' && Leave::deducts($lvRow->type)) {
        $bal = Leave::balance($lvRow->staff_id);
        $b = $bal[(int) $lvRow->year] ?? null;
        if ($b && $b['remaining'] < 0 && empty($in['force'])) {
            fail('Το υπόλοιπο του ' . $lvRow->year . ' θα γίνει ' . $b['remaining']
                . '. Στείλε force=1 αν το εγκρίνεις εν γνώσει σου.');
        }
    }
    Capsule::table('mod_cpm_leaves')->where('id', $lvId)->update([
        'status'      => $lvTo,
        'approved_by' => $adminId,
        'approved_at' => date('Y-m-d H:i:s'),
        'updated_at'  => date('Y-m-d H:i:s'),
    ]);
    cnp_leave_mirror($lvId);
    /* Ο εργαζόμενος μαθαίνει την απόφαση μέσα στο εργαλείο — δεν την ψάχνει. */
    $lvSt = Capsule::table('mod_cpm_leave_staff')->where('id', $lvRow->staff_id)->first();
    if ($lvSt) {
        Db::pushNotification((int) $lvSt->admin_id, 'leave',
            'Άδεια ' . Leave::flowLabel($lvTo) . ': ' . cnp_leave_span($lvRow)
            . ' (' . Leave::typeLabel($lvRow->type) . ')', '#/leave/me');
    }
    out(['ok' => true]);

case 'leave_delete':
    $lvId = (int) ($in['id'] ?? 0);
    $lvRow = $lvId ? Capsule::table('mod_cpm_leaves')->where('id', $lvId)->first() : null;
    if (!$lvRow) { fail('Δεν βρέθηκε'); }
    if ($lvRow->event_id) {
        Capsule::table('mod_cpm_events')->where('id', (int) $lvRow->event_id)->delete();
    }
    Capsule::table('mod_cpm_leaves')->where('id', $lvId)->delete();
    out(['ok' => true]);

case 'leave_year_save':
    /* Οι δικαιούμενες ημέρες ανά έτος — αυτό που ζητήθηκε ρητά: «να περάσουμε
       ανά εργαζόμενο μέρες άδειας που δικαιούται». Ο νόμος προτείνει, εδώ
       γράφεται η απόφαση. */
    $lvSid = (int) ($in['staffId'] ?? 0);
    $lvY   = (int) ($in['year'] ?? 0);
    $lvT   = (string) ($in['type'] ?? 'ANNUAL');
    if (!$lvSid || $lvY < 2000 || $lvY > 2100) { fail('Λείπει εργαζόμενος ή έτος'); }
    if (!isset(Leave::TYPES[$lvT])) { fail('Άγνωστος τύπος άδειας'); }
    $lvVals = [
        'staff_id'      => $lvSid,
        'year'          => $lvY,
        'type'          => $lvT,
        'entitled_days' => round((float) ($in['entitled'] ?? 0), 2),
        'carried_in'    => round((float) ($in['carried'] ?? 0), 2),
        'note'          => trim((string) ($in['note'] ?? '')) ?: null,
    ];
    $lvEx = Capsule::table('mod_cpm_leave_years')->where('staff_id', $lvSid)
        ->where('year', $lvY)->where('type', $lvT)->first();
    if ($lvEx) { Capsule::table('mod_cpm_leave_years')->where('id', $lvEx->id)->update($lvVals); }
    else { Capsule::table('mod_cpm_leave_years')->insert($lvVals); }
    out(['ok' => true, 'balance' => Leave::balance($lvSid, $lvT)]);

case 'leave_staff_save':
    $lvSid = (int) ($in['staffId'] ?? 0);
    $lvAdm = (int) ($in['adminId'] ?? 0);
    $lvVals = [
        'afm'           => trim((string) ($in['afm'] ?? '')) ?: null,
        'hire_date'     => trim((string) ($in['hire'] ?? '')) ?: null,
        'prior_months'  => max(0, (int) ($in['priorMonths'] ?? 0)),
        'week_days'     => (int) ($in['weekDays'] ?? 5) === 6 ? 6 : 5,
        'active'        => empty($in['inactive']) ? 1 : 0,
        'notes'         => trim((string) ($in['notes'] ?? '')) ?: null,
    ];
    if ($lvSid) {
        Capsule::table('mod_cpm_leave_staff')->where('id', $lvSid)->update($lvVals);
    } else {
        if (!$lvAdm) { fail('Διάλεξε χειριστή'); }
        if (Capsule::table('mod_cpm_leave_staff')->where('admin_id', $lvAdm)->exists()) {
            fail('Ο χειριστής είναι ήδη στο μητρώο');
        }
        $lvVals['admin_id'] = $lvAdm;
        $lvVals['created_at'] = date('Y-m-d H:i:s');
        $lvSid = (int) Capsule::table('mod_cpm_leave_staff')->insertGetId($lvVals);
    }
    out(['ok' => true, 'staffId' => $lvSid]);

case 'leave_ergani':
    /* Ε11 / βιβλίο αδειών: ο εργοδότης δηλώνει ΤΟΝ ΙΑΝΟΥΑΡΙΟ τις άδειες του
       προηγούμενου έτους, αλλιώς πρόστιμο. Η οθόνη δείχνει τι έχει δηλωθεί και
       τι όχι — το `ergani` είναι ξεχωριστό πεδίο ακριβώς γι' αυτό. */
    $lvY = (int) ($in['year'] ?? $_GET['year'] ?? (date('Y') - 1));
    $lvRows = [];
    foreach (Capsule::table('mod_cpm_leaves as l')
            ->join('mod_cpm_leave_staff as s', 's.id', '=', 'l.staff_id')
            ->where('l.year', $lvY)->whereIn('l.status', ['approved', 'taken'])
            ->orderBy('s.id')->orderBy('l.date_from')
            ->get(['l.*', 's.admin_id']) as $r) {
        $lvRows[] = [
            'id'     => (int) $r->id,
            'name'   => Db::adminName($r->admin_id),
            'type'   => Leave::typeLabel($r->type),
            'days'   => (float) $r->days,
            'span'   => cnp_leave_span($r),
            'ergani' => (string) $r->ergani,
            'missing' => trim((string) $r->ergani) === '',
        ];
    }
    $lvMiss = count(array_filter($lvRows, function ($r) { return $r['missing']; }));
    out(['ok' => true, 'year' => $lvY, 'rows' => $lvRows, 'missing' => $lvMiss,
        'deadline' => ($lvY + 1) . '-01-31']);


case 'products_tree':
    /* Ο ΚΑΤΑΛΟΓΟΣ — μία λίστα που τροφοδοτεί ρόλους, τηλεφωνικό κατάλογο και
       ταξινόμηση tickets. Δέντρο ενός επιπέδου: προϊόν → υποκατηγορία. */
    /* ΠΟΙΟΙ ΤΟ ΚΑΛΥΠΤΟΥΝ. Η ουρά του 3CX ΔΕΝ είναι ιδιότητα του προϊόντος —
       είναι το πώς δουλεύει σήμερα το τηλεφωνικό κέντρο, και ζει στη
       «Δρομολόγηση κλήσεων». Εδώ το προϊόν δηλώνει ΑΝΘΡΩΠΟΥΣ: «αυτή τη δουλειά
       την καλύπτουν ο Χ, ο Ψ και ο Ζ». Είναι ο ΙΔΙΟΣ χάρτης με τους Ρόλους,
       από την ανάποδη πλευρά — εκεί ξεκινάς από τον άνθρωπο, εδώ από τη δουλειά. */
    $pCov = [];
    foreach (Capsule::table('mod_cpm_agent_skills')->get(['admin_id', 'product_id', 'level']) as $r) {
        $pCov[(int) $r->product_id][] = ['admin_id' => (int) $r->admin_id,
            'name' => Db::adminName($r->admin_id), 'level' => (string) $r->level];
    }
    $pOrder = ['main' => 0, 'can' => 1, 'learn' => 2];
    foreach ($pCov as &$pC) {
        usort($pC, function ($x, $y) use ($pOrder) {
            return $pOrder[$x['level']] <=> $pOrder[$y['level']] ?: strcoll($x['name'], $y['name']);
        });
    }
    unset($pC);
    $pPeople = [];
    foreach (Db::admins() as $a) { $pPeople[] = ['id' => (int) $a->id, 'name' => Db::adminName($a->id)]; }

    $pRows = Catalog::tree(false);
    $pAttach = function (&$list) use (&$pAttach, $pCov) {
        foreach ($list as &$r) {
            $r['covers'] = $pCov[(int) $r['id']] ?? [];
            if (!empty($r['kids'])) { $pAttach($r['kids']); }
        }
    };
    $pAttach($pRows);

    out(['ok' => true, 'rows' => $pRows, 'people' => $pPeople,
         'levels' => Pool::LEVELS, 'used' => cnp_product_usage()]);

case 'product_save':
    $pName = mb_substr(trim((string) ($in['name'] ?? '')), 0, 80);
    if ($pName === '') { fail('Δώσε όνομα'); }
    $pId   = (int) ($in['id'] ?? 0);
    $pPar  = (int) ($in['parent_id'] ?? 0);
    /* Δέντρο ΕΝΟΣ επιπέδου: υποκατηγορία δεν αποκτά δικά της παιδιά, και
       κανένα προϊόν δεν γίνεται γονέας του εαυτού του. */
    if ($pPar) {
        $par = Capsule::table('mod_cpm_products')->where('id', $pPar)->first();
        if (!$par) { fail('Άγνωστο προϊόν-γονέας'); }
        if ($par->parent_id) { fail('Η υποκατηγορία δεν μπορεί να έχει δικές της υποκατηγορίες'); }
        if ($pId && $pId === $pPar) { fail('Δεν γίνεται γονέας του εαυτού του'); }
        if ($pId && Capsule::table('mod_cpm_products')->where('parent_id', $pId)->exists()) {
            fail('Έχει ήδη υποκατηγορίες — δεν μπορεί να γίνει υποκατηγορία');
        }
    }
    $pRow = [
        'name'      => $pName,
        'color'     => preg_match('/^#[0-9a-fA-F]{6}$/', (string) ($in['color'] ?? '')) ? $in['color'] : '#0090dd',
        'parent_id' => $pPar ?: null,
        'route_dn'  => preg_match('/^\d{2,6}$/', (string) ($in['route_dn'] ?? '')) ? $in['route_dn'] : null,
        'active'    => empty($in['active']) ? 0 : 1,
    ];
    if ($pId) {
        Capsule::table('mod_cpm_products')->where('id', $pId)->update($pRow);
    } else {
        $pRow['sort'] = (int) Capsule::table('mod_cpm_products')->max('sort') + 10;
        $pRow['created_at'] = date('Y-m-d H:i:s');
        $pId = (int) Capsule::table('mod_cpm_products')->insertGetId($pRow);
    }
    Catalog::mirrorToArea($pId);
    out(['ok' => true, 'id' => $pId]);

case 'product_del':
    $pId = (int) ($in['id'] ?? 0);
    if (!$pId) { fail('Λείπει το προϊόν'); }
    if (Capsule::table('mod_cpm_products')->where('parent_id', $pId)->exists()) {
        fail('Έχει υποκατηγορίες — σβήσε πρώτα αυτές');
    }
    /* Δεν σβήνουμε ό,τι κουβαλά ιστορικό: γίνεται ΑΝΕΝΕΡΓΟ. Η διαγραφή θα
       άφηνε εργασίες και δεξιότητες να δείχνουν στο πουθενά. */
    $pUse = cnp_product_usage()[$pId] ?? 0;
    if ($pUse) {
        Capsule::table('mod_cpm_products')->where('id', $pId)->update(['active' => 0]);
        out(['ok' => true, 'deactivated' => true, 'used' => $pUse]);
    }
    $pAid = (int) Capsule::table('mod_cpm_products')->where('id', $pId)->value('area_id');
    Capsule::table('mod_cpm_products')->where('id', $pId)->delete();
    if ($pAid) {
        Capsule::table('mod_cpm_ticket_cats')->where('id', $pAid)->delete();
        Capsule::table('mod_cpm_ticket_class')->where('area_id', $pAid)->update(['area_id' => null]);
    }
    out(['ok' => true, 'deleted' => true]);

case 'products_reorder':
    foreach ((array) ($in['ids'] ?? []) as $i => $pid) {
        Capsule::table('mod_cpm_products')->where('id', (int) $pid)->update(['sort' => ($i + 1) * 10]);
    }
    out(['ok' => true]);

case 'roles':
    /* ΡΟΛΟΙ & ΕΙΔΙΚΟΤΗΤΕΣ — η κάρτα κάθε χειριστή και ο χάρτης «ποιος ξέρει τι».
       Επιστρέφει ΟΛΟΥΣ τους ενεργούς χειριστές, όχι μόνο όσους έχουν ρυθμιστεί:
       αλλιώς ο καινούργιος δεν φαίνεται πουθενά και δεν μπαίνει ποτέ. */
    /* ΔΕΝΤΡΟ, όχι επίπεδη λίστα: τα προϊόντα έχουν υποκατηγορίες και ο χάρτης
       πρέπει να μπορεί να πει «ξέρει PharmacyOne» ή «ξέρει μόνο τη
       συνταγογράφηση του». */
    $plProds = Catalog::tree(true);
    $plTeam = [];
    foreach (Capsule::table('mod_cpm_team_members as m')
                ->join('mod_cpm_teams as t', 't.id', '=', 'm.team_id')
                ->get(['m.admin_id', 'm.is_leader', 'm.role_title', 't.name']) as $r) {
        $plTeam[(int) $r->admin_id][] = ['team' => (string) $r->name,
            'leader' => (int) $r->is_leader, 'role' => (string) $r->role_title];
    }
    $plRows = [];
    foreach (Db::admins() as $a) {
        $aid = (int) $a->id;
        $plRows[] = Pool::card($aid) + [
            'name'   => Db::adminName($aid),
            'teams'  => $plTeam[$aid] ?? [],
            'skills' => Pool::skills($aid),
        ];
    }
    out(['ok' => true, 'rows' => $plRows, 'products' => $plProds,
         'modes' => Pool::MODES, 'levels' => Pool::LEVELS]);

case 'roles_coverage':
    /* Τα ΚΕΝΑ του χάρτη. Δεν είναι για τον μηχανισμό — είναι για τον ιδιοκτήτη:
       «αυτό το προϊόν το ξέρει ΕΝΑΣ· αν λείψει, δεν το παίρνει κανείς». */
    $plCov = Pool::coverage();
    foreach ($plCov as &$plC) {
        foreach (['main', 'can', 'learn'] as $plK) {
            $plC[$plK] = array_map(function ($id) { return ['id' => $id, 'name' => Db::adminName($id)]; },
                $plC[$plK]);
        }
    }
    unset($plC);
    out(['ok' => true, 'rows' => $plCov]);

case 'role_save':
    $plAid = (int) ($in['admin_id'] ?? 0);
    if (!$plAid) { out(['error' => 'Λείπει ο χειριστής']); }
    out(['ok' => true, 'card' => Pool::saveCard($plAid, $in, $adminId)]);

case 'skill_save':
    $plAid = (int) ($in['admin_id'] ?? 0);
    $plPid = (int) ($in['product_id'] ?? 0);
    if (!$plAid || !$plPid) { out(['error' => 'Λείπει χειριστής ή προϊόν']); }
    out(['ok' => true, 'level' => Pool::setSkill($plAid, $plPid, (string) ($in['level'] ?? ''), $adminId)]);

case 'tasks_label':
    /* Συμπληρώνει την ΕΙΔΙΚΟΤΗΤΑ όπου προκύπτει χωρίς αμφιβολία (ticket → έργο →
       πελάτης με ένα μόνο προϊόν). Πρώτα δοκιμή, μετά εγγραφή: λάθος ετικέτα
       στέλνει τη δουλειά σε λάθος άνθρωπο, που είναι χειρότερο από το κενό. */
    out(['ok' => true] + Catalog::labelTasks(empty($in['apply'])));

case 'pool_today':
    /* Η ΚΑΘΗΜΕΡΙΝΗ ΕΙΚΟΝΑ. Καθρέφτης: τρέχει όλο το μυαλό της δεξαμενής και
       δείχνει τι ΘΑ έδινε σε ποιον — χωρίς να αναθέτει τίποτα. Έτσι φαίνεται
       αν ο χάρτης λέει αλήθεια, πριν αφεθεί ο μηχανισμός να μοιράζει μόνος. */
    out(['ok' => true] + Pool::today(
        $in['date'] ?? $_GET['date'] ?? null,
        $in['at'] ?? $_GET['at'] ?? null));

case 'attention':
    /* «Τι να προσέξω» — επόπτης και coach μαζί, ανά ρόλο.
       ΟΧΙ «watch»: το όνομα το κρατά ήδη ο μηχανισμός παρακολούθησης εργασίας
       (watchers), και η δεύτερη δήλωση δεν έφτανε ποτέ — η ενέργεια απαντούσε
       «task» και έμοιαζε με σφάλμα δικαιωμάτων. Προσωπική οθόνη:
       ο καθένας βλέπει ΤΑ ΔΙΚΑ ΤΟΥ, και επιπλέον την ομάδα του αν είναι
       επικεφαλής ή τις αναθέσεις αν είναι project manager. Δεν υπάρχει
       παράμετρος «δείξε μου κάποιον άλλον» — ο ρόλος κρίνεται στον server. */
    out(Watch::forAdmin($adminId, $FULL));

default:
    fail('unknown action', 404);
}
